from math import sqrt

def most_correlated_columns(data):
    if not data or len(data) < 2:
        raise ValueError("at least two columns are required")

    # Validate that every value is numeric
    for col in data.values():
        for x in col:
            if not isinstance(x, (int, float)):
                raise TypeError(f"non-numeric value: {x!r}")

    columns = list(data.keys())

    lengths = {len(col) for col in data.values()}
    if len(lengths) != 1:
        raise ValueError("all columns must have equal length")

    n = lengths.pop()
    if n == 0:
        raise ValueError("no data")
    if n < 2:
        raise ValueError("at least two data points are required")

    # Precompute centered values and sum of squared deviations for each column
    centered = {}
    ss = {}
    for name in columns:
        col = data[name]
        mean = sum(col) / n
        cen = [x - mean for x in col]
        centered[name] = cen
        ss[name] = sum(x * x for x in cen)

    best_pair = None
    best_abs = -1.0

    # Compare every distinct pair, preserving dict order in the tuple
    for i in range(len(columns)):
        name_i = columns[i]
        if ss[name_i] == 0:
            continue
        cen_i = centered[name_i]
        for j in range(i + 1, len(columns)):
            name_j = columns[j]
            if ss[name_j] == 0:
                continue

            num = sum(a * b for a, b in zip(cen_i, centered[name_j]))
            den = sqrt(ss[name_i] * ss[name_j])
            if den == 0:
                continue

            r = num / den
            # Clamp tiny floating-point overshoot
            if r > 1.0:
                r = 1.0
            elif r < -1.0:
                r = -1.0

            abs_r = abs(r)
            if abs_r > best_abs:
                best_abs = abs_r
                best_pair = (name_i, name_j)

    if best_pair is None:
        raise ValueError("no correlation could be computed")

    return best_pair
