import re
import math
from collections import Counter

def _clean(text: str) -> str:
    # Lowercase, then replace every run of non-word characters with one space.
    # Python's \w includes letters, digits, and underscores.
    return re.sub(r'\W+', ' ', text.lower())

def _lcs_length(a: str, b: str) -> int:
    # Dynamic programming LCS, using O(min(len(a), len(b))) memory.
    if len(a) > len(b):
        a, b = b, a

    prev = [0] * (len(a) + 1)
    for j in range(1, len(b) + 1):
        curr = [0] * (len(a) + 1)
        ch_b = b[j - 1]
        for i in range(1, len(a) + 1):
            if a[i - 1] == ch_b:
                curr[i] = prev[i - 1] + 1
            else:
                curr[i] = max(prev[i], curr[i - 1])
        prev = curr

    return prev[len(a)]

def text_similarity_scores(text1: str, text2: str) -> tuple[float, float]:
    c1 = _clean(text1)
    c2 = _clean(text2)

    words1 = Counter(c1.split())
    words2 = Counter(c2.split())

    # Cosine similarity of word-count vectors
    if not words1 or not words2:
        cosine = 0.0
    else:
        dot = sum(words1[w] * words2.get(w, 0) for w in words1)
        norm1 = math.sqrt(sum(v * v for v in words1.values()))
        norm2 = math.sqrt(sum(v * v for v in words2.values()))
        cosine = dot / (norm1 * norm2)

    # Ratio based on minimal insertions/deletions:
    # insertions + deletions = len1 + len2 - 2 * LCS
    total = len(c1) + len(c2)
    if total == 0:
        ratio = 1.0
    else:
        lcs = _lcs_length(c1, c2)
        ratio = (2.0 * lcs) / total

    return (cosine, ratio)
