def fit_linear_regression(features, values):
    """
    Fits ordinary least-squares linear regression with an intercept.

    Returns:
        {
            'coefficients': [coef_for_feature_1, coef_for_feature_2, ...],
            'intercept': float
        }
    """
    n = len(features)
    if n == 0:
        raise ValueError("features must contain at least one row")
    if len(values) != n:
        raise ValueError("features and values must have the same length")

    p = len(features[0])
    if any(len(row) != p for row in features):
        raise ValueError("all feature rows must have the same length")

    # Center features and target so the intercept can be computed separately.
    x_means = [sum(row[j] for row in features) / n for j in range(p)]
    y_mean = sum(values) / n

    Xc = [[row[j] - x_means[j] for j in range(p)] for row in features]
    yc = [v - y_mean for v in values]

    # Normal equations: (Xc^T Xc) beta = Xc^T yc
    A = [
        [sum(Xc[i][j] * Xc[i][k] for i in range(n)) for k in range(p)]
        for j in range(p)
    ]
    b = [sum(Xc[i][j] * yc[i] for i in range(n)) for j in range(p)]

    beta = _solve_linear_system(A, b)

    intercept = y_mean - sum(x_means[j] * beta[j] for j in range(p))

    return {
        "coefficients": [float(c) for c in beta],
        "intercept": float(intercept),
    }


def _solve_linear_system(A, b):
    """Solve A x = b using Gauss-Jordan elimination with partial pivoting."""
    n = len(b)
    if n == 0:
        return []

    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError(
                "singular system: features may be collinear or insufficient data"
            )

        M[col], M[pivot] = M[pivot], M[col]

        pivot_value = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pivot_value

        for r in range(n):
            if r != col:
                factor = M[r][col]
                if factor != 0.0:
                    for j in range(col, n + 1):
                        M[r][j] -= factor * M[col][j]

    return [M[i][n] for i in range(n)]
```

