def column_correlation_matrix(data, cols):
    n = len(cols)
    if n == 0:
        return []

    m = len(data)
    if m == 0:
        return [[float('nan')] * n for _ in range(n)]

    # Extract columns in the order given by cols
    columns = [[row[j] for row in data] for j in range(n)]

    # Center each column and compute its variance
    means = [sum(col) / m for col in columns]
    centered = [[x - mean for x in col] for col, mean in zip(columns, means)]
    variances = [sum(x * x for x in col) for col in centered]

    result = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == j:
                # Self-correlation is 1 if the column has non-zero variance
                result[i][j] = 1.0 if variances[i] > 0 else float('nan')
            else:
                denom = (variances[i] * variances[j]) ** 0.5
                if denom == 0.0:
                    result[i][j] = float('nan')  # undefined correlation
                else:
                    cov = sum(centered[i][k] * centered[j][k] for k in range(m))
                    result[i][j] = cov / denom

    return result
```

For zero-variance columns, Pearson correlation is undefined, so this implementation returns `float('nan')` for those entries.

