import csv
import io
import re

_NUMBER_RE = re.compile(r'^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$')


def _parse_value(value):
    if value is None or value == '':
        return None

    stripped = value.strip()
    if _NUMBER_RE.match(stripped):
        try:
            return int(stripped)
        except ValueError:
            pass
        try:
            return float(stripped)
        except (ValueError, OverflowError):
            pass

    return value


def merge_csv_texts(csv_texts):
    csv_texts = list(csv_texts)
    if not csv_texts:
        return []

    all_columns = []
    seen = set()
    parsed = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))

        try:
            header = next(reader)
        except StopIteration:
            parsed.append(([], []))
            continue

        for col in header:
            if col not in seen:
                seen.add(col)
                all_columns.append(col)

        rows = [row for row in reader if row]
        parsed.append((header, rows))

    result = []
    for header, rows in parsed:
        for row in rows:
            record = {col: None for col in all_columns}
            for col, value in zip(header, row):
                record[col] = _parse_value(value)
            result.append(record)

    return result
