import math

def letter_count_correlations(strings):
    if not strings:
        return None

    letters = sorted({ch for s in strings for ch in s})
    if not letters:
        return {}

    n = len(strings)
    counts = {ch: [0] * n for ch in letters}

    for i, s in enumerate(strings):
        for ch in s:
            counts[ch][i] += 1

    sums = {ch: sum(vec) for ch, vec in counts.items()}
    sum_sq = {ch: sum(v * v for v in vec) for ch, vec in counts.items()}

    result = {}

    for x in letters:
        result[x] = {}
        sx = sums[x]
        sxx = sum_sq[x]
        ax = n * sxx - sx * sx

        for y in letters:
            sy = sums[y]
            syy = sum_sq[y]
            ay = n * syy - sy * sy

            sxy = sum(counts[x][i] * counts[y][i] for i in range(n))

            numerator = n * sxy - sx * sy
            denominator = math.sqrt(ax * ay)

            result[x][y] = numerator / denominator

    return result
