from statistics import mean, pstdev

def _zscores(values):
    m = mean(values)
    s = pstdev(values)          # population standard deviation
    if s == 0:
        return [0.0 for _ in values]
    return [(v - m) / s for v in values]

def standardize_series(x, y, labels):
    return {
        label: [_zscores(xs), _zscores(ys)]
        for xs, ys, label in zip(x, y, labels)
    }
