import csv
import io
import math

def _is_numeric(value):
    try:
        num = float(value)
    except (TypeError, ValueError, OverflowError):
        return False
    return math.isfinite(num)

def normalize_numeric_columns(csv_text):
    rows = [row for row in csv.reader(io.StringIO(csv_text)) if row]
    if not rows:
        raise ValueError("CSV text has no header row")

    header = rows[0]
    columns = [[] for _ in header]

    for row in rows[1:]:
        if len(row) < len(header):
            row += [''] * (len(header) - len(row))
        elif len(row) > len(header):
            row = row[:len(header)]

        for i, value in enumerate(row):
            columns[i].append(value)

    numeric_cols = []
    for col in columns:
        if col and all(_is_numeric(v) for v in col):
            numeric_cols.append([float(v) for v in col])
        else:
            numeric_cols.append(None)

    if not any(col is not None for col in numeric_cols):
        raise ValueError("No numeric columns found")

    result = {}
    for name, original, nums in zip(header, columns, numeric_cols):
        if nums is None:
            result[name] = original
        else:
            lo = min(nums)
            hi = max(nums)
            if lo == hi:
                result[name] = [0.0] * len(nums)
            else:
                result[name] = [(x - lo) / (hi - lo) for x in nums]

    return result
