from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}

class _FirstTagTextParser(HTMLParser):
    def __init__(self, target_tag):
        super().__init__(convert_charrefs=True)  # decodes entities automatically
        self.target = target_tag.lower()
        self.depth = 0
        self.capturing = False
        self.found = False
        self.parts = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if not self.found:
            if tag == self.target:
                self.found = True
                if tag not in _VOID_TAGS:
                    self.capturing = True
                    self.depth = 1
            return

        if self.capturing and tag == self.target and tag not in _VOID_TAGS:
            self.depth += 1

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        if not self.found and tag == self.target:
            # Self-closing tag: an element with no text content.
            self.found = True

    def handle_endtag(self, tag):
        tag = tag.lower()
        if self.capturing and tag == self.target:
            self.depth -= 1
            if self.depth == 0:
                self.capturing = False

    def handle_data(self, data):
        if self.capturing:
            self.parts.append(data)


def first_tag_text(html, tag):
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    text = "".join(parser.parts)
    return text if text else None
