import re
from datetime import date

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")

def _parse_iso_date(value, label="date"):
    if not isinstance(value, str) or _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{label} must be a valid YYYY-MM-DD date: {value!r}")

    year, month, day = map(int, value.split("-"))
    try:
        return date(year, month, day)
    except ValueError as exc:
        raise ValueError(f"{label} must be a valid YYYY-MM-DD date: {value!r}") from exc


def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    start = _parse_iso_date(start_date, "start_date")
    end = _parse_iso_date(end_date, "end_date")

    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column not found: {column_name!r}")

    if column_name not in header:
        raise ValueError(f"Column not found: {column_name!r}")

    col_idx = header.index(column_name)

    result = []
    for row in reader:
        if len(row) <= col_idx:
            continue

        try:
            row_date = _parse_iso_date(row[col_idx], "row date")
        except ValueError:
            continue

        if start <= row_date <= end:
            result.append(row)

    return result
