import csv
import io
import math
from typing import List


def _parse_float(value, context):
    if value is None or value.strip() == "":
        raise ValueError(f"Missing value {context}")
    try:
        num = float(value)
    except (TypeError, ValueError):
        raise ValueError(f"Non-numeric value {value!r} {context}")
    if not math.isfinite(num):
        raise ValueError(f"Non-finite value {value!r} {context}")
    return num


def _read_csv(csv_text: str):
    if not isinstance(csv_text, str):
        raise ValueError("CSV input must be a string")
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        raise ValueError("CSV is empty")
    header = [h.strip() for h in rows[0]]
    if not any(header):
        raise ValueError("CSV header is empty")
    return header, rows[1:]


def _solve_linear_system(A, b):
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if M[pivot][col] == 0.0:
            raise ValueError("Singular matrix while fitting linear regression")
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_val = M[col][col]
        for r in range(col + 1, n):
            factor = M[r][col] / pivot_val
            if factor != 0.0:
                for c in range(col, n + 1):
                    M[r][c] -= factor * M[col][c]

    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n]
        for j in range(i + 1, n):
            s -= M[i][j] * x[j]
        if M[i][i] == 0.0:
            raise ValueError("Singular matrix while fitting linear regression")
        x[i] = s / M[i][i]

    return x


def predict_linear_regression(train_csv: str, test_csv: str, target: str) -> List[float]:
    target = target.strip()

    train_header, train_rows = _read_csv(train_csv)
    if target not in train_header:
        raise ValueError(f"Target column {target!r} not found in training CSV")

    target_idx = train_header.index(target)
    feature_names = [h for h in train_header if h != target]

    if not train_rows:
        raise ValueError("Training CSV has no data rows")

    X_train = []
    y_train = []

    for row_num, row in enumerate(train_rows, start=2):
        if len(row) < len(train_header):
            raise ValueError(f"Missing value in training row {row_num}")

        features = []
        y_val = None
        for idx, name in enumerate(train_header):
            if idx == target_idx:
                y_val = _parse_float(row[idx], f"in training row {row_num}, column {name!r}")
            else:
                features.append(_parse_float(row[idx], f"in training row {row_num}, column {name!r}"))

        X_train.append(features)
        y_train.append(y_val)

    test_header, test_rows = _read_csv(test_csv)

    feature_indices = []
    for name in feature_names:
        if name not in test_header:
            raise ValueError(f"Feature column {name!r} missing in test CSV")
        feature_indices.append(test_header.index(name))

    X_test = []
    for row_num, row in enumerate(test_rows, start=2):
        features = []
        for idx, name in zip(feature_indices, feature_names):
            if idx >= len(row):
                raise ValueError(f"Missing value in test row {row_num}, column {name!r}")
            features.append(_parse_float(row[idx], f"in test row {row_num}, column {name!r}"))
        X_test.append(features)

    n = len(X_train)
    p = len(feature_names)
    m = p + 1  # +1 for intercept

    # Normal equations: (X^T X) beta = X^T y
    A = [[0.0] * m for _ in range(m)]
    b = [0.0] * m

    for i in range(n):
        row = [1.0] + X_train[i]
        yi = y_train[i]
        for j in range(m):
            b[j] += row[j] * yi
            for k in range(m):
                A[j][k] += row[j] * row[k]

    beta = _solve_linear_system(A, b)

    predictions = []
    for features in X_test:
        pred = beta[0] + sum(beta[j + 1] * features[j] for j in range(p))
        predictions.append(float(pred))

    return predictions
