import csv
from io import StringIO

def normalize_csv_columns(csv_text):
    """Min-max normalize each numeric column of a CSV string to [0, 1]."""
    rows = list(csv.reader(StringIO(csv_text)))
    if not rows:
        return {}

    header = [cell.strip() for cell in rows[0]]
    columns = {name: [] for name in header}

    for row in rows[1:]:
        if not row or all(cell.strip() == "" for cell in row):
            continue
        for name, value in zip(header, row):
            columns[name].append(float(value.strip()))

    normalized = {}
    for name, values in columns.items():
        if not values:
            normalized[name] = []
            continue

        lo, hi = min(values), max(values)
        if hi == lo:
            normalized[name] = [0.0] * len(values)
        else:
            normalized[name] = [(v - lo) / (hi - lo) for v in values]

    return normalized

def remove_zscore_outliers(rows, column, threshold):
    if not rows:
        return [], []

    values = [row[column] for row in rows]
    n = len(values)

    mean = sum(values) / n
    std = (sum((v - mean) ** 2 for v in values) / n) ** 0.5

    kept = []
    outliers = []

    for i, row in enumerate(rows):
        z = (row[column] - mean) / std if std != 0 else 0.0

        if abs(z) > threshold:
            outliers.append(i)
        else:
            kept.append(row)

    return kept, sorted(outliers)

def normalize_with_row_averages(data):
    if not data:
        return []

    columns = list(zip(*data))
    mins = [min(col) for col in columns]
    maxs = [max(col) for col in columns]

    result = []
    for row in data:
        scaled = []
        for i, value in enumerate(row):
            col_range = maxs[i] - mins[i]
            if col_range == 0:
                scaled.append(0.0)
            else:
                scaled.append((value - mins[i]) / col_range)

        row_avg = sum(scaled) / len(scaled) if scaled else 0.0
        result.append(scaled + [row_avg])

    return result

