def standardize_columns(data):
    result = {}

    for col, values in data.items():
        present = [v for v in values if v is not None]

        if not present:
            raise ValueError(f"Column {col!r} has no non-None values")

        mean = sum(present) / len(present)

        filled = [mean if v is None else v for v in values]

        variance = sum((v - mean) ** 2 for v in filled) / len(filled)
        std = variance ** 0.5

        if std == 0:
            result[col] = [0.0 for _ in filled]
        else:
            result[col] = [(v - mean) / std for v in filled]

    return result

def roc_points_and_auc(labels, scores):
    if len(labels) != len(scores):
        raise ValueError("labels and scores must have the same length")

    n = len(labels)
    pos_total = sum(1 for label in labels if label == 1)
    neg_total = n - pos_total

    if pos_total == 0 or neg_total == 0:
        raise ValueError("labels must contain both classes")

    # Group labels by score: score -> [positives, negatives]
    groups = {}
    for label, score in zip(labels, scores):
        if score not in groups:
            groups[score] = [0, 0]
        if label == 1:
            groups[score][0] += 1
        else:
            groups[score][1] += 1

    points = [(0.0, 0.0)]
    tp = 0
    fp = 0

    # Thresholds from highest score to lowest
    for score in sorted(groups, reverse=True):
        p, n = groups[score]
        tp += p
        fp += n
        points.append((fp / neg_total, tp / pos_total))

    # Trapezoidal area under the ROC curve
    area = 0.0
    for i in range(len(points) - 1):
        x1, y1 = points[i]
        x2, y2 = points[i + 1]
        area += (x2 - x1) * (y1 + y2) / 2.0

    return points, area

