        if tag == "table":
            is_target = (
                not self.found_target
                and self._class_attr(attrs) == "data-table"
            )
            if is_target:
                self.found_target = True
            self.table_stack.append(is_target)

        elif tag == "tr" and self._in_target_table():
            if self.current_cell is not None:
                self._close_cell()
            if self.current_row is not None:
                self.rows.append(self.current_row)
            self.current_row = []

        elif tag == "td" and self._in_target_table() and self.current_row is not None:
            if self.current_cell is not None:
                self._close_cell()
            self.current_cell = []

    def handle_endtag(self, tag):
