from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr"
}

class _Node:
    __slots__ = ("tag", "attrs", "children")

    def __init__(self, tag, attrs=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []

    def add_text(self, text):
        if text:
            self.children.append(text)

    def add_child(self, node):
        self.children.append(node)

    def get_text(self):
        parts = []

        def walk(node):
            for child in node.children:
                if isinstance(child, str):
                    parts.append(child)
                else:
                    walk(child)

        walk(self)
        return "".join(parts).strip()

    def find_first(self, pred):
        for child in self.children:
            if isinstance(child, _Node):
                if pred(child):
                    return child
                found = child.find_first(pred)
                if found is not None:
                    return found
        return None


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node("#root")
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].add_child(node)
        if tag not in _VOID_TAGS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        self.stack[-1].add_child(_Node(tag, dict(attrs)))

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                break

    def handle_data(self, data):
        self.stack[-1].add_text(data)


def _has_class(node, class_name):
    classes = node.attrs.get("class") or ""
    return class_name in classes.split()


def extract_article_info(html):
    parser = _TreeBuilder()
    parser.feed(html)
    parser.close()

    containers = []

    def collect(node):
        for child in node.children:
            if isinstance(child, _Node):
                if child.tag == "div" and _has_class(child, "container"):
                    containers.append(child)
                collect(child)

    collect(parser.root)

    result = []
    for container in containers:
        h1 = container.find_first(lambda n: n.tag == "h1")
        title = h1.get_text() if h1 is not None else "No Title"

        date_span = container.find_first(
            lambda n: n.tag == "span" and _has_class(n, "date")
        )
        date = date_span.get_text() if date_span is not None else "No Date"

        author_span = container.find_first(
            lambda n: n.tag == "span" and _has_class(n, "author")
        )
        author = author_span.get_text() if author_span is not None else "No Author"

        result.append((title, date, author))

    return result
