def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    """Fit ordinary least-squares linear regression with an intercept
    and return the R^2 score on the test data.
    """
    if len(train_X) == 0:
        raise ValueError("training set is empty")
    if len(train_X) != len(train_y):
        raise ValueError("train_X and train_y must have the same length")
    if len(test_X) != len(test_y):
        raise ValueError("test_X and test_y must have the same length")
    if len(test_X) == 0:
        raise ValueError("test set is empty")

    n = len(train_X)
    p = len(train_X[0])

    if any(len(row) != p for row in train_X):
        raise ValueError("all training rows must have the same number of features")
    if any(len(row) != p for row in test_X):
        raise ValueError("test rows must have the same number of features as training rows")

    X = [[float(v) for v in row] for row in train_X]
    y = [float(v) for v in train_y]
    X_test = [[float(v) for v in row] for row in test_X]
    y_test = [float(v) for v in test_y]

    def solve_linear_system(A, b):
        """Solve A x = b using Gaussian elimination with partial pivoting."""
        m = len(A)
        M = [A[i][:] + [b[i]] for i in range(m)]

        for col in range(m):
            pivot = max(range(col, m), key=lambda r: abs(M[r][col]))
            if abs(M[pivot][col]) < 1e-12:
                raise ValueError("singular matrix in least-squares fit")
            if pivot != col:
                M[col], M[pivot] = M[pivot], M[col]

            pivot_val = M[col][col]
            for r in range(col + 1, m):
                factor = M[r][col] / pivot_val
                if factor != 0.0:
                    for c in range(col, m + 1):
                        M[r][c] -= factor * M[col][c]

        x = [0.0] * m
        for i in range(m - 1, -1, -1):
            s = M[i][m]
            for j in range(i + 1, m):
                s -= M[i][j] * x[j]
            x[i] = s / M[i][i]
        return x

    if p == 0:
        intercept = sum(y) / n
        predictions = [intercept] * len(X_test)
    else:
        x_mean = [sum(row[j] for row in X) / n for j in range(p)]
        y_mean = sum(y) / n

        # Normal equations on centered data: (Xc^T Xc) beta = Xc^T yc
        A = [[0.0] * p for _ in range(p)]
        b = [0.0] * p

        for row, yi in zip(X, y):
            xc = [row[j] - x_mean[j] for j in range(p)]
            yc = yi - y_mean
            for i in range(p):
                b[i] += xc[i] * yc
                for j in range(p):
                    A[i][j] += xc[i] * xc[j]

        beta = solve_linear_system(A, b)
        intercept = y_mean - sum(x_mean[j] * beta[j] for j in range(p))

        predictions = []
        for row in X_test:
            pred = intercept + sum(row[j] * beta[j] for j in range(p))
            predictions.append(pred)

    ss_res = sum((yt - pred) ** 2 for yt, pred in zip(y_test, predictions))
    y_test_mean = sum(y_test) / len(y_test)
    ss_tot = sum((yt - y_test_mean) ** 2 for yt in y_test)

    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0

    return float(1.0 - ss_res / ss_tot)
