def merge_and_standardize(rows1, rows2):
    # Collect feature columns, preserving first-seen order.
    cols1 = []
    for row in rows1:
        for key in row:
            if key != 'id' and key not in cols1:
                cols1.append(key)

    cols2 = []
    for row in rows2:
        for key in row:
            if key != 'id' and key not in cols2:
                cols2.append(key)

    by_id1 = {row['id']: row for row in rows1}
    by_id2 = {row['id']: row for row in rows2}
    all_ids = sorted(set(by_id1) | set(by_id2))

    # Standardize each first-table column using population std, ignoring None.
    standardized = {}  # col -> {id: standardized_value}
    for col in cols1:
        values = [row.get(col) for row in rows1 if row.get(col) is not None]

        if values:
            mean = sum(values) / len(values)
            if all(x == values[0] for x in values):
                std = 0.0
            else:
                variance = sum((x - mean) ** 2 for x in values) / len(values)
                std = variance ** 0.5
        else:
            mean = 0.0
            std = 0.0

        col_values = {}
        for row in rows1:
            x = row.get(col)
            if x is None:
                col_values[row['id']] = None
            elif std == 0.0:
                col_values[row['id']] = 0.0
            else:
                col_values[row['id']] = (x - mean) / std

        standardized[col] = col_values

    # Outer join on id, sorted by id.
    result = []
    for id_ in all_ids:
        merged = {'id': id_}

        row1 = by_id1.get(id_)
        for col in cols1:
            merged[col] = standardized[col].get(id_) if row1 is not None else None

        row2 = by_id2.get(id_)
        for col in cols2:
            merged[col] = row2.get(col) if row2 is not None else None

        result.append(merged)

