import math

def standardize_columns(rows):
    if not rows:
        raise ValueError("rows is empty")

    n = len(rows)
    ncols = len(rows[0])

    means = [0.0] * ncols
    for row in rows:
        for j, value in enumerate(row):
            means[j] += value
    means = [m / n for m in means]

    variances = [0.0] * ncols
    for row in rows:
        for j, value in enumerate(row):
            diff = value - means[j]
            variances[j] += diff * diff

    stds = [math.sqrt(v / n) for v in variances]

    # Detect constant columns explicitly, so they become all zeros
    # even if floating-point arithmetic would give a tiny nonzero std.
    constant = [all(row[j] == rows[0][j] for row in rows) for j in range(ncols)]

    return [
        [
            0.0 if (constant[j] or stds[j] == 0.0) else (value - means[j]) / stds[j]
            for j, value in enumerate(row)
        ]
        for row in rows
    ]
