def seasonal_decomposition(values, period, model):
    n = len(values)

    if period <= 0:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    trend = [None] * n
    half = period // 2

    # Centered moving average trend
    if period % 2 == 1:
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        # For even periods, use a 2 x period moving average to center it
        for i in range(half, n - half):
            ma1 = sum(values[i - half:i + half]) / period
            ma2 = sum(values[i - half + 1:i + half + 1]) / period
            trend[i] = (ma1 + ma2) / 2

    # Detrended values by seasonal phase
    detrended_by_phase = [[] for _ in range(period)]
    for i, t in enumerate(trend):
        if t is None:
            continue
        if model == "additive":
            d = values[i] - t
        else:
            d = values[i] / t
        detrended_by_phase[i % period].append(d)

    # Raw seasonal indices
    raw_seasonal = [sum(group) / len(group) for group in detrended_by_phase]

    # Normalize seasonal indices
    if model == "additive":
        mean_raw = sum(raw_seasonal) / period
        seasonal_index = [r - mean_raw for r in raw_seasonal]
    else:
        mean_raw = sum(raw_seasonal) / period
        if mean_raw == 0:
            raise ValueError("cannot normalize multiplicative seasonal indices to mean 1")
        seasonal_index = [r / mean_raw for r in raw_seasonal]

    seasonal = [seasonal_index[i % period] for i in range(n)]

    # Residuals
    residual = [None] * n
    for i in range(n):
        if trend[i] is None:
            continue
        if model == "additive":
            residual[i] = values[i] - trend[i] - seasonal[i]
        else:
            residual[i] = values[i] / (trend[i] * seasonal[i])

    return {"trend": trend, "seasonal": seasonal, "residual": residual}
