def scale_table_columns(data):
    columns = list(data.keys())
    if not columns:
        return {}

    n = len(data[columns[0]])

    # Keep only rows with no None in any column
    valid_indices = [
        i for i in range(n)
        if all(data[col][i] is not None for col in columns)
    ]

    result = {}
    for col in columns:
        values = [data[col][i] for i in valid_indices]

        if not values:
            result[col] = []
            continue

        lo = min(values)
        hi = max(values)

        if lo == hi:
            result[col] = [0.0 for _ in values]
        else:
            result[col] = [(v - lo) / (hi - lo) for v in values]

    return result
```

