def column_linear_regression(rows, columns, target):
    if not rows:
        raise ValueError("rows is empty")
    if target not in columns:
        raise ValueError(f"target {target!r} is not one of the columns")

    target_idx = columns.index(target)
    pred_idx = [i for i in range(len(columns)) if i != target_idx]

    # Design matrix X with intercept column first
    X = []
    y = []
    for row in rows:
        if len(row) != len(columns):
            raise ValueError("each row must have the same length as columns")
        X.append([1.0] + [float(row[i]) for i in pred_idx])
        y.append(float(row[target_idx]))

    m = len(pred_idx) + 1
    A = [[0.0] * m for _ in range(m)]  # X^T X
    b = [0.0] * m                       # X^T y

    for xi, yi in zip(X, y):
        for r in range(m):
            b[r] += xi[r] * yi
            for c in range(m):
                A[r][c] += xi[r] * xi[c]

    def solve_linear_system(A, b):
        n = len(A)
        M = [A[i][:] + [b[i]] for i in range(n)]

        for col in range(n):
            pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
            if abs(M[pivot][col]) < 1e-12:
                raise ValueError("singular matrix: OLS coefficients are not unique")
            if pivot != col:
                M[col], M[pivot] = M[pivot], M[col]

            pivot_val = M[col][col]
            for j in range(col, n + 1):
                M[col][j] /= pivot_val

            for r in range(n):
                if r != col and M[r][col] != 0.0:
                    factor = M[r][col]
                    for j in range(col, n + 1):
                        M[r][j] -= factor * M[col][j]

        return [M[i][n] for i in range(n)]

    beta = solve_linear_system(A, b)

    intercept = beta[0]
    coefficients = beta[1:]
    return coefficients, intercept
