        mean = sum(nums) / n
        variance = sum((x - mean) ** 2 for x in nums) / n
        std = math.sqrt(variance)

        if std == 0.0:
            result[column] = [0.0] * n
        else:
            result[column] = [(x - mean) / std for x in nums]

    return result
