def weather_column_summary(column, data):
    column_index = {
        'temperature': 1,
        'humidity': 2,
        'wind speed': 3,
        'precipitation': 4,
    }[column.strip().lower().replace('_', ' ')]

    values = [row[column_index] for row in data]

    if not values:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * 10,
        }

    total = sum(values)
    mean = total / len(values)
    low = min(values)
    high = max(values)

    histogram = [0] * 10
    width = (high - low) / 10

    if width == 0:
        # All values equal the min/max; the last bin includes the max.
        histogram[9] = len(values)
    else:
        eps = 1e-12  # helps with floating-point bin-edge precision
        for value in values:
            bin_idx = int((value - low) / width + eps)
            if bin_idx == 10:
                bin_idx = 9
            if bin_idx < 0:
                bin_idx = 0
            elif bin_idx > 9:
                bin_idx = 9
            histogram[bin_idx] += 1

    return {
        'sum': total,
        'mean': mean,
        'min': low,
        'max': high,
        'histogram': histogram,
    }
