def salary_histogram(salaries_by_dept, dept):
    salaries = salaries_by_dept[dept]
    lo = min(salaries)
    hi = max(salaries)

    # If all salaries are equal, only the last bin can contain them.
    if lo == hi:
        return [0] * 9 + [len(salaries)], [float(lo)] * 11

    width = (hi - lo) / 10.0
    edges = [float(lo + i * width) for i in range(10)] + [float(hi)]

    counts = [0] * 10
    for s in salaries:
        if s >= hi:
            idx = 9          # last bin also includes the maximum
        else:
            idx = int((s - lo) / width)
            if idx < 0:
                idx = 0
            elif idx > 9:
                idx = 9
        counts[idx] += 1

    return counts, edges
