import math

def column_correlations(data):
    cols = list(data.keys())
    if not cols:
        return {}

    n = len(data[cols[0]])
    if n == 0:
        return {
            x: {y: (1.0 if x == y else float('nan')) for y in cols}
            for x in cols
        }

    means = {c: sum(data[c]) / n for c in cols}
    centered = {c: [v - means[c] for v in data[c]] for c in cols}
    ss = {c: sum(v * v for v in centered[c]) for c in cols}

    result = {}
    for x in cols:
        result[x] = {}
        for y in cols:
            if x == y:
                result[x][y] = 1.0
            else:
                sx = math.sqrt(ss[x])
                sy = math.sqrt(ss[y])
                if sx == 0.0 or sy == 0.0:
                    result[x][y] = float('nan')
                else:
                    num = sum(a * b for a, b in zip(centered[x], centered[y]))
                    result[x][y] = num / (sx * sy)

    return result
```

This computes Pearson correlation as:

\[
r_{xy} = \frac{\sum (x_i - \bar{x})(y_i - \bar{y})}
{\sqrt{\sum (x_i - \bar{x})^2 \sum (y_i - \bar{y})^2}}
\]

Diagonal entries are `1.0`. If a column is constant, its correlation with other columns is undefined, so those entries are returned as `nan`.

