def sort_csv_rows(csv_text, sort_by_column='title'):
    reader = csv.DictReader(StringIO(csv_text), restval='')
    headers = reader.fieldnames

    if headers is None:
        return []

    if sort_by_column not in headers:
        raise ValueError(f"Column {sort_by_column!r} not found in CSV header")

    rows = list(reader)
    if not rows:
        return []

    def is_int(value):
        try:
            int(value)
            return True
        except (ValueError, TypeError):
            return False

    def is_float(value):
        try:
            float(value)
            return True
        except (ValueError, TypeError):
            return False

    # Decide the type for each column based on all of its values.
    converters = {}
    for col in headers:
        values = [row.get(col, '') for row in rows]
        if all(is_int(v) for v in values):
            converters[col] = int
        elif all(is_float(v) for v in values):
            converters[col] = float
        else:
            converters[col] = str

    # Convert values in each row.
    for row in rows:
        for col in headers:
            conv = converters[col]
            if conv is int:
                row[col] = int(row[col])
            elif conv is float:
                row[col] = float(row[col])

    # Sort by the requested column. Numeric columns are already numbers,
    # so they sort numerically; other columns sort lexicographically.
    rows.sort(key=lambda row: row[sort_by_column])
    return rows
