import math

def describe_filled_columns(columns):
    result = {}

    for name, values in columns.items():
        present = [v for v in values if v is not None]
        if not present:
            raise ValueError(f"Column {name!r} has no present values")

        fill_value = sum(present) / len(present)
        filled = [fill_value if v is None else v for v in values]

        n = len(filled)
        mean = sum(filled) / n

        if n > 1:
            std = math.sqrt(sum((x - mean) ** 2 for x in filled) / (n - 1))
        else:
            std = float("nan")  # sample std is undefined for one value

        ordered = sorted(filled)

        def quantile(q):
            pos = (n - 1) * q
            lo = int(pos)
            hi = lo if pos == lo else lo + 1

            if lo == hi:
                return float(ordered[lo])

            frac = pos - lo
            return float(ordered[lo] * (1 - frac) + ordered[hi] * frac)

        result[name] = {
            "count": float(n),
            "mean": float(mean),
            "std": std,
            "min": float(ordered[0]),
            "25%": quantile(0.25),
            "50%": quantile(0.50),
            "75%": quantile(0.75),
            "max": float(ordered[-1]),
        }

    return result
