import cmath

def spectrum_magnitude_histogram(pairs):
    pairs = list(pairs)
    if not pairs:
        return ([], [])

    values = [v for _, v in pairs]
    n = len(values)

    # Unnormalized DFT, matching the example
    magnitudes = []
    for k in range(n):
        coeff = sum(
            x * cmath.exp(-2j * math.pi * k * t / n)
            for t, x in enumerate(values)
        )
        magnitudes.append(abs(coeff))

    lo = min(magnitudes)
    hi = max(magnitudes)
    counts = [0] * 10

    if hi == lo:
        # All magnitudes are equal; the last bin includes the right edge.
        counts[9] = len(magnitudes)
    else:
        width = (hi - lo) / 10.0
        for m in magnitudes:
            if m >= hi:
                idx = 9
            else:
                idx = math.floor((m - lo) / width)
                if idx < 0:
                    idx = 0
                elif idx > 9:
                    idx = 9
            counts[idx] += 1

    return (magnitudes, counts)
