    result = {}

    for col, values in data.items():
        cumulative = []
        running = 0
        for x in values:
            running += x
            cumulative.append(running)

        lo = min(cumulative)
        hi = max(cumulative)

        if hi == lo:
            result[col] = [0.0] * len(cumulative)
        else:
            result[col] = [float((x - lo) / (hi - lo)) for x in cumulative]

    return result
