import xml.etree.ElementTree as ET

def xml_to_dict(xml: str) -> dict:
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError(f"Malformed XML: {exc}") from exc

    def convert(elem):
        # Leaf element: no attributes and no children
        if not elem.attrib and len(elem) == 0:
            text = (elem.text or "").strip()
            return text if text else None

        result = {}

        # Attributes
        for attr, value in elem.attrib.items():
            result["@" + attr] = value

        # Child elements; repeated tags become lists
        for child in elem:
            child_value = convert(child)
            if child.tag in result:
                existing = result[child.tag]
                if isinstance(existing, list):
                    existing.append(child_value)
                else:
                    result[child.tag] = [existing, child_value]
            else:
                result[child.tag] = child_value

        # Non-whitespace text content
        text = (elem.text or "").strip()
        if text:
            result["#text"] = text

        return result

    return {root.tag: convert(root)}
