    if not all(isinstance(row, list) for row in data):
        raise ValueError("each row must be a list")

    n_cols = len(data[0])
    if n_cols == 0:
        raise ValueError("rows must contain at least one number")
    if any(len(row) != n_cols for row in data):
        raise ValueError("data must be rectangular")

    for row in data:
        for x in row:
            if not _is_number(x):
                raise ValueError("all entries must be numbers")

    # Convert to float for uniform arithmetic
    data = [[float(x) for x in row] for row in data]
    n_rows = len(data)

    averages = [sum(row) / n_cols for row in data]

    columns = [list(col) for col in zip(*data)]
    means = [sum(col) / n_rows for col in columns]
    centered = [[x - mean for x in col] for col in columns]
    ss = [sum(x * x for x in col) for col in centered]

    corr = [[0.0] * n_cols for _ in range(n_cols)]
    for i in range(n_cols):
        for j in range(n_cols):
            if i == j:
                corr[i][j] = 1.0
            else:
                denom = sqrt(ss[i] * ss[j])
                if denom == 0.0:
                    corr[i][j] = 0.0
                else:
                    cov = sum(centered[i][k] * centered[j][k] for k in range(n_rows))
                    corr[i][j] = cov / denom

    return averages, corr

