def summarize_stock_column(column, data):
    column_indices = {
        'Open': 1,
        'High': 2,
        'Low': 3,
        'Close': 4,
        'Volume': 5,
    }

    if column not in column_indices:
        raise ValueError(f"Invalid column: {column!r}. Expected one of {sorted(column_indices)}")

    idx = column_indices[column]
    values = []

    for row in data:
        try:
            row_length = len(row)
        except TypeError:
            raise ValueError("Each row must have exactly six entries")

        if row_length != 6:
            raise ValueError("Each row must have exactly six entries")

        value = row[idx]
        if value is not None:
            values.append(float(value))

    n = len(values)

    if n == 0:
        return {
            'count': 0,
            'mean': None,
            'std': None,
            'min': None,
            '25%': None,
            '50%': None,
            '75%': None,
            'max': None,
        }

    values.sort()
    mean = math.fsum(values) / n

    if n > 1:
        variance = math.fsum((x - mean) ** 2 for x in values) / (n - 1)
        std = math.sqrt(variance)
    else:
        std = None  # sample standard deviation is undefined for a single value

    def quantile(q):
        # Linear interpolation: position = q * (n - 1)
        pos = q * (n - 1)
        lo = math.floor(pos)
        hi = math.ceil(pos)

        if lo == hi:
            return float(values[lo])

        frac = pos - lo
        return float(values[lo] * (1 - frac) + values[hi] * frac)

    return {
        'count': n,
        'mean': float(mean),
        'std': std,
        'min': float(values[0]),
        '25%': quantile(0.25),
        '50%': quantile(0.50),
        '75%': quantile(0.75),
        'max': float(values[-1]),
    }
