import re

def tfidf_without_urls(texts):
    n = len(texts)
    if n == 0:
        return [], []

    docs = []
    for text in texts:
        text = text.lower()
        text = re.sub(r'https?://\S+', ' ', text)
        docs.append(re.findall(r'\w{2,}', text))

    vocab = sorted({word for doc in docs for word in doc})
    if not vocab:
        return [], []

    df = {word: 0 for word in vocab}
    for doc in docs:
        for word in set(doc):
            df[word] += 1

    idf = {word: math.log((1 + n) / (1 + df[word])) + 1 for word in vocab}

    rows = []
    for doc in docs:
        counts = {}
        for word in doc:
            counts[word] = counts.get(word, 0) + 1

        vec = [counts.get(word, 0) * idf[word] for word in vocab]
        norm = math.sqrt(sum(x * x for x in vec))
        if norm > 0:
            vec = [x / norm for x in vec]

        rows.append(vec)

    return rows, vocab
