import math
from numbers import Real

def _is_numeric_column(values):
    return len(values) > 0 and all(isinstance(v, Real) for v in values)

def _mean(values):
    return sum(values) / len(values)

def _variance(values):
    m = _mean(values)
    return sum((v - m) ** 2 for v in values)

def _pearson(xs, ys):
    mx = _mean(xs)
    my = _mean(ys)

    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    den_x = sum((x - mx) ** 2 for x in xs)
    den_y = sum((y - my) ** 2 for y in ys)

    if den_x == 0 or den_y == 0:
        return float("nan")

    return num / math.sqrt(den_x * den_y)

def correlation_without_column(data, column):
    numeric = {
        name: values
        for name, values in data.items()
        if name != column and _is_numeric_column(values)
    }

    if not numeric:
        return None

    names = list(numeric)
    result = {name: {} for name in names}

    for i, x in enumerate(names):
        for j in range(i, len(names)):
            y = names[j]

            if x == y:
                r = 1.0 if _variance(numeric[x]) > 0 else float("nan")
            else:
                r = _pearson(numeric[x], numeric[y])
                result[y][x] = r

            result[x][y] = r

    return result
