    den_y = sum((y - my) ** 2 for y in ys)

    if den_x == 0 or den_y == 0:
        return float("nan")

    return num / math.sqrt(den_x * den_y)

def correlation_without_column(data, column):
    numeric = {
        name: values
        for name, values in data.items()
        if name != column and _is_numeric_column(values)
    }

    if not numeric:
        return None

    names = list(numeric)
    result = {name: {} for name in names}

    for i, x in enumerate(names):
        for j in range(i, len(names)):
            y = names[j]

            if x == y:
                r = 1.0 if _variance(numeric[x]) > 0 else float("nan")
            else:
                r = _pearson(numeric[x], numeric[y])
                result[y][x] = r

            result[x][y] = r

    return result

