import re
from collections import Counter

def tfidf_scores_for_question_articles(titles, contents):
    picked = [
        body for title, body in zip(titles, contents)
        if "how" in title.lower() or "what" in title.lower()
    ]

    if not picked:
        return {}

    docs = [Counter(re.findall(r"\w{2,}", body.lower())) for body in picked]

    df = Counter()
    for doc in docs:
        df.update(doc.keys())

    n = len(picked)
    idf = {
        word: math.log((1 + n) / (1 + count)) + 1
        for word, count in df.items()
    }

    totals = {}
    for doc in docs:
        tfidf = {word: count * idf[word] for word, count in doc.items()}
        norm = math.sqrt(sum(score * score for score in tfidf.values()))

        if norm == 0:
            continue

        for word, score in tfidf.items():
            totals[word] = totals.get(word, 0.0) + score / norm

    return dict(sorted(totals.items()))
