def replace_and_standardize(data, features, mapping):
    # Validate that all requested feature columns exist
    for feature in features:
        if feature not in data:
            raise ValueError(f"Missing feature column: {feature}")

    # Apply replacements to all columns, preserving original column order
    result = {}
    for col, values in data.items():
        result[col] = [mapping.get(value, value) for value in values]

    # Standardize each feature column using population standard deviation
    for feature in features:
        values = result[feature]
        n = len(values)
        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = variance ** 0.5

        result[feature] = [(x - mean) / std for x in values]

    return result
