from fractions import Fraction

def _solve_linear(A, b):
    """Solve A x = b exactly using Gaussian elimination with Fractions."""
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if M[pivot][col] == 0:
            raise ValueError("singular matrix")
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_val = M[col][col]
        for r in range(col + 1, n):
            factor = M[r][col] / pivot_val
            if factor != 0:
                for c in range(col, n + 1):
                    M[r][c] -= factor * M[col][c]

    x = [Fraction(0) for _ in range(n)]
    for i in range(n - 1, -1, -1):
        s = M[i][n]
        for j in range(i + 1, n):
            s -= M[i][j] * x[j]
        x[i] = s / M[i][i]

    return x


def fit_linear_regression(rows):
    """
    Fit OLS multiple linear regression with an intercept.

    rows: list of [x1, x2, x3, x4, y]
    Returns: ([intercept, b1, b2, b3, b4], r_squared)
    """
    if not rows:
        raise ValueError("rows is empty")

    X = []
    y = []

    for row in rows:
        if not isinstance(row, (list, tuple)) or len(row) != 5:
            raise ValueError("each row must have exactly five values")

        try:
            vals = [Fraction(v) for v in row]
        except (ValueError, TypeError, OverflowError):
            raise ValueError("each row must contain exactly five numbers") from None

        X.append([Fraction(1)] + vals[:4])
        y.append(vals[4])

    n = len(X)
    p = 5

    # Normal equations: X^T X beta = X^T y
    XtX = [[Fraction(0) for _ in range(p)] for _ in range(p)]
    Xty = [Fraction(0) for _ in range(p)]

    for i in range(n):
        xi = X[i]
        yi = y[i]
        for r in range(p):
            Xty[r] += xi[r] * yi
            for c in range(p):
                XtX[r][c] += xi[r] * xi[c]

    beta = _solve_linear(XtX, Xty)

    y_mean = sum(y) / n
    ss_res = Fraction(0)
    ss_tot = Fraction(0)

    for i in range(n):
        pred = sum(beta[j] * X[i][j] for j in range(p))
        resid = y[i] - pred
        ss_res += resid * resid
        ss_tot += (y[i] - y_mean) ** 2

    if ss_tot == 0:
        r_squared = Fraction(1) if ss_res == 0 else Fraction(0)
    else:
        r_squared = Fraction(1) - ss_res / ss_tot

    return [float(b) for b in beta], float(r_squared)
