import math
from collections import Counter

def bracket_free_tfidf(texts):
    def strip_brackets(s):
        out = []
        stack = []
        for ch in s:
            if ch == '[':
                stack.append(len(out))
                out.append(ch)
            elif ch == ']':
                if stack:
                    del out[stack.pop():]   # remove the whole bracketed span
                else:
                    out.append(ch)
            else:
                out.append(ch)
        return ''.join(out)

    # Tokenize after removing bracketed text
    docs = [re.findall(r'\w{2,}', strip_brackets(t).lower()) for t in texts]

    n = len(texts)
    df = Counter()
    for tokens in docs:
        df.update(set(tokens))

    def idf(word):
        return math.log((1 + n) / (1 + df[word])) + 1

    result = []
    for tokens in docs:
        counts = Counter(tokens)
        if not counts:
            result.append({})
            continue

        scores = {word: counts[word] * idf(word) for word in sorted(counts)}
        norm = math.sqrt(sum(score * score for score in scores.values()))
        result.append({word: score / norm for word, score in scores.items()})

    return result
