def normalize_columns(data_dict, data_keys):
    """
    Min-max scale each requested column found in data_dict to [0, 1].
    """
    scaled = {}

    for key in data_keys:
        if key not in data_dict:
            continue

        column = data_dict[key]

        if len(column) == 0:
            scaled[key] = []
            continue

        low = min(column)
        high = max(column)

        if high == low:
            scaled[key] = [0.0] * len(column)
        else:
            scaled[key] = [float((value - low) / (high - low)) for value in column]

    if not scaled:
        raise ValueError("None of the requested columns were found in data_dict")

    return scaled
