def column_histogram(records, column_name):
    if not records or any(column_name not in row for row in records):
        raise ValueError(f"Column {column_name!r} does not exist in the table")

    values = [row[column_name] for row in records]

    # If the column is string-typed, replace values with their rank
    # among the sorted distinct strings.
    if all(isinstance(v, str) for v in values):
        distinct = sorted(set(values))
        rank = {v: i for i, v in enumerate(distinct)}
        values = [rank[v] for v in values]

    lo = min(values)
    hi = max(values)
    counts = [0] * 10

    # If all values are equal, they are all the maximum, so they go in the last bin.
    if lo == hi:
        counts[-1] = len(values)
        return counts

    # Exact integer arithmetic when possible.
    if all(isinstance(v, int) for v in values):
        span = hi - lo
        for v in values:
            idx = (v - lo) * 10 // span
            if idx < 0:
                idx = 0
            elif idx > 9:
                idx = 9
            counts[idx] += 1
    else:
        width = (hi - lo) / 10
        for v in values:
            idx = int((v - lo) / width)
            if idx < 0:
