def top_ngrams(text, n, top_k):
    if n <= 0 or top_k <= 0:
        return []

    # Lowercase and extract words as alphanumeric sequences.
    words = re.findall(r"[a-z0-9]+", text.lower())

    if len(words) < n:
        return []

    counts = {}
    first_seen = {}

    for i in range(len(words) - n + 1):
        ngram = tuple(words[i:i + n])
        if ngram not in first_seen:
            first_seen[ngram] = i
        counts[ngram] = counts.get(ngram, 0) + 1

    # Sort by count descending, then by first appearance.
    ordered = sorted(
        counts.items(),
        key=lambda item: (-item[1], first_seen[item[0]])
    )

    return [(" ".join(ngram), count) for ngram, count in ordered[:top_k]]
