def _solve_linear_system(A, b):
    """Solve A x = b. Returns a solution even if A is singular but consistent."""
    n = len(A)
    if n == 0:
        return []

    M = [A[i][:] + [b[i]] for i in range(n)]
    max_abs = max(abs(M[i][j]) for i in range(n) for j in range(n))
    tol = 1e-12 * max_abs if max_abs > 0 else 1e-12

    pivot_cols = []
    row = 0

    for col in range(n):
        if row >= n:
            break

        pivot = max(range(row, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) <= tol:
            continue

        if pivot != row:
            M[row], M[pivot] = M[pivot], M[row]

        pivot_value = M[row][col]
        for j in range(n + 1):
            M[row][j] /= pivot_value

        for r in range(n):
            if r != row:
                factor = M[r][col]
                if factor != 0.0:
                    for j in range(n + 1):
                        M[r][j] -= factor * M[row][j]

        pivot_cols.append(col)
        row += 1

    x = [0.0] * n
    for i, col in enumerate(pivot_cols):
        x[col] = M[i][n]
    return x


def fit_linear_regression(rows, targets):
    """
    Fit ordinary least-squares linear regression with an intercept.

    Returns (coefficients, intercept).
    """
    if not rows or len(rows) != len(targets):
        raise ValueError("rows must be non-empty and have the same length as targets")

    n = len(rows)
    p = len(rows[0])

    for row in rows:
        if len(row) != p:
            raise ValueError("all feature vectors must have the same length")

    if p == 0:
        return [], float(sum(targets) / n)

    x_means = [sum(row[j] for row in rows) / n for j in range(p)]
    y_mean = sum(targets) / n

    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for row, y in zip(rows, targets):
        y_centered = y - y_mean
        x_centered = [row[j] - x_means[j] for j in range(p)]

        for j in range(p):
            b[j] += x_centered[j] * y_centered
            for k in range(p):
                A[j][k] += x_centered[j] * x_centered[k]

    beta = _solve_linear_system(A, b)
    intercept = y_mean - sum(x_means[j] * beta[j] for j in range(p))

    return [float(v) for v in beta], float(intercept)
