import xml.etree.ElementTree as ET

def xml_to_dict(s: str) -> dict:
    if not s or not s.strip():
        raise ValueError("Input is empty or only whitespace")

    try:
        root = ET.fromstring(s.strip())
    except ET.ParseError as exc:
        raise ValueError("Invalid XML string") from exc

    def convert(elem):
        attrs = {f"@{k}": v for k, v in elem.attrib.items()}
        children = list(elem)

        child_map = {}
        for child in children:
            value = convert(child)
            if child.tag in child_map:
                existing = child_map[child.tag]
                if not isinstance(existing, list):
                    child_map[child.tag] = [existing]
                child_map[child.tag].append(value)
            else:
                child_map[child.tag] = value

        text_parts = []
        if elem.text is not None:
            text_parts.append(elem.text)
        for child in children:
            if child.tail is not None:
                text_parts.append(child.tail)
        text = "".join(text_parts)

        if not children and not attrs:
            return text if text else None

        result = {}
        result.update(attrs)
        result.update(child_map)
        if text:
            result["#text"] = text
        return result

    return {root.tag: convert(root)}
