def dbscan_cluster_labels(points):
    n = len(points)
    if n == 0:
        return []

    EPS = 3.0
    MIN_SAMPLES = 2
    EPS_SQ = EPS * EPS

    labels = [-1] * n
    visited = [False] * n
    next_cluster = 0

    def neighborhood(i):
        pi = points[i]
        result = []
        for j, pj in enumerate(points):
            dist_sq = 0.0
            for a, b in zip(pi, pj):
                diff = a - b
                dist_sq += diff * diff
            if dist_sq <= EPS_SQ:
                result.append(j)
        return result

    def expand_cluster(seed, seed_neighbors, cluster_id):
        labels[seed] = cluster_id
        to_process = set(seed_neighbors)

        while to_process:
            p = to_process.pop()

            if not visited[p]:
                visited[p] = True
                neigh = neighborhood(p)
                if len(neigh) >= MIN_SAMPLES:
                    to_process.update(neigh)

            if labels[p] == -1:
                labels[p] = cluster_id

    for i in range(n):
        if visited[i]:
            continue

        visited[i] = True
        neigh = neighborhood(i)

        if len(neigh) < MIN_SAMPLES:
            labels[i] = -1
        else:
            expand_cluster(i, neigh, next_cluster)
            next_cluster += 1

    return labels
