            for a, b in zip(pi, pj):
                diff = a - b
                dist_sq += diff * diff
            if dist_sq <= EPS_SQ:
                result.append(j)
        return result

    def expand_cluster(seed, seed_neighbors, cluster_id):
        labels[seed] = cluster_id
        to_process = set(seed_neighbors)

        while to_process:
            p = to_process.pop()

            if not visited[p]:
