import csv
from io import StringIO

def _is_int(s):
    try:
        int(s)
        return True
    except (ValueError, TypeError):
        return False

def _is_float(s):
    try:
        float(s)
        return True
    except (ValueError, TypeError):
        return False

def concat_csv_tables(csv_texts):
    texts = list(csv_texts)
    if not texts:
        raise ValueError("csv_texts must not be empty")

    header = None
    rows = []

    for text in texts:
        reader = csv.reader(StringIO(text))
        doc_rows = [row for row in reader if row]  # skip blank lines

        if not doc_rows:
            continue

        if header is None:
            header = doc_rows[0]

        for row in doc_rows[1:]:
            # Keep rows aligned with the header length
            if len(row) < len(header):
                row += [""] * (len(header) - len(row))
            elif len(row) > len(header):
                row = row[:len(header)]
            rows.append(row)

    if header is None:
        return []

    # Determine each column's type
    columns = list(zip(*rows)) if rows else [() for _ in header]
    converted_columns = []

    for col in columns:
        if all(_is_int(v) for v in col):
            converted_columns.append([int(v) for v in col])
        elif all(_is_float(v) for v in col):
            converted_columns.append([float(v) for v in col])
        else:
            converted_columns.append(list(col))

    return [
        {header[j]: converted_columns[j][i] for j in range(len(header))}
        for i in range(len(rows))
    ]
