def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = list(data.keys())
    n = None
    mapped = {}

    for col in columns:
        values = data[col]
        if n is None:
            n = len(values)
        elif len(values) != n:
            raise ValueError("all columns must have the same length")
        mapped[col] = [float(mapping.get(v, v)) for v in values]

    if n == 0:
        return {
            a: {b: 1.0 if a == b else 0.0 for b in columns}
            for a in columns
        }

    means = {col: sum(mapped[col]) / n for col in columns}
    deviations = {
        col: [x - means[col] for x in mapped[col]]
        for col in columns
    }
    sum_sq = {col: sum(d * d for d in deviations[col]) for col in columns}

    result = {a: {} for a in columns}

    for i, a in enumerate(columns):
        for b in columns[i:]:
            if a == b:
                corr = 1.0
            elif sum_sq[a] == 0 or sum_sq[b] == 0:
                corr = 0.0
            else:
                cov = sum(deviations[a][k] * deviations[b][k] for k in range(n))
                corr = cov / ((sum_sq[a] * sum_sq[b]) ** 0.5)

            result[a][b] = corr
            result[b][a] = corr

    return result
