def csv_mean_median(csv_text):
    if not csv_text:
        return (None, None)

    reader = csv.reader(io.StringIO(csv_text))
    try:
        next(reader)  # skip the header row
    except StopIteration:
        return (None, None)

    nums = []

    for row in reader:
        if not row:
            continue  # blank line

        value = row[0].strip()
        if not value:
            continue

        try:
            num = float(value)
        except (ValueError, TypeError, OverflowError):
            continue

        if not math.isfinite(num):
            continue  # ignore NaN/inf as non-numeric

        nums.append(num)

    if not nums:
        return (None, None)

    nums.sort()
    n = len(nums)

    mean = sum(nums) / n

    if n % 2 == 1:
        median = nums[n // 2]
    else:
        median = (nums[n // 2 - 1] + nums[n // 2]) / 2.0

    return (float(mean), float(median))
