def cluster_centroids(points, k):
    if not points or k <= 0:
        return []
    if k > len(points):
        raise ValueError("k cannot exceed the number of points")

    # Deterministic initialization: use the first k points as initial centroids
    centroids = [(float(x), float(y)) for x, y in points[:k]]

    while True:
        clusters = [[] for _ in range(k)]

        # Assign each point to the nearest centroid
        for x, y in points:
            dists = [(x - cx) ** 2 + (y - cy) ** 2 for cx, cy in centroids]
            idx = dists.index(min(dists))
            clusters[idx].append((float(x), float(y)))

        # Recompute centroids
        new_centroids = []
        for i, cluster in enumerate(clusters):
            if cluster:
                n = len(cluster)
                new_centroids.append((
                    sum(p[0] for p in cluster) / n,
                    sum(p[1] for p in cluster) / n
                ))
            else:
                # Keep the old centroid if a cluster becomes empty
                new_centroids.append(centroids[i])

        if new_centroids == centroids:
            break

        centroids = new_centroids

    return sorted(centroids)
