from datetime import date, timedelta
import calendar
import re

_WEEKDAY_CODES = {
    'MON': 0,
    'TUE': 1,
    'WED': 2,
    'THU': 3,
    'FRI': 4,
    'SAT': 5,
    'SUN': 6,
}

def _parse_start_date(start_date):
    if not isinstance(start_date, str):
        raise ValueError("start_date must be a string in YYYY-MM-DD format")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", start_date):
        raise ValueError("start_date must be in YYYY-MM-DD format")

    try:
        year, month, day = (int(part) for part in start_date.split("-"))
        return date(year, month, day)
    except ValueError as exc:
        raise ValueError(f"invalid start_date: {start_date!r}") from exc

def _parse_freq(freq):
    if not isinstance(freq, str):
        raise ValueError("freq must be a string")

    f = freq.strip().upper()

    if f == "MONTH-END":
        return ("month_end", None, None)
    if f == "QUARTER-END":
        return ("quarter_end", None, None)

    match = re.fullmatch(r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", f)
    if match:
        return ("nth_weekday", int(match.group(1)), _WEEKDAY_CODES[match.group(2)])

    raise ValueError(f"invalid freq: {freq!r}")

def _nth_weekday_of_month(year, month, weekday, n):
    first_weekday = date(year, month, 1).weekday()
    offset = (weekday - first_weekday) % 7
    return date(year, month, 1 + offset + (n - 1) * 7)

def _next_matching(d, kind, n, weekday):
    if kind == "month_end":
        last_day = calendar.monthrange(d.year, d.month)[1]
        return date(d.year, d.month, last_day)

    if kind == "quarter_end":
        quarter_end_month = ((d.month - 1) // 3) * 3 + 3
        last_day = calendar.monthrange(d.year, quarter_end_month)[1]
        return date(d.year, quarter_end_month, last_day)

    if kind == "nth_weekday":
        candidate = _nth_weekday_of_month(d.year, d.month, weekday, n)
        if candidate >= d:
            return candidate

        year, month = d.year, d.month + 1
        if month > 12:
            year, month = year + 1, 1
        return _nth_weekday_of_month(year, month, weekday, n)

    raise ValueError(f"unknown freq kind: {kind!r}")

def forecast_schedule(start_date, freq, sales):
    start = _parse_start_date(start_date)
    kind, n, weekday = _parse_freq(freq)

    result = []
    cursor = start

    for sale in sales:
        d = _next_matching(cursor, kind, n, weekday)
        result.append((d.isoformat(), sale))
        cursor = d + timedelta(days=1)

    return result
