def country_score_summary(records):
    if not records:
        raise ValueError("records must be a non-empty list")

    required = ("Name", "Country", "Score")
    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in required):
            raise ValueError("each record must be a dict with keys 'Name', 'Country', and 'Score'")

    seen_names = set()
    by_country = {}

    # Keep only the first record for each name
    for record in records:
        name = record["Name"]
        if name in seen_names:
            continue
        seen_names.add(name)

        country = record["Country"]
        score = float(record["Score"])
        by_country.setdefault(country, []).append(score)

    def quantile(sorted_vals, p):
        """Linear interpolation quantile at position (n - 1) * p."""
        n = len(sorted_vals)
        if n == 1:
            return sorted_vals[0]

        pos = (n - 1) * p
        lo = int(pos)
        hi = lo + 1 if pos > lo else lo

        if lo == hi:
            return sorted_vals[lo]

        frac = pos - lo
        return sorted_vals[lo] + (sorted_vals[hi] - sorted_vals[lo]) * frac

    summary = {}
    for country, scores in by_country.items():
        sorted_scores = sorted(scores)
        summary[country] = [
            float(sorted_scores[0]),
            quantile(sorted_scores, 0.25),
            quantile(sorted_scores, 0.5),
            quantile(sorted_scores, 0.75),
            float(sorted_scores[-1]),
        ]

    return summary
