from numbers import Real

def column_covariance(columns):
    if not columns:
        raise ValueError("table has no columns")

    # Validate that all values are numeric
    for name, col in columns.items():
        for value in col:
            if not isinstance(value, Real):
                raise TypeError(f"non-numeric value in column {name!r}: {value!r}")

    # Validate lengths and row count
    lengths = {name: len(col) for name, col in columns.items()}
    n = next(iter(lengths.values()))

    if any(length != n for length in lengths.values()):
        raise ValueError("all columns must have the same length")
    if n < 2:
        raise ValueError("table must have at least two rows")

    means = {name: sum(col) / n for name, col in columns.items()}

    result = {}
    for a, col_a in columns.items():
        result[a] = {}
        mean_a = means[a]
        for b, col_b in columns.items():
            mean_b = means[b]
            result[a][b] = sum(
                (x - mean_a) * (y - mean_b)
                for x, y in zip(col_a, col_b)
            ) / (n - 1)

    return result
