def cluster_point_indices(points, n_clusters):
    n = len(points)
    if n_clusters <= 0:
        return []
    if n_clusters > n:
        raise ValueError("n_clusters cannot be greater than the number of points")
    if n_clusters == n:
        return [[i] for i in range(n)]

    dim = len(points[0])

    def dist2(a, b):
        return sum((a[d] - b[d]) ** 2 for d in range(dim))

    # Deterministic farthest-first initialization
    centroids = [points[0][:]]
    while len(centroids) < n_clusters:
        best_idx = 0
        best_dist = -1.0
        for i, p in enumerate(points):
            d = min(dist2(p, c) for c in centroids)
            if d > best_dist:
                best_dist = d
                best_idx = i
        centroids.append(points[best_idx][:])

    assignments = [-1] * n
    max_iter = 1000

    for _ in range(max_iter):
        new_assignments = []
        counts = [0] * n_clusters

        # Assign each point to the nearest centroid.
        # Ties go to the least-filled cluster to avoid empty clusters.
        for p in points:
            dists = [dist2(p, c) for c in centroids]
            min_d = min(dists)
            candidates = [k for k, d in enumerate(dists) if d <= min_d + 1e-12]
            best_k = min(candidates, key=lambda k: counts[k])
            new_assignments.append(best_k)
            counts[best_k] += 1

        if new_assignments == assignments:
            break
        assignments = new_assignments

        # Update centroids to the mean of their assigned points
        for k in range(n_clusters):
            members = [points[i] for i in range(n) if assignments[i] == k]
            if members:
                centroids[k] = [
                    sum(m[d] for m in members) / len(members)
                    for d in range(dim)
                ]
            else:
                # Reinitialize an empty cluster to the farthest point
                farthest = max(
                    range(n),
                    key=lambda i: dist2(points[i], centroids[assignments[i]])
                )
                centroids[k] = points[farthest][:]

    clusters = [[] for _ in range(n_clusters)]
    for i, k in enumerate(assignments):
        clusters[k].append(i)

    clusters = [c for c in clusters if c]
    clusters.sort(key=lambda c: c[0])
    return clusters
