import csv
import io
import math

def _parse_number(value):
    """Return an int/float if value is a finite numeric string, else None."""
    if not isinstance(value, str):
        return None
    s = value.strip()
    if not s:
        return None

    try:
        return int(s)
    except ValueError:
        pass

    try:
        f = float(s)
        if math.isfinite(f):
            return f
    except ValueError:
        pass

    return None


def sort_csv_rows(csv_text, sort_key):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {sort_key!r} not found")

    if sort_key not in header:
        raise ValueError(f"Column {sort_key!r} not found")

    rows = []
    for row in reader:
        if row == []:  # skip blank lines
            continue
        if len(row) < len(header):
            row = row + [''] * (len(header) - len(row))
        elif len(row) > len(header):
            row = row[:len(header)]
        rows.append(row)

    # A column is numeric only if every data value in that column is numeric.
    numeric_cols = [
        all(_parse_number(row[i]) is not None for row in rows)
        for i in range(len(header))
    ]

    result = []
    for row in rows:
        d = {}
        for i, col in enumerate(header):
            value = row[i]
            if numeric_cols[i]:
                num = _parse_number(value)
                d[col] = num if num is not None else value
            else:
                d[col] = value
        result.append(d)

    # Python's sorted is stable, so equal keys keep their original order.
    return sorted(result, key=lambda r: r[sort_key])
