def kmeans_clusters(xs, ys, n_clusters):
    """Cluster 2D points using k-means.

    Initial centroids are chosen deterministically as the first n_clusters points.
    """
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)

    if isinstance(n_clusters, bool) or not isinstance(n_clusters, int):
        raise ValueError("n_clusters must be an integer")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")
    if n_clusters > n:
        raise ValueError("n_clusters cannot exceed the number of points")

    k = n_clusters
    points = list(zip(xs, ys))

    if k == 1:
        return [list(range(n))]
    if k == n:
        return [[i] for i in range(n)]

    centroids = [list(p) for p in points[:k]]
    assignments = [-1] * n

    for _ in range(300):
        new_assignments = []

        for x, y in points:
            best = 0
            best_dist = (x - centroids[0][0]) ** 2 + (y - centroids[0][1]) ** 2

            for j in range(1, k):
                d = (x - centroids[j][0]) ** 2 + (y - centroids[j][1]) ** 2
                if d < best_dist:
                    best_dist = d
                    best = j

            new_assignments.append(best)

        if new_assignments == assignments:
            break

        assignments = new_assignments

        sums = [[0.0, 0.0] for _ in range(k)]
        counts = [0] * k

        for i, j in enumerate(assignments):
            sums[j][0] += points[i][0]
            sums[j][1] += points[i][1]
            counts[j] += 1

        for j in range(k):
            if counts[j] > 0:
                centroids[j] = [sums[j][0] / counts[j], sums[j][1] / counts[j]]

