import math

def row_distance_matrix(rows):
    # Validate that every element is an int or float.
    for row in rows:
        for value in row:
            if not isinstance(value, (int, float)):
                raise TypeError(
                    f"All row elements must be int or float, got {type(value).__name__}"
                )

    n = len(rows)
    if n == 0:
        return []

    # Enforce the documented equal-length precondition.
    width = len(rows[0])
    for row in rows:
        if len(row) != width:
            raise ValueError("All rows must have the same length")

    matrix = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            total = 0.0
            for a, b in zip(rows[i], rows[j]):
                diff = a - b
                total += diff * diff

            dist = math.sqrt(total)
            matrix[i][j] = dist
            matrix[j][i] = dist

    return matrix
