import math

def _cube_root(x: float) -> float:
    # Handles negative numbers by applying the sign after taking the cube root.
    return math.copysign(abs(x) ** (1.0 / 3.0), x)

def csv_cube_roots(csv_text, columns):
    columns = list(columns)
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        header = []

    # Validate requested columns against the header.
    for col in columns:
        if col not in header:
            raise KeyError(col)

    values = {name: [] for name in header}

    for row in reader:
        if not row:
            continue
        if len(row) != len(header):
            raise ValueError("row length does not match header")

        for name, cell in zip(header, row):
            try:
                values[name].append(float(cell))
            except ValueError:
                raise ValueError(
                    f"non-numeric value {cell!r} in column {name!r}"
                ) from None

    cube_roots = {
        col: [_cube_root(v) for v in values[col]]
        for col in columns
    }

    return values, cube_roots
