import math

def normal_histogram_with_pdf(samples, mu, sigma, bins):
    if not samples:
        raise ValueError("samples must not be empty")
    if sigma <= 0:
        raise ValueError("sigma must be positive")
    if not isinstance(bins, int) or bins <= 0:
        raise ValueError("bins must be a positive integer")

    n = len(samples)
    lo = min(samples)
    hi = max(samples)

    if lo == hi:
        raise ValueError("samples must contain at least two distinct values")

    width = (hi - lo) / bins
    counts = [0] * bins

    for x in samples:
        if x == hi:
            idx = bins - 1
        else:
            idx = int((x - lo) / width)
            if idx < 0:
                idx = 0
            elif idx >= bins:
                idx = bins - 1
        counts[idx] += 1

    # Density-normalised histogram: area = density * width, total area = 1
    densities = [count / (n * width) for count in counts]

    centers = [lo + (i + 0.5) * width for i in range(bins)]
    norm = 1.0 / (sigma * math.sqrt(2.0 * math.pi))
    pdf = [
        norm * math.exp(-0.5 * ((c - mu) / sigma) ** 2)
        for c in centers
    ]

    return densities, pdf
