def cluster_matched_pairs(first, second):
    # Shared ids, in the order they appear in `first`
    ids = [k for k in first if k in second]
    if not ids:
        raise ValueError("no shared ids")

    points = [(float(first[k]), float(second[k])) for k in ids]
    n = len(points)

    if n == 1:
        return [0]

    def dist2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Deterministic k-means initialization:
    # first point, and the point farthest from it
    c0 = points[0]
    c1 = max(points[1:], key=lambda p: dist2(p, c0))

    if c0 == c1:
        return [0] * n

    labels = None
    for _ in range(100):
        new_labels = [
            0 if dist2(p, c0) <= dist2(p, c1) else 1
            for p in points
        ]

        if new_labels == labels:
            break
        labels = new_labels

        sums = [[0.0, 0.0], [0.0, 0.0]]
        counts = [0, 0]

        for p, label in zip(points, labels):
            sums[label][0] += p[0]
            sums[label][1] += p[1]
            counts[label] += 1

        if counts[0] == 0:
            c0 = max(points, key=lambda p: dist2(p, c1))
        else:
            c0 = (sums[0][0] / counts[0], sums[0][1] / counts[0])

        if counts[1] == 0:
            c1 = max(points, key=lambda p: dist2(p, c0))
        else:
            c1 = (sums[1][0] / counts[1], sums[1][1] / counts[1])

    # Ensure the cluster containing the first point is labeled 0
    if labels[0] == 1:
        labels = [1 - label for label in labels]

    return labels
