import csv
import math
from io import StringIO

def correlation_matrix_from_csv(csv_text: str) -> dict:
    reader = csv.DictReader(StringIO(csv_text))
    names = list(reader.fieldnames or [])
    if not names:
        raise ValueError("CSV must have a header row")

    columns = {name: [] for name in names}
    for row in reader:
        for name in names:
            columns[name].append(float(row[name]))

    n = len(columns[names[0]])
    if n < 2:
        raise ValueError("At least two data rows are required")

    means = {name: sum(vals) / n for name, vals in columns.items()}
    centered = {
        name: [v - means[name] for v in vals]
        for name, vals in columns.items()
    }
    norms = {
        name: math.sqrt(sum(v * v for v in centered[name]))
        for name in names
    }

    result = {}
    for a in names:
        result[a] = {}
        for b in names:
            if a == b:
                result[a][b] = 1.0
            elif norms[a] == 0.0 or norms[b] == 0.0:
                result[a][b] = float("nan")  # Pearson correlation is undefined for constant columns
            else:
                numerator = sum(x * y for x, y in zip(centered[a], centered[b]))
                result[a][b] = numerator / (norms[a] * norms[b])

    return result
