from fractions import Fraction

def filtered_regression_coefficients(rows, height, weight, columns):
    def num(x):
        # Convert numbers to exact Fractions so the example returns clean floats.
        return Fraction(str(x))

    filtered = [
        r for r in rows
        if r[columns[1]] > height and r[columns[2]] < weight
    ]
    if not filtered:
        return None

    y = [num(r[columns[0]]) for r in filtered]
    X = [[Fraction(1)] + [num(r[c]) for c in columns[1:]] for r in filtered]

    p = len(columns)
    cols = list(zip(*X))  # columns of the design matrix

    # Normal equations: (X^T X) beta = X^T y
    A = [[sum(a * c for a, c in zip(ci, cj)) for cj in cols] for ci in cols]
    b = [sum(a * yi for a, yi in zip(ci, y)) for ci in cols]

    # Solve A beta = b exactly using Gauss-Jordan elimination.
    M = [A[i] + [b[i]] for i in range(p)]
    for col in range(p):
        pivot_row = max(range(col, p), key=lambda r: abs(M[r][col]))
        if M[pivot_row][col] == 0:
            return None
        if pivot_row != col:
            M[col], M[pivot_row] = M[pivot_row], M[col]

        pivot = M[col][col]
        for j in range(col, p + 1):
            M[col][j] /= pivot

        for r in range(p):
            if r != col:
                factor = M[r][col]
                if factor != 0:
                    for j in range(col, p + 1):
                        M[r][j] -= factor * M[col][j]

    beta = [float(M[i][p]) for i in range(p)]

    result = {"const": beta[0]}
    for i, name in enumerate(columns[1:], start=1):
        result[name] = beta[i]
    return result
