from datetime import date, datetime, timedelta

def second_friday_price_schedule(start_date, prices):
    start = datetime.strptime(start_date, "%Y-%m-%d").date()

    def second_friday(year, month):
        first_day = date(year, month, 1)
        first_friday = first_day + timedelta(days=(4 - first_day.weekday()) % 7)
        return first_friday + timedelta(days=7)

    def next_month(year, month):
        return (year + 1, 1) if month == 12 else (year, month + 1)

    year, month = start.year, start.month
    friday = second_friday(year, month)

    # If this month's second Friday is already before start_date, move to next month
    if friday < start:
        year, month = next_month(year, month)
        friday = second_friday(year, month)

    schedule = []
    for price in prices:
        schedule.append((friday.isoformat(), price))
        year, month = next_month(year, month)
        friday = second_friday(year, month)

    return schedule
