import math

def cluster_labels(rows):
    if not rows:
        return []

    n = len(rows)
    m = len(rows[0])

    # Standardize each column to zero mean and unit variance.
    means = [sum(row[j] for row in rows) / n for j in range(m)]
    stds = []
    for j in range(m):
        var = sum((row[j] - means[j]) ** 2 for row in rows) / n
        std = math.sqrt(var)
        if std == 0.0:
            std = 1.0  # constant column becomes all zeros
        stds.append(std)

    X = [[(row[j] - means[j]) / stds[j] for j in range(m)] for row in rows]

    k = 3

    # Initial centroids: first k distinct rows.
    centroids = []
    seen = set()
    for x in X:
        key = tuple(x)
        if key not in seen:
            seen.add(key)
            centroids.append(list(x))
            if len(centroids) == k:
                break
    while len(centroids) < k:
        centroids.append([0.0] * m)

    labels = [-1] * n

    for _ in range(100):
        # Assign each row to the nearest centroid.
        new_labels = []
        for x in X:
            best = 0
            best_d = float("inf")
            for c_idx, c in enumerate(centroids):
                d = sum((x[j] - c[j]) ** 2 for j in range(m))
                if d < best_d:
                    best_d = d
                    best = c_idx
            new_labels.append(best)

        # Update centroids.
        new_centroids = [None] * k
        for c_idx in range(k):
            members = [X[i] for i in range(n) if new_labels[i] == c_idx]
            if members:
                new_centroids[c_idx] = [
                    sum(point[j] for point in members) / len(members)
                    for j in range(m)
                ]

        # Reinitialize any empty cluster to a far-away point.
        empty = [c for c in range(k) if new_centroids[c] is None]
        if empty:
            used = set()
            for c in empty:
                best_i = -1
                best_d = -1.0
                for i, x in enumerate(X):
                    if i in used:
                        continue
                    d = sum(
                        (x[j] - centroids[new_labels[i]][j]) ** 2
                        for j in range(m)
                    )
                    if d > best_d:
                        best_d = d
                        best_i = i
                if best_i == -1:
                    new_centroids[c] = [0.0] * m
                else:
                    used.add(best_i)
                    new_centroids[c] = list(X[best_i])

        if new_labels == labels and all(
            new_centroids[c] == centroids[c] for c in range(k)
        ):
            labels = new_labels
            centroids = new_centroids
            break

        labels = new_labels
        centroids = new_centroids

    # Renumber clusters in order of first appearance.
    mapping = {}
    next_label = 0
    result = []
    for lab in labels:
        if lab not in mapping:
            mapping[lab] = next_label
            next_label += 1
        result.append(mapping[lab])

    return result
