from numbers import Real

def normalize_columns(data):
    if not data:
        raise ValueError("data must not be empty")

    normalized = {}

    for name, column in data.items():
        try:
            values = list(column)
        except TypeError as exc:
            raise ValueError(f"column {name!r} must be an iterable of numbers") from exc

        if not values:
            raise ValueError(f"column {name!r} must not be empty")

        for value in values:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise ValueError(
                    f"column {name!r} contains non-numeric value: {value!r}"
                )

        low = min(values)
        high = max(values)
        span = high - low

        if span == 0:
            normalized[name] = [0.0] * len(values)
        else:
            normalized[name] = [float((value - low) / span) for value in values]

    return normalized
