def fit_joined_regression(feature_rows, target_rows, features, target):
    target_by_id = {row['id']: row for row in target_rows}

    X = []
    y = []

    # Join on id, preserving feature_rows order
    for row in feature_rows:
        if row['id'] in target_by_id:
            target_row = target_by_id[row['id']]
            X.append([1.0] + [float(row[f]) for f in features])
            y.append(float(target_row[target]))

    if not X:
        raise ValueError("no overlapping ids between feature_rows and target_rows")

    m = len(features) + 1

    # Normal equations: A * params = b, where A = X^T X and b = X^T y
    A = [[0.0] * m for _ in range(m)]
    b = [0.0] * m

    for xi, yi in zip(X, y):
        for i in range(m):
            b[i] += xi[i] * yi
            for j in range(m):
                A[i][j] += xi[i] * xi[j]

    # Solve A * params = b using Gauss-Jordan elimination
    M = [A[i][:] + [b[i]] for i in range(m)]

    for col in range(m):
        pivot = max(range(col, m), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("singular matrix: cannot fit unique OLS coefficients")

        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_val = M[col][col]
        for c in range(col, m + 1):
            M[col][c] /= pivot_val

        for r in range(m):
            if r != col:
                factor = M[r][col]
                if factor != 0.0:
                    for c in range(col, m + 1):
                        M[r][c] -= factor * M[col][c]

    params = [M[i][m] for i in range(m)]

    intercept = params[0]
    coefficients = params[1:]

    residuals = []
    for xi, yi in zip(X, y):
        predicted = sum(params[i] * xi[i] for i in range(m))
        residuals.append(yi - predicted)

    return {
        'coefficients': [float(c) for c in coefficients],
        'intercept': float(intercept),
        'residuals': [float(r) for r in residuals],
    }
