import math
from typing import Dict, List, Tuple

def _linear_quantile(values: List[float], q: float) -> float:
    """Return the q-quantile using linear interpolation (numpy default)."""
    n = len(values)
    pos = (n - 1) * q
    lo = math.floor(pos)
    hi = math.ceil(pos)

    if lo == hi:
        return float(values[lo])

    frac = pos - lo
    return float(values[lo] + frac * (values[hi] - values[lo]))


def fruit_sales_box_stats(
    records: List[Tuple[str, str, float]]
) -> Dict[str, Tuple[float, float, float, float, float]]:
    if not records:
        raise ValueError("records is empty")

    sales_by_fruit: Dict[str, List[float]] = {}

    for fruit, _day, sales in records:
        sales_by_fruit.setdefault(fruit, []).append(sales)

    result = {}

    for fruit, sales in sales_by_fruit.items():
        values = sorted(sales)

        result[fruit] = (
            float(values[0]),
            _linear_quantile(values, 0.25),
            _linear_quantile(values, 0.50),
            _linear_quantile(values, 0.75),
            float(values[-1]),
        )

    return result
