        if self.done:
            return

        tag = tag.lower()

        if tag == "table":
            if self.table_depth == 0:
                self.found_table = True
                self.capturing = True
            self.table_depth += 1
            return

        # Only handle direct rows/cells of the first table.
        if not self.capturing or self.table_depth != 1:
            return

        if tag == "tr":
            if self.in_row:
                self._finalize_cell()
                self._finalize_row()
            self.in_row = True
            self.row_has_td = False
            self.row_tds = []

