        if tag == "table":
            if self.table_depth == 1:
                self._finalize_cell()
                self._finalize_row()
                self.done = True
                self.capturing = False
            if self.table_depth > 0:
                self.table_depth -= 1
            return

        if not self.capturing or self.table_depth != 1:
