import math

def row_zscores_and_correlation(data):
    if not data:
        return [], []

    n_rows = len(data)
    n_cols = len(data[0])

    for row in data:
        if len(row) != n_cols:
            raise ValueError("data must be rectangular")

    # Row-wise z-scores using population standard deviation
    z = []
    for row in data:
        if n_cols == 0:
            z.append([])
            continue

        mean = sum(row) / n_cols
        var = sum((x - mean) ** 2 for x in row) / n_cols
        sd = math.sqrt(var)

        if sd == 0.0:
            z.append([0.0] * n_cols)
        else:
            z.append([(x - mean) / sd for x in row])

    if n_cols == 0:
        return z, []

    # Column means and population standard deviations of the z-score matrix
    col_means = [
        sum(z[r][c] for r in range(n_rows)) / n_rows
        for c in range(n_cols)
    ]
    col_sds = [
        math.sqrt(
            sum((z[r][c] - col_means[c]) ** 2 for r in range(n_rows)) / n_rows
        )
        for c in range(n_cols)
    ]

    # Pearson correlation matrix between columns
    corr = []
    for i in range(n_cols):
        corr_row = []
        for j in range(n_cols):
            if i == j:
                corr_row.append(1.0)
            else:
                denom = col_sds[i] * col_sds[j]
                if denom == 0.0:
                    corr_row.append(0.0)
                else:
                    cov = sum(
                        (z[r][i] - col_means[i]) * (z[r][j] - col_means[j])
                        for r in range(n_rows)
                    ) / n_rows
                    corr_row.append(cov / denom)
        corr.append(corr_row)

    return z, corr
```

If a row has zero population standard deviation, its z-scores are returned as `0.0`. If a column of the z-score matrix has zero variance, correlations involving it are returned as `0.0`, with the diagonal kept as `1.0`.

