from datetime import datetime, timedelta, timezone

def timestamp_dates_and_histogram(timestamps):
    ts = list(timestamps)
    if not ts:
        raise ValueError("timestamps list is empty")

    # Convert Unix timestamps to UTC date-time strings
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    dates = []
    for t in ts:
        dt = epoch + timedelta(seconds=t)
        dates.append(
            f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d} "
            f"{dt.hour:02d}:{dt.minute:02d}:{dt.second:02d}"
        )

    lo = min(ts)
    hi = max(ts)
    counts = [0] * 10

    if lo == hi:
        counts[-1] = len(ts)
        return dates, counts

    span = hi - lo

    # Use exact integer arithmetic when possible
    if all(isinstance(t, int) for t in ts):
        for t in ts:
            idx = (t - lo) * 10 // span
            if idx >= 10:
                idx = 9
            counts[idx] += 1
    else:
        for t in ts:
            if t == hi:
                idx = 9
            else:
                idx = int((t - lo) * 10 / span)
                if idx >= 10:
                    idx = 9
                elif idx < 0:
                    idx = 0
            counts[idx] += 1

    return dates, counts
