import csv
import io

def grouped_column_means(csv_text, group_col, value_col):
    """
    Group rows by group_col and return the mean of value_col for each group.
    Blank value cells are ignored. Non-numeric values raise ValueError.
    """
    sums = {}
    counts = {}

    reader = csv.DictReader(io.StringIO(csv_text))

    for row in reader:
        group = row[group_col]
        if group is None:
            group = ""
        group = str(group)

        raw = row[value_col]
        if raw is None:
            raw = ""

        text = raw.strip()
        if not text:          # blank cell
            continue

        try:
            value = float(text)
        except (ValueError, OverflowError) as exc:
            raise ValueError(
                f"Non-numeric value {raw!r} in column {value_col!r}"
            ) from exc

        sums[group] = sums.get(group, 0.0) + value
        counts[group] = counts.get(group, 0) + 1

    return {group: sums[group] / counts[group] for group in sums}
