from bisect import bisect_right

def histogram_bins(values, bins):
    values = list(values)

    if isinstance(bins, int):
        if bins <= 0:
            raise ValueError("bins must be a positive integer")
        if not values:
            raise ValueError("values must be non-empty when bins is an integer")

        lo = min(values)
        hi = max(values)

        if lo == hi:
            edges = [float(lo)] * (bins + 1)
        else:
            edges = [float(lo + (hi - lo) * i / bins) for i in range(bins)]
            edges.append(float(hi))
    else:
        edges = [float(edge) for edge in bins]

    n = len(edges) - 1
    if n <= 0:
        return [], edges

    counts = [0] * n
    first, last = edges[0], edges[-1]

    for v in values:
        if v < first or v > last:
            continue

        if v == last:
            counts[-1] += 1
        else:
            idx = bisect_right(edges, v) - 1
            if 0 <= idx < n:
                counts[idx] += 1

    return counts, edges
