def classical_seasonal_decomposition(values, period, model='additive'):
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    values = list(values)
    n = len(values)

    if not isinstance(period, int) or period <= 0:
        raise ValueError("period must be a positive integer")
    if n < 2 * period:
        raise ValueError("values must contain at least two full periods")

    half = period // 2
    trend = [None] * n

    # Trend via centred moving average.
    # For even periods, use a 2 x period centred moving average.
    if period % 2 == 1:
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        for i in range(half, n - half):
            window = values[i - half:i + half + 1]
            trend[i] = (window[0] + 2 * sum(window[1:-1]) + window[-1]) / (2 * period)

    detrended = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == 'additive':
                detrended[i] = values[i] - trend[i]
            else:
                detrended[i] = values[i] / trend[i]

    phase_sums = [0.0] * period
    phase_counts = [0] * period

    for i, d in enumerate(detrended):
        if d is not None:
            r = i % period
            phase_sums[r] += d
            phase_counts[r] += 1

    phase_avgs = [
        phase_sums[r] / phase_counts[r] if phase_counts[r] else 0.0
        for r in range(period)
    ]

    if model == 'additive':
        offset = sum(phase_avgs) / period
        seasonal_avgs = [a - offset for a in phase_avgs]
    else:
        scale = sum(phase_avgs) / period
        seasonal_avgs = [a / scale for a in phase_avgs]

    seasonal = [seasonal_avgs[i % period] for i in range(n)]

    resid = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == 'additive':
                resid[i] = values[i] - trend[i] - seasonal[i]
            else:
                resid[i] = values[i] / (trend[i] * seasonal[i])

    return {'trend': trend, 'seasonal': seasonal, 'resid': resid}
