import math
import re

_NUM_RE = re.compile(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?')
_THOUSANDS_RE = re.compile(r'[+-]?\d{1,3}(?:,\d{3})+(?:\.\d*)?(?:[eE][+-]?\d+)?')


def _parse_number(value):
    """Parse a numeric string, allowing comma thousands separators."""
    if value is None:
        return None

    s = value.strip()
    if not s:
        return None

    if ',' in s:
        # Only accept commas as thousands separators, e.g. 1,000 or 12,345.67
        if not _THOUSANDS_RE.fullmatch(s):
            return None
        s = s.replace(',', '')
    else:
        if not _NUM_RE.fullmatch(s):
            return None

    try:
        num = float(s)
    except ValueError:
        return None

    if not math.isfinite(num):
        return None

    return num


def summarize_numeric_csv(csv_text):
    """
    Summarize numeric columns in CSV text.

    Returns a dict with:
      - 'means': column name -> mean
      - 'std_devs': column name -> sample standard deviation (None if only one value)
      - 'f_value': one-way ANOVA F statistic across numeric columns,
                   or None if fewer than two numeric columns / undefined
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)

    if not rows:
        return {'means': {}, 'std_devs': {}, 'f_value': None}

    header = rows[0]
    data_rows = [row for row in rows[1:] if row]  # skip completely blank lines

    numeric_columns = []

    for col_idx, name in enumerate(header):
        values = []
        is_numeric = True

        for row in data_rows:
            raw = row[col_idx] if col_idx < len(row) else None
            num = _parse_number(raw)
            if num is None:
                is_numeric = False
                break
            values.append(num)

        if is_numeric and values:
            numeric_columns.append((name, values))

    means = {}
    std_devs = {}

    for name, values in numeric_columns:
        n = len(values)
        mean = sum(values) / n
        means[name] = mean

        if n >= 2:
            variance = sum((x - mean) ** 2 for x in values) / (n - 1)
            std_devs[name] = math.sqrt(variance)
        else:
            std_devs[name] = None

    k = len(numeric_columns)

    if k < 2 or len(data_rows) < 2:
        f_value = None
    else:
        all_values = [x for _, values in numeric_columns for x in values]
        grand_mean = sum(all_values) / len(all_values)

        ss_between = 0.0
        ss_within = 0.0

        for name, values in numeric_columns:
            group_mean = means[name]
            ss_between += len(values) * (group_mean - grand_mean) ** 2
            ss_within += sum((x - group_mean) ** 2 for x in values)

        df_between = k - 1
        df_within = len(all_values) - k

        ms_between = ss_between / df_between
        ms_within = ss_within / df_within

        if ms_within == 0:
            f_value = None if ms_between == 0 else float('inf')
        else:
            f_value = ms_between / ms_within

    return {'means': means, 'std_devs': std_devs, 'f_value': f_value}
