import math

def max_pairwise_distance(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n < 2:
        return 0.0

    max_dist = 0.0

    for i in range(n):
        x1, y1 = xs[i], ys[i]
        for j in range(i + 1, n):
            x2, y2 = xs[j], ys[j]
            dist = math.hypot(x1 - x2, y1 - y2)
            if dist > max_dist:
                max_dist = dist

    return max_dist

def standardize_columns(data):
    result = {}

    for col, values in data.items():
        n = len(values)

        if n == 0:
            result[col] = ([], [0] * 20)
            continue

        # Population standard deviation: divide by n
        mean = sum(values) / n
        std = (sum((x - mean) ** 2 for x in values) / n) ** 0.5

        if std == 0:
            raise ValueError(
                f"Column {col!r} has zero variance; cannot standardize to unit variance"
            )

        standardized = [(x - mean) / std for x in values]

        # 20 equal-width bins from min to max; max goes in the last bin
        lo = min(standardized)
        hi = max(standardized)
        width = (hi - lo) / 20

        counts = [0] * 20
        for v in standardized:
            idx = int((v - lo) / width)
            if idx >= 20:
                idx = 19
            if idx < 0:
                idx = 0
            counts[idx] += 1

        result[col] = (standardized, counts)

    return result

