def fit_and_evaluate_linear_regression(X_train, y_train, X_test, y_test):
    n = len(X_train)
    p = len(X_train[0]) if n else 0
    m = p + 1  # intercept plus one coefficient per feature

    # Build normal equations: (X^T X) beta = X^T y
    A = [[0.0] * m for _ in range(m)]
    b = [0.0] * m

    for row, y in zip(X_train, y_train):
        x = [1.0] + [float(v) for v in row]
        y = float(y)
        for i in range(m):
            b[i] += x[i] * y
            for j in range(m):
                A[i][j] += x[i] * x[j]

    # Solve A beta = b using Gaussian elimination with partial pivoting
    aug = [A[i][:] + [b[i]] for i in range(m)]

    for col in range(m):
        pivot = max(range(col, m), key=lambda r: abs(aug[r][col]))
        if abs(aug[pivot][col]) < 1e-12:
            raise ValueError("Singular normal equations; cannot fit unique OLS model")

        aug[col], aug[pivot] = aug[pivot], aug[col]

        pivot_val = aug[col][col]
        for j in range(col, m + 1):
            aug[col][j] /= pivot_val

        for r in range(m):
            if r != col:
                factor = aug[r][col]
                if factor != 0.0:
                    for j in range(col, m + 1):
                        aug[r][j] -= factor * aug[col][j]

    beta = [aug[i][m] for i in range(m)]

    intercept = float(beta[0])
    coefficients = [float(c) for c in beta[1:]]

    predictions = []
    for row in X_test:
        x = [1.0] + [float(v) for v in row]
        pred = sum(x[i] * beta[i] for i in range(m))
        predictions.append(float(pred))

    if y_test:
        mse = sum((pred - float(y)) ** 2 for pred, y in zip(predictions, y_test)) / len(y_test)
    else:
        mse = 0.0

    return predictions, coefficients, intercept, float(mse)
