from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self._row_stack = []   # currently open <tr> rows
        self._cell_stack = []  # open <td> text buffers

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == "tr":
            row = []
            self.rows.append(row)
            self._row_stack.append(row)
        elif tag == "td" and self._row_stack:
            cell = []
            self._cell_stack.append(cell)
            self._row_stack[-1].append(cell)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == "tr":
            if self._row_stack:
                self._row_stack.pop()
        elif tag == "td" and self._cell_stack:
            cell = self._cell_stack.pop()
            if self._row_stack:
                row = self._row_stack[-1]
                for i, item in enumerate(row):
                    if item is cell:
                        row[i] = "".join(cell).strip()
                        break

    def handle_data(self, data):
        # Add text to every open <td>, so nested table text is included
        # in the enclosing cell's text as well.
        for cell in self._cell_stack:
            cell.append(data)


def extract_table_rows(html):
    """
    Return a list of rows from all <tr> elements in document order.
    Each row is a list of stripped text contents of its <td> cells.
    """
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    return parser.rows
