import json
from html.parser import HTMLParser


class _TitleParser(HTMLParser):
    def __init__(self):
        # convert_charrefs=True decodes HTML entities in text automatically
        super().__init__(convert_charrefs=True)
        self._seen_title = False
        self._in_title = False
        self._parts = []

    def handle_starttag(self, tag, attrs):
        if tag == "title" and not self._seen_title:
            self._seen_title = True
            self._in_title = True

    def handle_endtag(self, tag):
        if tag == "title" and self._in_title:
            self._in_title = False

    def handle_data(self, data):
        if self._in_title:
            self._parts.append(data)

    def get_title(self):
        return "".join(self._parts) if self._seen_title else None


def extract_title_json(html: str) -> str:
    parser = _TitleParser()
    parser.feed(html)
    parser.close()
    return json.dumps({"title": parser.get_title()}, ensure_ascii=False)
