import json
import math

def _percentile(sorted_vals, p):
    """p-th percentile using linear interpolation: pos = (n - 1) * p / 100."""
    n = len(sorted_vals)
    if n == 0:
        raise ValueError("Cannot compute percentile of empty list")
    if n == 1:
        return float(sorted_vals[0])

    pos = (n - 1) * (p / 100.0)
    lo = math.floor(pos)
    hi = math.ceil(pos)

    if lo == hi:
        return float(sorted_vals[lo])

    frac = pos - lo
    return float(sorted_vals[lo] + (sorted_vals[hi] - sorted_vals[lo]) * frac)


def summarize_values_by_key(json_text):
    def _reject_constant(value):
        raise ValueError(f"Invalid JSON constant: {value}")

    try:
        data = json.loads(json_text, parse_constant=_reject_constant)
    except (ValueError, TypeError) as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, list):
        raise ValueError("Top-level JSON value must be a list")

    values_by_key = {}

    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item in the list must be a JSON object")

        for key, value in item.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"Value for key {key!r} must be a number")
            values_by_key.setdefault(key, []).append(value)

    result = {}

    for key, values in values_by_key.items():
        ordered = sorted(values)
        n = len(ordered)

        result[key] = {
            "mean": sum(ordered) / n,
            "median": _percentile(ordered, 50),
            "q1": _percentile(ordered, 25),
            "q3": _percentile(ordered, 75),
        }

    return result
