import numbers


def _is_numeric(value):
    return isinstance(value, numbers.Number) and not isinstance(value, complex)


def _pearson(x, y):
    n = len(x)
    mean_x = math.fsum(x) / n
    mean_y = math.fsum(y) / n
    sxy = math.fsum((a - mean_x) * (b - mean_y) for a, b in zip(x, y))
    sxx = math.fsum((a - mean_x) ** 2 for a in x)
    syy = math.fsum((b - mean_y) ** 2 for b in y)
    if sxx <= 0.0 or syy <= 0.0:
        # Correlation is undefined for a constant column; treat as no correlation.
        return 0.0
    return sxy / math.sqrt(sxx * syy)


def most_correlated_columns(data):
    if not data:
        raise ValueError("no data")
    if len(data) < 2:
        raise ValueError("fewer than two columns")

    names = list(data.keys())
    columns = []
    for name in names:
        values = data[name]
        for value in values:
            if not _is_numeric(value):
                raise TypeError(
                    "column {!r} contains non-numeric value {!r}".format(name, value)
                )
        columns.append(list(values))

    lengths = {len(column) for column in columns}
    if 0 in lengths:
        raise ValueError("no data")
    if len(lengths) != 1:
        raise ValueError("columns must have equal lengths")

    best_pair = None
    best_abs = -1.0
    for i in range(len(names)):
