import csv
import io
import re

_NUMERIC_RE = re.compile(r'^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$')


def _parse_value(cell):
    if cell == '':
        return None
    if _NUMERIC_RE.match(cell):
        try:
            return int(cell)
        except ValueError:
            return float(cell)
    return cell


def merge_csv_texts(csv_texts):
    columns = []
    seen = set()
    parsed = []
    for text in csv_texts:
        rows = list(csv.reader(io.StringIO(text)))
        if not rows:
            parsed.append(([], []))
            continue
        header = rows[0]
        for col in header:
            if col not in seen:
                seen.add(col)
                columns.append(col)
        data = []
        for row in rows[1:]:
            data.append({col: (row[i] if i < len(row) else '') for i, col in enumerate(header)})
        parsed.append((header, data))

    result = []
    for header, data in parsed:
        for raw in data:
            result.append({col: _parse_value(raw.get(col, '')) for col in columns})
    return result

