import math


def letter_count_correlations(strings):
    """Return pairwise Pearson correlations between per-letter counts.

    `strings` is a list of lowercase strings. For each letter that occurs
    in at least one string, count its occurrences in every string, then
    compute the Pearson correlation between each pair of letters' count
    vectors across the strings. Returns a nested dict result[x][y], or
    None if `strings` is empty.
    """
    if not strings:
        return None

    letters = sorted({ch for s in strings for ch in s})
    counts = {
        ch: [s.count(ch) for s in strings]
        for ch in letters
    }

    n = len(strings)
    means = {ch: sum(v) / n for ch, v in counts.items()}

    def centered(ch):
        m = means[ch]
        return [x - m for x in counts[ch]]

    centered_counts = {ch: centered(ch) for ch in letters}
    norms = {
        ch: math.sqrt(sum(x * x for x in centered_counts[ch]))
        for ch in letters
    }

    result = {}
    for x in letters:
        row = {}
        for y in letters:
            if x == y:
                row[y] = 1.0
            elif norms[x] == 0.0 or norms[y] == 0.0:
                row[y] = 0.0
            else:
                dot = sum(a * b for a, b in zip(centered_counts[x], centered_counts[y]))
                corr = dot / (norms[x] * norms[y])
                if corr > 1.0 - 1e-12:
                    corr = 1.0
                elif corr < -1.0 + 1e-12:
                    corr = -1.0
                row[y] = corr
        result[x] = row
    return result

