import math


def _z_scores(values):
    n = len(values)
    mean = sum(values) / n
    variance = sum((v - mean) ** 2 for v in values) / n
    std = math.sqrt(variance)
    if std == 0:
        return [0.0 for _ in values]
    return [(v - mean) / std for v in values]


def standardize_series(x, y, labels):
    result = {}
    for xs, ys, label in zip(x, y, labels):
        result[label] = [_z_scores(xs), _z_scores(ys)]
    return result

