import io


def _is_float(value):
    try:
        float(value)
        return True
    except (TypeError, ValueError):
        return False


def normalize_numeric_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        raise ValueError("no numeric columns: empty CSV")

    header = rows[0]
    data_rows = [row for row in rows[1:] if row]

    columns = {name: [] for name in header}
    for row in data_rows:
        for i, name in enumerate(header):
            columns[name].append(row[i] if i < len(row) else "")

    result = {}
    numeric_found = False
    for name in header:
        values = columns[name]
        if values and all(_is_float(v) for v in values):
            numeric_found = True
            nums = [float(v) for v in values]
            lo = min(nums)
            hi = max(nums)
            if hi == lo:
                result[name] = [0.0] * len(nums)
            else:
                result[name] = [(v - lo) / (hi - lo) for v in nums]
        else:
            result[name] = list(values)

    if not numeric_found:
        raise ValueError("no numeric columns in the data")

    return result

