from html.parser import HTMLParser

_VOID_ELEMENTS = frozenset({
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
})


class _FirstTagTextParser(HTMLParser):
    """Streaming parser that captures the text of the first matching tag."""

    def __init__(self, tag):
        super().__init__(convert_charrefs=True)
        self.tag = tag
        self.found = False
        self.done = False
        self.depth = 0
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if not self.found:
            if tag == self.tag:
                self.found = True
                if tag in _VOID_ELEMENTS:
                    # Void elements have no content and no end tag.
                    self.done = True
                else:
                    self.depth = 1
            return
        if tag not in _VOID_ELEMENTS:
            self.depth += 1

    def handle_endtag(self, tag):
        if self.done or self.depth == 0:
            return
        if tag in _VOID_ELEMENTS:
            return
        self.depth -= 1
        if self.depth == 0:
            self.done = True

    def handle_data(self, data):
        if self.depth > 0:
            self.parts.append(data)

    @property
    def text(self):
        return ''.join(self.parts)


def first_tag_text(html, tag):
    """Return the text content of the first element named `tag` in `html`.

    The text of nested elements is included, tags are removed, and HTML
    entities are decoded. Returns None if no such element exists or its
    text content is empty.
