import csv
import io
import re
from datetime import date

_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _parse_date(value):
    """Parse a strict 'YYYY-MM-DD' string into a date, or return None."""
    if not isinstance(value, str) or not _DATE_RE.match(value):
        return None
    try:
        return date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        return None


def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    start = _parse_date(start_date)
    end = _parse_date(end_date)
    if start is None:
        raise ValueError(f"Invalid start_date: {start_date!r} (expected 'YYYY-MM-DD')")
    if end is None:
        raise ValueError(f"Invalid end_date: {end_date!r} (expected 'YYYY-MM-DD')")

    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        raise ValueError("CSV text is empty (no header row)")

    header = rows[0]
    try:
        col_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column {column_name!r} not found in header: {header}")

    result = []
    for row in rows[1:]:
        if not row:
            continue
        if col_index >= len(row):
            continue
        row_date = _parse_date(row[col_index])
        if row_date is not None and start <= row_date <= end:
            result.append(list(row))
    return result

