import csv
import io
import math


def _parse_csv(csv_text):
    """Parse CSV text into (header, rows) where rows are lists of raw strings."""
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV has no header row")
    rows = [row for row in reader if row]
    return header, rows


def _to_float(value, context):
    """Convert a raw CSV field to a finite float or raise ValueError."""
    if value is None:
        raise ValueError("missing value in " + context)
    text = value.strip()
    if text == "":
        raise ValueError("missing value in " + context)
    try:
        number = float(text)
    except (TypeError, ValueError):
        raise ValueError("non-numeric value %r in %s" % (value, context))
    if not math.isfinite(number):
        raise ValueError("non-finite value %r in %s" % (value, context))
    return number


def _solve_linear_system(matrix, rhs):
    """Solve matrix @ x = rhs by Gaussian elimination with partial pivoting.

    Falls back to a tiny ridge term if the matrix is singular so that a
    rank-deficient design still yields a least-squares-style solution.
    """
    n = len(matrix)
    a = [list(row) + [rhs[i]] for i, row in enumerate(matrix)]
    scale = max((abs(a[i][i]) for i in range(n)), default=0.0)
    if scale == 0.0:
        scale = 1.0
    tol = 1e-12 * scale * n

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(a[r][col]))
        if abs(a[pivot][col]) <= tol:
            # Singular: retry with a small ridge on the diagonal.
            ridge = 1e-10 * scale
            a = [list(row) + [rhs[i]] for i, row in enumerate(matrix)]
            for i in range(n):
                a[i][i] += ridge
            for retry_col in range(n):
                pivot = max(range(retry_col, n), key=lambda r: abs(a[r][retry_col]))
                if abs(a[pivot][retry_col]) <= tol:
                    raise ValueError("singular system in regression fit")
                a[retry_col], a[pivot] = a[pivot], a[retry_col]
                pivot_val = a[retry_col][retry_col]
                for r in range(retry_col + 1, n):
                    factor = a[r][retry_col] / pivot_val
                    if factor != 0.0:
                        for c in range(retry_col, n + 1):
                            a[r][c] -= factor * a[retry_col][c]
            break
        a[col], a[pivot] = a[pivot], a[col]
        pivot_val = a[col][col]
        for r in range(col + 1, n):
            factor = a[r][col] / pivot_val
            if factor != 0.0:
                for c in range(col, n + 1):
                    a[r][c] -= factor * a[col][c]

    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        total = a[i][n] - sum(a[i][j] * x[j] for j in range(i + 1, n))
        x[i] = total / a[i][i]
    return x


def predict_linear_regression(train_csv, test_csv, target):
    train_header, train_rows = _parse_csv(train_csv)
    test_header, test_rows = _parse_csv(test_csv)

    if target not in train_header:
        raise ValueError("target column %r not found in header" % target)
    if train_header != test_header:
        raise ValueError("train and test CSVs have different columns")

    feature_idx = [i for i, name in enumerate(train_header) if name != target]
    target_idx = train_header.index(target)

    n_features = len(feature_idx)
    if n_features == 0:
        raise ValueError("no feature columns available")

    # Design matrix with intercept column; X^T X and X^T y for normal equations.
    size = n_features + 1
    xtx = [[0.0] * size for _ in range(size)]
    xty = [0.0] * size

    if not train_rows:
        raise ValueError("training CSV has no data rows")

    for row in train_rows:
        if len(row) != len(train_header):
            raise ValueError("training row has wrong number of fields")
        x = [1.0] + [_to_float(row[i], "training features") for i in feature_idx]
        y = _to_float(row[target_idx], "training target")
        for i in range(size):
            xty[i] += x[i] * y
            xi = x[i]
            row_i = xtx[i]
            for j in range(i, size):
                row_i[j] += xi * x[j]
    for i in range(size):
        for j in range(i):
            xtx[i][j] = xtx[j][i]

    beta = _solve_linear_system(xtx, xty)

    predictions = []
    for row in test_rows:
        if len(row) != len(test_header):
            raise ValueError("test row has wrong number of fields")
        x = [1.0] + [_to_float(row[i], "test features") for i in feature_idx]
        predictions.append(float(sum(b * xi for b, xi in zip(beta, x))))
    return predictions

