import csv
import io


def normalize_csv_columns(csv_text):
    """Min-max normalize each numeric column of a CSV string to [0, 1].

    Returns a dict mapping each header column name to a list of floats
    in row order. Constant columns become all zeros.
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]

    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    data = []
    for row in rows[1:]:
        values = [float(cell) for cell in row]
        data.append(values)

    result = {}
    for col_idx, name in enumerate(header):
        column = [row[col_idx] for row in data]
        if not column:
            result[name] = []
            continue
        lo = min(column)
        hi = max(column)
        if hi == lo:
            result[name] = [0.0] * len(column)
        else:
            result[name] = [(v - lo) / (hi - lo) for v in column]

    return result

