from html.parser import HTMLParser

_TARGET_CLASS = "data-table"


class _DataTableExtractor(HTMLParser):
    """Collect the ``<tr>``/``<td>`` contents of the first matching table.

    Only the rows and cells that belong to the target table itself are
    collected; rows and cells of a table nested inside it are not rows of
    the target table (their text still counts as part of the enclosing
    cell's text, because tags are simply stripped).
    """

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self._found_target = False  # a matching <table> has already been seen
        self._table_stack = []      # one entry per currently open <table>
        self._target_depth = None   # stack depth at which the target table sits
        self._row = None            # cell texts of the currently open <tr>
        self._cell = None           # text chunks of the currently open <td>

    # ------------------------------------------------------------------
    # state helpers
    # ------------------------------------------------------------------
    @property
    def _in_target(self):
        return (
            self._target_depth is not None
            and len(self._table_stack) >= self._target_depth
        )

    @property
    def _inside_nested_table(self):
        return self._in_target and len(self._table_stack) > self._target_depth

    def _flush_cell(self):
        if self._cell is not None:
            if self._row is not None:
                self._row.append("".join(self._cell))
            self._cell = None

    def _flush_row(self):
        self._flush_cell()
        if self._row is not None:
            self.rows.append(self._row)
            self._row = None

    # ------------------------------------------------------------------
    # HTMLParser callbacks
    # ------------------------------------------------------------------
    def handle_starttag(self, tag, attrs):
        if tag == "table":
            is_target = False
            if not self._found_target:
                for name, value in attrs:
                    if name == "class":
                        is_target = value == _TARGET_CLASS
                        break
                if is_target:
                    self._found_target = True
                    self._target_depth = len(self._table_stack) + 1
            self._table_stack.append(is_target)
            return
        if not self._in_target or self._inside_nested_table:
            return
        if tag == "tr":
            # A new <tr> implicitly closes an open row (and its open cell).
            self._flush_row()
            self._row = []
        elif tag == "td":
            if self._row is not None:
                # A new <td> implicitly closes an open cell.
                self._flush_cell()
                self._cell = []

    def handle_endtag(self, tag):
        if tag == "table":
            if self._table_stack and self._table_stack.pop():
                self._target_depth = None
                self._flush_row()
            return
        if not self._in_target or self._inside_nested_table:
            return
        if tag == "tr":
            self._flush_row()
        elif tag == "td":
            self._flush_cell()

    def handle_data(self, data):
        if self._cell is not None:
            self._cell.append(data)

    def close(self):
        super().close()
        self._flush_row()


def extract_data_table_rows(html):
    """Return the rows of the first ``<table>`` whose class is exactly
    ``"data-table"``.

    The result is a list with one entry per ``<tr>`` of that table, in
    document order; each entry is the list of the text contents of the
    row's ``<td>`` cells.  Cell text keeps its inner whitespace and has
    entities decoded and tags removed.  A row with no ``<td>`` cells gives
    an empty list.  If there is no such table, or it has no rows, an
    empty list is returned.
    """
    if not html:
        return []
    if isinstance(html, bytes):
        html = html.decode("utf-8", "replace")
    parser = _DataTableExtractor()
    parser.feed(html)
    parser.close()
    return parser.rows

