from html.parser import HTMLParser

_VOID_ELEMENTS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
}


class _Node:
    __slots__ = ('tag', 'attrs', 'children')

    def __init__(self, tag, attrs):
        self.tag = tag
        self.attrs = attrs
        self.children = []  # list of _Node or str


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node('#root', {})
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].children.append(node)
        if tag not in _VOID_ELEMENTS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        if data:
            self.stack[-1].children.append(data)


def _classes(node):
    return (node.attrs.get('class') or '').split()


def _text(node):
    parts = []

    def _collect(n):
        for child in n.children:
            if isinstance(child, str):
                parts.append(child)
            else:
                _collect(child)

    _collect(node)
    return ''.join(parts)


def _first_descendant(node, predicate):
    for child in node.children:
        if isinstance(child, str):
            continue
        if predicate(child):
            return child
        found = _first_descendant(child, predicate)
        if found is not None:
            return found
    return None


def _iter_containers(node, out):
    for child in node.children:
        if isinstance(child, str):
            continue
        if child.tag == 'div' and 'container' in _classes(child):
            out.append(child)
        _iter_containers(child, out)


def extract_article_info(html):
    """Return a list of (title, date, author) tuples, one per container div."""
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()

    containers = []
    _iter_containers(builder.root, containers)

    results = []
    for div in containers:
        title_node = _first_descendant(div, lambda n: n.tag == 'h1')
        date_node = _first_descendant(
            div, lambda n: n.tag == 'span' and 'date' in _classes(n))
        author_node = _first_descendant(
            div, lambda n: n.tag == 'span' and 'author' in _classes(n))

        title = _text(title_node).strip() if title_node is not None else 'No Title'
        date = _text(date_node).strip() if date_node is not None else 'No Date'
        author = _text(author_node).strip() if author_node is not None else 'No Author'

        results.append((title, date, author))

    return results

