def _is_missing(value):
    return value is None or (isinstance(value, float) and math.isnan(value))


def _feature_columns(rows):
    cols = []
    seen = set()
    for row in rows:
        for key in row:
            if key != 'id' and key not in seen:
                seen.add(key)
                cols.append(key)
    return cols


def merge_and_standardize(rows1, rows2):
    cols1 = _feature_columns(rows1)
    cols2 = _feature_columns(rows2)

    # Mean and population standard deviation per first-table column,
    # ignoring missing values.
    stats = {}
    for col in cols1:
        values = [row[col] for row in rows1 if not _is_missing(row.get(col))]
        if values:
            mean = sum(values) / len(values)
            var = sum((v - mean) ** 2 for v in values) / len(values)
            std = math.sqrt(var)
        else:
            mean, std = 0.0, 0.0
        stats[col] = (mean, std)

    def standardized(col, value):
        if _is_missing(value):
            return None
        mean, std = stats[col]
        if std == 0:
            return 0.0
        return (value - mean) / std

    by_id1 = {}
    for row in rows1:
        by_id1[row['id']] = row
    by_id2 = {}
    for row in rows2:
        by_id2[row['id']] = row

    merged_rows = []
    for row_id in sorted(set(by_id1) | set(by_id2)):
        r1 = by_id1.get(row_id)
        r2 = by_id2.get(row_id)
        merged = {'id': row_id}
        for col in cols1:
            merged[col] = standardized(col, r1.get(col)) if r1 is not None else None
        for col in cols2:
            merged[col] = r2.get(col) if r2 is not None else None
        merged_rows.append(merged)
    return merged_rows

