def _percentile(sorted_data, p):
    n = len(sorted_data)
    if n == 1:
        return float(sorted_data[0])
    pos = (n - 1) * p
    lower = int(pos)
    frac = pos - lower
    if lower + 1 < n:
        return float(sorted_data[lower] + frac * (sorted_data[lower + 1] - sorted_data[lower]))
    return float(sorted_data[lower])


def detect_iqr_outliers(reference, values):
    reference = list(reference)
    values = list(values)
    if not reference:
        return []
    ref_sorted = sorted(float(x) for x in reference)
    q1 = _percentile(ref_sorted, 0.25)
    q3 = _percentile(ref_sorted, 0.75)
    iqr = q3 - q1
    lower_fence = q1 - 1.5 * iqr
    upper_fence = q3 + 1.5 * iqr
    combined = [float(x) for x in reference] + [float(x) for x in values]
    return [x for x in combined if x < lower_fence or x > upper_fence]

