def seasonal_decomposition(values, period, model):
    """Classical seasonal decomposition of a series.

    values: list of numbers.
    period: seasonal period (positive integer).
    model: 'additive' or 'multiplicative'.

    Returns {'trend': [...], 'seasonal': [...], 'residual': [...]},
    each a list the same length as values with None where the centered
    moving average is undefined.
    """
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or isinstance(period, bool) or period < 1:
        raise ValueError("period must be a positive integer")
    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series has fewer than two complete periods")

    # Trend: centered moving average of length `period`.
    # Odd period: plain mean of the window centered at i.
    # Even period: 2 x period MA = half-weighted endpoints, divided by period.
    trend = [None] * n
    half = period // 2
    if period % 2 == 1:
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        for i in range(half, n - half):
            window = values[i - half:i + half + 1]
            s = sum(window[1:-1]) + 0.5 * (window[0] + window[-1])
            trend[i] = s / period

    # Detrended values, grouped by seasonal phase.
    phases = [[] for _ in range(period)]
    for i in range(n):
        if trend[i] is None:
            continue
        if model == 'additive':
            phases[i % period].append(values[i] - trend[i])
        else:
            phases[i % period].append(values[i] / trend[i])

    # Raw seasonal index per phase, then normalised to average 0 (additive)
    # or 1 (multiplicative).
    raw = [sum(ph) / len(ph) for ph in phases]
    centre = sum(raw) / period
    if model == 'additive':
        indices = [r - centre for r in raw]
    else:
        indices = [r / centre for r in raw]

    seasonal = [indices[i % period] for i in range(n)]

    residual = [None] * n
    for i in range(n):
        if trend[i] is None:
            continue
        if model == 'additive':
            residual[i] = values[i] - trend[i] - seasonal[i]
        else:
            residual[i] = values[i] / (trend[i] * seasonal[i])

    return {'trend': trend, 'seasonal': seasonal, 'residual': residual}

