def scale_table_columns(data):
    columns = list(data.keys())
    if not columns:
        return {}
    n = len(data[columns[0]])
    keep = [
        i for i in range(n)
        if all(data[c][i] is not None for c in columns)
    ]
    result = {}
    for c in columns:
        values = [data[c][i] for i in keep]
        if not values:
            result[c] = []
            continue
        lo = min(values)
        hi = max(values)
        span = hi - lo
        if span == 0:
            result[c] = [0.0] * len(values)
        else:
            result[c] = [(v - lo) / span for v in values]
    return result

