import math


def standardize_numeric_columns(data):
    """Standardize every column whose values can all be converted to float.

    Each such column is replaced by its z-scores computed with the mean and
    the population standard deviation. A constant column becomes all zeros.
    Columns containing any non-convertible value are returned unchanged.
    """
    result = {}
    for key, column in data.items():
        try:
            values = [float(v) for v in column]
        except (TypeError, ValueError):
            result[key] = column
            continue

        n = len(values)
        if n == 0:
            result[key] = list(column)
            continue

        mean = sum(values) / n
        variance = sum((v - mean) ** 2 for v in values) / n
        std = math.sqrt(variance)

        if std == 0.0:
            result[key] = [0.0] * n
        else:
            result[key] = [(v - mean) / std for v in values]
    return result

