def association_chi_square(left, right):
    """Pearson chi-square statistic of independence between the left and
    right categories over records whose ids appear in both lists.

    left and right are lists of [id, category] pairs. Returns
    (statistic, dof) with no continuity correction.
    """
    right_by_id = {}
    for record in right:
        right_by_id[record[0]] = record[1]

    counts = {}
    row_totals = {}
    col_totals = {}
    n = 0
    for record in left:
        record_id, left_cat = record[0], record[1]
        if record_id in right_by_id:
            right_cat = right_by_id[record_id]
            counts[(left_cat, right_cat)] = counts.get((left_cat, right_cat), 0) + 1
            row_totals[left_cat] = row_totals.get(left_cat, 0) + 1
            col_totals[right_cat] = col_totals.get(right_cat, 0) + 1
            n += 1

    if n == 0:
        return (0.0, 0)

    statistic = 0.0
    for left_cat, row_total in row_totals.items():
        for right_cat, col_total in col_totals.items():
            observed = counts.get((left_cat, right_cat), 0)
            expected = row_total * col_total / n
            statistic += (observed - expected) ** 2 / expected

    dof = (len(row_totals) - 1) * (len(col_totals) - 1)
    return (statistic, int(dof))

