"""Self-contained helper for computing the next business day after a date string."""

import re
from datetime import date, timedelta

_MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

# Optional trailing time/timezone, e.g. 'T09:30:00', ' 09:30', 'Z', '+02:00', 'PM'.
_TIME_RE = re.compile(
    r"(?:[T\s]\d{1,2}:\d{2}(?::\d{2})?(?:\.\d+)?"
    r"(?:\s*(?:Z|z|[+-]\d{2}:?\d{2}|[AaPp]\.?[Mm]\.?))?)?\s*$"
)

# Numeric formats with -, / or . separators.
# e.g. 2022-10-22, 10/22/2022, 22.10.2022, 2022/10/22
_NUMERIC_RE = re.compile(
    r"^\s*(\d{1,4})\s*([-/.])\s*(\d{1,2})\s*\2\s*(\d{1,4})\s*$"
)

# Textual month formats.
# e.g. "Oct 22, 2022", "October 22 2022", "22 October 2022", "22-Oct-2022"
_MONTH_FIRST_RE = re.compile(
    r"^\s*([A-Za-z]+)\.?\s*[-/,\s]\s*(\d{1,2})(?:st|nd|rd|th)?\s*[-/,\s]\s*(\d{4})\s*(?:,?\s*\d{1,2}:\d{2}(?::\d{2})?\s*(?:[AaPp]\.?[Mm]\.?)?)?\s*$"
)
_DAY_FIRST_RE = re.compile(
    r"^\s*(\d{1,2})(?:st|nd|rd|th)?\s*[-/,\s]\s*([A-Za-z]+)\.?\s*[-/,\s]\s*(\d{4})\s*(?:,?\s*\d{1,2}:\d{2}(?::\d{2})?\s*(?:[AaPp]\.?[Mm]\.?)?)?\s*$"
)


def _month_from_name(name):
    key = name.strip().lower()[:3]
    if key not in _MONTHS:
        raise ValueError(f"Unrecognized month name: {name!r}")
    return _MONTHS[key]


def _parse(date_str):
    if not isinstance(date_str, str):
        raise ValueError(f"date_str must be a string, got {type(date_str).__name__}")
    text = date_str.strip()
    if not text:
        raise ValueError("date_str is empty")
    # Drop any trailing time/timezone portion; only the date matters here.
    text = _TIME_RE.sub("", text).strip()

    m = _NUMERIC_RE.match(text)
    if m:
        a, b, c = int(m.group(1)), int(m.group(3)), int(m.group(4))
        if len(m.group(1)) == 4:
            # Year first: YYYY-MM-DD (month/day validated by date()).
            year, month, day = a, b, c
        elif len(m.group(4)) == 4:
            # Year last. If the first field exceeds 12 it must be a day
            # (DD/MM/YYYY); otherwise assume the common US MM/DD/YYYY.
            if a > 12 and b <= 12:
                day, month, year = a, b, c
            else:
                month, day, year = a, b, c
        else:
            raise ValueError(f"Unrecognized date format: {date_str!r}")
        return date(year, month, day)

    m = _MONTH_FIRST_RE.match(text)
    if m:
        return date(int(m.group(3)), _month_from_name(m.group(1)), int(m.group(2)))

    m = _DAY_FIRST_RE.match(text)
    if m:
        return date(int(m.group(3)), _month_from_name(m.group(2)), int(m.group(1)))

    raise ValueError(f"Unrecognized date format: {date_str!r}")


def next_business_day(date_str):
    """Return the first business day (Mon-Fri) strictly after ``date_str``.

    Accepts common date string formats such as '2022-10-22', '10/22/2022',
    'Oct 22, 2022' or '22 October 2022' and returns an ISO 'YYYY-MM-DD'
    string, e.g. next_business_day('Oct 28, 2022') == '2022-10-31'.
    """
    d = _parse(date_str)
    d += timedelta(days=1)
    while d.weekday() >= 5:  # 5 = Saturday, 6 = Sunday
        d += timedelta(days=1)
    return d.isoformat()

