def column_correlations(data):
    columns = list(data.keys())
    n = len(data[columns[0]]) if columns else 0

    means = {}
    for name in columns:
        col = data[name]
        means[name] = sum(col) / n if n else 0.0

    def centered(name):
        m = means[name]
        return [v - m for v in data[name]]

    centered_cols = {name: centered(name) for name in columns}

    def norm(name):
        return sum(v * v for v in centered_cols[name])

    norms = {name: norm(name) for name in columns}

    def correlation(x, y):
        denom = (norms[x] * norms[y]) ** 0.5
        if denom == 0:
            return 1.0 if x == y else 0.0
        cov = sum(a * b for a, b in zip(centered_cols[x], centered_cols[y]))
        return cov / denom

    return {x: {y: correlation(x, y) for y in columns} for x in columns}

