import csv
import io
import re

_NUMERIC_RE = re.compile(r'^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$')


def _parse_number(text):
    """Convert a string to int if it is integral, otherwise to float."""
    if re.fullmatch(r'[+-]?\d+', text):
        return int(text)
    return float(text)


def _is_numeric(text):
    return bool(_NUMERIC_RE.match(text))


def sort_csv_rows(csv_text, sort_by_column='title'):
    """Parse CSV text with a header row and return data rows sorted ascending
    by ``sort_by_column`` as a list of dicts. Columns whose values are all
    numeric are converted to numbers (int when integral, else float) and
    sorted numerically; other columns remain strings."""
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]
    if not rows:
        return []

    header = rows[0]
    data = rows[1:]

    # Normalize row lengths to the header.
    normalized = []
    for row in data:
        if len(row) < len(header):
            row = row + [''] * (len(header) - len(row))
        elif len(row) > len(header):
            row = row[:len(header)]
        normalized.append(row)

    # A column is numeric only if every data value in it is numeric.
    numeric_cols = set()
    for col_idx, name in enumerate(header):
        values = [row[col_idx] for row in normalized]
        if values and all(_is_numeric(v) for v in values):
            numeric_cols.add(name)

    result = []
    for row in normalized:
        record = {}
        for name, value in zip(header, row):
            record[name] = _parse_number(value) if name in numeric_cols else value
        result.append(record)

    result.sort(key=lambda record: record[sort_by_column])
    return result

