def describe_filled_columns(columns):
    result = {}
    for name, values in columns.items():
        present = [v for v in values if v is not None]
        if present:
            fill = sum(present) / len(present)
        else:
            fill = 0.0
        filled = [fill if v is None else v for v in values]
        n = len(filled)
        s = sorted(filled)
        count = float(n)
        mean = sum(filled) / n if n else 0.0
        if n > 1:
            var = sum((x - mean) ** 2 for x in filled) / (n - 1)
            std = var ** 0.5
        else:
            std = float('nan')

        def quantile(p):
            if n == 0:
                return 0.0
            if n == 1:
                return float(s[0])
            pos = p * (n - 1)
            lo = int(pos)
            hi = min(lo + 1, n - 1)
            frac = pos - lo
            return s[lo] + frac * (s[hi] - s[lo])

        result[name] = {
            'count': count,
            'mean': mean,
            'std': std,
            'min': float(s[0]) if s else 0.0,
            '25%': quantile(0.25),
            '50%': quantile(0.50),
            '75%': quantile(0.75),
            'max': float(s[-1]) if s else 0.0,
        }
    return result

