def format_sorted_dict_table(my_dict):
    items = sorted(my_dict.items())

    key_width = max([len("Key")] + [len(str(k)) for k, _ in items])
    value_width = max([len("Value")] + [len(str(v)) for _, v in items])

    separator = (
        "+" + "-" * (key_width + 2)
        + "+" + "-" * (value_width + 2) + "+"
    )

    def format_row(key, value):
        return (
            "| " + str(key).center(key_width)
            + " | " + str(value).center(value_width) + " |"
        )

    lines = [separator, format_row("Key", "Value"), separator]
    lines.extend(format_row(k, v) for k, v in items)
    lines.append(separator)

    return "\n".join(lines)

