import csv
import io


def encode_csv_column(csv_text, column_name):
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        raise ValueError(f"Column not found: {column_name!r}")

    header = rows[0]
    try:
        col_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column not found: {column_name!r}")

    cleaned = []
    for row in rows[1:]:
        if not row:
            continue
        value = row[col_index] if col_index < len(row) else ""
        value = value.replace("\r\n", "<br>").replace("\n", "<br>").replace("\r", "<br>")
        cleaned.append(value)

    classes = sorted(set(cleaned))
    index = {value: i for i, value in enumerate(classes)}
    codes = [index[value] for value in cleaned]
    return classes, codes

