import numbers


def cumulative_column_sums(data):
    """Return running sums down each numeric column of a column-oriented table.

    ``data`` maps column names to equal-length lists. Columns whose values
    are not all numbers (booleans excluded) are ignored. Raises ValueError
    if the table has no rows or contains no numeric columns.
    """
    if not data:
        raise ValueError("table has no rows")

    row_count = len(next(iter(data.values())))
    if row_count == 0:
        raise ValueError("table has no rows")

    result = {}
    for name, values in data.items():
        if not all(
            isinstance(v, numbers.Number) and not isinstance(v, bool)
            for v in values
        ):
            continue
        cumulative = []
        running = 0
        for v in values:
            running += v
            cumulative.append(running)
        result[name] = cumulative

    if not result:
        raise ValueError("table has no numeric columns")

    return result

