import xml.etree.ElementTree as ET


def _element_to_value(elem):
    children = list(elem)
    attrs = elem.attrib

    if not attrs and not children:
        text = (elem.text or '').strip()
        return text if text else None

    result = {}
    for name, value in attrs.items():
        result['@' + name] = value

    parts = []
    if elem.text:
        parts.append(elem.text)
    for child in children:
        if child.tail:
            parts.append(child.tail)
    text = ''.join(parts).strip()
    if text:
        result['#text'] = text

    grouped = {}
    for child in children:
        grouped.setdefault(child.tag, []).append(_element_to_value(child))
    for tag, values in grouped.items():
        result[tag] = values[0] if len(values) == 1 else values

    return result


def xml_to_dict(xml):
    if not isinstance(xml, (str, bytes)):
        raise ValueError('xml must be a string')
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError('malformed XML: %s' % exc) from exc
    return {root.tag: _element_to_value(root)}

