def row_averages_and_correlations(data):
    """Compute the mean of each row and the pairwise Pearson correlation
    matrix of the columns of a rectangular table.

    Returns (averages, corr) where averages[i] is the mean of row i and
    corr[i][j] is the Pearson correlation between column i and column j.

    Raises ValueError if data is not a rectangular list of rows of numbers.
    """
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")
    for row in data:
        if not isinstance(row, list):
            raise ValueError("each row must be a list of numbers")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("each entry must be a number")

    if len(data) > 0:
        width = len(data[0])
        if width == 0:
            raise ValueError("rows must contain at least one number")
        for row in data:
            if len(row) != width:
                raise ValueError("data must be rectangular")

    n = len(data)
    if n == 0:
        return ([], [])

    averages = [math.fsum(row) / len(row) for row in data]

    width = len(data[0])
    col_means = [
        math.fsum(data[r][c] for r in range(n)) / n for c in range(width)
    ]
    centered = [
        [data[r][c] - col_means[c] for c in range(width)] for r in range(n)
    ]
