from datetime import date, datetime, timedelta


def _parse_day(value):
    """Extract the calendar day from an ISO date or datetime string."""
    if not isinstance(value, str):
        raise ValueError(f"invalid date value: {value!r}")
    text = value.strip()
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(text).date()
    except ValueError:
        # Plain 'YYYY-MM-DD' also parses via fromisoformat, but fall back
        # to date.fromisoformat for older interpreters just in case.
        return date.fromisoformat(text)


def daily_sales_totals(dates, sales):
    """Return total sales per calendar day as a list of (day, total) tuples.

    Covers every day from the earliest to the latest date in chronological
    order; days with no sales total 0. Raises ValueError if there are no
    records.
    """
    if len(dates) != len(sales):
        raise ValueError("dates and sales must have the same length")
    if len(dates) == 0:
        raise ValueError("no records")

    totals = {}
    for value, amount in zip(dates, sales):
        day = _parse_day(value)
        totals[day] = totals.get(day, 0) + amount

    first = min(totals)
    last = max(totals)

    result = []
    day = first
    while day <= last:
        result.append((day.isoformat(), totals.get(day, 0)))
        day += timedelta(days=1)
    return result

