import math


def standardized_tensor_product(P, T):
    """Compute the standardized table of P times each slice of T.

    P is an m x k matrix and T is a k x n x p tensor. Row j of the result
    table is P @ T[:, j, :] (an m x p matrix) flattened row by row. Each
    column of the n-row table is then standardized to zero mean and unit
    population variance; a zero-variance column becomes all zeros.
    """
    if not P or not T or not P[0] or not T[0] or not T[0][0]:
        raise ValueError("P and T must be non-empty")

    m = len(P)
    k = len(P[0])
    if k != len(T):
        raise ValueError(
            "P has %d columns but T's first dimension is %d" % (k, len(T))
        )

    n = len(T[0])
    p = len(T[0][0])
    width = m * p

    table = []
    for j in range(n):
        row = [0.0] * width
        for i in range(m):
            Pi = P[i]
            base = i * p
            for a in range(k):
                pa = Pi[a]
                Ta = T[a][j]
                for b in range(p):
                    row[base + b] += pa * Ta[b]
        table.append(row)

    for c in range(width):
        col = [table[j][c] for j in range(n)]
        if min(col) == max(col):
            for j in range(n):
                table[j][c] = 0.0
            continue
        mean = sum(col) / n
        var = sum((v - mean) ** 2 for v in col) / n
        std = math.sqrt(var)
        if std == 0.0:
            for j in range(n):
                table[j][c] = 0.0
        else:
            for j in range(n):
                # round to 15 decimal places; "+ 0.0" normalizes -0.0 to 0.0
                table[j][c] = round((table[j][c] - mean) / std, 15) + 0.0

    return table

