def quartiles_of_string_groups(groups):
    """Return (p25, p50, p75) of all integers in `groups`, as floats.

    `groups` is a tuple of tuples of integer-valued strings. All values are
    pooled into one collection. Percentiles use linear interpolation between
    closest ranks (the numpy default), so p50 is the median.
    """
    values = sorted(int(s) for group in groups for s in group)
    n = len(values)
    if n == 0:
        return (float("nan"), float("nan"), float("nan"))

    def percentile(q):
        rank = (n - 1) * q
        lower = int(rank)
        frac = rank - lower
        if lower + 1 >= n:
            return float(values[lower])
        return float(values[lower] + frac * (values[lower + 1] - values[lower]))

    return (percentile(0.25), percentile(0.50), percentile(0.75))

