def scale_by_group_with_histogram(ids, ages, incomes):
    n = len(ids)
    if n == 0:
        raise ValueError("no rows")

    groups = {}
    for i in range(n):
        groups.setdefault(ids[i], []).append(i)

    scaled = [[0.0, 0.0] for _ in range(n)]
    for idxs in groups.values():
        for values, col in ((ages, 0), (incomes, 1)):
            vals = [values[i] for i in idxs]
            mn = min(vals)
            mx = max(vals)
            rng = mx - mn
            if rng == 0:
                for i in idxs:
                    scaled[i][col] = 0.0
            else:
                inv = 1.0 / rng
                for i, v in zip(idxs, vals):
                    scaled[i][col] = v * inv - mn * inv

    counts = [0] * 10
    for row in scaled:
        b = int(row[1] * 10)
        if b > 9:
            b = 9
        counts[b] += 1

    return scaled, counts

