import io
import re

_NUM_RE = re.compile(r"^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$")


def _is_number(cell):
    return bool(_NUM_RE.match(cell.strip()))


def fill_missing_with_column_mean(csv_text):
    """Parse CSV text into {column: [values]}.

    Numeric columns (all non-empty cells parse as numbers) yield floats;
    empty cells are replaced by the column mean. Other columns yield
    strings with empty cells as None. A column with no values at all
    becomes all None. Empty input gives an empty dict.
    """
    if not csv_text or csv_text.strip() == "":
        return {}

    text = csv_text.lstrip("\ufeff")
    rows = list(csv.reader(io.StringIO(text)))
    if not rows:
        return {}

    header = rows[0]
    n = len(header)
    data_rows = rows[1:]

    # Normalize row lengths to the header width.
    cols = [[] for _ in range(n)]
    for row in data_rows:
        if len(row) < n:
            row = row + [""] * (n - len(row))
        for i in range(n):
            cols[i].append(row[i])

    result = {}
    for name, values in zip(header, cols):
        present = [v for v in values if v.strip() != ""]
        if present and all(_is_number(v) for v in present):
            nums = [float(v) for v in present]
            mean = sum(nums) / len(nums)
            result[name] = [float(v) if v.strip() != "" else mean for v in values]
        else:
            result[name] = [v if v.strip() != "" else None for v in values]
    return result

