def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists of values")

    def replace_value(value):
        try:
            if value in replacements:
                return replacements[value]
        except TypeError:
            pass
        return value

    columns = {}
    for name, values in data.items():
        replaced = [replace_value(v) for v in values]
        if any(isinstance(v, str) for v in replaced):
            distinct = sorted(set(replaced))
            codes = {value: i for i, value in enumerate(distinct)}
            replaced = [codes[v] for v in replaced]
        columns[name] = [float(v) for v in replaced]

    result = {}
    for name, values in columns.items():
        n = len(values)
        if n == 0:
            result[name] = []
