        total = sum(values)
        sumsq = sum(v * v for v in values)
        denom = math.sqrt((n * sumsq - total * total) * n / (n - 1)) if n > 1 else 0.0
        if denom == 0.0:
            result[name] = [0.0] * n
        else:
            result[name] = [(n * v - total) / denom for v in values]

    return result

