    if not vocab:
        return ([], [])

    n = len(docs)
    index = {w: i for i, w in enumerate(vocab)}
    df = [0] * len(vocab)
    counts = []
    for doc in docs:
        c = [0] * len(vocab)
        for w in doc:
            c[index[w]] += 1
        counts.append(c)
        for i, v in enumerate(c):
            if v:
                df[i] += 1

    idf = [math.log((1 + n) / (1 + d)) + 1 for d in df]

    rows = []
    for c in counts:
        vec = [c[i] * idf[i] for i in range(len(vocab))]
        norm = math.sqrt(sum(v * v for v in vec))
        if norm > 0:
            vec = [v / norm for v in vec]
        rows.append(vec)

    return (rows, vocab)

