def correlation_without_column(data, column):
    if not isinstance(data, dict):
        return None

    numeric = {}
    for name, values in data.items():
        if name == column:
            continue
        if not isinstance(values, (list, tuple)):
            continue
        if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in values):
            numeric[name] = list(values)

    if not numeric:
        return None

    n = len(next(iter(numeric.values())))
    if n == 0:
        return None

    sums = {name: sum(vals) for name, vals in numeric.items()}
    sq_sums = {name: sum(v * v for v in vals) for name, vals in numeric.items()}

    names = list(numeric.keys())
    result = {}
    for x in names:
        row = {}
        for y in names:
            if x == y:
                row[y] = 1.0
            else:
                num = n * sum(a * b for a, b in zip(numeric[x], numeric[y])) - sums[x] * sums[y]
                den_x = n * sq_sums[x] - sums[x] * sums[x]
                den_y = n * sq_sums[y] - sums[y] * sums[y]
                denom = (den_x * den_y) ** 0.5
                row[y] = num / denom if denom != 0 else 0.0
        result[x] = row

    return result

