"""Self-contained solution: per-column 10-bin histograms for numeric columns."""

import numbers


def _is_number(value):
    """True for real numeric values (bool is not treated as a number)."""
    return isinstance(value, numbers.Real) and not isinstance(value, bool)


def column_histograms(table):
    """Compute 10 equal-width bin histograms for every numeric column.

    Args:
        table: dict mapping column names to equal-length lists of values.

    Returns:
        dict mapping each numeric column name (in table column order) to a
        list of 10 bin counts. Bins span the column's min to max; the last
        bin includes the max.

    Raises:
        ValueError: if table is not a non-empty dict or has no numeric
            columns.
    """
    if not isinstance(table, dict) or len(table) == 0:
        raise ValueError("table must be a non-empty dict")

    histograms = {}
    for name, column in table.items():
        try:
            values = list(column)
        except TypeError:
            continue
        if not values:
            continue
        if not all(_is_number(v) for v in values):
            continue

        lo = min(values)
        hi = max(values)
        width = (hi - lo) / 10
        counts = [0] * 10
        if width == 0:
            # All values equal the max, which belongs to the last bin.
            counts[9] = len(values)
        else:
            for v in values:
                idx = int((v - lo) / width)
                if idx < 0:
                    idx = 0
                elif idx > 9:
                    idx = 9
                counts[idx] += 1
        histograms[name] = counts

    if not histograms:
        raise ValueError("table has no numeric columns")
    return histograms

