import csv
import io
import re
from datetime import date

_MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12,
}

# Numeric dates with a 4-digit year first: 2020-01-15, 2020/01/15, 2020.01.15
_YEAR_FIRST = re.compile(
    r'^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?:[T ].*)?$'
)
# Numeric dates with the year last: 01/15/2020, 15-01-2020, 1/5/20
_YEAR_LAST = re.compile(
    r'^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})(?:[T ].*)?$'
)
# Month name first: January 15, 2020 / Jan 15 2020 / Jan-15-2020
_MONTH_FIRST = re.compile(
    r'^([A-Za-z]+)\.?[-/ ](\d{1,2})(?:st|nd|rd|th)?[-/, ]+(\d{4})(?:[T ].*)?$'
)
# Day first with month name: 15 Jan 2020 / 15-Jan-2020 / 15 January, 2020
_DAY_FIRST = re.compile(
    r'^(\d{1,2})(?:st|nd|rd|th)?[-/ ]+([A-Za-z]+)\.?[-/, ]+(\d{4})(?:[T ].*)?$'
)
# Year first with month name: 2020 January 15
_YEAR_MONTH_DAY = re.compile(
    r'^(\d{4})[-/ ]+([A-Za-z]+)\.?[-/ ]+(\d{1,2})(?:st|nd|rd|th)?(?:[T ].*)?$'
)


