    key = name.lower()
    if key in _MONTHS:
        return _MONTHS[key]
    if len(key) >= 3 and key[:3] in _MONTHS:
        # Accept full names and 3-letter abbreviations (e.g. "sept").
        return _MONTHS[key[:3]]
    return None


def _to_date(year, month, day):
    try:
        return date(year, month, day)
    except ValueError:
        return None


def _parse_date(value):
    """Parse a date string in any common form; return a date or None."""
    text = ' '.join(value.strip().split())
    if not text:
        return None

    m = _YEAR_FIRST.match(text)
    if m:
        return _to_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _YEAR_LAST.match(text)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if len(m.group(3)) == 2:
            # Two-digit year, same pivot as strptime's %y.
            y += 2000 if y < 69 else 1900
        if a > 12 >= b:
            # Day-first: 15/01/2020
            a, b = b, a
        # Otherwise assume month-first (US style): 01/15/2020
        return _to_date(y, a, b)

    m = _MONTH_FIRST.match(text)
    if m:
        month = _month_number(m.group(1))
        if month is not None:
            return _to_date(int(m.group(3)), month, int(m.group(2)))

    m = _DAY_FIRST.match(text)
    if m:
        month = _month_number(m.group(2))
        if month is not None:
            return _to_date(int(m.group(3)), month, int(m.group(1)))

    m = _YEAR_MONTH_DAY.match(text)
    if m:
        month = _month_number(m.group(2))
        if month is not None:
            return _to_date(int(m.group(1)), month, int(m.group(3)))

    return None


def count_dates_by_year(csv_text, date_column):
    """Return {year: count} for the dates in `date_column` of `csv_text`.

    Raises ValueError if the column is missing or any value is not a
    valid date.
    """
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('CSV text is empty')

    try:
        col_index = header.index(date_column)
    except ValueError:
        raise ValueError(
            'column %r not found in header %r' % (date_column, header)
        )

    counts = {}
    for row in reader:
        if not row:
            continue
        value = row[col_index] if col_index < len(row) else ''
        parsed = _parse_date(value)
        if parsed is None:
            raise ValueError('not a valid date: %r' % value)
        counts[parsed.year] = counts.get(parsed.year, 0) + 1
    return counts

