"""Parse an XML string into nested Python dicts."""

import xml.etree.ElementTree as ET


def _element_text(elem):
    """Concatenate all text directly inside an element (its own text plus
    the tails of its children). Returns None if there is no meaningful text."""
    parts = []
    if elem.text:
        parts.append(elem.text)
    for child in elem:
        if child.tail:
            parts.append(child.tail)
    text = ''.join(parts)
    if text.strip():
        return text
    return None


def _to_value(elem):
    """Convert an Element into its dict/string/None representation."""
    children = list(elem)
    attrib = elem.attrib
    text = _element_text(elem)

    if not children and not attrib:
        # Only text (or nothing at all).
        return text if text is not None else None

    result = {}
    for name, value in attrib.items():
        result['@' + name] = value
    for child in children:
        value = _to_value(child)
        if child.tag in result:
            existing = result[child.tag]
            if isinstance(existing, list):
                existing.append(value)
            else:
                result[child.tag] = [existing, value]
        else:
            result[child.tag] = value
    if text is not None:
        result['#text'] = text
    return result


def xml_to_dict(s):
    """Parse an XML string and return it as nested Python dicts.

    The result maps the root tag to its content. An element containing only
    text becomes that text string; an empty element becomes None. Otherwise an
    element becomes a dict with attributes under '@name', children under their
    tag (repeated tags become lists in document order), and any text under
    '#text'. Raises ValueError if the input is empty, only whitespace, or not
    well-formed XML.
    """
    if not isinstance(s, str) or not s.strip():
        raise ValueError('input is empty or only whitespace')
    try:
        root = ET.fromstring(s)
    except ET.ParseError as exc:
        raise ValueError('invalid XML: %s' % exc) from exc
    return {root.tag: _to_value(root)}

