    year, month, day = (int(part) for part in start_date.split('-'))
    start = date(year, month, day)

    dates = []
    y, m = year, month
    while len(dates) < periods:
        candidate = _second_friday(y, m)
        if candidate >= start:
            dates.append(candidate)
        m += 1
        if m > 12:
            m = 1
            y += 1

    report = []
    index = 0
    for d in dates:
        date_str = d.isoformat()
        for category in categories:
            report.append((date_str, category, sales[index]))
            index += 1
    return report

