from html.parser import HTMLParser


class _TableRecordsParser(HTMLParser):
    """Stream-parse a document and collect the rows of the first table
    whose ``id`` attribute matches the requested id.

    ``rows`` ends up as a list of rows, each row a list of cell texts
    (tags removed, entities decoded, surrounding whitespace stripped).
    Rows belonging to tables nested inside the target table are ignored.
    """

    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self._table_id = table_id
        self.found = False
        self.rows = []
        self._in_target = False
        self._nested_tables = 0
        self._in_row = False
        self._in_cell = False
        self._cell_chunks = None
        self._skip_depth = 0
        self._done = False

    def handle_starttag(self, tag, attrs):
        if self._done:
            return
        if tag == 'table':
            if not self._in_target:
                if dict(attrs).get('id') == self._table_id:
                    self._in_target = True
                    self.found = True
                    self._nested_tables = 0
            else:
                self._nested_tables += 1
            return
        if not self._in_target or self._nested_tables > 0:
            return
        if tag in ('script', 'style'):
            self._skip_depth += 1
        elif tag == 'tr':
            self._in_row = True
            self.rows.append([])
        elif tag in ('td', 'th') and self._in_row:
            self._in_cell = True
            self._cell_chunks = []

    def handle_endtag(self, tag):
        if self._done:
            return
        if tag == 'table':
            if self._in_target:
                if self._nested_tables > 0:
                    self._nested_tables -= 1
                else:
                    self._in_target = False
                    self._done = True
            return
        if not self._in_target or self._nested_tables > 0:
            return
        if tag in ('script', 'style'):
            if self._skip_depth > 0:
                self._skip_depth -= 1
        elif tag in ('td', 'th'):
            if self._in_cell:
                self._in_cell = False
                if self.rows:
                    self.rows[-1].append(''.join(self._cell_chunks).strip())
                self._cell_chunks = None
        elif tag == 'tr':
            self._in_row = False

    def handle_data(self, data):
        if (self._in_target and self._in_cell
                and self._skip_depth == 0 and self._cell_chunks is not None):
            self._cell_chunks.append(data)


def html_table_records(html, table_id):
    """Return the data records of the table with the given id.

    The first row of the table supplies the column headers; every later
    row becomes one dict mapping each header to that row's cell text.
    Raises ValueError if no table in ``html`` has that id.
    """
    parser = _TableRecordsParser(table_id)
    parser.feed(html)
    parser.close()
    if not parser.found:
        raise ValueError('no table with id %r' % (table_id,))
    rows = parser.rows
    if not rows:
        return []
    headers = rows[0]
    return [dict(zip(headers, row)) for row in rows[1:]]

