def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = {
        name: [float(mapping.get(value, value)) for value in values]
        for name, values in data.items()
    }

    names = list(columns.keys())
    n = len(next(iter(columns.values()))) if columns else 0

    means = {
        name: sum(values) / n if n else 0.0
        for name, values in columns.items()
    }

    def centered(name):
        mean = means[name]
        return [v - mean for v in columns[name]]

    def variance(name):
        c = centered(name)
        return sum(v * v for v in c)

    variances = {name: variance(name) for name in names}

    def correlation(a, b):
        if a == b:
            return 1.0
        va = variances[a]
        vb = variances[b]
        if va == 0.0 or vb == 0.0:
            return 0.0
        ca = centered(a)
        cb = centered(b)
        cov = sum(x * y for x, y in zip(ca, cb))
        return cov / (va * vb) ** 0.5

    return {
        a: {b: correlation(a, b) for b in names}
        for a in names
    }

