import math


def score_grade_correlation(scores, grades):
    """Pearson correlation between numeric scores and ordinal-encoded grades.

    Each grade label is encoded as its index in the sorted list of distinct
    labels. Returns None when fewer than two entries are given. Raises
    ValueError on length mismatch or a non-numeric score.
    """
    if len(scores) != len(grades):
        raise ValueError("scores and grades must have the same length")

    if len(scores) < 2:
        return None

    values = []
    for s in scores:
        try:
            v = float(s)
        except (TypeError, ValueError):
            raise ValueError(f"invalid score: {s!r}") from None
        if not math.isfinite(v):
            raise ValueError(f"invalid score: {s!r}")
        values.append(v)

    distinct = sorted(set(grades))
    index = {label: i for i, label in enumerate(distinct)}
    encoded = [index[g] for g in grades]

    n = len(values)
    mean_x = sum(values) / n
    mean_y = sum(encoded) / n

    sxy = sum((x - mean_x) * (y - mean_y) for x, y in zip(values, encoded))
    sxx = sum((x - mean_x) ** 2 for x in values)
    syy = sum((y - mean_y) ** 2 for y in encoded)

    if sxx == 0 or syy == 0:
        return 0.0

    return sxy / (math.sqrt(sxx) * math.sqrt(syy))

