import statistics


def csv_mean_median(csv_text):
    """Return (mean, median) of the numeric values in a single-column CSV.

    The first row is treated as a header and skipped. Non-numeric values
    and blank lines are ignored. Returns (None, None) if there are no
    numeric values.
    """
    if not csv_text or not csv_text.strip():
        return (None, None)

    values = []
    reader = csv.reader(io.StringIO(csv_text))
    for i, row in enumerate(reader):
        if i == 0:
            continue  # header row
        if not row:
            continue  # blank line
        cell = row[0].strip()
        if not cell:
            continue
        try:
            values.append(float(cell))
        except ValueError:
            continue

    if not values:
        return (None, None)

    mean = sum(values) / len(values)
    median = statistics.median(values)
    return (float(mean), float(median))

