def cluster_centroids(points, k):
    """Cluster 2D points into k clusters with k-means (Lloyd's algorithm).

    Returns the centroids as a list of (x, y) float tuples sorted ascending.
    """
    pts = [(float(p[0]), float(p[1])) for p in points]
    if not pts or k <= 0:
        return []
    k = min(k, len(pts))

    # Deterministic initialization: first k points as initial centroids.
    centroids = [list(p) for p in pts[:k]]

    for _ in range(300):
        # Assign each point to the nearest centroid (squared distance).
        clusters = [[] for _ in range(k)]
        for p in pts:
            best = 0
            best_d = (p[0] - centroids[0][0]) ** 2 + (p[1] - centroids[0][1]) ** 2
            for i in range(1, k):
                d = (p[0] - centroids[i][0]) ** 2 + (p[1] - centroids[i][1]) ** 2
                if d < best_d:
                    best_d = d
                    best = i
            clusters[best].append(p)

        # Update centroids; keep the old centroid if a cluster is empty.
        new_centroids = []
        for i in range(k):
            if clusters[i]:
                n = len(clusters[i])
                new_centroids.append([
                    sum(p[0] for p in clusters[i]) / n,
                    sum(p[1] for p in clusters[i]) / n,
                ])
            else:
                new_centroids.append(list(centroids[i]))

        if new_centroids == centroids:
            break
        centroids = new_centroids

    return sorted((c[0], c[1]) for c in centroids)

