import ast
from html.parser import HTMLParser


class _ScriptBodyCollector(HTMLParser):
    """Collects the raw text content of every <script> element, in order."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.bodies = []
        self._in_script = False
        self._chunks = []

    def handle_starttag(self, tag, attrs):
        if tag == "script":
            self._in_script = True
            self._chunks = []

    def handle_endtag(self, tag):
        if tag == "script" and self._in_script:
            self.bodies.append("".join(self._chunks))
            self._in_script = False
            self._chunks = []

    def handle_data(self, data):
        if self._in_script:
            self._chunks.append(data)

    def close(self):
        super().close()
        # Flush content of an unterminated <script> at end of input.
        if self._in_script:
            self.bodies.append("".join(self._chunks))
            self._in_script = False
            self._chunks = []


def extract_script_dicts(html):
    """Return the dicts readable as Python literals from <script> bodies.

    Script bodies that are not a valid dict literal are skipped; the
    dicts that are found are returned in document order.
    """
    parser = _ScriptBodyCollector()
    parser.feed(html)
    parser.close()

    dicts = []
    for body in parser.bodies:
        try:
            value = ast.literal_eval(body.strip())
        except Exception:
            continue
        if isinstance(value, dict):
            dicts.append(value)
    return dicts

