import re
from datetime import date, timedelta

_WEEKDAYS = {
    'MON': 0,
    'TUE': 1,
    'WED': 2,
    'THU': 3,
    'FRI': 4,
    'SAT': 5,
    'SUN': 6,
}

_NTH_WEEKDAY_RE = re.compile(r'^([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _parse_start_date(start_date):
    if not isinstance(start_date, str) or not _DATE_RE.match(start_date):
        raise ValueError('invalid start date: %r' % (start_date,))
    try:
        return date.fromisoformat(start_date)
    except ValueError:
        raise ValueError('invalid start date: %r' % (start_date,))


def _last_day_of_month(year, month):
    if month == 12:
        return date(year, 12, 31)
    return date(year, month + 1, 1) - timedelta(days=1)


def _nth_weekday_of_month(year, month, week, weekday):
    first = date(year, month, 1)
    offset = (weekday - first.weekday()) % 7
    result = first + timedelta(days=offset + 7 * (week - 1))
    if result.month != month:
        return None
    return result


def _matching_dates(start, freq):
    """Yield matching dates on or after start, in order, indefinitely."""
    if freq == 'month-end':
        year, month = start.year, start.month
        while True:
            d = _last_day_of_month(year, month)
            if d >= start:
                yield d
            month += 1
            if month == 13:
                month = 1
                year += 1
    elif freq == 'quarter-end':
        year, month = start.year, start.month
        while True:
            # advance to the next quarter-end month (Mar/Jun/Sep/Dec)
            while month not in (3, 6, 9, 12):
                month += 1
                if month == 13:
                    month = 1
                    year += 1
            d = _last_day_of_month(year, month)
            if d >= start:
                yield d
            month += 3
            if month > 12:
                month -= 12
                year += 1
    else:
        m = _NTH_WEEKDAY_RE.match(freq) if isinstance(freq, str) else None
        if not m:
            raise ValueError('invalid freq: %r' % (freq,))
        week = int(m.group(1))
        weekday = _WEEKDAYS[m.group(2)]
        year, month = start.year, start.month
        while True:
            d = _nth_weekday_of_month(year, month, week, weekday)
            if d is not None and d >= start:
                yield d
            month += 1
            if month == 13:
                month = 1
                year += 1


def forecast_schedule(start_date, freq, sales):
    start = _parse_start_date(start_date)
    sales = list(sales)
    dates = _matching_dates(start, freq)
    return [(next(dates).isoformat(), sale) for sale in sales]

