        raise ValueError("records must be a non-empty list of dicts")

    required = ("Name", "Country", "Score")
    seen_names = set()
    scores_by_country = {}

    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in required):
            raise ValueError(
