            )
        name = record["Name"]
        if name in seen_names:
            continue
        seen_names.add(name)
        scores_by_country.setdefault(record["Country"], []).append(float(record["Score"]))

    def quantile(sorted_values, p):
        n = len(sorted_values)
        pos = (n - 1) * p
        lower = int(pos)
        upper = min(lower + 1, n - 1)
        fraction = pos - lower
        return sorted_values[lower] + fraction * (sorted_values[upper] - sorted_values[lower])

    summary = {}
    for country, scores in scores_by_country.items():
        ordered = sorted(scores)
        summary[country] = [
            ordered[0],
            quantile(ordered, 0.25),
            quantile(ordered, 0.50),
            quantile(ordered, 0.75),
            ordered[-1],
        ]
    return summary

