"""Sample covariance matrix for a column-oriented table."""

import numbers


def column_covariance(columns):
    """Return the sample covariance matrix (normalised by n - 1) of a table.

    ``columns`` maps column names to equal-length lists of numbers with at
    least two rows. The result is a nested dict where ``result[a][b]`` is the
    sample covariance between columns ``a`` and ``b``.

    Raises:
        ValueError: if the table has no columns or no rows.
        TypeError: if any column contains a non-numeric value.
    """
    if not columns:
        raise ValueError("table has no columns")

    names = list(columns.keys())
    cols = {}
    n = None
    for name in names:
        values = list(columns[name])
        for value in values:
            if not isinstance(value, numbers.Real):
                raise TypeError(
                    "column %r contains a non-numeric value: %r" % (name, value)
                )
        if n is None:
            n = len(values)
        elif len(values) != n:
            raise ValueError("columns must all have the same length")
        cols[name] = values

    if n < 2:
        raise ValueError("table must have at least two rows")

    means = {name: sum(cols[name]) / n for name in names}

    result = {}
    for a in names:
        row = {}
        ca = cols[a]
        ma = means[a]
        for b in names:
            cb = cols[b]
            mb = means[b]
            row[b] = sum((x - ma) * (y - mb) for x, y in zip(ca, cb)) / (n - 1)
        result[a] = row
    return result

