import math


def summarize_from_user(records):
    values = []
    for record in records:
        if "from_user" not in record:
            continue
        value = record["from_user"]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("from_user value is not numeric: %r" % (value,))
        values.append(float(value))

    if not values:
        return {"mean": None, "median": None, "min": None, "max": None, "std": None}

    n = len(values)
    mean = sum(values) / n
    ordered = sorted(values)
    if n % 2 == 1:
        median = ordered[n // 2]
    else:
        median = (ordered[n // 2 - 1] + ordered[n // 2]) / 2
    variance = sum((x - mean) ** 2 for x in values) / n
    std = math.sqrt(variance)

    return {"mean": mean, "median": median, "min": min(values), "max": max(values), "std": std}

