"""K-means clustering of points, returning clusters as lists of point indices."""

import random


def _squared_distance(a, b):
    return sum((x - y) * (x - y) for x, y in zip(a, b))


def _mean(points):
    n = len(points)
    dim = len(points[0])
    return [sum(p[d] for p in points) / n for d in range(dim)]


def _initial_centroids(points, k, start):
    """Deterministic farthest-first traversal beginning at points[start]:
    repeatedly add the point farthest from all chosen centroids."""
    centroids = [points[start]]
    while len(centroids) < k:
        best_index = None
        best_dist = -1.0
        for i, p in enumerate(points):
            d = min(_squared_distance(p, c) for c in centroids)
            if d > best_dist:
                best_dist = d
                best_index = i
        if best_dist <= 0.0:
            # All points coincide with chosen centroids; fall back to the
            # next unused index so every centroid is a distinct point.
            used = {points.index(c) for c in centroids}
            for i in range(len(points)):
                if i not in used:
                    best_index = i
                    break
        centroids.append(points[best_index])
    return centroids


def _kmeans_pp_centroids(points, k, rng):
    """k-means++ seeding with the given random generator."""
    n = len(points)
    centroids = [points[rng.randrange(n)]]
    while len(centroids) < k:
        weights = [
            min(_squared_distance(p, c) for c in centroids) for p in points
        ]
        total = sum(weights)
        if total <= 0.0:
            # All points coincide with chosen centroids; pick any unused one.
            for i in range(n):
                if points[i] not in centroids:
                    centroids.append(points[i])
                    break
            else:
                centroids.append(points[len(centroids) % n])
            continue
        threshold = rng.random() * total
        cumulative = 0.0
        chosen = n - 1
        for i, w in enumerate(weights):
            cumulative += w
            if cumulative >= threshold:
                chosen = i
                break
        centroids.append(points[chosen])
    return centroids


def _lloyd(points, k, init):
    """Run Lloyd's algorithm from the given initial centroids.

    Returns (assignments, inertia) where inertia is the sum of squared
    distances from each point to its assigned centroid.
    """
    n = len(points)
    centroids = [list(c) for c in init]
    assignments = [-1] * n

    for _ in range(300):
        new_assignments = []
        for p in points:
            best_c = 0
            best_d = _squared_distance(p, centroids[0])
            for c in range(1, k):
                d = _squared_distance(p, centroids[c])
                if d < best_d:
                    best_d = d
                    best_c = c
            new_assignments.append(best_c)

        if new_assignments == assignments:
            break
        assignments = new_assignments

        members = [[] for _ in range(k)]
        for i, c in enumerate(assignments):
            members[c].append(points[i])
        for c in range(k):
            if members[c]:
                centroids[c] = _mean(members[c])
            else:
                # Empty cluster: re-seed with the point farthest from its
                # assigned centroid.
                farthest = max(
                    range(n),
                    key=lambda i: _squared_distance(
                        points[i], centroids[assignments[i]]
                    ),
                )
                centroids[c] = list(points[farthest])

    inertia = sum(
        _squared_distance(points[i], centroids[assignments[i]]) for i in range(n)
    )
    return assignments, inertia


def cluster_point_indices(points, n_clusters):
    """Group points into n_clusters clusters with k-means.

    Returns a list of clusters; each cluster is a list of point indices in
    ascending order, and clusters are ordered by their smallest index.
    """
    n = len(points)
    if n == 0 or n_clusters <= 0:
        return []
    k = min(n_clusters, n)

    # Deterministic multi-start: farthest-first seeds plus k-means++ seeds
    # with fixed RNG seeds, keeping the run with the lowest inertia.
    n_restarts = 30 if n <= 500 else 10
    inits = [_initial_centroids(points, k, start) for start in range(min(n, 5))]
    inits += [
        _kmeans_pp_centroids(points, k, random.Random(seed))
        for seed in range(n_restarts)
    ]

    best_assignments = None
    best_inertia = None
    for init in inits:
        assignments, inertia = _lloyd(points, k, init)
        if best_inertia is None or inertia < best_inertia:
            best_inertia = inertia
            best_assignments = assignments

    clusters = [[] for _ in range(k)]
    for i, c in enumerate(best_assignments):
        clusters[c].append(i)

    clusters = [sorted(cluster) for cluster in clusters if cluster]
    clusters.sort(key=lambda cluster: cluster[0])
    return clusters

