"""Extract absolute hyperlink URLs from HTML markup."""

from html.parser import HTMLParser
from urllib.parse import urljoin


class _LinkParser(HTMLParser):
    """Collect the href attribute of every <a> tag in the document."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hrefs = []

    def handle_starttag(self, tag, attrs):
        if tag == "a":
            for name, value in attrs:
                if name == "href" and value is not None:
                    self.hrefs.append(value)

    # Self-closing / XHTML-style <a ... /> tags also carry attributes.
    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def extract_absolute_links(html, base_url):
    """Return the unique absolute URLs of all <a href="..."> links in *html*.

    Each href is resolved against *base_url* with urljoin semantics and the
    results are returned as a sorted list with duplicates removed.
    """
    parser = _LinkParser()
    parser.feed(html)
    parser.close()

    absolute = {urljoin(base_url, href.strip()) for href in parser.hrefs}
    return sorted(absolute)

