import math


def standardize_columns(data):
    rows = [list(row) for row in data]
    n = len(rows)
    if n == 0:
        return []
    ncols = len(rows[0])
    if ncols == 0:
        return [[] for _ in rows]

    means = [0.0] * ncols
    for row in rows:
        for j in range(ncols):
            means[j] += row[j]
    means = [m / n for m in means]

    variances = [0.0] * ncols
    for row in rows:
        for j in range(ncols):
            d = row[j] - means[j]
            variances[j] += d * d
    stds = [math.sqrt(v / n) for v in variances]

    result = []
    for row in rows:
        out_row = []
        for j in range(ncols):
            if stds[j] == 0.0:
                out_row.append(0.0)
            else:
                out_row.append((row[j] - means[j]) / stds[j])
        result.append(out_row)
    return result

