_WORD_RE = re.compile(r'[^\W_]+', re.UNICODE)


def tfidf_matrix(documents):
    n = len(documents)
    tokenized = [_WORD_RE.findall(doc.lower()) for doc in documents]

    vocab = sorted({tok for toks in tokenized for tok in toks})
    index = {word: i for i, word in enumerate(vocab)}

    df = [0] * len(vocab)
    counts = []
    for toks in tokenized:
        doc_counts = {}
        for tok in toks:
            doc_counts[tok] = doc_counts.get(tok, 0) + 1
        counts.append(doc_counts)
        for tok in doc_counts:
            df[index[tok]] += 1

    idf = [math.log((1 + n) / (1 + d)) + 1 for d in df]

    rows = []
    for doc_counts in counts:
        vec = [0.0] * len(vocab)
        for tok, cnt in doc_counts.items():
            i = index[tok]
            vec[i] = cnt * idf[i]
        norm = math.sqrt(sum(v * v for v in vec))
        if norm > 0:
            vec = [v / norm for v in vec]
        rows.append(vec)

    return (vocab, rows)

