import math


def row_distance_matrix(rows):
    for row in rows:
        for x in row:
            if not isinstance(x, (int, float)):
                raise TypeError(
                    "all elements must be int or float, got %r" % (x,)
                )

    n = len(rows)
    matrix = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            total = 0.0
            for a, b in zip(rows[i], rows[j]):
                diff = a - b
                total += diff * diff
            d = math.sqrt(total)
            matrix[i][j] = d
            matrix[j][i] = d
    return matrix

