def linear_regression_r2(data, target):
    """Fit OLS (with intercept) predicting `target` from all other columns
    of `data` and return the R-squared score on the same data."""
    feature_names = [name for name in data if name != target]
    n = len(data[target])
    y = [float(v) for v in data[target]]
    X = [[1.0] + [float(data[name][i]) for name in feature_names] for i in range(n)]
    p = len(feature_names) + 1

    # Normal equations: (X^T X) beta = X^T y, solved by Gaussian elimination
    # with partial pivoting.
    XtX = [[0.0] * p for _ in range(p)]
    Xty = [0.0] * p
    for row, yi in zip(X, y):
        for a in range(p):
            Xty[a] += row[a] * yi
            ra = row[a]
            XtX_row = XtX[a]
            for b in range(a, p):
                XtX_row[b] += ra * row[b]
    for a in range(p):
        for b in range(a):
            XtX[a][b] = XtX[b][a]

    # Augmented matrix [XtX | Xty]
    A = [XtX[a] + [Xty[a]] for a in range(p)]
    for col in range(p):
        # partial pivot
        piv = max(range(col, p), key=lambda r: abs(A[r][col]))
        if abs(A[piv][col]) < 1e-12:
            continue  # singular direction: leave coefficient at 0
        A[col], A[piv] = A[piv], A[col]
        pv = A[col][col]
        for r in range(col + 1, p):
            f = A[r][col] / pv
            if f != 0.0:
                for c in range(col, p + 1):
                    A[r][c] -= f * A[col][c]
    beta = [0.0] * p
    for r in range(p - 1, -1, -1):
        if abs(A[r][r]) < 1e-12:
            beta[r] = 0.0
            continue
        s = A[r][p]
        for c in range(r + 1, p):
            s -= A[r][c] * beta[c]
        beta[r] = s / A[r][r]

    y_mean = sum(y) / n
    ss_tot = sum((yi - y_mean) ** 2 for yi in y)
    ss_res = 0.0
    for row, yi in zip(X, y):
        pred = sum(b * x for b, x in zip(beta, row))
        ss_res += (yi - pred) ** 2

    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0
    return float(1.0 - ss_res / ss_tot)

