import csv
import io
from decimal import Decimal, localcontext


def _cbrt(x):
    """Real cube root, correctly rounded: negative inputs give negative roots."""
    if x == 0.0:
        return 0.0
    sign = -1.0 if x < 0 else 1.0
    with localcontext() as ctx:
        ctx.prec = 60
        root = abs(Decimal(x)) ** (Decimal(1) / Decimal(3))
    return sign * float(root)


def csv_cube_roots(csv_text, columns):
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        header = []
    else:
        header = rows[0]

    data = {name: [] for name in header}
    for row in rows[1:]:
        values = [float(value) for value in row]
        for name, value in zip(header, values):
            data[name].append(value)

    requested = {}
    for name in columns:
        if name not in data:
            raise KeyError(name)
        requested[name] = [_cbrt(v) for v in data[name]]

    return data, requested

