def complete_row_histogram(data, bins):
    columns = list(data.keys())
    if not columns:
        return {}, None

    rows = zip(*(data[col] for col in columns))
    kept = [row for row in rows if all(value is not None for value in row)]

    cleaned = {
        col: [float(row[i]) for row in kept]
        for i, col in enumerate(columns)
    }

    pooled = [value for col in columns for value in cleaned[col]]
    if not pooled:
        return cleaned, None

    low = min(pooled)
    high = max(pooled)
    if high == low:
        return cleaned, None

    width = (high - low) / bins
    counts = [0] * bins
    for value in pooled:
        index = int((value - low) / width)
        if index >= bins:
            index = bins - 1
        counts[index] += 1

    return cleaned, counts

