import math


def correlation_matrix_from_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]
    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    columns = {name: [] for name in header}
    for row in rows[1:]:
        for name, value in zip(header, row):
            columns[name].append(float(value))

    names = list(header)
    n = len(columns[names[0]]) if names else 0

    means = {}
    stds = {}
    for name in names:
        data = columns[name]
        mean = sum(data) / n if n else 0.0
        std = math.sqrt(sum((x - mean) ** 2 for x in data) / n) if n else 0.0
        means[name] = mean
        stds[name] = std

    result = {}
    for a in names:
        result[a] = {}
        for b in names:
            if a == b:
                result[a][b] = 1.0
            elif stds[a] == 0.0 or stds[b] == 0.0 or n == 0:
                result[a][b] = 0.0
            else:
                result[a][b] = sum(
                    ((x - means[a]) / stds[a]) * ((y - means[b]) / stds[b])
                    for x, y in zip(columns[a], columns[b])
                ) / n
    return result

