_WORD_RE = re.compile(r'[^\W_]+', re.UNICODE)


def document_term_matrix(texts, stop_words):
    stop = {str(w).lower() for w in stop_words}

    doc_words = []
    for text in texts:
        words = [w for w in _WORD_RE.findall(str(text).lower()) if w not in stop]
        doc_words.append(words)

    terms = sorted({w for words in doc_words for w in words})
    index = {t: i for i, t in enumerate(terms)}

    counts = []
    for words in doc_words:
        row = [0] * len(terms)
        for w in words:
            row[index[w]] += 1
        counts.append(row)

    return terms, counts

