def normalize_columns(data):
    """Rescale each column of ``data`` independently to the range [0, 1].

    ``data`` maps column names to equal-length lists of numbers. Each
    column's minimum maps to 0.0 and its maximum to 1.0; a constant
    column maps to all zeros. Returns a dict with the same keys.

    Raises ValueError if ``data`` is empty or any value is non-numeric.
    """
    if not data:
        raise ValueError("data must not be empty")

    result = {}
    for name, column in data.items():
        values = list(column)
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    "column {!r} contains a non-numeric value: {!r}".format(name, value)
                )
        if not values:
            result[name] = []
            continue
        low = min(values)
        high = max(values)
        span = high - low
        if span == 0:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [(value - low) / span for value in values]
    return result

