import math


def animal_count_stats(records):
    """Compute (mean, median, population std) of counts for each animal.

    records: iterable of (animal, count) pairs.
    Returns a dict mapping animal -> (mean, median, pstdev).
    """
    grouped = {}
    for animal, count in records:
        grouped.setdefault(animal, []).append(count)

    stats = {}
    for animal, counts in grouped.items():
        n = len(counts)
        mean = sum(counts) / n

        ordered = sorted(counts)
        mid = n // 2
        if n % 2 == 1:
            median = float(ordered[mid])
        else:
            median = (ordered[mid - 1] + ordered[mid]) / 2.0

        variance = sum((c - mean) ** 2 for c in counts) / n
        pstdev = math.sqrt(variance)

        stats[animal] = (mean, median, pstdev)

    return stats

