def _percentile(sorted_values, p):
    """Linear-interpolation percentile (numpy default) on pre-sorted values."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])
    pos = p * (n - 1)
    lower = int(pos)
    upper = lower + 1 if lower + 1 < n else lower
    frac = pos - lower
    return float(sorted_values[lower] + frac * (sorted_values[upper] - sorted_values[lower]))


def fruit_sales_box_stats(records):
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = {}
    for fruit, day, sales in records:
        sales_by_fruit.setdefault(fruit, []).append(sales)

    stats = {}
    for fruit, sales in sales_by_fruit.items():
        ordered = sorted(sales)
        stats[fruit] = (
            float(ordered[0]),
            _percentile(ordered, 0.25),
            _percentile(ordered, 0.50),
            _percentile(ordered, 0.75),
            float(ordered[-1]),
        )
    return stats

