def _replace_value(value, mapping):
    for key, replacement in mapping.items():
        try:
            if value == key:
                return replacement
        except Exception:
            pass
    return value


def _median(sorted_values):
    n = len(sorted_values)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_values[mid])
    return (sorted_values[mid - 1] + sorted_values[mid]) / 2.0


def _mode(values):
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    max_count = max(counts.values())
    candidates = [value for value, count in counts.items() if count == max_count]
    return min(candidates)


def column_summary_stats(table, mapping, features):
    result = {}
    for name in features:
        if name not in table:
            raise ValueError(f"Feature {name!r} not found in table")
        values = [_replace_value(v, mapping) for v in table[name]]
        n = len(values)
        mean = sum(values) / n
        sorted_values = sorted(values)
        median = _median(sorted_values)
        mode = _mode(values)
        variance = sum((v - mean) ** 2 for v in values) / n
        result[name] = {
            'mean': float(mean),
            'median': float(median),
            'mode': mode,
            'variance': float(variance),
        }
    return result

