"""Extract links from HTML markup."""

from html.parser import HTMLParser


class _LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self._stack = []  # open <a> tags: [text_parts, href]

    def handle_starttag(self, tag, attrs):
        if tag == "a":
            href = None
            for name, value in attrs:
                if name == "href":
                    href = value
                    break
            self._stack.append([[], href])

    def handle_startendtag(self, tag, attrs):
        if tag == "a":
            href = None
            for name, value in attrs:
                if name == "href":
                    href = value
                    break
            self.links.append(("", href))

    def handle_endtag(self, tag):
        if tag == "a" and self._stack:
            text_parts, href = self._stack.pop()
            self.links.append(("".join(text_parts), href))

    def handle_data(self, data):
        for anchor in self._stack:
            anchor[0].append(data)

    def close(self):
        super().close()
        # Flush any unclosed <a> tags still open at EOF, in document order.
        while self._stack:
            text_parts, href = self._stack.pop(0)
            self.links.append(("".join(text_parts), href))


def extract_links(html):
    """Return every <a> tag in ``html`` as a list of (text, href) tuples.

    ``text`` is the tag's inner text with nested tags removed and entities
    decoded; ``href`` is the href attribute or None if absent. Links are
    returned in document order.
    """
    parser = _LinkParser()
    parser.feed(html)
    parser.close()
    return parser.links

