"""Extract the first HTML table from a page as (headers, rows)."""

from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    """Collect <th>/<td> cells of the first <table> in the document."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.started = False    # a <table> has been seen
        self.finished = False   # the first <table> has been closed
        self.depth = 0          # <table> nesting depth
        self.headers = []       # stripped text of every <th> in the table
        self.rows = []          # one list of <td> texts per data <tr>
        self._row = None        # {'th': [...], 'td': [...]} for the open <tr>
        self._cell = None       # (kind, [chunks]) for the open <th>/<td>

    def _flush_cell(self):
        if self._cell is None:
            return
        kind, chunks = self._cell
        text = ''.join(chunks).strip()
        if kind == 'th':
            self.headers.append(text)
        if self._row is not None:
            self._row[kind].append(text)
        self._cell = None

    def _flush_row(self):
        self._flush_cell()
        if self._row is not None:
            if self._row['td']:
                self.rows.append(self._row['td'])
            self._row = None

    def handle_starttag(self, tag, attrs):
        if self.finished:
            return
        if tag == 'table':
            self.depth += 1
            if self.depth == 1:
                self.started = True
            return
        if not self.started or self.depth != 1:
            return
        if tag == 'tr':
            self._flush_row()
            self._row = {'th': [], 'td': []}
        elif tag in ('th', 'td'):
            self._flush_cell()
            if self._row is None:
                self._row = {'th': [], 'td': []}
            self._cell = (tag, [])

    def handle_endtag(self, tag):
        if self.finished:
            return
        if tag == 'table':
            if self.depth == 1:
                self._flush_row()
                self.depth = 0
                self.finished = True
            elif self.depth > 1:
                self.depth -= 1
            return
        if not self.started or self.depth != 1:
            return
        if tag in ('th', 'td'):
            self._flush_cell()
        elif tag == 'tr':
            self._flush_row()

    def handle_data(self, data):
        if self._cell is not None and self.started and not self.finished:
            self._cell[1].append(data)


def extract_first_table(html):
    """Return (headers, rows) for the first <table> in ``html``.

    ``headers`` is the stripped text of every <th> cell in the table (possibly
    empty). ``rows`` holds one list of stripped <td> texts per <tr> that
    contains at least one <td>. Raises ValueError if there is no table or the
    first table has no data rows.
    """
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()
    parser._flush_row()
    if not parser.started:
        raise ValueError('no <table> found in the page')
    if not parser.rows:
        raise ValueError('the first <table> has no data rows')
    return parser.headers, parser.rows

