import math


def row_zscores_and_correlation(data):
    """Standardise each row to z-scores (population std), then compute the
    Pearson correlation matrix between the columns of the z-score matrix.

    Returns (zscore_matrix, correlation_matrix).
    """
    if not data:
        return ([], [])

    n_rows = len(data)
    n_cols = len(data[0]) if n_rows else 0

    # Row-wise z-scores using population standard deviation.
    zscores = []
    for row in data:
        n = len(row)
        if n == 0:
            zscores.append([])
            continue
        mean = sum(row) / n
        var = sum((x - mean) ** 2 for x in row) / n
        std = math.sqrt(var)
        if std == 0.0:
            zscores.append([0.0] * n)
        else:
            zscores.append([(x - mean) / std for x in row])

    if n_cols == 0:
        return (zscores, [])

    # Column statistics of the z-score matrix.
    col_means = [sum(zscores[r][c] for r in range(n_rows)) / n_rows
                 for c in range(n_cols)]
    col_cent = [[zscores[r][c] - col_means[c] for c in range(n_cols)]
                for r in range(n_rows)]
    col_ss = [sum(col_cent[r][c] ** 2 for r in range(n_rows))
              for c in range(n_cols)]

    # Pearson correlation between columns.
    corr = [[0.0] * n_cols for _ in range(n_cols)]
    for i in range(n_cols):
        for j in range(i, n_cols):
            if i == j:
                value = 1.0 if col_ss[i] > 0.0 else 0.0
            else:
                denom = math.sqrt(col_ss[i] * col_ss[j])
                if denom == 0.0:
                    value = 0.0
                else:
                    cov = sum(col_cent[r][i] * col_cent[r][j]
                              for r in range(n_rows))
                    value = cov / denom
            corr[i][j] = value
            corr[j][i] = value

    return (zscores, corr)

