import math


def standardize_filtered(data, age, weight):
    ages = data['Age']
    weights = data['Weight']

    keep = [i for i in range(len(ages)) if ages[i] < age and weights[i] > weight]

    result = {}
    for col, values in data.items():
        kept = [values[i] for i in keep]
        if not kept:
            result[col] = []
            continue
        mean = sum(kept) / len(kept)
        variance = sum((v - mean) ** 2 for v in kept) / len(kept)
        std = math.sqrt(variance)
        if std == 0:
            result[col] = [0.0] * len(kept)
        else:
            result[col] = [(v - mean) / std for v in kept]
    return result

