def highly_correlated_column_pairs(data, cols, threshold):
    if not (0 <= threshold <= 1):
        raise ValueError("threshold must be between 0 and 1")

    n_cols = len(cols)
    n_rows = len(data)

    # Extract columns as lists of floats.
    columns = [[float(row[j]) for row in data] for j in range(n_cols)]

    def pearson(xs, ys):
        n = len(xs)
        if n == 0:
            return 0.0
        mean_x = sum(xs) / n
        mean_y = sum(ys) / n
        sxy = 0.0
        sxx = 0.0
        syy = 0.0
        for x, y in zip(xs, ys):
            dx = x - mean_x
            dy = y - mean_y
            sxy += dx * dy
            sxx += dx * dx
            syy += dy * dy
        if sxx == 0.0 or syy == 0.0:
            # Correlation undefined for a constant column; treat as no correlation.
            return 0.0
        return sxy / (sxx ** 0.5 * syy ** 0.5)

    result = []
    for i in range(n_cols):
        for j in range(i + 1, n_cols):
            corr = pearson(columns[i], columns[j])
            if abs(corr) > threshold:
                result.append((cols[i], cols[j]))
    return result

