import csv
import io


def grouped_column_means(csv_text, group_col, value_col):
    """Group CSV rows by ``group_col`` and compute the mean of ``value_col``.

    Returns a dict mapping each group label (as a string) to the mean of the
    numeric values in that group. Blank value cells are ignored; a non-numeric
    value raises ValueError.
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return {}

    header = rows[0]
    try:
        group_idx = header.index(group_col)
        value_idx = header.index(value_col)
    except ValueError:
        raise ValueError(
            "column not found in header: %r"
            % (group_col if group_col not in header else value_col,)
        )

    groups = {}
    for row in rows[1:]:
        if not row:
            continue
        group = row[group_idx] if group_idx < len(row) else ""
        raw = row[value_idx].strip() if value_idx < len(row) else ""
        if raw == "":
            continue
        try:
            value = float(raw)
        except ValueError:
            raise ValueError(
                "non-numeric value %r in column %r" % (raw, value_col)
            )
        groups.setdefault(group, []).append(value)

    return {label: sum(values) / len(values) for label, values in groups.items()}

