"""CSV row sorting utility."""

import csv
import io
import re

_INT_RE = re.compile(r"^[+-]?\d+$")
_NUM_RE = re.compile(r"^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$")


def _parse_number(text):
    """Return int/float for a numeric string, or None if not numeric."""
    if _INT_RE.match(text):
        return int(text)
    if _NUM_RE.match(text):
        return float(text)
    return None


def sort_csv_rows(csv_text, sort_by_column):
    """Sort the data rows of a CSV string by the given column.

    Returns a list of dicts mapping each header column to its value.
    Columns whose values are all numbers hold ints/floats; all other
    columns hold strings. Raises ValueError if the column is not in
    the header.
    """
    if csv_text.startswith("\ufeff"):
        csv_text = csv_text[1:]

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]

    if not rows:
        header = []
        data = []
    else:
        header = rows[0]
        data = rows[1:]

    if sort_by_column not in header:
        raise ValueError(
            "column %r not found in header %r" % (sort_by_column, header)
        )

    records = []
    for row in data:
        padded = list(row) + [""] * (len(header) - len(row))
        records.append(dict(zip(header, padded[: len(header)])))

    # Determine which columns are entirely numeric.
    numeric_columns = set()
    for col in header:
        values = [rec[col] for rec in records]
        if values and all(_parse_number(v) is not None for v in values):
            numeric_columns.add(col)

    # Convert numeric columns to numbers.
    for rec in records:
        for col in numeric_columns:
            rec[col] = _parse_number(rec[col])

    sort_index = header.index(sort_by_column)
    records.sort(key=lambda rec: rec[header[sort_index]])

    return records

