def histogram_bins(values, bins):
    values = list(values)
    if isinstance(bins, int):
        if not values:
            return ([], [])
        lo = min(values)
        hi = max(values)
        if bins <= 0:
            return ([], [])
        if lo == hi:
            edges = [float(lo)] * (bins + 1)
        else:
            width = (hi - lo) / bins
            edges = [float(lo + i * width) for i in range(bins)] + [float(hi)]
    else:
        edges = [float(e) for e in bins]

    n = len(edges) - 1
    counts = [0] * n
    if n <= 0:
        return (counts, edges)

    for v in values:
        if v < edges[0] or v > edges[-1]:
            continue
        idx = bisect_right(edges, v) - 1
        if idx == n:  # v equals the last edge: belongs to the final bin
            idx = n - 1
        if 0 <= idx < n:
            counts[idx] += 1

    return (counts, edges)

