"""Pixel-value histograms for 8-bit grayscale PGM images."""

from collections import Counter

_WHITESPACE = frozenset(b" \t\n\r\x0b\x0c")
_DIGITS = frozenset(b"0123456789")
_LINE_END = frozenset(b"\r\n")
_HASH = 0x23  # '#'


def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit grayscale PGM image.

    ``data`` must be the raw bytes of a PGM file in either the binary (P5)
    or ASCII (P2) variant, with a maximum gray value (maxval) of at most
    255.  The result is a dict mapping each pixel value that occurs in the
    image to the number of pixels with that value.  ``ValueError`` is
    raised if ``data`` is not a valid 8-bit grayscale PGM image.
    """
    if isinstance(data, (bytearray, memoryview)):
        data = bytes(data)
    if not isinstance(data, bytes):
        raise ValueError("input must be the raw bytes of a PGM file")

    magic = data[:2]
    if magic not in (b"P2", b"P5"):
        raise ValueError("not a PGM image: bad magic number")
    binary = magic == b"P5"
    n = len(data)
    pos = 2

    def skip_space_and_comments():
        nonlocal pos
        while pos < n:
            c = data[pos]
            if c in _WHITESPACE:
                pos += 1
            elif c == _HASH:
                # A comment runs from '#' through the end of the line.
                pos += 1
                while pos < n and data[pos] not in _LINE_END:
                    pos += 1
                if pos < n:
                    pos += 1
            else:
                return

    def read_uint():
        nonlocal pos
        skip_space_and_comments()
        start = pos
        while pos < n and data[pos] in _DIGITS:
            pos += 1
        if pos == start:
            raise ValueError("malformed header: expected an unsigned integer")
        return int(data[start:pos])

    width = read_uint()
    height = read_uint()
    maxval = read_uint()
    if width <= 0 or height <= 0:
        raise ValueError("malformed header: dimensions must be positive")
    if not 1 <= maxval <= 255:
        raise ValueError("malformed header: maxval must be in 1..255 (8-bit)")

    count = width * height
    histogram = {}

    if binary:
        # A single whitespace character (comments may precede it) separates
        # the header from the raw raster.
        while True:
            if pos >= n:
                raise ValueError("truncated file: missing raster")
            c = data[pos]
            if c == _HASH:
                pos += 1
                while pos < n and data[pos] not in _LINE_END:
                    pos += 1
                if pos < n:
                    pos += 1
            elif c in _WHITESPACE:
                pos += 1
                break
            else:
                raise ValueError("malformed header: expected whitespace after maxval")
        if n - pos < count:
            raise ValueError("truncated file: raster is shorter than width*height")
        raster = data[pos:pos + count]
        if max(raster) > maxval:
            raise ValueError("pixel value exceeds maxval")
        histogram = dict(Counter(raster))
        pos += count
        # Only trailing whitespace may follow the raster.
        while pos < n:
            if data[pos] not in _WHITESPACE:
                raise ValueError("unexpected data after raster")
            pos += 1
    else:
        for _ in range(count):
            value = read_uint()
            if value > maxval:
                raise ValueError("pixel value exceeds maxval")
            histogram[value] = histogram.get(value, 0) + 1
        skip_space_and_comments()
        if pos != n:
            raise ValueError("unexpected data after raster")

    return histogram

