        # A single whitespace character (comments may precede it) separates
        # the header from the raw raster.
        while True:
            if pos >= n:
                raise ValueError("truncated file: missing raster")
            c = data[pos]
            if c == _HASH:
                pos += 1
                while pos < n and data[pos] not in _LINE_END:
