def classical_seasonal_decomposition(values, period, model='additive'):
    """Classical (moving-average) seasonal decomposition of a series.

    Returns a dict with 'trend', 'seasonal' and 'resid' lists, each as long
    as ``values``. 'trend' and 'resid' are None where the centred moving
    average is not defined (the ends of the series).
    """
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    values = list(values)
    n = len(values)
    if period < 1:
        raise ValueError("period must be a positive integer")
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    # Trend: centred moving average of order `period`. For an even period a
    # 2 x period moving average is used so the result stays centred.
    trend = [None] * n
    if period % 2 == 1:
        half = period // 2
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        half = period // 2
        ma = [sum(values[j:j + period]) / period for j in range(n - period + 1)]
        for i in range(half, n - half):
            trend[i] = (ma[i - half] + ma[i - half + 1]) / 2.0

    # Detrended series (None where the trend is undefined).
    detrended = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == 'additive':
                detrended[i] = values[i] - trend[i]
            else:
                detrended[i] = values[i] / trend[i]

    # Seasonal: per-phase average of the detrended series, normalised so the
    # seasonal factors average to 0 (additive) or 1 (multiplicative).
    sums = [0.0] * period
    counts = [0] * period
    for i in range(n):
        if detrended[i] is not None:
            phase = i % period
            sums[phase] += detrended[i]
            counts[phase] += 1
    factors = [sums[r] / counts[r] for r in range(period)]
    centre = sum(factors) / period
    if model == 'additive':
        factors = [f - centre for f in factors]
    else:
        factors = [f / centre for f in factors]
    seasonal = [factors[i % period] for i in range(n)]

    # Residual: what remains after removing trend and seasonal.
    resid = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == 'additive':
                resid[i] = values[i] - trend[i] - seasonal[i]
            else:
                resid[i] = values[i] / trend[i] / seasonal[i]

    return {'trend': trend, 'seasonal': seasonal, 'resid': resid}

