"""Summarize the numeric columns of a CSV file.

The CSV text must have a header row. Numbers may use thousands separators
(e.g. "1,000", which is quoted in the CSV itself). A column is treated as
numeric only if every one of its data values parses as a number; any other
column is ignored.
"""

import csv
import io
import math
import re

# A number, optionally signed, with either plain digits or digits grouped by
# thousands separators ("1,000,000"), an optional fractional part, and an
# optional exponent.
_NUMBER_RE = re.compile(
    r"^[+-]?(?:(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
)


def _parse_number(cell):
    """Return the value of a CSV cell as a float, or None if it is not a number."""
    text = cell.strip()
    if not text or not _NUMBER_RE.match(text):
        return None
    return float(text.replace(",", ""))


def summarize_numeric_csv(csv_text):
    """Summarize the numeric columns of CSV text with a header row.

    Returns a dict with keys:
      'means'    -- {column name: mean} for each numeric column
      'std_devs' -- {column name: sample standard deviation (ddof=1)}
      'f_value'  -- F statistic of a one-way ANOVA over the numeric columns
                    treated as groups, or None if there are fewer than two
                    numeric columns
    """
    rows = [row for row in csv.reader(io.StringIO(csv_text)) if row]
    if not rows:
        return {"means": {}, "std_devs": {}, "f_value": None}

    header = rows[0]
    if header and header[0].startswith("\ufeff"):
        header[0] = header[0][1:]
    data_rows = rows[1:]

    # Keep only the columns whose every value is a number.
    numeric = {}
    for index, name in enumerate(header):
        values = []
        for row in data_rows:
            cell = row[index] if index < len(row) else ""
            value = _parse_number(cell)
            if value is None:
                values = None
                break
            values.append(value)
        if values:
            numeric[name] = values

    means = {}
    std_devs = {}
    for name, values in numeric.items():
        n = len(values)
        mean = math.fsum(values) / n
        means[name] = mean
        if n > 1:
            ss = math.fsum((x - mean) ** 2 for x in values)
            std_devs[name] = math.sqrt(ss / (n - 1))
        else:
            std_devs[name] = None

    groups = list(numeric.values())
    if len(groups) < 2:
        f_value = None
    else:
        total_n = sum(len(g) for g in groups)
        grand_mean = math.fsum(x for g in groups for x in g) / total_n
        ss_between = math.fsum(
            len(g) * (means[name] - grand_mean) ** 2
            for name, g in numeric.items()
        )
        ss_within = math.fsum(
            math.fsum((x - means[name]) ** 2 for x in g)
            for name, g in numeric.items()
        )
        ms_between = ss_between / (len(groups) - 1)
        df_within = total_n - len(groups)
        if df_within > 0:
            ms_within = ss_within / df_within
            if ms_within > 0:
                f_value = ms_between / ms_within
            else:
                f_value = float("inf") if ms_between > 0 else None
        else:
            f_value = float("inf") if ms_between > 0 else None

    return {"means": means, "std_devs": std_devs, "f_value": f_value}

