def matrix_tensor_product(P, T):
    if not P:
        return ([], [])
    n_p = len(P[0])
    n_t = len(T)
    if n_p != n_t:
        raise ValueError(
            "P's row length (%d) does not match T's first dimension (%d)"
            % (n_p, n_t)
        )

    product = []
    sums = []
    for row in P:
        if len(row) != n_p:
            raise ValueError("P is not a rectangular matrix")
        out_rows = None
        row_sums = None
        for n, p in enumerate(row):
            slice_n = T[n]
            if out_rows is None:
                a = len(slice_n)
                out_rows = [[0] * len(slice_n[a_i]) for a_i in range(a)]
                row_sums = [0] * a
            for a_i, vec in enumerate(slice_n):
                out_vec = out_rows[a_i]
                for b_i, v in enumerate(vec):
                    out_vec[b_i] += p * v
        if out_rows is None:
            out_rows = []
            row_sums = []
        for a_i, vec in enumerate(out_rows):
            row_sums[a_i] = sum(vec)
        product.append(out_rows)
        sums.append(row_sums)

    return (product, sums)

