import math


def max_pairwise_distance(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n < 2:
        return 0

    best = 0.0
    for i in range(n):
        xi = xs[i]
        yi = ys[i]
        for j in range(i + 1, n):
            dx = xi - xs[j]
            dy = yi - ys[j]
            d = math.hypot(dx, dy)
            if d > best:
                best = d
    return float(best)

