def _is_numeric_column(values):
    if len(values) == 0:
        return False
    return all(
        isinstance(v, (int, float)) and not isinstance(v, bool)
        for v in values
    )


def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    numeric_cols = [name for name, values in table.items() if _is_numeric_column(values)]
    if not numeric_cols:
        raise ValueError("table has no numeric columns")

    n = len(next(iter(table.values())))

    standardized = {}
    for name, values in table.items():
        if name in numeric_cols:
            mean = sum(values) / n
            var = sum((v - mean) ** 2 for v in values) / n
            std = var ** 0.5
            if std == 0.0:
                standardized[name] = [0.0] * n
            else:
                standardized[name] = [(v - mean) / std for v in values]
        else:
            standardized[name] = list(values)

    k = len(numeric_cols)
    raw = {name: [float(v) for v in table[name]] for name in numeric_cols}
    means = {name: sum(vals) / n for name, vals in raw.items()}
    centered = {
        name: [v - means[name] for v in vals] for name, vals in raw.items()
    }
    corr = [[0.0] * k for _ in range(k)]
    for i, ci in enumerate(numeric_cols):
        for j, cj in enumerate(numeric_cols):
            if i == j:
                corr[i][j] = 1.0
            else:
                num = sum(a * b for a, b in zip(centered[ci], centered[cj]))
                ss_i = sum(a * a for a in centered[ci])
                ss_j = sum(b * b for b in centered[cj])
                den = (ss_i * ss_j) ** 0.5
                corr[i][j] = num / den if den != 0.0 else 0.0

    return standardized, corr

