"""Extract hyperlink targets from an HTML page."""

from html.parser import HTMLParser
from urllib.parse import urljoin


class _LinkExtractor(HTMLParser):
    def __init__(self, base_url):
        super().__init__(convert_charrefs=True)
        self.base_url = base_url
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag != "a":
            return
        for name, value in attrs:
            if name == "href":
                self.links.append(urljoin(self.base_url, value or ""))
                break

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def extract_page_links(html, base_url):
    """Return the href of every <a> element in ``html``, in document order.

    Relative hrefs are resolved against ``base_url``; absolute hrefs are
    kept as they are. Duplicates are preserved.
    """
    parser = _LinkExtractor(base_url)
    parser.feed(html)
    parser.close()
    return parser.links

