import json


def _quantile(sorted_values, q):
    """Quantile by linear interpolation between sorted values (numpy default)."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])
    pos = (n - 1) * q
    lower = int(pos)
    upper = min(lower + 1, n - 1)
    frac = pos - lower
    return float(sorted_values[lower] + frac * (sorted_values[upper] - sorted_values[lower]))


def summarize_values_by_key(json_text):
    """Summarize per-key numeric values from a JSON list of objects.

    Returns a dict mapping each key to {'mean', 'median', 'q1', 'q3'} computed
    over all values recorded for that key across the objects.
    Raises ValueError if the input is not valid JSON.
    """
    try:
        data = json.loads(json_text)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, list):
        raise ValueError("Expected a JSON list of objects")

    values_by_key = {}
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Expected each element of the list to be an object")
        for key, value in item.items():
            values_by_key.setdefault(key, []).append(value)

    result = {}
    for key, values in values_by_key.items():
        ordered = sorted(values)
        n = len(ordered)
        mean = sum(ordered) / n
        result[key] = {
            "mean": mean,
            "median": _quantile(ordered, 0.5),
            "q1": _quantile(ordered, 0.25),
            "q3": _quantile(ordered, 0.75),
        }
    return result

