from numbers import Real


def _is_numeric(value):
    """Return True if *value* is a real number (bools count as ints)."""
    if isinstance(value, complex) and not isinstance(value, Real):
        return False
    return isinstance(value, (Real, decimal.Decimal))


def _pearson(xs, ys):
    """Pearson correlation of two equal-length sequences of numbers."""
    n = len(xs)
    if n == 0:
        return 0.0
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    num = 0.0
    var_x = 0.0
    var_y = 0.0
    for x, y in zip(xs, ys):
        dx = x - mean_x
        dy = y - mean_y
        num += dx * dy
        var_x += dx * dx
        var_y += dy * dy
    denom = (var_x * var_y) ** 0.5
    if denom == 0:
        # A constant column has no defined correlation; treat it as 0.
        return 0.0
    return num / denom


def most_correlated_columns(data):
    """Return the two distinct columns with the largest |Pearson correlation|.

    The column that appears first in ``data`` is returned first in the tuple.

    Raises:
        ValueError: if there is no data or fewer than two columns.
        TypeError: if any column contains non-numeric values.
    """
