        raise ValueError("no data: data is None")
    if not isinstance(data, Mapping):
        raise TypeError("data must be a dict mapping column names to lists")

    if len(data) == 0:
        raise ValueError("no data: data must contain at least two columns")
    if len(data) < 2:
        raise ValueError("at least two columns are required")

    columns = []
    for name, values in data.items():
        if isinstance(values, (str, bytes)):
            raise TypeError(
                "column %r must be an iterable of numbers, got %r" % (name, values)
            )
        try:
            raw = list(values)
        except TypeError:
            raise TypeError(
                "column %r must be an iterable of numbers, got %r" % (name, values)
            )
        if len(raw) == 0:
            raise ValueError("no data: column %r is empty" % (name,))
        column = []
        for value in raw:
            if not _is_numeric(value):
                raise TypeError(
                    "column %r contains a non-numeric value: %r" % (name, value)
                )
            try:
                column.append(float(value))
            except (TypeError, ValueError, OverflowError):
                raise TypeError(
                    "column %r contains a non-numeric value: %r" % (name, value)
                )
        columns.append((name, column))

    lengths = {len(col) for _, col in columns}
    if len(lengths) > 1:
        raise ValueError("all columns must have the same length")

    best_pair = None
    best_abs = None
    for i in range(len(columns)):
