"""K-means clustering for 2D points (pure Python, self-contained)."""

import random


def _validate(points, n_clusters):
    """Validate inputs; return (list of [x, y] float pairs, n_clusters int)."""
    if points is None:
        raise ValueError("points must not be empty")
    pts = list(points)
    if len(pts) == 0:
        raise ValueError("points must not be empty")

    if isinstance(n_clusters, bool):
        raise ValueError("n_clusters must be a positive integer")
    if isinstance(n_clusters, int):
        k = n_clusters
    elif isinstance(n_clusters, float) and n_clusters.is_integer():
        k = int(n_clusters)
    elif hasattr(n_clusters, "__index__"):
        k = int(n_clusters)
    else:
        raise ValueError("n_clusters must be a positive integer")
    if k <= 0:
        raise ValueError("n_clusters must be a positive integer")
    if k > len(pts):
        raise ValueError("n_clusters cannot exceed the number of points")

    cleaned = []
    for p in pts:
        if p is None:
            raise ValueError("each point must be an [x, y] pair")
        pair = list(p)
        if len(pair) != 2:
            raise ValueError("each point must be an [x, y] pair")
        cleaned.append([float(pair[0]), float(pair[1])])
    return cleaned, k


def _dist2(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


def _kmeans_pp_init(points, k, rng):
    """k-means++ seeding."""
    centers = [list(points[rng.randrange(len(points))])]
    while len(centers) < k:
        d2 = [min(_dist2(p, c) for c in centers) for p in points]
        total = sum(d2)
        if total <= 0.0:
            # All points coincide with already chosen centers.
            for p in points:
                if p not in centers:
                    centers.append(list(p))
                    break
            else:
                centers.append(list(points[rng.randrange(len(points))]))
            continue
        r = rng.random() * total
        acc = 0.0
        chosen = points[-1]
        for p, w in zip(points, d2):
            acc += w
            if acc >= r:
                chosen = p
                break
        centers.append(list(chosen))
    return centers


def _lloyd(points, k, seed, max_iters=300):
    """Run Lloyd's algorithm once; return (centers, inertia)."""
    rng = random.Random(seed)
    centers = _kmeans_pp_init(points, k, rng)
    assignments = [-1] * len(points)

    for _ in range(max_iters):
        changed = False
        inertia = 0.0
        for i, p in enumerate(points):
            best = 0
            best_d = _dist2(p, centers[0])
            for j in range(1, k):
                d = _dist2(p, centers[j])
                if d < best_d:
                    best_d = d
                    best = j
            inertia += best_d
            if assignments[i] != best:
                assignments[i] = best
                changed = True

        sums = [[0.0, 0.0] for _ in range(k)]
        counts = [0] * k
        for p, a in zip(points, assignments):
            s = sums[a]
            s[0] += p[0]
            s[1] += p[1]
            counts[a] += 1

        new_centers = []
        for j in range(k):
            if counts[j] == 0:
                # Empty cluster: re-seed at the point farthest from the
                # current (unused) center.
                farthest = max(
                    range(len(points)), key=lambda i: _dist2(points[i], centers[j])
                )
                new_centers.append(list(points[farthest]))
            else:
                new_centers.append(
                    [sums[j][0] / counts[j], sums[j][1] / counts[j]]
                )

        moved = any(_dist2(new_centers[j], centers[j]) > 1e-12 for j in range(k))
        centers = new_centers
        if not moved and not changed:
            break

    return centers, inertia


def kmeans_centers(points, n_clusters):
    """Cluster 2D points into ``n_clusters`` groups using k-means.

    Args:
        points: a non-empty list of ``[x, y]`` pairs.
        n_clusters: positive number of clusters, at most ``len(points)``.

    Returns:
        The cluster centers as a list of ``[x, y]`` float pairs, sorted in
        ascending order (by x, then y).

    Raises:
        ValueError: if ``points`` is empty, ``n_clusters`` is not positive,
            or ``n_clusters`` exceeds the number of points.
    """
    pts, k = _validate(points, n_clusters)

    # Several deterministic restarts; keep the best (lowest inertia) result.
    # More restarts for small/medium problems, fewer for very large ones.
    if len(pts) * k <= 20000:
        n_init = 25
    elif len(pts) * k <= 100000:
        n_init = 10
    else:
        n_init = 5
    if len(pts) < k * 2:
        n_init = 1
    best_centers = None
    best_inertia = None
    for seed in range(n_init):
        centers, inertia = _lloyd(pts, k, seed)
        if best_inertia is None or inertia < best_inertia - 1e-12:
            best_inertia = inertia
            best_centers = centers

    return sorted(
        ([float(c[0]), float(c[1])] for c in best_centers),
        key=lambda c: (c[0], c[1]),
    )

