                assignments[i] = best
                changed = True

        sums = [[0.0, 0.0] for _ in range(k)]
        counts = [0] * k
        for p, a in zip(points, assignments):
            s = sums[a]
            s[0] += p[0]
            s[1] += p[1]
            counts[a] += 1

        new_centers = []
        for j in range(k):
            if counts[j] == 0:
                # Empty cluster: re-seed at the point farthest from the
                # current (unused) center.
                farthest = max(
                    range(len(points)), key=lambda i: _dist2(points[i], centers[j])
                )
                new_centers.append(list(points[farthest]))
            else:
                new_centers.append(
                    [sums[j][0] / counts[j], sums[j][1] / counts[j]]
                )

        moved = any(_dist2(new_centers[j], centers[j]) > 1e-12 for j in range(k))
        centers = new_centers
        if not moved and not changed:
            break

    return centers, inertia


def kmeans_centers(points, n_clusters):
    """Cluster 2D points into ``n_clusters`` groups using k-means.

    Args:
        points: a non-empty list of ``[x, y]`` pairs.
        n_clusters: positive number of clusters, at most ``len(points)``.

    Returns:
