        ascending order (by x, then y).

    Raises:
        ValueError: if ``points`` is empty, ``n_clusters`` is not positive,
            or ``n_clusters`` exceeds the number of points.
    """
    pts, k = _validate(points, n_clusters)

    # Several deterministic restarts; keep the best (lowest inertia) result.
    # More restarts for small/medium problems, fewer for very large ones.
    if len(pts) * k <= 20000:
        n_init = 25
    elif len(pts) * k <= 100000:
        n_init = 10
    else:
        n_init = 5
    if len(pts) < k * 2:
        n_init = 1
    best_centers = None
    best_inertia = None
    for seed in range(n_init):
        centers, inertia = _lloyd(pts, k, seed)
        if best_inertia is None or inertia < best_inertia - 1e-12:
            best_inertia = inertia
            best_centers = centers

    return sorted(
        ([float(c[0]), float(c[1])] for c in best_centers),
        key=lambda c: (c[0], c[1]),
    )

