import math


def _solve_linear_system(matrix, rhs):
    """Solve ``matrix @ x = rhs`` by Gaussian elimination with partial pivoting.

    Returns a list of floats, or ``None`` if the matrix is singular.
    """
    n = len(matrix)
    if n == 0:
        return []
    a = [list(row[:]) + [float(rhs[i])] for i, row in enumerate(matrix)]
    for col in range(n):
        pivot_row = max(range(col, n), key=lambda r: abs(a[r][col]))
        if abs(a[pivot_row][col]) < 1e-300:
            return None  # singular
        if pivot_row != col:
            a[col], a[pivot_row] = a[pivot_row], a[col]
        pivot = a[col][col]
        for r in range(col + 1, n):
            factor = a[r][col] / pivot
            if factor == 0.0:
                continue
            for c in range(col, n + 1):
                a[r][c] -= factor * a[col][c]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        total = a[i][n] - sum(a[i][j] * x[j] for j in range(i + 1, n))
        x[i] = total / a[i][i]
    return x


def _normal_equations_ridge(design, targets, ridge=0.0):
    """Solve the (optionally ridge-regularized) normal equations."""
    m = len(design)
    n = len(design[0]) if m else 0
    xtx = [[0.0] * n for _ in range(n)]
    xty = [0.0] * n
    for row, y in zip(design, targets):
        for i in range(n):
            ri = row[i]
            if ri != 0.0:
                xty[i] += ri * y
                for j in range(i, n):
                    xtx[i][j] += ri * row[j]
    for i in range(n):
        for j in range(i):
            xtx[i][j] = xtx[j][i]
    if ridge:
        for i in range(n):
            xtx[i][i] += ridge
    return _solve_linear_system(xtx, xty)


def _qr_lstsq(design, targets):
    """Least squares via Householder QR.

    Returns (solution, rank) where ``rank`` is the detected rank of the design
    matrix.  ``solution`` may be ``None`` when the matrix is rank deficient.
    """
    m = len(design)
    n = len(design[0]) if m else 0
    a = [[float(v) for v in row] for row in design]
    b = [float(v) for v in targets]
    col_norms = [math.sqrt(sum(a[i][j] ** 2 for i in range(m))) for j in range(n)]

    for k in range(min(n, m)):
        norm = math.sqrt(sum(a[i][k] * a[i][k] for i in range(k, m)))
        if norm == 0.0:
            continue
        alpha = -norm if a[k][k] >= 0 else norm
        v = [0.0] * m
        v[k] = a[k][k] - alpha
        for i in range(k + 1, m):
            v[i] = a[i][k]
        vnorm2 = sum(v[i] * v[i] for i in range(k, m))
        if vnorm2 == 0.0:
