"""Merge multiple CSV documents (as strings) into a single list of dicts."""

import csv
import io
import re

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(
    r"^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?$"
)


def _to_value(cell):
    """Convert a raw CSV cell into None, int, float or str."""
    if cell is None:
        return None
    text = cell.strip()
    if text == "":
        return None
    if _INT_RE.match(text):
        try:
            return int(text)
        except ValueError:
            return text
    if _FLOAT_RE.match(text):
        try:
            return float(text)
        except ValueError:
            return text
    return text


def _parse_csv_text(text):
    """Parse one CSV document, returning (header, list of row lists)."""
    if text is None:
        return [], []
    if not isinstance(text, str):
        text = str(text)
    # Normalize newlines so csv reader handles \r\n and \r too.
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    reader = csv.reader(io.StringIO(text))
    rows = [row for row in reader if row]
    if not rows:
        return [], []
    header = [cell.strip() for cell in rows[0]]
    data = rows[1:]
    return header, data


def merge_csv_texts(csv_texts):
    """Stack the rows of several CSV documents into one table.

    Args:
        csv_texts: list of strings, each a CSV document with a header row.

    Returns:
        List of dicts, one per data row (in input order).  Each dict maps
        every column that appears in any input to that row's value.  Missing
        columns and empty cells become None.  Numeric-looking values are
        returned as int/float, everything else as a string.
    """
    if not csv_texts:
        return []

    parsed = [_parse_csv_text(text) for text in csv_texts]

    # Union of all columns, in order of first appearance.
    columns = []
    seen = set()
    for header, _ in parsed:
        for col in header:
            if col not in seen:
                seen.add(col)
                columns.append(col)

    result = []
    for header, data in parsed:
        index = {col: i for i, col in enumerate(header)}
        for row in data:
            record = {}
            for col in columns:
                i = index.get(col)
                if i is None or i >= len(row):
                    record[col] = None
                else:
                    record[col] = _to_value(row[i])
            result.append(record)

    return result

