import csv
import io
import re
from collections import Counter

STOP_WORDS = {"a", "an", "the", "in", "on", "at", "and", "or"}
WORD_RE = re.compile(r"\w{2,}", re.UNICODE)


def top_word_counts(csv_text):
    """Return the ten most common words in a single-column CSV with no header.

    Words are case-insensitive runs of two or more word characters
    (letters, digits, underscore). Stop words are ignored. Results are
    ordered by count descending, then alphabetically by word.
    """
    if not csv_text:
        return []

    counts = Counter()
    reader = csv.reader(io.StringIO(csv_text))
    for row in reader:
        for field in row:
            for match in WORD_RE.findall(field.lower()):
                if match not in STOP_WORDS:
                    counts[match] += 1

    if not counts:
        return []

    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:10]

