from html.parser import HTMLParser


# HTML void elements: they never have any content, so their text is always empty.
_VOID_ELEMENTS = frozenset({
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
})


class _FirstTagTextParser(HTMLParser):
    """Collects the text content of the first element with a given tag name."""

    def __init__(self, tag):
        # convert_charrefs=True makes HTMLParser decode entities for us.
        super().__init__(convert_charrefs=True)
        self.tag = tag
        self.depth = 0
        self.capturing = False
        self.done = False
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == self.tag:
            if self.capturing:
                # A nested element with the same tag name.
                self.depth += 1
            else:
                self.capturing = True
                self.depth = 1

    def handle_endtag(self, tag):
        if self.done or not self.capturing:
            return
        if tag == self.tag:
            self.depth -= 1
            if self.depth <= 0:
                self.capturing = False
                self.done = True

    def handle_startendtag(self, tag, attrs):
        # A self-closing tag (e.g. "<p/>") has no content at all.
        if self.done:
            return
        if tag == self.tag and not self.capturing:
            self.done = True
            self.parts = []
        # While capturing, a self-closing tag (of any name) does not
        # change the nesting depth, so nothing else to do.

    def handle_data(self, data):
        if self.capturing and not self.done and data:
            self.parts.append(data)

    def handle_entityref(self, name):  # only called when convert_charrefs=False
        if self.capturing and not self.done:
            from html.entities import name2codepoint
            if name in name2codepoint:
                self.parts.append(chr(name2codepoint[name]))
            else:
                self.parts.append("&" + name + ";")

    def handle_charref(self, name):  # only called when convert_charrefs=False
        if self.capturing and not self.done:
            try:
                if name.startswith(("x", "X")):
                    self.parts.append(chr(int(name[1:], 16)))
                else:
                    self.parts.append(chr(int(name)))
            except (ValueError, OverflowError):
                self.parts.append("&#" + name + ";")


def first_tag_text(html, tag):
    """Return the text content of the first element named ``tag`` in ``html``.

    The text content includes the text of any nested elements, with tags
    removed and character entities decoded.  ``None`` is returned when there
    is no such element or when its text content is empty.
