"""Ordinary least-squares linear regression (with intercept) on CSV text.

Self-contained implementation: the CSV strings are parsed with the standard
``csv`` module, the least-squares coefficients are computed exactly with
rational arithmetic (falling back to a floating-point pseudo-inverse when the
normal equations are singular or the problem is very large), and predictions
are returned as plain floats.
"""

import csv
import io
import math
from fractions import Fraction

# Above this many numeric cells in the training design matrix, switch from
# exact rational arithmetic to fast floating-point least squares.
_EXACT_CELL_LIMIT = 200000


def _parse_csv(csv_text):
    """Parse CSV text into (header, rows); rows are lists of raw strings."""
    if not isinstance(csv_text, str):
        raise ValueError("CSV input must be a string")
    try:
        records = list(csv.reader(io.StringIO(csv_text)))
    except csv.Error as exc:
        raise ValueError("Invalid CSV text: %s" % exc)
    if not records:
        raise ValueError("CSV text is empty (missing header row)")
    header = [cell.strip() for cell in records[0]]
    rows = []
    for record in records[1:]:
        if len(record) == 1 and record[0].strip() == "":
            continue  # ignore completely blank lines
        rows.append(record)
    return header, rows


def _to_number(value, context):
    """Convert a CSV cell into an exact Fraction, raising ValueError if the
    value is missing or non-numeric."""
    if value is None:
        raise ValueError("Missing value (%s)" % context)
    text = value.strip()
    if text == "":
        raise ValueError("Missing value (%s)" % context)
    try:
        number = Fraction(text)
    except (ValueError, ZeroDivisionError, OverflowError):
        raise ValueError("Non-numeric value %r (%s)" % (value, context))
    # Reject values that are not finite real numbers (nan / inf / overflow).
    try:
        as_float = float(text)
    except (ValueError, OverflowError):
        raise ValueError("Non-numeric value %r (%s)" % (value, context))
    if math.isnan(as_float) or math.isinf(as_float):
        raise ValueError("Non-finite value %r (%s)" % (value, context))
    return number


def _column_index(header, name, context):
    try:
        return header.index(name)
    except ValueError:
        raise ValueError("Column %r not found in %s header" % (name, context))


def _read_train(header, rows, feature_names, target):
    feat_idx = [_column_index(header, n, "training") for n in feature_names]
    tgt_idx = _column_index(header, target, "training")
    n_cols = len(header)
    X, y = [], []
    for row in rows:
        if len(row) < n_cols:
            raise ValueError("Row is missing values: %r" % (row,))
        X.append([_to_number(row[i], "training feature") for i in feat_idx])
        y.append(_to_number(row[tgt_idx], "training target"))
    return X, y


def _read_test(header, rows, feature_names):
    feat_idx = [_column_index(header, n, "test") for n in feature_names]
    n_cols = len(header)
    X = []
    for row in rows:
        if len(row) < n_cols:
            raise ValueError("Row is missing values: %r" % (row,))
        X.append([_to_number(row[i], "test feature") for i in feat_idx])
    return X


def _rref(rows, n_cols):
    """In-place reduced row echelon form (exact Fractions).

    ``rows`` is a list of lists of length >= n_cols (extra columns are the
    augmented right-hand side).  Returns the list of pivot column indices.
    """
    pivots = []
    r = 0
    for col in range(n_cols):
        if r >= len(rows):
            break
        piv = None
        for i in range(r, len(rows)):
            if rows[i][col] != 0:
                piv = i
                break
        if piv is None:
            continue
        rows[r], rows[piv] = rows[piv], rows[r]
        pv = rows[r][col]
        rows[r] = [v / pv for v in rows[r]]
        for i in range(len(rows)):
            if i != r and rows[i][col] != 0:
                factor = rows[i][col]
                rows[i] = [v - factor * w for v, w in zip(rows[i], rows[r])]
        pivots.append(col)
        r += 1
    return pivots


def _solve_exact(A, b):
    """Exact least-squares solution of A c ~= b (minimum-norm if rank
    deficient), via the normal equations solved with rational arithmetic.

    Returns None only if the problem cannot be solved exactly.
    """
    n = len(A)
    m = len(A[0])
    ata = [[Fraction(0)] * m for _ in range(m)]
    atb = [Fraction(0)] * m
    for i in range(n):
        row = A[i]
        bi = b[i]
        for j in range(m):
            rj = row[j]
            if rj:
                atb[j] += rj * bi
                for k in range(j, m):
                    ata[j][k] += rj * row[k]
    for j in range(m):
        for k in range(j):
            ata[j][k] = ata[k][j]

    # Reduced row echelon form of the normal equations.
    aug = [ata[j] + [atb[j]] for j in range(m)]
    pivots = _rref(aug, m)
    if len(pivots) == m:
        # Unique solution.
        return [aug[j][m] for j in range(m)]

    # Rank deficient: build the minimum-norm solution, i.e. the solution of
    # N c = A^T b that is orthogonal to the null space of N (= null space of A).
    free = [c for c in range(m) if c not in pivots]
    null_basis = []
    for f in free:
        v = [Fraction(0)] * m
        v[f] = Fraction(1)
        for r, pc in enumerate(pivots):
            v[pc] = -aug[r][f]
        null_basis.append(v)
    # System: non-zero RREF rows of the normal equations + orthogonality to
    # each null-space basis vector.
    system = [row[:] for row in aug if any(v != 0 for v in row[:m])]
    rhs = [row[m] for row in system]
    for v in null_basis:
        system.append(list(v))
        rhs.append(Fraction(0))
    # Solve the (consistent, full-rank) system exactly.
    aug2 = [system[i] + [rhs[i]] for i in range(len(system))]
    pivots2 = _rref(aug2, m)
    if len(pivots2) != m:
        return None
    return [aug2[j][m] for j in range(m)]


def _solve_float(A, b):
    """Floating-point least squares (minimum-norm solution if rank deficient)."""
    try:
        import numpy as np
    except ImportError:
        return _solve_float_pure(A, b)
    arr = np.asarray(A, dtype=float)
    vec = np.asarray(b, dtype=float)
    coeffs, _, _, _ = np.linalg.lstsq(arr, vec, rcond=None)
    return [float(c) for c in coeffs]


def _solve_float_pure(A, b):
    """Fallback normal-equations solve in pure Python (no numpy required)."""
    n = len(A)
    m = len(A[0])
    ata = [[0.0] * m for _ in range(m)]
    atb = [0.0] * m
    for i in range(n):
        row = A[i]
        bi = b[i]
        for j in range(m):
            if row[j]:
                atb[j] += row[j] * bi
                for k in range(j, m):
                    ata[j][k] += row[j] * row[k]
    for j in range(m):
        for k in range(j):
            ata[j][k] = ata[k][j]
    aug = [ata[j] + [atb[j]] for j in range(m)]
    for col in range(m):
        piv = max(range(col, m), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            continue  # treat as free variable (coefficient left at 0)
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        for r in range(col + 1, m):
            factor = aug[r][col] / pv
            if factor:
                for c in range(col, m + 1):
                    aug[r][c] -= factor * aug[col][c]
    x = [0.0] * m
    for r in range(m - 1, -1, -1):
        if abs(aug[r][r]) < 1e-12:
            x[r] = 0.0
            continue
        s = aug[r][m]
        for c in range(r + 1, m):
            s -= aug[r][c] * x[c]
        x[r] = s / aug[r][r]
    return x


def _fit(X, y):
    """Return coefficients [intercept, w1, ..., wp] for the OLS fit."""
    if not X:
        raise ValueError("Training data has no rows")
    A = [[Fraction(1)] + list(row) for row in X]
    if len(A) * len(A[0]) <= _EXACT_CELL_LIMIT:
        try:
            coeffs = _solve_exact(A, y)
        except (ZeroDivisionError, OverflowError):
            coeffs = None
        if coeffs is not None:
            return coeffs
    return _solve_float([list(map(float, row)) for row in A],
                        [float(v) for v in y])


def predict_linear_regression(train_csv, test_csv, target):
    """Fit ordinary least-squares linear regression with an intercept on
    ``train_csv``, predicting column ``target`` from all other columns, and
    return the predictions for each row of ``test_csv`` as a list of floats.

    The target column of ``test_csv`` is ignored.  A ValueError is raised if
    any value that is used is missing or non-numeric.
    """
    if not isinstance(target, str) or target.strip() == "":
        raise ValueError("Target column name must be a non-empty string")
    target = target.strip()

    train_header, train_rows = _parse_csv(train_csv)
    test_header, test_rows = _parse_csv(test_csv)

    if target not in train_header:
        raise ValueError("Target column %r not found in training header" % target)
    if target not in test_header:
        raise ValueError("Target column %r not found in test header" % target)

    feature_names = [name for name in train_header if name != target]
    if not feature_names:
        raise ValueError("No feature columns besides the target column")

    X_train, y_train = _read_train(train_header, train_rows, feature_names, target)
    coeffs = _fit(X_train, y_train)

    X_test = _read_test(test_header, test_rows, feature_names)

    intercept = coeffs[0]
    weights = coeffs[1:]
    predictions = []
    for row in X_test:
        acc = intercept
        for w, x in zip(weights, row):
            acc = acc + w * x
        predictions.append(float(acc))
    return predictions

