import csv
import io


def normalize_csv_columns(csv_text):
    """Normalize every column of a numeric CSV to the [0, 1] range.

    Args:
        csv_text: Text of a CSV file whose first row is a header and whose
            remaining rows contain numeric data.

    Returns:
        A dict mapping each column name to a list of floats (in row order),
        where each column is min-max normalized. Columns whose values are
        all identical map to all zeros.
    """
    if csv_text is None:
        return {}

    # Normalize newlines so csv.reader handles \r\n and \r properly.
    text = csv_text.replace("\r\n", "\n").replace("\r", "\n")
    reader = csv.reader(io.StringIO(text))
    rows = [row for row in reader if row and any(cell.strip() != "" for cell in row)]

    if not rows:
        return {}

    header = [cell.strip() for cell in rows[0]]
    data_rows = rows[1:]

    # Parse numeric values per column.
    columns = {name: [] for name in header}
    for row in data_rows:
        for i, name in enumerate(header):
            raw = row[i].strip() if i < len(row) else ""
            try:
                value = float(raw)
            except (ValueError, TypeError):
                value = 0.0
            columns[name].append(value)

    result = {}
    for name in header:
        values = columns[name]
        if not values:
            result[name] = []
            continue
        low = min(values)
        high = max(values)
        span = high - low
        if span == 0:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [(v - low) / span for v in values]

    return result

