    """Return the text content of ``html`` (tags removed, entities decoded)."""
    try:
        from bs4 import BeautifulSoup
    except ImportError:
        return _text_content_stdlib(html)

    soup = BeautifulSoup(html, "html.parser")
    # get_text() concatenates every text node of the document in document
    # order, with tags and attribute values already excluded and entities
    # already decoded.  Script/style contents are not text content.
    return soup.get_text()


