        def handle_starttag(self, tag, attrs):
            if tag in _NON_TEXT_ELEMENTS:
                self._skip_depth += 1

        def handle_endtag(self, tag):
            if tag in _NON_TEXT_ELEMENTS and self._skip_depth > 0:
                self._skip_depth -= 1

