Self-contained implementation built on the standard library only.
"""

from html.parser import HTMLParser

__all__ = ["extract_article_info"]

# Elements that never have children / closing tags.
_VOID_TAGS = frozenset(
    "area base br col embed hr img input link meta param source track wbr".split()
)


class _Node:
    """A minimal DOM node."""

    __slots__ = ("tag", "attrs", "children", "parent")

    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag
        self.attrs = dict(attrs) if attrs else {}
        self.children = []  # list of _Node or str (text)
        self.parent = parent

    # -- helpers ---------------------------------------------------------
    def classes(self):
        value = self.attrs.get("class")
        if not value:
            return []
        return value.split()

    def iter_elements(self):
        """Yield every descendant element (not including self), in document order."""
        for child in self.children:
            if isinstance(child, _Node):
                yield child
                yield from child.iter_elements()

    def text(self):
        """Concatenated descendant text, with tags removed."""
        parts = []
        for child in self.children:
            if isinstance(child, str):
                parts.append(child)
            else:
                parts.append(child.text())
        return "".join(parts)

    def first(self, tag, cls=None):
        """First descendant element matching the given tag (and optional class)."""
        for el in self.iter_elements():
            if el.tag == tag and (cls is None or cls in el.classes()):
                return el
        return None


