"""Ordinary least-squares linear regression (with intercept) and R^2 scoring.

Self-contained: works with the standard library alone. If NumPy happens to be
available it is used for the least-squares solve; otherwise a pure-Python
pseudo-inverse based on Jacobi eigenvalue iterations is used. Either way the
fit follows the usual "center the data, solve least squares, recover the
intercept" recipe, which yields the minimum-norm solution for rank-deficient
designs (matching scikit-learn's LinearRegression).
"""


def _solve_lstsq_numpy(Xc, yc):
    """Minimum-norm least-squares solve via NumPy; None if NumPy is missing."""
    try:
        import numpy as np
    except Exception:
        return None
    try:
        A = np.asarray(Xc, dtype=float)
        b = np.asarray([float(v) for v in yc], dtype=float)
        if A.size == 0:
            return []
        coef = np.linalg.lstsq(A, b, rcond=None)[0]
        return [float(v) for v in coef]
    except Exception:
        return None


def _jacobi_eigen(A, max_sweeps=100):
    """Eigen-decomposition of a symmetric matrix via cyclic Jacobi rotations.

    Returns (eigenvalues, V) where V[k][i] is the k-th component of the i-th
    eigenvector (columns of V are the eigenvectors).
    """
    n = len(A)
    a = [[float(A[i][j]) for j in range(n)] for i in range(n)]
    V = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    if n <= 1:
        return [a[0][0]] if n == 1 else [], V
    for _ in range(max_sweeps):
        off = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                off += a[i][j] * a[i][j]
        if off <= 1e-30:
            break
        for p in range(n - 1):
            for q in range(p + 1, n):
                apq = a[p][q]
                if abs(apq) < 1e-300:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * apq)
                if theta >= 0:
                    t = 1.0 / (theta + (theta * theta + 1.0) ** 0.5)
                else:
                    t = -1.0 / (-theta + (theta * theta + 1.0) ** 0.5)
                c = 1.0 / (t * t + 1.0) ** 0.5
                s = t * c
                for k in range(n):
                    akp, akq = a[k][p], a[k][q]
                    a[k][p] = c * akp - s * akq
                    a[k][q] = s * akp + c * akq
                for k in range(n):
                    apk, aqk = a[p][k], a[q][k]
                    a[p][k] = c * apk - s * aqk
                    a[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp, vkq = V[k][p], V[k][q]
                    V[k][p] = c * vkp - s * vkq
                    V[k][q] = s * vkp + c * vkq
    return [a[i][i] for i in range(n)], V


def _solve_lstsq_pure(Xc, yc):
    """Pure-Python minimum-norm least-squares solve (pseudo-inverse of the
    normal equations via a Jacobi eigen-decomposition)."""
    n = len(Xc[0]) if Xc else 0
    if n == 0:
        return []
    XtX = [[0.0] * n for _ in range(n)]
    Xty = [0.0] * n
    for row, yi in zip(Xc, yc):
        yi = float(yi)
        for i in range(n):
            ri = row[i]
            if ri == 0.0:
                continue
            Xty[i] += ri * yi
            xi = XtX[i]
            for j in range(i, n):
                xi[j] += ri * row[j]
    for i in range(n):
        for j in range(i):
            XtX[i][j] = XtX[j][i]

    eigenvalues, V = _jacobi_eigen(XtX)
    lam_max = max(eigenvalues) if eigenvalues else 0.0
    if lam_max <= 0.0:
        return [0.0] * n
    tol = lam_max * n * 2.220446049250313e-16 * 10.0
    coef = [0.0] * n
    for i in range(n):
        lam = eigenvalues[i]
        if lam <= tol:
            continue
        dot = 0.0
        for k in range(n):
            dot += V[k][i] * Xty[k]
        c = dot / lam
        if c != 0.0:
            for k in range(n):
                coef[k] += c * V[k][i]
    return coef


def _fit_ols(X, y):
    """Fit OLS with intercept. Returns [intercept, coef_1, ..., coef_p]."""
    n_samples = len(X)
    n_features = len(X[0]) if n_samples else 0
    X = [[float(v) for v in row] for row in X]
    y = [float(v) for v in y]

    if n_features == 0:
        return [sum(y) / n_samples]

    x_mean = [sum(row[j] for row in X) / n_samples for j in range(n_features)]
    y_mean = sum(y) / n_samples
    Xc = [[row[j] - x_mean[j] for j in range(n_features)] for row in X]
    yc = [v - y_mean for v in y]

    coef = _solve_lstsq_numpy(Xc, yc)
    if coef is None:
        coef = _solve_lstsq_pure(Xc, yc)
    intercept = y_mean - sum(x_mean[j] * coef[j] for j in range(n_features))
    return [intercept] + list(coef)


def _predict(X, beta):
    n_features = len(beta) - 1
    preds = []
    for row in X:
        s = beta[0]
        for j in range(n_features):
            s += beta[j + 1] * float(row[j])
        preds.append(s)
    return preds


def _r2_score(y_true, y_pred):
    n = len(y_true)
    if n == 0:
        # No test samples: nothing to explain.
        return 1.0
    y_true = [float(v) for v in y_true]
    mean = sum(y_true) / n
    ss_tot = 0.0
    ss_res = 0.0
    for true, pred in zip(y_true, y_pred):
        d = true - mean
        ss_tot += d * d
        e = true - pred
        ss_res += e * e
    if ss_tot == 0.0:
        # Constant target: 1.0 when predictions are perfect, else 0.0.
        return 1.0 if ss_res == 0.0 else 0.0
    return 1.0 - ss_res / ss_tot


def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    """Fit an ordinary least-squares linear regression (with intercept) on the
    training data and return its R^2 score on the test data as a float.

    Raises ValueError if the training set is empty, or if either X list and its
    matching y list have different lengths.
    """
    train_X = list(train_X) if train_X is not None else []
    test_X = list(test_X) if test_X is not None else []
    train_y = list(train_y) if train_y is not None else []
    test_y = list(test_y) if test_y is not None else []

    if len(train_X) == 0:
        raise ValueError("training set is empty: train_X has no rows")
    if len(train_X) != len(train_y):
        raise ValueError(
            "train_X and train_y have different lengths: %d != %d"
            % (len(train_X), len(train_y))
        )
    if len(test_X) != len(test_y):
        raise ValueError(
            "test_X and test_y have different lengths: %d != %d"
            % (len(test_X), len(test_y))
        )

    n_features = len(train_X[0]) if train_X else 0
    for row in train_X:
        if len(row) != n_features:
            raise ValueError("train_X rows have inconsistent numbers of features")
    for row in test_X:
        if len(row) != n_features:
            raise ValueError(
                "test_X rows must have the same number of features as train_X"
            )

    beta = _fit_ols(train_X, train_y)
    preds = _predict(test_X, beta)
    return float(_r2_score(test_y, preds))

