"""Compute per-key mean and median of numeric values in a JSON list of records."""

import json


def _is_number(value):
    """Return True if value is a JSON number (int/float, but not bool)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _median(sorted_values):
    """Median of an already sorted list of numbers (as a float)."""
    n = len(sorted_values)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_values[mid])
    return (sorted_values[mid - 1] + sorted_values[mid]) / 2.0


def key_mean_median(json_text):
    """Return {'key': {'mean': ..., 'median': ...}} for every key in the records.

    ``json_text`` is a JSON string holding a list of objects (records).  For each
    key that appears in any record, the mean and median of that key's numeric
    values are computed.  Missing, null and non-numeric values are ignored.
    Keys with no numeric values at all map to {'mean': None, 'median': None}.
    An empty list yields an empty dict.
    """
    # Be tolerant if an already-parsed structure is passed in.
    if isinstance(json_text, (list, tuple)):
        records = json_text
    else:
        records = json.loads(json_text)

    if not isinstance(records, (list, tuple)):
        return {}

    values_by_key = {}
    for record in records:
