# Mapping from (normalized) column names to the index of the value in a
# weather observation row: [date, temperature, humidity, wind_speed, precip]
_COLUMN_INDEX = {
    "temperature": 1,
    "humidity": 2,
    "windspeed": 3,
    "wind": 3,
    "precipitation": 4,
    "precip": 4,
    "rain": 4,
}

# Canonical names as they may appear in the data rows (used for dict-like rows)
_COLUMN_KEYS = {
    "temperature": "Temperature",
    "humidity": "Humidity",
    "windspeed": "Wind Speed",
    "precipitation": "Precipitation",
}


def _normalize_column(column):
    """Normalize a column name (case/space/underscore insensitive)."""
    if not isinstance(column, str):
        raise ValueError("column must be a string, got %r" % (column,))
    key = "".join(ch for ch in column.strip().lower() if ch.isalnum())
    if key not in _COLUMN_INDEX:
        raise ValueError(
            "unknown column %r; expected one of 'Temperature', 'Humidity', "
            "'Wind Speed' or 'Precipitation'" % (column,)
        )
    return key


def _extract(row, key, index):
    """Extract the value of the requested column from a single observation."""
    if isinstance(row, dict):
        if key in row:
            return row[key]
        canonical = _COLUMN_KEYS[key]
        if canonical in row:
            return row[canonical]
        for candidate, value in row.items():
            if _normalize_column(candidate) == key:
                return value
        raise KeyError("column %r not found in row %r" % (canonical, row))
    # Sequence-like row: [date, temperature, humidity, wind_speed, precip]
    return row[index]


def _histogram(values, low, high):
    """Counts of values in 10 equal-width bins spanning [low, high].

    The last bin includes the maximum value.
    """
    histogram = [0] * 10
    if high == low:
        # Degenerate range: every value equals both the minimum and the
        # maximum, so they all fall in the last (maximum-inclusive) bin.
        for _ in values:
            histogram[9] += 1
        return histogram
    width = (high - low) / 10.0
    for value in values:
        if value >= high:
            index = 9
        else:
            index = int((value - low) / width)
            if index < 0:
                index = 0
            elif index > 9:
                index = 9
        histogram[index] += 1
    return histogram


def weather_column_summary(column, data):
    """Summarize one column of a list of weather observations.

    Each observation is ``[date, temperature, humidity, wind_speed,
    precipitation]`` with the date as a 'YYYY-MM-DD' string.  ``column`` is
    one of 'Temperature', 'Humidity', 'Wind Speed' or 'Precipitation'.

    Returns a dict with 'sum', 'mean', 'min', 'max' and 'histogram' (the
    counts of the values in 10 equal-width bins spanning the column's
    minimum to its maximum, the last bin including the maximum).
    """
    key = _normalize_column(column)
    index = _COLUMN_INDEX[key]

    values = []
    if data is not None:
        for row in data:
            value = _extract(row, key, index)
            if value is None:
                continue
            values.append(value)

    if not values:
        return {
            "sum": 0,
            "mean": None,
            "min": None,
            "max": None,
            "histogram": [0] * 10,
        }

    total = sum(values)
    low = min(values)
    high = max(values)

    return {
        "sum": total,
        "mean": total / len(values),
        "min": low,
        "max": high,
        "histogram": _histogram(values, low, high),
    }

