"""Association chi-square between two id/category lists."""


def _index(pairs):
    """Map id -> list of categories (in order of appearance)."""
    idx = {}
    for rec in pairs:
        # Accept any sequence of length >= 2 (list, tuple, ...)
        key = rec[0]
        cat = rec[1]
        idx.setdefault(key, []).append(cat)
    return idx


def _contingency(left, right):
    """Cross-tabulate left categories (rows) against right categories (cols)
    over the records whose id appears in both lists."""
    li = _index(left)
    ri = _index(right)

    rows = []  # ordered unique left categories
    cols = []  # ordered unique right categories
    row_of = {}
    col_of = {}
    counts = {}

    for key in li:
        if key not in ri:
            continue
        for lcat in li[key]:
            for rcat in ri[key]:
                if lcat not in row_of:
                    row_of[lcat] = len(rows)
                    rows.append(lcat)
                if rcat not in col_of:
                    col_of[rcat] = len(cols)
                    cols.append(rcat)
                i = row_of[lcat]
                j = col_of[rcat]
                counts[(i, j)] = counts.get((i, j), 0) + 1

    table = [[counts.get((i, j), 0) for j in range(len(cols))]
             for i in range(len(rows))]
    return table


def association_chi_square(left, right):
    """Join `left` and `right` (lists of ``[id, category]`` pairs) on id and
    compute the Pearson chi-square statistic of independence (no continuity
    correction) for the resulting contingency table.

    Returns ``(statistic, dof)`` where ``dof`` is an ``int``.
    """
    table = _contingency(left, right)

    n_rows = len(table)
    n_cols = len(table[0]) if n_rows else 0

    dof = (n_rows - 1) * (n_cols - 1)
    if dof < 0:
        dof = 0
    dof = int(dof)

    total = sum(sum(r) for r in table)
    if total == 0 or n_rows == 0 or n_cols == 0:
        return (0.0, 0)

    row_sums = [sum(r) for r in table]
    col_sums = [sum(table[i][j] for i in range(n_rows)) for j in range(n_cols)]

    # Drop degenerate (all-zero) rows/columns, if any, from the dof/statistic.
    stat = 0.0
    for i in range(n_rows):
        if row_sums[i] == 0:
            continue
        for j in range(n_cols):
            if col_sums[j] == 0:
                continue
            expected = row_sums[i] * col_sums[j] / total
            if expected <= 0:
                continue
            diff = table[i][j] - expected
            stat += diff * diff / expected

    # Recompute dof ignoring empty rows/cols (cannot happen with the
    # construction above, but kept for safety).
    eff_rows = sum(1 for s in row_sums if s > 0)
    eff_cols = sum(1 for s in col_sums if s > 0)
    dof = int(max(0, (eff_rows - 1) * (eff_cols - 1)))

    return (float(stat), dof)

