from datetime import datetime, timezone as _dt_timezone
from zoneinfo import ZoneInfo

__all__ = ["publication_hour_stats"]


def _parse_published_time(value):
    """Parse an ISO 8601 timestamp (with UTC offset) into an aware datetime."""
    if isinstance(value, datetime):
        dt = value
    else:
        if not isinstance(value, str):
            raise ValueError(
                "published_time must be an ISO 8601 string, got %r" % (value,)
            )
        text = value.strip()
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(text)
        except ValueError:
            raise ValueError("invalid ISO 8601 published_time: %r" % (value,))
    if dt.tzinfo is None:
        # No offset given: assume UTC.
        dt = dt.replace(tzinfo=_dt_timezone.utc)
    return dt


def publication_hour_stats(articles, timezone):
    """Compute per-category statistics of publication hours in ``timezone``.

    Args:
        articles: list of dicts, each with a ``category`` and a
            ``published_time`` (ISO 8601 string with a UTC offset).
        timezone: an IANA timezone name, e.g. ``"America/New_York"``.

    Returns:
        A dict mapping each category to a dict with the ``count``, ``mean``,
        ``min`` and ``max`` of the publication hours (in ``timezone``).

    Raises:
        ValueError: if ``articles`` is empty, if an article is missing either
            the ``category`` or the ``published_time`` key, if a timestamp
            cannot be parsed, or if ``timezone`` is not a valid IANA name.
    """
    if articles is None:
        raise ValueError("articles list must not be empty")
    if isinstance(articles, (str, bytes)):
        raise ValueError("articles must be a list of dicts, not a string")
    try:
        articles = list(articles)
    except TypeError:
        raise ValueError("articles must be an iterable of dicts")
    if len(articles) == 0:
        raise ValueError("articles list must not be empty")

    try:
        tz = ZoneInfo(timezone)
    except Exception as exc:
        raise ValueError("invalid timezone: %r" % (timezone,)) from exc

    hours_by_category = {}
