"""Pairwise Pearson correlation matrix for a dict of columns."""

import math


def _pearson(xs, ys):
    """Pearson correlation coefficient between two equal-length sequences."""
    n = len(xs)
    if n == 0 or n != len(ys):
        raise ValueError("columns must be non-empty and have equal length")
    if n == 1:
        # A single sample has no variance, so the correlation is undefined.
        return 0.0
    mx = math.fsum(xs) / n
    my = math.fsum(ys) / n
    num = math.fsum([(x - mx) * (y - my) for x, y in zip(xs, ys)])
    varx = math.fsum([(x - mx) ** 2 for x in xs])
    vary = math.fsum([(y - my) ** 2 for y in ys])
    if varx <= 0.0 or vary <= 0.0:
        # Undefined when either column is constant.
        return 0.0
    r = num / math.sqrt(varx * vary)
    # Guard against tiny floating point excursions outside [-1, 1].
    return max(-1.0, min(1.0, r))


def column_correlations(data):
    """Return the pairwise Pearson correlation matrix of the columns.

    ``data`` is a dict mapping column names to equal-length lists of numbers.
    The result is a nested dict ``result[x][y]`` holding the Pearson
    correlation between columns ``x`` and ``y`` for every ordered pair of
    columns, including each column with itself (which is 1.0).
    """
    columns = list(data.keys())
    values = {name: list(data[name]) for name in columns}
    lengths = {len(v) for v in values.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    result = {}
    for x in columns:
        row = {}
        for y in columns:
            if x == y:
                # A column is perfectly correlated with itself.
                row[y] = 1.0
            else:
                row[y] = _pearson(values[x], values[y])
        result[x] = row
    return result

