"""Utilities for parsing and sorting CSV text."""

import csv
import io
import math


def _is_blank(value):
    return value is None or str(value).strip() == ""


def _parse_number(text):
    """Return the number represented by ``text``, or ``None`` if it isn't one.

    Integers are returned as ``int`` and everything else as ``float``.
    """
    if text is None:
        return None
    s = str(text).strip()
    if s == "":
        return None
    # int() accepts things like "+3", "-3", "  7  " and underscores ("1_000")
    # which we do not want to treat as plain CSV numbers, so guard with a
    # simple character check first.
    body = s[1:] if s[0] in "+-" else s
    if body == "" or not all(ch.isdigit() or ch == "." for ch in body):
        try:
            value = float(s)
        except ValueError:
            return None
    else:
        try:
            return int(s)
        except ValueError:
            try:
                value = float(s)
            except ValueError:
                return None
    if isinstance(value, float) and math.isnan(value):
        return None
    return value


def _column_is_numeric(values):
    """True if every non-blank value in the column is numeric."""
    saw_value = False
    for value in values:
        if _is_blank(value):
            continue
        if _parse_number(value) is None:
            return False
        saw_value = True
    return saw_value


def _convert(value, numeric):
    """Convert a raw cell to its output type."""
    if not numeric:
        return value
    if _is_blank(value):
        return ""
    return _parse_number(value)


def sort_csv_rows(csv_text, sort_by_column="title"):
    """Parse ``csv_text`` and return its data rows sorted by a column.

    The first row of ``csv_text`` is treated as the header.  The result is a
    list of dicts (one per data row) mapping column names to values.  Columns
    whose values are all numeric are returned as numbers (and sorted
    numerically); every other column is returned as a string.

    Rows are sorted in ascending order by ``sort_by_column`` using a stable
    sort, so rows with equal keys keep their original relative order.
    """
    if csv_text is None:
        return []
    if isinstance(csv_text, bytes):
        csv_text = csv_text.decode("utf-8-sig")
    text = str(csv_text)
    if text and text[0] == "\ufeff":
        text = text[1:]

    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        return []

    header = [name.strip() for name in header]
    if not any(header):
        # No real header row (empty or blank-only input).
        return []
    if isinstance(sort_by_column, int) and not isinstance(sort_by_column, bool):
        # Also allow referring to a column by its (0-based) position.
        if not 0 <= sort_by_column < len(header):
            raise ValueError(
                "column index %r is out of range (columns: %r)"
                % (sort_by_column, header)
            )
        sort_index = sort_by_column
    else:
        if sort_by_column not in header:
            raise ValueError(
                "sort_by_column %r is not a column of the CSV (columns: %r)"
                % (sort_by_column, header)
            )
        sort_index = header.index(sort_by_column)

    raw_rows = []
    for record in reader:
        if not record:  # skip completely blank lines
            continue
        # Pad short rows / drop extra cells so every row matches the header.
        if len(record) < len(header):
            record = list(record) + [""] * (len(header) - len(record))
        elif len(record) > len(header):
            record = record[: len(header)]
        raw_rows.append(record)

    numeric = [
        _column_is_numeric([row[i] for row in raw_rows]) for i in range(len(header))
    ]

    rows = [
        {header[i]: _convert(row[i], numeric[i]) for i in range(len(header))}
        for row in raw_rows
    ]

    def sort_key(row):
        value = row[header[sort_index]]
        if numeric[sort_index]:
            # Numeric column: sort numerically (blanks sort last).
            if isinstance(value, (int, float)):
                return (0, value)
            return (1, 0)
        return (0, "" if value is None else str(value))

    rows.sort(key=sort_key)
    return rows

