def format_sorted_dict_table(my_dict):
    """Return a plain-text ASCII table of the dict's items, sorted by key.

    Two columns headed 'Key' and 'Value', with '+'/'-'/'|' borders,
    rules above and below the header and at the bottom, centered cells
    and one space of padding on each side of every cell.
    """
    try:
        items = sorted(my_dict.items(), key=lambda kv: kv[0])
    except TypeError:
        # Keys of mixed, mutually non-comparable types: fall back to a
        # stable ordering by type name then by string representation.
        items = sorted(
            my_dict.items(),
            key=lambda kv: (type(kv[0]).__name__, str(kv[0])),
        )

    key_header = "Key"
    value_header = "Value"

    key_width = max([len(key_header)] + [len(str(k)) for k, _ in items])
    value_width = max([len(value_header)] + [len(str(v)) for _, v in items])

    def rule():
        return "+%s+%s+" % ("-" * (key_width + 2), "-" * (value_width + 2))

    def row(key_text, value_text):
        return "| %s | %s |" % (
            key_text.center(key_width),
            value_text.center(value_width),
        )

    lines = [
        rule(),
        row(key_header, value_header),
        rule(),
    ]
    for key, value in items:
        lines.append(row(str(key), str(value)))
    lines.append(rule())

    return "\n".join(lines)

