"""Self-contained implementation of ``normalized_cumulative_sums``."""

import math
import numbers


def _validate_column(name, column):
    """Validate a single column and return it as a list.

    Raises:
        TypeError: if the column is not iterable or contains non-numeric values.
        ValueError: if the column contains NaN.
    """
    if isinstance(column, (str, bytes)) or not hasattr(column, "__iter__"):
        raise TypeError(
            "column {!r} must be a list of numbers, got {!r}".format(name, column)
        )

    values = list(column)

    for value in values:
        # bool is a subclass of int, complex is not a real number: reject
        # anything that is not a real (i.e. orderable/scalable) number.
        if not isinstance(value, numbers.Real):
            raise TypeError(
                "column {!r} contains a non-numeric value: {!r}".format(name, value)
            )
        try:
            if math.isnan(value):
                raise ValueError(
                    "column {!r} contains NaN: {!r}".format(name, value)
                )
        except TypeError:
            # Not convertible to float (e.g. some exotic numeric type);
            # it is still a real number, so let it pass.
            pass

    return values


def normalized_cumulative_sums(data):
    """Min-max normalize the running cumulative sum of every column.

    Args:
        data: dict mapping column names to equal-length lists of numbers.

    Returns:
        dict mapping each column name to a list of floats in [0, 1], where the
        values are the column's cumulative sums min-max scaled to [0, 1].
        A column whose cumulative sum is constant maps to all zeros.

    Raises:
        TypeError: if any column contains non-numeric values.
        ValueError: if the data is empty or contains NaN.
    """
    if not isinstance(data, dict):
        raise TypeError(
            "data must be a dict mapping column names to lists of numbers, "
            "got {!r}".format(type(data).__name__)
        )

    if not data:
        raise ValueError("data is empty")

    columns = {}
    lengths = set()
    for name, column in data.items():
        values = _validate_column(name, column)
        columns[name] = values
        lengths.add(len(values))

    if any(length == 0 for length in lengths):
        raise ValueError("data is empty: column has no values")

    if len(lengths) > 1:
        raise ValueError("all columns must have equal lengths")

    result = {}
    for name, values in columns.items():
        cumulative = []
        total = 0
        for value in values:
            total = total + value
            cumulative.append(total)

        low = min(cumulative)
        high = max(cumulative)

        if high == low:
            # Constant cumulative sum -> all zeros.
            result[name] = [0.0] * len(cumulative)
        else:
            span = high - low
            result[name] = [float((value - low) / span) for value in cumulative]

    return result

