"""Utility for computing cumulative (running) sums down the numeric columns of a table."""

from numbers import Number


def _is_number(value):
    """Return True if `value` is a real numeric value (booleans excluded)."""
    return isinstance(value, Number) and not isinstance(value, bool)


def cumulative_column_sums(data):
    """Return the running (cumulative) sum down each numeric column of `data`.

    `data` is a dict mapping column names to equal-length lists of values.
    Columns whose values are not all numbers are ignored. The result is a dict
    mapping each numeric column name to its list of cumulative sums, preserving
    the original column order.

    Raises:
        ValueError: if the table has no rows or no numeric columns.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists of values")

    # Determine the number of rows (all columns are assumed equal-length).
    n_rows = None
    for column in data.values():
        try:
            length = len(column)
        except TypeError:
            raise ValueError("each column must be a list of values")
        if n_rows is None:
            n_rows = length
        elif length != n_rows:
            raise ValueError("all columns must have the same length")

    if not n_rows:
        raise ValueError("table has no rows")

    result = {}
    for name, column in data.items():
        values = list(column)
        if not all(_is_number(v) for v in values):
            continue
        cumulative = []
        running = 0
        for value in values:
            running = running + value
            cumulative.append(running)
        result[name] = cumulative

    if not result:
        raise ValueError("table has no numeric columns")

    return result

