import ast
import csv
import io
from statistics import pstdev


def _parse_numbers(raw):
    """Parse a Python-style list-of-numbers string into a list of numbers."""
    if raw is None:
        return []
    text = raw.strip()
    if not text:
        return []
    try:
        value = ast.literal_eval(text)
    except (ValueError, SyntaxError):
        # Fallback: manual comma-separated parsing.
        if text.startswith("[") and text.endswith("]"):
            text = text[1:-1]
        nums = []
        for token in text.split(","):
            token = token.strip()
            if not token:
                continue
            try:
                nums.append(int(token))
            except ValueError:
                nums.append(float(token))
        return nums
    if isinstance(value, (list, tuple)):
        return list(value)
    return [value]


def summarize_email_lists(csv_text):
    """Summarize rows of a CSV with 'email' and 'list' columns.

    Each 'list' value is a Python-style list of numbers written as a string,
    e.g. "[1, 2, 3]". Returns a list of (email, sum, mean, std) tuples, one
    per data row in file order, where std is the population standard
    deviation of that row's numbers.
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return []
    header = [h.strip().lower() for h in rows[0]]
    try:
        email_idx = header.index("email")
        list_idx = header.index("list")
    except ValueError:
        # Fall back to positional columns (email first, list second).
        email_idx, list_idx = 0, 1

    results = []
    for row in rows[1:]:
        if not row or all(cell.strip() == "" for cell in row):
            continue
        email = row[email_idx] if email_idx < len(row) else None
        raw = row[list_idx] if list_idx < len(row) else None
        nums = _parse_numbers(raw)
        total = sum(nums)
        if nums:
            mean = total / len(nums)
            std = pstdev(nums)
        else:
            mean = 0.0
            std = 0.0
        results.append((email, total, float(mean), float(std)))
    return results

