    """Turn a Clark-notation name (``{uri}local``) into the written tag/attr."""
    if isinstance(name, str) and name.startswith("{") and "}" in name:
        uri, local = name[1:].split("}", 1)
        prefix = prefixes.get(uri)
        if prefix:
            return prefix + ":" + local
        return local
    return name


