"""Row averages and pairwise Pearson correlation matrix of a table."""

from decimal import Decimal
from numbers import Real


def _is_number(value):
    """True if value is a real number (bools are not treated as numbers)."""
    if isinstance(value, bool):
        return False
    return isinstance(value, (Real, Decimal))


def _validate(data):
    """Validate that data is a rectangular list of rows of numbers."""
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows of numbers")
    if len(data) == 0:
        raise ValueError("data must contain at least one row")
    for row in data:
        if not isinstance(row, list):
            raise ValueError("each row must be a list of numbers")
        for value in row:
            if not _is_number(value):
                raise ValueError("each row must contain only numbers")
    width = len(data[0])
    if width == 0:
        raise ValueError("rows must contain at least one value")
    for row in data:
        if len(row) != width:
            raise ValueError("data must be rectangular (all rows have the same length)")
    return width


def row_averages_and_correlations(data):
    """Return ``(averages, corr)`` for a rectangular table of numbers.

    ``averages[i]`` is the mean of row ``i`` (in row order).
    ``corr[i][j]`` is the Pearson correlation between column ``i`` and
    column ``j``.
    """
    n_cols = _validate(data)
    n_rows = len(data)

    # Work with plain floats internally.
    rows = [[float(value) for value in row] for row in data]

    # Row averages.
    averages = [sum(row) / n_cols for row in rows]

    # Column sums / sums of squares / cross products.
    col_sum = [0.0] * n_cols
    col_sq = [0.0] * n_cols
    for row in rows:
        for c in range(n_cols):
            v = row[c]
            col_sum[c] += v
            col_sq[c] += v * v

    cross = [[0.0] * n_cols for _ in range(n_cols)]
    for row in rows:
        for i in range(n_cols):
            vi = row[i]
            for j in range(i, n_cols):
                cross[i][j] += vi * row[j]

    n = n_rows
    corr = [[0.0] * n_cols for _ in range(n_cols)]
    for i in range(n_cols):
        num_i = n * col_sq[i] - col_sum[i] * col_sum[i]
        for j in range(i, n_cols):
            if i == j:
                # A column always correlates perfectly with itself.
                corr[i][j] = 1.0
                continue
            num_j = n * col_sq[j] - col_sum[j] * col_sum[j]
            if num_i <= 0 or num_j <= 0:
                value = 0.0
            else:
                cov = n * cross[i][j] - col_sum[i] * col_sum[j]
                value = cov / ((num_i * num_j) ** 0.5)
                # Guard against tiny floating point overshoot.
                if value > 1.0:
                    value = 1.0
                elif value < -1.0:
                    value = -1.0
            corr[i][j] = value
            corr[j][i] = value
    return averages, corr

