def _flatten(L):
    """Recursively yield all the numbers contained in a nested sequence."""
    for item in L:
        if isinstance(item, (list, tuple, set, frozenset)) or (
            hasattr(item, "__iter__") and not isinstance(item, (str, bytes))
        ):
            yield from _flatten(item)
        else:
            yield item


def _quantile(sorted_data, q):
    """Quantile of sorted data using linear interpolation (numpy default)."""
    n = len(sorted_data)
    if n == 0:
        raise ValueError("cannot compute a quantile of empty data")
    if n == 1:
        return float(sorted_data[0])
    pos = (n - 1) * q
    lower = int(pos // 1)
    upper = min(lower + 1, n - 1)
    frac = pos - lower
    return float(sorted_data[lower]) * (1.0 - frac) + float(sorted_data[upper]) * frac


def interquartile_range_nested(L):
    """Return the interquartile range (Q3 - Q1) of all numbers in L as a float.

    L is a list of lists of numbers.  All numbers are pooled together and
    quartiles are computed with linear interpolation between data points
    (the usual default, e.g. numpy's ``percentile`` with method='linear').
    """
    data = sorted(float(x) for x in _flatten(L))
    if not data:
        return 0.0
    q1 = _quantile(data, 0.25)
    q3 = _quantile(data, 0.75)
    return float(q3 - q1)

