"""Ordinary least-squares linear regression with an intercept.

Self-contained: only the standard library is required (numpy is used for the
solve when available, purely as a numerical fallback for large/ill-conditioned
problems).
"""

from fractions import Fraction


def _solve_exact(A, b):
    """Solve A x = b exactly with Fractions (Gaussian elimination).

    Returns None if the system is singular (rank deficient)."""
    n = len(A)
    M = [[Fraction(A[i][j]) for j in range(n)] + [Fraction(b[i])] for i in range(n)]
    for col in range(n):
        piv = None
        for r in range(col, n):
            if M[r][col] != 0:
                piv = r
                break
        if piv is None:
            return None  # singular
        if piv != col:
            M[col], M[piv] = M[piv], M[col]
        pv = M[col][col]
        for r in range(col + 1, n):
            if M[r][col] == 0:
                continue
            f = M[r][col] / pv
            for c in range(col, n + 1):
                M[r][c] -= f * M[col][c]
    x = [Fraction(0)] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n] - sum(M[i][j] * x[j] for j in range(i + 1, n))
        x[i] = s / M[i][i]
    return x


def _solve_float(A, b):
    """Solve A x = b in floats with partial pivoting; singular directions -> 0."""
    n = len(A)
    if n == 0:
        return []
    M = [[float(A[i][j]) for j in range(n)] + [float(b[i])] for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col]) < 1e-12:
            continue
        if piv != col:
            M[col], M[piv] = M[piv], M[col]
        pv = M[col][col]
        for r in range(col + 1, n):
            f = M[r][col] / pv
            if f == 0.0:
                continue
            for c in range(col, n + 1):
                M[r][c] -= f * M[col][c]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        if abs(M[i][i]) < 1e-12:
            x[i] = 0.0
            continue
        s = M[i][n] - sum(M[i][j] * x[j] for j in range(i + 1, n))
        x[i] = s / M[i][i]
    return x


def fit_linear_regression(records, target='z'):
    """Fit an OLS linear regression with an intercept.

    records: list of dicts, all sharing the same numeric keys.
    target:  the key to predict; every other key is a predictor.

    Returns (intercept, {predictor_key: coefficient}).
    """
    records = list(records)
    if not records:
        return 0.0, {}

    keys = list(records[0].keys())
    if target in keys:
        keys.remove(target)
    predictors = keys

    n = len(records)
    p = len(predictors)
    m = p + 1  # design matrix columns (intercept + predictors)

    X = [[1] + [r[k] for k in predictors] for r in records]
    y = [r[target] for r in records]

    # Normal equations: (X^T X) beta = X^T y
    XtX = [[sum(X[i][a] * X[i][b] for i in range(n)) for b in range(m)] for a in range(m)]
    Xty = [sum(X[i][a] * y[i] for i in range(n)) for a in range(m)]

    sol = None
    # Exact rational solve when the problem is small enough (gives exact
    # answers for e.g. integer data).
    if n * m * m <= 2_000_000:
        try:
            sol = _solve_exact(XtX, Xty)
        except Exception:
            sol = None

    if sol is None:
        # Numerically robust fallback: numpy lstsq, then plain float solve.
        try:
            import numpy as np

            A = np.asarray(X, dtype=float)
            b = np.asarray(y, dtype=float)
            s, _, _, _ = np.linalg.lstsq(A, b, rcond=None)
            sol = [float(v) for v in s]
        except Exception:
            sol = _solve_float(XtX, Xty)

    intercept = float(sol[0])
    coefficients = {k: float(sol[i + 1]) for i, k in enumerate(predictors)}
    return intercept, coefficients

