"""Self-contained solution: fill missing CSV cells with the column mean."""

import csv
import io
import math


def _is_empty(cell):
    """A cell is missing when it is empty (or whitespace only)."""
    return cell is None or str(cell).strip() == ""


def _to_float(cell):
    """Return the float value of a cell, or None if it is not a finite number."""
    try:
        value = float(str(cell).strip())
    except (TypeError, ValueError):
        return None
    if math.isnan(value) or math.isinf(value):
        return None
    return value


def fill_missing_with_column_mean(csv_text):
    """Parse CSV text into a dict of column name -> list of values.

    Numeric columns (columns whose present values all parse as floats) hold
    floats; their empty cells are replaced by the mean of the present values
    of that column.  Other columns hold strings, with empty cells becoming
    None.  A column with no present values at all becomes all None.  Empty
    input yields an empty dict.
    """
    if csv_text is None:
        return {}
    text = str(csv_text)
    if text.startswith("\ufeff"):
        text = text[1:]
    if not text.strip():
        return {}

    rows = list(csv.reader(io.StringIO(text)))
    if not rows:
        return {}

    header = list(rows[0])
    width = len(header)

    # Normalise data rows to exactly `width` cells.
    data = []
    for row in rows[1:]:
        if len(row) < width:
            row = list(row) + [""] * (width - len(row))
        elif len(row) > width:
            row = list(row)[:width]
        data.append(row)

    # Column-major view, indexed by column position.
    columns = [list(col) for col in zip(*data)] if data else [[] for _ in header]

    result = {}
    for index, name in enumerate(header):
        cells = columns[index] if index < len(columns) else []
        present = [c for c in cells if not _is_empty(c)]

        numeric_values = []
        is_numeric = True
        for cell in present:
            value = _to_float(cell)
            if value is None:
                is_numeric = False
                break
            numeric_values.append(value)

        if not is_numeric:
            result[name] = [c if not _is_empty(c) else None for c in cells]
        elif numeric_values:
            mean = sum(numeric_values) / len(numeric_values)
            result[name] = [mean if _is_empty(c) else float(_to_float(c)) for c in cells]
        else:
            # Column has no values at all.
            result[name] = [None for _ in cells]

    return result

