"""Table preprocessing: value replacement, categorical encoding, standardization."""

import statistics


def _hashable(v):
    try:
        hash(v)
        return True
    except TypeError:
        return False


def _key_of(v):
    """Return a hashable key identifying the value ``v``."""
    return v if _hashable(v) else repr(v)


def _sorted_distinct(values):
    """Return the distinct values of ``values`` in sorted order."""
    distinct = []
    seen = set()
    for v in values:
        k = _key_of(v)
        if k not in seen:
            seen.add(k)
            distinct.append(v)
    try:
        return sorted(distinct)
    except TypeError:
        # Mixed types that cannot be compared directly: sort strings first
        # (by value), then the remaining values ordered by their repr.
        return sorted(
            distinct,
            key=lambda x: (0, x) if isinstance(x, str) else (1, repr(x)),
        )


def _standardize(values):
    """Subtract the mean and divide by the sample standard deviation (ddof=1)."""
    n = len(values)
    if n == 0:
        return []
    vals = [float(v) for v in values]
    if n < 2:
        return [0.0 for _ in vals]
    mean = float(statistics.mean(vals))
    std = float(statistics.stdev(vals))
    if std == 0.0:
        # Constant column: every deviation is zero.
        return [0.0 for _ in vals]
    return [(x - mean) / std for x in vals]


def encode_and_standardize(data, replacements):
    """Preprocess a table given as a dict of column name -> list of values.

    Steps:
      1. Replace every value that is a key of ``replacements`` with the value
         it maps to.
      2. Every column that contains strings is turned into integer codes
         0..k-1, numbering the distinct values in sorted order.
      3. Every column is standardized by subtracting its mean and dividing by
         its sample standard deviation (ddof=1).

    Returns a dict mapping each column name to its list of standardized
    floats, with the columns in the original order.

    Raises ValueError if ``data`` is not a dict.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")

    replacements = replacements or {}

    result = {}
    for name, column in data.items():
        values = list(column) if column is not None else []

        # 1. replace values that appear as keys in ``replacements``
        replaced = [
            replacements[_key_of(v)] if _key_of(v) in replacements else v
            for v in values
        ]

        # 2. encode columns containing strings as integer codes
        if any(isinstance(v, str) for v in replaced):
            order = _sorted_distinct(replaced)
            mapping = {_key_of(v): i for i, v in enumerate(order)}
            encoded = [mapping[_key_of(v)] for v in replaced]
        else:
            encoded = [float(v) for v in replaced]

        # 3. standardize the column
        result[name] = _standardize(encoded)

    return result

