Each row is ``[date, open, high, low, close, volume]`` where ``date`` is a
string.  ``summarize_stock_column`` returns descriptive statistics for one of
the numeric columns.
"""

_VALID_COLUMNS = ('Open', 'High', 'Low', 'Close', 'Volume')

# Mapping of column name -> index inside a row.
_COLUMN_INDEX = {
    'Open': 1,
    'High': 2,
    'Low': 3,
    'Close': 4,
    'Volume': 5,
}


def _quantile(sorted_values, q):
    """Linear interpolation quantile (numpy/pandas 'linear' method)."""
    n = len(sorted_values)
    if n == 0:
        return None
    if n == 1:
        return float(sorted_values[0])
    pos = (n - 1) * q
    lower = int(pos // 1)
    if lower >= n - 1:
        return float(sorted_values[n - 1])
    frac = pos - lower
    return float(sorted_values[lower] + (sorted_values[lower + 1] - sorted_values[lower]) * frac)


def summarize_stock_column(column, data):
    """Return a summary dict for ``column`` over the rows in ``data``.

    Keys: 'count', 'mean', 'std' (sample standard deviation), 'min', '25%',
    '50%', '75%', 'max'.  ``None`` values in the column are ignored.

    Raises ``ValueError`` for an unknown column name or for a row that does
    not have exactly six entries.
    """
    if column not in _COLUMN_INDEX:
        raise ValueError(
            "column must be one of %s, got %r" % (list(_VALID_COLUMNS), column)
        )

    index = _COLUMN_INDEX[column]

    values = []
    for row in data:
        try:
            length = len(row)
        except TypeError:
            raise ValueError("each row must be a sequence of exactly six entries")
        if length != 6:
            raise ValueError(
                "each row must have exactly six entries, got %d" % length
            )
        value = row[index]
        if value is None:
            continue
        values.append(value)

    count = len(values)

    if count == 0:
        return {
            'count': 0,
            'mean': None,
            'std': None,
            'min': None,
            '25%': None,
            '50%': None,
            '75%': None,
            'max': None,
        }

    ordered = sorted(values)
    total = 0.0
    for v in ordered:
        total += float(v)
    mean = total / count

    if count > 1:
        var = 0.0
        for v in ordered:
            var += (float(v) - mean) ** 2
        var /= (count - 1)  # sample variance (ddof = 1)
        std = var ** 0.5
    else:
        std = 0.0

    return {
        'count': count,
        'mean': float(mean),
        'std': float(std),
        'min': float(ordered[0]),
        '25%': _quantile(ordered, 0.25),
        '50%': _quantile(ordered, 0.5),
        '75%': _quantile(ordered, 0.75),
        'max': float(ordered[-1]),
    }

