import math
import re

_URL_RE = re.compile(r'https?://\S+', re.IGNORECASE)
_WORD_RE = re.compile(r'\w{2,}')


def tfidf_without_urls(texts):
    """Compute TF-IDF scores for words in each document, ignoring URLs.

    URLs (http:// or https:// followed by non-whitespace characters) are
    removed before tokenisation. Words are lowercased runs of two or more
    word characters. Scores are raw term counts times the smoothed IDF
    ln((1 + n) / (1 + df)) + 1, with each document vector L2-normalised.

    Returns (rows, vocab) where vocab is the sorted list of distinct words
    and rows has one list of scores per document in vocab order. If every
    document is empty, returns ([], []).
    """
    docs_counts = []
    df = {}
    for text in texts:
        if text is None:
            text = ''
        cleaned = _URL_RE.sub(' ', text)
        words = [w.lower() for w in _WORD_RE.findall(cleaned)]
        counts = {}
        for w in words:
            counts[w] = counts.get(w, 0) + 1
        docs_counts.append(counts)
        for w in counts:
            df[w] = df.get(w, 0) + 1

    vocab = sorted(df)
    if not vocab:
        return ([], [])

    n = len(texts)
    idf = {w: math.log((1 + n) / (1 + df[w])) + 1 for w in vocab}

    rows = []
    for counts in docs_counts:
        vec = [counts.get(w, 0) * idf[w] for w in vocab]
        norm = math.sqrt(sum(v * v for v in vec))
        if norm > 0:
            vec = [v / norm for v in vec]
        rows.append(vec)

    return (rows, vocab)

