"""Self-contained implementation of `correlation_without_column`."""

from numbers import Real


def _is_number(value):
    """True when `value` is a real number (ints, floats, bools, numpy reals)."""
    return isinstance(value, Real)


def _is_numeric_column(values):
    """A column is numeric when all of its values are real numbers."""
    return all(_is_number(v) for v in values)


def _pearson(xs, ys):
    """Pearson correlation of two equal-length numeric sequences.

    Uses the standard raw-sums formula

        r = (n*Sxy - Sx*Sy) / sqrt((n*Sxx - Sx^2) * (n*Syy - Sy^2))
    """
    n = len(xs)
    if n == 0:
        return 0.0
    sx = 0.0
    sy = 0.0
    sxx = 0.0
    syy = 0.0
    sxy = 0.0
    for x, y in zip(xs, ys):
        sx += x
        sy += y
        sxx += x * x
        syy += y * y
        sxy += x * y
    num = n * sxy - sx * sy
    var_x = n * sxx - sx * sx
    var_y = n * syy - sy * sy
    denom = (var_x * var_y) ** 0.5
    if denom == 0:
        # Correlation is undefined when either column is constant.
        return 0.0
    return num / denom


def correlation_without_column(data, column):
    """Pearson correlation matrix of `data` after dropping `column`.

    `data` is a dict mapping column names to equal-length lists of values.
    The column named `column` is dropped when present, and any column whose
    values are not all numbers is ignored.  The return value is a dict of
    dicts where ``result[x][y]`` is the Pearson correlation between columns
    ``x`` and ``y`` (the diagonal is 1.0).  When no numeric columns remain
    (including when `data` is empty), ``None`` is returned.
    """
    if not isinstance(data, dict):
        return None

    numeric = {}
    for name, values in data.items():
        if name == column:
            continue
        if values is None:
            continue
        values = list(values)
        if not values or not _is_numeric_column(values):
            continue
        numeric[name] = [float(v) for v in values]

    if not numeric:
        return None

    names = list(numeric.keys())
    result = {}
    for x in names:
        row = {}
        for y in names:
            if x == y:
                row[y] = 1.0
            else:
                row[y] = _pearson(numeric[x], numeric[y])
        result[x] = row
    return result

