"""Self-contained implementation of `column_histograms`."""

import math
import numbers


def _is_number(value):
    """Return True if `value` is a real (non-complex) number."""
    return isinstance(value, numbers.Number) and not isinstance(value, complex)


def _is_numeric_column(values):
    """A column is numeric when it is a non-empty sequence of real numbers."""
    if isinstance(values, (str, bytes)):
        return False
    try:
        items = list(values)
    except TypeError:
        return False
    if not items:
        return False
    return all(_is_number(v) for v in items)


def _histogram(values, n_bins=10):
    """10 equal-width bin counts spanning min..max; last bin includes the max."""
    lo = min(values)
    hi = max(values)
    counts = [0] * n_bins
    span = hi - lo
    if span == 0:
        # Degenerate range: every value equals the maximum, which belongs to
        # the last bin.
        counts[-1] = len(values)
        return counts
    width = span / n_bins
    for v in values:
        if v == hi:
            idx = n_bins - 1
        else:
            t = (v - lo) / width
            idx = int(math.floor(t))
            # Guard against floating point error just below a bin edge
            # (e.g. 0.3 / 0.1 == 2.9999999999999996).
            if t - idx > 1.0 - 1e-9:
                idx += 1
            if idx < 0:
                idx = 0
            elif idx >= n_bins:
                idx = n_bins - 1
        counts[idx] += 1
    return counts


def column_histograms(table):
    """Compute 10-bin histograms for every numeric column of `table`.

    Parameters
    ----------
    table : dict
        Mapping of column name -> equal-length list of values.

    Returns
    -------
    dict
        Mapping of numeric column name -> list of 10 bin counts, in the
        table's column order.

    Raises
    ------
    ValueError
        If `table` is not a non-empty dict, or has no numeric columns.
    """
    if not isinstance(table, dict) or len(table) == 0:
        raise ValueError("table must be a non-empty dict")

    result = {}
    for name, values in table.items():
        if _is_numeric_column(values):
            result[name] = _histogram(list(values))

    if not result:
        raise ValueError("table has no numeric columns")

    return result

