import math
import re


_WORD_RE = re.compile(r"\w{2,}")


def _words(text):
    return _WORD_RE.findall(text.lower())


def tfidf_scores_for_question_articles(titles, contents):
    """Sum TF-IDF scores (over selected article bodies) per word.

    Articles are selected when their title contains "how" or "what"
    (case-insensitive, even as part of a longer word).
    """
    picked = [
        content
        for title, content in zip(titles, contents)
        if "how" in title.lower() or "what" in title.lower()
    ]

    if not picked:
        return {}

    tokenized = [_words(content) for content in picked]
    n_docs = len(tokenized)

    # Document frequency over the picked articles' bodies.
    df = {}
    for tokens in tokenized:
        for word in set(tokens):
            df[word] = df.get(word, 0) + 1

    idf = {word: math.log((1 + n_docs) / (1 + count)) + 1 for word, count in df.items()}

    totals = {}
    for tokens in tokenized:
        counts = {}
        for word in tokens:
            counts[word] = counts.get(word, 0) + 1
        vector = {word: count * idf[word] for word, count in counts.items()}
        norm = math.sqrt(sum(value * value for value in vector.values()))
        if norm == 0:
            continue
        for word, value in vector.items():
            totals[word] = totals.get(word, 0.0) + value / norm

    return totals

