import re


def _words(s):
    """Extract words: case-insensitive runs of 2+ letters/digits/underscores."""
    return re.findall(r"\w{2,}", s.lower())


def bag_of_words_vector(text, corpus):
    text_words = _words(text)
    vocab = set(text_words)
    for sentence in corpus:
        vocab.update(_words(sentence))
    vocab = sorted(vocab)
    counts = {}
    for w in text_words:
        counts[w] = counts.get(w, 0) + 1
    return [counts.get(w, 0) for w in vocab]

