"""Utility for value replacement and column standardization of tabular data."""


def _replace_value(value, mapping):
    """Return the replacement for ``value`` from ``mapping`` if present."""
    try:
        return mapping.get(value, value)
    except TypeError:
        # Unhashable value: no replacement possible.
        return value


def _replace_column(values, mapping):
    return [_replace_value(v, mapping) for v in values]


def _to_float(value):
    if isinstance(value, bool):
        return float(int(value))
    return float(value)


def _standardize(values):
    """Standardize a list of numeric values to zero mean / unit variance.

    Uses the population standard deviation. If the standard deviation is
    zero (all values identical) the column is mapped to all zeros.
    """
    n = len(values)
    if n == 0:
        return []
    nums = [_to_float(v) for v in values]
    mean = sum(nums) / n
    var = sum((x - mean) ** 2 for x in nums) / n
    std = var ** 0.5
    if std == 0:
        return [0.0 for _ in nums]
    return [(x - mean) / std for x in nums]


def replace_and_standardize(data, features, mapping):
    """Replace values in ``data`` using ``mapping`` and standardize ``features``.

    Args:
        data: dict mapping column names to equal-length lists of values.
        features: list of column names to standardize (zero mean, unit
            variance using the population standard deviation).
        mapping: dict of value replacements applied to every cell of the
            table before standardization.

    Returns:
        A new dict mapping column names to lists of values, preserving the
        original column order. Columns not in ``features`` keep their
        (replaced) values.

    Raises:
        ValueError: if any column in ``features`` is missing from ``data``.
    """
    if mapping is None:
        mapping = {}
    if features is None:
        features = []

    missing = [f for f in features if f not in data]
    if missing:
        raise ValueError(
            "Column(s) missing from data: {}".format(", ".join(str(m) for m in missing))
        )

    feature_set = set(features)
    result = {}
    for name, values in data.items():
        replaced = _replace_column(values, mapping)
        if name in feature_set:
            try:
                result[name] = _standardize(replaced)
            except (TypeError, ValueError):
                # Non-numeric column: leave the replaced values untouched.
                result[name] = replaced
        else:
            result[name] = replaced
    return result

