"""Ordinary least squares multiple linear regression.

Self-contained pure-Python implementation (no third-party dependencies).
"""

from fractions import Fraction

# Above this many rows, fall back to floating point accumulation (speed).
_EXACT_ROW_LIMIT = 5000


def _solve_exact(a, b):
    """Exactly solve the n x n rational system ``a x = b`` (Gaussian elimination).

    Singular columns (free variables) are set to 0, which still yields a valid
    least-squares solution of the normal equations.
    """
    n = len(a)
    m = [list(a[i]) + [b[i]] for i in range(n)]
    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(m[r][col]))
        if m[pivot][col] == 0:
            continue
        if pivot != col:
            m[col], m[pivot] = m[pivot], m[col]
        pv = m[col][col]
        for r in range(col + 1, n):
            f = m[r][col] / pv
            if f:
                for c in range(col, n + 1):
                    m[r][c] -= f * m[col][c]
    x = [Fraction(0)] * n
    for i in range(n - 1, -1, -1):
        if m[i][i] == 0:
            x[i] = Fraction(0)
            continue
        s = m[i][n] - sum(m[i][j] * x[j] for j in range(i + 1, n))
        x[i] = s / m[i][i]
    return x


def _solve_float(a, b):
    """Solve the n x n float system ``a x = b`` with partial pivoting."""
    n = len(a)
    m = [list(map(float, a[i])) + [float(b[i])] for i in range(n)]
    tol = 1e-12
    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(m[r][col]))
        if abs(m[pivot][col]) <= tol:
            continue
        if pivot != col:
            m[col], m[pivot] = m[pivot], m[col]
        pv = m[col][col]
        for r in range(col + 1, n):
            f = m[r][col] / pv
            if f:
                for c in range(col, n + 1):
                    m[r][c] -= f * m[col][c]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        if abs(m[i][i]) <= tol:
            x[i] = 0.0
            continue
        s = m[i][n] - sum(m[i][j] * x[j] for j in range(i + 1, n))
        x[i] = s / m[i][i]
    return x


def fit_linear_regression(rows):
    """Fit an OLS multiple linear regression of the response on 4 predictors.

    ``rows`` is a list of rows, each a list of exactly five numbers: four
    predictor values followed by the response value.

    Returns ``(coefficients, r_squared)`` where ``coefficients`` is
    ``[intercept, b1, b2, b3, b4]`` (slopes in predictor order) and
    ``r_squared`` is the coefficient of determination of the fit.

    Raises ``ValueError`` if ``rows`` is empty or any row does not have exactly
    five values.
    """
    if rows is None or len(rows) == 0:
        raise ValueError("rows must be a non-empty list of rows")

    data = []
    for row in rows:
        if row is None or len(row) != 5:
            raise ValueError("each row must contain exactly five values")
        try:
            data.append([float(v) for v in row])
        except (TypeError, ValueError):
            raise ValueError("each row must contain exactly five numbers")

    n = len(data)
    p = 5  # intercept + 4 slopes

    if n <= _EXACT_ROW_LIMIT:
        # Exact rational arithmetic -> exact coefficients for rational inputs.
        X = [[Fraction(1)] + [Fraction(v) for v in row[:4]] for row in data]
        y = [Fraction(row[4]) for row in data]
        xtx = [[Fraction(0)] * p for _ in range(p)]
        xty = [Fraction(0)] * p
        for i in range(n):
            xi = X[i]
            yi = y[i]
            for r in range(p):
                xr = xi[r]
                if xr:
                    xty[r] += xr * yi
                    row_xtx = xtx[r]
                    for c in range(p):
                        row_xtx[c] += xr * xi[c]
        beta = _solve_exact(xtx, xty)
        y_mean = sum(y) / n
        ss_tot = sum((yi - y_mean) ** 2 for yi in y)
        ss_res = sum((y[i] - sum(X[i][j] * beta[j] for j in range(p))) ** 2
                     for i in range(n))
        if ss_tot == 0:
            r_squared = Fraction(1) if ss_res == 0 else Fraction(0)
        else:
            r_squared = 1 - ss_res / ss_tot
        return [float(b) for b in beta], float(r_squared)

    # Floating point path for very large inputs.
    X = [[1.0] + row[:4] for row in data]
    y = [row[4] for row in data]
    xtx = [[0.0] * p for _ in range(p)]
    xty = [0.0] * p
    for i in range(n):
        xi = X[i]
        yi = y[i]
        for r in range(p):
            xr = xi[r]
            if xr:
                xty[r] += xr * yi
                row_xtx = xtx[r]
                for c in range(p):
                    row_xtx[c] += xr * xi[c]
    beta = _solve_float(xtx, xty)
    y_mean = sum(y) / n
    ss_tot = sum((yi - y_mean) ** 2 for yi in y)
    ss_res = sum((y[i] - sum(X[i][j] * beta[j] for j in range(p))) ** 2
                 for i in range(n))
    if ss_tot == 0.0:
        r_squared = 1.0 if ss_res <= 1e-9 * max(1.0, float(n)) else 0.0
    else:
        r_squared = 1.0 - ss_res / ss_tot
    return [float(b) for b in beta], float(r_squared)

