import math
import re


def _strip_brackets(text):
    """Remove any text enclosed in square brackets (handles nesting)."""
    prev = None
    while prev != text:
        prev = text
        text = re.sub(r'\[[^\[\]]*\]', '', text)
    # Any remaining unmatched '[' swallows the rest of the string.
    text = re.sub(r'\[[^\]]*$', '', text)
    return text


def bracket_free_tfidf(texts):
    """Compute bracket-ignoring TF-IDF scores for each string in ``texts``."""
    texts = list(texts)
    n = len(texts)

    # Tokenize each text (ignoring bracketed parts).
    all_words = []
    for text in texts:
        if not isinstance(text, str):
            text = '' if text is None else str(text)
        cleaned = _strip_brackets(text)
        words = re.findall(r'\w{2,}', cleaned.lower())
        all_words.append(words)

    # Document frequency over the whole list.
    df = {}
    for words in all_words:
        for word in set(words):
            df[word] = df.get(word, 0) + 1

    idf = {word: math.log((1 + n) / (1 + count)) + 1 for word, count in df.items()}

    result = []
    for words in all_words:
        if not words:
            result.append({})
            continue
        counts = {}
        for word in words:
            counts[word] = counts.get(word, 0) + 1
        scores = {word: count * idf[word] for word, count in counts.items()}
        norm = math.sqrt(sum(value * value for value in scores.values()))
        if norm > 0:
            scores = {word: value / norm for word, value in scores.items()}
        result.append(scores)
    return result

