"""Utilities for computing the distribution of dates over days of the week."""

import calendar
import re
from datetime import date

WEEKDAY_NAMES = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
]

# Mapping of month names / abbreviations (lower-cased, trailing '.' removed)
# to month numbers.
_MONTHS = {}
for _num, _name in enumerate(calendar.month_name):
    if _name:
        _MONTHS[_name.lower()] = _num
for _num, _abbr in enumerate(calendar.month_abbr):
    if _abbr:
        _MONTHS[_abbr.lower().rstrip(".")] = _num
# A few extra common abbreviations.
_MONTHS.update({
    "sept": 9,
    "sep": 9,
})

# Time part that may trail a date, e.g. "2022-10-22 12:34:56" / "...T12:34:56Z".
_TIME_RE = re.compile(
    r"(?:[T ]\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?"
    r"(?:\s*(?:Z|UTC|GMT|[+-]\d{2}:?\d{2}|[+-]\d{2}))?)?\s*$",
    re.IGNORECASE,
)

# Ordinal suffixes: "22nd October 2022", "October 22nd, 2022".
_ORDINAL_RE = re.compile(r"(?<=\d)(st|nd|rd|th)\b", re.IGNORECASE)

# Numeric patterns.
_YMD_RE = re.compile(r"^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$")
_DMY_RE = re.compile(r"^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})$")

# Month-name patterns.
_MONTH_D_Y_RE = re.compile(r"^([A-Za-z]+)\.?\s+(\d{1,2})\s+(\d{2,4})$")
_D_MONTH_Y_RE = re.compile(r"^(\d{1,2})\s+([A-Za-z]+)\.?\s+(\d{2,4})$")
_Y_MONTH_D_RE = re.compile(r"^(\d{4})\s+([A-Za-z]+)\.?\s+(\d{1,2})$")


def _expand_year(year):
    """Expand a possibly two-digit year into a full year."""
    if year < 100:
        # Same pivot as common parsers: 0-68 -> 2000s, 69-99 -> 1900s.
        return 2000 + year if year <= 68 else 1900 + year
    return year


def _make_date(year, month, day):
    """Return a date, or None when the combination is not a valid date."""
    try:
        return date(int(year), int(month), int(day))
    except (ValueError, TypeError, OverflowError):
        return None


def _parse_numeric_year_last(a, b, year):
    """Parse a numeric date whose year comes last (e.g. 10/22/2022, 22/10/2022)."""
    a, b, year = int(a), int(b), _expand_year(int(year))
    if a < 1 or b < 1:
        return None
    # Unambiguous cases first.
    if a > 31 and b <= 12:  # first component must be a year-like? not possible here
        return None
    if b > 12 and a <= 12:
        # e.g. 10/22/2022 -> month/day/year
        return _make_date(year, a, b)
    if a > 12 and b <= 12:
        # e.g. 22/10/2022 -> day/month/year
        return _make_date(year, b, a)
    # Ambiguous: try month-first (US style), then day-first.
    return _make_date(year, a, b) or _make_date(year, b, a)


def parse_date_string(text):
    """Parse a single date string written in one of many common formats.

    Returns a ``datetime.date`` or ``None`` when the string cannot be parsed.
    """
    if not isinstance(text, str):
        if isinstance(text, date):
            return text
        return None

    s = text.strip()
    if not s:
        return None
    # Remove ordinal suffixes and commas, collapse whitespace.
    s = _ORDINAL_RE.sub("", s)
    s = s.replace(",", " ")
    s = re.sub(r"\s+", " ", s).strip()
    # Drop a trailing time-of-day / timezone part.
    s = _TIME_RE.sub("", s).strip()
    if not s:
        return None

    m = _YMD_RE.match(s)
    if m:
        return _make_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _DMY_RE.match(s)
    if m:
        return _parse_numeric_year_last(m.group(1), m.group(2), m.group(3))

    m = _MONTH_D_Y_RE.match(s)  # "Oct 22 2022" / "October 22 2022"
    if m and m.group(1).lower() in _MONTHS:
        return _make_date(_expand_year(int(m.group(3))), _MONTHS[m.group(1).lower()], int(m.group(2)))

    m = _D_MONTH_Y_RE.match(s)  # "22 October 2022" / "22 Oct 2022"
    if m and m.group(2).lower() in _MONTHS:
        return _make_date(_expand_year(int(m.group(3))), _MONTHS[m.group(2).lower()], int(m.group(1)))

    m = _Y_MONTH_D_RE.match(s)  # "2022 Oct 22"
    if m and m.group(2).lower() in _MONTHS:
        return _make_date(int(m.group(1)), _MONTHS[m.group(2).lower()], int(m.group(3)))

    return None


def weekday_distribution(date_strings):
    """Count how many of ``date_strings`` fall on each day of the week.

    The input strings may use different common date formats, for example
    ``'2022-10-22'``, ``'2022/10/22'``, ``'Oct 22, 2022'`` or
    ``'22 October 2022'``.  The result maps every weekday name, from
    ``'Monday'`` through ``'Sunday'``, to the number of dates falling on it
    (0 if none).  Strings that cannot be parsed are ignored.
    """
    distribution = {name: 0 for name in WEEKDAY_NAMES}
    if not date_strings:
        return distribution

    for item in date_strings:
        parsed = parse_date_string(item)
        if parsed is None:
            continue
        distribution[WEEKDAY_NAMES[parsed.weekday()]] += 1

    return distribution

