def course_grade_summary(records):
    """Summarize grades per course.

    Args:
        records: iterable of (student, course, grade) tuples.

    Returns:
        dict mapping course -> (average_grade as float, count of grades >= 60).
    """
    totals = {}
    counts = {}
    passing = {}
    for _student, course, grade in records:
        totals[course] = totals.get(course, 0) + grade
        counts[course] = counts.get(course, 0) + 1
        if grade >= 60:
            passing[course] = passing.get(course, 0) + 1
    return {
        course: (float(totals[course]) / counts[course], passing.get(course, 0))
        for course in totals
    }

