import csv
import io


def _is_int(value):
    try:
        int(value)
    except (TypeError, ValueError):
        return False
    return True


def _is_float(value):
    try:
        float(value)
    except (TypeError, ValueError):
        return False
    return True


def _parse_number(value):
    """Convert a numeric string to int when possible, otherwise float."""
    stripped = value.strip()
    try:
        return int(stripped)
    except (TypeError, ValueError):
        return float(stripped)


def _parse_documents(csv_texts):
    """Yield (header, rows) for each CSV document in the list."""
    for text in csv_texts:
        if text is None:
            continue
        if isinstance(text, bytes):
            text = text.decode("utf-8-sig")
        reader = csv.reader(io.StringIO(text))
        rows = [row for row in reader if row]
        if not rows:
            continue
        header = list(rows[0])
        if header and header[0].startswith("﻿"):
            header[0] = header[0][1:]
        data_rows = rows[1:]
        yield header, data_rows


def concat_csv_tables(csv_texts):
    """Concatenate the data rows of several CSV documents.

    Each document must have a header row and all documents share the same
    columns.  Returns a list of dicts mapping column name to value.  Columns
    whose values are all numeric are returned as numbers (int or float);
    every other column is returned as a string.

    Raises ValueError if `csv_texts` is empty.
    """
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    parsed = list(_parse_documents(csv_texts))
    if not parsed:
        return []

    header = parsed[0][0]
    n_cols = len(header)

    all_rows = []
    for doc_header, data_rows in parsed:
        # Normalise each row to the header length.
        for row in data_rows:
            if len(row) < n_cols:
                row = list(row) + [""] * (n_cols - len(row))
            elif len(row) > n_cols:
                row = list(row)[:n_cols]
            all_rows.append(row)

    # Decide the type of every column based on all of its values.
    converters = []
    for col in range(n_cols):
        values = [row[col] for row in all_rows]
        if values and all(_is_int(v) for v in values):
            converters.append(_parse_number)
        elif values and all(_is_float(v) for v in values):
            converters.append(_parse_number)
        else:
            converters.append(str)

    result = []
    for row in all_rows:
        result.append({header[i]: converters[i](row[i]) for i in range(n_cols)})
    return result

