import csv
import io
import math
import re
import statistics


_GROUPED_RE = re.compile(r"^\d{1,3}(,\d{3})+(\.\d+)?$")
_CURRENCY_CHARS = "$\u20ac\u00a3\u00a5\u20b9"


def _parse_number(text):
    """Return a float for a numeric-looking string, otherwise None."""
    if text is None:
        return None
    s = str(text).strip()
    if not s:
        return None
    # Drop a trailing percent sign and surrounding currency symbols.
    if s.endswith("%"):
        s = s[:-1].strip()
    s = s.strip(_CURRENCY_CHARS).strip()
    if not s:
        return None
    # Handle thousands separators, e.g. "1,234,567" or "1,234.56".
    if _GROUPED_RE.match(s):
        s = s.replace(",", "")
    try:
        value = float(s)
    except ValueError:
        return None
    if math.isnan(value) or math.isinf(value):
        return None
    return value


def column_summary_stats(csv_text, column_name):
    """Return mean/median/population std_dev of a numeric CSV column.

    Parameters
    ----------
    csv_text : str
        Text of a CSV file including a header row.
    column_name : str
        Name of one of the header columns.

    Returns
    -------
    dict
        {'mean': float, 'median': float, 'std_dev': float}

    Raises
    ------
    ValueError
        If the column is not present in the header or contains no
        numeric values.
    """
    if csv_text is None:
        raise ValueError("csv_text must be a string containing CSV data")
    if isinstance(csv_text, str) and csv_text.startswith("\ufeff"):
        csv_text = csv_text[1:]

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text is empty (no header row)")

    header = [h.strip() if isinstance(h, str) else h for h in header]

    # Locate the requested column (exact match first, then case-insensitive).
    index = None
    if column_name in header:
        index = header.index(column_name)
    else:
        target = str(column_name).strip()
        for i, h in enumerate(header):
            if isinstance(h, str) and h.strip() == target:
                index = i
                break
        if index is None:
            lowered = target.lower()
            for i, h in enumerate(header):
                if isinstance(h, str) and h.strip().lower() == lowered:
                    index = i
                    break
    if index is None:
        raise ValueError("Column %r not found in header %r" % (column_name, header))

    values = []
    for row in reader:
        if not row:
            continue
        # Pad short rows so indexing is safe.
        cell = row[index] if index < len(row) else ""
        number = _parse_number(cell)
        if number is not None:
            values.append(number)

    if not values:
        raise ValueError("Column %r contains no numeric values" % (column_name,))

    mean = sum(values) / len(values)
    median = statistics.median(values)
    if len(values) == 1:
        std_dev = 0.0
    else:
        variance = sum((v - mean) ** 2 for v in values) / len(values)
        std_dev = math.sqrt(variance)

    return {"mean": float(mean), "median": float(median), "std_dev": float(std_dev)}

