from fractions import Fraction
from math import isqrt, sqrt


def _to_fraction(value):
    """Convert a numeric value to an exact :class:`~fractions.Fraction`."""
    if isinstance(value, Fraction):
        return value
    if isinstance(value, bool):
        return Fraction(int(value))
    if isinstance(value, int):
        return Fraction(value)
    # float (exact binary conversion), Decimal, numeric string, ...
    try:
        return Fraction(value)
    except (TypeError, ValueError):
        return Fraction(float(value))


def _mapped(values, mapping):
    """Replace every value that is a key of ``mapping`` by its mapped value."""
    out = []
    for v in values:
        try:
            if v in mapping:
                v = mapping[v]
        except TypeError:
            # Unhashable value: it cannot possibly be a key of ``mapping``.
            pass
        out.append(_to_fraction(v))
    return out


def _isqrt_exact(n):
    """Return ``isqrt(n)`` if ``n`` is a perfect square, else ``None``."""
    if n < 0:
        return None
    r = isqrt(n)
    return r if r * r == n else None


def _pearson(xs, ys):
    """Pearson correlation coefficient of two equal-length numeric lists."""
    n = min(len(xs), len(ys))
    if n == 0:
        return 0.0
    xs = xs[:n]
    ys = ys[:n]
    mean_x = sum(xs, Fraction(0)) / n
    mean_y = sum(ys, Fraction(0)) / n
