"""Self-contained implementation of score/grade correlation scoring."""


def _parse_score(value):
    """Convert a score entry to a finite float, raising ValueError if invalid."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise ValueError("Invalid score: %r is not a valid number" % (value,))
    # Reject NaN / infinities: they are not valid numeric scores.
    if number != number or number in (float("inf"), float("-inf")):
        raise ValueError("Invalid score: %r is not a valid number" % (value,))
    return number


def _pearson(xs, ys):
    """Pearson correlation coefficient between two equal-length sequences."""
    n = len(xs)
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    cov = 0.0
    var_x = 0.0
    var_y = 0.0
    for x, y in zip(xs, ys):
        dx = x - mean_x
        dy = y - mean_y
        cov += dx * dy
        var_x += dx * dx
        var_y += dy * dy
    if var_x == 0.0 or var_y == 0.0:
        # Undefined (constant input); report no correlation.
        return 0.0
    return cov / ((var_x ** 0.5) * (var_y ** 0.5))


def score_grade_correlation(scores, grades):
    """Pearson correlation between numeric scores and ordinal grade labels.

    Each distinct grade label is encoded as its index in the sorted list of
    distinct labels. Returns None when fewer than two entries are given.
    Raises ValueError for mismatched lengths or non-numeric scores.
    """
    if scores is None or grades is None:
        raise ValueError("scores and grades must be provided")
    if len(scores) != len(grades):
        raise ValueError("scores and grades must have the same length")
    if len(scores) < 2:
        return None

    numeric_scores = [_parse_score(s) for s in scores]

    distinct = sorted(set(grades), key=str)
    encoding = {label: idx for idx, label in enumerate(distinct)}
    encoded_grades = [float(encoding[g]) for g in grades]

    return float(_pearson(numeric_scores, encoded_grades))

