import csv
import io
import statistics


def _to_float(text):
    """Return ``float(text)`` or ``None`` when `text` is not a valid number."""
    if text is None:
        return None
    try:
        return float(text)
    except (TypeError, ValueError):
        return None


def _numeric_fields(csv_text):
    """Yield every field of the CSV that parses as a number."""
    try:
        rows = csv.reader(io.StringIO(csv_text))
        for row in rows:
            if not row:  # blank line
                continue
            for field in row:
                number = _to_float(field)
                if number is not None:
                    yield number
    except (csv.Error, TypeError, UnicodeDecodeError):
        # Malformed / non-text input: fall back to a plain line-by-line parse.
        for line in str(csv_text).splitlines():
            if not line.strip():
                continue
            number = _to_float(line.strip())
            if number is not None:
                yield number


def csv_mean_median(csv_text):
    """Return ``(mean, median)`` of the numeric values of a single-column CSV.

    `csv_text` is the text of a CSV file with a header row and a single column
    of values.  Blank lines and values that are not numbers (such as the
    header) are ignored.  The result is a tuple of floats, or ``(None, None)``
    when the text is empty or contains no numeric values.

    >>> csv_mean_median("value\\n10\\n20\\nabc\\n40\\n")
    (23.333333333333332, 20.0)
    """
    if csv_text is None:
        return (None, None)
    if isinstance(csv_text, bytes):
        try:
            csv_text = csv_text.decode("utf-8", "replace")
        except Exception:
            return (None, None)
    if not isinstance(csv_text, str) or not csv_text.strip():
        return (None, None)

    values = list(_numeric_fields(csv_text))
    if not values:
        return (None, None)

    mean = float(sum(values)) / float(len(values))
    median = float(statistics.median(values))
    return (mean, median)

