    """Validate and convert a 'YYYY-MM-DD' string into a datetime.date."""
    if not isinstance(start_date, str):
        raise ValueError("start_date must be a 'YYYY-MM-DD' string, got %r" % (start_date,))
    match = _DATE_RE.match(start_date.strip())
    if not match:
        raise ValueError("Invalid start date: %r (expected 'YYYY-MM-DD')" % (start_date,))
    year, month, day = (int(part) for part in match.groups())
    try:
        return date(year, month, day)
    except ValueError:
        raise ValueError("Invalid start date: %r" % (start_date,))


def _days_in_month(year, month):
    """Number of days in the given month."""
    if month == 12:
        next_month = date(year + 1, 1, 1)
    else:
        next_month = date(year, month + 1, 1)
    return (next_month - date(year, month, 1)).days


def _last_day_of_month(year, month):
    return date(year, month, _days_in_month(year, month))


def _nth_weekday_of_month(year, month, weekday, n):
    """Date of the n-th (1-based) `weekday` of the month, or None if absent."""
    first = date(year, month, 1)
    offset = (weekday - first.weekday()) % 7
    day = 1 + offset + (n - 1) * 7
    if day > _days_in_month(year, month):
        return None
    return date(year, month, day)


def _parse_freq(freq):
    """Return a callable (year, month) -> date describing the frequency."""
    if not isinstance(freq, str):
        raise ValueError("Invalid freq: %r" % (freq,))
    normalized = freq.strip().lower().replace("_", "-").replace(" ", "")
    if normalized in ("month-end", "monthend", "me", "m"):
        return lambda year, month: _last_day_of_month(year, month)
    if normalized in ("quarter-end", "quarterend", "qe", "q"):
        def quarter_end(year, month):
            if month not in _MONTH_END_MONTHS:
                return None
            return _last_day_of_month(year, month)
        return quarter_end
    match = _FREQ_RE.match(freq.strip().upper())
    if match:
        n = int(match.group(1))
        weekday = _WEEKDAYS.get(match.group(2).upper())
        if weekday is not None:
            return lambda year, month, n=n, weekday=weekday: _nth_weekday_of_month(
                year, month, weekday, n
            )
    raise ValueError("Invalid freq: %r" % (freq,))


def _month_sequence(start):
    """Yield (year, month) pairs starting at the month of `start`."""
    year, month = start.year, start.month
    while True:
        yield year, month
        month += 1
        if month > 12:
            month = 1
            year += 1


def forecast_schedule(start_date, freq, sales):
    """Pair forecast sales figures with consecutive dates from `start_date`.

    Args:
        start_date: 'YYYY-MM-DD' string; the first date in the schedule is the
            earliest matching date on or after this date.
        freq: 'month-end', 'quarter-end', or a code like '2-FRI' meaning the
            second Friday of each month (week 1-4, weekday MON-SUN).
        sales: list of forecast sales figures; one date per figure.

    Returns:
        List of ('YYYY-MM-DD', sales) tuples in order.

    Raises:
        ValueError: if `start_date` (or `freq`) is invalid.
    """
    start = _parse_start_date(start_date)
    matcher = _parse_freq(freq)
    figures = list(sales) if sales is not None else []

    schedule = []
    for year, month in _month_sequence(start):
        if len(schedule) >= len(figures):
            break
        candidate = matcher(year, month)
        if candidate is None or candidate < start:
            continue
        schedule.append((candidate.isoformat(), figures[len(schedule)]))
    return schedule

