import csv
import io
import re


def _to_number(value):
    """Convert a sales value to int when possible, otherwise float."""
    if value is None:
        return 0
    text = str(value).strip()
    if text == "":
        return 0
    # tolerate thousands separators / currency decorations, e.g. "$1,234.56"
    cleaned = re.sub(r"[$\u20ac\u00a3\s]", "", text)
    if re.fullmatch(r"[+-]?\d{1,3}(,\d{3})+(\.\d+)?", cleaned):
        cleaned = cleaned.replace(",", "")
    text = cleaned
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return 0


def sales_report(csv_text):
    """Build a sales report from CSV text.

    The CSV text must have a header row containing at least the columns
    ``Customer``, ``Category`` and ``Sales`` (other columns may be present,
    in any order).  Only the first row for each customer name is kept.

    Returns a dict with:
      * ``'Total Sales'``: the sum of ``Sales`` over the kept rows.
      * ``'Most Popular Category'``: the most frequent ``Category`` among the
        kept rows; ties are resolved by picking the alphabetically first
        category.

    Raises:
        ValueError: if ``csv_text`` is not a string.
    """
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)

    if not rows:
        return {'Total Sales': 0, 'Most Popular Category': None}

    header = [str(h).strip() for h in rows[0]]
    try:
        customer_idx = header.index("Customer")
        category_idx = header.index("Category")
        sales_idx = header.index("Sales")
    except ValueError as exc:
        raise ValueError(
            "CSV header must contain 'Customer', 'Category' and 'Sales' columns"
        ) from exc

    def cell(row, idx):
        if row is None or idx >= len(row):
            return ""
        return row[idx]

    seen = set()
    kept = []  # list of (customer, category, sales_value)
    for row in rows[1:]:
        if not row or all(str(c).strip() == "" for c in row):
            continue
        customer = str(cell(row, customer_idx)).strip()
        if customer == "" or customer in seen:
            continue
        seen.add(customer)
        category = str(cell(row, category_idx)).strip()
        sales = _to_number(cell(row, sales_idx))
        kept.append((customer, category, sales))

    total_sales = sum(sales for _, _, sales in kept)
    # Normalize integral floats to int for nicer output (e.g. 800 instead of 800.0)
    if isinstance(total_sales, float) and total_sales.is_integer():
        total_sales = int(total_sales)

    counts = {}
    for _, category, _ in kept:
        counts[category] = counts.get(category, 0) + 1

    if counts:
        # most frequent; on tie, alphabetically first category
        most_popular = min(counts.items(), key=lambda kv: (-kv[1], kv[0]))[0]
    else:
        most_popular = None

    return {'Total Sales': total_sales, 'Most Popular Category': most_popular}

