"""Self-contained solution for the country_score_summary task."""


def _percentile(sorted_values, q):
    """Linear interpolation percentile (numpy 'linear' method) on sorted data."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])
    pos = (n - 1) * q
    lower = int(pos)
    upper = min(lower + 1, n - 1)
    frac = pos - lower
    return float(sorted_values[lower] + (sorted_values[upper] - sorted_values[lower]) * frac)


def country_score_summary(records):
    """Summarize scores per country.

    Keeps only the first record for each name, then returns a dict mapping
    each country to [min, Q1, median, Q3, max] of its scores (linear
    interpolation between sorted values).

    Raises ValueError if records is empty or any record lacks a required key.
    """
    if not records:
        raise ValueError("records must not be empty")

    required = ("Name", "Country", "Score")
    seen = set()
    by_country = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("each record must be a dict")
        for key in required:
            if key not in record:
                raise ValueError("record missing required key: %r" % (key,))
        name = record["Name"]
        if name in seen:
            continue
        seen.add(name)
        by_country.setdefault(record["Country"], []).append(record["Score"])

    summary = {}
    for country, scores in by_country.items():
        ordered = sorted(scores)
        summary[country] = [
            float(ordered[0]),
            _percentile(ordered, 0.25),
            _percentile(ordered, 0.50),
            _percentile(ordered, 0.75),
            float(ordered[-1]),
        ]
    return summary

