"""Column-wise sample covariance for tables represented as dicts of lists."""

import decimal
import math
import numbers

__all__ = ["column_covariance"]


def _is_numeric(value):
    """Return True for real numeric values (int, float, bool, Fraction, ...)."""
    if isinstance(value, numbers.Real):
        return True
    # decimal.Decimal is not registered as a numbers.Real subclass.
    return isinstance(value, decimal.Decimal)


def column_covariance(columns):
    """Return the sample covariance matrix (normalised by n - 1) of a table.

    ``columns`` maps column names to equal-length lists of numbers.  The
    result is a nested dict ``result[a][b]`` giving the covariance between
    columns ``a`` and ``b``.

    Raises:
        ValueError: if the table has no columns, no rows, fewer than two
            rows, or columns of unequal length.
        TypeError: if any column contains a non-numeric value.
    """
    if not isinstance(columns, dict) or len(columns) == 0:
        raise ValueError("table must contain at least one column")

    names = list(columns.keys())
    values = {}
    length = None
    for name in names:
        col = columns[name]
        if isinstance(col, (str, bytes)) or not hasattr(col, "__iter__"):
            raise TypeError("column %r must be an iterable of numbers" % (name,))
        col = list(col)
        if length is None:
            length = len(col)
        elif len(col) != length:
            raise ValueError("all columns must have the same length")
        for value in col:
            if not _is_numeric(value):
                raise TypeError(
                    "column %r contains a non-numeric value: %r" % (name, value)
                )
        values[name] = [float(v) for v in col]

    n = length if length is not None else 0
    if n < 2:
        raise ValueError("table must contain at least two rows")

    means = {name: math.fsum(values[name]) / n for name in names}

    result = {}
    for a in names:
        row = {}
        for b in names:
            row[b] = math.fsum(
                (values[a][i] - means[a]) * (values[b][i] - means[b])
                for i in range(n)
            ) / (n - 1)
        result[a] = row
    return result

