"""Utilities for parsing and sorting CSV text."""

import csv
import io
import re

# A number: optional sign, digits with optional decimal point and/or exponent.
_NUMBER_RE = re.compile(
    r"^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$"
)
_INT_RE = re.compile(r"^[+-]?\d+$")


def _is_numeric(text):
    """Return True if `text` looks like a number (int or float)."""
    if text is None:
        return False
    return bool(_NUMBER_RE.match(text.strip()))


def _to_number(text):
    """Convert a numeric string to an int when possible, otherwise a float."""
    stripped = text.strip()
    if _INT_RE.match(stripped):
        return int(stripped)
    return float(stripped)


def sort_csv_rows(csv_text, sort_key):
    """Sort the data rows of a CSV text by the column named `sort_key`.

    Args:
        csv_text: The full text of a CSV file, including a header row.
        sort_key: The name of the column to sort by, ascending.

    Returns:
        A list of dicts mapping column names to values.  Columns whose
        values are all numeric hold numbers (so they sort numerically);
        every other column stays as strings.  Rows with equal keys keep
        their original relative order (the sort is stable).

    Raises:
        ValueError: If `sort_key` is not a column of the CSV.
    """
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        header = []

    # Strip a possible BOM from the first header cell.
    if header:
        header[0] = header[0].lstrip("\ufeff")

    if sort_key not in header:
        raise ValueError(
            "column %r does not exist (available columns: %s)"
            % (sort_key, ", ".join(repr(name) for name in header))
        )

    key_index = header.index(sort_key)
    width = len(header)

    rows = []
    for row in reader:
        if not row:
            continue  # skip completely blank lines
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        rows.append(row)

    # A column is numeric only when every one of its values is numeric.
    numeric_columns = set()
    for idx in range(width):
        if rows and all(_is_numeric(row[idx]) for row in rows):
            numeric_columns.add(idx)

    records = []
    for row in rows:
        record = {}
        for idx, name in enumerate(header):
            value = row[idx]
            if idx in numeric_columns:
                value = _to_number(value)
            record[name] = value
        records.append(record)

    # list.sort is stable, so equal keys keep their original order.
    records.sort(key=lambda record: record[sort_key])
    return records

