"""Utilities for computing per-row statistics from a CSV of email/list pairs."""

import ast
import csv
import io
import statistics


def _parse_list(cell):
    """Parse a Python-style list-of-numbers string into a list of numbers."""
    if cell is None:
        return []
    text = cell.strip()
    if not text:
        return []
    try:
        value = ast.literal_eval(text)
    except (ValueError, SyntaxError, MemoryError, RecursionError):
        value = _tolerant_parse(text)
    if isinstance(value, (list, tuple, set)):
        return list(value)
    return [value]


def _tolerant_parse(text):
    """Best-effort parse of a malformed list-of-numbers string."""
    cleaned = text.strip().strip("[](){}")
    numbers = []
    for part in cleaned.split(","):
        part = part.strip()
        if not part:
            continue
        try:
            numbers.append(int(part))
        except ValueError:
            try:
                numbers.append(float(part))
            except ValueError:
                continue
    return numbers


def _stats(numbers):
    """Return (sum, mean, median) for a sequence of numbers."""
    total = sum(numbers)
    if not numbers:
        return total, None, None
    mean = statistics.mean(numbers)
    median = statistics.median(numbers)
    if isinstance(mean, int) and not isinstance(mean, bool):
        mean = float(mean)
    if isinstance(median, int) and not isinstance(median, bool):
        median = float(median)
    return total, mean, median


def list_stats_by_email(csv_text):
    """Compute sum/mean/median of the list column for each row of a CSV.

    Args:
        csv_text: Text of a CSV file with 'email' and 'list' columns, where
            each 'list' cell is a Python-style list of numbers as a string.

    Returns:
        A list of dicts (one per data row, in file order) with the keys
        'email', 'list', 'sum', 'mean' and 'median'.
    """
    if csv_text is None:
        return []
    reader = csv.DictReader(io.StringIO(csv_text))
    results = []
    for row in reader:
        if row is None:
            continue
        email = row.get("email")
        numbers = _parse_list(row.get("list"))
        total, mean, median = _stats(numbers)
        results.append({
            "email": email,
            "list": numbers,
            "sum": total,
            "mean": mean,
            "median": median,
        })
    return results

