"""Classification summary utility."""

from fractions import Fraction


def classification_summary(y_true, y_pred):
    """Return a per-label classification report as a dict.

    Maps each label appearing in either ``y_true`` or ``y_pred`` to a tuple
    ``(precision, recall, f1, support)`` where support is the label's count in
    ``y_true``; undefined metrics are 0.0.  The keys ``'accuracy'``,
    ``'macro avg'`` and ``'weighted avg'`` hold the overall accuracy and the
    macro / support-weighted averages as ``(precision, recall, f1, total)``.

    Raises ``ValueError`` if the two sequences have different lengths.
    """
    y_true = list(y_true)
    y_pred = list(y_pred)
    if len(y_true) != len(y_pred):
        raise ValueError(
            "y_true and y_pred must have the same length "
            "(%d != %d)" % (len(y_true), len(y_pred))
        )

    # Labels in order of first appearance (y_true first, then y_pred).
    labels = []
    for label in y_true:
        if label not in labels:
            labels.append(label)
    for label in y_pred:
        if label not in labels:
            labels.append(label)

    total = len(y_true)
    correct = sum(1 for t, p in zip(y_true, y_pred) if t == p)
    accuracy = Fraction(correct, total) if total else Fraction(0)

    per_label = {}
    for label in labels:
        tp = sum(1 for t, p in zip(y_true, y_pred) if t == label and p == label)
        support = sum(1 for t in y_true if t == label)
        predicted = sum(1 for p in y_pred if p == label)
        precision = Fraction(tp, predicted) if predicted else Fraction(0)
        recall = Fraction(tp, support) if support else Fraction(0)
        if precision + recall > 0:
            f1 = 2 * precision * recall / (precision + recall)
        else:
            f1 = Fraction(0)
        per_label[label] = (precision, recall, f1, support)

    n_labels = len(labels)
    if n_labels:
        macro = tuple(
            sum(per_label[label][i] for label in labels) / n_labels
            for i in range(3)
        ) + (total,)
    else:
        macro = (Fraction(0), Fraction(0), Fraction(0), total)

    if total:
        weighted = tuple(
            sum(per_label[label][i] * per_label[label][3] for label in labels)
            / total
            for i in range(3)
        ) + (total,)
    else:
        weighted = (Fraction(0), Fraction(0), Fraction(0), total)

    def as_float(value):
        return float(value) if isinstance(value, Fraction) else value

    result = {
        label: tuple(as_float(v) for v in values)
        for label, values in per_label.items()
    }
    result["accuracy"] = float(accuracy)
    result["macro avg"] = tuple(as_float(v) for v in macro)
    result["weighted avg"] = tuple(as_float(v) for v in weighted)
    return result

