import math
import re


def tfidf_matrix(documents):
    """Compute TF-IDF scores for a list of documents.

    Words are maximal runs of letters and digits, lowercased. Raw term
    counts are used with the smoothed idf ln((1 + n) / (1 + df)) + 1, and
    each document vector is scaled to unit Euclidean length.

    Returns a tuple (words, rows) where `words` is the alphabetically
    sorted vocabulary and `rows[i]` is the list of scores for document i.
    """
    docs = list(documents)
    n = len(docs)
    tokenized = [re.findall(r'[^\W_]+', doc.lower()) for doc in docs]

    df = {}
    for tokens in tokenized:
        for word in set(tokens):
            df[word] = df.get(word, 0) + 1

    words = sorted(df)
    index = {word: i for i, word in enumerate(words)}

    idf = {word: math.log((1 + n) / (1 + count)) + 1 for word, count in df.items()}

    rows = []
    for tokens in tokenized:
        counts = {}
        for token in tokens:
            counts[token] = counts.get(token, 0) + 1
        vec = [0.0] * len(words)
        for word, count in counts.items():
            vec[index[word]] = count * idf[word]
        norm = math.sqrt(sum(v * v for v in vec))
        if norm > 0:
            vec = [v / norm for v in vec]
        rows.append(vec)

    return words, rows

