"""Ordinary least-squares linear regression with an intercept, scored by R^2."""


def _to_float_matrix(data, target):
    """Return (X, y) where X has one row per observation and one column per
    non-target key of ``data`` (in sorted order), and y is the target column."""
    if target not in data:
        raise KeyError("target column %r not present in data" % (target,))
    columns = [k for k in data if k != target]
    columns.sort(key=lambda k: str(k))
    y = [float(v) for v in data[target]]
    n = len(y)
    for k in data:
        if len(data[k]) != n:
            raise ValueError("all columns must have equal length")
    X = [[float(data[k][i]) for k in columns] for i in range(n)]
    return X, y


def _r2_from_predictions(y, pred):
    n = len(y)
    if n == 0:
        return 0.0
    mean_y = sum(y) / n
    ss_tot = 0.0
    ss_res = 0.0
    for yi, pi in zip(y, pred):
        d = yi - mean_y
        ss_tot += d * d
        r = yi - pi
        ss_res += r * r
    if ss_tot == 0.0:
        # Target is constant: sklearn-style behaviour.
        return 1.0 if ss_res <= 1e-12 * max(1.0, abs(mean_y)) ** 2 else 0.0
    return 1.0 - ss_res / ss_tot


def _solve_lstsq_numpy(X, y):
    import numpy as np

    n = len(y)
    p = len(X[0]) if n else 0
    A = np.ones((n, p + 1), dtype=float)
    for i, row in enumerate(X):
        A[i, 1:] = row
    beta, _, _, _ = np.linalg.lstsq(A, np.asarray(y, dtype=float), rcond=None)
    pred = A @ beta
    return [float(v) for v in pred]


def _solve_lstsq_pure(X, y):
    """Least squares via normal equations + Gaussian elimination with partial
    pivoting (used only when numpy is unavailable)."""
    n = len(y)
    p = len(X[0]) if n else 0
    # Design matrix with leading intercept column.
    A = [[1.0] + list(row) for row in X]
    m = p + 1
    # Normal equations: (A^T A) beta = A^T y
    ata = [[0.0] * m for _ in range(m)]
    aty = [0.0] * m
    for i in range(n):
        row = A[i]
        yi = y[i]
        for a in range(m):
            ra = row[a]
            if ra != 0.0:
                aty[a] += ra * yi
                rat = ata[a]
                for b in range(a, m):
                    rat[b] += ra * row[b]
    for a in range(m):
        for b in range(a):
            ata[a][b] = ata[b][a]
    beta = _gauss_solve(ata, aty)
    pred = []
    for i in range(n):
        row = A[i]
        s = 0.0
        for a in range(m):
            s += beta[a] * row[a]
        pred.append(s)
    return pred


def _gauss_solve(M, v):
    """Solve M x = v; if M is singular, fall back to a tiny ridge term."""
    m = len(M)
    A = [list(row) + [v[i]] for i, row in enumerate(M)]
    for col in range(m):
        piv = max(range(col, m), key=lambda r: abs(A[r][col]))
        if abs(A[piv][col]) < 1e-300:
            A[piv][col] = 1e-300
        A[col], A[piv] = A[piv], A[col]
        pv = A[col][col]
        for r in range(m):
            if r == col:
                continue
            f = A[r][col] / pv
            if f != 0.0:
                for c in range(col, m + 1):
                    A[r][c] -= f * A[col][c]
    return [A[i][m] / A[i][i] for i in range(m)]


def linear_regression_r2(data, target):
    """Fit OLS (with intercept) predicting ``target`` from the other columns of
    ``data`` and return the R^2 of that fit on the same data, as a float."""
    X, y = _to_float_matrix(data, target)
    if not y:
        return 0.0
    try:
        pred = _solve_lstsq_numpy(X, y)
    except Exception:
        pred = _solve_lstsq_pure(X, y)
    return float(_r2_from_predictions(y, pred))

