import csv
import io
import math


def _cube_root(value):
    """Return the real cube root of ``value`` (negative for negative input)."""
    root = math.cbrt(value)
    if not math.isfinite(root):
        return root
    # Snap perfect cubes to their exact integer root so that e.g. 27 -> 3.0
    # instead of a value one ulp away.
    nearest = round(root)
    if nearest != 0 and nearest ** 3 == value:
        return float(nearest)
    return root


def _resolve(header, name):
    """Return the actual header entry for a requested column name."""
    if name in header:
        return name
    stripped = name.strip()
    for entry in header:
        if entry.strip() == stripped:
            return entry
    raise KeyError(name)


def csv_cube_roots(csv_text, columns):
    """Parse ``csv_text`` and compute cube roots for the requested columns.

    Args:
        csv_text: Text of a CSV file with a header row.
        columns: List of column names whose cube roots are requested.

    Returns:
        A tuple ``(all_columns, requested_cube_roots)`` where ``all_columns``
        maps every column name in the file to the list of its float values in
        row order, and ``requested_cube_roots`` maps each requested column
        name to the list of cube roots of its values.

    Raises:
        KeyError: If a requested column is not present in the file.
        ValueError: If any value in the file is not numeric.
    """
