    try:
        header = next(reader)
    except StopIteration:
        header = []

    # Validate the requested columns first (raises KeyError when missing).
    resolved = {name: _resolve(header, name) for name in columns}

    values = {name: [] for name in header}
    for row in reader:
        if not row or all(cell.strip() == "" for cell in row):
            # Skip completely blank lines.
            continue
        for index, name in enumerate(header):
            cell = row[index] if index < len(row) else ""
            try:
                number = float(cell)
            except (TypeError, ValueError):
                raise ValueError(
                    "Non-numeric value %r in column %r" % (cell, name)
                )
            values[name].append(number)

    requested = {
        name: [_cube_root(value) for value in values[resolved[name]]]
        for name in columns
    }
    return values, requested

