"""Self-contained helper for computing a Pearson correlation matrix from CSV text."""

import csv
import io
import math


def _to_float(value):
    """Convert a CSV cell to a float, tolerating surrounding whitespace."""
    if value is None:
        raise ValueError("missing value in numeric CSV")
    text = value.strip()
    if text == "":
        raise ValueError("empty value in numeric CSV")
    return float(text)


def correlation_matrix_from_csv(csv_text):
    """Return the pairwise Pearson correlation matrix of the numeric columns.

    ``csv_text`` is the full text of a CSV file whose first line is a header
    row and whose remaining rows are numeric values.  The result is a dict of
    dicts: ``result[a][b]`` is the Pearson correlation between column ``a``
    and column ``b``.  The matrix is symmetric and its diagonal is 1.0.
    """
    if not isinstance(csv_text, str):
        csv_text = str(csv_text)

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row and any(cell.strip() != "" for cell in row)]
    if not rows:
        return {}

    header = [cell.strip() for cell in rows[0]]
    n_cols = len(header)

    columns = [[] for _ in range(n_cols)]
    for row in rows[1:]:
        for i in range(n_cols):
            cell = row[i] if i < len(row) else ""
            columns[i].append(_to_float(cell))

    n = len(columns[0]) if columns else 0
    for col in columns:
        if len(col) != n:
            raise ValueError("columns have different numbers of rows")

    # Per-column sums used by the Pearson correlation formula.
    sums = [math.fsum(col) for col in columns]
    sq_sums = [math.fsum(x * x for x in col) for col in columns]

    def _corr(i, j):
        if i == j:
            return 1.0
        if n == 0:
            return 0.0
        sx, sy = sums[i], sums[j]
        var_x = n * sq_sums[i] - sx * sx
        var_y = n * sq_sums[j] - sy * sy
        if var_x <= 0.0 or var_y <= 0.0:
            # A constant column has no defined correlation with others.
            return 0.0
        sxy = math.fsum(columns[i][k] * columns[j][k] for k in range(n))
        numerator = n * sxy - sx * sy
        value = numerator / (math.sqrt(var_x) * math.sqrt(var_y))
        # Guard against tiny floating point overshoot of the [-1, 1] range.
        return max(-1.0, min(1.0, value))

    result = {}
    for a, name_a in enumerate(header):
        result[name_a] = {name_b: _corr(a, b) for b, name_b in enumerate(header)}
    return result

