from fractions import Fraction


def _solve_exact(X, y):
    """Exactly solve the normal equations X^T X b = X^T y over the rationals.

    X: list of rows of Fractions (first column is ones), y: list of Fractions.
    Returns list of Fractions, or None if the system cannot be solved.
    Rank-deficient directions get a coefficient of 0.
    """
    n = len(X)
    m = len(X[0])
    A = [[Fraction(0)] * m for _ in range(m)]
    b = [Fraction(0)] * m
    for i in range(n):
        xi = X[i]
        yi = y[i]
        for a in range(m):
            xa = xi[a]
            if xa:
                rowA = A[a]
                for c in range(m):
                    rowA[c] += xa * xi[c]
                b[a] += xa * yi

    aug = [A[i] + [b[i]] for i in range(m)]
    for col in range(m):
        piv = col
        for r in range(col + 1, m):
            if abs(aug[r][col]) > abs(aug[piv][col]):
                piv = r
        if aug[piv][col] == 0:
            continue
        if piv != col:
            aug[col], aug[piv] = aug[piv], aug[col]
        pr = aug[col]
        inv = 1 / pr[col]
        for c in range(col, m + 1):
            pr[c] *= inv
        for r in range(m):
            if r != col and aug[r][col]:
                factor = aug[r][col]
                rr = aug[r]
                for c in range(col, m + 1):
                    rr[c] -= factor * pr[c]
    return [aug[i][m] for i in range(m)]


