    for i in range(n):
        xi = X[i]
        yi = y[i]
        for a in range(m):
            xa = xi[a]
            if xa != 0.0:
                rowA = A[a]
                for c in range(m):
                    rowA[c] += xa * xi[c]
                b[a] += xa * yi
    aug = [A[i] + [b[i]] for i in range(m)]
    for col in range(m):
        piv = col
        best = abs(aug[col][col])
        for r in range(col + 1, m):
            v = abs(aug[r][col])
            if v > best:
                best = v
                piv = r
        if best <= 1e-12:
