"""Cluster rows into 3 groups with k-means after per-column standardization."""

import math
import random


def _standardize(rows):
    """Scale every column to zero mean and unit variance (population std)."""
    n = len(rows)
    if n == 0:
        return []
    m = len(rows[0])
    means = [0.0] * m
    for r in rows:
        for j in range(m):
            means[j] += float(r[j])
    means = [v / n for v in means]

    variances = [0.0] * m
    for r in rows:
        for j in range(m):
            d = float(r[j]) - means[j]
            variances[j] += d * d
    stds = [math.sqrt(v / n) for v in variances]

    out = []
    for r in rows:
        out.append([
            (float(r[j]) - means[j]) / stds[j] if stds[j] > 0.0 else 0.0
            for j in range(m)
        ])
    return out


def _dist2(a, b):
    s = 0.0
    for x, y in zip(a, b):
        d = x - y
        s += d * d
    return s


def _kmeans(points, k, rng, max_iter=300):
    """One run of k-means (k-means++ init). Returns (labels, inertia)."""
    n = len(points)
    # k-means++ initialization
    centers = [list(points[rng.randrange(n)])]
    while len(centers) < k:
        d2 = []
        for p in points:
            best = None
            for c in centers:
                dd = _dist2(p, c)
                if best is None or dd < best:
                    best = dd
            d2.append(best if best is not None else 0.0)
        total = sum(d2)
        if total <= 0.0:
            # all points identical to existing centers; pick any point
            idx = rng.randrange(n)
        else:
            target = rng.random() * total
            acc = 0.0
            idx = n - 1
            for i, v in enumerate(d2):
                acc += v
                if acc >= target:
                    idx = i
                    break
        centers.append(list(points[idx]))

    labels = [0] * n
    for _ in range(max_iter):
        changed = False
        for i, p in enumerate(points):
            best_c = 0
            best_d = None
            for c, center in enumerate(centers):
                dd = _dist2(p, center)
                if best_d is None or dd < best_d:
                    best_d = dd
                    best_c = c
            if labels[i] != best_c:
                labels[i] = best_c
                changed = True
        # update centers
        sums = [[0.0] * len(points[0]) for _ in range(k)]
        counts = [0] * k
        for i, p in enumerate(points):
            c = labels[i]
            counts[c] += 1
            row = sums[c]
            for j, v in enumerate(p):
                row[j] += v
        for c in range(k):
            if counts[c] == 0:
                # empty cluster: move to the point farthest from its center
                far_i = max(range(n), key=lambda i: _dist2(points[i], centers[labels[i]]))
                centers[c] = list(points[far_i])
            else:
                centers[c] = [v / counts[c] for v in sums[c]]
        if not changed:
            break

    inertia = sum(_dist2(points[i], centers[labels[i]]) for i in range(n))
    return labels, inertia


