    """Rescale each column of ``data`` independently to the range [0, 1].

    Parameters
    ----------
    data:
        A dict mapping column names to equal-length lists of numbers.

    Returns
    -------
    dict
        A new dict with the same keys, each mapped to a list of floats in
        the original order.  The minimum of each column becomes 0.0 and the
        maximum becomes 1.0.  Columns whose values are all equal become all
        0.0.

    Raises
    ------
    ValueError
        If ``data`` is empty or if any column contains non-numeric values.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")
    if not data:
        raise ValueError("data must not be empty")

    result = {}
    for name, column in data.items():
        values = list(column) if not isinstance(column, str) else column
        if isinstance(column, str) or not hasattr(column, "__iter__"):
            raise ValueError("column %r must be a list of numbers" % (name,))

        for value in values:
            if not _is_numeric(value):
                raise ValueError(
                    "column %r contains a non-numeric value: %r" % (name, value)
                )

        if not values:
            result[name] = []
            continue

        low = min(values)
        high = max(values)
        span = high - low
        if span == 0:
            result[name] = [0.0 for _ in values]
        else:
            result[name] = [(float(v) - float(low)) / float(span) for v in values]

    return result

