"""Joined ordinary least-squares linear regression.

Self-contained: only the Python standard library is required.  Well-posed
(full rank) problems of modest size are solved exactly with rational
arithmetic, which yields correctly rounded results; rank-deficient or very
large problems fall back to a floating point least-squares solver (numpy when
available, otherwise a pure-Python normal-equation solver).
"""

from fractions import Fraction

# Above these sizes the exact rational solver is skipped (performance).
_EXACT_MAX_ROWS = 2000
_EXACT_MAX_COLS = 40


def _to_float(value):
    """Convert a value to a float (missing/None counts as 0.0)."""
    if value is None:
        return 0.0
    if isinstance(value, bool):
        return 1.0 if value else 0.0
    return float(value)


def _to_fraction(value):
    """Convert a value to an exact Fraction."""
    if value is None:
        return Fraction(0)
    if isinstance(value, Fraction):
        return value
    if isinstance(value, bool):
        return Fraction(1 if value else 0)
    if isinstance(value, int):
        return Fraction(value)
    if isinstance(value, float):
        return Fraction(value)
    return Fraction(str(value))


def _solve_exact(matrix, rhs):
    """Solve a square rational linear system exactly by Gaussian elimination.

    Returns None when the matrix is singular (rank deficient).
    """
    n = len(matrix)
    if n == 0:
        return []
    a = [list(row) + [rhs[i]] for i, row in enumerate(matrix)]
    for col in range(n):
        pivot_row = None
        for r in range(col, n):
            if a[r][col] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return None  # singular
        if pivot_row != col:
            a[col], a[pivot_row] = a[pivot_row], a[col]
        pivot = a[col][col]
        for r in range(col + 1, n):
            if a[r][col] == 0:
                continue
            factor = a[r][col] / pivot
            for c in range(col, n + 1):
                a[r][c] -= factor * a[col][c]
    x = [Fraction(0)] * n
    for i in range(n - 1, -1, -1):
        s = a[i][n]
        for j in range(i + 1, n):
            if x[j] != 0:
                s -= a[i][j] * x[j]
        x[i] = s / a[i][i]
    return x


def _lstsq_exact(design, y):
    """Exact least-squares solution of ``design @ beta ~ y``; None if singular."""
    n = len(design)
    m = len(design[0]) if n else 0
    if m == 0:
        return []
    gram = [[Fraction(0)] * m for _ in range(m)]
    rhs = [Fraction(0)] * m
    for i in range(m):
        for j in range(i, m):
            s = Fraction(0)
            for r in range(n):
                s += design[r][i] * design[r][j]
            gram[i][j] = s
            gram[j][i] = s
        s = Fraction(0)
        for r in range(n):
            s += design[r][i] * y[r]
        rhs[i] = s
    return _solve_exact(gram, rhs)


def _solve_float(matrix, rhs):
    """Solve a square float linear system with partial pivoting."""
    n = len(matrix)
    if n == 0:
        return []
    a = [list(row) + [rhs[i]] for i, row in enumerate(matrix)]
    scale = max(max(abs(v) for v in row[:n]) for row in a) or 1.0
    tol = 1e-12 * scale * max(n, 1)
    for col in range(n):
        pivot_row = max(range(col, n), key=lambda r: abs(a[r][col]))
        if abs(a[pivot_row][col]) <= tol:
            continue
        if pivot_row != col:
            a[col], a[pivot_row] = a[pivot_row], a[col]
        pivot = a[col][col]
        for r in range(col + 1, n):
            factor = a[r][col] / pivot
            if factor == 0.0:
                continue
            for c in range(col, n + 1):
                a[r][c] -= factor * a[col][c]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        if abs(a[i][i]) <= tol:
            x[i] = 0.0
            continue
        s = a[i][n] - sum(a[i][j] * x[j] for j in range(i + 1, n))
        x[i] = s / a[i][i]
    return x


def _lstsq_float(design, y):
    """Float least-squares solution via the normal equations."""
    n = len(design)
    m = len(design[0]) if n else 0
    if m == 0:
        return []
    gram = [[0.0] * m for _ in range(m)]
    rhs = [0.0] * m
    for i in range(m):
        for j in range(i, m):
            s = 0.0
            for r in range(n):
                s += design[r][i] * design[r][j]
            gram[i][j] = s
            gram[j][i] = s
        s = 0.0
        for r in range(n):
            s += design[r][i] * y[r]
        rhs[i] = s
    return _solve_float(gram, rhs)


def _lstsq_numpy(design, y):
    """Least-squares (minimum-norm for rank-deficient systems) via numpy."""
    import numpy as np
    arr = np.asarray(design, dtype=float)
    target = np.asarray(y, dtype=float)
    if arr.ndim != 2 or arr.shape[0] == 0 or arr.shape[1] == 0:
        return [0.0] * (arr.shape[1] if arr.ndim == 2 else 0)
    beta = np.linalg.lstsq(arr, target, rcond=None)[0]
    return [float(b) for b in beta]


def _lstsq(design, y):
    """Least-squares solution of ``design @ beta ~ y`` (intercept column first)."""
    n = len(design)
    m = len(design[0]) if n else 0
    if not n or not m:
        return [Fraction(0)] * m if isinstance(y[0], Fraction) else [0.0] * m
    # Exact rational solve for modest, full-rank problems (correctly rounded).
    if n <= _EXACT_MAX_ROWS and m <= _EXACT_MAX_COLS and isinstance(y[0], Fraction):
        try:
            beta = _lstsq_exact(design, y)
        except Exception:
            beta = None
        if beta is not None:
            return beta
    try:
        return _lstsq_numpy(design, y)
    except Exception:
        return _lstsq_float(design, y)


def fit_joined_regression(feature_rows, target_rows, features, target):
    """Fit an OLS linear regression with intercept on rows joined by 'id'.

    Parameters
    ----------
    feature_rows : list of dict
        Rows with a unique 'id' key plus the ``features`` columns.
    target_rows : list of dict
        Rows with a unique 'id' key plus the ``target`` column.
    features : list of str
        Predictor column names, in the desired coefficient order.
    target : str
        Name of the column to predict.

    Returns
    -------
    dict with keys
        'coefficients' : list of float, one per feature, in ``features`` order
        'intercept'    : float
        'residuals'    : list of float (observed minus predicted), one per
                         joined row, in ``feature_rows`` order
    """
    features = list(features)

    target_by_id = {}
    for row in target_rows:
        target_by_id[row['id']] = row

    joined = []
    for row in feature_rows:
        rid = row['id']
        if rid in target_by_id:
            joined.append((row, target_by_id[rid]))

    n = len(joined)
    m = len(features)

    if n == 0:
        return {'coefficients': [0.0] * m, 'intercept': 0.0, 'residuals': []}

    use_exact = n <= _EXACT_MAX_ROWS and m <= _EXACT_MAX_COLS
    design = []
    y = []
    for frow, trow in joined:
        if use_exact:
            design.append([Fraction(1)] + [_to_fraction(frow.get(f)) for f in features])
            y.append(_to_fraction(trow.get(target)))
        else:
            design.append([1.0] + [_to_float(frow.get(f)) for f in features])
            y.append(_to_float(trow.get(target)))

    beta = _lstsq(design, y)
    exact = bool(beta) and isinstance(beta[0], Fraction)
    intercept = float(beta[0])
    coefficients = [float(b) for b in beta[1:]]

    residuals = []
    for r in range(n):
        row = design[r]
        if exact:
            predicted = beta[0]
            for j in range(m):
                predicted += beta[j + 1] * row[j + 1]
            residuals.append(float(y[r] - predicted))
        else:
            predicted = intercept
            for j in range(m):
                predicted += coefficients[j] * float(row[j + 1])
            residuals.append(float(float(y[r]) - predicted))

    return {
        'coefficients': coefficients,
        'intercept': intercept,
        'residuals': residuals,
    }

