"""Self-contained implementation of integer_histogram_counts."""


def _parse_value(token):
    """Convert a single stripped token to an int, raising ValueError if not numeric."""
    if token == "":
        raise ValueError("empty value in data string")
    try:
        f = float(token)
    except (TypeError, ValueError):
        raise ValueError("non-numeric value: %r" % (token,))
    if f != f or f in (float("inf"), float("-inf")):
        raise ValueError("non-numeric value: %r" % (token,))
    try:
        return int(f)
    except (ValueError, OverflowError):
        raise ValueError("non-numeric value: %r" % (token,))


def integer_histogram_counts(data_str, separator=',', bins=20):
    """Parse a separated string of numbers and build an integer histogram.

    Returns (values, counts) where `values` is the list of integers in their
    original order and `counts` holds how many values fall into each of
    `bins` equal-width bins spanning [min(values), max(values)].  Each bin
    includes its left edge; the last bin also includes the maximum.

    Raises ValueError if the string is empty or any value isn't numeric.
    """
    if not isinstance(data_str, str):
        raise ValueError("data_str must be a string")
    if isinstance(bins, bool) or not isinstance(bins, (int, float)):
        raise ValueError("bins must be a positive integer")
    if isinstance(bins, float):
        if bins != int(bins):
            raise ValueError("bins must be a positive integer")
        bins = int(bins)
    if bins < 1:
        raise ValueError("bins must be a positive integer")

    stripped = data_str.strip()
    if stripped == "":
        raise ValueError("empty data string")

    if separator is None or separator == "":
        raise ValueError("separator must be a non-empty string")

    if separator.strip() == '':
        # A whitespace separator: any run of whitespace separates values.
        tokens = stripped.split()
    else:
        tokens = stripped.split(separator)
    values = [_parse_value(tok.strip()) for tok in tokens]
    if not values:
        raise ValueError("empty data string")

    lo = min(values)
    hi = max(values)
    counts = [0] * bins

    if hi == lo:
        # All values identical: everything falls in the first bin.
        counts[0] = len(values)
        return (values, counts)

    span = hi - lo
    for v in values:
        # Exact integer arithmetic: index of the bin whose left edge is <= v.
        idx = (v - lo) * bins // span
        if idx >= bins:  # the maximum belongs to the last bin
            idx = bins - 1
        if idx < 0:
            idx = 0
        counts[idx] += 1

    return (values, counts)

