"""Utility for computing grouped means from CSV text."""

import csv
import io


def _to_float(text):
    """Convert a string to a float, raising ValueError for non-numeric values."""
    return float(text)


def grouped_column_means(csv_text, group_col, value_col):
    """Group rows of a CSV by ``group_col`` and average ``value_col`` per group.

    Args:
        csv_text: The full text of a CSV file, including a header row.
        group_col: Name of the column whose values define the groups.
        value_col: Name of the column whose numeric values are averaged.

    Returns:
        A dict mapping each group label (as a string) to the mean of the
        numeric values in ``value_col`` for the rows of that group.

    Raises:
        ValueError: If ``group_col`` or ``value_col`` is not present in the
            header, or if a non-blank ``value_col`` cell is not numeric.
    """
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")

    group_col = str(group_col).strip()
    value_col = str(value_col).strip()

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text must contain a header row")

    header = [name.strip() for name in header]
    try:
        group_idx = header.index(group_col)
    except ValueError:
        raise ValueError("group column %r not found in header" % (group_col,))
    try:
        value_idx = header.index(value_col)
    except ValueError:
        raise ValueError("value column %r not found in header" % (value_col,))

    sums = {}
    counts = {}

    for row in reader:
        # Skip completely empty rows (e.g. trailing blank lines).
        if not row or all(cell.strip() == "" for cell in row):
            continue

        group_label = row[group_idx] if group_idx < len(row) else ""
        raw_value = row[value_idx] if value_idx < len(row) else ""

        if raw_value is None or raw_value.strip() == "":
            # Blank cells in the value column are ignored.
            continue

        try:
            value = _to_float(raw_value.strip())
        except (TypeError, ValueError):
            raise ValueError(
                "non-numeric value %r in column %r" % (raw_value, value_col)
            )

        sums[group_label] = sums.get(group_label, 0.0) + value
        counts[group_label] = counts.get(group_label, 0) + 1

    return {
        label: sums[label] / counts[label]
        for label in sums
        if counts[label] > 0
    }

