"""Utilities for parsing and sorting CSV text."""

import csv
import io
import re

# A strict numeric pattern: optional sign, digits with optional decimal part
# (in either "1.5", "1." or ".5" form) and an optional exponent.
_NUMBER_RE = re.compile(
    r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
)
_INT_RE = re.compile(r"^[+-]?\d+$")


def _is_number(text):
    """Return True if `text` is a (finite, decimal-looking) number."""
    return bool(_NUMBER_RE.match(text.strip()))


def _to_number(text):
    """Convert a numeric string to an int when possible, otherwise a float."""
    text = text.strip()
    if _INT_RE.match(text):
        return int(text)
    return float(text)


def _convert_column(values):
    """Return the values converted to numbers if all of them are numbers."""
    if values and all(_is_number(v) for v in values):
        return [_to_number(v) for v in values]
    return list(values)


def sort_csv_rows(csv_text, sort_by_column):
    """Parse CSV text and return its data rows sorted by `sort_by_column`.

    The first row of `csv_text` is treated as the header.  The result is a
    list of dicts (one per data row) mapping column names to values.  Columns
    whose values are all numbers are returned as ints/floats, all other
    columns as strings.

    Raises:
        ValueError: if `sort_by_column` is not present in the header row.
    """
    if not isinstance(csv_text, str):
        csv_text = str(csv_text)
    # Drop a possible byte-order mark at the start of the text.
    if csv_text.startswith("\ufeff"):
        csv_text = csv_text.lstrip("\ufeff")

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]

    if not rows:
        header = []
        data_rows = []
    else:
        header = [h.strip() for h in rows[0]]
        data_rows = rows[1:]

    if not isinstance(sort_by_column, str):
        raise ValueError("sort_by_column must be a string, got %r" % (sort_by_column,))
    sort_by_column = sort_by_column.strip()
    if sort_by_column not in header:
        raise ValueError(
            "Column %r not found in header %r" % (sort_by_column, header)
        )

    # Normalise row lengths so every row has one value per column.
    width = len(header)
    normalised = []
    for row in data_rows:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        normalised.append(row)

    # Decide the type of every column based on all of its values.
    converted = [
        _convert_column([row[i] for row in normalised]) for i in range(width)
    ]

    records = [dict(zip(header, record)) for record in zip(*converted)]

    records.sort(key=lambda record: record[sort_by_column])
    return records

