            # A comment runs up to (not including) the end of the line; the
            # line terminator itself is consumed as ordinary whitespace by
            # the loop above.
            while pos < end and data[pos] not in _NEWLINE:
                pos += 1
        else:
            break
    return pos


def _read_uint(data, pos, description):
    """Read one unsigned decimal integer token starting at/after ``pos``.

    Returns ``(value, new_pos)`` where ``new_pos`` points at the byte that
    immediately follows the digits.
    """
    pos = _skip_blanks_and_comments(data, pos)
    end = len(data)
    start = pos
    while pos < end and _DIGIT_MIN <= data[pos] <= _DIGIT_MAX:
        pos += 1
    if pos == start:
        raise ValueError(
            "invalid PGM data: expected %s at byte %d" % (description, pos)
        )
    return int(data[start:pos]), pos


def _parse_header(data):
    """Parse magic number, width, height and maxval.

    Returns ``(is_binary, width, height, maxval, pos)`` where ``pos`` is the
    index of the first byte of the raster (P5) or of the first sample token
    (P2).
    """
    if len(data) < 2:
        raise ValueError("invalid PGM data: file is too short")
    magic = data[:2]
    if magic == _BINARY_MAGIC:
        is_binary = True
    elif magic == _ASCII_MAGIC:
        is_binary = False
    else:
        raise ValueError(
            "invalid PGM data: unsupported magic number %r (expected P2 or P5)"
            % (magic,)
        )

    width, pos = _read_uint(data, 2, "a width")
    height, pos = _read_uint(data, pos, "a height")
    maxval, pos = _read_uint(data, pos, "a maximum value")

    if width <= 0 or height <= 0:
        raise ValueError(
            "invalid PGM data: dimensions must be positive (got %dx%d)"
            % (width, height)
        )
    # Only single-byte (8-bit) samples are supported.
    if not 1 <= maxval <= 255:
        raise ValueError(
            "invalid PGM data: maxval must be between 1 and 255 for an 8-bit "
            "image (got %d)" % (maxval,)
        )

    if is_binary:
        # A single whitespace character separates maxval from the raster (a
        # CRLF line ending is accepted as that one delimiter).
        if data[pos:pos + 2] == b"\r\n":
            pos += 2
        elif pos < len(data) and data[pos] in _WHITESPACE:
            pos += 1
        else:
            raise ValueError(
                "invalid PGM data: expected a single whitespace byte after maxval"
            )

    return is_binary, width, height, maxval, pos


def _check_sample(value, maxval):
    if not 0 <= value <= maxval:
        raise ValueError(
            "invalid PGM data: sample value %d is out of range 0..%d"
            % (value, maxval)
        )


def _parse_binary_raster(data, pos, width, height, maxval):
    """Return the list of sample values of a P5 raster."""
    count = width * height
    end = pos + count
    if len(data) < end:
        raise ValueError(
            "invalid PGM data: expected %d pixel bytes but only %d are present"
            % (count, len(data) - pos)
        )
    if len(data) > end:
        # Only trailing whitespace may follow the raster.
        if any(byte not in _WHITESPACE for byte in data[end:]):
            raise ValueError(
                "invalid PGM data: %d extra byte(s) after the pixel data"
                % (len(data) - end)
            )
    pixels = data[pos:end]
    for value in pixels:
        _check_sample(value, maxval)
    return pixels


def _parse_ascii_raster(data, pos, width, height, maxval):
    """Return the list of sample values of a P2 raster."""
    count = width * height
    pixels = []
    for _ in range(count):
        value, pos = _read_uint(data, pos, "a pixel value")
        _check_sample(value, maxval)
        pixels.append(value)
    # Nothing but whitespace/comments may follow the last sample.
    if _skip_blanks_and_comments(data, pos) != len(data):
        raise ValueError("invalid PGM data: extra data after the pixel values")
    return pixels


def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit grayscale PGM image.

    ``data`` must be the raw bytes of a PGM file, either the binary (``P5``)
    or the ASCII (``P2``) variant, with a maximum value of at most 255.

    The result is a ``dict`` mapping each pixel value (0-255) that occurs in
    the image to the number of pixels with that value, e.g.::

        >>> grayscale_histogram(b'P5\\n2 2\\n255\\n\\x00\\x01\\x02\\xff')
        {0: 1, 1: 1, 2: 1, 255: 1}

    A ``ValueError`` is raised if ``data`` is not a valid 8-bit grayscale PGM
    image.
    """
    if isinstance(data, (bytearray, memoryview)):
        data = bytes(data)
    if not isinstance(data, bytes):
        raise ValueError("data must be the raw bytes of a PGM image, got %r"
                         % (type(data).__name__,))

    is_binary, width, height, maxval, pos = _parse_header(data)

    if is_binary:
        pixels = _parse_binary_raster(data, pos, width, height, maxval)
    else:
        pixels = _parse_ascii_raster(data, pos, width, height, maxval)

    histogram = {}
    for value in pixels:
        histogram[value] = histogram.get(value, 0) + 1
    return histogram

