import operator


def _centered_moving_average(values, period):
    """Return the centred moving average of `values` with window `period`.

    Entries where the centred window does not fit are None.
    """
    n = len(values)
    trend = [None] * n
    if period % 2 == 1:
        half = period // 2
        for i in range(half, n - half):
            window = values[i - half:i + half + 1]
            trend[i] = sum(window) / period
    else:
        half = period // 2
        # average of two consecutive moving averages of length `period`
        for i in range(half, n - half):
            left = sum(values[i - half:i + half]) / period
            right = sum(values[i - half + 1:i + half + 1]) / period
            trend[i] = (left + right) / 2.0
    return trend


def classical_seasonal_decomposition(values, period, model='additive'):
    """Classical seasonal decomposition of an evenly spaced series.

    Parameters
    ----------
    values : sequence of numbers
        The evenly spaced observations.
    period : int
        The seasonal period.
    model : {'additive', 'multiplicative'}
        'additive' -> values = trend + seasonal + resid
        'multiplicative' -> values = trend * seasonal * resid

    Returns
    -------
    dict with keys 'trend', 'seasonal' and 'resid', each a list of the same
    length as `values`.  'trend' and 'resid' contain None where the centred
    moving average is not defined.
    """
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative', got %r" % (model,))

    try:
        period = operator.index(period)
    except TypeError:
        raise ValueError("period must be an integer, got %r" % (period,))
    if period < 1:
        raise ValueError("period must be a positive integer, got %r" % (period,))

    try:
        values = [float(v) for v in values]
    except (TypeError, ValueError):
        raise ValueError("values must be a sequence of real numbers")
    n = len(values)
    if n < 2 * period:
        raise ValueError(
            "series is shorter than two full periods (%d < %d)" % (n, 2 * period)
        )

    trend = _centered_moving_average(values, period)

    # detrended series
    detrended = [None] * n
    for i in range(n):
        if trend[i] is None:
            continue
        if model == 'additive':
            detrended[i] = values[i] - trend[i]
        else:
            if trend[i] == 0:
                continue
            detrended[i] = values[i] / trend[i]

    # average the detrended values per seasonal phase
    sums = [0.0] * period
    counts = [0] * period
    for i in range(n):
        if detrended[i] is None:
            continue
