        sums[phase] += detrended[i]
        counts[phase] += 1

    seasonal_raw = []
    for phase in range(period):
        if counts[phase] == 0:
            seasonal_raw.append(0.0 if model == 'additive' else 1.0)
        else:
            seasonal_raw.append(sums[phase] / counts[phase])

    # normalise so that the seasonal effect averages out over one period
    if model == 'additive':
        shift = sum(seasonal_raw) / period
        seasonal_pattern = [s - shift for s in seasonal_raw]
    else:
        scale = sum(seasonal_raw) / period
        if scale == 0:
            seasonal_pattern = seasonal_raw
        else:
            seasonal_pattern = [s / scale for s in seasonal_raw]

    seasonal = [seasonal_pattern[i % period] for i in range(n)]

    resid = [None] * n
    for i in range(n):
        if trend[i] is None:
            continue
        if model == 'additive':
            resid[i] = values[i] - trend[i] - seasonal[i]
        else:
            denom = trend[i] * seasonal[i]
            resid[i] = values[i] / denom if denom != 0 else None

    return {'trend': trend, 'seasonal': seasonal, 'resid': resid}

