"""Summarize the numeric columns of a CSV text.

The function :func:`summarize_numeric_csv` parses CSV text (with a header
row), decides which columns are entirely numeric (thousands separators such
as ``"1,000"`` are allowed) and returns the mean, the sample standard
deviation of every numeric column together with the F statistic of a one-way
ANOVA that treats the numeric columns as groups.
"""

import csv
import io
import math
import re

# A number, optionally with (correctly grouped) thousands separators.
_NUMBER_RE = re.compile(
    r"""^[+-]?                       # optional sign
        (?:
            \d{1,3}(?:,\d{3})+       # 1,000 / 12,345,678 (grouped thousands)
          | \d+                      # plain integer part
          | \.\d+                   # .5
        )
        (?:\.\d*)?                   # optional fractional part
        (?:[eE][+-]?\d+)?            # optional exponent
        $""",
    re.VERBOSE,
)


def _parse_number(text):
    """Return the float value of ``text`` or ``None`` if it is not a number."""
    if text is None:
        return None
    cleaned = text.strip()
    if not cleaned:
        return None
    if not _NUMBER_RE.match(cleaned):
        return None
    try:
        return float(cleaned.replace(",", ""))
    except (TypeError, ValueError):
        return None


def _mean(values):
    return math.fsum(values) / len(values)


def _sample_std_dev(values):
    """Sample (n-1) standard deviation; ``None`` when it is undefined."""
    n = len(values)
    if n < 2:
        return None
    mean = _mean(values)
    ss = math.fsum((v - mean) ** 2 for v in values)
    return math.sqrt(ss / (n - 1))


def _anova_f(groups):
    """F statistic of a one-way ANOVA over the given groups of numbers."""
    k = len(groups)
    if k < 2:
        return None
    n_total = sum(len(g) for g in groups)
    if n_total <= k:  # no degrees of freedom within groups
        return None
    grand_mean = math.fsum(v for g in groups for v in g) / n_total
    ss_between = 0.0
    ss_within = 0.0
    for g in groups:
        n_g = len(g)
        if n_g == 0:
            continue
        mean_g = math.fsum(g) / n_g
        ss_between += n_g * (mean_g - grand_mean) ** 2
        ss_within += math.fsum((v - mean_g) ** 2 for v in g)
    df_between = k - 1
    df_within = n_total - k
    if df_between <= 0 or df_within <= 0:
        return None
    ms_between = ss_between / df_between
    ms_within = ss_within / df_within
    if ms_within == 0.0:
        return None
    return ms_between / ms_within


def summarize_numeric_csv(csv_text):
    """Summarize the numeric columns of ``csv_text``.

    Returns a dict with the keys ``'means'``, ``'std_devs'`` and
    ``'f_value'``.  Columns containing any non-numeric value are ignored.
    """
    if csv_text is None:
        csv_text = ""
    if isinstance(csv_text, bytes):
        csv_text = csv_text.decode("utf-8-sig", "replace")
    else:
        csv_text = csv_text.lstrip("\ufeff")

    delimiter = ","
    first_line = csv_text.splitlines()[0] if csv_text.splitlines() else ""
    if "," not in first_line:
        for candidate in ("\t", ";", "|"):
            if candidate in first_line:
                delimiter = candidate
                break

    reader = csv.reader(io.StringIO(csv_text), delimiter=delimiter)
    try:
        rows = list(reader)
    except csv.Error:
        rows = []
    if not rows:
        return {"means": {}, "std_devs": {}, "f_value": None}

    header = [h.strip() for h in rows[0]]
    data_rows = rows[1:]

    columns = {}
    for index, name in enumerate(header):
        columns[index] = [row[index] if index < len(row) else "" for row in data_rows]

    means = {}
    std_devs = {}
    numeric_groups = []
    for index, name in enumerate(header):
        values = columns[index]
        parsed = [_parse_number(v) for v in values]
        if any(p is None for p in parsed):
            continue  # some value isn't a number -> ignore the column
        if not parsed:
            continue  # no data at all -> not a numeric column
        means[name] = _mean(parsed)
        std_devs[name] = _sample_std_dev(parsed)
        numeric_groups.append(parsed)

    return {
        "means": means,
        "std_devs": std_devs,
        "f_value": _anova_f(numeric_groups),
    }

