"""Maximum pairwise Euclidean distance between 2D points given as two lists."""

import math


def _dist(p, q):
    dx = p[0] - q[0]
    dy = p[1] - q[1]
    return math.sqrt(dx * dx + dy * dy)


def _cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def _convex_hull(points):
    """Andrew monotone chain; returns hull vertices in CCW order (no collinear points)."""
    pts = sorted(set(points))
    if len(pts) <= 1:
        return pts

    lower = []
    for p in pts:
        while len(lower) >= 2 and _cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and _cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]


def _hull_diameter(hull):
    """Rotating calipers on a convex polygon given in CCW order."""
    n = len(hull)
    if n == 1:
        return 0.0
    if n == 2:
        return _dist(hull[0], hull[1])

    best = 0.0
    k = 1
    for i in range(n):
        ni = (i + 1) % n
        # advance k while the area of triangle (hull[i], hull[ni], hull[k+1]) grows
        while True:
            nk = (k + 1) % n
            if _cross(hull[i], hull[ni], hull[nk]) > _cross(hull[i], hull[ni], hull[k]):
                k = nk
            else:
                break
        d = _dist(hull[i], hull[k])
        if d > best:
            best = d
        d = _dist(hull[ni], hull[k])
        if d > best:
            best = d
    return best


def max_pairwise_distance(xs, ys):
    """Return the largest Euclidean distance between any two distinct points.

    Points are (xs[i], ys[i]). Raises ValueError if the lists differ in length.
    Returns 0.0 when fewer than two points are given.
    """
    xs = list(xs)
    ys = list(ys)
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")
    n = len(xs)
    if n < 2:
        return 0.0

    points = [(float(x), float(y)) for x, y in zip(xs, ys)]
    hull = _convex_hull(points)
    if len(hull) <= 2:
        return _hull_diameter(hull)

    # For small hulls a direct scan is cheap and avoids caliper edge cases.
    if len(hull) <= 64:
        best = 0.0
        for i in range(len(hull)):
            for j in range(i + 1, len(hull)):
                d = _dist(hull[i], hull[j])
                if d > best:
                    best = d
        return best
    return _hull_diameter(hull)

