    def _flush(frame):
        """Close the currently open cell of ``frame`` (if any)."""
        if frame is not None and frame["buf"] is not None:
            if frame["collect"]:
                frame["cells"].append("".join(frame["buf"]).strip())
            frame["buf"] = None
            frame["collect"] = False

