        # e.g. <td/> -- behave like an empty start + end pair
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if tag in ("td", "th"):
            self._flush(self._top())
        elif tag == "tr":
            if self._stack:
                self._flush(self._stack.pop())

    def handle_data(self, data):
        frame = self._top()
        if frame is not None and frame["collect"] and frame["buf"] is not None:
            frame["buf"].append(data)

    def close(self):
        super().close()
        # Flush cells left open by missing </td>/</tr> at end of input.
        while self._stack:
            self._flush(self._stack.pop())


