import json
from html.parser import HTMLParser


class _TitleExtractor(HTMLParser):
    """Collect the text of the first <title> element in a document."""

    def __init__(self):
        # convert_charrefs=True makes the parser decode character references
        # (HTML entities) in the data for us.
        super().__init__(convert_charrefs=True)
        self.title = None
        self._in_title = False
        self._chunks = []

    def handle_starttag(self, tag, attrs):
        if self.title is None and tag.lower() == "title":
            self._in_title = True
            self._chunks = []

    def handle_startendtag(self, tag, attrs):
        # A self-closing <title/> has no text content.
        if self.title is None and tag.lower() == "title":
            self.title = ""

    def handle_endtag(self, tag):
        if self._in_title and tag.lower() == "title":
            self.title = "".join(self._chunks)
            self._in_title = False

    def handle_data(self, data):
        if self._in_title:
            self._chunks.append(data)

    def close(self):
        super().close()
        # If the document ended while still inside an unclosed <title>,
        # treat whatever text was collected as the title.
        if self._in_title and self.title is None:
            self.title = "".join(self._chunks)


def extract_title_json(html):
    """Return a JSON string with the page's title.

    The result is an object with a single key "title" whose value is the
    decoded text of the first <title> element, or null when the markup
    contains no <title> element.

    Example:
        >>> extract_title_json("<html><head><title>Hello World</title></head></html>")
        '{"title": "Hello World"}'
    """
    if html is None:
        html = ""
    if not isinstance(html, str):
        html = str(html)

    parser = _TitleExtractor()
    try:
        parser.feed(html)
        parser.close()
    except Exception:
        # Never let malformed markup break the caller: if nothing was
        # extracted before the error, report a missing title.
        if parser.title is None:
            return json.dumps({"title": None})

    return json.dumps({"title": parser.title})

