from html.parser import HTMLParser


class _ArticleParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.articles = []
        self.stack = []            # open tags
        self.article = None       # dict for the container we're inside
        self.container_depth = 0  # stack depth where the container started
        self.capture = None        # 'title' | 'date' | 'author' while capturing
        self.capture_depth = 0    # stack depth where the captured element started
        self.buf = []             # text buffer for the captured element

    def handle_starttag(self, tag, attrs):
        self.stack.append(tag)
        classes = (dict(attrs).get('class') or '').split()

        if self.article is None:
            if tag == 'div' and 'container' in classes:
                self.article = {'title': None, 'date': None, 'author': None}
                self.container_depth = len(self.stack)
            return

        if self.capture is not None:
            return  # inside the element we're capturing; ignore nested tags

        if tag == 'h1' and self.article['title'] is None:
            self.capture, self.capture_depth, self.buf = 'title', len(self.stack), []
        elif tag == 'span':
            if 'date' in classes and self.article['date'] is None:
                self.capture, self.capture_depth, self.buf = 'date', len(self.stack), []
            elif 'author' in classes and self.article['author'] is None:
                self.capture, self.capture_depth, self.buf = 'author', len(self.stack), []

    def handle_endtag(self, tag):
        # Pop until the matching tag (tolerates minor mismatches).
        while self.stack and self.stack.pop() != tag:
            pass

        # Finish capturing the current element's text.
        if self.capture is not None and len(self.stack) < self.capture_depth:
            self.article[self.capture] = ''.join(self.buf).strip()
            self.capture = None

        # Close the container: record the article.
        if self.article is not None and len(self.stack) < self.container_depth:
            a = self.article
            self.articles.append((
                a['title'] if a['title'] is not None else 'No Title',
                a['date'] if a['date'] is not None else 'No Date',
                a['author'] if a['author'] is not None else 'No Author',
            ))
            self.article = None

    def handle_data(self, data):
        if self.article is not None and self.capture is not None:
            self.buf.append(data)


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.close()
    return parser.articles

