                continue
            values_by_key.setdefault(key, []).append(float(value))

    result = {}
    for key in set(k for r in records for k in r) | set(values_by_key):
        vals = values_by_key.get(key, [])
        if not vals:
            result[key] = {'mean': None, 'median': None}
        else:
            result[key] = {
                'mean': sum(vals) / len(vals),
                'median': float(median(vals)),
            }
    return result
