def standardize_columns(rows, columns):
    n = len(rows)
    result = {}
    for idx, name in enumerate(columns):
        values = [row[idx] for row in rows]
        mean = sum(values) / n
        var = sum((v - mean) ** 2 for v in values) / n
        std = var ** 0.5
        if std == 0:
            result[name] = [0.0] * n
        else:
            result[name] = [(v - mean) / std for v in values]
    return result

