    cols2 = feature_columns(rows2)

    # --- Standardize the first table's feature columns ---
    # Compute per-column mean and (population) std, ignoring missing values.
    stats = {}
    for col in cols1:
        values = [row[col] for row in rows1 if row.get(col) is not None]
        if values:
            mean = sum(values) / len(values)
            var = sum((v - mean) ** 2 for v in values) / len(values)
            std = var ** 0.5
        else:
            mean, std = 0.0, 0.0
        stats[col] = (mean, std)

    # Map each row's id to its standardized feature values
    table1 = {}
    for row in rows1:
        rid = row['id']
        entry = {}
        for col in cols1:
            v = row.get(col)
            if v is None:
                entry[col] = None
            else:
                mean, std = stats[col]
                entry[col] = 0.0 if std == 0 else (v - mean) / std
        table1[rid] = entry

