    table2 = {}
    for row in rows2:
        rid = row['id']
        entry = {}
        for col in cols2:
            v = row.get(col)
            entry[col] = None if v is None else v
        table2[rid] = entry

    # --- Outer join on 'id', sorted by id ---
    all_ids = sorted(set(table1) | set(table2))
