def seasonal_decomposition(values, period, model):
    """
    Classical seasonal decomposition of a series.

    Parameters
    ----------
    values : list of numbers
    period : int, length of the seasonal cycle
    model  : 'additive' or 'multiplicative'

    Returns
    -------
    dict with keys 'trend', 'seasonal', 'residual', each a list the
    same length as `values` (None where undefined).
    """
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or period < 1:
        raise ValueError("period must be a positive integer")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    additive = (model == 'additive')

    # ---- Trend: centered moving average ----
    trend = [None] * n
    if period % 2 == 1:
        half = period // 2
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        # Even period: average a period-MA with a 2-MA of it to center.
        half = period // 2
        ma = [sum(values[j:j + period]) / period for j in range(n - period + 1)]
        for i in range(half, n - half):
            trend[i] = (ma[i - half] + ma[i - half + 1]) / 2

    # ---- Detrended series ----
    detrended = [None] * n
    for i in range(n):
        if trend[i] is not None:
            detrended[i] = values[i] - trend[i] if additive else values[i] / trend[i]

    # ---- Raw seasonal index per phase ----
    raw = []
    for ph in range(period):
        vals = [detrended[i] for i in range(ph, n, period)
                if detrended[i] is not None]
        raw.append(sum(vals) / len(vals))

    # Normalise: mean 0 (additive) or mean 1 (multiplicative)
    norm = sum(raw) / period
    if additive:
        indices = [x - norm for x in raw]
    else:
        indices = [x / norm for x in raw]

    seasonal = [indices[i % period] for i in range(n)]

    # ---- Residuals ----
    residual = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if additive:
                residual[i] = values[i] - trend[i] - seasonal[i]
            else:
                residual[i] = values[i] / (trend[i] * seasonal[i])

    return {'trend': trend, 'seasonal': seasonal, 'residual': residual}

