def grade_report(students, subjects, grades):
    report = {}
    for i, student in enumerate(students):
        student_grades = {}
        total = 0
        for j, subject in enumerate(subjects):
            student_grades[subject] = float(grades[i][j])
            total += grades[i][j]
        student_grades['Average Grade'] = total / len(subjects)
        report[student] = student_grades

    # Compute the 'Average' entry: mean of each subject, and mean of averages
    average_entry = {}
    total_avg = 0
    for j, subject in enumerate(subjects):
        subject_total = sum(grades[i][j] for i in range(len(students)))
        average_entry[subject] = subject_total / len(students)
    for student in students:
        total_avg += report[student]['Average Grade']
    average_entry['Average Grade'] = total_avg / len(students)
    report['Average'] = average_entry

    return report

def fit_linear_regression(rows, targets):
    """Fit ordinary least-squares linear regression with an intercept.

    Returns (coefficients, intercept).
    Raises ValueError if rows is empty or lengths of rows and targets differ.
    """
    if len(rows) == 0:
        raise ValueError("rows must not be empty")
    if len(rows) != len(targets):
        raise ValueError("rows and targets must have the same length")

    n_features = len(rows[0])

    # Design matrix: each row is [features..., 1] (the 1 is for the intercept).
    X = [list(row) + [1.0] for row in rows]
    y = [float(t) for t in targets]
    n_params = n_features + 1
    n = len(X)

    # Normal equations: (X^T X) beta = X^T y
    # Build the augmented matrix A = [X^T X | X^T y].
    A = [[0.0] * (n_params + 1) for _ in range(n_params)]
    for i in range(n_params):
        for j in range(n_params):
            s = 0.0
            for k in range(n):
                s += X[k][i] * X[k][j]
            A[i][j] = s
        s = 0.0
        for k in range(n):
            s += X[k][i] * y[k]
        A[i][n_params] = s

    # Gaussian elimination with partial pivoting on the augmented matrix.
    for col in range(n_params):
        # Find pivot row.
        pivot = max(range(col, n_params), key=lambda r: abs(A[r][col]))
        if abs(A[pivot][col]) < 1e-12:
            raise ValueError("singular design matrix; cannot fit regression")
        if pivot != col:
            A[col], A[pivot] = A[pivot], A[col]
        # Eliminate below the pivot.
        for r in range(col + 1, n_params):
            factor = A[r][col] / A[col][col]
            if factor != 0.0:
                for c in range(col, n_params + 1):
                    A[r][c] -= factor * A[col][c]

    # Back-substitution.
    beta = [0.0] * n_params
    for i in range(n_params - 1, -1, -1):
        s = A[i][n_params]
        for j in range(i + 1, n_params):
            s -= A[i][j] * beta[j]
        beta[i] = s / A[i][i]

    coefficients = [float(b) for b in beta[:n_features]]
    intercept = float(beta[n_features])
    return (coefficients, intercept)

import json
import math


def boxplot_stats_at_path(json_data, key_path):
    """Walk a nested JSON object via key_path to a comma-separated number
    string and compute standard boxplot statistics for those numbers."""
    # --- Parse the JSON ---
    try:
        current = json.loads(json_data)
    except (json.JSONDecodeError, TypeError):
        raise ValueError("Malformed JSON input")

    # --- Follow the key path through nested objects ---
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(f"Key not found: {key!r}")
        current = current[key]

    # --- Parse the comma-separated number string ---
    if not isinstance(current, str) or not current.strip():
        raise ValueError("Value at path must be a non-empty string of numbers")

    values = []
    for part in current.split(','):
        part = part.strip()
        if not part:
            raise ValueError("Empty or non-numeric entry in data string")
        try:
            values.append(float(part))
        except ValueError:
            raise ValueError(f"Non-numeric value in data string: {part!r}")

    values.sort()
    n = len(values)

    # --- Linear-interpolation percentile (numpy 'linear' method) ---
    def percentile(sorted_vals, p):
        if n == 1:
            return float(sorted_vals[0])
        idx = p * (n - 1)
        lo = math.floor(idx)
        hi = math.ceil(idx)
        if lo == hi:
            return float(sorted_vals[int(idx)])
        return sorted_vals[lo] + (sorted_vals[hi] - sorted_vals[lo]) * (idx - lo)

    q1 = percentile(values, 0.25)
    median = percentile(values, 0.50)
    q3 = percentile(values, 0.75)

    # --- Whiskers (1.5 * IQR rule) and outliers ---
    iqr = q3 - q1
    low_fence = q1 - 1.5 * iqr
    high_fence = q3 + 1.5 * iqr

    inliers = [v for v in values if low_fence <= v <= high_fence]
    outliers = [v for v in values if v < low_fence or v > high_fence]

    if inliers:
        whisker_low = min(inliers)
        whisker_high = max(inliers)
    else:  # defensive; can't normally happen since the median is always inside the fences
        whisker_low, whisker_high = q1, q3

    return {
        'q1': q1,
        'median': median,
        'q3': q3,
        'whisker_low': whisker_low,
        'whisker_high': whisker_high,
        'outliers': outliers,
    }

from datetime import datetime

WEEKDAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']

# Common date formats to try, in order
FORMATS = [
    '%Y-%m-%d',       # 2022-10-22
    '%Y/%m/%d',       # 2022/10/22
    '%b %d, %Y',      # Oct 22, 2022
    '%d %B %Y',       # 22 October 2022
    '%d %b %Y',       # 22 Oct 2022
    '%B %d, %Y',      # October 22, 2022
    '%B %d %Y',       # October 22 2022
    '%m/%d/%Y',       # 10/22/2022
    '%m-%d-%Y',       # 10-22-2022
    '%Y.%m.%d',       # 2022.10.22
    '%d %b %Y',       # (duplicate safety)
]


def _parse_date(date_string):
    """Try to parse a date string using known formats, with a dateutil fallback."""
    s = date_string.strip()
    for fmt in FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    # Fallback: use dateutil if installed (handles many more formats)
    try:
        from dateutil import parser
        return parser.parse(s)
    except Exception:
        raise ValueError(f"Unrecognized date format: {date_string!r}")


def weekday_distribution(date_strings):
    """Count how many dates fall on each day of the week.

    Returns a dict with keys 'Monday' through 'Sunday' (in that order),
    mapping to the number of dates that fall on that weekday.
    """
    counts = {day: 0 for day in WEEKDAYS}
    for date_string in date_strings:
        dt = _parse_date(date_string)
        counts[WEEKDAYS[dt.weekday()]] += 1
    return counts

