def xml_to_dict(s):
    """Parse an XML string into nested dictionaries.

    Rules:
      - The result maps the root tag to its converted content.
      - An element with only text (no children, no attributes) becomes that text.
      - An empty element (no children, no attributes, no text) becomes None.
      - Otherwise an element becomes a dict:
          * attributes -> '@name': value
          * child elements -> tag: value (list of values if the tag repeats)
          * element text  -> '#text': value
      - Raises ValueError if the input is empty/whitespace-only.
    """
    if s is None or not s.strip():
        raise ValueError("Input XML string is empty or whitespace only")

    try:
        root = ET.fromstring(s)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML: {e}")

    return {root.tag: _convert(root)}


def _convert(el):
    children = list(el)
    attrs = {f"@{name}": value for name, value in el.attrib.items()}
    text = (el.text or "").strip()

    # Element containing only text, or an empty element.
    if not children and not attrs:
        return text if text else None

    result = dict(attrs)

    if children:
        grouped = {}
        for child in children:  # document order preserved
            grouped.setdefault(child.tag, []).append(_convert(child))
        for tag, values in grouped.items():
            result[tag] = values[0] if len(values) == 1 else values
        if text:
            result["#text"] = text
    else:
        # Attributes (and possibly text) but no children.
        if text:
            result["#text"] = text

    return result
