from html.parser import HTMLParser


class _TableParser(HTMLParser):
    """Collects the rows of the table whose id matches a target id."""

    def __init__(self, table_id):
        # convert_charrefs=True makes HTMLParser decode entities (&amp;, &#39;, ...)
        # automatically and hand them to handle_data as plain text.
        super().__init__(convert_charrefs=True)
        self._table_id = table_id.strip().lower()
        self._depth = 0          # nesting depth inside the target table
        self.found = False      # whether a table with that id was seen
        self.rows = []          # completed rows, each a list of cell strings
        self._row = None        # cells of the row currently being parsed
        self._cell = None       # text fragments of the cell currently being parsed

    # -- helpers ---------------------------------------------------------

    def _at_top_of_target(self):
        return self._depth == 1

    def _flush_cell(self):
        if self._row is not None and self._cell is not None:
            self._row.append(''.join(self._cell).strip())
        self._cell = None

    # -- HTMLParser callbacks --------------------------------------------

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            if self._depth:
                # nested table inside the target table
                self._depth += 1
            else:
                for name, value in attrs:
                    if (name and name.lower() == 'id'
                            and value is not None
                            and value.strip().lower() == self._table_id):
                        self._depth = 1
                        self.found = True
                        break
            return
        if not self._at_top_of_target():
            return
        if tag == 'tr':
            self._flush_cell()
            self._row = []
        elif tag in ('td', 'th'):
            self._flush_cell()
            self._cell = []

    def handle_endtag(self, tag):
        if tag == 'table':
            if self._depth:
                self._depth -= 1
                if self._depth == 0:
                    self._flush_cell()
            return
        if not self._at_top_of_target():
            return
        if tag in ('td', 'th'):
            self._flush_cell()
