            self._row = None

    def handle_data(self, data):
        # Tags inside a cell contribute nothing here; only text is collected,
        # so nested markup is naturally "removed".
        if self._at_top_of_target() and self._cell is not None:
            self._cell.append(data)


def html_table_records(html, table_id):
    """Extract data records from the table with the given id.

    The first row of the table supplies the headers; each later row becomes
    a dict mapping header -> cell text (tags stripped, entities decoded,
    whitespace stripped). Returns [] for a header-only table, and raises
    ValueError if no table has that id.
    """
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError("no table with id {!r}".format(table_id))

    rows = parser.rows
    if not rows:
        return []

    headers = rows[0]
    return [dict(zip(headers, row)) for row in rows[1:]]

