import ast


class _ScriptBodyExtractor(HTMLParser):
    """Collects the raw text of each <script> element, in document order."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._in_script = False
        self._current = None
        self.bodies = []

    def handle_starttag(self, tag, attrs):
        if tag == "script":
            self._in_script = True
            self._current = []

    def handle_endtag(self, tag):
        if tag == "script" and self._in_script:
            self.bodies.append("".join(self._current))
            self._in_script = False
            self._current = None

    def handle_data(self, data):
        if self._in_script:
            self._current.append(data)


def extract_script_dicts(html):
    """Return a list of dict literals found in <script> bodies, in document order.

    Any script whose content is not a valid Python dict literal is skipped.
    """
    parser = _ScriptBodyExtractor()
    parser.feed(html)
    parser.close()

    results = []
    for body in parser.bodies:
        try:
            value = ast.literal_eval(body)
        except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
            continue  # not a valid literal
        if isinstance(value, dict):
            results.append(value)
    return results

from datetime import datetime, date
import calendar

_WEEKDAYS = {'MON': 0, 'TUE': 1, 'WED': 2, 'THU': 3, 'FRI': 4, 'SAT': 5, 'SUN': 6}


def _month_ends(start):
    """Yield the last day of each month, beginning with start's month."""
    y, m = start.year, start.month
    while True:
        last = calendar.monthrange(y, m)[1]
        d = date(y, m, last)
        if d >= start:
            yield d
        m += 1
        if m == 13:
            m, y = 1, y + 1


def _quarter_ends(start):
    """Yield the last day of Mar/Jun/Sep/Dec, beginning with start's quarter."""
    m = (start.month - 1) // 3 * 3 + 3      # -> 3, 6, 9 or 12
    y = start.year
    while True:
        last = calendar.monthrange(y, m)[1]
        d = date(y, m, last)
        if d >= start:
            yield d
        m += 3
        if m > 12:
            m, y = m - 12, y + 1


def _nth_weekdays(start, week, weekday):
    """Yield the `week`-th occurrence of `weekday` in each month."""
    y, m = start.year, start.month
    while True:
        first = date(y, m, 1)
        day = 1 + (weekday - first.weekday()) % 7 + (week - 1) * 7
        d = date(y, m, day)
        if d >= start:
            yield d
        m += 1
        if m == 13:
            m, y = 1, y + 1


def forecast_schedule(start_date, freq, sales):
    # Validate the start date.
    try:
        start = datetime.strptime(start_date, '%Y-%m-%d').date()
    except (ValueError, TypeError):
        raise ValueError(f'Invalid start date: {start_date!r}')

    # Choose the appropriate infinite date generator.
    if freq == 'month-end':
        date_iter = _month_ends(start)
    elif freq == 'quarter-end':
        date_iter = _quarter_ends(start)
    else:
        try:
            week_str, weekday_str = freq.split('-')
            week = int(week_str)
            weekday = _WEEKDAYS[weekday_str]
            if week not in (1, 2, 3, 4):
                raise ValueError
        except (ValueError, KeyError, AttributeError):
            raise ValueError(f'Invalid freq: {freq!r}')
        date_iter = _nth_weekdays(start, week, weekday)

    # zip stops automatically once the sales figures run out.
    return [(d.strftime('%Y-%m-%d'), s) for d, s in zip(date_iter, sales)]

