def country_score_summary(records):
    """
    Given a list of record dicts with 'Name', 'Country' and 'Score' keys,
    keep only the first record for each name, then return a dict mapping
    each country to the five-number summary [min, Q1, median, Q3, max]
    of its scores. Quartiles use linear interpolation between sorted values.
    """
    if not isinstance(records, list) or not records:
        raise ValueError("records must be a non-empty list")

    required = ('Name', 'Country', 'Score')
    seen_names = set()
    country_scores = {}

    for rec in records:
        if not isinstance(rec, dict):
            raise ValueError("each record must be a dict")
        for key in required:
            if key not in rec:
                raise ValueError(f"record missing required key: {key!r}")

        name = rec['Name']
        if name in seen_names:
            continue
        seen_names.add(name)

        country_scores.setdefault(rec['Country'], []).append(float(rec['Score']))

    def quantile(sorted_vals, q):
        """Linear-interpolated q-th quantile (0 <= q <= 1) of sorted values."""
        if len(sorted_vals) == 1:
            return float(sorted_vals[0])
        pos = q * (len(sorted_vals) - 1)
        lower = int(pos)
        frac = pos - lower
        if lower + 1 < len(sorted_vals):
            return sorted_vals[lower] + frac * (sorted_vals[lower + 1] - sorted_vals[lower])
        return float(sorted_vals[lower])

    summary = {}
    for country, scores in country_scores.items():
        scores.sort()
        summary[country] = [
            scores[0],
            quantile(scores, 0.25),
            quantile(scores, 0.50),
            quantile(scores, 0.75),
            scores[-1],
        ]
    return summary
