def extract_absolute_links(html, base_url):
    """
    Extract all href values from <a> tags in the given HTML,
    resolve them against base_url, and return the unique
    absolute URLs as a sorted list.
    """
    hrefs = []

    class LinkParser(HTMLParser):
        def handle_starttag(self, tag, attrs):
            if tag == 'a':
                for name, value in attrs:
                    if name == 'href' and value is not None:
                        hrefs.append(value)

    parser = LinkParser()
    parser.feed(html)
    parser.close()

    absolute = {urljoin(base_url, href) for href in hrefs}
    return sorted(absolute)

