        if vals and all(is_number(v) for v in vals)
    }
    if not numeric_cols:
        raise ValueError("No numeric columns found")

    # --- Pearson correlation helper ---
    def pearson(xs, ys):
        mean_x = sum(xs) / n
        mean_y = sum(ys) / n
        cov = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
        var_x = sum((x - mean_x) ** 2 for x in xs)
        var_y = sum((y - mean_y) ** 2 for y in ys)
        denom = math.sqrt(var_x * var_y)
        if denom == 0:
            # Zero variance: define self-correlation as 1.0, else 0.0
            return 1.0 if var_x == 0 and var_y == 0 and xs == ys else 0.0
        return cov / denom

    # --- Build the matrix ---
    result = {}
    for col_a in numeric_cols:
        row = {}
        for col_b in numeric_cols:
            if col_a == col_b:
                row[col_b] = 1.0
            else:
                row[col_b] = pearson(numeric_cols[col_a], numeric_cols[col_b])
        result[col_a] = row
    return result
