def standardize_filtered(data, age, weight):
    # Raise KeyError if 'Age' or 'Weight' is missing
    if 'Age' not in data:
        raise KeyError("'Age' column is missing")
    if 'Weight' not in data:
        raise KeyError("'Weight' column is missing")

    columns = list(data.keys())
    n = None
    for col in columns:
        if n is None:
            n = len(data[col])
        # assume equal lengths per problem statement

    # Keep rows where Age < age and Weight > weight
    keep = [i for i in range(n) if data['Age'][i] < age and data['Weight'][i] > weight]

    if not keep:
        return {col: [] for col in columns}

    result = {}
    for col in columns:
        values = [data[col][i] for i in keep]
        m = len(values)
        mean = sum(values) / m
        # Population standard deviation
        std = (sum((v - mean) ** 2 for v in values) / m) ** 0.5
        if std == 0:
            result[col] = [0.0] * m
        else:
            result[col] = [(v - mean) / std for v in values]
    return result
