import random


def cluster_point_labels(data, n_clusters):
    if not data:
        raise ValueError("data must not be empty")
    if n_clusters < 1:
        raise ValueError("n_clusters must be at least 1")

    points = [(float(x), float(y)) for _, x, y in data]
    n = len(points)
    k = min(n_clusters, n)

    if k == 1:
        return [0] * n

    # ---- k-means++ initialization (deterministic via seeded RNG) ----
    rng = random.Random(0)
    centroids = [points[rng.randrange(n)]]
    while len(centroids) < k:
        d2 = [min((px - cx) ** 2 + (py - cy) ** 2 for cx, cy in centroids)
              for px, py in points]
        total = sum(d2)
        if total == 0:  # all points coincide with existing centroids
            centroids.append(points[rng.randrange(n)])
            continue
        r = rng.random() * total
        acc = 0.0
        for i, d in enumerate(d2):
            acc += d
            if acc >= r:
                centroids.append(points[i])
                break
        else:
            centroids.append(points[-1])

    # ---- Lloyd's algorithm ----
    labels = [None] * n
    for _ in range(300):
        # assign each point to nearest centroid
        new_labels = []
        for px, py in points:
            best_i, best_d = 0, float("inf")
            for ci, (cx, cy) in enumerate(centroids):
                d = (px - cx) ** 2 + (py - cy) ** 2
                if d < best_d:
                    best_d, best_i = d, ci
            new_labels.append(best_i)
        if new_labels == labels:
            break
        labels = new_labels

        # recompute centroids; repair any empty cluster with the
        # point farthest from its current centroid
        sums = [[0.0, 0.0, 0] for _ in range(k)]
        for (px, py), l in zip(points, labels):
            sums[l][0] += px
            sums[l][1] += py
            sums[l][2] += 1
        for i in range(k):
            if sums[i][2] == 0:
                far_i, far_d = 0, -1.0
                for j, (px, py) in enumerate(points):
                    cx, cy = centroids[labels[j]]
                    d = (px - cx) ** 2 + (py - cy) ** 2
                    if d > far_d:
                        far_d, far_i = d, j
                centroids[i] = points[far_i]
            else:
                centroids[i] = (sums[i][0] / sums[i][2],
                                 sums[i][1] / sums[i][2])

    # ---- relabel clusters by first appearance in input order ----
    mapping = {}
    result = []
    for l in labels:
        if l not in mapping:
            mapping[l] = len(mapping)
        result.append(mapping[l])
    return result

