    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]  # skip blank lines

    if not rows:
        raise ValueError("CSV file has no header row")

    header = rows[0]
    data_rows = rows[1:]

    if sort_by_column not in header:
        raise ValueError(f"Column '{sort_by_column}' not found in header")

    # Determine which columns are entirely numeric
    numeric_columns = set()
    for col_idx, col_name in enumerate(header):
        if data_rows and all(_is_number(row[col_idx]) for row in data_rows):
