        if pos >= len(data):
            raise ValueError("unexpected end of file in header")
        start = pos
        while pos < len(data) and data[pos] not in WHITESPACE:
            pos += 1
        return data[start:pos], pos

    def read_int(pos):
        token, pos = read_token(pos)
        if not token.isdigit():
            raise ValueError("expected a non-negative integer, got %r" % token)
        return int(token), pos

    # --- header ---
    magic, pos = read_token(0)
    if magic not in (b"P5", b"P2"):
        raise ValueError("not a PGM file (magic number must be P2 or P5)")

    width, pos = read_int(pos)
    height, pos = read_int(pos)
    maxval, pos = read_int(pos)

    if width <= 0 or height <= 0:
        raise ValueError("invalid image dimensions")
    if not (1 <= maxval <= 255):
        raise ValueError("maxval must be between 1 and 255 for 8-bit grayscale")

    num_pixels = width * height
    histogram = {}

    if magic == b"P5":
        # A single whitespace character separates the header from the data.
        if pos >= len(data) or data[pos] not in WHITESPACE:
            raise ValueError("missing whitespace after maxval")
        pos += 1
        pixels = data[pos:]
        if len(pixels) != num_pixels:
            raise ValueError(
                "expected %d pixel bytes, got %d" % (num_pixels, len(pixels))
            )
        for v in pixels:
            if v > maxval:
                raise ValueError("pixel value %d exceeds maxval %d" % (v, maxval))
            histogram[v] = histogram.get(v, 0) + 1
    else:  # P2 (ASCII)
        for _ in range(num_pixels):
            value, pos = read_int(pos)
            if value > maxval:
                raise ValueError("pixel value %d exceeds maxval %d" % (value, maxval))
            histogram[value] = histogram.get(value, 0) + 1
        # only whitespace / comments may remain
        if skip_ws_and_comments(pos) != len(data):
            raise ValueError("extra data after pixel values")

    return histogram
```

Notes on the implementation:

- **Header parsing** handles arbitrary whitespace and `#` comments (which run to end of line), as allowed by the PGM format, for both variants.
- **P5 (binary):** after the `maxval` field, exactly one whitespace byte separates the header from the raster; the remaining bytes must number exactly `width * height`, and each must be `<= maxval`.
- **P2 (ASCII):** it reads exactly `width * height` whitespace-separated integers, rejects values above `maxval`, and then requires that nothing but whitespace/comments remains in the file.
- Invalid magic numbers, non-numeric header fields, non-positive dimensions, a `maxval` outside 1–255 (only 8-bit images are supported), truncated or excess pixel data, and out-of-range pixel values all raise `ValueError`.

