import csv
import io
import statistics


def summarize_numeric_csv(csv_text):
    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return {'means': {}, 'std_devs': {}, 'f_value': None}

    header = rows[0]
    data = rows[1:]

    def try_num(s):
        """Parse a number that may contain thousands separators, else None."""
        try:
            return float(s.replace(',', '').strip())
        except (ValueError, AttributeError):
            return None

    # Keep only columns where every value parses as a number.
    numeric = {}
    for i, name in enumerate(header):
        vals = [try_num(row[i]) if i < len(row) else None for row in data]
        if data and all(v is not None for v in vals):
            numeric[name] = vals

    means = {name: sum(vals) / len(vals) for name, vals in numeric.items()}
    std_devs = {name: statistics.stdev(vals) for name, vals in numeric.items()}

    f_value = None
    if len(numeric) >= 2:
        k = len(numeric)
        all_vals = [v for vals in numeric.values() for v in vals]
        n = len(all_vals)
        grand = sum(all_vals) / n

        # Between-group sum of squares
        ssb = sum(
            len(vals) * (means[name] - grand) ** 2
            for name, vals in numeric.items()
        )
        # Within-group sum of squares
        ssw = sum(
            sum((x - means[name]) ** 2 for x in vals)
            for name, vals in numeric.items()
        )

        df_b = k - 1
        df_w = n - k
        msb = ssb / df_b
        if df_w > 0:
            msw = ssw / df_w
            if msw > 0:
                f_value = msb / msw
            else:
                f_value = None if msb == 0 else float('inf')
        # df_w == 0 (one value per group): F is undefined -> stays None

    return {'means': means, 'std_devs': std_devs, 'f_value': f_value}
```

**How it works:**

- **Parsing:** The `csv` module correctly handles quoted fields, so `"1,000"` comes through as a single field. `try_num` strips thousands separators (and surrounding whitespace) and attempts a `float` conversion; failure means the column is non-numeric.
- **Column filtering:** A column is included only if *every* value parses as a number; otherwise it's ignored entirely.
- **Means & std devs:** Means are straightforward; sample standard deviation uses `statistics.stdev` (the `n − 1` denominator).
- **ANOVA F statistic:** With the numeric columns treated as groups:
  - $SS_{between} = \sum_g n_g (\bar{x}_g - \bar{x})^2$, with $df = k - 1$
  - $SS_{within} = \sum_g \sum_i (x_{gi} - \bar{x}_g)^2$, with $df = N - k$
  - $F = MS_{between} / MS_{within}$

  For the example: $SSB = 13.5$, $SSW = 4$, so $F = (13.5/1) / (4/4) = 13.5$. ✓

- **Edge cases:** Fewer than two numeric columns (or zero rows) gives `f_value = None`. Degenerate cases (zero within-group variance, or a single observation per group) return `None` or `inf` as appropriate, rather than raising a division-by-zero error.

