import math


def max_pairwise_distance(xs, ys):
    """Return the largest Euclidean distance between any two distinct points.

    Points are defined by (xs[i], ys[i]). Returns 0 for fewer than two
    points. Raises ValueError if the lists have different lengths.
    """
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n < 2:
        return 0

    max_dist = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(xs[i] - xs[j], ys[i] - ys[j])
            if d > max_dist:
                max_dist = d
    return max_dist

def standardize_columns(data):
    result = {}
    for col, values in data.items():
        n = len(values)
        if n == 0:
            result[col] = ([], [0] * 20)
            continue

        # Standardize: zero mean, unit (population) variance
        mean = sum(values) / n
        variance = sum((v - mean) ** 2 for v in values) / n
        std = variance ** 0.5
        if std == 0:
            standardized = [0.0] * n
        else:
            standardized = [(v - mean) / std for v in values]

        # 20-bin histogram over [min, max], max counted in last bin
        lo = min(standardized)
        hi = max(standardized)
        counts = [0] * 20

        if hi == lo:
            # All values coincide with the max, so they fall in the last bin
            counts[19] = n
        else:
            width = (hi - lo) / 20
            for v in standardized:
                if v == hi:
                    counts[19] += 1
                else:
                    idx = int((v - lo) / width)
                    if idx > 19:  # guard against floating-point rounding
                        idx = 19
                    counts[idx] += 1

        result[col] = (standardized, counts)
    return result

def standardize_and_correlate(table):
    """
    Standardize numeric columns of a table (dict of column -> list) and
    compute the Pearson correlation matrix among the numeric columns.

    Returns (standardized, corr):
      - standardized: same columns/order; numeric columns rescaled to
        mean 0 and *population* standard deviation 1; other columns untouched.
      - corr: n x n list of lists of correlations between numeric columns,
        in table order.

    Raises ValueError if the table has no columns/rows or no numeric columns.
    """
    if not table:
        raise ValueError("table is empty")

    n = len(next(iter(table.values())))
    if n == 0:
        raise ValueError("table has no rows")

    # A column is numeric if it's non-empty and every value is a number
    # (excluding booleans, which are ints in Python).
    def is_numeric(col):
        return bool(col) and all(
            isinstance(v, (int, float)) and not isinstance(v, bool) for v in col
        )

    numeric_cols = [name for name, values in table.items()
                    if len(values) == n and is_numeric(values)]
    if not numeric_cols:
        raise ValueError("table has no numeric columns")

    # Standardize each numeric column; remember the z-scores for correlation.
    zscores = {}
    standardized = {}
    for name, values in table.items():
        if name in numeric_cols:
            mean = sum(values) / n
            var = sum((v - mean) ** 2 for v in values) / n  # population variance
            std = var ** 0.5
            if std == 0:
                z = [0.0] * n
            else:
                z = [(v - mean) / std for v in values]
            zscores[name] = z
            standardized[name] = z
        else:
            standardized[name] = list(values)

    # Pearson correlation of standardized columns is just the mean of the
    # elementwise products (equivalently, the dot product / n).
    corr = []
    for col_a in numeric_cols:
        row = []
        za = zscores[col_a]
        for col_b in numeric_cols:
            zb = zscores[col_b]
            # A constant column has undefined correlation; report 0.
            if all(v == 0.0 for v in za) or all(v == 0.0 for v in zb):
                row.append(0.0)
            else:
                row.append(sum(a * b for a, b in zip(za, zb)) / n)
        corr.append(row)

    return standardized, corr

