from html.parser import HTMLParser


class _TableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)  # decode entities for us
        self.rows = []
        self._stack = []  # open elements: ('tr', cells_list) or ('td', buffer_list)

    # --- helpers -------------------------------------------------------
    def _find_open(self, tag):
        for i in range(len(self._stack) - 1, -1, -1):
            if self._stack[i][0] == tag:
                return i
        return -1

    # --- tag handling ---------------------------------------------------
    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            cells = []
            self.rows.append(cells)          # document order = order of <tr>
            self._stack.append(('tr', cells))
        elif tag == 'td':
            self._stack.append(('td', []))
        # everything else (th, table, b, ...) is ignored as a container

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag in ('tr', 'td'):
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if tag in ('tr', 'td'):
            self._close_tag(tag)

    def _close_tag(self, tag):
        i = self._find_open(tag)
        if i == -1:
            return
        # close any unclosed inner elements first
        while len(self._stack) - 1 > i:
            self._finalize(*self._stack.pop())
        self._finalize(*self._stack.pop())

    def _finalize(self, tag, value):
        if tag == 'td':
            text = ''.join(value).strip()
            # attach the cell to the nearest enclosing row
            for j in range(len(self._stack) - 1, -1, -1):
                if self._stack[j][0] == 'tr':
                    self._stack[j][1].append(text)
                    break
        # 'tr' entries are already in self.rows

    def handle_data(self, data):
        # text goes to the nearest enclosing <td>
        for j in range(len(self._stack) - 1, -1, -1):
            if self._stack[j][0] == 'td':
                self._stack[j][1].append(data)
                break

    def close(self):
        super().close()
        while self._stack:                    # tolerate unclosed tags
            self._finalize(*self._stack.pop())


def extract_table_rows(html):
    parser = _TableParser()
    parser.feed(html)
    parser.close()
