from html import unescape


class _TitleParser(HTMLParser):
    """HTML parser that captures the text of the first <title> element."""

    def __init__(self):
        super().__init__()
        self._in_title = False
        self._done = False
        self.title_parts = []

    def handle_starttag(self, tag, attrs):
        if tag == "title" and not self._done:
            self._in_title = True

    def handle_endtag(self, tag):
        if tag == "title" and self._in_title:
            self._in_title = False
            self._done = True

    def handle_data(self, data):
        if self._in_title:
            self.title_parts.append(data)

    @property
    def title(self):
        if self.title_parts:
            return unescape("".join(self.title_parts))
        return None


def extract_title_json(html):
    """
    Extract the first <title> element's text from an HTML string
    and return it as a JSON object: {"title": "..."} or {"title": null}.
    """
    parser = _TitleParser()
    parser.feed(html)
    parser.close()
    return json.dumps({"title": parser.title})

