import json
from collections import defaultdict


def _percentile(sorted_values, q):
    """Linear-interpolation percentile (q in [0, 1]) on pre-sorted data."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])
    pos = q * (n - 1)
    lo = int(pos // 1)
    frac = pos - lo
    if lo + 1 < n:
        return sorted_values[lo] + frac * (sorted_values[lo + 1] - sorted_values[lo])
    return float(sorted_values[lo])


def summarize_values_by_key(json_text):
    # json.JSONDecodeError is a subclass of ValueError, so invalid
    # JSON automatically raises ValueError as required.
    data = json.loads(json_text)

    if not isinstance(data, list):
        raise ValueError("JSON text must encode a list of objects.")

    values_by_key = defaultdict(list)
    for obj in data:
        if not isinstance(obj, dict):
            raise ValueError("Each element must be an object.")
        for key, value in obj.items():
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise ValueError(f"Value for key '{key}' is not a number.")
            values_by_key[key].append(float(value))

    summary = {}
    for key, values in values_by_key.items():
        values.sort()
        summary[key] = {
            'mean': sum(values) / len(values),
            'median': _percentile(values, 0.5),
            'q1': _percentile(values, 0.25),
            'q3': _percentile(values, 0.75),
        }
    return summary
