import math


def most_correlated_columns(data):
    """Return the pair of distinct columns with the largest |Pearson correlation|.

    Args:
        data: dict mapping column names to equal-length lists of numbers.

    Returns:
        A tuple (first, second) of column names, where ``first`` is the
        column that appears earlier in the dict. Ties between pairs are
        broken by dict order (the earliest pair wins).

    Raises:
        ValueError: if there is no data or fewer than two columns.
        TypeError: if any column holds non-numeric values.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dict mapping column names to lists of numbers")
    if not data:
        raise ValueError("no data: data is empty")
    if len(data) < 2:
        raise ValueError("need at least two columns")

    names = []
    deviations = []
    sum_squares = []
    length = None

    for name, values in data.items():
        checked = []
        for value in values:
            if not isinstance(value, (int, float)):
                raise TypeError(
                    f"column {name!r} contains a non-numeric value: {value!r}"
                )
            checked.append(float(value))
        if length is None:
            length = len(checked)
            if length == 0:
                raise ValueError("no data: columns are empty")
        mean = sum(checked) / len(checked) if checked else 0.0
        dev = [v - mean for v in checked]
        names.append(name)
        deviations.append(dev)
        sum_squares.append(sum(d * d for d in dev))

    best = None  # (abs_correlation, i, j)
    for i in range(len(names)):
        if sum_squares[i] == 0.0:
            continue  # constant column: correlation is undefined
        for j in range(i + 1, len(names)):
            if sum_squares[j] == 0.0:
                continue
            cross = sum(x * y for x, y in zip(deviations[i], deviations[j]))
            r = cross / math.sqrt(sum_squares[i] * sum_squares[j])
            score = abs(r)
            if best is None or score > best[0]:
                best = (score, i, j)

    if best is None:
        # No pair has a defined correlation (e.g. all columns constant).
        return (names[0], names[1])
    return (names[best[1]], names[best[2]])

