from fractions import Fraction


def fit_linear_regression(features, values):
    """Fit ordinary least-squares linear regression with an intercept.

    Args:
        features: list of rows, each a list of numbers (one per feature).
        values: list of target values, one per row.

    Returns:
        {'coefficients': [float, ...] in feature-column order,
         'intercept': float}
    """
    n = len(values)
    if n == 0:
        raise ValueError("values must contain at least one row")

    num_features = len(features[0]) if features else 0
    if any(len(row) != num_features for row in features):
        raise ValueError("all feature rows must have the same length")

    p = num_features + 1  # plus intercept

    # Build X^T X and X^T y in exact rational arithmetic, where X has a
    # leading column of ones for the intercept, then solve (X^T X) beta
    # = X^T y exactly via Gaussian elimination. Converting to float only
    # at the end avoids intermediate rounding error.
    xtx = [[Fraction(0)] * p for _ in range(p)]
    xty = [Fraction(0)] * p

    for i in range(n):
        row = [Fraction(1)] + [_to_fraction(v) for v in features[i]]
        y = _to_fraction(values[i])
        for a in range(p):
            ra = row[a]
            xty[a] += ra * y
            for b in range(p):
                xtx[a][b] += ra * row[b]

    beta = _solve(xtx, xty)

    return {
        'coefficients': [float(c) for c in beta[1:]],
        'intercept': float(beta[0]),
    }


def _to_fraction(v):
    if isinstance(v, Fraction):
        return v
    if isinstance(v, int):
        return Fraction(v)
    return Fraction(str(v)) if isinstance(v, str) else Fraction(v)


def _solve(matrix, rhs):
    """Solve matrix @ x = rhs exactly via Gaussian elimination with pivoting."""
    n = len(rhs)
    a = [list(row) for row in matrix]
    b = list(rhs)

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(a[r][col]))
        if a[pivot][col] == 0:
            raise ValueError("singular matrix; features may be collinear")
        if pivot != col:
            a[col], a[pivot] = a[pivot], a[col]
            b[col], b[pivot] = b[pivot], b[col]
        for r in range(col + 1, n):
            factor = a[r][col] / a[col][col]
            if factor:
                for c in range(col, n):
                    a[r][c] -= factor * a[col][c]
                b[r] -= factor * b[col]

    x = [None] * n
    for r in range(n - 1, -1, -1):
        acc = b[r]
        for c in range(r + 1, n):
            acc -= a[r][c] * x[c]
        x[r] = acc / a[r][r]
    return x

