"""Merge multiple CSV documents (with headers) into a single table of dicts."""

import csv
import io
import re

# Matches integers and decimals, optionally signed, with optional exponent.
# Excludes forms like "inf", "nan", or "1_000" that float()/int() would accept.
_NUMBER_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")


def _convert(value):
    """Return the value as a number if it looks like one, else the string."""
    stripped = value.strip()
    if not _NUMBER_RE.match(stripped):
        return value
    body = stripped.lstrip("+-")
    if len(body) > 1 and body[0] == "0" and body[1].isdigit():
        # Integer with a leading zero: treat as an identifier (e.g. "007").
        return value
    try:
        return int(stripped)
    except ValueError:
        return float(stripped)


def merge_csv_texts(csv_texts):
    """Stack the data rows of several CSV texts into one list of dicts.

    Each dict contains every column that appears in any input; a row whose
    source file lacks a column, or whose cell is empty, gets None. Values
    that look like numbers are returned as int/float, others as strings.
    """
    if not csv_texts:
        return []

    columns = []  # union of headers, in first-seen order
    seen = set()

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))
        try:
            header = next(reader)
        except StopIteration:
            continue

        for name in header:
            if name not in seen:
                seen.add(name)
                columns.append(name)

    result = []
    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))
        try:
            header = next(reader)
        except StopIteration:
            continue

        for record in reader:
            if not record:  # skip blank lines
                continue
            row = {name: None for name in columns}
            for i, name in enumerate(header):
                cell = record[i] if i < len(record) else ""
                row[name] = None if cell == "" else _convert(cell)
            result.append(row)

    return result

