import math


def letter_count_correlations(strings):
    if not strings:
        return None

    letters = sorted({ch for s in strings for ch in s})

    counts = {x: [s.count(x) for s in strings] for x in letters}
    n = len(strings)

    def mean(v):
        return sum(v) / n

    def pearson(vx, vy):
        mx, my = mean(vx), mean(vy)
        num = sum((a - mx) * (b - my) for a, b in zip(vx, vy))
        dx = math.sqrt(sum((a - mx) ** 2 for a in vx))
        dy = math.sqrt(sum((b - my) ** 2 for b in vy))
        den = dx * dy
        if den == 0:
            # unreachable when counts vary, per the problem statement
            return 1.0 if vx is vy else 0.0
        return num / den

    result = {}
    for x in letters:
        result[x] = {}
        for y in letters:
            r = pearson(counts[x], counts[y])
            # clamp and round to suppress floating-point noise
            r = max(-1.0, min(1.0, r))
            r = round(r, 12) + 0.0
            result[x][y] = r
    return result

