import csv
import io
import re
from collections import Counter

STOP_WORDS = {"a", "an", "the", "in", "on", "at", "and", "or"}

_WORD_RE = re.compile(r"\w{2,}", re.UNICODE)


def top_word_counts(csv_text):
    """Return the ten most common words in the given single-column CSV text.

    Words are case-insensitive runs of two or more word characters
    (letters, digits, underscore). Stop words are ignored. Results are
    ordered by count descending, then alphabetically.
    """
    counts = Counter()
    if csv_text is None:
        return []
    reader = csv.reader(io.StringIO(csv_text))
    for row in reader:
        for field in row:
            for word in _WORD_RE.findall(field):
                lowered = word.lower()
                if lowered not in STOP_WORDS:
                    counts[lowered] += 1
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:10]

