def five_column_correlation_matrix(array):
    if not array:
        raise ValueError("input must not be empty")

    columns = [[], [], [], [], []]
    for row in array:
        if not isinstance(row, (list, tuple)) or len(row) != 5:
            raise ValueError("each row must have exactly 5 values")
        for i in range(5):
            columns[i].append(row[i])

    n = len(columns[0])

    means = [sum(col) / n for col in columns]
    variances = []
    covariances = [[0.0] * 5 for _ in range(5)]
    for i in range(5):
        var = 0.0
        for k in range(n):
            d = columns[i][k] - means[i]
            var += d * d
            for j in range(i, 5):
                covariances[i][j] += d * (columns[j][k] - means[j])
        variances.append(var)

    result = [[0.0] * 5 for _ in range(5)]
    for i in range(5):
        for j in range(i, 5):
            if i == j:
                value = 1.0
            elif variances[i] == 0 or variances[j] == 0:
                value = 0.0
            else:
                value = covariances[i][j] / (variances[i] * variances[j]) ** 0.5
                if value > 1.0:
                    value = 1.0
                elif value < -1.0:
                    value = -1.0
            result[i][j] = value
            result[j][i] = value

    return result

