from html.parser import HTMLParser

_VOID_ELEMENTS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}


class _FirstTagTextParser(HTMLParser):
    """Collects the text inside the first occurrence of the target tag."""

    def __init__(self, tag):
        super().__init__(convert_charrefs=True)
        self._target = tag.lower()
        self._depth = 0
        self._state = "searching"  # searching -> collecting -> done
        self._parts = []

    def handle_starttag(self, tag, attrs):
        if tag != self._target:
            return
        if self._state == "searching":
            if tag in _VOID_ELEMENTS:
                # A void element has no content and is never closed.
                self._state = "done"
            else:
                self._state = "collecting"
                self._depth = 1
        elif self._state == "collecting":
            self._depth += 1

    def handle_startendtag(self, tag, attrs):
        if self._state == "searching" and tag == self._target:
            self._state = "done"

    def handle_endtag(self, tag):
        if self._state == "collecting" and tag == self._target:
            self._depth -= 1
            if self._depth <= 0:
                self._state = "done"

    def handle_data(self, data):
        if self._state == "collecting":
            self._parts.append(data)

    def result(self):
        text = "".join(self._parts).strip()
        return text if text else None


