def product_profit_report(records):
    """Aggregate sales records by product.

    Each record is a tuple (product, sales, margin); profit for a record is
    sales * margin. Returns a list of (product, total_sales, total_profit)
    tuples sorted by total profit, highest first.
    """
    totals = {}
    for product, sales, margin in records:
        total_sales, total_profit = totals.get(product, (0, 0.0))
        totals[product] = (total_sales + sales, total_profit + sales * margin)
    return sorted(
        ((product, sales, profit) for product, (sales, profit) in totals.items()),
        key=lambda item: item[2],
        reverse=True,
    )

