import json
from statistics import median


def key_mean_median(json_text):
    """Compute mean and median of numeric values per key across JSON records.

    Args:
        json_text: JSON string holding a list of objects (records).

    Returns:
        Dict mapping each key to {'mean': ..., 'median': ...}.
        Keys with no numeric values have both statistics set to None.
    """
    records = json.loads(json_text)
    if not isinstance(records, list):
        raise ValueError("JSON text must hold a list of records")

    values_by_key = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        for key, value in record.items():
            values_by_key.setdefault(key, [])
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                continue
            values_by_key[key].append(value)

    stats = {}
    for key, values in values_by_key.items():
        if not values:
            stats[key] = {'mean': None, 'median': None}
            continue
        stats[key] = {
            'mean': sum(values) / len(values),
            'median': float(median(values)),
        }
    return stats

