def merge_and_standardize(rows1, rows2):
    """Outer-join two tables of dicts on 'id'.

    rows1's feature columns (every key except 'id') are standardized to
    mean 0 and population standard deviation 1, computed over the
    non-missing values; a constant (or all-missing) column becomes 0.
    rows2's columns are left unchanged. The result is sorted by id and
    contains every column of both tables, with None where a value is
    missing.
    """
    cols1 = []
    for row in rows1:
        for key in row:
            if key != 'id' and key not in cols1:
                cols1.append(key)
    cols2 = []
    for row in rows2:
        for key in row:
            if key != 'id' and key not in cols2:
                cols2.append(key)

    # Standardized copies of rows1.
    std_rows1 = []
    for row in rows1:
        std_rows1.append({col: row.get(col) for col in cols1})
    for col in cols1:
        vals = [row[col] for row in std_rows1 if row[col] is not None]
        if vals:
            n = len(vals)
            mean = sum(vals) / n
            std = (sum((v - mean) ** 2 for v in vals) / n) ** 0.5
        else:
            mean, std = 0.0, 0.0
        for row in std_rows1:
            v = row[col]
            if v is None:
                row[col] = None
            elif std == 0:
                row[col] = 0.0
            else:
                row[col] = (v - mean) / std

    index1 = {row['id']: row for row in rows1}
    index2 = {row['id']: row for row in rows2}
    std_by_id = {row['id']: srow for row, srow in zip(rows1, std_rows1)}

    merged = []
    for rid in sorted(set(index1) | set(index2)):
        out = {'id': rid}
        srow = std_by_id.get(rid)
        for col in cols1:
            out[col] = srow[col] if srow is not None and srow.get(col) is not None else None
        r2 = index2.get(rid)
        for col in cols2:
            out[col] = r2[col] if r2 is not None and col in r2 else None
        merged.append(out)
    return merged

