def seasonal_decomposition(values, period, model):
    """Classical seasonal decomposition of a series.

    Args:
        values: sequence of numbers.
        period: seasonal period (positive integer).
        model: 'additive' or 'multiplicative'.

    Returns:
        dict with 'trend', 'seasonal' and 'residual' lists of the same
        length as values, containing None where the component is
        undefined (the ends where the centered moving average is not
        available).
    """
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or period < 1:
        raise ValueError('period must be a positive integer')

    n = len(values)
    if n < 2 * period:
        raise ValueError('series must contain at least two complete periods')

    values = [float(v) for v in values]

    # Centered moving average trend.
    if period % 2 == 1:
        half = (period - 1) // 2
        trend = [None] * n
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        # Even period: average the two moving averages that straddle
        # the center (equivalently a centered window with half weights
        # on the end points).
        trend = [None] * n
        for i in range(period // 2, n - period // 2):
            left = sum(values[i - period // 2:i - period // 2 + period]) / period
            right = sum(values[i - period // 2 + 1:i - period // 2 + 1 + period]) / period
            trend[i] = (left + right) / 2.0

    # Detrended values, grouped by phase within the period.
    detrended = [[] for _ in range(period)]
    for i in range(n):
        if trend[i] is not None:
            if model == 'additive':
                detrended[i % period].append(values[i] - trend[i])
            else:
                detrended[i % period].append(values[i] / trend[i])

    # Raw seasonal index per phase, then normalise to mean 0 / 1.
    seasonal = [None] * n
    if model == 'additive':
        raw = [sum(d) / len(d) for d in detrended]
        mean = sum(raw) / period
        norm = [r - mean for r in raw]
    else:
        raw = [sum(d) / len(d) for d in detrended]
        mean = sum(raw) / period
        norm = [r / mean for r in raw]

    for i in range(n):
        seasonal[i] = norm[i % period]

    # Residuals where the trend is defined.
    residual = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == 'additive':
                residual[i] = values[i] - trend[i] - seasonal[i]
            else:
                residual[i] = values[i] / (trend[i] * seasonal[i])

    return {'trend': trend, 'seasonal': seasonal, 'residual': residual}

