def scale_table_columns(data):
    """Rescale table columns to [0, 1] after dropping incomplete rows.

    Rows containing None in any column are dropped. Each remaining column
    is scaled independently so its minimum is 0.0 and maximum is 1.0;
    a constant column scales to all 0.0. Values keep their original order.
    """
    columns = list(data.keys())
    if not columns:
        return {}

    n = len(next(iter(data.values()))) if data else 0
    keep = [
        i for i in range(n)
        if all(data[c][i] is not None for c in columns)
    ]

    result = {}
    for c in columns:
        vals = [data[c][i] for i in keep]
        lo = min(vals) if vals else 0.0
        hi = max(vals) if vals else 0.0
        span = hi - lo
        if span == 0:
            result[c] = [0.0 for _ in vals]
        else:
            result[c] = [(v - lo) / span for v in vals]
    return result

