import math


def standardize_numeric_columns(data):
    result = {}
    for column, values in data.items():
        converted = []
        is_numeric = True
        for value in values:
            try:
                converted.append(float(value))
            except (TypeError, ValueError):
                is_numeric = False
                break

        if not is_numeric or len(converted) == 0:
            result[column] = values
            continue

        mean = sum(converted) / len(converted)
        variance = sum((v - mean) ** 2 for v in converted) / len(converted)
        std_dev = math.sqrt(variance)

        if std_dev == 0:
            result[column] = [0.0] * len(converted)
        else:
            result[column] = [(v - mean) / std_dev for v in converted]

    return result

