import re
from datetime import date, timedelta

_MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12,
}
_ORDINALS = {'st', 'nd', 'rd', 'th'}


def _month_from_name(name):
    key = name.strip('. ').lower()[:3]
    if key not in _MONTHS:
        raise ValueError('unknown month name: %r' % name)
    return _MONTHS[key]


def _to_int(token):
    token = token.strip()
    if token[-2:].lower() in _ORDINALS and len(token) > 2:
        token = token[:-2]
    return int(token)


def _make_date(year, month, day):
    return date(year, month, day)


def _parse_date(date_str):
    if not isinstance(date_str, (str, bytes)):
        raise ValueError('date must be a string')
    if isinstance(date_str, bytes):
        date_str = date_str.decode('utf-8', 'replace')
    s = date_str.strip()
    if not s:
        raise ValueError('empty date string')

