from datetime import datetime
from zoneinfo import ZoneInfo


def _hour_in_timezone(iso_time, tz):
    dt = datetime.fromisoformat(iso_time)
    if dt.tzinfo is None:
        raise ValueError("published_time must include a UTC offset")
    return dt.astimezone(tz).hour


def publication_hour_stats(articles, timezone):
    """Group articles by category and report stats on their local publication hour.

    Args:
        articles: list of dicts, each with a 'category' and a 'published_time'
            (ISO 8601 string with a UTC offset).
        timezone: IANA timezone name, e.g. 'America/New_York'.

    Returns:
        {category: {'count': int, 'mean': float, 'min': int, 'max': int}}

    Raises:
        ValueError: if articles is empty, an article is missing 'category' or
            'published_time', a published_time lacks a UTC offset, or the
            timezone name is unknown.
    """
    if not articles:
        raise ValueError("articles must be a non-empty list")

    tz = ZoneInfo(timezone)

    hours_by_category = {}
    for article in articles:
        if 'category' not in article:
            raise ValueError("article missing 'category'")
        if 'published_time' not in article:
            raise ValueError("article missing 'published_time'")
        category = article['category']
        hour = _hour_in_timezone(article['published_time'], tz)
        hours_by_category.setdefault(category, []).append(hour)

    stats = {}
    for category in sorted(hours_by_category):
        hours = hours_by_category[category]
        stats[category] = {
            'count': len(hours),
            'mean': sum(hours) / len(hours),
            'min': min(hours),
            'max': max(hours),
        }
    return stats

