import random
from collections import Counter


def _dist2(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


def _kmeanspp_seed(pts, k, rng):
    """k-means++ seeding with a caller-provided (deterministic) RNG."""
    centroids = [rng.choice(pts)]
    while len(centroids) < k:
        weights = []
        for p in pts:
            if p in centroids:
                weights.append(0.0)
            else:
                weights.append(min(_dist2(p, c) for c in centroids))
        total = sum(weights)
        if total <= 0.0:
            # all remaining points coincide with a centroid
            remaining = [p for p in pts if p not in centroids]
            for p in remaining:
                if p not in centroids:
                    centroids.append(p)
                    if len(centroids) == k:
                        break
            break
        r = rng.random() * total
        acc = 0.0
        for p, w in zip(pts, weights):
            acc += w
            if acc >= r and w > 0.0:
                centroids.append(p)
                break
    return centroids


def _lloyds(pts, k, centroids):
    """Run Lloyd's algorithm; return (assignments, inertia)."""
    assignments = None
    for _ in range(300):
        new_assignments = []
        for p in pts:
            best_idx = 0
            best_d = _dist2(p, centroids[0])
            for i in range(1, k):
                d = _dist2(p, centroids[i])
                if d < best_d:
                    best_d = d
                    best_idx = i
            new_assignments.append(best_idx)

        if new_assignments == assignments:
            break
        assignments = new_assignments

        sums = [[0.0, 0.0] for _ in range(k)]
        counts = [0] * k
        for p, a in zip(pts, assignments):
            sums[a][0] += p[0]
            sums[a][1] += p[1]
            counts[a] += 1
        for i in range(k):
            if counts[i] > 0:
                centroids[i] = (sums[i][0] / counts[i], sums[i][1] / counts[i])

    inertia = 0.0
    groups = [[] for _ in range(k)]
    for p, a in zip(pts, assignments):
        groups[a].append(p)
    for group in groups:
        if not group:
            continue
        cx = sum(p[0] for p in group) / len(group)
        cy = sum(p[1] for p in group) / len(group)
        for p in group:
            inertia += (p[0] - cx) ** 2 + (p[1] - cy) ** 2
    return assignments, inertia


def _kmeans(points, n_clusters, n_init=10):
    """Deterministic k-means on 2D points.

    Runs k-means++ seeding plus Lloyd's algorithm several times with
    fixed RNG seeds (deterministic across runs), keeps the result with
    the lowest inertia. Assignment ties go to the lowest centroid index.
    """
    pts = sorted(points)
    n = len(pts)
    k = min(n_clusters, n)
    if k <= 0:
        return []

    best = None
    best_key = None
    for seed in range(n_init):
        rng = random.Random(seed)
        centroids = _kmeanspp_seed(pts, k, rng)
        if len(centroids) < k:
            continue
        assignments, inertia = _lloyds(pts, k, list(centroids))
        clusters = [[] for _ in range(k)]
        for p, a in zip(pts, assignments):
            clusters[a].append(p)
        clusters = sorted(sorted(c) for c in clusters if c)
        key = (inertia, clusters)
        if best_key is None or key < best_key:
            best_key = key
            best = clusters
    if best is None:
        # Degenerate fallback (e.g., every point identical): one cluster.
        best = [sorted(pts)] if pts else []
    return best


def cluster_unique_points(points, n_clusters):
    counts = Counter(points)
    duplicates = {p: c for p, c in counts.items() if c > 1}

    unique_points = list(counts.keys())
    clusters = _kmeans(unique_points, n_clusters)
    return (duplicates, clusters)

