"""Utilities for sorting CSV data."""

import csv
import io


def _to_number(value):
    """Return int or float for a numeric string, or None if not numeric."""
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        return None


def sort_csv_rows(csv_text, sort_by_column='title'):
    """Parse CSV text with a header row and return sorted data rows.

    Rows are returned as a list of dicts mapping column names to values.
    Columns whose values are all numeric are converted to numbers
    (int when possible, otherwise float); other columns stay as strings.
    Rows are sorted in ascending order by ``sort_by_column``.

    :param csv_text: full CSV text including the header row
    :param sort_by_column: name of the column to sort by
    :return: list of row dicts sorted by the given column
    :raises KeyError: if ``sort_by_column`` is not a header column
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader]

    if not rows:
        return []

    header = rows[0]
    data_rows = [row for row in rows[1:] if row]

    # Determine which columns are entirely numeric.
    numeric_columns = set(header)
    for row in data_rows:
        for index, name in enumerate(header):
            if index < len(row) and _to_number(row[index]) is None:
                numeric_columns.discard(name)

    # Build row dicts, converting numeric columns to numbers.
    parsed_rows = []
    for row in data_rows:
        record = {}
        for index, name in enumerate(header):
            value = row[index] if index < len(row) else ''
            if name in numeric_columns:
                value = _to_number(value)
            record[name] = value
        parsed_rows.append(record)

    if sort_by_column not in header:
        raise KeyError('Unknown sort column: {!r}'.format(sort_by_column))

    parsed_rows.sort(key=lambda record: record[sort_by_column])
    return parsed_rows

