def format_sorted_dict_table(my_dict):
    """Return a plain-text table of the dict's items, sorted by key ascending.

    Classic ASCII grid style: '+', '-' and '|' borders, a rule above and
    below the header and at the bottom, centered cells, one space of
    padding on each side.
    """
    headers = ('Key', 'Value')
    rows = [(str(key), str(value)) for key, value in sorted(my_dict.items())]

    def width(index):
        return max([headers[index]] + [row[index] for row in rows], key=len).__len__()

    key_w = width(0)
    val_w = width(1)

    def cell(text, w):
        pad = w - len(text)
        left = pad // 2
        right = pad - left
        return ' ' * (left + 1) + text + ' ' * (right + 1)

    def row_line(key_text, value_text):
        return '|' + cell(key_text, key_w) + '|' + cell(value_text, val_w) + '|'

    def rule():
        return '+' + '-' * (key_w + 2) + '+' + '-' * (val_w + 2) + '+'

    lines = [
        rule(),
        row_line(*headers),
        rule(),
    ]
    lines.extend(row_line(*row) for row in rows)
    lines.append(rule())
    return '\n'.join(lines)

