"""Compute the DFT of values from (label, value) pairs and a magnitude histogram."""

import math


def spectrum_magnitude_histogram(pairs):
    """Return (magnitudes, histogram_counts) for the values in ``pairs``.

    Magnitudes are the absolute values of the discrete Fourier transform
    coefficients, in order. Histogram counts use 10 equal-width bins spanning
    [min magnitude, max magnitude]; bins are left-closed and right-open except
    the last, which includes its right edge. Empty input yields ([], []).
    """
    values = [float(value) for _, value in pairs]
    if not values:
        return ([], [])

    n = len(values)
    magnitudes = []
    for k in range(n):
        re = 0.0
        im = 0.0
        for j, x in enumerate(values):
            angle = -2.0 * math.pi * ((j * k) % n) / n
            re += x * math.cos(angle)
            im += x * math.sin(angle)
        magnitudes.append(math.hypot(re, im))

    lo = min(magnitudes)
    hi = max(magnitudes)
    width = (hi - lo) / 10.0
    counts = [0] * 10
    if width == 0.0:
        counts[9] = len(magnitudes)
    else:
        for m in magnitudes:
            if m >= hi:
                counts[9] += 1
            else:
                idx = int((m - lo) / width)
                if idx > 9:
                    idx = 9
                counts[idx] += 1

    return (magnitudes, counts)

