import math


def normalized_cumulative_sums(data):
    """Return min-max scaled cumulative sums for each column in `data`.

    `data` maps column names to equal-length lists of numbers. Each column's
    running cumulative sum is scaled to [0, 1]; a constant cumulative sum
    yields all zeros.

    Raises:
        TypeError: if any column contains non-numeric values.
        ValueError: if `data` is empty or contains NaN.
    """
    if not data:
        raise ValueError("data is empty")

    result = {}
    for column, values in data.items():
        if not isinstance(values, (list, tuple)):
            raise TypeError(f"column {column!r} is not a list of numbers")

        for value in values:
            if not isinstance(value, (int, float)):
                raise TypeError(f"column {column!r} contains a non-numeric value")
            if isinstance(value, float) and math.isnan(value):
                raise ValueError(f"column {column!r} contains NaN")

        cumsum = []
        total = 0
        for value in values:
            total += value
            cumsum.append(float(total))

        if not cumsum:
            result[column] = []
            continue

        lo = min(cumsum)
        hi = max(cumsum)
        if hi == lo:
            result[column] = [0.0] * len(cumsum)
        else:
            span = hi - lo
            result[column] = [(s - lo) / span for s in cumsum]

    return result

