import math


def standardize_by_group(records):
    """Standardize 'age' and 'income' to z-scores within each 'id' group.

    Uses the group's mean and population standard deviation. Values that are
    constant within a group become 0. Returns a list of dicts with keys
    'id', 'age', 'income' in input order. Raises ValueError if any record
    lacks one of the three keys.
    """
    required = ('id', 'age', 'income')
    for record in records:
        for key in required:
            if key not in record:
                raise ValueError(f"record missing required key: {key}")

    groups = {}
    for index, record in enumerate(records):
        groups.setdefault(record['id'], []).append(index)

    result = [{'id': record['id'], 'age': 0.0, 'income': 0.0} for record in records]
    for indices in groups.values():
        for key in ('age', 'income'):
            values = [float(records[i][key]) for i in indices]
            mean = sum(values) / len(values)
            variance = sum((v - mean) ** 2 for v in values) / len(values)
            std = math.sqrt(variance)
            for i, v in zip(indices, values):
                result[i][key] = 0.0 if std == 0.0 else (v - mean) / std
    return result

