def cumulative_column_sums(data):
    """Return running (cumulative) sums down each numeric column of a table.

    The table is a dict mapping column names to equal-length lists. A column
    is numeric only if every value in it is an int or float (bool excluded).
    Non-numeric columns are ignored, and the original column order is kept.

    Raises ValueError if the table has no rows or no numeric columns.
    """
    if not data:
        raise ValueError("table has no numeric columns")

    n_rows = len(next(iter(data.values())))
    if n_rows == 0:
        raise ValueError("table has no rows")

    result = {}
    for name, values in data.items():
        if not all(isinstance(v, (int, float)) and not isinstance(v, bool)
                   for v in values):
            continue
        running = 0
        sums = []
        for v in values:
            running += v
            sums.append(running)
        result[name] = sums

    if not result:
        raise ValueError("table has no numeric columns")
    return result

