"""Parse an XML string into nested dicts.

Rules:
- The result is ``{root_tag: value}``.
- An element with no attributes and no child elements becomes its text as a
  string (surrounding whitespace trimmed), or ``None`` if it has no text.
- Any other element becomes a dict: attributes become keys prefixed with
  ``@``, child elements are keyed by their tag, and any text becomes the
  value of the ``#text`` key.
- A tag that occurs more than once among siblings maps to a list of the
  values in document order.
- A ``ValueError`` is raised if the XML is malformed.
"""

import xml.etree.ElementTree as ET


def _text_of(elem, children):
    """Return the element's text content in document order, or None."""
    raw = elem.text or ""
    for child in children:
        raw += child.tail or ""
    text = raw.strip()
    return text if text else None


def _convert(elem):
    children = list(elem)

    if not children and not elem.attrib:
        return elem.text.strip() if elem.text is not None else None

    result = {}
    for name, value in elem.attrib.items():
        result["@" + name] = value

    counts = {}
    for child in children:
        counts[child.tag] = counts.get(child.tag, 0) + 1

    for child in children:
        value = _convert(child)
        if counts[child.tag] > 1:
            result.setdefault(child.tag, []).append(value)
        else:
            result[child.tag] = value

    text = _text_of(elem, children)
    if text is not None:
        result["#text"] = text

    return result


def xml_to_dict(xml):
    """Parse an XML string into nested Python dicts."""
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError("Malformed XML: {}".format(exc)) from exc
    except ValueError:
        # ET raises ValueError itself for some invalid inputs (e.g. bytes
        # with an encoding declaration in some versions); let it propagate.
        raise
    return {root.tag: _convert(root)}

