import math


def standardize_columns(rows, columns, features):
    """Rescale the given feature columns to zero mean and unit variance.

    Uses the population standard deviation. A constant feature column is
    mapped to all zeros. Non-feature columns keep their values (as floats).
    """
    rows = [list(row) for row in rows]
    if not rows:
        return []

    n = len(rows)
    col_index = {name: i for i, name in enumerate(columns)}

    for feature in features:
        j = col_index[feature]
        values = [row[j] for row in rows]
        mean = sum(values) / n
        variance = sum((v - mean) ** 2 for v in values) / n
        std = math.sqrt(variance)
        if std == 0:
            for row in rows:
                row[j] = 0.0
        else:
            for row in rows:
                row[j] = (row[j] - mean) / std

    return [[float(v) for v in row] for row in rows]

