def interquartile_range_nested(L):
    """Return the IQR (Q3 - Q1) of all numbers in a list of lists.

    Quartiles use linear interpolation between closest ranks
    (position (n-1) * p, like numpy's default percentile method).
    """
    values = sorted(float(x) for row in L for x in row)
    n = len(values)
    if n == 0:
        raise ValueError("IQR is undefined for an empty dataset")

    def quantile(p):
        pos = (n - 1) * p
        lo = int(pos)
        hi = min(lo + 1, n - 1)
        frac = pos - lo
        return values[lo] + frac * (values[hi] - values[lo])

    return quantile(0.75) - quantile(0.25)

