"""Total sales per calendar day, covering the full date range with zero-filled gaps."""

from datetime import date, datetime, timedelta


def daily_sales_totals(dates, sales):
    """Return a list of (day, total) tuples, one per day from the earliest
    to the latest date, in chronological order. Days with no sales have a
    total of 0. Raises ValueError if there are no records.

    Each element of `dates` is an ISO date ('YYYY-MM-DD') or ISO datetime
    string ('YYYY-MM-DDTHH:MM:SS[.ffffff][+HH:MM|Z]'); only the calendar
    date portion contributes to the grouping.
    """
    if not dates:
        raise ValueError("no records provided")

    if len(dates) != len(sales):
        raise ValueError("dates and sales must have the same length")

    def to_date(value):
        if isinstance(value, datetime):
            return value.date()
        if isinstance(value, date):
            return value
        text = value.strip()
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        return datetime.fromisoformat(text).date()

    totals = {}
    for raw_date, amount in zip(dates, sales):
        day = to_date(raw_date)
        totals[day] = totals.get(day, 0) + amount

    start = min(totals)
    end = max(totals)

    result = []
    day = start
    while day <= end:
        result.append((day.isoformat(), totals.get(day, 0)))
        day += timedelta(days=1)
    return result

