def scale_by_group_with_histogram(ids, ages, incomes):
    n = len(ids)
    if n == 0:
        raise ValueError("no rows")
    if len(ages) != n or len(incomes) != n:
        raise ValueError("ids, ages and incomes must have equal length")

    groups = {}
    for i, key in enumerate(ids):
        groups.setdefault(key, []).append(i)

    scaled = [None] * n
    for indices in groups.values():
        for values, column in ((ages, 0), (incomes, 1)):
            lo = min(values[i] for i in indices)
            hi = max(values[i] for i in indices)
            if hi == lo:
                for i in indices:
                    if scaled[i] is None:
                        scaled[i] = [0.0, 0.0]
                    scaled[i][column] = 0.0
            else:
                scale = 1.0 / (hi - lo)
                offset = lo * scale
                for i in indices:
                    if scaled[i] is None:
                        scaled[i] = [0.0, 0.0]
                    scaled[i][column] = values[i] * scale - offset

    counts = [0] * 10
    for pair in scaled:
        v = pair[1]
        b = int(v * 10)
        if b < 0:
            b = 0
        elif b > 9:
            b = 9
        counts[b] += 1

    return scaled, counts

