import csv
import io


def _is_float(text):
    try:
        float(text)
        return True
    except ValueError:
        return False


def fill_missing_with_column_mean(csv_text):
    """Parse CSV text into a dict mapping column name -> list of values.

    Numeric columns (every present value parses as a float) yield floats,
    with empty cells replaced by the mean of that column's present values.
    Other columns yield strings, with empty cells replaced by None.
    A column with no present values at all becomes a list of None values.
    Empty input gives an empty dict.
    """
    if not csv_text:
        return {}

    rows = [row for row in csv.reader(io.StringIO(csv_text)) if row]
    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    data = [(row + [""] * len(header))[:len(header)] for row in rows[1:]]

    columns = {}
    for col_idx, name in enumerate(header):
        cells = [row[col_idx].strip() for row in data]
        present = [c for c in cells if c != ""]

        if present and all(_is_float(c) for c in present):
            nums = [float(c) for c in present]
            mean = sum(nums) / len(nums)
            columns[name] = [float(c) if c != "" else mean for c in cells]
        else:
            columns[name] = [c if c != "" else None for c in cells]

    return columns

