"""Preprocess a table: value replacement, integer encoding, standardization."""


def encode_and_standardize(data, replacements):
    """Preprocess a table given as a dict mapping column names to lists.

    Steps:
      1. Replace any value that is a key of ``replacements`` with its mapped value.
      2. Turn every column containing strings into integer codes 0..k-1,
         numbering the distinct string values in sorted order.
      3. Standardize every column: subtract the mean, divide by the sample
         standard deviation (ddof=1).

    Returns a dict mapping each column name to its list of standardized
    floats, with columns in the original order.

    Raises ValueError if ``data`` is not a dict.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")

    result = {}

    for name, column in data.items():
        # Step 1: value replacement.
        values = []
        for v in column:
            try:
                if v in replacements:
                    v = replacements[v]
            except TypeError:
                # Unhashable value can never be a replacement key.
                pass
            values.append(v)

        # Step 2: integer-encode columns containing strings.
        if any(isinstance(v, str) for v in values):
            distinct = sorted({v for v in values if isinstance(v, str)})
            codes = {v: i for i, v in enumerate(distinct)}
            values = [codes[v] if isinstance(v, str) else v for v in values]

        # Step 3: standardize (sample standard deviation, ddof=1).
        n = len(values)
        if n == 0:
            result[name] = []
            continue

        mean = sum(values) / n
        if n > 1:
            ssq = sum((v - mean) ** 2 for v in values)
            std = (ssq / (n - 1)) ** 0.5
        else:
            std = 0.0

        if std == 0:
            result[name] = [0.0 for _ in values]
        else:
            result[name] = [(v - mean) / std for v in values]

    return result

