def summarize_stock_column(column, data):
    column_indices = {'Open': 1, 'High': 2, 'Low': 3, 'Close': 4, 'Volume': 5}
    if column not in column_indices:
        raise ValueError("column must be one of 'Open', 'High', 'Low', 'Close' or 'Volume'")
    idx = column_indices[column]

    values = []
    for row in data:
        if not isinstance(row, list) or len(row) != 6:
            raise ValueError('each row must have exactly six entries')
        value = row[idx]
        if value is not None:
            values.append(float(value))

    count = len(values)
    if count == 0:
        return {'count': 0, 'mean': None, 'std': None, 'min': None,
                '25%': None, '50%': None, '75%': None, 'max': None}

    values.sort()

    def quantile(sorted_vals, q):
        pos = (len(sorted_vals) - 1) * q
        lower = int(pos)
        upper = min(lower + 1, len(sorted_vals) - 1)
        frac = pos - lower
        return sorted_vals[lower] * (1 - frac) + sorted_vals[upper] * frac

    mean = sum(values) / count
    if count > 1:
        var = sum((v - mean) ** 2 for v in values) / (count - 1)
        std = var ** 0.5
    else:
        std = float('nan')

    return {
        'count': count,
        'mean': mean,
        'std': std,
        'min': values[0],
        '25%': quantile(values, 0.25),
        '50%': quantile(values, 0.5),
        '75%': quantile(values, 0.75),
        'max': values[-1],
    }

