import math


def summarize_xyz(records):
    if not isinstance(records, list) or not all(isinstance(r, dict) for r in records):
        raise ValueError("input must be a list of dicts")

    keys = ("x", "y", "z")
    result = {}
    for key in keys:
        if not any(key in record for record in records):
            result[key] = None
            continue

        values = [record.get(key, 0) for record in records]
        total = sum(values)
        n = len(values)
        mean = total / n
        variance = sum((v - mean) ** 2 for v in values) / n
        result[key] = {
            "mean": mean,
            "sum": total,
            "max": max(values),
            "min": min(values),
            "std": math.sqrt(variance),
        }
    return result

