import math


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _pearson(nx, sx, sxx, ny, sy, syy, sxy):
    num = nx * sxy - sx * sy
    den = math.sqrt(nx * sxx - sx * sx) * math.sqrt(ny * syy - sy * sy)
    if den == 0:
        return 0.0
    return num / den


def correlation_without_column(data, column):
    numeric = {}
    for name, values in data.items():
        if name == column:
            continue
        if all(_is_number(v) for v in values):
            numeric[name] = [float(v) for v in values]
    if not numeric:
        return None
    stats = {}
    for name, values in numeric.items():
        stats[name] = (
            len(values),
            sum(values),
            sum(v * v for v in values),
        )
    names = list(numeric)
    result = {}
    for x in names:
        nx, sx, sxx = stats[x]
        row = {}
        for y in names:
            if y == x:
                row[y] = 1.0
            else:
                ny, sy, syy = stats[y]
                sxy = sum(a * b for a, b in zip(numeric[x], numeric[y]))
                row[y] = _pearson(nx, sx, sxx, ny, sy, syy, sxy)
        result[x] = row
    return result

