import math


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _is_numeric_column(values):
    if not isinstance(values, (list, tuple)) or len(values) == 0:
        return False
    return all(_is_number(v) for v in values)


def _histogram(values):
    mn = min(values)
    mx = max(values)
    counts = [0] * 10
    width = mx - mn
    if width == 0:
        counts[0] = len(values)
        return counts
    for v in values:
        idx = int((v - mn) * 10 / width)
        if idx < 0:
            idx = 0
        elif idx > 9:
            idx = 9
        counts[idx] += 1
    return counts


def column_histograms(table):
    if not isinstance(table, dict) or len(table) == 0:
        raise ValueError("table must be a non-empty dict")

    result = {}
    for name, values in table.items():
        if _is_numeric_column(values):
            result[name] = _histogram(list(values))

    if not result:
        raise ValueError("table has no numeric columns")
    return result

