def zscores_by_date(rows):
    """Compute population z-scores per value position across all rows.

    rows: list of [date, values] pairs, where date is a 'YYYY-MM-DD' string
    and values is a list of numbers (same length in every row).

    Returns a list of [date, z1, z2, ...] entries in input order.
    """
    n_rows = len(rows)
    if n_rows == 0:
        return []

    n_cols = len(rows[0][1])
    sums = [0.0] * n_cols
    for _, values in rows:
        for j, v in enumerate(values):
            sums[j] += v
    means = [s / n_rows for s in sums]

    sqdevs = [0.0] * n_cols
    for _, values in rows:
        for j, v in enumerate(values):
            d = v - means[j]
            sqdevs[j] += d * d
    stds = [(sq / n_rows) ** 0.5 for sq in sqdevs]

    result = []
    for date, values in rows:
        out = [date]
        for j, v in enumerate(values):
            if stds[j] == 0.0:
                out.append(0.0)
            else:
                out.append((v - means[j]) / stds[j])
        result.append(out)
    return result

