import math


def replace_and_standardize(data, features, mapping):
    # Validate feature columns before any work.
    for col in features:
        if col not in data:
            raise ValueError(f"Column '{col}' is missing from data")

    result = {}
    for col, values in data.items():
        result[col] = [mapping[v] if v in mapping else v for v in values]

    for col in features:
        col_values = result[col]
        n = len(col_values)
        mean = sum(col_values) / n
        variance = sum((v - mean) ** 2 for v in col_values) / n
        std = math.sqrt(variance)
        if std == 0:
            result[col] = [0.0] * n
        else:
            result[col] = [(v - mean) / std for v in col_values]

    return result

