def summarize_distribution(values, bins):
    if not values:
        raise ValueError("values must be a non-empty list")
    if not isinstance(bins, int) or bins <= 0:
        raise ValueError("bins must be a positive integer")

    n = len(values)
    mean = sum(values) / n
    std_dev = (sum((v - mean) ** 2 for v in values) / n) ** 0.5

    sorted_vals = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        median = float(sorted_vals[mid])
    else:
        median = (sorted_vals[mid - 1] + sorted_vals[mid]) / 2

    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    # dicts preserve insertion order, so max returns the tied value seen first
    mode = max(counts, key=counts.get)

    lo = min(values)
    hi = max(values)
    histogram = [0] * bins
    if hi == lo:
        histogram[bins - 1] = n
    else:
        width = (hi - lo) / bins
        for v in values:
            idx = int((v - lo) / width)
            if idx >= bins:
                idx = bins - 1
            histogram[idx] += 1

    return {
        "mean": mean,
        "median": median,
        "mode": mode,
        "std_dev": std_dev,
        "histogram": histogram,
    }

