"""Boxplot statistics for a comma-separated number string found at a key path in JSON."""

import json


def _percentile(sorted_values, fraction):
    """Linear interpolation between data points (numpy 'linear' method)."""
    if len(sorted_values) == 1:
        return float(sorted_values[0])
    position = fraction * (len(sorted_values) - 1)
    lower = int(position)
    upper = min(lower + 1, len(sorted_values) - 1)
    weight = position - lower
    return sorted_values[lower] * (1.0 - weight) + sorted_values[upper] * weight


def boxplot_stats_at_path(json_data, key_path):
    try:
        data = json.loads(json_data)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("malformed JSON") from exc

    current = data
    for key in key_path:
        if not isinstance(current, dict):
            raise KeyError(repr(key))
        try:
            current = current[key]
        except KeyError:
            raise KeyError(repr(key)) from None

    if not isinstance(current, str):
        raise ValueError("value at key path is not a data string")

    text = current.strip()
    if not text:
        raise ValueError("data string is empty")

    values = []
    for token in text.split(","):
        token = token.strip()
        if not token:
            raise ValueError("data string contains an empty value")
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError("data string contains a non-numeric value") from None

    if not values:
        raise ValueError("data string is empty")

    ordered = sorted(values)
    q1 = _percentile(ordered, 0.25)
    median = _percentile(ordered, 0.5)
    q3 = _percentile(ordered, 0.75)

    iqr = q3 - q1
    low_fence = q1 - 1.5 * iqr
    high_fence = q3 + 1.5 * iqr

    in_range = [v for v in ordered if low_fence <= v <= high_fence]
    outliers = [v for v in ordered if v < low_fence or v > high_fence]

    return {
        "q1": q1,
        "median": median,
        "q3": q3,
        "whisker_low": float(min(in_range)) if in_range else None,
        "whisker_high": float(max(in_range)) if in_range else None,
        "outliers": outliers,
    }

