"""Count how many dates in a list fall on each day of the week.

Supports common date string formats such as:
    2022-10-22, 2022/10/22, 10-22-2022, 10/22/2022, 22.10.2022
    Oct 22, 2022, October 22, 2022, 22 Oct 2022, 22 October 2022
    2022 Oct 22, 22 Oct 2022 10:30 (times are ignored)

Ambiguous numeric orders (e.g. 10/22/2022 vs 22/10/2022) are resolved
by preferring an interpretation where day and month are both valid,
favoring month/day/year when both readings are valid.
"""

import re
from datetime import date

WEEKDAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday',
            'Friday', 'Saturday', 'Sunday']

_MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12,
}
_ORDINALS = {
    '1st': 1, '2nd': 2, '3rd': 3, '4th': 4, '5th': 5, '6th': 6, '7th': 7,
    '8th': 8, '9th': 9, '10th': 10, '11th': 11, '12th': 12, '13th': 13,
    '14th': 14, '15th': 15, '16th': 16, '17th': 17, '18th': 18,
    '19th': 19, '20th': 20, '21st': 21, '22nd': 22, '23rd': 23,
    '24th': 24, '25th': 25, '26th': 26, '27th': 27, '28th': 28,
    '29th': 29, '30th': 30, '31st': 31,
}


def _valid_year(y):
    return 1 <= y <= 9999


def _valid_month(m):
    return 1 <= m <= 12


def _valid_day(y, m, d):
    try:
        date(y, m, d)
        return True
    except ValueError:
        return False


def _month_from_name(name):
    return _MONTHS.get(name[:3].lower())


def _full_year(y):
    if y < 100:
        # Two-digit years: 00-68 -> 2000-2068, 69-99 -> 1969-1999
        return 2000 + y if y <= 68 else 1900 + y
    return y


def _try_numeric(order, a, b, c):
    """Try to build a date from three numbers given a field order."""
    try:
        a, b, c = int(a), int(b), int(c)
    except (TypeError, ValueError):
        return None
    orders = {
        'ymd': (a, b, c),
        'dmy': (c, b, a),
        'mdy': (c, a, b),
    }
    candidates = []
    for order_name, (yy, mm, dd) in orders.items():
        y = _full_year(yy)
        if _valid_year(y) and _valid_month(mm) and _valid_day(y, mm, dd):
            candidates.append((order_name, date(y, mm, dd)))
    if not candidates:
        return None
    if order is not None:
        for order_name, d in candidates:
            if order_name == order:
                return d
        return None
    # Prefer ymd, then dmy, then mdy among the valid readings.
    for preferred in ('ymd', 'dmy', 'mdy'):
        for order_name, d in candidates:
            if order_name == preferred:
                return d
    return candidates[0][1]


def _parse_token_date(tokens):
    """Parse dates that mix month names with numbers."""
    # Find a month name token.
    month = None
    rest = []
    for tok in tokens:
        m = _month_from_name(tok) if tok.isalpha() else None
        if m and month is None:
            month = m
        else:
            rest.append(tok)
    if month is None or len(rest) < 2:
        return None

    # Locate a 4-digit (or likely) year among the remaining tokens.
    year = None
    day = None
    numbers = []
    for tok in rest:
        tok_clean = tok.strip(',')
        if tok_clean in _ORDINALS and day is None:
            day = _ORDINALS[tok_clean]
            continue
        try:
            n = int(tok_clean)
        except ValueError:
            return None
        numbers.append(n)

    # Heuristic: a number >= 1000 is the year; otherwise the larger
    # of the remaining numbers is treated as the year if there are two,
    # or the single number is the day with a missing year (unsupported).
    for n in numbers:
        if n >= 1000:
            year = n
            numbers.remove(n)
            break
    if year is None and len(numbers) == 2:
        # e.g. "22 Oct 22" -> day 22, year 22; larger/last is ambiguous,
        # assume the second number is the year.
        day, year = numbers[0], _full_year(numbers[1])
        numbers = []
    if year is None or day is None:
        if len(numbers) == 1:
            day = numbers[0]
        else:
            return None
    if year is None:
        return None
    year = _full_year(year)
    if not (_valid_year(year) and _valid_day(year, month, day)):
        return None
    return date(year, month, day)


def _parse_date_string(s):
    """Parse a single date string, returning a date or None."""
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s:
        return None

    # Strip a trailing/leading weekday name if present (e.g. "Sat, Oct 22, 2022").
    prefix_re = re.compile(r'^(?:' + '|'.join(WEEKDAYS) +
                           r'|Mon|Tue|Tues|Wed|Thu|Thur|Thurs|Fri|Sat|Sun)\b[,.]?\s*',
                           re.IGNORECASE)
    s2 = prefix_re.sub('', s, count=1)
    if _parse_core(s2) is not None:
        s = s2

    # Drop a trailing time component (e.g. "Oct 22, 2022 10:30" or "...T14:00").
    s = re.sub(r'\s+\d{1,2}:\d{2}(:\d{2})?(\s*(?:AM|PM|am|pm))?$', '', s)
    s = re.sub(r'[T ]\d{1,2}:\d{2}(:\d{2})?(\.\d+)?(Z|[+-]\d{2}:?\d{2})?$', '', s,
               flags=re.IGNORECASE)
    return _parse_core(s)


def _parse_core(s):
    s = s.strip().rstrip(',').strip()
    if not s:
        return None

    # Compact ISO form: 20221022
    if re.fullmatch(r'\d{8}', s):
        return _try_numeric('ymd', s[:4], s[4:6], s[6:])

    # Purely numeric with separators: 2022-10-22, 10/22/2022, 22.10.2022
    m = re.fullmatch(r'(\d{1,4})[-/.](\d{1,2})[-/.](\d{1,4})', s)
    if m:
        a, b, c = m.group(1), m.group(2), m.group(3)
        order = 'ymd' if len(a) == 4 else None
        return _try_numeric(order, a, b, c)

    # Numeric with spaces: "22 10 2022" (rare) — treat like separators.
    m = re.fullmatch(r'(\d{1,4})\s+(\d{1,2})\s+(\d{1,4})', s)
    if m:
