        a, b, c = m.group(1), m.group(2), m.group(3)
        order = 'ymd' if len(a) == 4 else None
        return _try_numeric(order, a, b, c)

    # Numeric with spaces: "22 10 2022" (rare) — treat like separators.
    m = re.fullmatch(r'(\d{1,4})\s+(\d{1,2})\s+(\d{1,4})', s)
    if m:
        return _try_numeric(None, m.group(1), m.group(2), m.group(3))

    # Token-based parsing for month-name formats.
    tokens = re.findall(r'[A-Za-z]+|\d+', s.replace(',', ' , '))
    has_alpha = any(t.isalpha() and t != ',' for t in tokens)
    if has_alpha:
        return _parse_token_date([t for t in tokens if t != ','])

    return None


def weekday_distribution(date_strings):
    """Count the weekdays on which the given date strings fall.

    Returns a dict with keys 'Monday' .. 'Sunday' (in that order) and
    integer counts; unparseable entries are skipped.
    """
    counts = {name: 0 for name in WEEKDAYS}
    for s in date_strings or []:
        d = _parse_date_string(s)
        if d is not None:
            counts[WEEKDAYS[d.weekday()]] += 1
    return counts

