import xml.etree.ElementTree as ET


def _convert(elem):
    """Convert an Element to its value: a string, None, or a dict."""
    children = list(elem)
    text = elem.text

    if children:
        # Ignore whitespace-only text surrounding child elements.
        if text is None or not text.strip():
            text = None
    else:
        # An element without children: whitespace-only counts as empty.
        if text is None or not text.strip():
            text = None

    if not children and not elem.attrib:
        # Only text (possibly None) and no attributes.
        return text

    result = {'@' + name: value for name, value in elem.attrib.items()}
    if text is not None:
        result['#text'] = text

    for child in children:
        value = _convert(child)
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if not isinstance(existing, list):
                result[tag] = [existing]
            result[tag].append(value)
        else:
            result[tag] = value
    return result


def xml_to_dict(s):
    """Parse XML string ``s`` and return a dict mapping the root tag to content.

    - An element with only text becomes that text string.
    - An empty element becomes None.
    - Otherwise: attributes under '@name', children under their tags, and
      text under '#text'.
    - Repeated sibling tags become a list of values in document order.

    Raises ValueError if ``s`` is empty or whitespace-only (or unparseable).
    """
    if s is None or not str(s).strip():
        raise ValueError('Input XML string is empty or whitespace-only')
    try:
        root = ET.fromstring(s)
    except ET.ParseError as exc:
        raise ValueError(f'Invalid XML: {exc}') from None
    return {root.tag: _convert(root)}

