import math


def dbscan_cluster_labels(points):
    """Cluster points with DBSCAN (Euclidean distance, eps=3, min_samples=2).

    Returns a list of integer labels, one per input point in order.
    Clusters are numbered 0, 1, 2, ... in the order they are first found
    while scanning points in input order; noise points get -1.
    """
    n = len(points)
    eps = 3.0
    min_samples = 2

    def dist(a, b):
        return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

    # Neighbours of i, including i itself (self counts toward min_samples).
    neighbors = []
    for i in range(n):
        nbrs = []
        for j in range(n):
            if dist(points[i], points[j]) <= eps:
                nbrs.append(j)
        neighbors.append(nbrs)

    labels = [None] * n  # None = unvisited, -1 = noise, >=0 = cluster id
    cluster_id = 0

    for i in range(n):
        if labels[i] is not None:
            continue
        nbrs = neighbors[i]
        if len(nbrs) < min_samples:
            labels[i] = -1  # noise (may later become a border point)
            continue

        # Start a new cluster at point i.
        labels[i] = cluster_id
        seeds = [j for j in nbrs if j != i]
        k = 0
        while k < len(seeds):
            j = seeds[k]
            k += 1
            if labels[j] == -1:
                # Previously marked noise: it is a border point of this cluster.
                labels[j] = cluster_id
            if labels[j] is not None:
                continue
            labels[j] = cluster_id
            j_nbrs = neighbors[j]
            if len(j_nbrs) >= min_samples:
                # j is a core point; merge its neighbourhood into the seed set.
                for q in j_nbrs:
                    if labels[q] is None and q not in seeds:
                        seeds.append(q)

        cluster_id += 1

    return labels

