import re


def tokenize_text(text):
    # Decimal numbers (e.g. 3.14), then words/numbers whose segments are
    # joined by hyphens or apostrophes (e.g. high-level, don't, x2).
    _token_re = re.compile(
        r"\d+(?:\.\d+)?"
        r"|[A-Za-z0-9]+(?:[-'][A-Za-z0-9]+)*"
    )

    tokens = []
    for line in text.splitlines():
        pos = 0
        for match in _token_re.finditer(line):
            start, end = match.span()
            # Any non-whitespace characters before the next token are
            # punctuation; each mark becomes its own token.
            for ch in line[pos:start]:
                if not ch.isspace():
                    tokens.append(ch)
            tokens.append(match.group())
            pos = end
        for ch in line[pos:]:
            if not ch.isspace():
                tokens.append(ch)
    return tokens

