import csv
import io


def _try_number(value):
    try:
        return int(value)
    except (ValueError, TypeError):
        pass
    try:
        return float(value)
    except (ValueError, TypeError):
        return None


def concat_csv_tables(csv_texts):
    """Concatenate the data rows of multiple CSV documents.

    Args:
        csv_texts: a list of CSV document strings, each with a header row,
            all sharing the same columns.

    Returns:
        A list of dicts mapping column name to value, one per data row,
        in document order. Columns whose values are all numeric come back
        as numbers (int or float); other columns as strings.

    Raises:
        ValueError: if csv_texts is empty.
    """
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    rows = []
    for text in csv_texts:
        if not isinstance(text, str):
            raise ValueError("each CSV document must be a string")
        reader = csv.DictReader(io.StringIO(text))
        for row in reader:
            rows.append({k: v for k, v in row.items() if k is not None})

    numeric_columns = set()
    if rows:
        candidate_columns = set(rows[0].keys())
        for row in rows[1:]:
            candidate_columns.intersection_update(row.keys())
        for column in candidate_columns:
            if all(_try_number(row[column]) is not None for row in rows):
                numeric_columns.add(column)

    return [
        {
            column: _try_number(value) if column in numeric_columns else value
            for column, value in row.items()
        }
        for row in rows
    ]

