import csv
import io
import math


def column_summary_stats(csv_text, column_name):
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        raise ValueError("CSV has no header row")

    header = rows[0]
    try:
        col_index = header.index(column_name)
    except ValueError:
        raise ValueError("Column not found in header: {!r}".format(column_name))

    values = []
    for row in rows[1:]:
        if col_index >= len(row):
            continue
        cell = row[col_index].strip()
        if cell == "":
            continue
        values.append(float(cell))

    if not values:
        raise ValueError("Column has no numeric values: {!r}".format(column_name))

    n = len(values)
    mean = sum(values) / n

    ordered = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        median = ordered[mid]
    else:
        median = (ordered[mid - 1] + ordered[mid]) / 2

    variance = sum((v - mean) ** 2 for v in values) / n
    std_dev = math.sqrt(variance)

    return {"mean": mean, "median": median, "std_dev": std_dev}

