import math


def _pearson(xs, ys):
    n = len(xs)
    if n == 0:
        return float('nan')
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    dx = [x - mean_x for x in xs]
    dy = [y - mean_y for y in ys]
    num = sum(a * b for a, b in zip(dx, dy))
    den_x = math.sqrt(sum(a * a for a in dx))
    den_y = math.sqrt(sum(b * b for b in dy))
    if den_x == 0 or den_y == 0:
        return 1.0 if den_x == den_y else 0.0
    r = num / (den_x * den_y)
    # Clamp and round to remove floating-point noise (e.g. 1.0000000000000002).
    r = max(-1.0, min(1.0, r))
    return round(r, 12) + 0.0


def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError('data must be a dict')

    columns = {}
    for name, values in data.items():
        converted = [mapping[v] if v in mapping else v for v in values]
        columns[name] = converted

    result = {}
    for a, xs in columns.items():
        row = {}
        for b, ys in columns.items():
            row[b] = _pearson(xs, ys)
        result[a] = row
    return result

