def _to_float(value):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if math.isnan(number) or math.isinf(number):
        return None
    return number


def csv_mean_median(csv_text):
    """Compute (mean, median) of numeric values in a single-column CSV.

    The first non-blank row is treated as a header and ignored. Values that
    are not numbers and blank lines are ignored. Returns (None, None) if the
    text is empty or contains no numeric values.
    """
    if csv_text is None or not csv_text.strip():
        return (None, None)

    rows = list(csv.reader(io.StringIO(csv_text)))
    rows = [row for row in rows if row]

    values = []
    for row in rows[1:]:
        value = _to_float(row[0].strip())
        if value is not None:
            values.append(value)

    if not values:
        return (None, None)

    mean = sum(values) / len(values)
    values.sort()
    n = len(values)
    mid = n // 2
    if n % 2 == 1:
        median = float(values[mid])
    else:
        median = (values[mid - 1] + values[mid]) / 2.0

    return (mean, median)

