import random
import math


def _distance_sq(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


def _kmeans_pp_init(points, k, rng):
    """Deterministic k-means++ initialization."""
    centers = [points[rng.randrange(len(points))]]
    while len(centers) < k:
        dists = [min(_distance_sq(p, c) for c in centers) for p in points]
        total = sum(dists)
        if total <= 0.0:
            # All remaining points coincide with chosen centers.
            for p in points:
                if all(_distance_sq(p, c) > 0.0 for c in centers):
                    centers.append(p)
                    break
            else:
                centers.append(points[0])
            continue
        r = rng.random() * total
        acc = 0.0
        for p, d in zip(points, dists):
            acc += d
            if acc >= r:
                centers.append(p)
                break
        else:
            centers.append(points[-1])
    return centers


def _lloyd(points, centers):
    """Run Lloyd's algorithm to convergence from the given centers."""
    k = len(centers)
    centers = [list(c) for c in centers]
    assignments = [0] * len(points)

    for _ in range(300):
        changed = False
        # Assignment step.
        for i, p in enumerate(points):
            best_j = 0
            best_d = _distance_sq(p, centers[0])
            for j in range(1, k):
                d = _distance_sq(p, centers[j])
                if d < best_d:
                    best_d = d
                    best_j = j
            if assignments[i] != best_j:
                assignments[i] = best_j
                changed = True
        if not changed and _ > 0:
            break

        # Update step.
        sums = [[0.0, 0.0] for _ in range(k)]
        counts = [0] * k
        for p, j in zip(points, assignments):
            sums[j][0] += p[0]
            sums[j][1] += p[1]
            counts[j] += 1

        new_centers = []
        for j in range(k):
            if counts[j] > 0:
                new_centers.append([sums[j][0] / counts[j], sums[j][1] / counts[j]])
            else:
                # Empty cluster: reseed with the point farthest from its center.
                far_i = 0
                far_d = -1.0
                for i, p in enumerate(points):
                    d = _distance_sq(p, centers[assignments[i]])
                    if d > far_d:
                        far_d = d
                        far_i = i
                new_centers.append([float(points[far_i][0]), float(points[far_i][1])])

        if new_centers == centers:
            break
        centers = new_centers

    inertia = sum(
        _distance_sq(p, centers[j]) for p, j in zip(points, assignments)
    )
    return centers, inertia


def cluster_centroids(points, k):
    """Group 2D points into k clusters with k-means and return the sorted centroids."""
    pts = [(float(p[0]), float(p[1])) for p in points]
    n = len(pts)
    if n == 0 or k is None or k <= 0:
        return []
    k = min(k, n)

    # Deduplicate to know how many distinct centroids are achievable.
    distinct = list(dict.fromkeys(pts))
    if len(distinct) <= k:
