"""Extract Python dict literals from the bodies of <script> elements in HTML."""

import ast
from html.parser import HTMLParser


class _ScriptCollector(HTMLParser):
    """Collect the raw text content of each <script> element in document order."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.bodies = []
        self._in_script = False
        self._chunks = []

    def handle_starttag(self, tag, attrs):
        if tag == "script":
            self._in_script = True
            self._chunks = []

    def handle_startendtag(self, tag, attrs):
        if tag == "script":
            self._in_script = False

    def handle_endtag(self, tag):
        if tag == "script" and self._in_script:
            self._finish_script()

    def handle_data(self, data):
        if self._in_script:
            self._chunks.append(data)

    def close(self):
        super().close()
        if self._in_script:
            self._finish_script()

    def _finish_script(self):
        self._in_script = False
        self.bodies.append("".join(self._chunks))
        self._chunks = []


def _parse_dict(body):
    """Return the dict read from a script body, or None if it isn't one."""
    text = body.strip()
    candidates = [text]
    # Tolerate a trailing statement terminator, e.g. '{"a": 1};'
    stripped = text.rstrip("\t\n\r ;")
    if stripped != text:
        candidates.append(stripped)
    for candidate in candidates:
        if not candidate.startswith("{"):
            continue
        try:
            value = ast.literal_eval(candidate)
        except Exception:
            continue
        if isinstance(value, dict):
            return value
    return None


def extract_script_dicts(html):
    """Extract Python dict literals from <script> bodies in an HTML string.

    Returns a list of the dictionaries found, in document order. Scripts
    whose content is not a valid dict literal are skipped.
    """
    parser = _ScriptCollector()
    parser.feed(html)
    parser.close()
    results = []
    for body in parser.bodies:
        value = _parse_dict(body)
        if value is not None:
            results.append(value)
    return results

