"""Forecast schedule generation."""

import calendar
import re
from datetime import date

_WEEKDAYS = {
    'MON': 0, 'TUE': 1, 'WED': 2, 'THU': 3, 'FRI': 4, 'SAT': 5, 'SUN': 6,
}

_NTH_WEEKDAY_RE = re.compile(r'^([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)$')


def _parse_start_date(start_date):
    if not isinstance(start_date, str):
        raise ValueError('start_date must be a string in YYYY-MM-DD format')
    parts = start_date.split('-')
    if len(parts) != 3 or len(parts[0]) != 4 or len(parts[1]) != 2 or len(parts[2]) != 2:
        raise ValueError('start_date must be in YYYY-MM-DD format: %r' % (start_date,))
    try:
        return date(int(parts[0]), int(parts[1]), int(parts[2]))
    except ValueError:
        raise ValueError('invalid start date: %r' % (start_date,))


def _nth_weekday_of_month(year, month, week, weekday):
    """Return the date of the `week`-th `weekday` in the given month."""
    first_weekday = date(year, month, 1).weekday()
    day = 1 + (weekday - first_weekday) % 7 + (week - 1) * 7
    if day > calendar.monthrange(year, month)[1]:
        return None
    return date(year, month, day)


def _candidate_in_month(year, month, freq):
    """Return the matching date in the given month, or None if there is none."""
    last_day = calendar.monthrange(year, month)[1]
    if freq == 'month-end':
        return date(year, month, last_day)
    if freq == 'quarter-end':
        if month in (3, 6, 9, 12):
            return date(year, month, last_day)
        return None
    match = _NTH_WEEKDAY_RE.match(freq)
    if match:
        week = int(match.group(1))
        weekday = _WEEKDAYS[match.group(2)]
        return _nth_weekday_of_month(year, month, week, weekday)
    raise ValueError('invalid freq: %r' % (freq,))


def _schedule_dates(start, freq):
    """Yield matching dates in order, beginning with the first on/after start."""
    year, month = start.year, start.month
    while True:
        candidate = _candidate_in_month(year, month, freq)
        if candidate is not None and candidate >= start:
            yield candidate
        month += 1
        if month == 13:
            year, month = year + 1, 1


def forecast_schedule(start_date, freq, sales):
    """Pair each sales figure with the next scheduled date from start_date.

    Returns a list of (date string 'YYYY-MM-DD', sales) tuples.
    """
    start = _parse_start_date(start_date)
    dates = _schedule_dates(start, freq)
    return [(d.isoformat(), value) for d, value in zip(dates, sales)]

