    if not records:
        raise ValueError("records must be a non-empty list")

    REQUIRED_KEYS = ("Name", "Country", "Score")

    seen_names = set()
    by_country = {}
    for record in records:
        for key in REQUIRED_KEYS:
            if key not in record:
                raise ValueError("record is missing required key: {!r}".format(key))
        name = record["Name"]
        if name in seen_names:
            continue
        seen_names.add(name)
        by_country.setdefault(record["Country"], []).append(record["Score"])

    def quantile(sorted_scores, q):
        n = len(sorted_scores)
        pos = (n - 1) * q
        lower = int(pos // 1)
        upper = min(lower + 1, n - 1)
        frac = pos - lower
        return sorted_scores[lower] + (sorted_scores[upper] - sorted_scores[lower]) * frac

    summary = {}
    for country, scores in by_country.items():
        s = sorted(scores)
        summary[country] = [
            float(s[0]),
            quantile(s, 0.25),
            quantile(s, 0.5),
            quantile(s, 0.75),
            float(s[-1]),
        ]
    return summary

