def column_covariance(columns):
    """Compute the sample covariance matrix of a table.

    Args:
        columns: A dict mapping column names to equal-length lists of
            numbers, with at least two rows.

    Returns:
        A nested dict ``result[a][b]`` giving the sample covariance
        (normalised by n - 1) between columns ``a`` and ``b``.

    Raises:
        ValueError: If the table has no columns, no rows, fewer than two
            rows, or columns of unequal length.
        TypeError: If any column contains non-numeric values.
    """
    if not isinstance(columns, dict):
        raise TypeError("columns must be a dict mapping names to lists of numbers")

    names = list(columns.keys())
    if not names:
        raise ValueError("table has no columns")

    data = []
    for name in names:
        values = columns[name]
        if not isinstance(values, (list, tuple)):
            raise TypeError(f"column {name!r} is not a list of numbers")
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(f"column {name!r} contains a non-numeric value: {value!r}")
        data.append([float(v) for v in values])

    n = len(data[0])
    if n == 0:
        raise ValueError("table has no rows")
    if any(len(col) != n for col in data):
        raise ValueError("columns have unequal lengths")
    if n < 2:
        raise ValueError("table must have at least two rows")

    means = [sum(col) / n for col in data]

    result = {}
    for i, a in enumerate(names):
        row = {}
        for j, b in enumerate(names):
            cov = sum(
                (data[i][k] - means[i]) * (data[j][k] - means[j])
                for k in range(n)
            ) / (n - 1)
            row[b] = cov
        result[a] = row
    return result

