from collections import Counter


def summarize_student_records(data):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")
    for key in ('Name', 'Age', 'Score'):
        if key not in data:
            raise ValueError("missing key: " + key)

    names = list(data['Name'])
    ages = list(data['Age'])
    scores = list(data['Score'])

    n = len(names)
    if len(ages) != n or len(scores) != n:
        raise ValueError("Name, Age and Score lists must have the same length")

    records = [[names[i], ages[i], scores[i]] for i in range(n)]

    sorted_records = sorted(records, key=lambda r: (r[0], r[1]))

    totals = {}
    counts = {}
    for name, _, score in records:
        totals[name] = totals.get(name, 0) + score
        counts[name] = counts.get(name, 0) + 1
    averages = {name: totals[name] / counts[name] for name in totals}

    if n == 0:
        most_common_age = None
    else:
        age_counts = Counter(ages)
        most_common_age = age_counts.most_common(1)[0][0]

    return (sorted_records, averages, most_common_age)

