"""Self-contained k-means clustering for 2D points."""

import random


def kmeans_clusters(xs, ys, n_clusters):
    """Cluster 2D points into n_clusters groups using k-means.

    xs and ys are equal-length lists; point i is (xs[i], ys[i]).
    Returns a list of clusters, each a sorted list of point indices,
    ordered by each cluster's smallest index.
    """
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n_clusters < 1:
        raise ValueError("n_clusters must be at least 1")
    if n_clusters > n:
        raise ValueError("n_clusters cannot exceed the number of points")

    points = [(float(x), float(y)) for x, y in zip(xs, ys)]

    centers = _kmeans_plus_plus(points, n_clusters, seed=0)

    labels = [0] * n
    for _ in range(300):
        new_labels = [_nearest(points[i], centers) for i in range(n)]
        if new_labels == labels:
            break
        labels = new_labels
        centers = _recompute_centers(points, labels, n_clusters, centers)

    labels = _fix_empty_clusters(points, labels, n_clusters)

    clusters = [[] for _ in range(n_clusters)]
    for i, label in enumerate(labels):
        clusters[label].append(i)
    clusters = [sorted(c) for c in clusters if c]
    clusters.sort(key=lambda c: c[0])
    return clusters


def _fix_empty_clusters(points, labels, k):
    """Guarantee every cluster is non-empty when k <= len(points)."""
    n = len(points)
    for j in range(k):
        if any(label == j for label in labels):
            continue
        # Take the point closest to this cluster's (empty) mean from the
        # largest cluster that can give one up.
        donor = max(
            (c for c in range(k) if sum(1 for l in labels if l == c) > 1),
            key=lambda c: sum(1 for l in labels if l == c),
            default=None,
        )
        if donor is None:
            break
        best_i, best_d = None, None
        for i in range(n):
            if labels[i] != donor:
                continue
            d = _dist2(points[i], _cluster_mean(points, labels, j, donor))
            if best_d is None or d < best_d:
                best_i, best_d = i, d
        labels[best_i] = j
    return labels


def _cluster_mean(points, labels, j, fallback_label):
    xs = [points[i][0] for i in range(len(points)) if labels[i] == fallback_label]
    ys = [points[i][1] for i in range(len(points)) if labels[i] == fallback_label]
    if xs:
        return (sum(xs) / len(xs), sum(ys) / len(ys))
    return (0.0, 0.0)


def _dist2(p, q):
    dx = p[0] - q[0]
    dy = p[1] - q[1]
    return dx * dx + dy * dy


def _nearest(p, centers):
    best, best_d = 0, _dist2(p, centers[0])
    for j in range(1, len(centers)):
        d = _dist2(p, centers[j])
        if d < best_d:
            best, best_d = j, d
    return best


def _kmeans_plus_plus(points, k, seed):
    rng = random.Random(seed)
    centers = [points[rng.randrange(len(points))]]
    while len(centers) < k:
        d2 = [min(_dist2(p, c) for c in centers) for p in points]
        total = sum(d2)
        if total == 0.0:
            # All remaining points coincide with a chosen center;
            # fall back to uniform picks.
            centers.append(points[rng.randrange(len(points))])
            continue
        r = rng.random() * total
        acc = 0.0
        for i, d in enumerate(d2):
            acc += d
            if acc >= r:
                centers.append(points[i])
                break
        else:
            centers.append(points[-1])
    return centers


def _recompute_centers(points, labels, k, old_centers):
    sums = [[0.0, 0.0, 0] for _ in range(k)]
    for i, label in enumerate(labels):
        s = sums[label]
        s[0] += points[i][0]
        s[1] += points[i][1]
        s[2] += 1
    centers = []
    for j in range(k):
        sx, sy, count = sums[j]
        if count > 0:
            centers.append((sx / count, sy / count))
        else:
            # Empty cluster: reseed with the point farthest from
            # its assigned center.
            far_i, far_d = 0, -1.0
            for i, label in enumerate(labels):
                d = _dist2(points[i], old_centers[label])
                if d > far_d:
                    far_i, far_d = i, d
            centers.append(points[far_i])
    return centers

