"""Compute the pairwise Pearson correlation matrix of numeric columns in a JSON table."""

import json
import math


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _pearson(xs, ys):
    n = len(xs)
    sx = sum(xs)
    sy = sum(ys)
    num = n * sum(a * b for a, b in zip(xs, ys)) - sx * sy
    dx = n * sum(a * a for a in xs) - sx * sx
    dy = n * sum(b * b for b in ys) - sy * sy
    den = math.sqrt(dx) * math.sqrt(dy)
    if den == 0:
        return float("nan")
    return num / den


def numeric_correlation_from_json(json_text):
    """Return the pairwise Pearson correlation matrix of the numeric columns.

    The input is a JSON object mapping column names to equal-length lists of
    values. Non-numeric columns are ignored. The result maps each numeric
    column name to a dict mapping each numeric column name to the Pearson
    correlation between the two columns.

    Raises ValueError if the text is not valid JSON or the data is empty.
    """
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("not valid JSON: {}".format(exc))

    if not isinstance(data, dict) or not data:
        raise ValueError("data is empty")

    columns = {}
    length = None
    for name, values in data.items():
        if not isinstance(values, list):
            raise ValueError("column {!r} is not a list".format(name))
        if length is None:
            length = len(values)
        elif len(values) != length:
            raise ValueError("columns have unequal lengths")
        if values and all(_is_number(v) for v in values):
            columns[name] = [float(v) for v in values]

    if not length or not columns:
        raise ValueError("data is empty")

    result = {}
    for name, xs in columns.items():
        row = {}
        for other, ys in columns.items():
            if name == other:
                row[other] = 1.0
            else:
                row[other] = _pearson(xs, ys)
        result[name] = row
    return result

