def standardize_columns(data):
    """Standardize each column of a numeric table to zero mean and unit
    variance (population standard deviation). Columns with no variation
    become all zeros. Returns a new list of lists of floats."""
    if not data:
        return []

    num_cols = len(data[0])
    for row in data:
        if len(row) != num_cols:
            raise ValueError("All rows must have the same length")

    result = [[0.0] * num_cols for _ in data]
    for j in range(num_cols):
        col = [float(row[j]) for row in data]
        n = len(col)
        mean = sum(col) / n
        var = sum((x - mean) ** 2 for x in col) / n
        std = var ** 0.5
        for i in range(n):
            result[i][j] = 0.0 if std == 0.0 else (col[i] - mean) / std
    return result

