from fractions import Fraction


def classification_summary(y_true, y_pred):
    if len(y_true) != len(y_pred):
        raise ValueError("y_true and y_pred must have the same length")

    labels = []
    for label in list(y_true) + list(y_pred):
        if label not in labels:
            labels.append(label)

    total = len(y_true)
    correct = sum(1 for t, p in zip(y_true, y_pred) if t == p)
    accuracy = Fraction(correct, total) if total else Fraction(0)

    zero = Fraction(0)
    report = {}
    precisions = []
    recalls = []
    f1s = []
    supports = []
    for label in labels:
        tp = sum(1 for t, p in zip(y_true, y_pred) if t == label and p == label)
        pred_count = sum(1 for p in y_pred if p == label)
        support = sum(1 for t in y_true if t == label)

        precision = Fraction(tp, pred_count) if pred_count else zero
        recall = Fraction(tp, support) if support else zero
        f1 = 2 * precision * recall / (precision + recall) if tp else zero

        report[label] = (float(precision), float(recall), float(f1), support)
        precisions.append(precision)
        recalls.append(recall)
        f1s.append(f1)
        supports.append(support)

    n_labels = len(labels)
    if n_labels:
        macro = tuple(
            float(sum(values, zero) / n_labels)
            for values in (precisions, recalls, f1s)
        ) + (total,)
    else:
        macro = (0.0, 0.0, 0.0, total)

    if n_labels and total:
        weighted = tuple(
            float(
                sum((v * s for v, s in zip(values, supports)), zero) / total
            )
            for values in (precisions, recalls, f1s)
        ) + (total,)
    else:
        weighted = (0.0, 0.0, 0.0, total)

    report["accuracy"] = float(accuracy)
    report["macro avg"] = macro
    report["weighted avg"] = weighted
    return report

