import re


def tfidf_matrix(documents):
    """Compute a TF-IDF matrix for a list of documents.

    Words are maximal runs of letters and digits, lowercased. Term frequency
    is the raw count in the document, idf is ln((1 + n) / (1 + df)) + 1, and
    each document vector is scaled to unit Euclidean length.

    Returns (words, rows): the alphabetically sorted vocabulary and one row of
    TF-IDF scores per document, aligned with the vocabulary.
    """
    tokens_per_doc = [
        [t.lower() for t in re.findall(r"[A-Za-z0-9]+", doc)] for doc in documents
    ]
    n = len(documents)

    # Document frequency per word.
    df = {}
    for tokens in tokens_per_doc:
        for word in set(tokens):
            df[word] = df.get(word, 0) + 1

    words = sorted(df)

    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1 for word in words
    }

    rows = []
    for tokens in tokens_per_doc:
        counts = {}
        for t in tokens:
            counts[t] = counts.get(t, 0) + 1
        vec = [counts.get(word, 0) * idf[word] for word in words]
        norm = math.sqrt(sum(v * v for v in vec))
        if norm > 0:
            vec = [v / norm for v in vec]
        rows.append(vec)

    return words, rows

