import math


def row_distance_matrix(rows):
    """Return the matrix of Euclidean distances between every pair of rows.

    rows is a 2D list of numbers (each inner list a row, all the same
    length). Entry [i][j] of the result is the Euclidean distance between
    row i and row j. Raises TypeError if any element is not an int or float.
    """
    for row in rows:
        for x in row:
            if not isinstance(x, (int, float)):
                raise TypeError(
                    "all elements must be int or float, got "
                    + type(x).__name__
                )

    n = len(rows)
    matrix = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            dist = math.sqrt(
                sum((a - b) ** 2 for a, b in zip(rows[i], rows[j]))
            )
            matrix[i][j] = dist
            matrix[j][i] = dist
    return matrix

