import math


def _cube_root(x):
    """Return the cube root of x, exact when one is representable.

    pow(x, 1/3) and math.cbrt(x) each produce inexact results for some
    inputs (27 and 64 respectively on common platforms), so try both and
    refine with Newton steps, preferring a root whose cube equals x.
    """
    sign = math.copysign(1.0, x)
    a = abs(x)
    if a == 0.0 or a == math.inf:
        return sign * a

    best = a ** (1.0 / 3.0)
    best_err = abs(best * best * best - a)
    if best_err == 0.0:
        return sign * best

    try:
        other = math.cbrt(a)
        err = abs(other * other * other - a)
        if err == 0.0:
            return sign * other
        if err < best_err:
            best, best_err = other, err
    except AttributeError:
        pass

    for _ in range(3):
        r = best - (best * best * best - a) / (3.0 * best * best)
        err = abs(r * r * r - a)
        if err == 0.0:
            return sign * r
        if err < best_err:
            best, best_err = r, err

    for neighbour in (math.nextafter(best, math.inf),
                      math.nextafter(best, -math.inf)):
        if neighbour > 0.0 and neighbour * neighbour * neighbour == a:
            return sign * neighbour

    return sign * best


