    rows = list(reader)
    if not rows:
        return {}, {}

    header = rows[0]
    data_rows = rows[1:]

    values = {name: [] for name in header}
    for row in data_rows:
        for i, name in enumerate(header):
            raw = row[i] if i < len(row) else ""
            try:
