import csv
import io
import math


def correlation_matrix_from_csv(csv_text):
    """Compute the pairwise Pearson correlation matrix of numeric CSV columns.

    The first line of the CSV is a header naming the columns. Returns a dict
    of dicts where result[a][b] is the Pearson correlation between columns
    a and b. If a column has zero variance, its correlations are reported
    as 0.0 (Pearson correlation is undefined in that case).
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]
    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    data = {name: [] for name in header}

    for row in rows[1:]:
        if len(row) != len(header):
            raise ValueError(
                "Row has %d fields, expected %d" % (len(row), len(header))
            )
        for name, value in zip(header, row):
            data[name].append(float(value))

    n = len(rows) - 1
    if n == 0:
        raise ValueError("CSV has no data rows")

    sums = {name: sum(values) for name, values in data.items()}
    sqsums = {
        name: sum(v * v for v in values) for name, values in data.items()
    }

    def correlation(a, b):
        if a == b:
            return 1.0
        sa, sb = sums[a], sums[b]
        sab = sum(x * y for x, y in zip(data[a], data[b]))
        num = n * sab - sa * sb
        den = math.sqrt(
            (n * sqsums[a] - sa * sa) * (n * sqsums[b] - sb * sb)
        )
        if den == 0.0:
            return 0.0
        return num / den

    result = {}
    for a in header:
        result[a] = {b: correlation(a, b) for b in header}
    return result

