"""Cluster rows into 3 groups with k-means on standardized columns."""

import math
import random


def _standardize(rows):
    """Return rows with each column scaled to zero mean and unit variance."""
    n = len(rows)
    dim = len(rows[0]) if n else 0
    data = []
    for j in range(dim):
        col = [float(r[j]) for r in rows]
        mean = sum(col) / n
        var = sum((x - mean) ** 2 for x in col) / n
        std = math.sqrt(var)
        if std == 0.0:
            std = 1.0
        data.append([(x - mean) / std for x in col])
    # transpose back to row-major
    return [[data[j][i] for j in range(dim)] for i in range(n)]


def _dist_sq(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b))


def _kmeans_once(data, k, rng):
    """One k-means run (k-means++ init, Lloyd iterations). Returns (labels, inertia)."""
    n = len(data)

    # k-means++ initialization
    centroids = [list(data[rng.randrange(n)])]
    while len(centroids) < k:
        d2 = []
        for p in data:
            best = min(_dist_sq(p, c) for c in centroids)
            d2.append(best)
        total = sum(d2)
        if total == 0.0:
            # all points coincide with existing centroids
            centroids.append(list(data[0]))
            continue
        threshold = rng.random() * total
        acc = 0.0
        for i, d in enumerate(d2):
            acc += d
            if acc >= threshold:
                centroids.append(list(data[i]))
                break
        else:
            centroids.append(list(data[-1]))

    labels = [0] * n
    for _ in range(300):
        # assignment step
        changed = False
        for i, p in enumerate(data):
            best_j = 0
            best_d = _dist_sq(p, centroids[0])
            for j in range(1, k):
                d = _dist_sq(p, centroids[j])
                if d < best_d:
                    best_d = d
                    best_j = j
            if labels[i] != best_j:
                labels[i] = best_j
                changed = True
        if not changed:
            break
        # update step (re-seed empty clusters with the farthest point)
        sums = [[0.0] * len(data[0]) for _ in range(k)]
        counts = [0] * k
        for i, p in enumerate(data):
            counts[labels[i]] += 1
            s = sums[labels[i]]
            for j, v in enumerate(p):
                s[j] += v
        for j in range(k):
            if counts[j] > 0:
                centroids[j] = [v / counts[j] for v in sums[j]]
            else:
                far_i = max(range(n), key=lambda i: _dist_sq(data[i], centroids[labels[i]]))
                centroids[j] = list(data[far_i])
        # one extra assignment pass so labels match the final centroids
        for i, p in enumerate(data):
            best_j = 0
            best_d = _dist_sq(p, centroids[0])
            for j in range(1, k):
                d = _dist_sq(p, centroids[j])
                if d < best_d:
                    best_d = d
                    best_j = j
            labels[i] = best_j

    inertia = sum(_dist_sq(p, centroids[labels[i]]) for i, p in enumerate(data))
    return labels, inertia


def cluster_labels(rows):
    """Standardize columns, k-means (k=3) the rows, return labels in first-appearance order."""
    data = _standardize([list(r) for r in rows])
    n = len(data)
    if n == 0:
        return []

    # number of distinct points limits the usable k
    distinct = []
    for p in data:
        if not any(_dist_sq(p, q) == 0.0 for q in distinct):
            distinct.append(p)
    k = min(3, len(distinct))

    if k <= 1:
        return [0] * n

    best_labels = None
    best_inertia = math.inf
    for seed in range(10):
        rng = random.Random(seed)
        labels, inertia = _kmeans_once(data, k, rng)
        if inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels

    # renumber clusters by first appearance (first row is always 0)
    mapping = {}
    out = []
    for lab in best_labels:
        if lab not in mapping:
            mapping[lab] = len(mapping)
        out.append(mapping[lab])
    return out

