"""Histogram of date strings parsed with strftime-style formats."""

from datetime import datetime


def _sort_key(dt):
    td = dt - datetime.min
    return (td.days * 86400 + td.seconds) * 1000000 + td.microseconds


def date_histogram(dates, date_format):
    counts = [0] * 10
    if not dates:
        return counts

    parsed = []
    for s in dates:
        try:
            parsed.append(datetime.strptime(s, date_format))
        except (ValueError, TypeError) as exc:
            raise ValueError(
                "date %r does not match format %r" % (s, date_format)
            ) from exc

    keys = [_sort_key(dt) for dt in parsed]
    lo, hi = min(keys), max(keys)
    span = hi - lo

    for k in keys:
        if k == hi:
            idx = 9
        elif span == 0:
            idx = 0
        else:
            idx = (k - lo) * 10 // span
        counts[idx] += 1

    return counts

