def last_column_skewness(rows):
    """Return the biased Fisher-Pearson skewness of a table's last column.

    ``rows`` is a list of rows, each a list of numbers, where ``None`` marks
    a missing value. Missing values in the last column are ignored.
    Raises ValueError if the table has no rows or no columns.
    """
    if not rows:
        raise ValueError("table has no rows")
    if not any(rows):
        raise ValueError("table has no columns")

    values = [row[-1] for row in rows if row and row[-1] is not None]

    n = len(values)
    if n < 2:
        return 0.0

    mean = sum(values) / n
    m2 = sum((x - mean) ** 2 for x in values) / n
    m3 = sum((x - mean) ** 3 for x in values) / n

    if m2 == 0:
        return 0.0

    return float(m3 / m2 ** 1.5)

