def normalize_columns(data):
    """Rescale each column of a dict of equal-length lists to the range [0, 1].

    Each column's minimum becomes 0.0 and its maximum becomes 1.0. A column
    whose values are all equal becomes all zeros.

    Raises:
        ValueError: if `data` is empty, if a column is not a list of numbers,
            or if a column is empty.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")

    if not data:
        raise ValueError("data must contain at least one column")

    result = {}
    for key, values in data.items():
        if not isinstance(values, (list, tuple)):
            raise ValueError(f"column {key!r} must be a list of numbers")

        if len(values) == 0:
            raise ValueError(f"column {key!r} is empty")

        for v in values:
            # bool is a subclass of int but is not treated as a number here.
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"column {key!r} contains a non-numeric value: {v!r}")

        lo = min(values)
        hi = max(values)
        span = hi - lo

        if span == 0:
            result[key] = [0.0 for _ in values]
        else:
            result[key] = [(v - lo) / span for v in values]

    return result

