def _solve_least_squares(A, b):
    """Solve min ||A z - b||^2 via Householder QR without external deps.

    A is a list of m rows, each a list of p floats. Returns a list of p
    floats. If A is rank deficient, the free components of z are set to 0,
    which still yields an exact solution of the (always consistent) normal
    equations.
    """
    m = len(A)
    p = len(A[0]) if m else 0
    if p == 0:
        return []
    R = [row[:] for row in A]
    q = [float(v) for v in b]

    for k in range(min(m, p)):
        sigma = 0.0
        for i in range(k, m):
            sigma += R[i][k] * R[i][k]
        if sigma <= 0.0:
            continue
        alpha = sigma ** 0.5
        if R[k][k] > 0.0:
            alpha = -alpha
        v = [0.0] * m
        v[k] = R[k][k] - alpha
        for i in range(k + 1, m):
            v[i] = R[i][k]
        vnorm2 = 0.0
        for i in range(k, m):
            vnorm2 += v[i] * v[i]
        if vnorm2 == 0.0:
            continue
        for j in range(k, p):
            s = 0.0
            for i in range(k, m):
                s += v[i] * R[i][j]
            f = 2.0 * s / vnorm2
            for i in range(k, m):
                R[i][j] -= f * v[i]
        s = 0.0
        for i in range(k, m):
            s += v[i] * q[i]
        f = 2.0 * s / vnorm2
        for i in range(k, m):
            q[i] -= f * v[i]

    z = [0.0] * p
    for k in range(min(m, p) - 1, -1, -1):
        denom = R[k][k]
        if abs(denom) <= 1e-12 * max(1.0, abs(R[0][0]) if m else 1.0):
            continue
        s = q[k]
        for j in range(k + 1, p):
            s -= R[k][j] * z[j]
        z[k] = s / denom
    return z


def fit_joined_regression(feature_rows, target_rows, features, target):
    target_by_id = {row['id']: row for row in target_rows}
    joined = [
        (row, target_by_id[row['id']])
        for row in feature_rows
        if row['id'] in target_by_id
    ]

    n = len(features)
    m = len(joined)
    p = n + 1

    X = []
    y = []
    for frow, trow in joined:
        X.append([float(frow[f]) for f in features] + [1.0])
        y.append(float(trow[target]))

    beta = _solve_least_squares(X, y) if m else [0.0] * p

    coefficients = [beta[i] for i in range(n)]
    intercept = float(beta[n])

    residuals = []
    for i in range(m):
        pred = intercept
        for j in range(n):
            pred += coefficients[j] * X[i][j]
        residuals.append(y[i] - pred)

    return {
        'coefficients': coefficients,
        'intercept': intercept,
        'residuals': residuals,
    }

