import csv
import io


def normalize_csv_column(csv_text, column):
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text has no header row")

    try:
        col_index = header.index(column)
    except ValueError:
        raise ValueError("Column not found: {!r}".format(column))

    values = []
    for row in reader:
        if not row:
            continue
        values.append(float(row[col_index]))

    n = len(values)
    if n == 0:
        raise ValueError("No values found in column {!r}".format(column))

    mean = sum(values) / n
    if n < 2:
        raise ValueError("Sample standard deviation requires at least two values")

    variance = sum((v - mean) ** 2 for v in values) / (n - 1)
    std_dev = variance ** 0.5

    if std_dev == 0:
        raise ValueError("Sample standard deviation is zero")

    return [(v - mean) / std_dev for v in values]

