def _quantile(sorted_values, p):
    """Linear-interpolated quantile of an already-sorted list."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])
    pos = (n - 1) * p
    lower = int(pos)
    upper = min(lower + 1, n - 1)
    frac = pos - lower
    return sorted_values[lower] + (sorted_values[upper] - sorted_values[lower]) * frac


def fruit_sales_box_stats(records):
    """Return box-plot statistics (min, q1, median, q3, max) of sales per fruit."""
    if not records:
        raise ValueError("records must not be empty")

    by_fruit = {}
    for fruit, _day, sales in records:
        by_fruit.setdefault(fruit, []).append(sales)

    stats = {}
    for fruit, sales in by_fruit.items():
        values = sorted(float(s) for s in sales)
        stats[fruit] = (
            values[0],
            _quantile(values, 0.25),
            _quantile(values, 0.5),
            _quantile(values, 0.75),
            values[-1],
        )
    return stats

