def column_summary_stats(table, mapping, features):
    """Compute summary statistics for selected columns of a table.

    Args:
        table: dict mapping column names to lists of values.
        mapping: dict used to replace values; any value equal to a key in
            this dict is replaced by the corresponding value before computing.
        features: list of column names to summarize.

    Returns:
        dict mapping each feature name to a dict with keys
        'mean', 'median', 'mode' and 'variance' (population variance).
        Ties for the mode are broken by choosing the smallest value.

    Raises:
        ValueError: if a requested feature is not present in the table.
    """
    result = {}
    for name in features:
        if name not in table:
            raise ValueError(f"Feature not found in table: {name!r}")

        # Apply the value replacements.
        values = []
        for v in table[name]:
            replaced = False
            try:
                if v in mapping:
                    v = mapping[v]
                    replaced = True
            except TypeError:
                replaced = False
            if not replaced:
                # Fall back to equality checks for unhashable values.
                for k, repl in mapping.items():
                    if k == v:
                        v = repl
                        break
            values.append(v)

        if not values:
            result[name] = {'mean': None, 'median': None,
                            'mode': None, 'variance': None}
            continue

        # Mode: most common value, smallest wins ties.
        counts = {}
        for v in values:
            counts[v] = counts.get(v, 0) + 1
        max_count = max(counts.values())
        mode = min(v for v, c in counts.items() if c == max_count)

        # Numeric statistics.
        total = sum(values)
        mean = total / len(values)

        ordered = sorted(values)
        n = len(ordered)
        mid = n // 2
        if n % 2 == 1:
            median = float(ordered[mid])
        else:
            median = (ordered[mid - 1] + ordered[mid]) / 2

        variance = sum((v - mean) ** 2 for v in values) / n

        result[name] = {
            'mean': mean,
            'median': median,
            'mode': mode,
            'variance': variance,
        }
    return result

