from html.parser import HTMLParser


class _LinkExtractor(HTMLParser):
    """Collects (text, href) for each <a> tag in document order."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []   # one dict per <a> tag, in order of appearance
        self._open = []   # stack of currently open <a> entries

    def handle_starttag(self, tag, attrs):
        if tag != 'a':
            return
        entry = {'text': [], 'href': None}
        for name, value in attrs:
            if name == 'href':
                entry['href'] = value
                break
        self.links.append(entry)
        self._open.append(entry)

    def handle_endtag(self, tag):
        if tag == 'a' and self._open:
            self._open.pop()

    def handle_data(self, data):
        if self._open:
            self._open[-1]['text'].append(data)

    def result(self):
        return [(
            ''.join(entry['text']).strip(),
            entry['href'],
        ) for entry in self.links]


def extract_links(html):
    """Return a list of (text, href) tuples for every <a> tag in *html*.

    text is the concatenated text content of the anchor with nested tags
    removed and HTML entities decoded. href is the decoded href attribute
    value, or None if the anchor has no href.
    """
    parser = _LinkExtractor()
    parser.feed(html)
    parser.close()
    return parser.result()

