"""Extract the first <table> from an HTML string.

Self-contained: uses only the standard library.
"""

from html.parser import HTMLParser


_VOID_ELEMENTS = frozenset({
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
})


class _Node:
    __slots__ = ("tag", "children")

    def __init__(self, tag):
        self.tag = tag
        self.children = []  # mix of _Node and str (text)


class _TreeBuilder(HTMLParser):
    """Builds a lightweight DOM tree, tolerating unclosed table tags."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node(None)
        self._stack = [self.root]

    def handle_starttag(self, tag, attrs):
        # Implicit end tags for common malformed table markup.
        if tag in ("td", "th"):
            while self._stack[-1].tag in ("td", "th"):
                self._stack.pop()
        elif tag == "tr":
            while self._stack[-1].tag in ("td", "th", "tr"):
                self._stack.pop()

        if tag in _VOID_ELEMENTS:
            self._stack[-1].children.append(_Node(tag))
        else:
            node = _Node(tag)
            self._stack[-1].children.append(node)
            self._stack.append(node)

    def handle_endtag(self, tag):
        if tag in _VOID_ELEMENTS:
            return
        # Close the nearest matching open element (and anything inside it).
        for i in range(len(self._stack) - 1, 0, -1):
            if self._stack[i].tag == tag:
                del self._stack[i:]
                return

    def handle_startendtag(self, tag, attrs):
        self._stack[-1].children.append(_Node(tag))

    def handle_data(self, data):
        self._stack[-1].children.append(data)


def _iter_tag(node, tag):
    """Yield descendants with the given tag in document order."""
    for child in node.children:
        if isinstance(child, _Node):
            if child.tag == tag:
                yield child
            yield from _iter_tag(child, tag)


def _text(node):
    """Concatenated text of all descendants, tags removed."""
    parts = []

    def walk(n):
        for child in n.children:
            if isinstance(child, str):
                parts.append(child)
            else:
                walk(child)

    walk(node)
    return "".join(parts)


def _td_cells(tr):
    """The <td> cells belonging to a <tr>."""
    cells = [c for c in tr.children if isinstance(c, _Node) and c.tag == "td"]
    if not cells:
        # Fallback for unusual nesting (e.g. wrappers around cells).
        cells = list(_iter_tag(tr, "td"))
    return cells


def extract_first_table(html):
    """Return (headers, rows) for the first <table> in ``html``.

    headers: stripped text of every <th> cell in the table (document order).
    rows: one entry per <tr> that contains <td> cells; each entry is the
    list of stripped text of that row's <td> cells. Rows with no <td>
    (e.g. header rows) are skipped.

    Raises ValueError if there is no table or the table has no data rows.
    """
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()

    tables = list(_iter_tag(builder.root, "table"))
    if not tables:
        raise ValueError("no <table> found in the HTML")

    table = tables[0]

    headers = [_text(th).strip() for th in _iter_tag(table, "th")]

    rows = []
    for tr in _iter_tag(table, "tr"):
        cells = [_text(td).strip() for td in _td_cells(tr)]
        if cells:
            rows.append(cells)

    if not rows:
        raise ValueError("the first table has no data rows")

    return headers, rows

