def chi_square_independence(xs, ys):
    """Pearson chi-square test of independence between two categorical variables.

    Position i is one observation (xs[i], ys[i]). Returns
    (statistic, dof) with no continuity correction.

    Raises ValueError for empty inputs, mismatched lengths, or if either
    variable has fewer than two distinct categories.
    """
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")
    n = len(xs)
    if n == 0:
        raise ValueError("inputs must not be empty")

    row_labels = []
    for x in xs:
        if x not in row_labels:
            row_labels.append(x)
    col_labels = []
    for y in ys:
        if y not in col_labels:
            col_labels.append(y)

    r = len(row_labels)
    c = len(col_labels)
    if r < 2:
        raise ValueError("xs must have at least two distinct categories")
    if c < 2:
        raise ValueError("ys must have at least two distinct categories")

    observed = [[0] * c for _ in range(r)]
    row_totals = [0] * r
    col_totals = [0] * c
    for x, y in zip(xs, ys):
        i = row_labels.index(x)
        j = col_labels.index(y)
        observed[i][j] += 1
        row_totals[i] += 1
        col_totals[j] += 1

    statistic = 0.0
    for i in range(r):
        for j in range(c):
            expected = row_totals[i] * col_totals[j] / n
            statistic += (observed[i][j] - expected) ** 2 / expected

    dof = (r - 1) * (c - 1)
    return (statistic, dof)

