import csv
import io


def grouped_column_means(csv_text, group_col, value_col):
    """Group rows of ``csv_text`` by ``group_col`` and return the mean of
    ``value_col`` per group.

    Returns a dict mapping each group label (as a string) to the mean of the
    numeric values in that group. Blank cells in the value column are ignored.
    Raises ValueError if the value column contains a non-numeric value, or if
    either requested column is missing from the header.
    """
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text has no header row")

    header = [name.strip() for name in header]
    try:
        group_idx = header.index(group_col)
        value_idx = header.index(value_col)
    except ValueError:
        raise ValueError(
            "Column not found in header: %r" % (group_col if group_col not in header else value_col)
        )

    sums = {}
    counts = {}
    for row in reader:
        if not row or all(cell.strip() == "" for cell in row):
            continue
        if group_idx >= len(row) or value_idx >= len(row):
            raise ValueError("Row does not have enough columns: %r" % (row,))
        group_label = row[group_idx].strip()
        raw_value = row[value_idx].strip()
        if raw_value == "":
            continue
        try:
            value = float(raw_value)
        except ValueError:
            raise ValueError(
                "Non-numeric value %r in column %r" % (row[value_idx], value_col)
            )
        sums[group_label] = sums.get(group_label, 0.0) + value
        counts[group_label] = counts.get(group_label, 0) + 1

    return {label: sums[label] / counts[label] for label in sums if counts[label] > 0}

