_MAX_ITER = 100
_N_INIT = 8


def _sq_dist(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


class _Rng:
    """Small deterministic PRNG (xorshift32), independent of global state."""

    def __init__(self, state):
        self._state = (state or 1) & 0xFFFFFFFF

    def random(self):
        s = self._state
        s ^= (s << 13) & 0xFFFFFFFF
        s ^= s >> 17
        s ^= (s << 5) & 0xFFFFFFFF
        self._state = s
        return s / 0x100000000


def _kmeanspp_init(points, k, rng):
    n = len(points)
    centroids = [points[int(rng.random() * n) % n]]
    while len(centroids) < k:
        dists = [min(_sq_dist(p, c) for c in centroids) for p in points]
        total = sum(dists)
        if total <= 0.0:
            # All points coincide with existing centroids; fall back to the
            # first point not already chosen.
            for p in points:
                if p not in centroids:
                    centroids.append(p)
                    break
            else:
                break
            continue
        threshold = rng.random() * total
        cumulative = 0.0
        for p, d in zip(points, dists):
            cumulative += d
            if cumulative >= threshold:
                centroids.append(p)
                break
        else:
            centroids.append(points[dists.index(max(dists))])
    return centroids


def _farthest_init(points, k):
    centroids = [points[0]]
    while len(centroids) < k:
        dists = [min(_sq_dist(p, c) for c in centroids) for p in points]
        best = max(range(len(points)), key=lambda i: dists[i])
        if dists[best] <= 0.0:
            for p in points:
                if p not in centroids:
                    centroids.append(p)
                    break
            else:
                break
            continue
        centroids.append(points[best])
    return centroids


def _lloyd(points, k, centroids):
    n = len(points)
    labels = [0] * n
    inertia = 0.0
    for _ in range(_MAX_ITER):
        changed = False
        inertia = 0.0
        for i, p in enumerate(points):
            best_j = 0
            best_d = _sq_dist(p, centroids[0])
            for j in range(1, k):
                d = _sq_dist(p, centroids[j])
                if d < best_d:
                    best_d = d
                    best_j = j
            inertia += best_d
            if labels[i] != best_j:
                labels[i] = best_j
                changed = True
        if not changed:
            break
        sums = [[0.0, 0.0, 0] for _ in range(k)]
        for p, lbl in zip(points, labels):
            s = sums[lbl]
            s[0] += p[0]
            s[1] += p[1]
            s[2] += 1
        for j in range(k):
            count = sums[j][2]
            if count:
                centroids[j] = (sums[j][0] / count, sums[j][1] / count)
    return labels, inertia


def cluster_point_labels(data, n_clusters):
    """Group (identifier, x, y) tuples into ``n_clusters`` clusters via k-means.

    Returns integer cluster labels, one per point, in input order. Clusters
    are numbered by first appearance in input order: the first point's
    cluster is 0, the next new cluster encountered is 1, and so on.

    Raises ValueError if ``data`` is empty.
    """
    if not data:
        raise ValueError("data must not be empty")

    n = len(data)
    try:
        k = int(n_clusters)
    except (TypeError, ValueError):
        raise ValueError("n_clusters must be an integer") from None
    if k < 1:
        raise ValueError("n_clusters must be at least 1")
    if k > n:
        raise ValueError(
            "n_clusters (%d) cannot exceed the number of points (%d)" % (k, n)
        )

    points = [(float(x), float(y)) for _, x, y in data]

    # Trivial case: every point is its own cluster.
    if k == n:
        return list(range(n))

    # Cap k at the number of distinct points; duplicate points cannot form
    # separate clusters.
    distinct = list(dict.fromkeys(points))
    k = min(k, len(distinct))
    if k <= 1:
        return [0] * n

    # Multiple deterministic initialisations; keep the best result.
    best_labels = None
    best_inertia = None
    inits = [_farthest_init(points, k)]
    for seed in range(1, _N_INIT):
        inits.append(_kmeanspp_init(points, k, _Rng(seed * 2654435761 + 12345)))
    for init in inits:
        labels, inertia = _lloyd(points, k, list(init))
        if best_labels is None or inertia < best_inertia:
            best_labels, best_inertia = labels, inertia

    # Renumber clusters by first appearance in input order.
    mapping = {}
    result = []
    for lbl in best_labels:
        if lbl not in mapping:
            mapping[lbl] = len(mapping)
        result.append(mapping[lbl])
    return result

