import io


def _parse_number(text):
    """Return int/float for numeric text, else None."""
    if not isinstance(text, str):
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        pass
    try:
        return float(stripped)
    except ValueError:
        return None


def sort_csv_rows(csv_text, sort_by_column):
    """Sort the data rows of a CSV (with header) ascending by a column.

    Returns a list of dicts mapping column names to values. Columns whose
    values are all numeric hold ints/floats; other columns hold strings.
    Raises ValueError if sort_by_column is not in the header.
    """
    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return []
