"""Histogram of an 8-bit grayscale PGM image (binary P5 or ASCII P2)."""

_WHITESPACE = b" \t\n\r\x0b\x0c"
_COMMENT = 0x23  # '#'


def _skip_whitespace(data, i):
    """Skip whitespace and '#' comments starting at index i."""
    n = len(data)
    while i < n:
        c = data[i]
        if c in _WHITESPACE:
            i += 1
        elif c == _COMMENT:
            while i < n and data[i] not in b"\r\n":
                i += 1
        else:
            break
    return i


def _next_token(data, i):
    """Return (token, index after token) for the next header token."""
    i = _skip_whitespace(data, i)
    n = len(data)
    if i >= n:
        raise ValueError("unexpected end of PGM header")
    j = i
    while j < n and data[j] not in _WHITESPACE and data[j] != _COMMENT:
        j += 1
    return data[i:j], j


def _token_to_int(token, what):
    # bytes.isdigit() is true only for non-empty runs of ASCII digits,
    # so signs, spaces, or other garbage are rejected here.
    if not token.isdigit():
        raise ValueError("invalid %s in PGM header: %r" % (what, token))
    return int(token)


def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit grayscale PGM image.

    ``data`` is the raw bytes of a P5 (binary) or P2 (ASCII) PGM file.
    The result maps each occurring pixel value (0-255) to its pixel count.
    Raises ValueError if the bytes are not a valid 8-bit grayscale PGM.
    """
    if isinstance(data, (bytearray, memoryview)):
        data = bytes(data)
    if not isinstance(data, bytes):
        raise ValueError("PGM image data must be raw bytes")

    magic, pos = _next_token(data, 0)
    if magic not in (b"P2", b"P5"):
        raise ValueError("not a grayscale PGM image (bad magic number)")

    token, pos = _next_token(data, pos)
    width = _token_to_int(token, "width")
    token, pos = _next_token(data, pos)
    height = _token_to_int(token, "height")
    token, pos = _next_token(data, pos)
    maxval = _token_to_int(token, "maxval")

    if width < 1 or height < 1:
        raise ValueError("invalid image dimensions")
    if not 1 <= maxval <= 255:
        raise ValueError("only 8-bit grayscale PGM images are supported")

    if magic == b"P5":
        # Exactly one whitespace byte separates the maxval from the raster.
        if pos >= len(data) or data[pos] not in _WHITESPACE:
            raise ValueError("missing whitespace between maxval and raster")
        raster = data[pos + 1:]
        if len(raster) != width * height:
            raise ValueError("raster size mismatch")
        if maxval < 255 and any(v > maxval for v in raster):
            raise ValueError("pixel value exceeds maxval")
        hist = {}
        for v in raster:
            hist[v] = hist.get(v, 0) + 1
        return hist

    # P2: ASCII pixel values, whitespace- and comment-separated.
    hist = {}
    count = 0
    expected = width * height
    n = len(data)
    i = pos
    while True:
        i = _skip_whitespace(data, i)
        if i >= n:
            break
        j = i
        while j < n and data[j] not in _WHITESPACE and data[j] != _COMMENT:
            j += 1
        token = data[i:j]
        i = j
        if not token.isdigit():
            raise ValueError("invalid pixel value: %r" % token)
        if count >= expected:
            raise ValueError("too many pixel values")
        value = int(token)
        if value > maxval:
            raise ValueError("pixel value exceeds maxval")
        hist[value] = hist.get(value, 0) + 1
        count += 1
    if count != expected:
        raise ValueError("too few pixel values")
    return hist

