import csv
import io
import math


def _try_parse_number(text):
    """Parse a string as a number, allowing thousands separators.

    Returns a float on success, or None if the text is not a number.
    """
    if text is None:
        return None
    cleaned = text.strip().replace(",", "")
    if not cleaned:
        return None
    try:
        return float(cleaned)
    except ValueError:
        return None


def _sample_std_dev(values):
    n = len(values)
    if n < 2:
        return 0.0
    mean = sum(values) / n
    return math.sqrt(sum((v - mean) ** 2 for v in values) / (n - 1))


def _anova_f(groups):
    """One-way ANOVA F statistic treating each column's values as a group."""
    k = len(groups)
    if k < 2:
        return None

    all_values = [v for g in groups for v in g]
    n_total = len(all_values)
    grand_mean = sum(all_values) / n_total

    # Between-group (treatment) sum of squares.
    ss_treatment = sum(
        len(g) * (sum(g) / len(g) - grand_mean) ** 2 for g in groups
    )
    df_treatment = k - 1

    # Within-group (error) sum of squares.
    ss_error = sum(
        sum((v - sum(g) / len(g)) ** 2 for v in g) for g in groups
    )
    df_error = n_total - k

    if df_error <= 0 or ss_error == 0:
        return None

    ms_treatment = ss_treatment / df_treatment
    ms_error = ss_error / df_error
    return ms_treatment / ms_error


def summarize_numeric_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return {"means": {}, "std_devs": {}, "f_value": None}

    header = rows[0]
    data_rows = rows[1:]

    numeric_columns = {}
    for col_index, name in enumerate(header):
        values = []
        is_numeric = True
        for row in data_rows:
            if col_index >= len(row):
                is_numeric = False
                break
            parsed = _try_parse_number(row[col_index])
            if parsed is None:
                is_numeric = False
                break
            values.append(parsed)
        if is_numeric and values:
            numeric_columns[name] = values

    if not data_rows:
        return {"means": {}, "std_devs": {}, "f_value": None}

    means = {name: sum(v) / len(v) for name, v in numeric_columns.items()}
    std_devs = {name: _sample_std_dev(v) for name, v in numeric_columns.items()}
    f_value = _anova_f(list(numeric_columns.values()))

    return {"means": means, "std_devs": std_devs, "f_value": f_value}

