def matrix_tensor_product(P, T):
    """Contract P (M x N) with T (N x A x B) over N.

    Returns (product, sums) where product is M x A x B with
    product[m][a][b] = sum_n P[m][n] * T[n][a][b], and sums is
    M x A with sums[m][a] = sum_b product[m][a][b].
    """
    if not P:
        raise ValueError("P must have at least one row")
    if not T or not T[0]:
        raise ValueError("T must be a non-empty tensor")

    N = len(T)
    for row in P:
        if len(row) != N:
            raise ValueError(
                "P row length (%d) does not match T first dimension (%d)"
                % (len(row), N)
            )

    product = [
        [
            [
                sum(P[m][n] * T[n][a][b] for n in range(N))
                for b in range(len(T[0][0]))
            ]
            for a in range(len(T[0]))
        ]
        for m in range(len(P))
    ]

    sums = [
        [sum(product[m][a]) for a in range(len(product[m]))]
        for m in range(len(product))
    ]

    return (product, sums)

