def feature_correlation_matrix(samples):
    """Compute the pairwise Pearson correlation matrix between features.

    `samples` is a list of rows, each a list of numeric feature values,
    all rows the same length. Each position in a row is a feature; the
    returned matrix entry [i][j] is the Pearson correlation between
    feature i and feature j, in column order.
    """
    n = len(samples)
    if n == 0:
        return []
    m = len(samples[0])
    if n == 1 or m == 0:
        return [[1.0] * m for _ in range(m)]

    means = []
    for j in range(m):
        col = [row[j] for row in samples]
        means.append(sum(col) / n)

    # Population standard deviations per feature.
    stds = []
    for j in range(m):
        var = sum((row[j] - means[j]) ** 2 for row in samples) / n
        stds.append(var ** 0.5)

    matrix = []
    for i in range(m):
        row_out = []
        for j in range(m):
            if i == j:
                row_out.append(1.0)
            elif stds[i] == 0.0 or stds[j] == 0.0:
                # Correlation is undefined for a constant feature;
                # report 0.0 rather than a division by zero.
                row_out.append(0.0)
            else:
                cov = sum(
                    (samples[r][i] - means[i]) * (samples[r][j] - means[j])
                    for r in range(n)
                ) / n
                row_out.append(cov / (stds[i] * stds[j]))
        matrix.append(row_out)
    return matrix

