"""Extract hyperlink targets from an HTML document."""

from html.parser import HTMLParser
from urllib.parse import urljoin


class _LinkCollector(HTMLParser):
    """Collects the href attribute of every <a> element, in document order."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hrefs = []

    def handle_starttag(self, tag, attrs):
        if tag != "a":
            return
        for name, value in attrs:
            if name == "href":
                if value is not None:
                    self.hrefs.append(value)
                break


def extract_page_links(html, base_url):
    """Return the href of every <a> element in *html*, in document order.

    Relative links are resolved against *base_url*; absolute links are
    left unchanged. Duplicates are kept.
    """
    parser = _LinkCollector()
    parser.feed(html if html is not None else "")
    parser.close()
    return [urljoin(base_url, href) for href in parser.hrefs]

