import html.parser


class _RowExtractor(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        # Stack of open containers. Entries are ("table",) for <table> or
        # ("row", row_dict) for <tr>. Rows are dicts with the collected
        # cells and an optional in-progress cell buffer.
        self.stack = []
        self.rows = []

    def _nearest_row(self):
        for entry in reversed(self.stack):
            if entry[0] == "row":
                return entry[1]
        return None

    def _close_open_cell(self):
        # Close the innermost open <td> cell, wherever it sits on the stack.
        for entry in reversed(self.stack):
            if entry[0] == "row" and entry[1]["cell"] is not None:
                entry[1]["cells"].append(entry[1]["cell"].strip())
                entry[1]["cell"] = None
                return

    def _start_tag(self, tag):
        if tag == "table":
            self.stack.append(("table",))
        elif tag == "tr":
            self._close_open_cell()
            row = {"cells": [], "cell": None}
            self.stack.append(("row", row))
            self.rows.append(row)
        elif tag == "td":
            self._close_open_cell()
            row = self._nearest_row()
            if row is not None:
                row["cell"] = ""
        elif tag == "th":
            # Header cells are ignored: terminate any open cell so header
            # text can never leak into a data cell.
            self._close_open_cell()

    def _end_tag(self, tag):
        if tag == "table":
            self._close_open_cell()
            while self.stack:
                if self.stack.pop()[0] == "table":
                    break
        elif tag == "tr":
            self._close_open_cell()
            while self.stack:
                if self.stack.pop()[0] == "row":
                    break
        elif tag in ("td", "thead", "tbody", "tfoot"):
            self._close_open_cell()

    def handle_starttag(self, tag, attrs):
        self._start_tag(tag)

    def handle_startendtag(self, tag, attrs):
        if tag in ("table", "tr", "td", "th"):
            self._start_tag(tag)
            self._end_tag(tag)

    def handle_endtag(self, tag):
        self._end_tag(tag)

    def handle_data(self, data):
        # Text belongs to the innermost open cell, if any.
        for entry in reversed(self.stack):
            if entry[0] == "row" and entry[1]["cell"] is not None:
                entry[1]["cell"] += data
                return

    def close(self):
        super().close()
        self._close_open_cell()
        self.stack.clear()


