    of its <td> cells. Rows without <td> cells (e.g. header-only rows)
    yield empty lists. Returns [] when there are no rows.
    """
    parser = _RowExtractor()
    parser.feed(html_text)
    parser.close()
    return [row["cells"] for row in parser.rows]

