import json


def _percentile(sorted_values, p):
    """Value at percentile p (0..1) via linear interpolation between sorted values."""
    n = len(sorted_values)
    pos = p * (n - 1)
    lo = int(pos)
    hi = min(lo + 1, n - 1)
    frac = pos - lo
    return float(sorted_values[lo]) + frac * (float(sorted_values[hi]) - float(sorted_values[lo]))


def summarize_values_by_key(json_text):
    """Summarize numeric values per key across a JSON list of objects.

    Returns {key: {'mean', 'median', 'q1', 'q3'}} using linear-interpolation
    quartiles. Raises ValueError for invalid JSON.
    """
    data = json.loads(json_text)
    if not isinstance(data, list):
        raise ValueError("Expected a JSON list of objects")

    values_by_key = {}
    for obj in data:
        if not isinstance(obj, dict):
            raise ValueError("Expected a JSON list of objects")
        for key, value in obj.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("Object values must be numbers")
            values_by_key.setdefault(key, []).append(value)

    summary = {}
    for key, values in values_by_key.items():
        values = sorted(values)
        summary[key] = {
            "mean": sum(values) / len(values),
            "median": _percentile(values, 0.5),
            "q1": _percentile(values, 0.25),
            "q3": _percentile(values, 0.75),
        }
    return summary

