def _exact_solve(features, values, n_features):
    """Solve the normal equations exactly using rational arithmetic.

    Returns the solution as a list of Fractions, or None if the system is
    singular (in which case a pseudo-inverse based fallback is used).
    """
    from fractions import Fraction

    n_cols = n_features + 1
    ata = [[Fraction(0)] * n_cols for _ in range(n_cols)]
    aty = [Fraction(0)] * n_cols

    for row, target in zip(features, values):
        aug = [Fraction(x) for x in row] + [Fraction(1)]
        for j in range(n_cols):
            aty[j] += aug[j] * target
            for k in range(n_cols):
                ata[j][k] += aug[j] * aug[k]

    # Gaussian elimination with partial pivoting (exact arithmetic).
    for col in range(n_cols):
        pivot = col
        best = abs(ata[col][col])
        for r in range(col + 1, n_cols):
            if abs(ata[r][col]) > best:
                best = abs(ata[r][col])
                pivot = r
        if best == 0:
            return None  # singular / rank deficient
        if pivot != col:
            ata[col], ata[pivot] = ata[pivot], ata[col]
            aty[col], aty[pivot] = aty[pivot], aty[col]
        pv = ata[col][col]
        for r in range(col + 1, n_cols):
            factor = ata[r][col] / pv
            if factor:
                for c in range(col, n_cols):
                    ata[r][c] -= factor * ata[col][c]
                aty[r] -= factor * aty[col]

    beta = [Fraction(0)] * n_cols
    for i in range(n_cols - 1, -1, -1):
        acc = aty[i]
        for c in range(i + 1, n_cols):
            acc -= ata[i][c] * beta[c]
        beta[i] = acc / ata[i][i]
    return beta


def fit_linear_regression(features, values):
    """Fit OLS linear regression with an intercept.

    Parameters
    ----------
    features : list of rows, each a list of numbers (one per feature)
    values : list of target values, one per row

    Returns
    -------
    dict with:
        'coefficients' : list of fitted coefficients (feature-column order)
        'intercept'    : float, the fitted intercept
    """
    # Normalize / validate input.
    features = list(features)
    values = list(values)
    if len(features) != len(values):
        raise ValueError('features and values must have the same length')
    if not features:
        raise ValueError('at least one data row is required')

    n_rows = len(values)
    n_features = len(features[0]) if features[0] is not None else 0
    for row in features:
        if len(row) != n_features:
            raise ValueError('all feature rows must have the same length')

    feats = [[float(x) for x in row] for row in features]
    vals = [float(v) for v in values]

    # Try an exact rational solve when every input is an exact integer.
    # This keeps results such as 2.0 exactly 2.0 (no floating-point noise).
    all_integral = all(float(v).is_integer() for v in vals) and all(
        float(x).is_integer() for row in feats for x in row
    )
    if all_integral and n_rows * (n_features + 1) <= 200000:
        int_feats = [[int(x) for x in row] for row in feats]
        int_vals = [int(v) for v in vals]
        beta = _exact_solve(int_feats, int_vals, n_features)
        if beta is not None:
            return {
                'coefficients': [float(b) for b in beta[:n_features]],
