            for k in range(n_cols):
                ata[j][k] += aug[j] * aug[k]

    for col in range(n_cols):
        pivot = max(range(col, n_cols), key=lambda r: abs(ata[r][col]))
        if abs(ata[pivot][col]) < 1e-12:
