"""Merge multiple CSV texts (each with a header row) into a single table."""

import csv
import io
import re

_NUMBER_RE = re.compile(r'^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$')
_INT_RE = re.compile(r'^[+-]?\d+$')


def _convert(value):
    """Convert a CSV cell to int/float when it looks like a number."""
    if value is None:
        return None
    text = value.strip()
    if text == '':
        return None
    if _INT_RE.match(text):
        return int(text)
    if _NUMBER_RE.match(text):
        return float(text)
    return value


def merge_csv_texts(csv_texts):
    """Stack rows of several CSV documents into one table of dicts.

    Parameters
    ----------
    csv_texts : list of str
        CSV documents, each with a header row.

    Returns
    -------
    list of dict
        One dict per data row (in input order).  Every column that appears
        in any input is present as a key; missing or empty cells are None.
        Numeric-looking values are returned as int/float, others as str.
    """
    if not csv_texts:
        return []

    columns = []  # columns in first-seen order across all inputs
    seen = set()
    rows = []

    for text in csv_texts:
        if text is None:
            text = ''
        reader = csv.reader(io.StringIO(text))
        records = list(reader)
        if not records:
            continue

        header = records[0]
        for col in header:
            if col not in seen:
                seen.add(col)
                columns.append(col)

        for record in records[1:]:
            if not record:  # blank line
                continue
            row = {}
            for idx, col in enumerate(header):
                cell = record[idx] if idx < len(record) else ''
                row[col] = _convert(cell)
            rows.append(row)

    # Backfill columns that only appear in later inputs.
    for row in rows:
        for col in columns:
            if col not in row:
                row[col] = None

    return rows

