def letter_count_correlations(strings):
    """Compute pairwise Pearson correlations between per-string letter counts.

    Args:
        strings: A list of lowercase strings.

    Returns:
        A nested dict result[x][y] giving the Pearson correlation between the
        counts of letter x and letter y across the input strings, or None if
        the input list is empty. Only letters that occur somewhere in the
        input are included.
    """
    if strings is None:
