import csv
import io
import math


def _parse_number(text):
    """Return the float value of ``text`` if it represents a real number.

    Returns ``None`` when ``text`` is not a plain (finite) number.
    """
    if text is None:
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        value = float(stripped)
    except (TypeError, ValueError):
        return None
    if math.isnan(value) or math.isinf(value):
        return None
    return value


def _is_numeric(values):
    """A column is numeric when every one of its values is a number."""
    if not values:
        return False
    return all(_parse_number(value) is not None for value in values)


def _min_max_scale(values):
    """Scale ``values`` (already known to be numeric) to the 0..1 range."""
    numbers = [_parse_number(value) for value in values]
    if not numbers:
        return []
    low = min(numbers)
    high = max(numbers)
    span = high - low
    if span == 0:
        # Every value is identical: map the whole column to 0.0.
        return [0.0 for _ in numbers]
    return [(number - low) / span for number in numbers]


def normalize_numeric_columns(csv_text):
    """Normalize the numeric columns of a CSV document.

    The CSV text must start with a header row.  The returned dict maps each
    column name (in header order) to the list of that column's values.  Every
    column whose values are all numbers is min-max scaled to the range 0..1
