    if not rows:
        raise ValueError("CSV text is empty: no numeric columns found")

    header = rows[0]
    data_rows = rows[1:]

    # Build the per-column value lists (short rows are padded with '').
    columns = []
    for index, _name in enumerate(header):
        values = []
        for row in data_rows:
            if index < len(row):
                values.append(row[index])
            else:
                values.append("")
        columns.append(values)

