"""Min-max normalize every numeric column of a CSV document."""

import csv
import io


def _to_number(value):
    """Convert a CSV cell to a float.

    Returns None for empty / unparseable cells.
    """
    if value is None:
        return None
    text = value.strip()
    if not text:
        return None
    try:
        return float(text)
    except ValueError:
        # Tolerate things like "1,234" or "10%" that float() rejects.
        cleaned = text.replace(",", "").replace("%", "")
        try:
            return float(cleaned)
        except ValueError:
            return None


def normalize_csv_columns(csv_text):
    """Min-max normalize each column of ``csv_text`` to the range [0, 1].

    Parameters
    ----------
    csv_text : str
        Text of a CSV file whose first row is a header and whose remaining
        rows contain numeric data.

    Returns
    -------
    dict
        Maps each column name to the list of normalized values (floats),
        in row order.  Columns whose values are all identical (or which
        contain no usable values) are returned as all zeros.
    """
    if csv_text is None:
        return {}

    reader = csv.reader(io.StringIO(csv_text) if not isinstance(csv_text, (list, tuple)) else None)

    # Read all rows as lists of raw strings.
    if isinstance(csv_text, (list, tuple)):
        rows = [list(row) for row in csv_text]
    else:
        rows = []
        for row in reader:
            # Skip completely blank lines (e.g. trailing newline artifacts).
            if row and all((cell is None or cell.strip() == "") for cell in row):
                continue
            rows.append(row)

    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    data_rows = rows[1:]

    # Collect the raw (string) values of each column.
    columns = {name: [] for name in header}
    for row in data_rows:
        for index, name in enumerate(header):
            cell = row[index] if index < len(row) else ""
            columns[name].append(cell)

    result = {}
    for name in header:
        raw_values = columns[name]
        numbers = [_to_number(cell) for cell in raw_values]
        usable = [n for n in numbers if n is not None]

        if not usable:
            # No data (or nothing parseable) -> all zeros.
            result[name] = [0.0] * len(raw_values)
            continue

        low = min(usable)
        high = max(usable)
        span = high - low

        normalized = []
        for n in numbers:
            if n is None:
                normalized.append(0.0)
            elif span == 0:
