"""Extract phone numbers from the text content of an HTML document."""

from html.parser import HTMLParser
import re

_PHONE_RE = re.compile(r'\+\d+')


class _TextExtractor(HTMLParser):
    """Collect all text content of an HTML document, in document order.

    Attribute values are ignored (they are not text content) and character
    entity references are decoded (``convert_charrefs=True``).
    """

    def __init__(self):
        # convert_charrefs=True makes the parser decode entities such as
        # &plus; or &#43; and hand the resulting characters to handle_data.
        super().__init__(convert_charrefs=True)
        self._chunks = []

    def handle_data(self, data):
        if data:
            self._chunks.append(data)

    # Entity / character references are normally resolved by
    # convert_charrefs=True, but if they ever reach these handlers
    # (e.g. malformed markup paths) decode them explicitly so the
    # resulting characters still count as text content.
    def handle_entityref(self, name):
        from html import unescape
        self._chunks.append(unescape('&%s;' % name))

    def handle_charref(self, name):
        from html import unescape
        self._chunks.append(unescape('&#%s;' % name))

    def get_text(self):
        return ''.join(self._chunks)


def extract_phone_numbers(html):
    """Return the list of phone numbers found in ``html``'s text content.

    The text content is the document's text with tags removed and entities
    decoded, concatenated in document order (attribute values excluded).
    A phone number is a '+' immediately followed by one or more digits.
    """
    if html is None:
        return []

    if isinstance(html, bytes):
        try:
            html = html.decode('utf-8')
        except (UnicodeDecodeError, LookupError):
            html = html.decode('utf-8', 'replace')

    parser = _TextExtractor()
    try:
        parser.feed(html)
        parser.close()
    except Exception:
        # Fall back to a plain tag-stripping approach if the parser chokes.
        text = re.sub(r'<[^>]*>', '', html)
    else:
        text = parser.get_text()

    return _PHONE_RE.findall(text)

