import string


def keyword_article_word_counts(articles):
    """Count word occurrences in the content of articles whose titles
    contain 'like' or 'what' (case-insensitive).

    Words keep their original case; punctuation is ignored. Raises
    ValueError if any article lacks a 'Title' or 'Content' key.
    """
    counts = {}

    for article in articles:
        if 'Title' not in article or 'Content' not in article:
            raise ValueError("Article must have both 'Title' and 'Content' keys")

        title = article['Title']
        if not isinstance(title, str):
            title = str(title)
        lowered = title.lower()
        if 'like' not in lowered and 'what' not in lowered:
            continue

        content = article['Content']
        if not isinstance(content, str):
            content = str(content)

        for token in content.split():
            word = token.strip(string.punctuation)
            if word:
                counts[word] = counts.get(word, 0) + 1

    return counts

