from html.parser import HTMLParser

# Elements that are declared empty in HTML and therefore never have any
# content or closing tag.
_VOID_ELEMENTS = frozenset([
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
    'meta', 'param', 'source', 'track', 'wbr',
])

_NO_TITLE = 'No Title'
_NO_DATE = 'No Date'
_NO_AUTHOR = 'No Author'


class _Element(object):
    """A minimal DOM-like node.

    ``nodes`` keeps text and child elements interleaved so that the
    document order of the content is preserved exactly.
    """

    __slots__ = ('tag', 'attrs', 'nodes')

    def __init__(self, tag, attrs=None):
        self.tag = tag
        self.attrs = attrs if attrs is not None else {}
        self.nodes = []

    # -- helpers -------------------------------------------------------
    def classes(self):
        """Return the set of classes declared on this element."""
        cls = self.attrs.get('class')
        if not cls:
            return set()
        if isinstance(cls, (list, tuple)):
            cls = ' '.join(cls)
        return set(cls.split())

    def text(self):
        """Concatenated text content (nested tags removed), stripped."""
        parts = []
        for node in self.nodes:
            if isinstance(node, _Element):
                parts.append(node.text())
            else:
                parts.append(node)
        return ''.join(parts).strip()

    def iter_descendants(self):
        for node in self.nodes:
            if isinstance(node, _Element):
                yield node
                for desc in node.iter_descendants():
                    yield desc

    def find(self, predicate):
        """First descendant element matching ``predicate``, else None."""
        for element in self.iter_descendants():
            if predicate(element):
                return element
        return None


class _TreeBuilder(HTMLParser):
    """Builds a very small element tree from a fragment of HTML."""

    def __init__(self):
        # convert_charrefs=True (the default) decodes entities in text.
        HTMLParser.__init__(self, convert_charrefs=True)
        self.root = _Element('#document')
        self._stack = [self.root]

    # -- parser callbacks ----------------------------------------------
    def handle_starttag(self, tag, attrs):
        attr_dict = {}
        for name, value in attrs:
            if name not in attr_dict:
                attr_dict[name] = value if value is not None else ''

        element = _Element(tag, attr_dict)
        self._stack[-1].nodes.append(element)

        if tag not in _VOID_ELEMENTS:
            self._stack.append(element)

    def handle_startendtag(self, tag, attrs):
        attr_dict = {}
        for name, value in attrs:
            if name not in attr_dict:
                attr_dict[name] = value if value is not None else ''
        self._stack[-1].nodes.append(_Element(tag, attr_dict))

    def handle_endtag(self, tag):
        # Close the nearest matching open tag, implicitly closing any
        # unclosed elements in between.
        for index in range(len(self._stack) - 1, 0, -1):
            if self._stack[index].tag == tag:
                del self._stack[index:]
                return

    def handle_data(self, data):
        self._stack[-1].nodes.append(data)


def _parse(html):
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()
    return builder.root


def extract_article_info(html):
    """Return a list of ``(title, date, author)`` tuples.

    One tuple per ``<div>`` having the class ``container`` (possibly
    among other classes), in document order.  The title is the text of
    the first ``<h1>`` inside the div, the date the text of its first
    ``<span class="date">`` and the author the text of its first
    ``<span class="author">``.  Missing pieces become ``'No Title'``,
    ``'No Date'`` and ``'No Author'``.
    """
    root = _parse(html)

    results = []
    # Depth-first traversal yields the divs in document order.
    for div in root.iter_descendants():
        if div.tag != 'div' or 'container' not in div.classes():
            continue

        h1 = div.find(lambda el: el.tag == 'h1')
        date_el = div.find(
            lambda el: el.tag == 'span' and 'date' in el.classes())
        author_el = div.find(
            lambda el: el.tag == 'span' and 'author' in el.classes())

        title = h1.text() if h1 is not None else ''
        date = date_el.text() if date_el is not None else ''
        author = author_el.text() if author_el is not None else ''

        results.append((
            title if title else _NO_TITLE,
            date if date else _NO_DATE,
            author if author else _NO_AUTHOR,
        ))

    return results

