def key_mean_median(json_text):
    """For every key appearing in any record of a JSON list of objects,
    compute the mean and median of that key's numeric values.

    Missing, null, and non-numeric values are ignored.
    Keys with no numeric values map to {'mean': None, 'median': None}.
    """
    records = json.loads(json_text)

    result = {}
    if not isinstance(records, list):
        return result

    values_by_key = {}

    for record in records:
        if not isinstance(record, dict):
            continue
        for key, value in record.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                continue
            values_by_key.setdefault(key, []).append(value)

    for key in values_by_key:
        vals = values_by_key[key]
        if not vals:
            result[key] = {'mean': None, 'median': None}
        else:
            result[key] = {
                'mean': sum(vals) / len(vals),
                'median': float(median(vals)),
            }

    # Keys that appear in records but never with a numeric value
    for record in records:
        if isinstance(record, dict):
            for key in record:
                if key not in result:
                    result[key] = {'mean': None, 'median': None}

    return result

