    """Outer-join two table row lists on 'id' and standardize the first table.

    Parameters
    ----------
    rows1 : list of dict
        Rows of the first table.  Each row has an 'id' key plus numeric
        feature columns.  A feature value may be missing (either the key is
        absent or the value is None).
    rows2 : list of dict
        Rows of the second table, with an 'id' key plus numeric feature
        columns whose names are disjoint from the first table's columns.

    Returns
    -------
    list of dict
        Merged rows sorted by 'id'.  Every row contains 'id', every feature
        column of the first table (standardized to mean 0 and population
        standard deviation 1, missing values left as None) and every feature
        column of the second table (unchanged, missing values as None).
    """
    rows1 = list(rows1 or [])
    rows2 = list(rows2 or [])

    # ---- collect the (ordered) column names of each table -----------------
    cols1 = []
    for row in rows1:
        for key in row:
            if key != 'id' and key not in cols1:
                cols1.append(key)
    cols2 = []
    for row in rows2:
        for key in row:
            if key != 'id' and key not in cols2:
                cols2.append(key)

    # ---- index the rows by id (keeping insertion order, last one wins) ----
    def index_rows(rows):
        table = {}
        for row in rows:
            table[row['id']] = row
        return table

    table1 = index_rows(rows1)
    table2 = index_rows(rows2)

    all_ids = set(table1) | set(table2)

    def sort_key(i):
        # ids are expected to be comparable numbers; fall back to string form
        try:
            return (0, i)
        except TypeError:
            return (1, str(i))

