def scale_table_columns(data):
    """Scale each column of a table to the [0, 1] range.

    Parameters
    ----------
    data : dict
        Mapping from column names to equal-length lists of numbers, where
        entries may be ``None``.

    Returns
    -------
    dict
        Mapping from each column name to a list of scaled floats, containing
        only the rows that had no ``None`` values, in the original row order.
    """
    if not data:
        return {}

    # Number of rows (all columns are assumed to have equal length, but be
    # defensive and use the length of each column independently).
    n_rows = None
    for values in data.values():
        try:
            length = len(values)
        except TypeError:
            length = 0
        if n_rows is None or length > n_rows:
            n_rows = length
    if n_rows is None:
        n_rows = 0

    # Determine which rows survive: a row is kept only if every column has a
    # non-None value in that row.
    keep = []
    for i in range(n_rows):
        ok = True
        for values in data.values():
            if i >= len(values) or values[i] is None:
                ok = False
                break
        if ok:
            keep.append(i)

    result = {}
    for name, values in data.items():
        kept_values = [float(values[i]) for i in keep]
        if not kept_values:
            result[name] = []
            continue
        lo = min(kept_values)
        hi = max(kept_values)
        span = hi - lo
        if span == 0:
            scaled = [0.0 for _ in kept_values]
        else:
            scaled = [(v - lo) / span for v in kept_values]
        result[name] = scaled

    return result

