def association_chi_square(left, right):
    """Compute the Pearson chi-square statistic of independence.

    Parameters
    ----------
    left, right : lists of [id, category] pairs

    Returns
    -------
    (statistic, dof) : tuple of float and int
    """
    # Join the two lists on id, keeping only ids present in both.
    right_map = {}
    for item in right:
        rid = item[0]
        # keep first occurrence semantics consistent with a dict build
        if rid not in right_map:
            right_map[rid] = item[1]

    joined = []
    seen_left = set()
    for item in left:
        lid = item[0]
        if lid in right_map and lid not in seen_left:
            seen_left.add(lid)
            joined.append((item[1], right_map[lid]))

    if not joined:
        return (0.0, 0)

    # Build the contingency table.
    row_cats = []
    col_cats = []
    for r, c in joined:
        if r not in row_cats:
            row_cats.append(r)
        if c not in col_cats:
            col_cats.append(c)

    row_index = {c: i for i, c in enumerate(row_cats)}
    col_index = {c: i for i, c in enumerate(col_cats)}
    table = [[0] * len(col_cats) for _ in range(len(row_cats))]
    for r, c in joined:
        table[row_index[r]][col_index[c]] += 1

    n_rows = len(row_cats)
    n_cols = len(col_cats)
    row_totals = [sum(row) for row in table]
    col_totals = [sum(table[i][j] for i in range(n_rows)) for j in range(n_cols)]
    total = sum(row_totals)

    if total <= 0:
        return (0.0, 0)

    statistic = 0.0
    for i in range(n_rows):
        for j in range(n_cols):
            expected = row_totals[i] * col_totals[j] / total
            if expected > 0:
                observed = table[i][j]
                statistic += (observed - expected) ** 2 / expected

    dof = (n_rows - 1) * (n_cols - 1)
    return (float(statistic), int(dof))

