"""Utilities for parsing dates written in common human formats.

The module is intentionally self contained: it only relies on the Python
standard library.  The main entry point is :func:`next_business_day`.
"""

from __future__ import annotations

import re
from datetime import date, datetime, timedelta

__all__ = ["next_business_day", "parse_date"]


# ---------------------------------------------------------------------------
# Month handling
# ---------------------------------------------------------------------------

_MONTH_NUMBERS = {
    "january": 1,
    "february": 2,
    "march": 3,
    "april": 4,
    "may": 5,
    "june": 6,
    "july": 7,
    "august": 8,
    "september": 9,
    "october": 10,
    "november": 11,
    "december": 12,
}

# Abbreviations (three letter forms and a few common variants).
_MONTH_ABBREVIATIONS = {
    "jan": 1,
    "feb": 2,
    "mar": 3,
    "apr": 4,
    "may": 5,
    "jun": 6,
    "jul": 7,
    "aug": 8,
    "sep": 9,
    "sept": 9,
    "oct": 10,
    "nov": 11,
    "dec": 12,
}

_WEEKDAYS = {
    "mon", "monday",
    "tue", "tues", "tuesday",
    "wed", "wednesday",
    "thu", "thur", "thurs", "thursday",
    "fri", "friday",
    "sat", "saturday",
    "sun", "sunday",
}

_TIME_RE = re.compile(
    r"(?i)(?:[T ]|^)\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?"
    r"(?:\s*(?:am|pm))?"
    r"(?:\s*(?:z|utc|gmt|[+-]\d{2}:?\d{2}))?"
)
_TZ_RE = re.compile(
    r"(?i)\b(?:z|utc|gmt|ut|est|edt|cst|cdt|mst|mdt|pst|pdt|hrs?)\b"
)
_ORDINAL_RE = re.compile(r"(?i)\b(\d{1,2})(st|nd|rd|th)\b")
_TOKEN_RE = re.compile(r"[a-z]+|\d+")


def _month_from_word(word):
    """Return the month number for a (possibly abbreviated) month name."""
    word = re.sub(r"[^a-z]", "", word.lower())
    if not word:
        return None
    if word in _MONTH_NUMBERS:
        return _MONTH_NUMBERS[word]
    if word in _MONTH_ABBREVIATIONS:
        return _MONTH_ABBREVIATIONS[word]
    if len(word) >= 3:
        matches = {num for name, num in _MONTH_NUMBERS.items() if name.startswith(word)}
        if len(matches) == 1:
            return matches.pop()
    return None


# ---------------------------------------------------------------------------
# Cleaning helpers
# ---------------------------------------------------------------------------

def _clean(text):
    """Strip noise (times, weekday names, ordinals, filler words)."""
    text = text.strip()
    # Remove clock times and the ISO "T"/timezone decorations around them.
    text = _TIME_RE.sub(" ", text)
    text = _TZ_RE.sub(" ", text)
    # "22nd" -> "22"
    text = _ORDINAL_RE.sub(r"\1", text)
    # Meridiem markers left over (e.g. "3 pm").
    text = re.sub(r"(?i)\b(?:a|p)\.?m\.?\b", " ", text)
    # Weekday names and abbreviations carry no date information here.
    text = " ".join(
        tok for tok in text.split()
        if re.sub(r"[^a-z]", "", tok.lower()) not in _WEEKDAYS
    )
    return text


def _expand_year(value):
    """Expand a possibly two digit year into a full year."""
    if value < 100:
        return 2000 + value if value <= 68 else 1900 + value
    return value


def _valid(year, month, day):
    try:
        return date(year, month, day)
    except ValueError:
        return None


# ---------------------------------------------------------------------------
# Parsers
# ---------------------------------------------------------------------------

def _parse_with_month_name(tokens):
    """Parse tokens where one of them is a month name."""
    month = None
    numbers = []
    for token in tokens:
        candidate = _month_from_word(token)
        if candidate is not None and month is None:
            month = candidate
            continue
        if token.isdigit():
            numbers.append(token)

    if month is None or not numbers:
        return None

    year = None
    day = None
    for token in numbers:
        value = int(token)
        if len(token) >= 4:
            year = value
            break
    if year is None:
        # Prefer a value that cannot possibly be a day.
        for token in numbers:
            value = int(token)
            if value > 31:
                year = value
                break
    if year is None:
        if len(numbers) >= 2:
            year = int(numbers[-1])
            numbers = numbers[:-1]
        else:
            return None
    rest = [t for t in numbers if int(t) != year] or numbers
    if rest:
        day = int(rest[0])
    if day is None or not (1 <= day <= 31):
        # Only a month and a year were given ("October 2022"); default to
        # the first day of that month.
        if year >= 1000:
            return _valid(year, month, 1)
        return None
    return _valid(_expand_year(year), month, day)


def _parse_all_numeric(tokens):
    """Parse tokens that are all numeric (e.g. 2022-10-22, 10/22/2022)."""
    if not tokens:
        return None
    # Ignore leftover words (time zone markers, labels, ...) if we still have
    # enough numeric parts to build a date.
    tokens = [t for t in tokens if t.isdigit()]
    if not tokens:
        return None

    # Compact ISO form, e.g. "20221022" (possibly followed by a time).
    for token in tokens:
        if len(token) == 8 and token[:2] in ("19", "20"):
            parsed = _valid(int(token[:4]), int(token[4:6]), int(token[6:8]))
            if parsed is not None:
                return parsed

    if len(tokens) == 1:
        return None

    if len(tokens) < 3:
        return None

    first, second, third = tokens[0], tokens[1], tokens[2]
    a, b, c = int(first), int(second), int(third)

    # 2022-10-22, 2022/10/22, 2022.10.22
    if len(first) == 4:
        return _valid(a, b, c)

    # 10/22/2022, 22/10/2022, 10-22-22, 22.10.22
    if len(third) == 4:
