"""Cluster unique 2-D points with k-means and report duplicated points."""


def _duplicates(points):
    """Map each point occurring more than once to its occurrence count."""
    counts = {}
    for p in points:
        key = tuple(p)
        counts[key] = counts.get(key, 0) + 1
    return {k: v for k, v in counts.items() if v > 1}


def _kmeans_python(points, n_clusters):
    """Deterministic fallback k-means (used only if scikit-learn is missing)."""
    import math
    import random

    pts = [tuple(map(float, p)) for p in points]
    n = len(pts)
    dim = len(pts[0]) if pts else 0

    def dist2(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    def kmeanspp_init(rng):
        centers = [pts[rng.randrange(n)]]
        while len(centers) < n_clusters:
            d = [min(dist2(p, c) for c in centers) for p in pts]
            total = sum(d)
            if total == 0:
                # all remaining points coincide with a chosen center
                remaining = [p for p in pts if p not in centers]
                if not remaining:
                    break
                centers.append(remaining[0])
                continue
            r = rng.random() * total
            acc = 0.0
            for i, di in enumerate(d):
                acc += di
                if acc >= r:
                    centers.append(pts[i])
                    break
            else:
                centers.append(pts[-1])
        return centers

    best_labels, best_inertia = None, None
    for seed in range(10):
        rng = random.Random(seed)
        centers = kmeanspp_init(rng)
        for _ in range(300):
            clusters = [[] for _ in range(n_clusters)]
            labels = []
            for p in pts:
                idx = min(range(n_clusters), key=lambda j: dist2(p, centers[j]))
                labels.append(idx)
                clusters[idx].append(p)
            # handle empty clusters
            for j in range(n_clusters):
                if not clusters[j]:
                    # move the point farthest from its center here
                    far = max(range(n), key=lambda i: dist2(pts[i], centers[labels[i]]))
                    labels[far] = j
                    clusters = [[] for _ in range(n_clusters)]
                    for i, p in enumerate(pts):
                        clusters[labels[i]].append(p)
                    break
            new_centers = []
            for j in range(n_clusters):
                members = clusters[j]
                if members:
                    new_centers.append(
                        tuple(sum(c[i] for c in members) / len(members) for i in range(dim))
                    )
                else:
                    new_centers.append(centers[j])
            if new_centers == centers:
                break
            centers = new_centers
        inertia = sum(dist2(p, centers[labels[i]]) for i, p in enumerate(pts))
        if best_inertia is None or inertia < best_inertia:
            best_inertia, best_labels = inertia, labels
    return best_labels


def _kmeans_labels(points, n_clusters):
    """Return k-means labels for `points`, preferring scikit-learn."""
    try:
        import numpy as np
        from sklearn.cluster import KMeans

        data = np.asarray(points, dtype=float)
        km = KMeans(n_clusters=n_clusters, n_init=10, random_state=0)
        return list(km.fit_predict(data))
    except Exception:
        return _kmeans_python(points, n_clusters)


def cluster_unique_points(points, n_clusters):
    """Report duplicated points and cluster the distinct points with k-means.

    Parameters
    ----------
    points : list of (x, y) tuples
        The input points (duplicates allowed).
    n_clusters : int
        Requested number of clusters.  If there are fewer distinct points
        than this, only that many clusters are produced.

    Returns
    -------
    (duplicates, clusters) : tuple
        ``duplicates`` maps every point occurring more than once to the
        number of times it occurs.  ``clusters`` is a sorted list of
        clusters, where each cluster is a sorted list of point tuples.
    """
    duplicates = _duplicates(points)

    # distinct points, in a stable (first-seen) order
    seen = set()
    unique = []
    for p in points:
        key = tuple(p)
        if key not in seen:
            seen.add(key)
            unique.append(key)

    if not unique:
        return (duplicates, [])

    k = min(int(n_clusters), len(unique))
    if k < 1:
        k = 1

    if k == 1:
        return (duplicates, [sorted(unique)])

    labels = _kmeans_labels(unique, k)

    groups = {}
    for point, label in zip(unique, labels):
        groups.setdefault(int(label), []).append(point)

    clusters = [sorted(group) for group in groups.values()]
    clusters.sort()
    return (duplicates, clusters)


if __name__ == "__main__":
