"""Utilities for parsing and sorting CSV text."""

import csv
import io


def _parse_number(text):
    """Return int/float for a numeric-looking string, else None."""
    if not isinstance(text, str):
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        if _looks_integer(stripped):
            return int(stripped)
        value = float(stripped)
    except (TypeError, ValueError):
        return None
    # Reject things like "nan" / "inf" so ordering stays well defined.
    if value != value or value in (float('inf'), float('-inf')):
        return None
    return value


def _looks_integer(text):
    body = text[1:] if text[:1] in ("+", "-") else text
    return body.isdigit()


def sort_csv_rows(csv_text, sort_by_column='title'):
    """Parse ``csv_text`` and return its data rows sorted by a column.

    Parameters
    ----------
    csv_text : str
        The full text of a CSV file, including its header row.
    sort_by_column : str
        The name of the column to sort the rows by (ascending).

    Returns
    -------
    list of dict
        One dict per data row, mapping each column name to that row's
        value.  Columns whose values are all numeric are converted to
        numbers (int or float); other columns keep string values.
    """
    if csv_text is None:
        return []

    if isinstance(csv_text, bytes):
        csv_text = csv_text.decode('utf-8', 'replace')

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row and any(cell != '' for cell in row)]
    if not rows:
        return []

    header = rows[0]
    data_rows = rows[1:]

    # Determine which columns are entirely numeric.
    numeric_columns = set()
    for index, _name in enumerate(header):
        column_values = []
        for row in data_rows:
            if index < len(row):
                column_values.append(row[index])
        if column_values and all(_parse_number(value) is not None
                                 for value in column_values):
            numeric_columns.add(index)

    # Build the dicts for each row, converting numeric columns.
    parsed_rows = []
    for row in data_rows:
        record = {}
        for index, name in enumerate(header):
            value = row[index] if index < len(row) else ''
            if index in numeric_columns:
                record[name] = _parse_number(value)
            else:
                record[name] = value
        parsed_rows.append(record)

    if not parsed_rows:
        return []

    if sort_by_column not in header:
        raise ValueError(
            "Sort column %r not found in CSV header %r" % (sort_by_column, header))

    return sorted(parsed_rows, key=lambda record: record[sort_by_column])

