"""Discrete Fourier transform magnitudes and a 10-bin magnitude histogram."""

import cmath

try:
    import numpy as _np
except Exception:  # pragma: no cover - fall back to a pure-python DFT
    _np = None

_NUM_BINS = 10


def _dft_magnitudes(values):
    """Magnitudes of the (unnormalized, forward) DFT of ``values``."""
    if not values:
        return []
    if _np is not None:
        coeffs = _np.fft.fft(_np.asarray(values, dtype=complex))
        return [float(m) for m in _np.abs(coeffs)]

    n = len(values)
    mags = []
    for k in range(n):
        s = 0j
        for j, v in enumerate(values):
            s += complex(v) * cmath.exp(-2j * cmath.pi * k * j / n)
        mags.append(abs(s))
    return mags


def _fallback_counts(mags, num_bins=_NUM_BINS):
    """Equal-width histogram counts; the last bin includes its right edge.

    Used when numpy is unavailable or refuses the (degenerate) data range.
    A zero-width range is widened by 0.5 on each side, as numpy does for
    exactly constant data.
    """
    counts = [0] * num_bins
    if not mags:
        return counts

    first = min(mags)
    last = max(mags)
    if first == last:
        first = first - 0.5
        last = last + 0.5

    span = last - first
    for v in mags:
        if v == last:
            idx = num_bins - 1
        else:
            idx = int((v - first) / span * num_bins)
            if idx < 0:
                idx = 0
            elif idx > num_bins - 1:
                idx = num_bins - 1
        counts[idx] += 1
    return counts


def _histogram_counts(mags, num_bins=_NUM_BINS):
    """Counts of an equal-width histogram of ``mags`` over [min, max]."""
    if not mags:
        return [0] * num_bins
    if _np is not None:
        try:
            counts = _np.histogram(_np.asarray(mags, dtype=float),
                                   bins=num_bins)[0]
            return [int(c) for c in counts]
        except (ValueError, TypeError):
            pass
    return _fallback_counts(mags, num_bins)


def spectrum_magnitude_histogram(pairs):
    """Return ``(magnitudes, histogram_counts)`` for the pair values.

    ``pairs`` is a list of ``(label, value)`` tuples.  The values, taken in
    list order, are transformed with the discrete Fourier transform; the
    first returned list holds the magnitudes of the transform's
    coefficients in order, and the second holds the counts of a 10-bin
    equal-width histogram of those magnitudes (bins spanning the smallest
    to the largest magnitude, with the last bin including its right
    edge).
