import ast
import csv
import io
import math


def _is_number(token):
    try:
        float(token)
        return True
    except (TypeError, ValueError):
        return False


def _parse_numbers(value):
    """Parse a string such as "[1, 2, 3]" into a list of numbers."""
    if value is None:
        return []
    value = value.strip()
    if not value:
        return []
    try:
        parsed = ast.literal_eval(value)
    except (ValueError, SyntaxError, TypeError, MemoryError):
        # Fall back to a manual scan for numbers inside the string.
        body = value.strip().lstrip("[").rstrip("]")
        parsed = [
            float(tok) if ("." in tok or "e" in tok.lower()) else int(tok)
            for tok in body.replace(",", " ").split()
            if _is_number(tok)
        ]
    if isinstance(parsed, (int, float)):
        parsed = [parsed]
    if not isinstance(parsed, (list, tuple, set)):
        return []
    numbers = []
    for item in parsed:
        if isinstance(item, bool):
            numbers.append(int(item))
        elif isinstance(item, (int, float)):
            numbers.append(item)
        elif isinstance(item, str) and _is_number(item.strip()):
            token = item.strip()
            numbers.append(float(token) if ("." in token or "e" in token.lower()) else int(float(token)))
    return numbers


def _read_rows(text, delimiter):
    """Read CSV text into rows using an explicit *delimiter*."""
    reader = csv.reader(io.StringIO(text), delimiter=delimiter)
    return [row for row in reader]


def _has_columns(header):
    """True if *header* contains both an ``email`` and a ``list`` column."""
    names = []
    for name in header:
        if isinstance(name, bytes):
            name = name.decode("utf-8", "replace")
        names.append(str(name).strip().lstrip("\ufeff").strip().lower())
    return "email" in names and "list" in names


def _brackets_balanced(text):
    """True if square brackets in *text* are balanced (ignoring nesting order)."""
    depth = 0
    for ch in text:
        if ch == "[":
            depth += 1
        elif ch == "]":
            depth -= 1
            if depth == 0:
                return True
    return depth == 0


def _split_records(text):
    """Parse CSV text into (header, data_rows), repairing unquoted list fields."""
    rows = []
