import xml.etree.ElementTree as ET


def _convert(elem):
    """Convert an Element to its dict/string/None representation."""
    # Collect child values by tag, preserving document order.
    children = {}
    child_order = []
    for child in elem:
        value = _convert(child)
        if child.tag in children:
            if not isinstance(children[child.tag], list):
                children[child.tag] = [children[child.tag]]
            children[child.tag].append(value)
        else:
            children[child.tag] = value
            child_order.append(child.tag)

    text = (elem.text or "").strip()
    attrs = {"@" + k: v for k, v in elem.attrib.items()}

    if not attrs and not children:
        # Simple element: its text (or None).
        return text if text else None

    result = {}
    # Preserve document order: attributes first, then children, then text.
    for key in attrs:
        result[key] = attrs[key]
    for tag in child_order:
        result[tag] = children[tag]
    if text:
        result["#text"] = text
    return result


def xml_to_dict(xml):
    """Parse an XML string into a nested dict of the form {root_tag: value}.

    - An element with no attributes and no child elements becomes its
      (whitespace-trimmed) text, or None if it has no text.
    - Any other element becomes a dict: attributes keyed by '@name',
      child elements keyed by their tag, and text under '#text'.
    - Repeated sibling tags map to a list of values in document order.
    - Raises ValueError for malformed XML.
    """
    if not isinstance(xml, str):
        raise ValueError("xml must be a string")

    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError(str(exc)) from exc
    except (TypeError, ValueError) as exc:
        raise ValueError(str(exc)) from exc

    return {root.tag: _convert(root)}

