def _flatten(L):
    """Recursively flatten a (possibly nested) list of numbers."""
    out = []
    for item in L:
        if isinstance(item, (list, tuple)):
            out.extend(_flatten(item))
        else:
            out.append(item)
    return out


def _percentile(sorted_data, p):
    """Percentile with linear interpolation between data points.

    Equivalent to numpy's default 'linear' interpolation method:
    position = p/100 * (n - 1).
    """
    n = len(sorted_data)
    if n == 0:
        raise ValueError("Cannot compute quartiles of empty data.")
    if n == 1:
        return float(sorted_data[0])
    pos = (p / 100.0) * (n - 1)
    lower = int(pos)
    if lower >= n - 1:
        return float(sorted_data[n - 1])
    frac = pos - lower
    return float(sorted_data[lower]) + frac * (float(sorted_data[lower + 1]) - float(sorted_data[lower]))


def interquartile_range_nested(L):
    """Return the interquartile range (Q3 - Q1) of all numbers in L.

    L is a list of lists of numbers (any nesting depth is handled).
    Quartiles are computed with linear interpolation between data
    points (the usual default, as numpy uses).
    """
    data = sorted(float(x) for x in _flatten(L))
    if not data:
        raise ValueError("Cannot compute quartiles of empty data.")
    q1 = _percentile(data, 25)
    q3 = _percentile(data, 75)
    return float(q3 - q1)

