def quartiles_of_string_groups(groups):
    """Return the 25th, 50th and 75th percentiles of all integers given
    as strings inside a tuple of tuples.

    Uses linear interpolation between closest ranks (the usual default,
    e.g. numpy's 'linear' interpolation method), so the 50th percentile
    is the median.
    """
    # Flatten the groups and convert the string integers to real ints.
    values = [int(item) for group in groups for item in group]
    values.sort()

    n = len(values)
    if n == 0:
        raise ValueError("quartiles_of_string_groups() requires at least one value")

    def percentile(q):
        # Position along the sorted data, 0-based, with linear interpolation.
        pos = (n - 1) * q
        lower = int(pos)
        frac = pos - lower
        if lower + 1 < n:
            return float(values[lower]) + frac * (values[lower + 1] - values[lower])
        return float(values[lower])

    return (percentile(0.25), percentile(0.50), percentile(0.75))

