    for g in order:
        idx = members[g]

        def minmax(vals, col):
            lo = min(vals[i] for i in idx)
            hi = max(vals[i] for i in idx)
            if hi == lo:
                for i in idx:
                    scaled[i][col] = 0.0
            else:
