_MAX_EXACT_ROWS = 5000
_MAX_EXACT_COLS = 80
_MAX_EXACT_DENOM = 1 << 20


def fit_linear_regression(records, target="z"):
    """Fit an OLS linear regression with an intercept.

    Parameters
    ----------
    records : list of dict
        A non-empty list of dicts sharing the same numeric keys.
    target : str, optional
        The key to predict.  Every other key is used as a predictor.

    Returns
    -------
    tuple
        ``(intercept, coefficients)``: ``intercept`` is a float and
        ``coefficients`` is a dict mapping each predictor key to its fitted
        coefficient.

    Examples
    --------
    >>> records = [{'x': 0, 'y': 0, 'z': 1},
    ...            {'x': 1, 'y': 0, 'z': 3},
    ...            {'x': 0, 'y': 1, 'z': 4},
    ...            {'x': 1, 'y': 1, 'z': 6}]
    >>> fit_linear_regression(records)
    (1.0, {'x': 2.0, 'y': 3.0})
    """
    if records is None:
        raise ValueError("records must be a non-empty list of dicts")
    records = list(records)
    if not records:
        raise ValueError("records must not be empty")

    # Keys common to every record (defensive if records differ slightly).
    common = None
    for rec in records:
        if not isinstance(rec, dict):
            raise TypeError("each record must be a dict, got %r" % type(rec))
        keys = set(rec.keys())
        common = keys if common is None else (common & keys)
    if not common:
        raise ValueError("records have no keys in common")
    if target not in common:
        raise ValueError("target key %r not found in records" % (target,))

    predictors = sorted((k for k in common if k != target), key=repr)

    n = len(records)
    m = len(predictors) + 1  # one column per predictor plus the intercept

    # Raw predictor values (intercept column implied) and responses.
    rows = [[rec[k] for k in predictors] for rec in records]
    ys = [rec[target] for rec in records]

    beta = _fit(rows, ys, n, m)

    intercept = _clean(beta[0])
    coefficients = {k: _clean(beta[i + 1]) for i, k in enumerate(predictors)}
    return (intercept, coefficients)


