    >>> records = [{'x': 0, 'y': 0, 'z': 1},
    ...            {'x': 1, 'y': 0, 'z': 3},
    ...            {'x': 0, 'y': 1, 'z': 4},
    ...            {'x': 1, 'y': 1, 'z': 6}]
    >>> fit_linear_regression(records)
    (1.0, {'x': 2.0, 'y': 3.0})
    """
