"""Self-contained helper for reading CSV text and filling in missing values."""

import csv
import io


def _is_number(text):
    """Return True if ``text`` can be parsed as a float."""
    try:
        float(text)
    except (TypeError, ValueError):
        return False
    return True


def fill_missing_with_column_mean(csv_text):
    """Parse CSV text and return a dict mapping column names to value lists.

    Numeric columns are returned as lists of floats where empty cells are
    replaced with the mean of the column's present values.  Non-numeric
    columns are returned as lists of strings where empty cells become None.
    Columns without any present values consist entirely of None values.
    """
    if csv_text is None:
        return {}

    if not isinstance(csv_text, str):
        csv_text = str(csv_text)

    if not csv_text.strip():
        return {}

    rows = [row for row in csv.reader(io.StringIO(csv_text)) if row]

    if not rows:
        return {}

    header = rows[0]
    data = [row for row in rows[1:]]

    # Normalise every row to the width of the header.
    width = len(header)
    normalised = []
    for row in data:
        row = list(row)
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        normalised.append(row)

    columns = {}
    for index, name in enumerate(header):
        raw = [row[index] for row in normalised]
        present = [cell for cell in raw if cell != ""]
        columns[name] = (raw, present)

    result = {}
    for name, (raw, present) in columns.items():
        if present and all(_is_number(cell) for cell in present):
            mean = sum(float(cell) for cell in present) / len(present)
            result[name] = [float(cell) if cell != "" else mean for cell in raw]
        else:
            result[name] = [cell if cell != "" else None for cell in raw]

    return result

