import math
from decimal import Decimal
from fractions import Fraction


def encode_and_standardize(data, replacements):
    """Preprocess a table given as a dict mapping column names to value lists.

    The following steps are applied to every column:

    1. Any value that is a key of ``replacements`` is replaced by its mapped
       value.
    2. Every column containing strings is turned into integer codes 0..k-1,
       numbering the distinct values in sorted order.
    3. Every column is standardized: the mean is subtracted and the result is
       divided by the sample standard deviation (ddof=1).

    Parameters
    ----------
    data : dict
        Maps column names to equal-length lists of values.
    replacements : dict
        Maps values that should be replaced by new values.

    Returns
    -------
    dict
        Maps each column name to its list of standardized floats, with the
        columns in their original order.

    Raises
    ------
    ValueError
        If ``data`` is not a dict.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists of values")

    if replacements is None:
        replacements = {}

    # Step 1: value replacement.
    replaced = {}
    for col, values in data.items():
        new_values = []
        for value in values:
            try:
                if value in replacements:
                    value = replacements[value]
            except TypeError:
                # Unhashable values can never be dict keys.
                pass
            new_values.append(value)
        replaced[col] = new_values

    # Step 2: encode columns containing strings as integer codes.
    encoded = {}
    for col, values in replaced.items():
        if any(isinstance(v, str) for v in values):
            values = _encode_strings(values)
        encoded[col] = values

    # Step 3: standardize every column.
    return {col: _standardize(values) for col, values in encoded.items()}


def _encode_strings(values):
    """Map the distinct values of a column onto codes 0..k-1 in sorted order."""
    try:
        distinct = sorted(set(values))
    except TypeError:
        # Mixed and/or unhashable values: deduplicate manually, sort robustly.
        seen = []
        for v in values:
            if not any(v == s for s in seen):
                seen.append(v)
        try:
            distinct = sorted(seen)
        except TypeError:
            distinct = sorted(seen, key=lambda x: (type(x).__name__, str(x)))
    codes = {v: i for i, v in enumerate(distinct)}
    return [codes[v] for v in values]


def _standardize(values):
    """Standardize one column: (x - mean) / sample standard deviation.

    The mean and the deviations from it are evaluated exactly (rational
    arithmetic), so the only rounding happens when a deviation is divided by
    the sample standard deviation.
    """
    n = len(values)
    if n == 0:
        return []

    # Non-finite floats (nan/inf) propagate through plain float arithmetic.
    if any(isinstance(v, float) and not math.isfinite(v) for v in values):
