import math


def _percentile(sorted_values, q):
    """Linear interpolation percentile, matching numpy's default method."""
    n = len(sorted_values)
    if n == 0:
        return float('nan')
    if n == 1:
        return float(sorted_values[0])
    pos = (n - 1) * q
    lower = int(math.floor(pos))
    upper = min(lower + 1, n - 1)
    frac = pos - lower
    return float(sorted_values[lower] + frac * (sorted_values[upper] - sorted_values[lower]))


def summarize_stock_column(column, data):
    """Summarise a single column of daily stock rows.

    Parameters
    ----------
    column : str
        One of 'Open', 'High', 'Low', 'Close' or 'Volume'.
    data : list
        List of rows, each a list ``[date, open, high, low, close, volume]``.

    Returns
    -------
    dict
        Dictionary with keys 'count', 'mean', 'std', 'min', '25%', '50%',
        '75%' and 'max'.  Missing values (None) are ignored.
    """
    columns = {'Open': 1, 'High': 2, 'Low': 3, 'Close': 4, 'Volume': 5}
    if column not in columns:
        raise ValueError(
            "Invalid column name: %r. Expected one of %s" % (column, sorted(columns))
        )

    if data is None:
        data = []

    # Validate every row before summarising.
    for row in data:
        try:
            length = len(row)
        except TypeError:
            raise ValueError("Each row must have exactly six entries")
        if length != 6:
            raise ValueError(
                "Each row must have exactly six entries, got %d" % length
            )

    index = columns[column]
    values = [row[index] for row in data if row[index] is not None]
    values = [float(v) for v in values]
    values.sort()

    count = len(values)
    if count == 0:
        nan = float('nan')
        return {
            'count': 0,
            'mean': nan,
            'std': nan,
            'min': nan,
            '25%': nan,
            '50%': nan,
            '75%': nan,
            'max': nan,
        }

    mean = sum(values) / count
    if count > 1:
        var = sum((v - mean) ** 2 for v in values) / (count - 1)
        std = math.sqrt(var)
    else:
        std = float('nan')

    return {
        'count': count,
        'mean': mean,
        'std': std,
        'min': values[0],
        '25%': _percentile(values, 0.25),
        '50%': _percentile(values, 0.50),
        '75%': _percentile(values, 0.75),
        'max': values[-1],
    }

