import math
import re


def tfidf_without_urls(texts):
    """Compute L2-normalised TF-IDF scores for words in documents, ignoring URLs.

    Words are lowercased runs of two or more word characters. URLs starting
    with http:// or https:// (up to the next whitespace) are removed before
    tokenisation. IDF is smoothed: ln((1 + n) / (1 + df)) + 1.
    """
    url_re = re.compile(r'https?://\S+')
    word_re = re.compile(r'\w{2,}')

    docs_tokens = [word_re.findall(url_re.sub('', text).lower()) for text in texts]

    # Vocabulary of distinct words (sorted).
    vocab = sorted({w for tokens in docs_tokens for w in tokens})

    if not vocab:
        return ([], [])

    n = len(texts)
    df = {w: sum(1 for tokens in docs_tokens if w in tokens) for w in vocab}
    idf = {w: math.log((1 + n) / (1 + df[w])) + 1 for w in vocab}

    rows = []
    for tokens in docs_tokens:
        counts = {w: 0 for w in vocab}
        for w in tokens:
            counts[w] += 1
        vec = [counts[w] * idf[w] for w in vocab]
        norm = math.sqrt(sum(v * v for v in vec))
        if norm > 0:
            vec = [v / norm for v in vec]
        rows.append(vec)

    return (rows, vocab)

