import math


def _is_number(value):
    """True for real numbers (int/float), excluding booleans."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _pearson(xs, ys):
    """Pearson correlation of two equal-length lists of finite floats.

    Mirrors the classic scaled algorithm (as used by pandas Series.corr):
    center each vector, scale by the max absolute deviation, then compute
    the normalized dot product.  Pairs containing NaN are ignored.
    """
    # Drop pairs where either value is NaN (NaN != NaN).
    xs = [float(v) for v in xs]
    ys = [float(v) for v in ys]
    pairs = [(x, y) for x, y in zip(xs, ys) if x == x and y == y]
    n = len(pairs)
    if n < 2:
        return float('nan')
    xs = [p[0] for p in pairs]
    ys = [p[1] for p in pairs]

    mx = sum(xs) / n
    my = sum(ys) / n
    a = [x - mx for x in xs]
    b = [y - my for y in ys]

    a_scale = max(abs(v) for v in a)
    b_scale = max(abs(v) for v in b)
    if a_scale == 0 or b_scale == 0:
        # A constant (zero-variance) column has undefined correlation.
        return float('nan')

    a = [v / a_scale for v in a]
    b = [v / b_scale for v in b]

    fact = n - 1
    divisor = math.sqrt(sum(v * v for v in a) / fact)
    if divisor == 0:
        return float('nan')
    result = sum(a[i] * b[i] for i in range(n)) / fact / divisor
    divisor = math.sqrt(sum(v * v for v in b) / fact)
    if divisor == 0:
        return float('nan')
    return max(-1.0, min(1.0, result / divisor))


def correlation_without_column(data, column):
    """Compute the Pearson correlation matrix of the numeric columns of `data`,
    excluding `column` if it is present.

    Parameters
    ----------
    data : dict mapping column names to equal-length lists of values
    column : the column name to drop (ignored if not present)

    Returns
    -------
    dict of dicts where result[x][y] is the Pearson correlation between
    columns x and y, or None if no numeric columns remain.
    """
    # Keep only numeric columns, dropping the requested column if present.
    numeric_cols = []
    for name, values in data.items():
        if name == column:
            continue
        if all(_is_number(v) for v in values):
            numeric_cols.append(name)

    if not numeric_cols:
        return None

    # No observations at all -> correlation is undefined.
    if len(data[numeric_cols[0]]) == 0:
        return None

    result = {}
    for x in numeric_cols:
        row = {}
        for y in numeric_cols:
            if x == y:
                row[y] = 1.0
            else:
                row[y] = _pearson(data[x], data[y])
        result[x] = row
    return result

