from collections import Counter

WORD_RE = re.compile(r'\w{2,}')


def tfidf_scores_for_question_articles(titles, contents):
    """Compute summed TF-IDF scores over bodies of articles whose title
    contains "how" or "what" (case-insensitive, substring match)."""
    picked = [c for t, c in zip(titles, contents)
              if 'how' in t.lower() or 'what' in t.lower()]

    if not picked:
        return {}

    # Tokenise each picked article's body.
    docs = [WORD_RE.findall(c.lower()) for c in picked]
    n_docs = len(docs)

    # Document frequency of each word among picked articles.
    df = Counter()
    for doc in docs:
        for word in set(doc):
            df[word] += 1

    # Smoothed idf.
    idf = {w: math.log((1 + n_docs) / (1 + d)) + 1.0 for w, d in df.items()}

    scores = {}
    for doc in docs:
        counts = Counter(doc)
        vec = {w: counts[w] * idf[w] for w in counts}
        norm = math.sqrt(sum(v * v for v in vec.values()))
        if norm == 0:
            continue
        for w, v in vec.items():
            scores[w] = scores.get(w, 0.0) + v / norm

    return scores

