import re


def _tokenize(text):
    """Return case-insensitive runs of two or more letters, digits, or underscores."""
    return [w.lower() for w in re.findall(r'[A-Za-z0-9_]{2,}', text)]


def bag_of_words_vector(text, corpus):
    """Return the bag-of-words count vector of ``text``.

    The vocabulary consists of every distinct word (a case-insensitive run of
    two or more letters, digits, or underscores) appearing in ``text`` or in
    any sentence of ``corpus``, sorted alphabetically.  The returned list gives
    the count of each vocabulary word in ``text``, in vocabulary order.
    """
    text_words = _tokenize(text)
    vocab = set(text_words)
    if corpus is not None:
        for sentence in corpus:
            if isinstance(sentence, str):
                vocab.update(_tokenize(sentence))
            else:
                vocab.update(_tokenize(str(sentence)))
    ordered_vocab = sorted(vocab)
    counts = {}
    for w in text_words:
        counts[w] = counts.get(w, 0) + 1
    return [counts.get(w, 0) for w in ordered_vocab]

