# "January 15, 2020", "Jan. 15 2020", "Jan 15th, 2020", "Jan-15-2020"
_RE_MONTH_FIRST = re.compile(
    r"^([A-Za-z]+)\.?[\s\-/]+(\d{1,2})(?:st|nd|rd|th)?\s*,?\s*(?:[\s\-/]+)?(\d{4})$",
    re.I,
)
# "15 Jan 2020", "15th January, 2020", "15-Jan-2020"
_RE_DAY_FIRST = re.compile(
    r"^(\d{1,2})(?:st|nd|rd|th)?[\s\-/]+([A-Za-z]+)\.?[\s,\-]*(\d{4})$",
    re.I,
)
