_RE_NUMERIC = re.compile(r"^(\d{1,4})([-/.])(\d{1,2})\2(\d{2}|\d{4})$")
# bare digits: "20200115" or "01152020"
_RE_DIGITS = re.compile(r"^(\d{8})$")
