_RE_WEEKDAY_SUFFIX = re.compile(r"[,;]?\s*(?:mon|tues?|wed(?:nes)?|thur?s?|fri|sat(?:ur)?|sun)[a-z]*\.?$",
                                re.I)
# trailing time-of-day component: "2020-01-15 10:30:00" / "2020-01-15T10:30Z"
_RE_TIME = re.compile(
    r"[T ]\d{1,2}:\d{2}(:\d{2})?(\.\d+)?"
    r"(?:\s*(?:am|pm|utc|gmt|z|[+-]\d{2}:?\d{2}|\([A-Za-z]+\)))*\s*$",
    re.I,
)


