    return _MONTHS.get(name.strip(".").lower())


def _year_from_value(value):
    """Normalize a year token that may be 2, 3 or 4 digits wide."""
    year = int(value)
    if len(value) <= 2:
        year += 2000 if year < 70 else 1900
    return year


def _parse_date(text):
    """Parse a date string written in a common format; return a date object.

    Raises ValueError when the text cannot be interpreted as a valid date.
