    if text is None:
        raise ValueError("Missing date value")
    raw = str(text).strip()
    if not raw:
        raise ValueError("Empty date value")

    # Drop a trailing time-of-day component, if present.
    cleaned = _RE_TIME.sub("", raw).strip()
    if not cleaned:
        raise ValueError("Invalid date value: %r" % text)

    # Drop a leading/trailing weekday name, if present ("Mon, 15 Jan 2020").
    cleaned = _RE_WEEKDAY_PREFIX.sub("", cleaned).strip()
    cleaned = _RE_WEEKDAY_SUFFIX.sub("", cleaned).strip()
