        month = _month_from_name(match.group(2))
        if month is None:
            raise ValueError("Invalid date value: %r" % text)
        return datetime.date(_year_from_value(match.group(3)), month, int(match.group(1)))

    # "2020-01-15" / "01/15/2020" / "15.01.2020" styles.
    match = _RE_NUMERIC.match(cleaned)
