        if len(first) == 4:
            year, month, day = first, int(second), int(third)
        elif len(first) <= 2:
            a, b = int(first), int(second)
            if a > 12 and b <= 12:
                # day/month/year, e.g. "25/12/2020"
                day, month, year = a, b, third
            else:
                # month/day/year, e.g. "01/15/2020"
                month, day, year = a, b, third
