"""Self-contained helper: convert an XML string into nested Python dicts.

The conversion rules are:

* The returned mapping contains a single key: the root element's tag,
  mapped to the converted content of the root element.
* An element that only holds text is converted to that text (string).
* An element with no attributes, no children and no text becomes ``None``.
* Any other element becomes a ``dict`` where
    - attributes are stored under their name prefixed with ``'@'``,
    - child elements are stored under their tag,
    - any text of the element is stored under ``'#text'``.
* A tag appearing more than once among the same siblings is converted into
  a list of the values in document order.
"""

import xml.etree.ElementTree as ET

__all__ = ["xml_to_dict", "XMLParseError"]


class XMLParseError(ValueError, ET.ParseError):
    """Raised when the given string cannot be parsed as XML.

    It derives from both :class:`ValueError` and
    :class:`xml.etree.ElementTree.ParseError` so that callers may catch
    either one of them.
    """


def _convert_text(text):
    """Normalise the text of an element (``None`` or whitespace only -> ``None``)."""
    if text is None:
        return None
    stripped = text.strip()
    return stripped if stripped else None


def _convert_element(elem):
    """Convert an :class:`xml.etree.ElementTree.Element` into a dict / str / None."""
    attribs = dict(elem.attrib) if elem.attrib else {}
    children = list(elem)
    text = _convert_text(elem.text)

    if not attribs and not children:
        # Only text (or nothing at all).
        return text

    result = {}
    for name, value in attribs.items():
        result["@" + name] = value

    for child in children:
        value = _convert_element(child)
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if not isinstance(existing, list):
                result[tag] = [existing]
            result[tag].append(value)
        else:
            result[tag] = value

    if text is not None:
        result["#text"] = text

    return result


def xml_to_dict(s):
    """Parse the XML string ``s`` and return it as nested dictionaries.

    >>> xml_to_dict('<book id="123">Python Guide</book>')
    {'book': {'@id': '123', '#text': 'Python Guide'}}
    """
    if isinstance(s, (bytes, bytearray)):
        s = s.decode("utf-8")
    elif not isinstance(s, str):
        raise ValueError("xml_to_dict expects a string, got %r" % type(s).__name__)

    if not s.strip():
        raise ValueError("Input XML string is empty or contains only whitespace")

    try:
        root = ET.fromstring(s)
    except ET.ParseError as exc:
        raise XMLParseError(str(exc)) from None

    return {root.tag: _convert_element(root)}

