def _as_seq(p):
    """Allow scalars as 1-D points for convenience."""
    try:
        iter(p)
        return p
    except TypeError:
        return (p,)


def _dist_sq(a, b):
    a = _as_seq(a)
    b = _as_seq(b)
    s = 0.0
    for x, y in zip(a, b):
        d = float(x) - float(y)
        s += d * d
    return s


def _neighbors(points, i, eps):
    eps_sq = eps * eps
    p = points[i]
    out = []
    for j, q in enumerate(points):
        if _dist_sq(p, q) <= eps_sq:
            out.append(j)
    return out


def dbscan_cluster_labels(points, eps=3, min_samples=2):
    """Cluster `points` with DBSCAN (Euclidean distance, eps=3, min_samples=2,
    a point counting towards its own neighbourhood).

    Returns a list of integer labels, one per point in input order:
    clusters numbered 0, 1, 2, ... in the order they are first found when
    scanning the points in order; noise points get -1.
    """
    n = len(points)
    if n == 0:
        return []

    pts = [_as_seq(p) for p in points]
    neighborhoods = [_neighbors(pts, i, eps) for i in range(n)]
    is_core = [len(nb) >= min_samples for nb in neighborhoods]

    labels = [-1] * n
    visited = [False] * n
    cluster_id = -1

    for i in range(n):
        if visited[i]:
            continue
        visited[i] = True
        if not is_core[i]:
            continue  # may still be claimed later as a border point

        # Start a new cluster at this core point and expand it.
        cluster_id += 1
        labels[i] = cluster_id
        queue = list(neighborhoods[i])
        qi = 0
        while qi < len(queue):
            j = queue[qi]
            qi += 1
            if labels[j] == -1:
                labels[j] = cluster_id
            if not visited[j]:
                visited[j] = True
                if is_core[j]:
                    queue.extend(neighborhoods[j])

    return labels


if __name__ == "__main__":
    print(dbscan_cluster_labels([[1, 2], [2, 2], [2, 3], [8, 7], [8, 8], [25, 80]]))

