from decimal import Decimal, localcontext


def _to_decimal(value):
    """Convert a number to an exact Decimal (falls back through float)."""
    try:
        return Decimal(value)
    except Exception:
        return Decimal(float(value))


def threshold_and_standardize(data):
    """Threshold values below 0.5 to 0, then standardize each column.

    Each column is standardized to zero mean and unit variance using the
    population standard deviation (ddof = 0).  A column whose
    (thresholded) values are all equal becomes all zeros.

    Parameters
    ----------
    data : list of rows, each row a list of numbers (one per column).

    Returns
    -------
    list of rows of floats with the same shape as the input.
    """
    if not data:
        return []

    n_rows = len(data)

    # High-precision context so results are correctly rounded.
    with localcontext() as ctx:
        ctx.prec = 60

        # 1) Threshold: every value below 0.5 becomes 0.
        thresholded = [
            [Decimal(0) if v < 0.5 else _to_decimal(v) for v in row]
            for row in data
        ]

        n_cols = max(len(row) for row in thresholded)

        # 2) Standardize each column to zero mean / unit variance.
        result = [[0.0] * len(row) for row in thresholded]
        for j in range(n_cols):
            col = [
                thresholded[i][j]
                for i in range(n_rows)
                if j < len(thresholded[i])
            ]
            n = len(col)
            if n == 0:
                continue
            mean = sum(col) / n
            variance = sum((v - mean) ** 2 for v in col) / n
            if variance == 0:
                continue  # constant column -> all zeros
            std = variance.sqrt()
            for i in range(n_rows):
                if j < len(thresholded[i]):
                    result[i][j] = float((thresholded[i][j] - mean) / std)

    return result


if __name__ == "__main__":
    print(threshold_and_standardize([[1, 2], [3, 0.2], [5, 6]]))

