"""Extract data records from an HTML table.

Self-contained implementation built on the standard library's
``html.parser`` module -- no third-party dependencies are required.
"""

from html.parser import HTMLParser

try:  # Python 3
    from html import unescape as _html_unescape
except ImportError:  # pragma: no cover - Python 2
    from HTMLParser import HTMLParser as _Py2Parser

    def _html_unescape(text):
        return _Py2Parser().unescape(text)

__all__ = ["html_table_records"]


# Elements that never have any content (and therefore never have a closing tag).
_VOID_ELEMENTS = frozenset([
    "area", "base", "basefont", "bgsound", "br", "col", "command", "embed",
    "frame", "hr", "image", "img", "input", "isindex", "keygen", "link",
    "menuitem", "meta", "nextid", "param", "source", "track", "wbr",
])

# Elements whose raw text content must not be treated as markup.
_RAW_TEXT_ELEMENTS = frozenset(["script", "style", "textarea", "title"])

# Tag names that make sense only inside a table; used to recover from the
# common "forgotten closing tag" case in hand-written HTML.
_TABLE_CELL_TAGS = frozenset(["td", "th"])
_TABLE_ROW_TAGS = frozenset(["tr"])


class _Element(object):
    """A very small DOM-like node."""

    __slots__ = ("tag", "attrs", "children", "parent")

    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag
        self.parent = parent
        self.attrs = {}
        for name, value in attrs or []:
            key = name.lower()
            if key not in self.attrs:  # first occurrence wins
                self.attrs[key] = value if value is not None else ""
        self.children = []

    def append(self, child):
        if isinstance(child, _Element):
            child.parent = self
        self.children.append(child)

    def iter(self):
        """Yield this element and every descendant element in document order."""
        yield self
        for child in self.children:
            if isinstance(child, _Element):
                for node in child.iter():
                    yield node

    def get_text(self):
        """Concatenated, unescaped text of this element (all descendants)."""
        parts = []
        self._collect_text(parts)
        return "".join(parts)

    def _collect_text(self, parts):
        for child in self.children:
            if isinstance(child, _Element):
                if child.tag in _RAW_TEXT_ELEMENTS:
                    continue
                child._collect_text(parts)
            else:
                parts.append(child)


class _TreeBuilder(HTMLParser):
    """Build a tiny element tree from an HTML document."""

    def __init__(self):
        # convert_charrefs=True (the default) decodes entities in text for us.
        HTMLParser.__init__(self, convert_charrefs=True)
        self.root = _Element("[document]")
        self.stack = [self.root]

    # -- helpers ---------------------------------------------------------
    @property
    def _top(self):
        return self.stack[-1]

    # -- HTMLParser API --------------------------------------------------
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        # Recover from omitted end tags for table related elements.
        if tag in _TABLE_ROW_TAGS:
            while self._top is not self.root and self._top.tag in _TABLE_CELL_TAGS | _TABLE_ROW_TAGS:
                self.stack.pop()
        elif tag in _TABLE_CELL_TAGS:
            while self._top is not self.root and self._top.tag in _TABLE_CELL_TAGS:
                self.stack.pop()

        element = _Element(tag, attrs)
        self._top.append(element)
        if tag not in _VOID_ELEMENTS:
            self.stack.append(element)

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        if tag in _VOID_ELEMENTS:
            self.handle_starttag(tag, attrs)
        else:
            self.handle_starttag(tag, attrs)
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in _VOID_ELEMENTS:
            return
        for index in range(len(self.stack) - 1, 0, -1):
            if self.stack[index].tag == tag:
                del self.stack[index:]
                return
        # Stray end tag: ignore it.

    def handle_data(self, data):
        if data:
            self._top.append(data)

    def handle_entityref(self, name):  # pragma: no cover - convert_charrefs
        self._top.append(_unescape("&%s;" % name))

    def handle_charref(self, name):  # pragma: no cover - convert_charrefs
        self._top.append(_unescape("&#%s;" % name))

    def close(self):
        HTMLParser.close(self)
        self.stack = [self.root]


def _unescape(text):
    """Decode HTML entities in ``text``."""
    return _html_unescape(text)


def _clean_text(text):
    """Decode entities and strip surrounding whitespace."""
    if text is None:
        return ""
    return _unescape(text).strip()


def _find_elements(element, tag):
    """All descendant elements with the given tag name, in document order."""
    found = []
    for node in element.iter():
        if node is not element and node.tag == tag:
            found.append(node)
    return found


def _find_table(root, table_id):
    """Locate the ``<table>`` whose id attribute equals ``table_id``."""
    for node in root.iter():
        if node is root:
            continue
        if node.tag == "table" and node.attrs.get("id") == table_id:
            return node
    return None


def _owns(ancestor, node):
    """True when ``ancestor`` is the nearest enclosing table of ``node``.

    ``ancestor`` may be any element; the check is whether walking up the
    ancestor chain from ``node`` reaches ``ancestor`` before hitting any
    ``<table>`` element.  This keeps nested tables out of the parent table's
    rows and cells.
    """
    current = node.parent
    while current is not None:
        if current is ancestor:
            return True
        if current.tag == "table":
            return False
        current = current.parent
    return False


def _table_rows(table):
    """All ``<tr>`` elements of ``table`` in document order."""
    return [tr for tr in _find_elements(table, "tr") if _owns(table, tr)]


def _cells(row):
    """The ``<td>``/``<th>`` elements of ``row`` in document order."""
    cells = []
    for node in row.iter():
        if node is row:
            continue
        if node.tag in _TABLE_CELL_TAGS and _owns(row, node):
            cells.append(node)
    return cells


def html_table_records(html, table_id):
    """Return a list of dicts -- one per data row of the table ``table_id``.

    The table's first row is assumed to hold the column headers; every
    following row becomes a dict mapping each header to that row's cell text
    (tags removed, entities decoded, surrounding whitespace stripped).

    An empty list is returned when the table has no rows, and a
    ``ValueError`` is raised when no table with that id exists.
    """
    if html is None:
        html = ""
    if not isinstance(html, str):
        try:
            html = html.decode("utf-8", "replace")
        except AttributeError:
            html = str(html)

    parser = _TreeBuilder()
    try:
        parser.feed(html)
        parser.close()
    except Exception:
        # Be forgiving about pathological input; use whatever was built.
        pass

    root = parser.root
    table = _find_table(root, table_id) if table_id is not None else None
    if table is None:
        raise ValueError("No table with id %r" % (table_id,))

    rows = _table_rows(table)
    if not rows:
        return []

    headers = [_clean_text(cell.get_text()) for cell in _cells(rows[0])]

    records = []
    for row in rows[1:]:
        cells = _cells(row)
        record = {}
        for index, header in enumerate(headers):
            if index >= len(cells):
