"""Compute summary statistics (mean, median, population std dev) for a CSV column."""

import csv
import io
import math


def _to_number(value):
    """Return the numeric value of ``value`` as a float, or None if not numeric."""
    if value is None:
        return None
    text = value.strip()
    if not text:
        return None
    try:
        number = float(text)
    except (TypeError, ValueError):
        return None
    if math.isnan(number) or math.isinf(number):
        return None
    return number


def column_summary_stats(csv_text, column_name):
    """Return {'mean', 'median', 'std_dev'} for the named CSV column.

    The statistics are computed over the column's numeric values (rows whose
    value cannot be interpreted as a number are ignored).  A ValueError is
    raised if the column is not present in the header row.
    """
    if csv_text is None:
        csv_text = ''
    if isinstance(csv_text, bytes):
        csv_text = csv_text.decode('utf-8', 'replace')

    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('CSV has no header row')

    if column_name not in header:
        # Fall back to a whitespace-insensitive match, e.g. ' Sales ' vs 'Sales'.
        stripped = [name.strip() for name in header]
        if column_name is not None and column_name.strip() in stripped:
            index = stripped.index(column_name.strip())
        else:
            raise ValueError('Column not found in header: %r' % (column_name,))
    else:
        index = header.index(column_name)

    values = []
    for row in reader:
        if row is None or len(row) <= index:
            continue
        number = _to_number(row[index])
        if number is not None:
            values.append(number)

    count = len(values)
    if count == 0:
        raise ValueError('No numeric values in column %r' % (column_name,))

    mean = sum(values) / count

    ordered = sorted(values)
    middle = count // 2
    if count % 2 == 1:
        median = float(ordered[middle])
    else:
        median = (ordered[middle - 1] + ordered[middle]) / 2.0

    variance = sum((v - mean) ** 2 for v in values) / count
    std_dev = math.sqrt(variance)

    return {'mean': float(mean), 'median': float(median),
            'std_dev': float(std_dev)}

