"""Pairwise Pearson correlation matrix for mapped column data."""


def _pearson(xs, ys):
    """Pearson correlation between two equal-length numeric sequences."""
    n = len(xs)
    if n == 0:
        return float('nan')
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    dx = [x - mean_x for x in xs]
    dy = [y - mean_y for y in ys]
    num = sum(a * b for a, b in zip(dx, dy))
    den_x = sum(a * a for a in dx)
    den_y = sum(b * b for b in dy)
    if den_x == 0 or den_y == 0:
        # A constant column has no defined correlation with anything.
        return float('nan')
    return num / ((den_x * den_y) ** 0.5)


def _to_number(value):
    """Coerce a (already mapped) value to a float if possible."""
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            raise ValueError("non-numeric value after mapping: %r" % (value,))
    if isinstance(value, complex):
        return float(value.real)
    raise ValueError("non-numeric value after mapping: %r" % (value,))


def mapped_correlation_matrix(data, mapping):
    """Return the pairwise Pearson correlation matrix of ``data``'s columns.

    ``data`` maps column names to equal-length lists of values.  Before the
    correlation is computed, every value that appears as a key in ``mapping``
    is replaced by the corresponding value; other values are used unchanged.

    The result is a nested dict: ``result[a][b]`` is the correlation between
    columns ``a`` and ``b``.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")

    if mapping is None:
        mapping = {}
    if not isinstance(mapping, dict):
        mapping = dict(mapping)

    # Replace mapped values and coerce everything to numbers.
    columns = {}
    for name, values in data.items():
        cols = []
        for value in values:
            try:
                if value in mapping:
                    value = mapping[value]
            except TypeError:
                # unhashable values can never be mapping keys
                pass
            cols.append(_to_number(value))
        columns[name] = cols

    lengths = {len(v) for v in columns.values()}
    if lengths and len(lengths) > 1:
        raise ValueError("all columns must have the same length")

    result = {}
    for outer, outer_values in columns.items():
        row = {}
        for inner, inner_values in columns.items():
            if outer == inner:
                # A column is perfectly correlated with itself (unless it is
                # constant, in which case the correlation is undefined).
                if len(outer_values) == 0:
                    row[inner] = float('nan')
                elif len(set(outer_values)) == 1:
                    row[inner] = float('nan')
                else:
                    row[inner] = 1.0
            else:
                row[inner] = _pearson(outer_values, inner_values)
        result[outer] = row
    return result

