import csv
import io
import math


def _parse_number(text):
    """Return a float for `text` if it represents a (finite) number, else None."""
    if text is None:
        return None
    if isinstance(text, float):
        return text if math.isfinite(text) else None
    text = str(text).strip()
    if not text:
        return None
    # Reject things like "1_000" (accepted by float in some cases) only
    # implicitly: float() is used as the arbiter of what is numeric.
    try:
        value = float(text)
    except (TypeError, ValueError):
        return None
    # Normalise the odd spellings of infinity / not-a-number.
    if math.isnan(value) or math.isinf(value):
        return None
    return value


def csv_mean_median(csv_text):
    """Return ``(mean, median)`` of the numeric values in a single-column CSV.

    The first row of the CSV is a header row and is not treated as data.
    Blank lines and values that are not numbers are ignored.  If there are no
    numeric values (including when the text is empty) ``(None, None)`` is
    returned.
    """
    if csv_text is None:
        return (None, None)
    if not isinstance(csv_text, str):
        # Be tolerant of bytes / other text-like inputs.
        try:
            csv_text = csv_text.decode("utf-8")
        except AttributeError:
            csv_text = str(csv_text)
        except UnicodeDecodeError:
            return (None, None)

    if not csv_text.strip():
        return (None, None)

    values = []
    try:
        reader = csv.reader(io.StringIO(csv_text))
    except Exception:
        return (None, None)

    first = True
    try:
        for row in reader:
            if not row:
                # Blank line.
                continue
            cells = [cell for cell in row if cell is not None and cell.strip() != ""]
            if not cells:
                continue
            numbers = [_parse_number(cell) for cell in cells]
            numbers = [n for n in numbers if n is not None]
            if first:
                first = False
                if numbers:
                    # The "header" looks numeric -- treat it as data.
                    values.extend(numbers)
                continue
            values.extend(numbers)
    except Exception:
        # Malformed CSV should not blow up; work with what we collected.
        pass

    if not values:
        return (None, None)

    mean = sum(values) / len(values)
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    if n % 2 == 1:
        median = float(ordered[mid])
    else:
        median = (ordered[mid - 1] + ordered[mid]) / 2.0

