import csv
import io
import re

STOPWORDS = {"a", "an", "the", "in", "on", "at", "and", "or"}
WORD_RE = re.compile(r"[A-Za-z0-9_]{2,}")


def top_ten_words_from_csv(csv_text):
    """Count words in the first column of a CSV (skipping the header row).

    Words are runs of 2+ letters/digits/underscores, compared case-insensitively.
    Stopwords are ignored. Returns up to 10 (word, count) tuples, sorted by
    descending count with ties broken alphabetically.
    """
    counts = {}
    reader = csv.reader(io.StringIO(csv_text))
    for i, row in enumerate(reader):
        if i == 0 or not row:
            continue
        for word in WORD_RE.findall(row[0]):
            word = word.lower()
            if word in STOPWORDS:
                continue
            counts[word] = counts.get(word, 0) + 1

    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ranked[:10]

