    """Return the list of dicts found as literals in <script> bodies.

    Scripts whose content is not a valid Python dict literal are skipped.
    The dicts are returned in document order; the result is [] if none are
    found.
    """
    if not isinstance(html, str):
        return []

    parser = _ScriptCollector()
    try:
        parser.feed(html)
        parser.close()
    except Exception:
        pass

    results = []
    for body in parser.scripts:
        parsed = _parse_dict_literal(body)
        if parsed is not None:
            results.append(parsed)
    return results

