"""Pair forecast sales figures with a schedule of consecutive dates."""

from datetime import date, datetime, timedelta

_WEEKDAYS = {
    'MON': 0,
    'TUE': 1,
    'WED': 2,
    'THU': 3,
    'FRI': 4,
    'SAT': 5,
    'SUN': 6,
}

_MONTH_END_ALIASES = ('MONTH-END', 'MONTEND', 'ME', 'M')
_QUARTER_END_ALIASES = ('QUARTER-END', 'QUARTEREND', 'QE', 'Q')


def _parse_start_date(start_date):
    """Return a datetime.date for ``start_date`` or raise ValueError."""
    if isinstance(start_date, datetime):
        return start_date.date()
    if isinstance(start_date, date):
        return start_date
    if not isinstance(start_date, str):
        raise ValueError("invalid start date: %r" % (start_date,))
    try:
        return datetime.strptime(start_date.strip(), '%Y-%m-%d').date()
    except ValueError:
        raise ValueError("invalid start date: %r" % (start_date,))


def _month_end(year, month):
    """Last day of the given month."""
    if month == 12:
        return date(year + 1, 1, 1) - timedelta(days=1)
    return date(year, month + 1, 1) - timedelta(days=1)


def _nth_weekday(year, month, week, weekday):
    """Date of the ``week``-th ``weekday`` of the given month."""
    first = date(year, month, 1)
    offset = (weekday - first.weekday()) % 7
    return first + timedelta(days=offset + 7 * (week - 1))


def _next_month(year, month):
    """(year, month) one month after the given (year, month)."""
    if month == 12:
        return year + 1, 1
    return year, month + 1


def _parse_freq(freq):
    """Return a callable giving the matching date for (year, month).

    Raises ValueError for an unsupported frequency specification.
    """
    if not isinstance(freq, str):
        raise ValueError("invalid frequency: %r" % (freq,))
    key = freq.strip().upper()

    if key in _MONTH_END_ALIASES:
        return _month_end

    if key in _QUARTER_END_ALIASES:
        def quarter_end(year, month):
            # Months ending a quarter: March, June, September, December.
            return _month_end(year, 3 * ((month - 1) // 3) + 3)
        return quarter_end

    parts = key.split('-')
    if len(parts) == 2 and parts[1] in _WEEKDAYS:
        try:
            week = int(parts[0])
        except ValueError:
            raise ValueError("invalid frequency: %r" % (freq,))
        if not 1 <= week <= 4:
            raise ValueError("invalid frequency: %r" % (freq,))
        weekday = _WEEKDAYS[parts[1]]
        return lambda year, month: _nth_weekday(year, month, week, weekday)

    raise ValueError("invalid frequency: %r" % (freq,))


def _schedule_dates(start, freq, count):
    """Generate ``count`` strictly increasing matching dates >= ``start``."""
    matcher = _parse_freq(freq)

    dates = []
    year, month = start.year, start.month
    # Generous bound on the number of months to scan.
    limit = 12 * count + 24
    while len(dates) < count and limit > 0:
        candidate = matcher(year, month)
        if candidate >= start and (not dates or candidate > dates[-1]):
            dates.append(candidate)
        year, month = _next_month(year, month)
        limit -= 1

    if len(dates) < count:
        raise ValueError("could not build a schedule for %r" % (freq,))
    return dates


def forecast_schedule(start_date, freq, sales):
    """Pair each sales figure with the next matching date.

    Parameters
    ----------
    start_date : str
        Start date in 'YYYY-MM-DD' format.
    freq : str
        'month-end', 'quarter-end' or a code such as '2-FRI' (the second
        Friday of each month; week 1 to 4, weekday MON to SUN).
    sales : sequence
        Sales figures; one date is produced per figure.

    Returns
    -------
    list
        List of (date string 'YYYY-MM-DD', sales) tuples in order.
    """
    start = _parse_start_date(start_date)
    figures = list(sales)
    if not figures:
        return []
    dates = _schedule_dates(start, freq, len(figures))
    return [(d.isoformat(), value) for d, value in zip(dates, figures)]

