import csv
import io


def _to_number(text):
    """Convert a sales value to int when possible, otherwise float."""
    try:
        value = float(text)
    except (TypeError, ValueError):
        return 0
    if value == int(value):
        return int(value)
    return value


def sales_report(csv_text):
    """Build a sales report from CSV text.

    Parameters
    ----------
    csv_text : str
        CSV text with a header row that must contain the columns
        'Customer', 'Category' and 'Sales'.  Additional columns may be
        present, in any order.

    Returns
    -------
    dict
        {'Total Sales': sum of Sales over the first row of each customer,
         'Most Popular Category': most frequent category among those rows,
                                   ties broken alphabetically}

    Raises
    ------
    ValueError
        If ``csv_text`` is not a string.
    """
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.DictReader(io.StringIO(csv_text))

    seen = set()
    total = 0
    categories = {}

    for row in reader:
        if not row:
            continue

        # Normalise keys so stray whitespace in the header is harmless.
        row = {
            (key.strip() if isinstance(key, str) else key): value
            for key, value in row.items()
        }

        customer = row.get("Customer")
        if isinstance(customer, str):
            customer = customer.strip()

        if customer in seen:
            continue
        seen.add(customer)

        category = row.get("Category")
        if isinstance(category, str):
            category = category.strip()

        sales = row.get("Sales")
        if isinstance(sales, str):
            sales = sales.strip()

        if sales:
            total += _to_number(sales)

        if category:
            categories[category] = categories.get(category, 0) + 1

    most_popular = None
    if categories:
        # Highest count first, then alphabetically first on a tie.
        most_popular = sorted(categories.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]

    return {
        "Total Sales": total,
        "Most Popular Category": most_popular,
    }

