def fit_age_score_regression(records):
    """Fit an ordinary least-squares line predicting Score from Age.

    Keeps only the first record for each distinct name, then computes the
    OLS regression line Score = slope * Age + intercept and the Pearson
    correlation coefficient r between Age and Score.

    Returns a tuple (slope, intercept, r).
    """
    # Keep only the first record for each name.
    seen = set()
    rows = []
    for rec in records:
        name = rec.get('Name')
        if name in seen:
            continue
        seen.add(name)
        rows.append((float(rec['Age']), float(rec['Score'])))

    n = len(rows)
    if n == 0:
        return (0.0, 0.0, 0.0)
    if n == 1:
        # Only one point: line passes through it with zero slope.
        return (0.0, rows[0][1], 0.0)

    xs = [x for x, _ in rows]
    ys = [y for _, y in rows]

    mean_x = sum(xs) / n
    mean_y = sum(ys) / n

    sxx = sum((x - mean_x) ** 2 for x in xs)
    syy = sum((y - mean_y) ** 2 for y in ys)
    sxy = sum((x - mean_x) * (y - mean_y) for x, y in rows)

    if sxx == 0.0:
        # All ages identical: slope undefined; use zero slope through mean.
        return (0.0, mean_y, 0.0)

    slope = sxy / sxx
    intercept = mean_y - slope * mean_x

    if syy == 0.0:
        # Score is constant: correlation undefined; treat as zero.
        r = 0.0
    else:
        denom = (sxx * syy) ** 0.5
        r = sxy / denom if denom else 0.0
        # Guard against tiny floating point overshoot.
        if r > 1.0:
            r = 1.0
        elif r < -1.0:
            r = -1.0

    return (slope, intercept, r)

