    """Return True if *value* is a real number (int, float, Decimal, ...)."""
    # ``bool`` is a subclass of ``int`` but is not a numeric value here.
    if isinstance(value, bool):
        return False
    if _Decimal is not None and isinstance(value, _Decimal):
        return True
    return isinstance(value, Real)


