    """Return *values* as a list, or raise a TypeError if impossible."""
    if isinstance(values, (str, bytes, bytearray)):
        raise TypeError("column %r is not a list of numbers" % (name,))
    if not hasattr(values, "__len__") or not hasattr(values, "__iter__"):
        raise TypeError("column %r is not a list of numbers" % (name,))
    return list(values)


