import csv
import io
from datetime import datetime, date


def _parse_date(value, date_format):
    """Parse a string into a datetime.date, or return None if it can't be parsed."""
    if value is None:
        return None
    value = value.strip()
    if not value:
        return None
    try:
        parsed = datetime.strptime(value, date_format)
    except (ValueError, TypeError):
        return None
    return parsed.date()


def upcoming_rows(csv_text, column_name, today, date_format="%Y-%m-%d"):
    """Return the rows of ``csv_text`` whose date in ``column_name`` is >= ``today``.

    Args:
        csv_text: CSV text including a header row.
        column_name: Name of the column holding the date to compare.
        today: A 'YYYY-MM-DD' string marking the boundary (inclusive).
        date_format: The strptime format used to parse the date column.

    Returns:
        A list of dicts (one per matching row) mapping each column name to the
        row's original string value, sorted by date. Ties keep their original
        relative order.

    Raises:
        ValueError: If the column does not exist or ``today`` is not a valid date.
    """
    if csv_text is None:
        return []

    if isinstance(csv_text, bytes):
        csv_text = csv_text.decode("utf-8")

    if not csv_text.strip():
        return []

    text = csv_text.lstrip("\ufeff")
    reader = csv.DictReader(io.StringIO(text))
    fieldnames = reader.fieldnames or []

    if column_name not in fieldnames:
        raise ValueError("Column not found: {!r}".format(column_name))

    if isinstance(today, str):
        today_value = _parse_date(today, "%Y-%m-%d")
        if today_value is None:
            raise ValueError("Invalid 'today' value: {!r}".format(today))
    elif isinstance(today, (datetime, date)):
        today_value = today.date() if isinstance(today, datetime) else today
    else:
        raise ValueError("Invalid 'today' value: {!r}".format(today))

    upcoming = []
    for row in reader:
        if row is None:
            continue
        row_date = _parse_date(row.get(column_name), date_format)
        if row_date is None or row_date < today_value:
            continue
        clean = {}
        for key, value in row.items():
            if key is None:
                continue
            clean[key] = "" if value is None else value
        upcoming.append((row_date, len(upcoming), clean))

    upcoming.sort(key=lambda item: (item[0], item[1]))

    return [row for _, _, row in upcoming]

