import csv
import io


def _to_number(value):
    """Return ``value`` converted to int or float, or None if not numeric."""
    text = value.strip() if isinstance(value, str) else value
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        pass
    try:
        number = float(text)
    except ValueError:
        return None
    # Reject infinities and NaNs: they do not order sensibly and treating
    # them as "numeric" would produce surprising sorts.
    if number != number or number in (float("inf"), float("-inf")):
        return None
    return number


def sort_csv_rows(csv_text, sort_key):
    """Return the data rows of ``csv_text`` sorted by the ``sort_key`` column.

    Each data row is returned as a dict mapping column names to values.
    Columns whose values are all numeric hold numbers (so they sort
    numerically); all other columns keep their string values.  Rows with
    equal keys keep their original relative order (the sort is stable).

    A ``ValueError`` is raised when ``sort_key`` does not name a column of
    the given CSV document.
    """
    if csv_text is None:
        csv_text = ""
    if not isinstance(csv_text, str):
        csv_text = str(csv_text)
    if csv_text.startswith("\ufeff"):  # strip a UTF-8 byte order mark
        csv_text = csv_text[1:]

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = [str(name) for name in next(reader)]
    except StopIteration:
        header = []

    # Locate the requested column (tolerating whitespace padding).
    if isinstance(sort_key, str):
        wanted = sort_key.strip()
    else:
        wanted = sort_key
    key_index = None
    for index, name in enumerate(header):
        if name == sort_key or (isinstance(sort_key, str) and name.strip() == wanted):
            key_index = index
            break
    if key_index is None:
        raise ValueError("Unknown column: %r" % (sort_key,))

    # Read the data rows, skipping blank lines.
    rows = []
    for record in reader:
        if not record or all(field == "" for field in record):
            continue
        if len(record) < len(header):  # pad short rows
            record = list(record) + [""] * (len(header) - len(record))
        rows.append(record)

    # A column is numeric when every non-empty value in it is a number.
    numeric_columns = set()
    for index in range(len(header)):
        is_numeric = False
        for record in rows:
            value = record[index]
            if str(value).strip() == "":
                continue
            if _to_number(value) is None:
                is_numeric = False
                break
            is_numeric = True
        if is_numeric:
            numeric_columns.add(index)

    # Build one dict per data row, converting numeric columns to numbers.
    result = []
    for record in rows:
        row = {}
        for index, name in enumerate(header):
            value = record[index]
            if index in numeric_columns and str(value).strip() != "":
                value = _to_number(value)
            row[name] = value
        result.append(row)

    # Stable sort on the requested column.  Numbers (int/float) compare
    # together, strings compare together, and numbers sort before strings
    # so that mixed columns (e.g. blanks in an otherwise numeric column)
    # never raise a TypeError.
    def _sort_key(row):
        value = row[header[key_index]]
        if isinstance(value, bool):
            return (0, float(value))
        if isinstance(value, (int, float)):
            return (0, value)
        return (1, str(value))

    result.sort(key=_sort_key)
    return result

