"""Utilities for computing per-row statistics from CSV text."""

import ast
import csv
import io
import json
import statistics


def _parse_list(text):
    """Parse a Python-style (or JSON-style) list of numbers from a string."""
    if text is None:
        return []
    if isinstance(text, (list, tuple)):
        return list(text)
    text = text.strip()
    if not text:
        return []
    # Strip a matching pair of surrounding quotes left over from the CSV cell.
    if len(text) >= 2 and text[0] == text[-1] and text[0] in ('\"', "'"):
        text = text[1:-1].strip()
    try:
        value = ast.literal_eval(text)
    except (ValueError, SyntaxError, TypeError):
        try:
            value = json.loads(text)
        except (ValueError, SyntaxError, TypeError):
            raise ValueError("Could not parse list value: %r" % (text,))
    if isinstance(value, (list, tuple)):
        return list(value)
    raise ValueError("Expected a list of numbers, got: %r" % (text,))


def list_stats_by_email(csv_text):
    """Compute per-row statistics for a CSV with 'email' and 'list' columns.

    Each 'list' cell contains a Python-style list of numbers written as a
    string (e.g. ``"[12, 17, 29]"``).  For every data row a dict is returned
    with the keys 'email', 'list', 'sum', 'mean' and 'median'.  A file with
    only a header yields an empty list.
    """
    if csv_text is None:
        return []

    reader = csv.DictReader(io.StringIO(csv_text))
    rows = []
    for row in reader:
        if not isinstance(row, dict):
            continue
        email = row.get('email')
        if email is None:
            email = ''
        raw_list = row.get('list')
        # Handle unquoted list values, which csv splits over extra columns.
        if isinstance(raw_list, list):
            raw_list = raw_list[0] if raw_list else None
        extras = row.get(None)
        if extras:
            raw_list = raw_list if raw_list is not None else ''
            raw_list = ','.join([str(raw_list)] + [str(e) for e in extras])
        numbers = _parse_list(raw_list)
        numbers = [v for v in numbers
                   if isinstance(v, (int, float)) and not isinstance(v, bool)]
        if numbers:
            total = sum(numbers)
            mean = total / len(numbers)
            median = float(statistics.median(numbers))
        else:
            total = 0
            mean = 0.0
            median = 0.0
        rows.append({
            'email': email,
            'list': numbers,
            'sum': total,
            'mean': mean,
            'median': median,
        })
    return rows

