import math
import re


def tfidf_matrix(documents):
    """Compute TF-IDF scores for a list of documents.

    Words are maximal runs of letters and digits, lowercased.
    TF is the raw term count. IDF is the smoothed
    ln((1 + n) / (1 + df)) + 1. Each document vector is
    scaled to unit Euclidean length.

    Returns (words, rows) where words is the sorted vocabulary
    and rows[i][j] is the score of word j in document i.
    """
    # Tokenize documents into lowercase words.
    tokenized = []
    for doc in documents:
        tokens = [t.lower() for t in re.findall(r'[A-Za-z0-9]+', doc)]
        tokenized.append(tokens)

    n = len(documents)

    # Document frequency for each word.
    df = {}
    for tokens in tokenized:
        for word in set(tokens):
            df[word] = df.get(word, 0) + 1

    words = sorted(df)
    idf = {
        word: math.log((1.0 + n) / (1.0 + df[word])) + 1.0
        for word in words
    }

    rows = []
    for tokens in tokenized:
        counts = {}
        for t in tokens:
            counts[t] = counts.get(t, 0) + 1
        vec = [counts.get(word, 0) * idf[word] for word in words]
        norm = math.sqrt(sum(v * v for v in vec))
        if norm > 0:
            vec = [v / norm for v in vec]
        else:
            vec = [0.0 for _ in vec]
        rows.append(vec)

    return words, rows

