    rows = list(reader)
    if not rows or len(rows[0]) == 0:
        header = []
    else:
        header = rows[0]

    # Validate requested columns before doing any work.
    for col in columns:
        if col not in header:
            raise KeyError("Column not found in file: {!r}".format(col))

    values = {name: [] for name in header}
    for row in rows[1:]:
        # Skip a completely empty trailing line.
        if not row or (len(row) == 1 and row[0] == ""):
            continue
        for i, name in enumerate(header):
            raw = row[i] if i < len(row) else ""
            try:
