def complete_row_histogram(data, bins):
    """
    Drop every row (index position) that contains a None in any column.

    Parameters
    ----------
    data : dict mapping column names to equal-length lists of numbers
        Some entries may be None (missing).
    bins : int
        Number of equal-width histogram bins spanning the pooled
        minimum to the pooled maximum of the remaining values.

    Returns
    -------
    (cleaned, counts) : tuple
        cleaned : dict mapping each column name to the list of its
                  remaining values (as floats), in their original order.
        counts  : list of `bins` integer bin counts for all remaining
                  values pooled together, or None if no rows remain,
                  all remaining values are equal, or `bins` is not a
                  positive integer.
    """
    if not data:
        return ({}, None)

    columns = list(data.keys())
    lists = [list(data[c]) for c in columns]

    # Determine the number of rows (all lists are assumed equal length).
    n_rows = len(lists[0]) if lists else 0

    # Keep only rows with no None in any column.
    kept_indices = []
    for i in range(n_rows):
        if all(lst[i] is not None for lst in lists):
            kept_indices.append(i)

    cleaned = {
        c: [float(lst[i]) for i in kept_indices]
        for c, lst in zip(columns, lists)
    }

    pooled = [v for lst in lists for i in kept_indices for v in [float(lst[i])]]

    if not pooled:
        return (cleaned, None)

    lo = min(pooled)
    hi = max(pooled)

    # All values equal (or effectively so) -> cannot build meaningful bins.
    if hi == lo:
        return (cleaned, None)

    try:
        bins = int(bins)
    except (TypeError, ValueError):
        return (cleaned, None)
    if bins < 1:
        return (cleaned, None)

    width = (hi - lo) / bins
    counts = [0] * bins
    for v in pooled:
        idx = int((v - lo) / width)
        if idx >= bins:  # value == hi goes into the last bin
            idx = bins - 1
        if idx < 0:  # safety, shouldn't happen
            idx = 0
        counts[idx] += 1

    return (cleaned, counts)

