import csv
import io


def correlation_matrix_from_csv(csv_text):
    """Return the pairwise Pearson correlation matrix of the CSV's columns.

    ``csv_text`` is the text of a CSV file whose first line is a header and
    whose columns are all numeric.  The result is a dict of dicts:
    ``result[a][b]`` is the Pearson correlation between column ``a`` and
    column ``b``, for every pair of column names.
    """
    if isinstance(csv_text, bytes):
        csv_text = csv_text.decode("utf-8")

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row and any(cell.strip() != "" for cell in row)]
    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    data_rows = rows[1:]

    # Parse the numeric data into per-column lists.
    columns = {name: [] for name in header}
    for row in data_rows:
        for i, name in enumerate(header):
            value = row[i].strip() if i < len(row) else ""
            columns[name].append(float(value) if value != "" else 0.0)

    n_rows = len(data_rows)

    def mean(values):
        return sum(values) / len(values) if values else 0.0

    def correlation(xs, ys):
        mx = mean(xs)
        my = mean(ys)
        dx = [x - mx for x in xs]
        dy = [y - my for y in ys]
        numerator = sum(a * b for a, b in zip(dx, dy))
        sx = sum(a * a for a in dx)
        sy = sum(b * b for b in dy)
        if sx == 0.0 or sy == 0.0:
            # A column with zero variance has no well-defined correlation.
            return 1.0 if sx == sy else 0.0
        # Computed as covariance / std(x) / std(y) (population estimates).
        return (numerator / len(xs)) / ((sx / len(xs)) ** 0.5) / ((sy / len(ys)) ** 0.5)

    result = {}
    for a in header:
        row = {}
        for b in header:
            if a == b:
                row[b] = 1.0
            elif n_rows == 0:
                row[b] = 0.0
            else:
                row[b] = correlation(columns[a], columns[b])
        result[a] = row
    return result

