def last_column_skewness(rows):
    """Return the (biased) Fisher-Pearson skewness of the table's last column.

    ``rows`` is a list of rows, each row a list of numbers where ``None``
    marks a missing value.  Missing values are ignored when computing the
    skewness of the last column.

    Raises a ValueError if the table has no rows or no columns.
    """
    if rows is None:
        raise ValueError("table has no rows")
    rows = list(rows)
    if not rows:
        raise ValueError("table has no rows")
    if all(len(row) == 0 for row in rows if isinstance(row, (list, tuple))):
        raise ValueError("table has no columns")

    values = []
    for row in rows:
        if not isinstance(row, (list, tuple)):
            row = list(row)
        if len(row) == 0:
            continue
        value = row[-1]
        if value is None:
            continue
        if isinstance(value, bool):
            value = int(value)
        values.append(float(value))

    n = len(values)
    if n == 0:
        raise ValueError("no values in the last column")
    mean = sum(values) / n
    m2 = sum((x - mean) ** 2 for x in values) / n
    if m2 <= 0:
        return 0.0
    m3 = sum((x - mean) ** 3 for x in values) / n
    return float(m3 / (m2 ** 1.5))

