        if not isinstance(row, (list, tuple)):
            row = list(row)
        if len(row) == 0:
            continue
        value = row[-1]
        if value is None:
            continue
        if isinstance(value, bool):
            value = int(value)
        values.append(float(value))

    n = len(values)
    if n == 0:
        raise ValueError("no values in the last column")
    mean = sum(values) / n
    m2 = sum((x - mean) ** 2 for x in values) / n
    if m2 <= 0:
        return 0.0
    m3 = sum((x - mean) ** 3 for x in values) / n
    return float(m3 / (m2 ** 1.5))

