def standardize_columns(rows, scale_cols):
    """Return a new table where each column in scale_cols is replaced by its z-score.

    Z-score = (value - column mean) / population standard deviation.
    Columns with zero variation become all zeros. Other columns are unchanged.
    """
    n = len(rows)
    if n == 0:
        return []
    result = [list(row) for row in rows]
    for col in scale_cols:
        values = [row[col] for row in rows]
        mean = sum(values) / len(values)
        var = sum((v - mean) ** 2 for v in values) / len(values)
        std = var ** 0.5
        if std == 0:
            new_vals = [0.0 for _ in values]
        else:
            new_vals = [(v - mean) / std for v in values]
        for i, nv in enumerate(new_vals):
            result[i][col] = nv
    return result

