from html.parser import HTMLParser

class _TableParser(HTMLParser):
    """Collect the headers and data rows of the first <table> in a document."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found_table = False      # saw the first <table> start tag
        self.in_table = 0            # nesting depth inside the first table
        self.done = False             # finished with the first table
        self.headers = []             # stripped text of every <th>
        self.rows = []                # rows (lists of stripped <td> text)
        # per-cell state
        self._in_header_cell = 0      # >0 while inside a <th>
        self._in_data_cell = 0        # >0 while inside a <td>
        self._buffer = []             # text pieces of the current cell
        self._current_row = None      # cells of the row being built
        self._row_has_td = False

    # -- helpers ---------------------------------------------------------
    def _flush_cell(self):
        text = "".join(self._buffer).strip()
        self._buffer = []
        if self._in_header_cell and not self._in_data_cell:
            self.headers.append(text)
        elif self._in_data_cell:
            if self._current_row is not None:
                self._current_row.append(text)
            self._row_has_td = True
        self._in_header_cell = 0
        self._in_data_cell = 0

    def _start_row(self):
        self._current_row = []
        self._row_has_td = False

    def _end_row(self):
        if self._current_row is not None and self._row_has_td:
            self.rows.append(self._current_row)
        self._current_row = None

    # -- parser callbacks -------------------------------------------------
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == "table":
            if not self.found_table:
                self.found_table = True
                self.in_table = 1
                self._start_row()
            elif self.in_table:
                self.in_table += 1
            return
        if not self.in_table:
            return
        if self.in_table > 1:
            # Inside a nested table: keep its text as part of the enclosing
            # cell rather than treating it as separate rows/headers.
            return

        if tag == "tr":
            self._flush_cell()
            self._end_row()
            self._start_row()
        elif tag == "th":
            self._flush_cell()
            if self._current_row is None:
                self._start_row()
            self._in_header_cell += 1
        elif tag == "td":
            self._flush_cell()
            if self._current_row is None:
                self._start_row()
            self._in_data_cell += 1

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == "table":
            if self.in_table:
                self.in_table -= 1
                if self.in_table == 0:
                    # The outermost (first) table is finished.
                    self._flush_cell()
                    self._end_row()
                    self.done = True
            return
        if not self.in_table:
            return
        if self.in_table > 1:
            return

        if tag in ("td", "th"):
            self._flush_cell()
        elif tag == "tr":
            self._flush_cell()
            self._end_row()

    def handle_data(self, data):
        if self.in_table and (self._in_header_cell or self._in_data_cell):
            self._buffer.append(data)


