"""Sort the data rows of a CSV text by a given column."""

import csv
import io


def _convert(value):
    """Convert a string to int or float if possible, else return the string."""
    text = value.strip()
    if not text:
        return value
    try:
        return int(text)
    except ValueError:
        try:
            return float(text)
        except ValueError:
            return value


def _is_number(value):
    """Return True if the (converted) value is an int or float."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def sort_csv_rows(csv_text, sort_by_column):
    """Parse a CSV (with a header row) and return its data rows sorted ascending
    by the given column.

    Returns a list of dicts mapping each column name to its value. Columns whose
    values are all numeric hold numbers (ints or floats); other columns hold
    strings.

    Raises ValueError if `sort_by_column` is not present in the header.
    """
    if csv_text is None:
        csv_text = ""

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row and any(field != "" for field in row)]

    if not rows:
        return []

    header = [name.strip() for name in rows[0]]
    data_rows = rows[1:]

    # Allow lookups of header names with or without surrounding whitespace
    # (e.g. " age" matching a header of "age" or " age").
    lookup = sort_by_column
    raw_header = rows[0]
    if lookup not in header and lookup not in raw_header:
        stripped = lookup.strip()
        if stripped in header or stripped in raw_header:
            lookup = stripped

    if lookup not in header and lookup not in raw_header:
        raise ValueError(
            "Column %r not found in header. Available columns: %s"
            % (sort_by_column, header)
        )
    if lookup not in header:
        # It matched the raw header; the records use stripped keys.
        lookup = header[raw_header.index(lookup)]

    # First pass: convert every cell to a number where possible.
    converted = [[_convert(field) for field in row] for row in data_rows]

    # Pad rows that are shorter than the header so indexing is safe.
    num_cols = len(header)
    for row in converted:
        while len(row) < num_cols:
            row.append("")

    # Determine, per column, whether all values are numbers. Only then do we
    # keep the numeric types; otherwise the column stays as strings.
    keep_numeric = []
    for col_idx in range(num_cols):
        keep_numeric.append(
            all(
                _is_number(row[col_idx]) for row in converted
            )
        )

    result = []
    for row in converted:
        record = {}
        for col_idx, name in enumerate(header):
            value = row[col_idx]
            if keep_numeric[col_idx]:
                record[name] = value
            else:
                record[name] = str(value) if _is_number(value) else value
        result.append(record)

    # Sort ascending (stable) by the requested column.
    try:
        result.sort(key=lambda record: record[lookup])
    except TypeError:
        # Mixed types that cannot be compared directly: fall back to a
        # string-based comparison for a deterministic ordering.
        result.sort(key=lambda record: str(record[lookup]))

    return result

