"""Self-contained histogram binning utility."""

from bisect import bisect_right


def _linear_edges(vmin, vmax, nbins):
    """Equal-width edges spanning [vmin, vmax] inclusive of both endpoints."""
    if nbins <= 0:
        raise ValueError("number of bins must be a positive integer")
    if nbins == 1:
        return [float(vmin), float(vmax)]
    width = (vmax - vmin) / nbins
    edges = [vmin + i * width for i in range(nbins)]
    edges.append(float(vmax))
    return [float(e) for e in edges]


def histogram_bins(values, bins):
    """Compute a histogram of ``values``.

    Parameters
    ----------
    values : iterable of numbers
        The data to bin.
    bins : int or sequence of numbers
        Either the number of equal-width bins spanning the minimum to the
        maximum of ``values``, or an explicit sequence of bin edges.

    Returns
    -------
    (counts, edges) : tuple
        ``counts`` is a list of integers (one per bin) and ``edges`` is the
        list of bin edges as floats.  Bins are half-open ``[e_i, e_{i+1})``
        except the last bin, which also includes its right edge.  Values that
        fall outside the edges are ignored.
    """
    data = list(values)

    # Build the list of (float) edges.
    if isinstance(bins, bool):
        raise TypeError("bins must be an integer or a sequence of edges")
    if isinstance(bins, int):
        if bins <= 0:
            raise ValueError("number of bins must be a positive integer")
        if not data:
            # No data: no meaningful range, so use a degenerate range at 0.
            edges = _linear_edges(0.0, 0.0, bins)
            return ([0] * bins, edges)
        vmin = min(data)
        vmax = max(data)
        edges = _linear_edges(vmin, vmax, bins)
    else:
        try:
            edges = [float(e) for e in bins]
        except TypeError:
            raise TypeError("bins must be an integer or a sequence of numbers")
        if len(edges) < 2:
            return ([], edges)

    nbins = len(edges) - 1
    counts = [0] * nbins
    if not data:
        return (counts, edges)

    lo = edges[0]
    hi = edges[-1]

    for v in data:
        if v < lo or v > hi:
            continue
        idx = bisect_right(edges, v) - 1
        if idx < 0:
            idx = 0
        elif idx >= nbins:
            idx = nbins - 1
        counts[idx] += 1

    return (counts, edges)

