def _header_tokens(data):
    """Yield (token, end_index) pairs from the PGM header, skipping comments."""
    i = 0
    n = len(data)
    while True:
        # skip whitespace and comments
        while i < n:
            c = data[i:i + 1]
            if c in b' \t\r\n\x0b\x0c':
                i += 1
            elif c == b'#':
