"""Summarize numeric columns of a CSV text.

Provides :func:`summarize_numeric_csv` which parses a CSV (with header row),
detects the columns whose values are all numeric (allowing thousands
separators such as ``1,000``), and reports per-column means, per-column sample
standard deviations and the one-way ANOVA F statistic comparing the numeric
columns as groups.
"""

import csv
import io
import re

__all__ = ["summarize_numeric_csv"]

# Pattern matching a plain (possibly signed / decimal / exponent) number.
_NUMBER_RE = re.compile(
    r"""^[+-]?          # optional sign
        (?:\d+\.?\d*    # 123 | 123. | 123.45
          |\.\d+)       # .45
        (?:[eE][+-]?\d+)?  # optional exponent
        $""",
    re.VERBOSE,
)


def _parse_number(text):
    """Return the float value of *text* or ``None`` if it isn't a number.

    Thousands separators (commas) and surrounding whitespace are tolerated,
    e.g. ``" 1,000 "`` -> ``1000.0``.
    """
    if text is None:
        return None
    s = text.strip()
    if not s:
        return None
    # Remove thousands separators.
    candidate = s.replace(",", "").replace("\u00a0", "").strip()
    if not _NUMBER_RE.match(candidate):
        return None
    try:
        return float(candidate)
    except (TypeError, ValueError):
        return None


def _mean(values):
    return sum(values) / len(values)


def _sample_std(values):
    n = len(values)
    if n < 2:
        return 0.0
    m = _mean(values)
    return (sum((v - m) ** 2 for v in values) / (n - 1)) ** 0.5


def _anova_f(groups):
    """One-way ANOVA F statistic for a list of non-empty groups."""
    k = len(groups)
    ns = [len(g) for g in groups]
    n_total = sum(ns)
    if k < 2 or n_total <= k:
        return None
    grand = sum(v for g in groups for v in g) / n_total
    ss_between = sum(n * (_mean(g) - grand) ** 2 for n, g in zip(ns, groups))
    df_between = k - 1
    ss_within = sum((v - _mean(g)) ** 2 for g in groups for v in g)
    df_within = n_total - k
    ms_between = ss_between / df_between
    ms_within = ss_within / df_within
    if ms_within == 0.0:
        return float("nan") if ms_between == 0.0 else float("inf")
    return ms_between / ms_within


def summarize_numeric_csv(csv_text):
    """Summarize the numeric columns of a CSV document.

    Parameters
    ----------
    csv_text : str
        The full text of a CSV file, including its header row.

    Returns
    -------
    dict
        ``{'means': {...}, 'std_devs': {...}, 'f_value': ...}`` where only the
        columns whose every value parses as a number appear in ``means`` /
        ``std_devs``.  ``f_value`` is the one-way ANOVA F statistic treating the
        numeric columns as groups, or ``None`` when fewer than two numeric
        columns exist.
    """
    if csv_text is None:
        csv_text = ""
    if csv_text.startswith("\ufeff"):
        csv_text = csv_text[1:]

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        return {"means": {}, "std_devs": {}, "f_value": None}

    n_cols = len(header)

    # Collect raw values per column, ignoring completely empty rows.
    columns = [[] for _ in range(n_cols)]
    for row in reader:
        if not row or all(not (cell or "").strip() for cell in row):
            continue
        for i in range(n_cols):
            cell = row[i] if i < len(row) else None
            columns[i].append(cell)

    numeric = {}
    for name, cells in zip(header, columns):
        if not cells:
            continue
        values = []
        ok = True
        for cell in cells:
            parsed = _parse_number(cell)
            if parsed is None:
                ok = False
                break
            values.append(parsed)
        if ok:
            # Last occurrence of a duplicated header name wins.
            numeric[name] = values

    means = {name: _mean(values) for name, values in numeric.items()}
    std_devs = {name: _sample_std(values) for name, values in numeric.items()}

    if len(numeric) < 2:
        f_value = None
    else:
        f_value = _anova_f(list(numeric.values()))
        if f_value is None:
            f_value = None

    return {"means": means, "std_devs": std_devs, "f_value": f_value}

