import math


def max_pairwise_distance(xs, ys):
    """Return the largest Euclidean distance between any two distinct points.

    Each index i defines the 2D point (xs[i], ys[i]). Pairs are formed from
    different positions (even if the coordinates at those positions are equal).

    Returns 0.0 when fewer than two points are given. Raises ValueError when
    the input lists have different lengths.
    """
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n < 2:
        return 0.0

    best = 0.0
    for i in range(n):
        xi = xs[i]
        yi = ys[i]
        for j in range(i + 1, n):
            d = math.hypot(xi - xs[j], yi - ys[j])
            if d > best:
                best = d
    return float(best)

