"""Summarize numeric values per key from a JSON list of objects."""

import json


def _quantile(sorted_values, q):
    """Linear-interpolation quantile (the common default, e.g. numpy's)."""
    n = len(sorted_values)
    if n == 0:
        raise ValueError("cannot compute quantile of empty data")
    if n == 1:
        return float(sorted_values[0])
    pos = (n - 1) * q
    lower = int(pos // 1)
    upper = min(lower + 1, n - 1)
    frac = pos - lower
    return float(sorted_values[lower]) * (1.0 - frac) + float(sorted_values[upper]) * frac


def summarize_values_by_key(json_text):
    """Summarize values by key from a JSON string encoding a list of objects.

    Returns a dict mapping each key to {'mean', 'median', 'q1', 'q3'}.
    Raises ValueError for invalid JSON or malformed input.
    """
    try:
        data = json.loads(json_text)
    except (TypeError, ValueError) as exc:
        raise ValueError("invalid JSON input") from exc

    if not isinstance(data, list):
        raise ValueError("JSON input must encode a list of objects")

    values_by_key = {}
    for index, item in enumerate(data):
        if not isinstance(item, dict):
            raise ValueError("element %d is not an object" % index)
        for key, value in item.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("value for key %r is not a number" % key)
            values_by_key.setdefault(key, []).append(value)

    summary = {}
    for key, values in values_by_key.items():
        if not values:
            continue
        ordered = sorted(values)
        n = len(ordered)
        mean = sum(values) / n
        if n % 2 == 1:
            median = float(ordered[n // 2])
        else:
            median = (float(ordered[n // 2 - 1]) + float(ordered[n // 2])) / 2.0
        summary[key] = {
            'mean': float(mean),
            'median': float(median),
            'q1': _quantile(ordered, 0.25),
            'q3': _quantile(ordered, 0.75),
        }
    return summary

