import math
import numbers


def most_correlated_columns(data):
    if not data or len(data) < 2:
        raise ValueError("At least two columns are required")

    items = list(data.items())
    columns = []

    for name, values in items:
        try:
            vals = list(values)
        except TypeError:
            raise TypeError(f"Column {name!r} does not contain numbers")

        for value in vals:
            if not isinstance(value, numbers.Real):
                raise TypeError(f"Column {name!r} contains a non-numeric value")

        columns.append(vals)

    n = len(columns[0])
    for vals in columns[1:]:
        if len(vals) != n:
            raise ValueError("All columns must have the same length")

    if n < 2:
        raise ValueError("At least two data points are required")

    means = [math.fsum(vals) / n for vals in columns]

    best_pair = None
    max_abs_corr = -1.0

    for i in range(len(columns)):
        for j in range(i + 1, len(columns)):
            xi, xj = columns[i], columns[j]
            mi, mj = means[i], means[j]

            cov = 0.0
            var_i = 0.0
            var_j = 0.0

            for a, b in zip(xi, xj):
                da = a - mi
                db = b - mj
                cov += da * db
                var_i += da * da
                var_j += db * db

            if var_i == 0.0 or var_j == 0.0:
                continue

            corr = cov / math.sqrt(var_i * var_j)
            abs_corr = abs(corr)

            if abs_corr > max_abs_corr:
                max_abs_corr = abs_corr
                best_pair = (items[i][0], items[j][0])

    if best_pair is None:
        raise ValueError("No pair of columns has a defined Pearson correlation")

    return best_pair
