def kmeans_centers(points, n_clusters):
    if not points:
        raise ValueError("points must not be empty")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")
    if n_clusters > len(points):
        raise ValueError("n_clusters cannot exceed the number of points")

    pts = [[float(x), float(y)] for x, y in points]
    k = n_clusters

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    # Deterministic farthest-first initialization.
    centers = [pts[0][:]]
    while len(centers) < k:
        best_point = None
        best_dist = -1.0
        for p in pts:
            d = min(dist2(p, c) for c in centers)
            if d > best_dist:
                best_dist = d
                best_point = p
        centers.append(best_point[:])

    labels = [0] * len(pts)

    for _ in range(100):
        # Assign points to the nearest center.
        for i, p in enumerate(pts):
            best_idx = 0
            best_d = dist2(p, centers[0])
            for j in range(1, k):
                d = dist2(p, centers[j])
                if d < best_d:
                    best_d = d
                    best_idx = j
            labels[i] = best_idx

        # Compute new centers.
        sums = [[0.0, 0.0, 0] for _ in range(k)]
        for p, label in zip(pts, labels):
            sums[label][0] += p[0]
            sums[label][1] += p[1]
            sums[label][2] += 1

        new_centers = []
        for i in range(k):
            count = sums[i][2]
            if count:
                new_centers.append([sums[i][0] / count, sums[i][1] / count])
            else:
                new_centers.append(centers[i][:])

        # Repair empty clusters by moving them to far-away points.
        empty_indices = [i for i in range(k) if sums[i][2] == 0]
        if empty_indices:
            candidates = []
            for idx, p in enumerate(pts):
                d = dist2(p, centers[labels[idx]])
                candidates.append((d, idx))
            candidates.sort(reverse=True)

            used = set()
            for empty_idx in empty_indices:
                for _, point_idx in candidates:
                    if point_idx not in used:
                        used.add(point_idx)
                        new_centers[empty_idx] = pts[point_idx][:]
                        break

        # Check convergence.
        converged = all(dist2(new_centers[i], centers[i]) < 1e-12 for i in range(k))
        centers = new_centers
        if converged:
            break

    centers.sort(key=lambda c: (c[0], c[1]))
    return [[float(x), float(y)] for x, y in centers]
