def fit_linear_regression(features, values):
    n = len(features)
    if n != len(values):
        raise ValueError("features and values must have the same length")
    if n == 0:
        raise ValueError("at least one sample is required")

    p = len(features[0])
    if any(len(row) != p for row in features):
        raise ValueError("all feature rows must have the same length")

    m = p + 1  # intercept + features

    # Design matrix with a leading intercept column
    X = [[1.0] + [float(x) for x in row] for row in features]
    y = [float(v) for v in values]

    # Normal equations: (X^T X) beta = X^T y
    A = [[0.0] * (m + 1) for _ in range(m)]
    for xi, yi in zip(X, y):
        for j in range(m):
            A[j][m] += xi[j] * yi
            for k in range(m):
                A[j][k] += xi[j] * xi[k]

    # Gaussian elimination with partial pivoting
    for col in range(m):
        pivot = max(range(col, m), key=lambda r: abs(A[r][col]))
        if abs(A[pivot][col]) < 1e-12:
            raise ValueError("singular design matrix")

        A[col], A[pivot] = A[pivot], A[col]

        pivot_value = A[col][col]
        for j in range(col, m + 1):
            A[col][j] /= pivot_value

        for r in range(m):
            if r == col:
                continue
            factor = A[r][col]
            if abs(factor) < 1e-15:
                continue
            for j in range(col, m + 1):
                A[r][j] -= factor * A[col][j]

    beta = [A[i][m] for i in range(m)]

    return {
        "coefficients": beta[1:],
        "intercept": float(beta[0])
    }
