from math import sqrt

def letter_count_correlations(strings):
    if not strings:
        return None

    counters = [Counter(s) for s in strings]
    letters = sorted(set("".join(strings)))

    if not letters:
        return {}

    vectors = {
        letter: [counter[letter] for counter in counters]
        for letter in letters
    }

    n = len(strings)

    def pearson(x, y):
        if x == y:
            return 1.0

        mean_x = sum(x) / n
        mean_y = sum(y) / n

        numerator = sum(
            (xi - mean_x) * (yi - mean_y)
            for xi, yi in zip(x, y)
        )

        sum_sq_x = sum((xi - mean_x) ** 2 for xi in x)
        sum_sq_y = sum((yi - mean_y) ** 2 for yi in y)

        return numerator / sqrt(sum_sq_x * sum_sq_y)

    return {
        x: {
            y: pearson(vectors[x], vectors[y])
            for y in letters
        }
        for x in letters
    }
