import csv
import io

def normalize_numeric_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV has no header row")

    columns = {name: [] for name in header}

    for row in reader:
        if not row:
            continue
        for i, name in enumerate(header):
            columns[name].append(row[i] if i < len(row) else "")

    numeric_columns = []

    for name in header:
        values = columns[name]
        if not values:
            continue

        try:
            numeric_values = [float(value) for value in values]
        except ValueError:
            continue

        numeric_columns.append((name, numeric_values))

    if not numeric_columns:
        raise ValueError("No numeric columns found")

    for name, values in numeric_columns:
        minimum = min(values)
        maximum = max(values)

        if minimum == maximum:
            columns[name] = [0.0 for _ in values]
        else:
            columns[name] = [
                (value - minimum) / (maximum - minimum)
                for value in values
            ]

    return columns
