import math

def five_column_correlation_matrix(array):
    if not array:
        raise ValueError("Input must contain at least one row")

    n = len(array)

    for row in array:
        if len(row) != 5:
            raise ValueError("Each row must contain exactly 5 values")

    means = [
        sum(row[j] for row in array) / n
        for j in range(5)
    ]

    sum_sq_dev = [
        sum((row[j] - means[j]) ** 2 for row in array)
        for j in range(5)
    ]

    corr = [[0.0] * 5 for _ in range(5)]

    for i in range(5):
        for j in range(i, 5):
            if i == j:
                corr[i][j] = 1.0
            else:
                denominator = math.sqrt(sum_sq_dev[i] * sum_sq_dev[j])

                if denominator == 0.0:
                    value = 0.0
                else:
                    covariance = sum(
                        (row[i] - means[i]) * (row[j] - means[j])
                        for row in array
                    )
                    value = covariance / denominator

                corr[i][j] = value
                corr[j][i] = value

    return corr
