def predict_linear_regression(train_csv, test_csv, target):
    import csv
    import io
    import math

    def read_rows(text):
        return list(csv.reader(io.StringIO(text)))

    def parse_numeric(s):
        s = s.strip()
        if s == "":
            raise ValueError("missing value")
        try:
            v = float(s)
        except ValueError:
            raise ValueError("non-numeric value")
        if not math.isfinite(v):
            raise ValueError("non-finite value")
        return v

    train_rows = read_rows(train_csv)
    if not train_rows:
        raise ValueError("empty training CSV")

    train_header = train_rows[0]
    if target not in train_header:
        raise ValueError("target column not found")

    feature_names = [name for name in train_header if name != target]

    idx_train = {name: i for i, name in enumerate(train_header)}
    target_idx = idx_train[target]
    feature_indices_train = [idx_train[name] for name in feature_names]

    X = []
    y = []
    for row in train_rows[1:]:
        if len(row) != len(train_header):
            raise ValueError("wrong number of fields")
        features = [parse_numeric(row[i]) for i in feature_indices_train]
        y.append(parse_numeric(row[target_idx]))
        X.append(features)

    if not X:
        raise ValueError("no training data")

    test_rows = read_rows(test_csv)
    if not test_rows:
        raise ValueError("empty test CSV")

    test_header = test_rows[0]
    idx_test = {name: i for i, name in enumerate(test_header)}
    for name in feature_names:
        if name not in idx_test:
            raise ValueError("missing feature column in test CSV")

    feature_indices_test = [idx_test[name] for name in feature_names]

    X_test = []
    for row in test_rows[1:]:
        if len(row) != len(test_header):
            raise ValueError("wrong number of fields")
        features = [parse_numeric(row[i]) for i in feature_indices_test]
        X_test.append(features)

    if not X_test:
        return []

    try:
        import numpy as np
    except ImportError:
        np = None

    if np is not None:
        X_arr = np.array([[1.0] + row for row in X], dtype=float)
        y_arr = np.array(y, dtype=float)
        coef, *_ = np.linalg.lstsq(X_arr, y_arr, rcond=None)

        X_test_arr = np.array([[1.0] + row for row in X_test], dtype=float)
        preds = X_test_arr @ coef
        return [float(v) for v in preds]

    # Pure-Python fallback: ordinary least squares via normal equations.
    p = len(feature_names) + 1
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for features, yi in zip(X, y):
        design_row = [1.0] + features
        for i in range(p):
            b[i] += design_row[i] * yi
            for j in range(p):
                A[i][j] += design_row[i] * design_row[j]

    M = [A[i][:] + [b[i]] for i in range(p)]
    scale = max((abs(A[i][j]) for i in range(p) for j in range(p)), default=0.0)
    tol = 1e-12 * max(1.0, scale)

    row_idx = 0
    pivot_cols = []

    for col in range(p):
        pivot = None
        max_val = 0.0
        for r in range(row_idx, p):
            val = abs(M[r][col])
            if val > max_val:
                max_val = val
                pivot = r

        if pivot is None or max_val <= tol:
            continue

        M[row_idx], M[pivot] = M[pivot], M[row_idx]
        pv = M[row_idx][col]

        for j in range(col, p + 1):
            M[row_idx][j] /= pv

        for r in range(p):
            if r != row_idx:
                factor = M[r][col]
                if abs(factor) > tol:
                    for j in range(col, p + 1):
                        M[r][j] -= factor * M[row_idx][j]

        pivot_cols.append(col)
        row_idx += 1
        if row_idx == p:
            break

    beta = [0.0] * p
    for i, col in enumerate(pivot_cols):
        beta[col] = M[i][p]

    preds = []
    for features in X_test:
        design_row = [1.0] + features
        preds.append(float(sum(design_row[i] * beta[i] for i in range(p))))

    return preds
