def normalize_with_row_averages(data):
    if not data:
        return []

    num_cols = len(data[0])

    if num_cols == 0:
        return [[] for _ in data]

    mins = [min(row[j] for row in data) for j in range(num_cols)]
    maxs = [max(row[j] for row in data) for j in range(num_cols)]

    result = []

    for row in data:
        scaled = []

        for j, value in enumerate(row):
            denom = maxs[j] - mins[j]

            if denom == 0:
                scaled_value = 0.0
            else:
                scaled_value = (value - mins[j]) / denom

            scaled.append(float(scaled_value))

        average = sum(scaled) / len(scaled)
        result.append(scaled + [average])

    return result

