from html.parser import HTMLParser

def extract_article_info(html):
    class Node:
        __slots__ = ("tag", "attrs", "children", "parent", "data")

        def __init__(self, tag=None, attrs=None, parent=None, data=None):
            self.tag = tag
            self.attrs = attrs or {}
            self.children = []
            self.parent = parent
            self.data = data

    class TreeBuilder(HTMLParser):
        VOID = {
            "area", "base", "br", "col", "embed", "hr", "img", "input",
            "link", "meta", "param", "source", "track", "wbr"
        }

        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.root = Node()
            self.stack = [self.root]

        def handle_starttag(self, tag, attrs):
            tag = tag.lower()
            attrs_dict = {}
            for k, v in attrs:
                attrs_dict[k.lower()] = "" if v is None else v

            node = Node(tag, attrs_dict, self.stack[-1])
            self.stack[-1].children.append(node)

            if tag not in self.VOID:
                self.stack.append(node)

        def handle_startendtag(self, tag, attrs):
            self.handle_starttag(tag, attrs)
            self.handle_endtag(tag)

        def handle_endtag(self, tag):
            tag = tag.lower()
            for i in range(len(self.stack) - 1, 0, -1):
                if self.stack[i].tag == tag:
                    del self.stack[i:]
                    break

        def handle_data(self, data):
            if data:
                self.stack[-1].children.append(
                    Node(parent=self.stack[-1], data=data)
                )

    def has_class(node, cls):
        if node.tag is None:
            return False
        return cls in node.attrs.get("class", "").split()

    def find_first(node, predicate):
        for child in node.children:
            if child.tag is not None:
                if predicate(child):
                    return child
                found = find_first(child, predicate)
                if found is not None:
                    return found
        return None

    def text_content(node):
        if node.tag is None:
            return node.data or ""
        return "".join(text_content(child) for child in node.children)

    builder = TreeBuilder()
    builder.feed(html)
    builder.close()

    containers = []

    def collect_containers(node):
        for child in node.children:
            if child.tag is not None:
                if child.tag == "div" and has_class(child, "container"):
                    containers.append(child)
                collect_containers(child)

    collect_containers(builder.root)

    result = []

    for div in containers:
        h1 = find_first(div, lambda n: n.tag == "h1")
        date_el = find_first(
            div, lambda n: n.tag == "span" and has_class(n, "date")
        )
        author_el = find_first(
            div, lambda n: n.tag == "span" and has_class(n, "author")
        )

        title = text_content(h1).strip() if h1 is not None else "No Title"
        date = text_content(date_el).strip() if date_el is not None else "No Date"
        author = (
            text_content(author_el).strip()
            if author_el is not None
            else "No Author"
        )

        result.append((title, date, author))

    return result

