def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    if len(train_X) == 0:
        raise ValueError("Training set is empty")
    if len(train_X) != len(train_y) or len(test_X) != len(test_y):
        raise ValueError("X and y lengths do not match")

    n = len(train_X)
    p = len(train_X[0]) if n > 0 else 0

    mean_X = [0.0] * p
    for j in range(p):
        mean_X[j] = sum(train_X[i][j] for i in range(n)) / n
    mean_y = sum(train_y) / n

    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p
    for i in range(n):
        x_cent = [train_X[i][j] - mean_X[j] for j in range(p)]
        y_cent = train_y[i] - mean_y
        for j in range(p):
            b[j] += x_cent[j] * y_cent
            for k in range(p):
                A[j][k] += x_cent[j] * x_cent[k]

    def solve_linear_system(A, b):
        n = len(A)
        M = [A[i][:] + [b[i]] for i in range(n)]
        pivot_cols = []
        row = 0

        for col in range(n):
            pivot_row = -1
            max_val = 1e-12
            for r in range(row, n):
                if abs(M[r][col]) > max_val:
                    max_val = abs(M[r][col])
                    pivot_row = r

            if pivot_row == -1:
                continue

            M[row], M[pivot_row] = M[pivot_row], M[row]
            pivot = M[row][col]

            for r in range(row + 1, n):
                factor = M[r][col] / pivot
                if factor != 0:
                    for c in range(col, n + 1):
                        M[r][c] -= factor * M[row][c]

            pivot_cols.append(col)
            row += 1
            if row == n:
                break

        x = [0.0] * n
        for i in range(row - 1, -1, -1):
            col = pivot_cols[i]
            s = M[i][n]
            for c in range(col + 1, n):
                s -= M[i][c] * x[c]
            if abs(M[i][col]) > 1e-12:
                x[col] = s / M[i][col]
            else:
                x[col] = 0.0
        return x

    coef = solve_linear_system(A, b)
    intercept = mean_y - sum(mean_X[j] * coef[j] for j in range(p))

    y_pred = []
    for i in range(len(test_X)):
        pred = intercept
        for j in range(p):
            pred += coef[j] * test_X[i][j]
        y_pred.append(pred)

    if len(test_y) == 0:
        return float('nan')

    mean_y_test = sum(test_y) / len(test_y)
    ss_res = sum((test_y[i] - y_pred[i]) ** 2 for i in range(len(test_y)))
    ss_tot = sum((y - mean_y_test) ** 2 for y in test_y)

    if ss_tot == 0:
        return 1.0 if ss_res == 0 else 0.0
    return 1.0 - ss_res / ss_tot
