            if key != "id" and key not in seen:
                seen.add(key)
                first_cols.append(key)

    second_cols = []
    seen = set()
    for row in rows2:
        for key in row:
            if key != "id" and key not in seen:
                seen.add(key)
                second_cols.append(key)

    # Compute mean and population standard deviation for first-table columns.
    stats = {}
    for col in first_cols:
        values = [row[col] for row in rows1 if col in row and row[col] is not None]
        if values:
            mean = sum(values) / len(values)
            variance = sum((v - mean) ** 2 for v in values) / len(values)
            stats[col] = (mean, math.sqrt(variance))
        else:
            stats[col] = (None, None)

    def standardize(row):
        out = {"id": row["id"]}
        for col in first_cols:
            value = row.get(col)
            if value is None:
                out[col] = None
