import math

def standardize_columns(rows):
    if not rows:
        raise ValueError("rows must not be empty")

    n = len(rows)
    num_cols = len(rows[0])
    result = [[0.0] * num_cols for _ in range(n)]

    for j in range(num_cols):
        col = [row[j] for row in rows]

        # If all values in the column are equal, leave them as zeros.
        if all(value == col[0] for value in col):
            continue

        mean = math.fsum(col) / n
        variance = math.fsum((value - mean) ** 2 for value in col) / n

        if variance == 0.0:
            continue

        std_dev = math.sqrt(variance)

        for i, value in enumerate(col):
            result[i][j] = (value - mean) / std_dev

    return result

