def seasonal_decomposition(values, period, model):
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or period <= 0:
        raise ValueError("period must be a positive integer")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    h = period // 2
    trend = [None] * n

    # Centered moving average
    for i in range(h, n - h):
        if period % 2 == 1:
            trend[i] = sum(values[i - h:i + h + 1]) / period
        else:
            numerator = (
                0.5 * values[i - h]
                + sum(values[i - h + 1:i + h])
                + 0.5 * values[i + h]
            )
            trend[i] = numerator / period

    # Raw seasonal indices by averaging detrended values for each season
    sums = [0.0] * period
    counts = [0] * period

    for i, t in enumerate(trend):
        if t is None:
            continue

        if model == "additive":
            detrended = values[i] - t
        else:
            detrended = values[i] / t

        season = i % period
        sums[season] += detrended
        counts[season] += 1

    raw_seasonal = [
        sums[s] / counts[s]
        for s in range(period)
    ]

    # Normalize seasonal indices
    if model == "additive":
        mean_index = sum(raw_seasonal) / period
        seasonal_indices = [x - mean_index for x in raw_seasonal]
    else:
        mean_index = sum(raw_seasonal) / period
        seasonal_indices = [x / mean_index for x in raw_seasonal]

    seasonal = [seasonal_indices[i % period] for i in range(n)]

    # Residuals
    residual = [None] * n
    for i, t in enumerate(trend):
        if t is None:
            continue

        if model == "additive":
            residual[i] = values[i] - t - seasonal[i]
        else:
            residual[i] = values[i] / (t * seasonal[i])

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
