            )
            trend[i] = numerator / period

    # Raw seasonal indices by averaging detrended values for each season
    sums = [0.0] * period
    counts = [0] * period

    for i, t in enumerate(trend):
        if t is None:
            continue

        if model == "additive":
            detrended = values[i] - t
        else:
            detrended = values[i] / t

        season = i % period
        sums[season] += detrended
        counts[season] += 1

    raw_seasonal = [
        sums[s] / counts[s]
        for s in range(period)
    ]

    # Normalize seasonal indices
    if model == "additive":
        mean_index = sum(raw_seasonal) / period
        seasonal_indices = [x - mean_index for x in raw_seasonal]
    else:
