import math

def column_linear_regression(rows, columns, target):
    if not rows or target not in columns:
        raise ValueError("rows must be non-empty and target must be a column name")

    target_idx = columns.index(target)
    feature_indices = [i for i in range(len(columns)) if i != target_idx]
    n_features = len(feature_indices)
    n = n_features + 1  # intercept + features
    m = len(rows)

    # Build the design matrix A (with intercept as the first column) and target vector b.
    A = []
    b = []
    for row in rows:
        A.append([1.0] + [float(row[i]) for i in feature_indices])
        b.append(float(row[target_idx]))

    # Householder QR decomposition to solve the least-squares problem.
    for k in range(min(m, n)):
        x = [A[i][k] for i in range(k, m)]
        norm = math.sqrt(sum(v * v for v in x))
        if norm < 1e-12:
            continue

        if x[0] >= 0:
            v0 = x[0] + norm
        else:
            v0 = x[0] - norm
        v = [v0] + x[1:]

        v_norm2 = sum(v_i * v_i for v_i in v)
        if v_norm2 == 0:
            continue
        beta = 2.0 / v_norm2

        # Apply the Householder reflector to the remaining columns of A.
        for j in range(k, n):
            dot = 0.0
            for i in range(len(v)):
                dot += v[i] * A[k + i][j]
            for i in range(len(v)):
                A[k + i][j] -= beta * v[i] * dot

        # Apply the Householder reflector to b.
        dot = 0.0
        for i in range(len(v)):
            dot += v[i] * b[k + i]
        for i in range(len(v)):
            b[k + i] -= beta * v[i] * dot

    # Back substitution to solve R * beta = z.
    beta_vec = [0.0] * n
    for i in range(min(m, n) - 1, -1, -1):
        if abs(A[i][i]) < 1e-12:
            beta_vec[i] = 0.0
        else:
            s = b[i]
            for j in range(i + 1, n):
                s -= A[i][j] * beta_vec[j]
            beta_vec[i] = s / A[i][i]

    intercept = beta_vec[0]
    coefficients = beta_vec[1:]
    return coefficients, intercept

