def weather_column_summary(column, data):
    column_indices = {
        'Temperature': 1,
        'Humidity': 2,
        'Wind Speed': 3,
        'Precipitation': 4,
    }

    if column not in column_indices:
        raise ValueError(f"Unknown column: {column}")

    index = column_indices[column]
    values = [row[index] for row in data]

    if not values:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * 10,
        }

    total = sum(values)
    mean = total / len(values)
    min_val = min(values)
    max_val = max(values)

    histogram = [0] * 10
    bin_width = (max_val - min_val) / 10.0

    for value in values:
        if value == max_val:
            bin_index = 9
        else:
            bin_index = int((value - min_val) / bin_width)
            bin_index = max(0, min(bin_index, 9))
        histogram[bin_index] += 1

    return {
        'sum': total,
        'mean': mean,
        'min': min_val,
        'max': max_val,
        'histogram': histogram,
    }

