from collections import Counter, defaultdict

def association_chi_square(left, right):
    right_by_id = defaultdict(list)
    for key, category in right:
        right_by_id[key].append(category)

    joined = []
    for key, left_category in left:
        for right_category in right_by_id.get(key, ()):
            joined.append((left_category, right_category))

    if not joined:
        return (0.0, 0)

    counts = Counter(joined)
    row_totals = Counter()
    col_totals = Counter()

    for (row, col), count in counts.items():
        row_totals[row] += count
        col_totals[col] += count

    n = len(joined)
    statistic = 0.0

    for row, row_total in row_totals.items():
        for col, col_total in col_totals.items():
            observed = counts.get((row, col), 0)
            expected = row_total * col_total / n
            statistic += (observed - expected) ** 2 / expected

    dof = (len(row_totals) - 1) * (len(col_totals) - 1)
    return (float(statistic), int(dof))
