    salaries = salaries_by_dept[dept]

    if not salaries:
        return [0] * 10, [0.0] * 11

    lo = float(min(salaries))
    hi = float(max(salaries))
    counts = [0] * 10

    if lo == hi:
        edges = [lo] * 11
        counts[-1] = len(salaries)
        return counts, edges

    span = hi - lo
    width = span / 10.0

    for salary in salaries:
        if salary == hi:
            idx = 9
        else:
            idx = int((float(salary) - lo) / span * 10)
            if idx < 0:
                idx = 0
            elif idx > 9:
                idx = 9
        counts[idx] += 1

    edges = [lo + i * width for i in range(11)]
    edges[-1] = hi

    return counts, edges

