        return duplicates, []
    if k == 1:
        return duplicates, [unique]

    def dist2(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # Deterministic farthest-first initialization for k-means.
    centroids = [unique[0]]
    min_d2 = [dist2(p, centroids[0]) for p in unique]

    while len(centroids) < k:
        idx = max(range(len(unique)), key=lambda i: min_d2[i])
        centroids.append(unique[idx])
        c = unique[idx]
        for i, p in enumerate(unique):
            d = dist2(p, c)
            if d < min_d2[i]:
                min_d2[i] = d

    def assign(centroids):
        labels = []
        for p in unique:
            best_j = 0
            best_d = dist2(p, centroids[0])
            for j in range(1, k):
                d = dist2(p, centroids[j])
                if d < best_d:
                    best_d = d
                    best_j = j
            labels.append(best_j)
        return labels

    labels = None
    for _ in range(300):
        new_labels = assign(centroids)
        if new_labels == labels:
            labels = new_labels
            break

        labels = new_labels
        dim = len(unique[0])
        sums = [[0.0] * dim for _ in range(k)]
        counts_k = [0] * k

        for p, j in zip(unique, labels):
            counts_k[j] += 1
            for d in range(dim):
                sums[j][d] += p[d]

        for j in range(k):
            if counts_k[j]:
                centroids[j] = tuple(
                    sums[j][d] / counts_k[j] for d in range(dim)
                )
            else:
                far_idx = max(
                    range(len(unique)),
                    key=lambda i: dist2(unique[i], centroids[labels[i]])
                )
                centroids[j] = unique[far_idx]

    labels = assign(centroids)

    # Ensure no empty clusters remain.
    counts_k = [0] * k
    for j in labels:
        counts_k[j] += 1

    for empty in range(k):
        if counts_k[empty] == 0:
            best_idx = None
            best_dist = -1.0
            for i, (p, j) in enumerate(zip(unique, labels)):
                if counts_k[j] > 1:
                    d = dist2(p, centroids[j])
                    if d > best_dist:
                        best_dist = d
                        best_idx = i
            if best_idx is not None:
                old = labels[best_idx]
                labels[best_idx] = empty
                counts_k[old] -= 1
                counts_k[empty] += 1

    clusters = [[] for _ in range(k)]
    for p, j in zip(unique, labels):
        clusters[j].append(p)

    clusters = [sorted(cluster) for cluster in clusters if cluster]
    clusters.sort()

    return duplicates, clusters
