import math

def _quantile(sorted_values, q):
    n = len(sorted_values)
    if n == 0:
        return float("nan")
    if n == 1:
        return float(sorted_values[0])

    pos = (n - 1) * q
    lower = int(math.floor(pos))
    upper = int(math.ceil(pos))

    if lower == upper:
        return float(sorted_values[lower])

    frac = pos - lower
    return float(
        sorted_values[lower]
        + (sorted_values[upper] - sorted_values[lower]) * frac
    )


def describe_filled_columns(columns):
    result = {}

    for name, values in columns.items():
        present = [v for v in values if v is not None]

        if present:
            fill_value = sum(present) / len(present)
        else:
            fill_value = float("nan")

        filled = [fill_value if v is None else v for v in values]
        valid = [v for v in filled if not (isinstance(v, float) and math.isnan(v))]

        n = len(valid)

        if n == 0:
            result[name] = {
                "count": 0.0,
                "mean": float("nan"),
                "std": float("nan"),
                "min": float("nan"),
                "25%": float("nan"),
                "50%": float("nan"),
                "75%": float("nan"),
                "max": float("nan"),
            }
            continue

        mean = sum(valid) / n

        if n > 1:
            std = math.sqrt(sum((x - mean) ** 2 for x in valid) / (n - 1))
        else:
            std = float("nan")

        sorted_values = sorted(valid)

        result[name] = {
            "count": float(n),
            "mean": float(mean),
            "std": float(std),
            "min": float(sorted_values[0]),
            "25%": _quantile(sorted_values, 0.25),
            "50%": _quantile(sorted_values, 0.50),
            "75%": _quantile(sorted_values, 0.75),
            "max": float(sorted_values[-1]),
        }

    return result
