def format_sorted_dict_table(my_dict):
    items = sorted(my_dict.items(), key=lambda kv: kv[0])
    rows = [(str(k), str(v)) for k, v in items]

    key_width = max([len("Key")] + [len(k) for k, _ in rows])
    value_width = max([len("Value")] + [len(v) for _, v in rows])

    def border():
        return (
            "+"
            + "-" * (key_width + 2)
            + "+"
            + "-" * (value_width + 2)
            + "+"
        )

    def format_row(key, value):
        return (
            "| "
            + key.center(key_width)
            + " | "
            + value.center(value_width)
            + " |"
        )

    lines = [
        border(),
        format_row("Key", "Value"),
        border(),
    ]

    for key, value in rows:
        lines.append(format_row(key, value))

    if rows:
        lines.append(border())

    return "\n".join(lines)
