import csv
import io

def encode_csv_column(csv_text, column_name):
    reader = csv.reader(io.StringIO(csv_text, newline=""))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {column_name!r} does not exist")

    try:
        column_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column {column_name!r} does not exist")

    cleaned_values = []

    for row in reader:
        value = row[column_index] if column_index < len(row) else ""
        value = value.replace("\r\n", "<br>")
        value = value.replace("\n", "<br>")
        value = value.replace("\r", "<br>")
        cleaned_values.append(value)

    classes = sorted(set(cleaned_values))
    class_to_code = {value: index for index, value in enumerate(classes)}
    codes = [class_to_code[value] for value in cleaned_values]

    return classes, codes

