import math

def spectrum_magnitude_histogram(pairs):
    values = [value for _, value in pairs]
    n = len(values)

    if n == 0:
        return ([], [])

    magnitudes = []
    for k in range(n):
        total = 0j
        for t, value in enumerate(values):
            total += value * cmath.exp(-2j * math.pi * k * t / n)
        magnitudes.append(abs(total))

    min_mag = min(magnitudes)
    max_mag = max(magnitudes)
    counts = [0] * 10

    if min_mag == max_mag:
        counts[9] = len(magnitudes)
        return (magnitudes, counts)

    width = (max_mag - min_mag) / 10.0

    for mag in magnitudes:
        if mag >= max_mag:
            index = 9
        else:
            index = int((mag - min_mag) / width)
            index = max(0, min(index, 9))
        counts[index] += 1

    return (magnitudes, counts)
