from numbers import Real

def normalized_cumulative_sums(data):
    if not data:
        raise ValueError("data is empty")

    for values in data.values():
        if len(values) == 0:
            raise ValueError("data is empty")
        for value in values:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise TypeError("columns must contain only numeric values")
            if isinstance(value, float) and math.isnan(value):
                raise ValueError("data contains NaN")

    result = {}

    for name, values in data.items():
        cumulative = []
        total = 0

        for value in values:
            total += value
            cumulative.append(total)

        minimum = min(cumulative)
        maximum = max(cumulative)

        if minimum == maximum:
            result[name] = [0.0] * len(cumulative)
        else:
            span = maximum - minimum
            result[name] = [float((x - minimum) / span) for x in cumulative]

    return result
