import math

def standardize_by_group(records):
    required = ("id", "age", "income")

    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in required):
            raise ValueError("Each record must contain 'id', 'age', and 'income'.")

    groups = {}
    for i, record in enumerate(records):
        groups.setdefault(record["id"], []).append(i)

    result = [None] * len(records)

    for indices in groups.values():
        ages = [records[i]["age"] for i in indices]
        incomes = [records[i]["income"] for i in indices]

        def mean_and_std(values):
            n = len(values)
            first = values[0]

            if all(value == first for value in values):
                return None, None  # constant group

            mean = sum(values) / n
            variance = sum((value - mean) ** 2 for value in values) / n
            return mean, math.sqrt(variance)

        age_mean, age_std = mean_and_std(ages)
        income_mean, income_std = mean_and_std(incomes)

        for i in indices:
            record = records[i]

            if age_std is None or age_std == 0:
                age_z = 0.0
            else:
                age_z = (record["age"] - age_mean) / age_std

            if income_std is None or income_std == 0:
                income_z = 0.0
            else:
                income_z = (record["income"] - income_mean) / income_std

            output = dict(record)
            output["id"] = record["id"]
            output["age"] = float(age_z)
            output["income"] = float(income_z)
            result[i] = output

    return result
