from math import sqrt

def standardize_columns(rows):
    n = len(rows)
    if n == 0:
        return []

    m = len(rows[0])
    if m == 0:
        return [[] for _ in rows]

    result = [[0.0] * m for _ in range(n)]

    for j in range(m):
        column = [rows[i][j] for i in range(n)]

        # Constant columns become all zeros.
        if all(value == column[0] for value in column):
            continue

        mean = sum(column) / n
        variance = sum((value - mean) ** 2 for value in column) / n
        std = sqrt(variance)

        if std == 0.0:
            continue

        for i in range(n):
            result[i][j] = (rows[i][j] - mean) / std

    return result

