import xml.etree.ElementTree as ET

def xml_to_dict(xml):
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError("Malformed XML") from exc

    def convert(elem):
        children = list(elem)

        # Leaf element: no attributes and no child elements
        if not elem.attrib and not children:
            if elem.text is None:
                return None
            text = elem.text.strip()
            return text if text else None

        result = {f"@{key}": value for key, value in elem.attrib.items()}

        # Collect direct text belonging to this element
        direct_text = []
        if elem.text:
            direct_text.append(elem.text)
        for child in children:
            if child.tail:
                direct_text.append(child.tail)

        text = "".join(direct_text).strip()
        if text:
            result["#text"] = text

        child_values = {}
        for child in children:
            tag = child.tag
            value = convert(child)

            if tag in child_values:
                if isinstance(child_values[tag], list):
                    child_values[tag].append(value)
                else:
                    child_values[tag] = [child_values[tag], value]
            else:
                child_values[tag] = value

        result.update(child_values)
        return result

    return {root.tag: convert(root)}
