def standardize_columns(rows, columns, features):
    if not rows:
        return []

    col_index = {name: i for i, name in enumerate(columns)}
    result = [list(row) for row in rows]
    n = len(rows)

    for feature in features:
        j = col_index[feature]
        values = [row[j] for row in rows]

        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = variance ** 0.5

        if std == 0:
            for i in range(n):
                result[i][j] = 0.0
        else:
            for i, x in enumerate(values):
                result[i][j] = (x - mean) / std

    return result
