def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("Inputs must not be empty")

    m = len(P)
    k = len(P[0])

    if len(T) != k:
        raise ValueError("P's number of columns must match T's first dimension")

    n = len(T[0])
    p = len(T[0][0]) if n > 0 else 0

    table = []

    for j in range(n):
        row = []
        for i in range(m):
            for b in range(p):
                value = 0.0
                for a in range(k):
                    value += P[i][a] * T[a][j][b]
                row.append(value)
        table.append(row)

    if not table:
        return []

    num_cols = len(table[0])

    for c in range(num_cols):
        col = [table[r][c] for r in range(n)]

        first = col[0]
        if all(x == first for x in col):
            for r in range(n):
                table[r][c] = 0.0
            continue

        mean = sum(col) / n
        variance = sum((x - mean) ** 2 for x in col) / n
        std = math.sqrt(variance)

        if std == 0.0:
            for r in range(n):
                table[r][c] = 0.0
        else:
            for r in range(n):
                table[r][c] = (col[r] - mean) / std

