def quartiles_of_string_groups(groups):
    data = sorted(int(value) for group in groups for value in group)

    if not data:
        raise ValueError("Cannot compute quartiles of an empty collection")

    def percentile(p):
        if len(data) == 1:
            return float(data[0])

        position = (len(data) - 1) * p
        lower = int(position)

        if lower == position:
            return float(data[lower])

        upper = lower + 1
        fraction = position - lower

        return float(data[lower] + fraction * (data[upper] - data[lower]))

    return (
        percentile(0.25),
        percentile(0.50),
        percentile(0.75),
    )
