from bisect import bisect_right
from statistics import mean, pstdev

def summarize_distribution(values, bins):
    if not values:
        raise ValueError("values must not be empty")
    if bins <= 0:
        raise ValueError("bins must be positive")

    m = mean(values)
    s = pstdev(values)  # population standard deviation

    vmin = float(min(values))
    vmax = float(max(values))

    if vmin == vmax:
        edges = [vmin] * (bins + 1)
    else:
        width = (vmax - vmin) / bins
        edges = [vmin + i * width for i in range(bins)] + [vmax]

    counts = [0] * bins

    for x in values:
        idx = bisect_right(edges, x) - 1
        if idx < 0:
            idx = 0
        elif idx >= bins:
            idx = bins - 1
        counts[idx] += 1

    return m, s, counts, edges

