def fit_linear_regression(records, target='z'):
    if not records:
        raise ValueError("records must not be empty")

    predictor_keys = [key for key in records[0] if key != target]
    m = len(predictor_keys) + 1  # intercept + predictors

    # Build normal equations: (X^T X) beta = X^T y
    XTX = [[0.0] * m for _ in range(m)]
    XTy = [0.0] * m

    for record in records:
        row = [1.0] + [float(record[key]) for key in predictor_keys]
        y = float(record[target])

        for i in range(m):
            XTy[i] += row[i] * y
            for j in range(i, m):
                XTX[i][j] += row[i] * row[j]

    # Mirror the symmetric matrix
    for i in range(m):
        for j in range(i + 1, m):
            XTX[j][i] = XTX[i][j]

    # Solve using Gaussian elimination with partial pivoting
    A = [XTX[i] + [XTy[i]] for i in range(m)]

    for col in range(m):
        pivot_row = max(range(col, m), key=lambda r: abs(A[r][col]))

        if abs(A[pivot_row][col]) < 1e-12:
            raise ValueError("Cannot fit linear regression: singular system")

        if pivot_row != col:
            A[col], A[pivot_row] = A[pivot_row], A[col]

        pivot = A[col][col]

        for r in range(col + 1, m):
            factor = A[r][col] / pivot
            if factor != 0.0:
                for c in range(col, m + 1):
                    A[r][c] -= factor * A[col][c]

    beta = [0.0] * m

    for i in range(m - 1, -1, -1):
        rhs = A[i][m] - sum(A[i][j] * beta[j] for j in range(i + 1, m))
        beta[i] = rhs / A[i][i]

    intercept = beta[0]
    coefficients = {
        key: beta[i + 1]
        for i, key in enumerate(predictor_keys)
    }

    return intercept, coefficients
