        numeric_values = []
        is_numeric = True

        for value in present:
            try:
                numeric_values.append(float(value))
            except ValueError:
                is_numeric = False
                break

        if is_numeric:
            mean = sum(numeric_values) / len(numeric_values)
            result[column_name] = [
                float(value) if value != "" else mean
                for value in values
            ]
        else:
