        replaced = []
        for value in values:
            if value in replacements:
                replaced.append(replacements[value])
            else:
                replaced.append(value)

        if any(isinstance(value, str) for value in replaced):
            distinct_values = sorted(set(replaced))
            codes = {value: i for i, value in enumerate(distinct_values)}
            replaced = [codes[value] for value in replaced]

        encoded_columns.append((name, replaced))

    result = {}

