        mean = sum(values) / n

        if n == 1:
            result[name] = [0.0]
            continue

        variance = sum((value - mean) ** 2 for value in values) / (n - 1)
        std = math.sqrt(variance)

        if std == 0:
            result[name] = [0.0] * n
        else:
            result[name] = [(value - mean) / std for value in values]

    return result
