import math

def standardize_and_correlate(rows):
    if not rows:
        return [], []

    n = len(rows)
    m = len(rows[0])

    # Column means ignoring missing values
    means = []
    for j in range(m):
        vals = [row[j] for row in rows if row[j] is not None]
        if not vals:
            raise ValueError("Cannot compute mean of an all-missing column")
        means.append(sum(vals) / len(vals))

    # Replace missing values with column means
    filled = [
        [means[j] if row[j] is None else row[j] for j in range(m)]
        for row in rows
    ]

    # Compute column means and population standard deviations
    col_means = []
    stds = []
    for j in range(m):
        col = [filled[i][j] for i in range(n)]
        mu = sum(col) / n
        var = sum((x - mu) ** 2 for x in col) / n
        col_means.append(mu)
        stds.append(math.sqrt(var))

    # Standardize columns
    standardized = []
    for i in range(n):
        new_row = []
        for j in range(m):
            if stds[j] == 0:
                new_row.append(0.0)
            else:
                new_row.append((filled[i][j] - col_means[j]) / stds[j])
        standardized.append(new_row)

    # Pearson correlation matrix
    corr = [[0.0] * m for _ in range(m)]
    for j in range(m):
        for k in range(j, m):
            if stds[j] == 0 or stds[k] == 0:
                value = 1.0 if j == k else 0.0
            else:
                value = sum(
                    standardized[i][j] * standardized[i][k]
                    for i in range(n)
                ) / n
                if j == k:
                    value = 1.0
            corr[j][k] = corr[k][j] = value

    return standardized, corr
