import math

def summarize_stock_column(column, data):
    column_indices = {
        'Open': 1,
        'High': 2,
        'Low': 3,
        'Close': 4,
        'Volume': 5,
    }

    if column not in column_indices:
        raise ValueError(f"Invalid column name: {column}")

    idx = column_indices[column]
    values = []

    for row in data:
        if len(row) != 6:
            raise ValueError("Each row must have exactly six entries")

        value = row[idx]
        if value is not None:
            values.append(float(value))

    values.sort()
    count = len(values)

    if count == 0:
        return {
            'count': 0,
            'mean': None,
            'std': None,
            'min': None,
            '25%': None,
            '50%': None,
            '75%': None,
            'max': None,
        }

    mean = sum(values) / count

    if count > 1:
        std = math.sqrt(sum((x - mean) ** 2 for x in values) / (count - 1))
    else:
        std = 0.0

    def percentile(p):
        if count == 1:
            return values[0]

        pos = (count - 1) * p
        lower = math.floor(pos)
        upper = math.ceil(pos)

        if lower == upper:
            return values[int(pos)]

        return values[lower] + (values[upper] - values[lower]) * (pos - lower)

    return {
        'count': count,
        'mean': mean,
        'std': std,
        'min': values[0],
        '25%': percentile(0.25),
        '50%': percentile(0.50),
        '75%': percentile(0.75),
