import numbers

def correlation_without_column(data, column):
    filtered = {}
    for name, values in data.items():
        if name == column:
            continue
        if all(isinstance(v, numbers.Real) and not isinstance(v, bool) for v in values):
            filtered[name] = [float(v) for v in values]

    if not filtered:
        return None

    columns = list(filtered)
    n = len(next(iter(filtered.values())))
    means = {
        col: (sum(values) / n if n else float("nan"))
        for col, values in filtered.items()
    }

    def pearson(x, y):
        xs = filtered[x]
        ys = filtered[y]
        mx = means[x]
        my = means[y]

        numerator = 0.0
        sum_x2 = 0.0
        sum_y2 = 0.0

        for a, b in zip(xs, ys):
            dx = a - mx
            dy = b - my
            numerator += dx * dy
            sum_x2 += dx * dx
            sum_y2 += dy * dy

        denominator = math.sqrt(sum_x2 * sum_y2)
        if denominator == 0.0:
            return float("nan")
        return numerator / denominator

    result = {}
    for x in columns:
        result[x] = {}
        for y in columns:
            result[x][y] = pearson(x, y)

    return result
