    result = {}

    for name, values in numeric_columns:
        lo = min(values)
        hi = max(values)
        counts = [0] * 10

        if lo == hi:
            # The final bin is the only closed bin, so it contains the single value.
            counts[9] = len(values)
        else:
            width = (hi - lo) / 10.0

            for value in values:
                if value == hi:
                    index = 9
                else:
                    index = math.floor((value - lo) / width)
                    index = max(0, min(9, index))

                counts[index] += 1

        result[name] = counts

