import re
from collections import Counter, defaultdict

def tfidf_scores_for_question_articles(titles, contents):
    docs = [
        content
        for title, content in zip(titles, contents)
        if "how" in title.lower() or "what" in title.lower()
    ]

    n = len(docs)
    if n == 0:
        return {}

    doc_counts = []
    df = Counter()

    for body in docs:
        counts = Counter(re.findall(r"\w{2,}", body.lower()))
        doc_counts.append(counts)
        for word in counts:
            df[word] += 1

    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1.0
        for word in df
    }

    scores = defaultdict(float)

    for counts in doc_counts:
        weights = {
            word: count * idf[word]
            for word, count in counts.items()
        }

        norm = math.sqrt(sum(value * value for value in weights.values()))
        if norm == 0:
            continue

        for word, value in weights.items():
            scores[word] += value / norm

    return dict(scores)
