import math

def normal_fit_histogram(values, bins):
    n = len(values)
    if n == 0:
        raise ValueError("values must be non-empty")
    if bins <= 0:
        raise ValueError("bins must be positive")

    mu = sum(values) / n
    sigma = math.sqrt(sum((x - mu) ** 2 for x in values) / n)

    lo = min(values)
    hi = max(values)

    if hi == lo:
        width = 1.0
    else:
        width = (hi - lo) / bins

    counts = [0] * bins

    for x in values:
        if x == hi:
            idx = bins - 1
        else:
            idx = int((x - lo) / width)
            if idx < 0:
                idx = 0
            elif idx >= bins:
                idx = bins - 1
        counts[idx] += 1

    densities = [count / (n * width) for count in counts]

    return mu, sigma, densities
