import math
from bisect import bisect_right

def summarize_distribution(values, bins):
    n = len(values)

    mean = sum(values) / n

    sorted_values = sorted(values)
    mid = n // 2
    if n % 2:
        median = float(sorted_values[mid])
    else:
        median = (sorted_values[mid - 1] + sorted_values[mid]) / 2.0

    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1

    max_count = max(counts.values())
    mode = None
    for value in values:
        if counts[value] == max_count:
            mode = value
            break

    variance = sum((value - mean) ** 2 for value in values) / n
    std_dev = math.sqrt(variance)

    min_val = min(values)
    max_val = max(values)
    histogram = [0] * bins

    if min_val == max_val:
        histogram[-1] = n
    else:
        width = (max_val - min_val) / bins
        edges = [min_val + i * width for i in range(bins + 1)]
        edges[-1] = max_val

        for value in values:
            idx = bisect_right(edges, value) - 1
            if idx < 0:
                idx = 0
            elif idx >= bins:
                idx = bins - 1
            histogram[idx] += 1

    return {
        'mean': mean,
        'median': median,
        'mode': mode,
        'std_dev': std_dev,
        'histogram': histogram,
    }

def fit_linear_regression(rows):
    import math

    if not rows:
        raise ValueError("rows must be non-empty")

    X = []
    y = []

    for row in rows:
        try:
            if len(row) != 5:
                raise ValueError
            values = [float(v) for v in row]
        except (TypeError, ValueError):
            raise ValueError("each row must contain exactly five numeric values")

        X.append([1.0] + values[:4])
        y.append(values[4])

    n = len(X)
    p = 5

    # Normal equations: (X^T X) beta = X^T y
    XtX = [[0.0] * p for _ in range(p)]
    Xty = [0.0] * p

    for xi, yi in zip(X, y):
        for j in range(p):
            Xty[j] += xi[j] * yi
            for k in range(j, p):
                XtX[j][k] += xi[j] * xi[k]

    for j in range(p):
        for k in range(j):
            XtX[j][k] = XtX[k][j]

    # Jacobi eigenvalue decomposition of the symmetric matrix XtX
    A = [row[:] for row in XtX]
    V = [[1.0 if i == j else 0.0 for j in range(p)] for i in range(p)]

    for _ in range(100):
        max_val = 0.0
        p_idx = q_idx = 0

        for i in range(p):
            for j in range(i + 1, p):
                val = abs(A[i][j])
                if val > max_val:
                    max_val = val
                    p_idx, q_idx = i, j

        max_diag = max(abs(A[i][i]) for i in range(p))
        if max_val <= 1e-14 * max(1.0, max_diag):
            break

        i, j = p_idx, q_idx
        app = A[i][i]
        aqq = A[j][j]
        apq = A[i][j]

        if abs(apq) < 1e-300:
            continue

        tau = (aqq - app) / (2.0 * apq)
        if tau >= 0.0:
            t = 1.0 / (tau + math.sqrt(1.0 + tau * tau))
        else:
            t = -1.0 / (-tau + math.sqrt(1.0 + tau * tau))

        c = 1.0 / math.sqrt(1.0 + t * t)
        s = t * c

        for k in range(p):
            if k != i and k != j:
                aik = A[i][k]
                ajk = A[j][k]
                A[i][k] = A[k][i] = c * aik - s * ajk
                A[j][k] = A[k][j] = s * aik + c * ajk

        A[i][i] = c * c * app - 2.0 * s * c * apq + s * s * aqq
        A[j][j] = s * s * app + 2.0 * s * c * apq + c * c * aqq
        A[i][j] = A[j][i] = 0.0

        for k in range(p):
            vki = V[k][i]
            vkj = V[k][j]
            V[k][i] = c * vki - s * vkj
            V[k][j] = s * vki + c * vkj

    eigenvalues = [A[i][i] for i in range(p)]
    max_eig = max(abs(v) for v in eigenvalues)
    tol = 1e-12 * max(1.0, max_eig)

    beta = [0.0] * p

    # Pseudoinverse solution using the eigen-decomposition
    for i in range(p):
        lam = eigenvalues[i]
        if abs(lam) > tol:
            v = [V[r][i] for r in range(p)]
            proj = sum(v[j] * Xty[j] for j in range(p))
            coef = proj / lam
            for j in range(p):
                beta[j] += coef * v[j]

    yhat = [sum(beta[j] * xi[j] for j in range(p)) for xi in X]

    mean_y = sum(y) / n
    sst = sum((yi - mean_y) ** 2 for yi in y)
    sse = sum((yi - yhi) ** 2 for yi, yhi in zip(y, yhat))

    if sst <= 1e-12:
        r_squared = 1.0 if sse <= 1e-12 else 0.0
    else:
        r_squared = 1.0 - sse / sst
        if abs(r_squared - 1.0) < 1e-12:
            r_squared = 1.0
        elif abs(r_squared) < 1e-12:
            r_squared = 0.0

    return beta, r_squared

