import re
from collections import Counter, defaultdict


def bracket_free_tfidf(texts):
    def strip_brackets(s):
        remove = [False] * len(s)
        stack = []

        for i, ch in enumerate(s):
            if ch == '[':
                stack.append(i)
            elif ch == ']' and stack:
                start = stack.pop()
                for j in range(start, i + 1):
                    remove[j] = True

        return ''.join(ch for i, ch in enumerate(s) if not remove[i])

    tokenized = []
    df = defaultdict(int)

    for text in texts:
        clean = strip_brackets(text)
        tokens = re.findall(r'\w{2,}', clean.lower(), flags=re.UNICODE)
        tokenized.append(tokens)

        for word in set(tokens):
            df[word] += 1

    n = len(texts)
    result = []

    for tokens in tokenized:
        if not tokens:
            result.append({})
            continue

        counts = Counter(tokens)
        scores = {}

        for word, tf in counts.items():
            idf = math.log((1 + n) / (1 + df[word])) + 1
            scores[word] = tf * idf

        norm = math.sqrt(sum(score * score for score in scores.values()))
        result.append({
            word: scores[word] / norm
            for word in sorted(scores)
        })

    return result

