        minimum = min(values)
        maximum = max(values)

        if maximum == minimum:
            normalized[name] = [0.0 for _ in values]
        else:
            span = maximum - minimum
            normalized[name] = [(value - minimum) / span for value in values]

    if not found:
        raise ValueError("None of the requested columns were found")

