def column_histogram(records, column_name):
    if not records:
        raise ValueError(f"Column {column_name!r} does not exist")

    for row in records:
        if column_name not in row:
            raise ValueError(f"Column {column_name!r} does not exist")

    values = [row[column_name] for row in records]

    # If the column contains strings, map each string to its rank
    # among the sorted distinct string values.
    if all(isinstance(v, str) for v in values):
        distinct = sorted(set(values))
        ranks = {value: i for i, value in enumerate(distinct)}
        values = [ranks[v] for v in values]

    counts = [0] * 10
    lo = min(values)
    hi = max(values)

    # If all values are equal, the maximum belongs in the last bin.
    if lo == hi:
        counts[-1] = len(values)
        return counts

    span = hi - lo

    for value in values:
        if value == hi:
            index = 9
        else:
            index = int((value - lo) * 10 / span)
            index = max(0, min(9, index))

        counts[index] += 1

    return counts
