def fit_linear_regression(rows, targets):
    if not rows or len(rows) != len(targets):
        raise ValueError("rows must be non-empty and have the same length as targets")

    n = len(rows)
    p = len(rows[0])

    for row in rows:
        if len(row) != p:
            raise ValueError("all rows must have the same number of features")

    mean_x = [sum(row[j] for row in rows) / n for j in range(p)]
    mean_y = sum(targets) / n

    if p == 0:
        return [], float(mean_y)

    sxx = [[0.0] * p for _ in range(p)]
    sxy = [0.0] * p

    for row, y in zip(rows, targets):
        dx = [row[j] - mean_x[j] for j in range(p)]
        dy = y - mean_y

        for j in range(p):
            sxy[j] += dx[j] * dy
            for k in range(p):
                sxx[j][k] += dx[j] * dx[k]

    # Solve sxx * beta = sxy using Gaussian elimination.
    a = [sxx[i][:] + [sxy[i]] for i in range(p)]

    max_abs = max((abs(sxx[i][j]) for i in range(p) for j in range(p)), default=0.0)
    eps = 1e-12 * max_abs if max_abs > 0.0 else 0.0

    row = 0
    pivot_cols = []

    for col in range(p):
        if row >= p:
            break

        pivot = max(range(row, p), key=lambda r: abs(a[r][col]))

        if abs(a[pivot][col]) > eps:
            if pivot != row:
                a[row], a[pivot] = a[pivot], a[row]

            for r in range(row + 1, p):
                factor = a[r][col] / a[row][col]
                if factor != 0.0:
                    for c in range(col, p + 1):
                        a[r][c] -= factor * a[row][c]

            pivot_cols.append(col)
            row += 1

    beta = [0.0] * p

    for i in range(len(pivot_cols) - 1, -1, -1):
        col = pivot_cols[i]
        value = a[i][p]
        for j in range(col + 1, p):
            value -= a[i][j] * beta[j]
        beta[col] = value / a[i][col]

    intercept = mean_y - sum(beta[j] * mean_x[j] for j in range(p))

    return beta, float(intercept)
