import json
import math


def _linear_quantile(sorted_values, p):
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])

    position = (n - 1) * p
    lower = int(math.floor(position))
    upper = int(math.ceil(position))

    if lower == upper:
        return float(sorted_values[lower])

    fraction = position - lower
    return float(
        sorted_values[lower]
        + (sorted_values[upper] - sorted_values[lower]) * fraction
    )


def boxplot_stats_at_path(json_data, key_path):
    try:
        data = json.loads(json_data)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Malformed JSON") from exc

    current = data
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    if not isinstance(current, str):
        raise ValueError("Data at key path is not a string")

    data_string = current.strip()
    if not data_string:
        raise ValueError("Data string is empty")

    values = []
    for part in data_string.split(","):
        token = part.strip()
        if not token:
            raise ValueError("Data string contains an empty value")

        try:
            value = float(token)
        except ValueError as exc:
            raise ValueError("Data string contains a non-numeric value") from exc

        if not math.isfinite(value):
            raise ValueError("Data string contains a non-finite value")

        values.append(value)

    values.sort()

    q1 = _linear_quantile(values, 0.25)
    median = _linear_quantile(values, 0.5)
    q3 = _linear_quantile(values, 0.75)

    iqr = q3 - q1
    lower_fence = q1 - 1.5 * iqr
    upper_fence = q3 + 1.5 * iqr

    within_fences = [
        value for value in values
        if lower_fence <= value <= upper_fence
    ]

    whisker_low = min(within_fences)
    whisker_high = max(within_fences)

    outliers = [
        float(value) for value in values
        if value < lower_fence or value > upper_fence
    ]

    return {
        "q1": q1,
        "median": median,
        "q3": q3,
        "whisker_low": float(whisker_low),
        "whisker_high": float(whisker_high),
        "outliers": outliers,
    }
