def _parse_date(date_string):
    s = date_string.strip().lower()
    for ch in ",./-":
        s = s.replace(ch, " ")
    tokens = s.split()

    month_names = {
        "january": 1, "february": 2, "march": 3, "april": 4,
        "may": 5, "june": 6, "july": 7, "august": 8,
        "september": 9, "october": 10, "november": 11, "december": 12,
        "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
        "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10,
        "nov": 11, "dec": 12,
    }

    month = None
    numbers = []

    for token in tokens:
        if token in month_names:
            month = month_names[token]
        elif token.isdigit():
            numbers.append(int(token))
        else:
            match = re.fullmatch(r"(\d+)(st|nd|rd|th)?", token)
            if match:
                numbers.append(int(match.group(1)))
            else:
                raise ValueError(f"Unrecognized token {token!r} in date string {date_string!r}")

    if month is not None:
        year = None
        for i, n in enumerate(numbers):
            if n > 31:
                year = n
                numbers.pop(i)
                break

        if year is None:
            if not numbers:
                raise ValueError(f"No year found in date string {date_string!r}")
            year = numbers.pop()

        if len(numbers) != 1:
            raise ValueError(f"Could not parse day from date string {date_string!r}")

        day = numbers[0]

    else:
        if len(numbers) != 3:
            raise ValueError(f"Could not parse date string {date_string!r}")

        a, b, c = numbers

        if a > 31:
            year, month, day = a, b, c
        elif c > 31 or len(str(c)) == 4:
            year = c
            if a > 12:
                day, month = a, b
            elif b > 12:
                month, day = a, b
            else:
                month, day = a, b
        else:
            year = c
            if a > 12:
                day, month = a, b
            elif b > 12:
                month, day = a, b
            else:
                month, day = a, b

    if year < 100:
        year += 2000 if year <= 68 else 1900

    return date(year, month, day)


