            idx = bins - 1
        else:
            idx = int((x - lo) / width)
            if idx < 0:
                idx = 0
            elif idx >= bins:
                idx = bins - 1
        counts[idx] += 1

    densities = [count / (n * width) for count in counts]
    return mu, sigma, densities

