import xml.etree.ElementTree as ET

def xml_to_dict(s):
    if not s or not s.strip():
        raise ValueError("XML input is empty or whitespace")

    try:
        root = ET.fromstring(s)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML: {e}") from e

    def element_value(elem):
        children = list(elem)
        attrs = {f"@{k}": v for k, v in elem.attrib.items()}

        # Collect text directly inside this element, including text after children.
        text_parts = []
        if elem.text is not None:
            text_parts.append(elem.text)
        for child in children:
            if child.tail is not None:
                text_parts.append(child.tail)
        text = "".join(text_parts)

        # Text-only element or empty element.
        if not attrs and not children:
            return text if text != "" else None

        result = {}
        result.update(attrs)

        grouped_children = {}
        for child in children:
            tag = child.tag
            value = element_value(child)

            if tag in grouped_children:
                if not isinstance(grouped_children[tag], list):
                    grouped_children[tag] = [grouped_children[tag]]
                grouped_children[tag].append(value)
            else:
                grouped_children[tag] = value

        result.update(grouped_children)

        if text != "":
            result["#text"] = text

        return result

    return {root.tag: element_value(root)}
