from datetime import date, timedelta

def second_friday_sales_report(start_date, periods, categories, sales):
    def second_friday(year, month):
        first_day = date(year, month, 1)
        # Monday = 0, Friday = 4
        days_until_friday = (4 - first_day.weekday()) % 7
        first_friday = first_day + timedelta(days=days_until_friday)
        return first_friday + timedelta(days=7)

    year, month, day = map(int, start_date.split("-"))
    current_start = date(year, month, day)

    year, month = current_start.year, current_start.month
    report_dates = []

    while len(report_dates) < periods:
        date_for_month = second_friday(year, month)

        if date_for_month >= current_start:
            report_dates.append(date_for_month)

        if month == 12:
            year += 1
            month = 1
        else:
            month += 1

    result = []
    sales_index = 0

    for report_date in report_dates:
        date_string = report_date.isoformat()

        for category in categories:
            result.append((date_string, category, sales[sales_index]))
            sales_index += 1

    return result

