import math

def threshold_and_standardize(data):
    if not data:
        return []

    nrows = len(data)
    ncols = len(data[0])

    # Copy and apply threshold
    result = [[0.0] * ncols for _ in range(nrows)]
    for i in range(nrows):
        for j in range(ncols):
            value = data[i][j]
            result[i][j] = 0.0 if value < 0.5 else float(value)

    # Standardize each column
    for j in range(ncols):
        mean = sum(result[i][j] for i in range(nrows)) / nrows
        variance = sum((result[i][j] - mean) ** 2 for i in range(nrows)) / nrows
        std = math.sqrt(variance)

        if std == 0.0:
            for i in range(nrows):
                result[i][j] = 0.0
        else:
            for i in range(nrows):
                result[i][j] = (result[i][j] - mean) / std

    return result
