    class _TableParser(HTMLParser):
        def __init__(self, wanted_id):
            super().__init__(convert_charrefs=True)
            self.wanted_id = wanted_id
            self.seen_target = False
            self.done = False
            self.target_depth = 0
            self.rows = []
            self.current_row = None
            self.current_cell = None

        def handle_starttag(self, tag, attrs):
            if self.done:
                return

            tag = tag.lower()

            if not self.seen_target:
                if tag == "table":
                    for key, value in attrs:
                        if key.lower() == "id" and value == self.wanted_id:
                            self.seen_target = True
                            self.target_depth = 1
                            self.rows = []
                            self.current_row = None
                            self.current_cell = None
                            break
                return

            if tag == "table":
                self.target_depth += 1
                return

            if self.target_depth > 1:
                return

            if tag == "tr":
                if self.current_row is not None:
                    self._finish_cell()
                    self._finish_row()
                self.current_row = []
                self.current_cell = None
            elif tag in ("td", "th"):
                if self.current_cell is not None:
                    self._finish_cell()
                if self.current_row is None:
                    self.current_row = []
                self.current_cell = []

        def handle_startendtag(self, tag, attrs):
            self.handle_starttag(tag, attrs)
            self.handle_endtag(tag)

        def handle_endtag(self, tag):
            if self.done or not self.seen_target:
                return

            tag = tag.lower()

            if tag == "table":
                if self.target_depth == 1:
                    self._finish_cell()
                    self._finish_row()
                    self.done = True
                else:
                    self.target_depth -= 1
                return

            if self.target_depth > 1:
                return

            if tag == "tr":
                self._finish_cell()
                self._finish_row()
            elif tag in ("td", "th"):
                self._finish_cell()

        def handle_data(self, data):
            if self.done or not self.seen_target:
                return
            if self.current_cell is not None:
                self.current_cell.append(data)

        def _finish_cell(self):
            if self.current_cell is not None:
                if self.current_row is None:
                    self.current_row = []
                self.current_row.append("".join(self.current_cell).strip())
                self.current_cell = None

        def _finish_row(self):
            if self.current_row is not None:
                self.rows.append(self.current_row)
                self.current_row = None
                self.current_cell = None

    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.seen_target:
        raise ValueError(f"No table with id {table_id!r}")

    if not parser.done:
        parser._finish_cell()
        parser._finish_row()

    if not parser.rows:
        return []

    headers = parser.rows[0]
    records = []

    for row in parser.rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ""
        records.append(record)

    return records
