import math
from io import StringIO


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    def parse_number(value):
        try:
            return int(value)
        except (ValueError, TypeError):
            try:
                number = float(value)
            except (ValueError, TypeError):
                return None
            return number if math.isfinite(number) else None

    columns = None
    raw_rows = []

    for text in csv_texts:
        reader = csv.reader(StringIO(text))
        try:
            header = next(reader)
        except StopIteration:
            continue

        if columns is None:
            columns = header

        for row in reader:
            if not row:
                continue
            raw_rows.append(dict(zip(header, row)))

    if columns is None:
        return []

    numeric_columns = {}

    for col in columns:
        converted_values = []
        is_numeric = True

        for row in raw_rows:
            value = parse_number(row[col])
            if value is None:
                is_numeric = False
                break
            converted_values.append(value)

        if is_numeric:
            numeric_columns[col] = converted_values

    result = []
    for i, row in enumerate(raw_rows):
        result.append({
            col: numeric_columns[col][i] if col in numeric_columns else row[col]
            for col in columns
        })

    return result
