import math

def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = list(data.keys())
    mapped_data = {
        col: [mapping.get(value, value) for value in data[col]]
        for col in columns
    }

    result = {}

    for a in columns:
        result[a] = {}
        xs = mapped_data[a]
        n = len(xs)

        if n == 0:
            for b in columns:
                result[a][b] = 1.0 if a == b else float("nan")
            continue

        mean_x = sum(xs) / n
        dx = [x - mean_x for x in xs]
        var_x = sum(d * d for d in dx)

        for b in columns:
            if a == b:
                result[a][b] = 1.0
                continue

            ys = mapped_data[b]
            mean_y = sum(ys) / n
            dy = [y - mean_y for y in ys]
            var_y = sum(d * d for d in dy)

            covariance = sum(x * y for x, y in zip(dx, dy))
            denominator = math.sqrt(var_x * var_y)

            if denominator == 0:
                result[a][b] = float("nan")
            else:
                result[a][b] = covariance / denominator

    return result
