import csv
import io
import re
from collections import Counter

def top_ten_words_from_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        next(reader)  # skip header
    except StopIteration:
        return []

    stopwords = {"a", "an", "the", "in", "on", "at", "and", "or"}
    word_pattern = re.compile(r"\w{2,}", re.UNICODE)
    counts = Counter()

    for row in reader:
        if not row:
            continue

        text = row[0]
        for word in word_pattern.findall(text):
            word = word.lower()
            if word not in stopwords:
                counts[word] += 1

    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:10]
