def box_blur(image, kernel_size):
    if (
        not isinstance(kernel_size, int)
        or isinstance(kernel_size, bool)
        or kernel_size <= 0
        or kernel_size % 2 == 0
    ):
        raise ValueError("kernel_size must be a positive odd integer")

    if not image:
        return []

    h = len(image)
    if h == 0:
        return []

    w = len(image[0])
    if w == 0:
        return [[] for _ in range(h)]

    channels = len(image[0][0])
    radius = kernel_size // 2
    k = kernel_size

    def mirror(index, size):
        if size == 1:
            return 0
        period = 2 * size - 2
        index %= period
        if index < size:
            return index
        return period - index

    # Horizontal pass: sum over kernel_size columns.
    horizontal = [
        [[0.0 for _ in range(channels)] for _ in range(w)]
        for _ in range(h)
    ]

    extended_w = w + 2 * radius

    for y in range(h):
        prefix = [[0.0] * (extended_w + 1) for _ in range(channels)]
        row = image[y]

        for p in range(extended_w):
            sx = mirror(p - radius, w)
            pixel = row[sx]
            for c in range(channels):
                prefix[c][p + 1] = prefix[c][p] + pixel[c]

        for x in range(w):
            for c in range(channels):
                horizontal[y][x][c] = (
                    prefix[c][x + k] - prefix[c][x]
                )

    # Vertical pass: sum over kernel_size rows and average.
    result = [
        [[0.0 for _ in range(channels)] for _ in range(w)]
        for _ in range(h)
    ]

    extended_h = h + 2 * radius
    denominator = float(k * k)

    for x in range(w):
        for c in range(channels):
            prefix = [0.0] * (extended_h + 1)

            for p in range(extended_h):
                sy = mirror(p - radius, h)
                prefix[p + 1] = prefix[p] + horizontal[sy][x][c]

            for y in range(h):
                total = prefix[y + k] - prefix[y]
                result[y][x][c] = total / denominator

    return result
