def cluster_centroids(points, k):
    if k <= 0:
        return []
    if not points:
        return []
    if k > len(points):
        raise ValueError("k cannot be greater than the number of points")

    pts = [(float(x), float(y)) for x, y in points]

    # Deterministic farthest-first initialization.
    centers = [pts[0]]
    while len(centers) < k:
        best_idx = 0
        best_dist = -1.0

        for i, p in enumerate(pts):
            min_dist = min(
                (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2
                for c in centers
            )
            if min_dist > best_dist:
                best_dist = min_dist
                best_idx = i

        centers.append(pts[best_idx])

    # Lloyd's k-means algorithm.
    for _ in range(100):
        clusters = [[] for _ in range(k)]

        for p in pts:
            distances = [
                (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2
                for c in centers
            ]
            label = min(range(k), key=lambda i: distances[i])
            clusters[label].append(p)

        new_centers = []
        for i, cluster in enumerate(clusters):
            if cluster:
                sx = sum(p[0] for p in cluster) / len(cluster)
                sy = sum(p[1] for p in cluster) / len(cluster)
                new_centers.append((sx, sy))
            else:
                new_centers.append(centers[i])

        converged = all(
            abs(new_centers[i][0] - centers[i][0]) < 1e-12
            and abs(new_centers[i][1] - centers[i][1]) < 1e-12
            for i in range(k)
        )

        centers = new_centers
        if converged:
            break

    return sorted((float(x), float(y)) for x, y in centers)
