from datetime import date, datetime
import calendar
import re


def forecast_schedule(start_date, freq, sales):
    # Validate strict YYYY-MM-DD start date
    if not isinstance(start_date, str) or not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", start_date):
        raise ValueError("Invalid start date")

    try:
        start = datetime.strptime(start_date, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("Invalid start date")

    def last_day(year, month):
        return date(year, month, calendar.monthrange(year, month)[1])

    def add_months(year, month, count):
        index = year * 12 + (month - 1) + count
        return index // 12, index % 12 + 1

    def nth_weekday(year, month, n, weekday):
        first = date(year, month, 1)
        offset = (weekday - first.weekday()) % 7
        return date(year, month, 1 + offset + (n - 1) * 7)

    result = []

    if freq == "month-end":
        year, month = start.year, start.month
        current = last_day(year, month)

        if current < start:
            year, month = add_months(year, month, 1)
            current = last_day(year, month)

        for value in sales:
            result.append((current.isoformat(), value))
            year, month = add_months(year, month, 1)
            current = last_day(year, month)

        return result

    if freq == "quarter-end":
        year, month = start.year, start.month

        while not (month in (3, 6, 9, 12) and last_day(year, month) >= start):
            year, month = add_months(year, month, 1)

        for value in sales:
            current = last_day(year, month)
            result.append((current.isoformat(), value))
            year, month = add_months(year, month, 3)

        return result

    match = re.fullmatch(r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", freq)
    if not match:
        raise ValueError("Invalid frequency")

    n = int(match.group(1))
    weekdays = {
        "MON": 0,
        "TUE": 1,
        "WED": 2,
        "THU": 3,
        "FRI": 4,
        "SAT": 5,
        "SUN": 6,
    }
    weekday = weekdays[match.group(2)]

    year, month = start.year, start.month
    current = nth_weekday(year, month, n, weekday)

    if current < start:
        year, month = add_months(year, month, 1)
        current = nth_weekday(year, month, n, weekday)

    for value in sales:
        result.append((current.isoformat(), value))
        year, month = add_months(year, month, 1)
        current = nth_weekday(year, month, n, weekday)

    return result

