def country_score_summary(records):
    if not records:
        raise ValueError("records must not be empty")

    required_keys = ("Name", "Country", "Score")
    seen_names = set()
    scores_by_country = {}

    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in required_keys):
            raise ValueError("Each record must contain 'Name', 'Country', and 'Score'")

        name = record["Name"]
        if name in seen_names:
            continue

        seen_names.add(name)
        country = record["Country"]
        scores_by_country.setdefault(country, []).append(record["Score"])

    def quantile(sorted_values, p):
        n = len(sorted_values)
        if n == 1:
            return float(sorted_values[0])

        position = (n - 1) * p
        lower = int(position)
        upper = min(lower + 1, n - 1)
        fraction = position - lower

        return float(
            sorted_values[lower]
            + (sorted_values[upper] - sorted_values[lower]) * fraction
        )

    result = {}

    for country, scores in scores_by_country.items():
        scores = sorted(scores)

        result[country] = [
            float(scores[0]),
            quantile(scores, 0.25),
            quantile(scores, 0.5),
            quantile(scores, 0.75),
            float(scores[-1]),
        ]

    return result
