from numbers import Real

def column_covariance(columns):
    if not columns:
        raise ValueError("table has no columns")

    names = list(columns)
    n = len(columns[names[0]])

    if n == 0:
        raise ValueError("table has no rows")

    for name in names:
        if len(columns[name]) != n:
            raise ValueError("all columns must have the same length")
        for value in columns[name]:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise TypeError(f"column {name!r} contains a non-numeric value")

    if n < 2:
        raise ValueError("table must have at least two rows")

    data = {name: [float(v) for v in columns[name]] for name in names}
    means = {name: sum(values) / n for name, values in data.items()}

    result = {}
    for a in names:
        result[a] = {}
        for b in names:
            covariance = sum(
                (x - means[a]) * (y - means[b])
                for x, y in zip(data[a], data[b])
            ) / (n - 1)
            result[a][b] = covariance

    return result
