        raise ValueError("n_clusters must be positive")
    if n_clusters > n:
        raise ValueError("n_clusters cannot exceed the number of points")
    if n_clusters == 1:
        return [list(range(n))]

    # Deterministic k-means++ initialization.
    chosen = [0]
    while len(chosen) < n_clusters:
        best_i = None
        best_d = -1.0
        for i in range(n):
            if i in chosen:
                continue
            d = min(dist2(points[i], points[j]) for j in chosen)
            if d > best_d:
                best_d = d
                best_i = i
        chosen.append(best_i)

    centers = [list(points[i]) for i in chosen]
    labels = None

    for _ in range(300):
        new_labels = []

        for p in points:
            best_j = 0
            best_d = dist2(p, centers[0])

            for j in range(1, n_clusters):
                d = dist2(p, centers[j])
                if d < best_d:
                    best_d = d
                    best_j = j

            new_labels.append(best_j)

