from collections import Counter

def summarize_student_records(data):
    required_keys = ('Name', 'Age', 'Score')
    if any(key not in data for key in required_keys):
        raise ValueError("Missing one or more required keys: 'Name', 'Age', 'Score'")

    records = [
        [name, age, score]
        for name, age, score in zip(data['Name'], data['Age'], data['Score'])
    ]

    sorted_records = sorted(records, key=lambda record: (record[0], record[1]))

    totals = {}
    counts = {}

    for name, age, score in records:
        totals[name] = totals.get(name, 0) + score
        counts[name] = counts.get(name, 0) + 1

    averages = {
        name: totals[name] / counts[name]
        for name in sorted(totals)
    }

    ages = [record[1] for record in records]
    most_common_age = Counter(ages).most_common(1)[0][0] if ages else None

    return sorted_records, averages, most_common_age
