from html.parser import HTMLParser
from urllib.parse import urljoin


def extract_absolute_links(html, base_url):
    class LinkParser(HTMLParser):
        def __init__(self):
            super().__init__()
            self.links = set()

        def handle_starttag(self, tag, attrs):
            if tag != "a":
                return

            href = None
            for name, value in attrs:
                if name == "href":
                    href = value if value is not None else ""
                    break

            if href is not None:
                self.links.add(urljoin(base_url, href))

    parser = LinkParser()
    parser.feed(html)
    parser.close()

    return sorted(parser.links)
