def _parse_number(value):
    """Parse a CSV value as an int or float, or raise ValueError if not numeric."""
    if value is None:
        raise ValueError
    s = value.strip()
    if not s:
        raise ValueError

    try:
        return int(s)
    except ValueError:
        number = float(s)
        if not math.isfinite(number):
            raise ValueError
        return number


def sort_csv_rows(csv_text, sort_key):
    reader = csv.DictReader(io.StringIO(csv_text))
    fieldnames = reader.fieldnames

    if fieldnames is None or sort_key not in fieldnames:
        raise ValueError(f"Column {sort_key!r} does not exist")

    rows = []
    for row in reader:
        rows.append({
            col: row.get(col) if row.get(col) is not None else ""
            for col in fieldnames
        })

    # Convert every column whose values are all numeric.
    for col in fieldnames:
        parsed_values = []
        all_numeric = True

        for row in rows:
            try:
                parsed_values.append(_parse_number(row[col]))
            except (ValueError, TypeError):
                all_numeric = False
                break

        if all_numeric and rows:
            for row, value in zip(rows, parsed_values):
                row[col] = value

    rows.sort(key=lambda row: row[sort_key])
    return rows
