def kmeans_clusters(xs, ys, n_clusters):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")

    points = list(zip(xs, ys))
    n = len(points)
    if n_clusters > n:
        raise ValueError("n_clusters cannot exceed the number of points")
    if n_clusters == 1:
        return [list(range(n))]

    # Initialize centroids using the first n_clusters points
    centroids = points[:n_clusters]

    while True:
        clusters = [[] for _ in range(n_clusters)]

        # Assign each point to the nearest centroid
        for i, (x, y) in enumerate(points):
            best = 0
            best_dist = float("inf")
            for j, (cx, cy) in enumerate(centroids):
                d = (x - cx) ** 2 + (y - cy) ** 2
                if d < best_dist:
                    best_dist = d
                    best = j
            clusters[best].append(i)

        # Recompute centroids
        new_centroids = []
        for j, cluster in enumerate(clusters):
            if cluster:
                avg_x = sum(points[i][0] for i in cluster) / len(cluster)
                avg_y = sum(points[i][1] for i in cluster) / len(cluster)
                new_centroids.append((avg_x, avg_y))
            else:
                # Keep the previous centroid if a cluster becomes empty
                new_centroids.append(centroids[j])

        if new_centroids == centroids:
            break
        centroids = new_centroids

    # Sort each cluster and then order clusters by their smallest index
    clusters = [sorted(cluster) for cluster in clusters]
    clusters.sort(key=lambda c: c[0] if c else float("inf"))
    return clusters

