def numeric_correlation_from_json(json_text):
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("Data is empty or not a JSON object")

    numeric_columns = {}
    row_count = None

    for column, values in data.items():
        if not isinstance(values, list):
            raise ValueError("Each column must be a list")

        if row_count is None:
            row_count = len(values)
        elif len(values) != row_count:
            raise ValueError("All columns must have equal length")

        # A column is numeric only if every value is a non-boolean number.
        if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in values):
            numeric_columns[column] = [float(v) for v in values]

    if row_count is None or row_count == 0:
        raise ValueError("Data is empty")

    if not numeric_columns:
        return {}

    means = {
        column: sum(values) / row_count
        for column, values in numeric_columns.items()
    }

    centered = {
        column: [value - means[column] for value in values]
        for column, values in numeric_columns.items()
    }

    sum_squares = {
        column: sum(value * value for value in centered[column])
        for column in numeric_columns
    }

    result = {}

    for a in numeric_columns:
        result[a] = {}
        for b in numeric_columns:
            if a == b:
                result[a][b] = 1.0 if sum_squares[a] > 0 else float("nan")
                continue

            denominator = math.sqrt(sum_squares[a] * sum_squares[b])
            if denominator == 0:
                result[a][b] = float("nan")
            else:
                covariance_sum = sum(
                    x * y for x, y in zip(centered[a], centered[b])
                )
                result[a][b] = covariance_sum / denominator

    return result
