        sum(row[j] for row in data) / n_rows
        for j in range(n_cols)
    ]

    constant = [
        all(row[j] == data[0][j] for row in data)
        for j in range(n_cols)
    ]

    stds = []
    for j in range(n_cols):
        if constant[j]:
            stds.append(0.0)
        else:
