def classification_summary(y_true, y_pred):
    if len(y_true) != len(y_pred):
        raise ValueError("y_true and y_pred must have the same length")

    labels = []
    seen = set()

    for label in y_true:
        if label not in seen:
            seen.add(label)
            labels.append(label)

    for label in y_pred:
        if label not in seen:
            seen.add(label)
            labels.append(label)

    support = {label: 0 for label in labels}
    predicted_count = {label: 0 for label in labels}
    true_positive = {label: 0 for label in labels}

    correct = 0

    for true_label, pred_label in zip(y_true, y_pred):
        support[true_label] += 1
        predicted_count[pred_label] += 1

        if true_label == pred_label:
            true_positive[true_label] += 1
            correct += 1

    result = {}

    for label in labels:
        tp = true_positive[label]
        support_count = support[label]
        predicted = predicted_count[label]

        precision = tp / predicted if predicted else 0.0
        recall = tp / support_count if support_count else 0.0
        f1 = (
            2 * precision * recall / (precision + recall)
            if precision + recall
            else 0.0
        )

        result[label] = (precision, recall, f1, support_count)

    total_count = len(y_true)
    result["accuracy"] = correct / total_count if total_count else 0.0

    if labels:
        macro_precision = sum(result[label][0] for label in labels) / len(labels)
        macro_recall = sum(result[label][1] for label in labels) / len(labels)
        macro_f1 = sum(result[label][2] for label in labels) / len(labels)
    else:
        macro_precision = macro_recall = macro_f1 = 0.0

    result["macro avg"] = (
        macro_precision,
        macro_recall,
        macro_f1,
        total_count,
    )

    if total_count:
        weighted_precision = sum(
            result[label][0] * support[label] for label in labels
        ) / total_count
        weighted_recall = sum(
            result[label][1] * support[label] for label in labels
        ) / total_count
        weighted_f1 = sum(
            result[label][2] * support[label] for label in labels
        ) / total_count
    else:
        weighted_precision = weighted_recall = weighted_f1 = 0.0

    result["weighted avg"] = (
        weighted_precision,
        weighted_recall,
        weighted_f1,
        total_count,
    )

    return result
