        macro_recall = sum(result[label][1] for label in labels) / len(labels)
        macro_f1 = sum(result[label][2] for label in labels) / len(labels)
    else:
        macro_precision = macro_recall = macro_f1 = 0.0

    result["macro avg"] = (
        macro_precision,
        macro_recall,
        macro_f1,
        total_count,
    )

    if total_count:
        weighted_precision = sum(
            result[label][0] * support[label] for label in labels
        ) / total_count
        weighted_recall = sum(
            result[label][1] * support[label] for label in labels
        ) / total_count
        weighted_f1 = sum(
            result[label][2] * support[label] for label in labels
        ) / total_count
    else:
        weighted_precision = weighted_recall = weighted_f1 = 0.0

    result["weighted avg"] = (
        weighted_precision,
        weighted_recall,
        weighted_f1,
        total_count,
    )

