def standardize_with_row_means(data):
    """
    Standardize each column to zero mean and unit population variance,
    then append each row's standardized-value mean.
    """
    if not data:
        return []

    n_rows = len(data)
    n_cols = len(data[0])

    column_means = [
        sum(row[j] for row in data) / n_rows
        for j in range(n_cols)
    ]

    column_stds = []
    for j in range(n_cols):
        mean = column_means[j]
        variance = sum((row[j] - mean) ** 2 for row in data) / n_rows
        column_stds.append(variance ** 0.5)

    result = []

    for row in data:
        standardized_row = []

        for j, value in enumerate(row):
            if column_stds[j] == 0:
                standardized_row.append(0.0)
            else:
                standardized_row.append(
                    (value - column_means[j]) / column_stds[j]
                )

        row_mean = sum(standardized_row) / len(standardized_row)
        result.append(standardized_row + [row_mean])

    return result
