from bisect import bisect_right

def complete_row_histogram(data, bins):
    if not data:
        return {}, None

    columns = list(data.keys())
    n = len(data[columns[0]])
    cleaned = {col: [] for col in columns}
    pooled = []

    for i in range(n):
        row = [data[col][i] for col in columns]
        if any(v is None for v in row):
            continue
        for col, v in zip(columns, row):
            fv = float(v)
            cleaned[col].append(fv)
            pooled.append(fv)

    if not pooled:
        return cleaned, None

    lo = min(pooled)
    hi = max(pooled)

    if lo == hi:
        return cleaned, None

    edges = [lo + (hi - lo) * i / bins for i in range(bins)] + [hi]
    counts = [0] * bins

    for v in pooled:
        if v == hi:
            idx = bins - 1
        else:
            idx = bisect_right(edges, v) - 1
            if idx < 0:
                idx = 0
            elif idx >= bins:
                idx = bins - 1
        counts[idx] += 1

    return cleaned, counts
