import math

def correlation_matrix_from_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        headers = next(reader)
    except StopIteration:
        return {}

    rows = []
    for row in reader:
        if row:
            rows.append([float(value) for value in row])

    if not rows:
        return {
            h: {g: 1.0 if h == g else float("nan") for g in headers}
            for h in headers
        }

    columns = list(zip(*rows))
    means = [sum(col) / len(col) for col in columns]
    denoms = [
        math.sqrt(sum((x - mean) ** 2 for x in col))
        for col, mean in zip(columns, means)
    ]

    result = {h: {} for h in headers}

    for i, a in enumerate(headers):
        for j, b in enumerate(headers):
            if i == j:
                corr = 1.0
            else:
                denominator = denoms[i] * denoms[j]
                if denominator == 0:
                    corr = float("nan")
                else:
                    numerator = sum(
                        (x - means[i]) * (y - means[j])
                        for x, y in zip(columns[i], columns[j])
                    )
                    corr = numerator / denominator

            result[a][b] = corr

    return result
