import math

def cluster_labels(rows):
    if not rows:
        return []

    n = len(rows)
    d = len(rows[0])

    # Standardize each column to zero mean and unit variance.
    means = []
    stds = []
    for j in range(d):
        col = [float(row[j]) for row in rows]
        mean = sum(col) / n
        var = sum((x - mean) ** 2 for x in col) / n
        std = math.sqrt(var) if var > 0 else 1.0
        means.append(mean)
        stds.append(std)

    X = [
        [(float(rows[i][j]) - means[j]) / stds[j] for j in range(d)]
        for i in range(n)
    ]

    k = min(3, n)
    if k == 0:
        return []
    if k == 1:
        return [0] * n

    # Deterministic farthest-first initialization.
    center_indices = [0]
    for _ in range(1, k):
        best_idx = None
        best_dist = -1.0
        for i in range(n):
            if i in center_indices:
                continue
            min_dist = min(
                sum((X[i][j] - X[c][j]) ** 2 for j in range(d))
                for c in center_indices
            )
            if min_dist > best_dist:
                best_dist = min_dist
                best_idx = i
        center_indices.append(best_idx)

    centers = [X[i][:] for i in center_indices]
    labels = [-1] * n

    # Lloyd's algorithm.
    for _ in range(100):
        changed = False
        new_labels = []

        for i in range(n):
            best_c = 0
            best_dist = float("inf")
            for c in range(k):
                dist = sum((X[i][j] - centers[c][j]) ** 2 for j in range(d))
                if dist < best_dist:
                    best_dist = dist
                    best_c = c
            new_labels.append(best_c)
            if labels[i] != best_c:
                changed = True

        labels = new_labels

        new_centers = []
        for c in range(k):
            members = [X[i] for i in range(n) if labels[i] == c]
            if members:
                new_centers.append([
                    sum(m[j] for m in members) / len(members)
                    for j in range(d)
                ])
            else:
                new_centers.append(centers[c][:])
        centers = new_centers

        if not changed:
            break

    # Renumber clusters by first appearance.
    mapping = {}
    result = []
    next_label = 0

    for lab in labels:
        if lab not in mapping:
            mapping[lab] = next_label
            next_label += 1
        result.append(mapping[lab])

    return result
