from datetime import datetime


def _to_microseconds(delta):
    return (delta.days * 24 * 60 * 60 + delta.seconds) * 1_000_000 + delta.microseconds


def date_histogram(dates, date_format):
    if not dates:
        return [0] * 10

    parsed = [datetime.strptime(date, date_format) for date in dates]

    earliest = min(parsed)
    latest = max(parsed)

    counts = [0] * 10

    if earliest == latest:
        counts[-1] = len(parsed)
        return counts

    span = _to_microseconds(latest - earliest)

    for date in parsed:
        if date == latest:
            index = 9
        else:
            offset = _to_microseconds(date - earliest)
            index = (offset * 10) // span

        counts[index] += 1

    return counts

