    m = p + 1

    X = []
    y = []
    for frow, trow in joined:
        X.append([1.0] + [float(frow[f]) for f in features])
        y.append(float(trow[target]))

    # Build normal equations: (X^T X) beta = X^T y
    XtX = [[0.0] * m for _ in range(m)]
    Xty = [0.0] * m

    for row, val in zip(X, y):
        for i in range(m):
            Xty[i] += row[i] * val
            for j in range(m):
                XtX[i][j] += row[i] * row[j]

    # Solve with Gauss-Jordan elimination and partial pivoting
    A = [XtX[i][:] + [Xty[i]] for i in range(m)]

    for col in range(m):
        pivot = max(range(col, m), key=lambda r: abs(A[r][col]))

        if abs(A[pivot][col]) < 1e-12:
            raise ValueError("Singular design matrix")

        A[col], A[pivot] = A[pivot], A[col]

        pv = A[col][col]
        for j in range(col, m + 1):
            A[col][j] /= pv

        for r in range(m):
            if r == col:
                continue
            factor = A[r][col]
            if factor != 0.0:
                for j in range(col, m + 1):
                    A[r][j] -= factor * A[col][j]

    beta = [A[i][m] for i in range(m)]

