    coefficients = beta[1:]

    residuals = []
    for row, observed in zip(X, y):
        predicted = sum(row[i] * beta[i] for i in range(m))
        residuals.append(observed - predicted)

    return {
        "coefficients": coefficients,
        "intercept": intercept,
        "residuals": residuals,
