from collections import defaultdict

def fruit_sales_box_stats(records):
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = defaultdict(list)

    for fruit, _day, sales in records:
        sales_by_fruit[fruit].append(sales)

    def percentile(sorted_values, p):
        n = len(sorted_values)
        if n == 1:
            return float(sorted_values[0])

        position = (n - 1) * p
        lower = int(position)
        upper = min(lower + 1, n - 1)
        fraction = position - lower

        return float(
            sorted_values[lower]
            + (sorted_values[upper] - sorted_values[lower]) * fraction
        )

    result = {}

    for fruit, sales in sales_by_fruit.items():
        sorted_sales = sorted(sales)
        result[fruit] = (
            percentile(sorted_sales, 0.00),
            percentile(sorted_sales, 0.25),
            percentile(sorted_sales, 0.50),
            percentile(sorted_sales, 0.75),
            percentile(sorted_sales, 1.00),
        )

    return result
