def column_summary_stats(table, mapping, features):
    results = {}

    for feature in features:
        if feature not in table:
            raise ValueError(f"Feature {feature!r} is not in table")

        values = [mapping.get(v, v) for v in table[feature]]
        n = len(values)

        if n == 0:
            raise ValueError(f"Feature {feature!r} has no values")

        mean = sum(values) / n

        ordered = sorted(values)
        mid = n // 2
        if n % 2:
            median = float(ordered[mid])
        else:
            median = (ordered[mid - 1] + ordered[mid]) / 2.0

        counts = {}
        for value in values:
            counts[value] = counts.get(value, 0) + 1

        mode = min(counts.items(), key=lambda item: (-item[1], item[0]))[0]

        variance = sum((value - mean) ** 2 for value in values) / n

        results[feature] = {
            'mean': mean,
            'median': median,
            'mode': mode,
            'variance': variance,
        }

    return results
