import math

def standardize_columns(rows, scale_cols):
    if not rows:
        return []

    n = len(rows)
    scale_cols = set(scale_cols)
    stats = {}

    for col in scale_cols:
        values = [row[col] for row in rows]
        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = math.sqrt(variance)
        stats[col] = (mean, std)

    result = []
    for row in rows:
        new_row = list(row)
        for col in scale_cols:
            mean, std = stats[col]
            if std == 0:
                new_row[col] = 0.0
            else:
                new_row[col] = (row[col] - mean) / std
        result.append(new_row)

    return result
