from html.parser import HTMLParser

class _LinkExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []       # list of (href, text_parts)
        self._open = []       # active anchors' text_parts lists

    @staticmethod
    def _get_href(attrs):
        for name, value in attrs:
            if name.lower() == "href":
                return "" if value is None else value
        return None

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "a":
            href = self._get_href(attrs)
            parts = []
            self.links.append((href, parts))
            self._open.append(parts)

    def handle_startendtag(self, tag, attrs):
        if tag.lower() == "a":
            href = self._get_href(attrs)
            self.links.append((href, []))

    def handle_data(self, data):
        for parts in self._open:
            parts.append(data)

    def handle_endtag(self, tag):
        if tag.lower() == "a" and self._open:
            self._open.pop()


def extract_links(html):
    parser = _LinkExtractor()
    parser.feed(html)
    parser.close()
    return [("".join(parts), href) for href, parts in parser.links]
