def row_zscores_and_correlation(data):
    zscores = []

    # Standardise each row using its mean and population standard deviation.
    for row in data:
        n = len(row)
        if n == 0:
            zscores.append([])
            continue

        mean = sum(row) / n
        variance = sum((x - mean) ** 2 for x in row) / n
        std = variance ** 0.5

        if std == 0:
            zscores.append([0.0 for _ in row])
        else:
            zscores.append([(x - mean) / std for x in row])

    if not zscores:
        return zscores, []

    n_rows = len(zscores)
    n_cols = len(zscores[0])

    # Extract columns of the z-score matrix.
    columns = [
        [zscores[r][c] for r in range(n_rows)]
        for c in range(n_cols)
    ]

    column_means = []
    centered_columns = []
    sum_squares = []

    for col in columns:
        mean = sum(col) / n_rows
        centered = [x - mean for x in col]
        column_means.append(mean)
        centered_columns.append(centered)
        sum_squares.append(sum(x * x for x in centered))

    # Pearson correlation matrix between columns.
    correlation = []
    for i in range(n_cols):
        corr_row = []
        for j in range(n_cols):
            if sum_squares[i] == 0 or sum_squares[j] == 0:
                corr_row.append(1.0 if i == j else 0.0)
            else:
                covariance = sum(
                    centered_columns[i][r] * centered_columns[j][r]
                    for r in range(n_rows)
                )
                denominator = (sum_squares[i] * sum_squares[j]) ** 0.5
                corr_row.append(covariance / denominator)
        correlation.append(corr_row)

    return zscores, correlation

