    for raw in data_str.split(separator):
        token = raw.strip()
        try:
            value = int(token)
        except ValueError:
            try:
                value = int(float(token))
            except (ValueError, OverflowError):
                raise ValueError(f"Invalid numeric value: {raw!r}") from None
        values.append(value)

    minimum = min(values)
    maximum = max(values)
    counts = [0] * bins

    if minimum == maximum:
        counts[-1] = len(values)
    else:
        span = maximum - minimum
        for value in values:
            if value == maximum:
                index = bins - 1
            else:
                index = ((value - minimum) * bins) // span
            counts[index] += 1

