from bisect import bisect_right

def last_column_histogram(rows, bins=20):
    if not rows:
        raise ValueError("rows must not be empty")
    if bins <= 0:
        raise ValueError("bins must be positive")

    values = [row[-1] for row in rows]
    min_val = min(values)
    max_val = max(values)

    if min_val == max_val:
        edges = [float(min_val)] * (bins + 1)
        counts = [0] * bins
        counts[-1] = len(values)
        return counts, edges

    width = (max_val - min_val) / bins
    edges = [float(min_val + i * width) for i in range(bins + 1)]
    edges[-1] = float(max_val)

    counts = [0] * bins

    for value in values:
        if value == max_val:
            index = bins - 1
        else:
            index = bisect_right(edges, value) - 1
            if index < 0:
                index = 0
            elif index >= bins:
                index = bins - 1

        counts[index] += 1

    return counts, edges

