import math

def standardize_filtered(data, age, weight):
    if 'Age' not in data:
        raise KeyError('Age')
    if 'Weight' not in data:
        raise KeyError('Weight')

    kept_indices = [
        i for i, (a, w) in enumerate(zip(data['Age'], data['Weight']))
        if a < age and w > weight
    ]

    result = {}

    if not kept_indices:
        for col in data:
            result[col] = []
        return result

    for col, values in data.items():
        kept = [values[i] for i in kept_indices]
        n = len(kept)
        mean = sum(kept) / n

        variance = sum((x - mean) ** 2 for x in kept) / n

        if variance == 0:
            result[col] = [0.0] * n
        else:
            std = math.sqrt(variance)
            result[col] = [(x - mean) / std for x in kept]

    return result

