def min_max_scale_columns(rows):
    if not rows:
        return []

    n_cols = len(rows[0])
    if n_cols == 0:
        return [list(row) for row in rows]

    mins = [float("inf")] * n_cols
    maxs = [float("-inf")] * n_cols

    for row in rows:
        for j, value in enumerate(row):
            mins[j] = min(mins[j], value)
            maxs[j] = max(maxs[j], value)

