from collections import Counter

def chi_square_independence(xs, ys):
    if len(xs) == 0 or len(ys) == 0:
        raise ValueError("Input lists must not be empty")
    if len(xs) != len(ys):
        raise ValueError("Input lists must have the same length")

    row_counts = Counter(xs)
    col_counts = Counter(ys)

    if len(row_counts) < 2 or len(col_counts) < 2:
        raise ValueError("Each variable must have at least two distinct categories")

    n = len(xs)
    joint_counts = Counter(zip(xs, ys))

    statistic = 0.0

    for row, row_total in row_counts.items():
        for col, col_total in col_counts.items():
            observed = joint_counts.get((row, col), 0)
            expected = row_total * col_total / n
            statistic += (observed - expected) ** 2 / expected

    dof = (len(row_counts) - 1) * (len(col_counts) - 1)

    return statistic, dof

