def grouped_column_means(csv_text, group_col, value_col):
    reader = csv.DictReader(io.StringIO(csv_text))
    sums = {}
    counts = {}

    for row in reader:
        group = row[group_col]
        raw_value = row[value_col]

        if raw_value is None or raw_value.strip() == "":
            continue

        try:
            value = float(raw_value)
        except ValueError:
            raise ValueError(
