def cluster_point_labels(data, n_clusters):
    if not data:
        raise ValueError("data must not be empty")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")

    n = len(data)
    if n_clusters > n:
        raise ValueError("n_clusters cannot exceed the number of points")
    if n_clusters == 1:
        return [0] * n
    if n_clusters == n:
        return list(range(n))

    points = [(float(x), float(y)) for _, x, y in data]
    k = n_clusters

    # Deterministic farthest-first initialization.
    centers = [points[0]]
    selected = {0}

    while len(centers) < k:
        best_idx = None
        best_dist = -1.0

        for i, p in enumerate(points):
            if i in selected:
                continue

            dist = min(
                (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2
                for c in centers
            )

            if dist > best_dist:
                best_dist = dist
                best_idx = i

        selected.add(best_idx)
        centers.append(points[best_idx])

    # Lloyd's algorithm.
    labels = [-1] * n

    for _ in range(100):
        new_labels = []

        for p in points:
            best_cluster = 0
            best_dist = float("inf")

            for j, c in enumerate(centers):
                dist = (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2
                if dist < best_dist:
                    best_dist = dist
                    best_cluster = j

            new_labels.append(best_cluster)

        if new_labels == labels:
            break

        labels = new_labels

        sums = [[0.0, 0.0, 0] for _ in range(k)]

        for p, label in zip(points, labels):
            sums[label][0] += p[0]
            sums[label][1] += p[1]
            sums[label][2] += 1

        for j in range(k):
            if sums[j][2] > 0:
                centers[j] = (
                    sums[j][0] / sums[j][2],
                    sums[j][1] / sums[j][2],
                )

    # Renumber clusters by first appearance in input order.
    mapping = {}
    result = []
    next_label = 0

    for label in labels:
        if label not in mapping:
            mapping[label] = next_label
            next_label += 1
        result.append(mapping[label])

    return result
