import csv
import io


def _parse_number(value):
    s = value.strip()
    if s == "":
        raise ValueError
    try:
        return int(s)
    except ValueError:
        return float(s)


def _is_number(value):
    try:
        _parse_number(value)
        return True
    except (ValueError, TypeError):
        return False


def sort_csv_rows(csv_text, sort_by_column):
    reader = csv.reader(io.StringIO(csv_text, newline=""))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV has no header row")

    if sort_by_column not in header:
        raise ValueError(f"Column {sort_by_column!r} not found in header")

    rows = []
    for row in reader:
        if not row:
            continue

        if len(row) < len(header):
            row = row + [""] * (len(header) - len(row))
        elif len(row) > len(header):
            row = row[:len(header)]

        rows.append(row)

    numeric_columns = set()

    for i in range(len(header)):
        values = [row[i] for row in rows]
        if values and all(_is_number(value) for value in values):
            numeric_columns.add(i)

    result = []

    for row in rows:
        item = {}
        for i, column_name in enumerate(header):
            value = row[i]
            if i in numeric_columns:
                value = _parse_number(value)
            item[column_name] = value
        result.append(item)

    result.sort(key=lambda item: item[sort_by_column])
    return result
