from bisect import bisect_right

def histogram_bins(values, bins):
    if isinstance(bins, int):
        if bins <= 0:
            raise ValueError("bins must be positive")

        values = list(values)
        if not values:
            raise ValueError("values must be non-empty when bins is an integer")

        lo, hi = min(values), max(values)
        width = (hi - lo) / bins if hi != lo else 0.0

        edges = [float(lo + i * width) for i in range(bins)]
        edges.append(float(hi))
    else:
        edges = [float(edge) for edge in bins]
        if len(edges) < 2:
            raise ValueError("at least two bin edges are required")

    counts = [0] * (len(edges) - 1)

    if not counts:
        return counts, edges

    left, right = edges[0], edges[-1]

    for value in values:
        if value < left or value > right:
            continue

        if value == right:
            index = len(counts) - 1
        else:
            index = bisect_right(edges, value) - 1

        if 0 <= index < len(counts):
            counts[index] += 1

    return counts, edges
