def classical_seasonal_decomposition(values, period, model='additive'):
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    if not isinstance(period, int) or isinstance(period, bool) or period <= 0:
        raise ValueError("period must be a positive integer")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    trend = [None] * n

    if period % 2 == 1:
        half = period // 2
        for t in range(half, n - half):
            trend[t] = sum(values[t - half:t + half + 1]) / period
    else:
        half = period // 2
        for t in range(half, n - half):
            total = 0.5 * values[t - half] + 0.5 * values[t + half]
            for k in range(t - half + 1, t + half):
                total += values[k]
            trend[t] = total / period

    phase_sums = [0.0] * period
    phase_counts = [0] * period

    for t in range(n):
        if trend[t] is None:
            continue

        phase = t % period

        if model == 'additive':
            detrended = values[t] - trend[t]
        else:
            detrended = values[t] / trend[t]

        phase_sums[phase] += detrended
        phase_counts[phase] += 1

    seasonal_phase = []
    for phase in range(period):
        if phase_counts[phase] == 0:
            raise ValueError("not enough data to estimate seasonal component")
        seasonal_phase.append(phase_sums[phase] / phase_counts[phase])

    if model == 'additive':
        seasonal_mean = sum(seasonal_phase) / period
        seasonal_phase = [x - seasonal_mean for x in seasonal_phase]
    else:
        seasonal_mean = sum(seasonal_phase) / period
        if seasonal_mean == 0:
            raise ValueError("cannot normalize multiplicative seasonal component")
        seasonal_phase = [x / seasonal_mean for x in seasonal_phase]

    seasonal = [seasonal_phase[t % period] for t in range(n)]
    resid = [None] * n

    for t in range(n):
        if trend[t] is None:
            continue

        if model == 'additive':
            resid[t] = values[t] - trend[t] - seasonal[t]
        else:
            resid[t] = values[t] / (trend[t] * seasonal[t])

    return {
        'trend': trend,
        'seasonal': seasonal,
        'resid': resid,
    }
