def attribute_histogram(records, key, num_bins=30):
    if num_bins <= 0:
        raise ValueError("num_bins must be positive")

    values = [float(record[key]) for record in records]

    if not values:
        return [0] * num_bins, [0.0] * (num_bins + 1)

    lo, hi = min(values), max(values)

    if lo == hi:
        edges = [lo] * (num_bins + 1)
        counts = [0] * num_bins
        counts[-1] = len(values)
        return counts, edges

    width = (hi - lo) / num_bins
    edges = [lo + i * width for i in range(num_bins)] + [hi]

    counts = [0] * num_bins

    for value in values:
        idx = bisect_right(edges, value) - 1
        if idx < 0:
            idx = 0
        elif idx >= num_bins:
            idx = num_bins - 1
        counts[idx] += 1

    return counts, edges
