def standardize_columns(data):
    result = {}

    for column, values in data.items():
        n = len(values)

        if n == 0:
            result[column] = ([], [0] * 20)
            continue

        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = math.sqrt(variance)

        if std == 0:
            standardized = [0.0] * n
        else:
            standardized = [(x - mean) / std for x in values]

        counts = [0] * 20

        if standardized:
            lo = min(standardized)
            hi = max(standardized)

            if hi == lo:
                # All values are equal and are therefore the maximum.
                counts[-1] = len(standardized)
            else:
                width = (hi - lo) / 20

                for value in standardized:
                    if value == hi:
                        index = 19
                    else:
                        index = int((value - lo) / width)
                        index = max(0, min(index, 19))

                    counts[index] += 1

        result[column] = (standardized, counts)

    return result
