def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    numeric_names = []
    for name, values in table.items():
        if values and all(isinstance(v, Real) and not isinstance(v, bool) for v in values):
            numeric_names.append(name)

    if not numeric_names:
        raise ValueError("table has no numeric columns")

    standardized = {}
    numeric_standardized = []

    for name, values in table.items():
        if name in numeric_names:
            n = len(values)
            mean = sum(float(v) for v in values) / n
            variance = sum((float(v) - mean) ** 2 for v in values) / n
            std = math.sqrt(variance)

            if std == 0:
                z_values = [0.0] * n
            else:
                z_values = [(float(v) - mean) / std for v in values]

            standardized[name] = z_values
            numeric_standardized.append(z_values)
        else:
            standardized[name] = values

    m = len(numeric_names)
    n = len(table[numeric_names[0]])
    corr = [[0.0] * m for _ in range(m)]

    for i in range(m):
        for j in range(m):
            if i == j:
                corr[i][j] = 1.0
            else:
                corr[i][j] = (
                    sum(numeric_standardized[i][k] * numeric_standardized[j][k]
                        for k in range(n)) / n
                )

    return standardized, corr
