def feature_correlation_matrix(samples):
    if not samples:
        return []

    n = len(samples)
    m = len(samples[0])

    means = [
        sum(row[j] for row in samples) / n
        for j in range(m)
    ]

    stds = []
    for j in range(m):
        variance = sum((row[j] - means[j]) ** 2 for row in samples) / n
        stds.append(variance ** 0.5)

    corr = [[0.0] * m for _ in range(m)]

    for i in range(m):
        for j in range(m):
            if stds[i] == 0 or stds[j] == 0:
                corr[i][j] = 1.0 if i == j else 0.0
            else:
                covariance = sum(
                    (samples[k][i] - means[i]) * (samples[k][j] - means[j])
                    for k in range(n)
                ) / n
                corr[i][j] = covariance / (stds[i] * stds[j])

    return corr
