def extract_table_rows(html):
    from html.parser import HTMLParser

    class TableRowExtractor(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.rows = []
            self.row_stack = []
            self.td_stack = []
            self.table_depth = 0

        def handle_starttag(self, tag, attrs):
            tag = tag.lower()

            if tag == 'table':
                self.table_depth += 1

            elif tag == 'tr':
                while self.row_stack and self.row_stack[-1]['depth'] == self.table_depth:
                    self._close_row()

                row = {'cells': [], 'depth': self.table_depth}
                self.rows.append(row)
                self.row_stack.append(row)

            elif tag in ('td', 'th'):
                row = self._current_row()
                if row is None:
                    return

                # Starting a new cell implicitly closes an open cell in this row.
                while self.td_stack and self.td_stack[-1]['row'] is row:
                    self.td_stack.pop()

                if tag == 'td':
                    buf = []
                    row['cells'].append(buf)
                    self.td_stack.append({
                        'row': row,
                        'buffer': buf,
                        'depth': self.table_depth
                    })

        def handle_startendtag(self, tag, attrs):
            self.handle_starttag(tag, attrs)
            self.handle_endtag(tag)

        def handle_endtag(self, tag):
            tag = tag.lower()

            if tag == 'table':
                while self.row_stack and self.row_stack[-1]['depth'] >= self.table_depth:
                    self._close_row()
                if self.table_depth > 0:
                    self.table_depth -= 1

            elif tag == 'tr':
                if self.row_stack and self.row_stack[-1]['depth'] == self.table_depth:
                    self._close_row()

            elif tag == 'td':
                if self.td_stack and self.td_stack[-1]['depth'] == self.table_depth:
                    self.td_stack.pop()

        def handle_data(self, data):
            for ctx in self.td_stack:
                ctx['buffer'].append(data)

        def _current_row(self):
            if self.row_stack and self.row_stack[-1]['depth'] == self.table_depth:
                return self.row_stack[-1]
            return None

        def _close_row(self):
            row = self.row_stack.pop()
            self.td_stack = [ctx for ctx in self.td_stack if ctx['row'] is not row]

    parser = TableRowExtractor()
    parser.feed(html)
    parser.close()

    return [
        [''.join(buf).strip() for buf in row['cells']]
        for row in parser.rows
    ]
