import json
import math


def _linear_quantile(sorted_values, q):
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])

    position = (n - 1) * q
    lower = math.floor(position)
    upper = math.ceil(position)

    if lower == upper:
        return float(sorted_values[lower])

    fraction = position - lower
    return float(
        sorted_values[lower]
        + (sorted_values[upper] - sorted_values[lower]) * fraction
    )


def summarize_values_by_key(json_text):
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, list):
        raise ValueError("JSON must encode a list of objects")

    values_by_key = {}

    for obj in data:
        if not isinstance(obj, dict):
            raise ValueError("Each item in the JSON list must be an object")

        for key, value in obj.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"Value for key {key!r} is not a number")
            values_by_key.setdefault(key, []).append(value)

    result = {}

    for key, values in values_by_key.items():
        values.sort()
        result[key] = {
            "mean": float(sum(values) / len(values)),
            "median": _linear_quantile(values, 0.5),
            "q1": _linear_quantile(values, 0.25),
            "q3": _linear_quantile(values, 0.75),
        }

    return result
