from collections import Counter


_NON_ALNUM = re.compile(r"[\W_]+", re.UNICODE)


def _clean_text(text):
    """Lowercase text and collapse non-alphanumeric runs to one space."""
    return _NON_ALNUM.sub(" ", text.lower()).strip()


def _lcs_length(left, right):
    """Return the length of the longest common subsequence of two strings."""
    if len(left) < len(right):
        left, right = right, left

    previous = [0] * (len(right) + 1)
    for left_char in left:
        current = [0]
        for index, right_char in enumerate(right, 1):
            if left_char == right_char:
                current.append(previous[index - 1] + 1)
            else:
                current.append(
                    previous[index]
                    if previous[index] >= current[index - 1]
                    else current[index - 1]
                )
        previous = current

    return previous[-1]


def text_similarity_scores(text1, text2):
    """Return the cosine and insertion/deletion similarity of two texts."""
    cleaned1 = _clean_text(text1)
    cleaned2 = _clean_text(text2)

    words1 = cleaned1.split()
    words2 = cleaned2.split()

    if not words1 or not words2:
        cosine = 0.0
    else:
        counts1 = Counter(words1)
        counts2 = Counter(words2)
        if counts1 == counts2:
            cosine = 1.0
        else:
            dot_product = sum(
                count * counts2[word] for word, count in counts1.items()
            )
            magnitude1 = math.sqrt(
                sum(count * count for count in counts1.values())
            )
            magnitude2 = math.sqrt(
                sum(count * count for count in counts2.values())
            )
            cosine = dot_product / (magnitude1 * magnitude2)

