"""Ordinary least-squares linear regression with an intercept (pure Python).

The fit is computed from the normal equations of the augmented design matrix
``[X | 1]``, solved through a Jacobi eigendecomposition of ``A^T A``.  Using the
pseudoinverse built from that eigendecomposition means rank-deficient and
underdetermined inputs still produce the minimum-norm least-squares solution
instead of raising, which is what a least-squares fit should do.
"""

import math

_EPS = 2.220446049250313e-16


def _jacobi_eigen(matrix, n, sweeps=100):
    """Eigenvalues/vectors of a symmetric matrix by the cyclic Jacobi method.

    Returns ``(eigenvalues, eigenvectors)`` where ``eigenvectors[j]`` is the
    unit eigenvector belonging to ``eigenvalues[j]``.
    """
    a = [list(map(float, row)) for row in matrix]
    v = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]

    for _ in range(sweeps):
        off = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                off += a[i][j] * a[i][j]
        if off <= 1e-30 * max(1.0, sum(a[i][i] * a[i][i] for i in range(n))):
            break

        for p in range(n - 1):
            for q in range(p + 1, n):
                apq = a[p][q]
                if apq == 0.0:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * apq)
                if theta >= 0.0:
                    t = 1.0 / (theta + math.sqrt(1.0 + theta * theta))
                else:
                    t = -1.0 / (-theta + math.sqrt(1.0 + theta * theta))
                c = 1.0 / math.sqrt(1.0 + t * t)
                s = t * c

                for k in range(n):
                    akp = a[k][p]
                    akq = a[k][q]
                    a[k][p] = c * akp - s * akq
                    a[k][q] = s * akp + c * akq
                for k in range(n):
                    apk = a[p][k]
                    aqk = a[q][k]
                    a[p][k] = c * apk - s * aqk
                    a[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp = v[k][p]
                    vkq = v[k][q]
                    v[k][p] = c * vkp - s * vkq
                    v[k][q] = s * vkp + c * vkq

    eigenvalues = [a[i][i] for i in range(n)]
    eigenvectors = [[v[i][j] for i in range(n)] for j in range(n)]
    return eigenvalues, eigenvectors


def _clean(x):
    """Snap values that are within rounding noise of a nearby integer/float."""
    nearest = round(x)
    if abs(x - nearest) <= 1e-12 * max(1.0, abs(x)):
        return float(nearest)
    return float(x)


def fit_linear_regression(features, values):
    """Fit ``y = intercept + sum_j coefficients[j] * x[j]`` by least squares.

    ``features`` is a sequence of equal-length numeric rows and ``values`` the
    matching target values.  Returns a dict with ``'coefficients'`` (in
    feature-column order) and ``'intercept'``.
    """
    rows = [list(row) for row in features]
    targets = [float(v) for v in values]

    if len(rows) != len(targets):
        raise ValueError(
            'features and values must have the same length '
            '(%d rows vs %d values)' % (len(rows), len(targets))
        )
    if not rows:
        raise ValueError('features and values must not be empty')

    n_rows = len(rows)
    n_features = len(rows[0])
    for row in rows:
        if len(row) != n_features:
            raise ValueError('all feature rows must have the same length')

    design = [[float(v) for v in row] + [1.0] for row in rows]
    n_params = n_features + 1

    # Normal equations of the augmented system: (A^T A) theta = A^T y.
    ata = [[0.0] * n_params for _ in range(n_params)]
    aty = [0.0] * n_params
    for row, y in zip(design, targets):
        for i in range(n_params):
            xi = row[i]
            if xi == 0.0:
                continue
            aty[i] += xi * y
            ata_row = ata[i]
            for j in range(i, n_params):
                ata_row[j] += xi * row[j]
    for i in range(n_params):
        for j in range(i):
            ata[i][j] = ata[j][i]

    eigenvalues, eigenvectors = _jacobi_eigen(ata, n_params)

    largest = max(eigenvalues) if eigenvalues else 0.0
    tol = max(largest, 0.0) * max(n_rows, n_params) * _EPS

    theta = [0.0] * n_params
