        projection = sum(vec[i] * aty[i] for i in range(n_params))
        factor = projection / lam
        for i in range(n_params):
            theta[i] += factor * vec[i]

    return {
        'coefficients': [_clean(c) for c in theta[:n_features]],
        'intercept': _clean(theta[n_features]),
