import csv
import io
import re

_NUMBER_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")


def _convert(cell):
    """Turn a raw CSV cell into None, a number, or a string."""
    if cell is None:
        return None
    text = cell.strip()
    if not text:
        return None
    if _NUMBER_RE.match(text):
        try:
            if "." in text or "e" in text or "E" in text:
                return float(text)
            return int(text)
        except ValueError:
            return cell
    return cell


def merge_csv_texts(csv_texts):
    if not csv_texts:
        return []

    columns = []
    seen = set()
    tables = []

    for text in csv_texts:
        if text is None:
            continue
        if text.startswith("\ufeff"):
            text = text[1:]
        reader = csv.reader(io.StringIO(text))
        try:
            header = next(reader)
        except StopIteration:
            continue
        header = [name.strip() if isinstance(name, str) else name for name in header]
        for name in header:
            if name not in seen:
                seen.add(name)
                columns.append(name)
        rows = []
        for row in reader:
            if not row or all(cell.strip() == "" for cell in row):
                continue
            rows.append(row)
        tables.append((header, rows))

    result = []
    for header, rows in tables:
        for row in rows:
            record = {name: None for name in columns}
            for index, name in enumerate(header):
                if index < len(row):
                    record[name] = _convert(row[index])
            result.append(record)
    return result

