def letter_count_correlations(strings):
    """Pearson correlation between per-string letter counts.

    ``strings`` is a list of lowercase strings.  For every letter that occurs
    somewhere in the input, its count in each string is recorded; the result is
    a nested dict mapping letter pairs to the Pearson correlation of those
    count vectors.  Returns ``None`` for an empty list.
    """
    if not strings:
        return None

