    means = {letter: sum(vals) / n for letter, vals in counts.items()}

    # Centred vectors, plus their sums of squares (the variances up to a factor).
    centred = {
        letter: [value - means[letter] for value in vals]
        for letter, vals in counts.items()
    }
    sq_sums = {letter: sum(c * c for c in vec) for letter, vec in centred.items()}

