def _zscore(values):
    n = len(values)
    if n == 0:
        return []
    mean = sum(values) / n
    std = (sum((v - mean) ** 2 for v in values) / n) ** 0.5
    if std == 0:
        return [0.0 for _ in values]
    return [(v - mean) / std for v in values]


def standardize_series(x, y, labels):
    return {
        label: [_zscore(xs), _zscore(ys)]
        for label, xs, ys in zip(labels, x, y)
    }

