def normalize_numeric_columns(csv_text):
    """Min-max scale every numeric CSV column to the range 0..1.

    Returns a dict mapping column names, in header order, to their values.
    A column counts as numeric when every one of its values parses as a finite
    number; those values are scaled, and a column whose values are all equal
    becomes all 0.0. Any other column is returned unchanged as strings.
    Raises ValueError when the CSV has no numeric columns.
