"""Ordinary least-squares linear regression on CSV text."""

import csv
import io
import math

_EPS = 2.220446049250313e-16


def _to_float(text, label):
    """Parse one CSV field as a finite float, raising ValueError otherwise."""
    if text is None:
        raise ValueError("%s is missing" % label)
    s = text.strip()
    if not s:
        raise ValueError("%s is missing" % label)
    try:
        value = float(s)
    except (TypeError, ValueError):
        raise ValueError("%s is non-numeric: %r" % (label, text))
    if not math.isfinite(value):
        raise ValueError("%s is non-numeric: %r" % (label, text))
    return value


def _read_table(text):
    """Return (header, rows) for CSV text, skipping blank lines."""
    if isinstance(text, bytes):
        text = text.decode("utf-8-sig")
    text = text.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text))
    header = None
    rows = []
    for row in reader:
        if not row or all(field.strip() == "" for field in row):
            continue
        if header is None:
            header = [field.strip() for field in row]
            continue
        rows.append(row)
    if header is None:
        raise ValueError("CSV text has no header row")
    return header, rows


def _qr(a):
    """Thin Householder QR: returns (Q, R) with a == Q @ R, Q m x n, R n x n."""
    m = len(a)
    n = len(a[0])
    r = [row[:] for row in a]
    reflectors = []
    for k in range(n):
        norm = math.sqrt(sum(r[i][k] * r[i][k] for i in range(k, m)))
        if norm == 0.0:
            reflectors.append(None)
            continue
        alpha = -norm if r[k][k] >= 0.0 else norm
        v = [0.0] * m
        v[k] = r[k][k] - alpha
        for i in range(k + 1, m):
            v[i] = r[i][k]
        vnorm2 = sum(x * x for x in v)
        if vnorm2 == 0.0:
            reflectors.append(None)
            continue
        reflectors.append((v, vnorm2))
        for j in range(k, n):
            s = 0.0
            for i in range(k, m):
                s += v[i] * r[i][j]
            f = 2.0 * s / vnorm2
            if f:
                for i in range(k, m):
                    r[i][j] -= f * v[i]
    # a == H_0 H_1 ... H_{n-1} R, so apply the reflectors in reverse order.
    q = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(m)]
    for reflector in reversed(reflectors):
        if reflector is None:
            continue
        v, vnorm2 = reflector
        for j in range(n):
            s = 0.0
            for i in range(m):
                s += v[i] * q[i][j]
            f = 2.0 * s / vnorm2
            if f:
                for i in range(m):
                    q[i][j] -= f * v[i]
    for i in range(n):
        for j in range(i):
            r[i][j] = 0.0
    return q, r[:n]


def _rank_tolerance(matrix):
    scale = 0.0
    for row in matrix:
        for value in row:
            if abs(value) > scale:
                scale = abs(value)
    if scale == 0.0:
        return 0.0
    return max(len(matrix), max(len(row) for row in matrix)) * _EPS * scale


def _solve_upper(r, rhs):
    """Solve an upper-triangular system; dependent directions are set to zero."""
    n = len(r)
    tol = _rank_tolerance(r)
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        acc = rhs[i]
        for j in range(i + 1, n):
            acc -= r[i][j] * x[j]
        if abs(r[i][i]) <= tol:
            x[i] = 0.0
        else:
            x[i] = acc / r[i][i]
    return x


def _lstsq(a, b):
    """Least-squares solution of a @ x ~= b (minimum-norm when underdetermined)."""
    m = len(a)
    n = len(a[0])
    if n == 0:
        return []
    if m >= n:
        q, r = _qr(a)
        qtb = [sum(q[i][j] * b[i] for i in range(m)) for j in range(n)]
        return _solve_upper(r, qtb)
    at = [[a[i][j] for i in range(m)] for j in range(n)]
    q, r = _qr(at)
    # a == r^T @ q^T, so solve r^T z = b then x = q @ z.
    tol = _rank_tolerance(r)
    z = [0.0] * m
    for i in range(m):
        acc = b[i]
        for j in range(i):
            acc -= r[j][i] * z[j]
        if abs(r[i][i]) <= tol:
            z[i] = 0.0
        else:
            z[i] = acc / r[i][i]
    return [sum(q[i][j] * z[j] for j in range(m)) for i in range(n)]


def predict_linear_regression(train_csv, test_csv, target):
    """Fit an OLS model with intercept on train_csv and predict test_csv rows."""
    header, train_rows = _read_table(train_csv)
    if target not in header:
        raise ValueError("target column %r is not in the training header" % (target,))
    target_index = header.index(target)
    feature_indices = [j for j in range(len(header)) if j != target_index]
    feature_names = [header[j] for j in feature_indices]

    design = []
    responses = []
    for line_no, row in enumerate(train_rows, start=2):
        if len(row) != len(header):
            raise ValueError(
                "row %d has %d fields, expected %d"
                % (line_no, len(row), len(header))
            )
        features = [1.0]
        for j in feature_indices:
            features.append(
                _to_float(row[j], "column %r on row %d" % (header[j], line_no))
            )
        design.append(features)
        responses.append(
            _to_float(row[target_index], "column %r on row %d" % (target, line_no))
        )

    if not design:
        raise ValueError("training data has no rows")

    coefficients = _lstsq(design, responses)

    test_header, test_rows = _read_table(test_csv)
    test_positions = []
    for name in feature_names:
        if name not in test_header:
            raise ValueError("column %r is missing from the test header" % (name,))
        test_positions.append(test_header.index(name))

    predictions = []
    for line_no, row in enumerate(test_rows, start=2):
        if len(row) != len(test_header):
            raise ValueError(
                "row %d has %d fields, expected %d"
                % (line_no, len(row), len(test_header))
            )
        prediction = coefficients[0] if coefficients else 0.0
        for offset, j in enumerate(test_positions):
            value = _to_float(
                row[j], "column %r on row %d" % (test_header[j], line_no)
            )
            prediction += coefficients[offset + 1] * value
        predictions.append(float(prediction))
    return predictions

