    test_header, test_rows = _read_table(test_csv)
    test_positions = []
    for name in feature_names:
        if name not in test_header:
            raise ValueError("column %r is missing from the test header" % (name,))
        test_positions.append(test_header.index(name))

    predictions = []
    for line_no, row in enumerate(test_rows, start=2):
        if len(row) != len(test_header):
            raise ValueError(
                "row %d has %d fields, expected %d"
                % (line_no, len(row), len(test_header))
            )
        prediction = coefficients[0] if coefficients else 0.0
        for offset, j in enumerate(test_positions):
            value = _to_float(
                row[j], "column %r on row %d" % (test_header[j], line_no)
            )
            prediction += coefficients[offset + 1] * value
        predictions.append(float(prediction))
    return predictions

