"""Min-max normalization of numeric CSV columns."""

import csv
import io


def normalize_csv_columns(csv_text):
    """Min-max normalize every column of a CSV with a header row.

    Returns a dict mapping each column name to the list of normalized values
    (floats in [0, 1]) in row order. A constant column becomes all zeros.
    """
    if csv_text is None:
        raise ValueError("csv_text must not be None")

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if any(cell.strip() for cell in row)]

    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    body = rows[1:]

    result = {}
    for index, name in enumerate(header):
        values = []
        for row in body:
            raw = row[index].strip() if index < len(row) else ""
            values.append(float(raw) if raw else 0.0)

        if not values:
            result[name] = []
            continue

        low = min(values)
        span = max(values) - low
        if span == 0:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [(value - low) / span for value in values]

    return result

