"""Word-frequency helper for articles whose titles mention 'like' or 'what'."""

import string

__all__ = ["keyword_article_word_counts"]

_PUNCTUATION = set(string.punctuation)
_TITLE_KEYWORDS = ("like", "what")


def _words(content):
    """Yield the words of ``content`` with surrounding punctuation removed."""
    for token in content.split():
        start, end = 0, len(token)
        while start < end and token[start] in _PUNCTUATION:
            start += 1
        while end > start and token[end - 1] in _PUNCTUATION:
            end -= 1
        word = token[start:end]
        if word:
            yield word


def keyword_article_word_counts(articles):
    """Count words in the content of articles whose title names a keyword.

    An article is selected when its ``'Title'`` contains ``'like'`` or
    ``'what'`` anywhere, compared case-insensitively.  Words are the
    whitespace-separated tokens of the selected articles' ``'Content'`` with
    punctuation stripped from their edges; each word keeps its original
    spelling, so counting is case-sensitive.

    :param articles: iterable of mappings with ``'Title'`` and ``'Content'``.
    :returns: ``dict`` mapping word to number of occurrences.
    :raises ValueError: if an article lacks either required key.
    """
    articles = list(articles)

    for index, article in enumerate(articles):
        if "Title" not in article or "Content" not in article:
            raise ValueError(
                "article at index %d is missing a 'Title' or 'Content' key"
                % index
            )

    counts = {}
    for article in articles:
        title = article["Title"]
        if not isinstance(title, str):
            title = str(title)
        lowered = title.lower()
        if not any(keyword in lowered for keyword in _TITLE_KEYWORDS):
            continue

        content = article["Content"]
        if not isinstance(content, str):
            content = str(content)

        for word in _words(content):
            counts[word] = counts.get(word, 0) + 1

    return counts

