"""Compute per-key mean and median of the numeric values in a JSON record list."""

import json
import math
from numbers import Real


def _is_number(value):
    """True for JSON numbers, excluding booleans and non-finite floats."""
    if isinstance(value, bool):
        return False
    if not isinstance(value, Real):
        return False
    return not (isinstance(value, float) and not math.isfinite(value))


def _median(values):
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    if n % 2:
        return float(ordered[mid])
    return (ordered[mid - 1] + ordered[mid]) / 2.0


def key_mean_median(json_text):
    records = json.loads(json_text)

    values_by_key = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        for key, value in record.items():
            bucket = values_by_key.setdefault(key, [])
            if _is_number(value):
                bucket.append(value)

    result = {}
    for key, values in values_by_key.items():
        if not values:
            result[key] = {'mean': None, 'median': None}
        else:
            result[key] = {
                'mean': float(sum(values)) / len(values),
                'median': _median(values),
            }
    return result

