"""Outer-join two tables on 'id' and standardize the first table's features."""

from math import sqrt


def _feature_columns(rows):
    """Feature column names (everything but 'id'), in first-appearance order."""
    columns = []
    seen = set()
    for row in rows:
        for key in row:
            if key != "id" and key not in seen:
                seen.add(key)
                columns.append(key)
    return columns


def _standardizer(rows, column):
    """Return a function mapping a value to its standardized form."""
    values = [float(row[column]) for row in rows
              if row.get(column) is not None]
    if not values:
        return lambda value: None

    mean = sum(values) / len(values)
    variance = sum((value - mean) ** 2 for value in values) / len(values)
    std = sqrt(variance)

    if std == 0:
        return lambda value: 0.0

    return lambda value: (float(value) - mean) / std


def merge_and_standardize(rows1, rows2):
    rows1 = list(rows1 or [])
    rows2 = list(rows2 or [])

    cols1 = _feature_columns(rows1)
    cols2 = _feature_columns(rows2)

    # One transform per first-table feature column, fit on that table alone.
    transforms = {column: _standardizer(rows1, column) for column in cols1}

    merged = {}

    for row in rows1:
        row_id = row["id"]
        if row_id in merged:
            continue
        record = {"id": row_id}
        for column in cols1:
            value = row.get(column)
            record[column] = None if value is None else transforms[column](value)
