def scale_table_columns(data):
    """Drop rows containing None, then min-max scale each column to [0.0, 1.0]."""
    columns = list(data.keys())
    if not columns:
        return {}

    row_count = len(data[columns[0]])
    kept = [
        row
        for row in range(row_count)
        if all(data[name][row] is not None for name in columns)
    ]

    result = {}
    for name in columns:
        values = [data[name][row] for row in kept]
        if not values:
            result[name] = []
            continue
        low = min(values)
        high = max(values)
        if high == low:
            result[name] = [0.0 for _ in values]
        else:
            span = high - low
            result[name] = [(value - low) / span for value in values]
    return result

