"""Ordinary least-squares linear regression over named columns."""


def _solve(matrix, rhs):
    """Solve a square linear system by Gaussian elimination with partial pivoting.

    Returns None if the system is numerically singular.
    """
    n = len(matrix)
    a = [list(row) + [rhs[i]] for i, row in enumerate(matrix)]

    scale = max((abs(v) for row in matrix for v in row), default=0.0)
    tolerance = max(scale, 1.0) * n * 1e-14

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(a[r][col]))
        if abs(a[pivot][col]) <= tolerance:
            return None
        a[col], a[pivot] = a[pivot], a[col]

        pivot_value = a[col][col]
        for r in range(col + 1, n):
            factor = a[r][col] / pivot_value
            if factor == 0.0:
                continue
            for c in range(col, n + 1):
                a[r][c] -= factor * a[col][c]

    solution = [0.0] * n
    for col in range(n - 1, -1, -1):
        total = a[col][n]
        for c in range(col + 1, n):
            total -= a[col][c] * solution[c]
        solution[col] = total / a[col][col]
    return solution


def _jacobi_eigen(matrix, iterations=100):
    """Eigen-decompose a symmetric matrix with the cyclic Jacobi method."""
    n = len(matrix)
    a = [list(row) for row in matrix]
    vectors = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]

    for _ in range(iterations):
        off_diagonal = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                off_diagonal += a[i][j] * a[i][j]
        if off_diagonal <= 1e-30:
            break

        for p in range(n - 1):
            for q in range(p + 1, n):
                if abs(a[p][q]) <= 1e-300:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * a[p][q])
                if theta >= 0.0:
                    t = 1.0 / (theta + (theta * theta + 1.0) ** 0.5)
                else:
                    t = -1.0 / (-theta + (theta * theta + 1.0) ** 0.5)
                c = 1.0 / (t * t + 1.0) ** 0.5
                s = t * c

                for k in range(n):
                    akp = a[k][p]
                    akq = a[k][q]
                    a[k][p] = c * akp - s * akq
                    a[k][q] = s * akp + c * akq
                for k in range(n):
                    apk = a[p][k]
                    aqk = a[q][k]
                    a[p][k] = c * apk - s * aqk
                    a[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp = vectors[k][p]
                    vkq = vectors[k][q]
                    vectors[k][p] = c * vkp - s * vkq
                    vectors[k][q] = s * vkp + c * vkq

    return [a[i][i] for i in range(n)], vectors


def _minimum_norm_solution(design, values):
    """Minimum-norm least-squares solution, used when the design is rank deficient."""
    width = len(design[0])
    gram = [[0.0] * width for _ in range(width)]
    moment = [0.0] * width
    for row, value in zip(design, values):
        for a in range(width):
            moment[a] += row[a] * value
            for b in range(a, width):
                gram[a][b] += row[a] * row[b]
    for a in range(width):
        for b in range(a):
            gram[a][b] = gram[b][a]

    eigenvalues, vectors = _jacobi_eigen(gram)
    largest = max((abs(v) for v in eigenvalues), default=0.0)
    tolerance = largest * width * 1e-12

    solution = [0.0] * width
    for index, value in enumerate(eigenvalues):
        if value <= tolerance:
            continue
        column = [vectors[r][index] for r in range(width)]
        projection = sum(column[r] * moment[r] for r in range(width)) / value
        for r in range(width):
            solution[r] += projection * column[r]
    return solution


def column_linear_regression(rows, columns, target):
    """Fit an OLS regression with an intercept predicting ``target`` from other columns.

    ``rows`` is a list of numeric rows, ``columns`` names each position.  Returns
    ``(coefficients, intercept)`` with coefficients ordered like the predictor
    columns (the target column removed).
    """
    if not rows:
        raise ValueError("rows must not be empty")

    names = list(columns)
    if target not in names:
        raise ValueError("target %r is not one of the columns" % (target,))

    width = len(names)
    for row in rows:
        if len(row) != width:
            raise ValueError("each row must have %d values, got %d" % (width, len(row)))

    target_index = names.index(target)
    predictors = [i for i in range(width) if i != target_index]
    count = len(rows)

    y = [float(row[target_index]) for row in rows]
    y_mean = sum(y) / count

    if not predictors:
        return [], y_mean

    x_mean = [
        sum(float(row[i]) for row in rows) / count for i in predictors
    ]

    design = [
        [float(row[i]) - mean for i, mean in zip(predictors, x_mean)] for row in rows
    ]
    centered_y = [value - y_mean for value in y]

    size = len(predictors)
    normal = [[0.0] * size for _ in range(size)]
    moment = [0.0] * size
    for row, value in zip(design, centered_y):
        for a in range(size):
            moment[a] += row[a] * value
            for b in range(a, size):
                normal[a][b] += row[a] * row[b]
    for a in range(size):
        for b in range(a):
            normal[a][b] = normal[b][a]

    coefficients = _solve(normal, moment)
    if coefficients is None:
        augmented = [[1.0] + [float(row[i]) for i in predictors] for row in rows]
        solution = _minimum_norm_solution(augmented, y)
        return [float(value) for value in solution[1:]], float(solution[0])

    intercept = y_mean - sum(
        coefficient * mean for coefficient, mean in zip(coefficients, x_mean)
    )
    return [float(c) for c in coefficients], float(intercept)

