"""Summarize one numeric column of a list of weather observations."""

COLUMN_INDEX = {
    'Temperature': 1,
    'Humidity': 2,
    'Wind Speed': 3,
    'Precipitation': 4,
}

BIN_COUNT = 10


def weather_column_summary(column, data):
    """Return sum, mean, min, max and a 10-bin histogram for `column`.

    `data` holds observations shaped as
    ``[date, temperature, humidity, wind_speed, precipitation]``.
    """
    try:
        index = COLUMN_INDEX[column]
    except KeyError:
        raise ValueError('unknown column: %r' % (column,))

    values = [row[index] for row in data]

    if not values:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * BIN_COUNT,
        }

    total = sum(values)
    low = min(values)
    high = max(values)

    histogram = [0] * BIN_COUNT
    if high == low:
        # A single distinct value has no spread; keep it in the last bin,
        # matching the "last bin includes the maximum" convention.
        histogram[-1] = len(values)
    else:
        width = (high - low) / BIN_COUNT
        for value in values:
            position = int((value - low) / width)
            if position >= BIN_COUNT:
                position = BIN_COUNT - 1
            elif position < 0:
                position = 0
            histogram[position] += 1

    return {
        'sum': total,
        'mean': total / len(values),
        'min': low,
        'max': high,
        'histogram': histogram,
    }

