        # matching the "last bin includes the maximum" convention.
        histogram[-1] = len(values)
    else:
        width = (high - low) / BIN_COUNT
        for value in values:
            position = int((value - low) / width)
            if position >= BIN_COUNT:
                position = BIN_COUNT - 1
            elif position < 0:
                position = 0
            histogram[position] += 1

    return {
        'sum': total,
        'mean': total / len(values),
        'min': low,
        'max': high,
        'histogram': histogram,
    }

