from collections import Counter
from fractions import Fraction


def association_chi_square(left, right):
    """Return the Pearson chi-square statistic and dof for the joined records.

    The join is an inner relational join on id, so duplicate ids contribute
    one joined record for each matching pair.
    """
    right_by_id = {}
    for row_id, category in right:
        right_by_id.setdefault(row_id, []).append(category)

    counts = Counter()
    for row_id, left_category in left:
        for right_category in right_by_id.get(row_id, ()):
            counts[(left_category, right_category)] += 1

    if not counts:
        return 0.0, 0

    row_totals = Counter()
    column_totals = Counter()
    for (left_category, right_category), count in counts.items():
        row_totals[left_category] += count
        column_totals[right_category] += count

    total = sum(counts.values())
    statistic = Fraction(0, 1)
    for left_category, row_total in row_totals.items():
        for right_category, column_total in column_totals.items():
            observed = counts.get((left_category, right_category), 0)
            expected = Fraction(row_total * column_total, total)
            statistic += (observed - expected) ** 2 / expected

    dof = (len(row_totals) - 1) * (len(column_totals) - 1)
    return float(statistic), dof

