from datetime import datetime, timezone as dt_timezone
from zoneinfo import ZoneInfo


def publication_hour_stats(articles, timezone):
    """Aggregate publication hours per category, in the given IANA timezone."""
    if not articles:
        raise ValueError("articles must not be empty")

    tz = ZoneInfo(timezone)
    hours_by_category = {}

    for index, article in enumerate(articles):
        try:
            category = article["category"]
            published_time = article["published_time"]
        except (KeyError, TypeError):
            raise ValueError(
                f"article at index {index} is missing 'category' or 'published_time'"
            ) from None

        if isinstance(published_time, datetime):
            moment = published_time
        else:
            moment = datetime.fromisoformat(published_time)

        if moment.tzinfo is None:
            moment = moment.replace(tzinfo=dt_timezone.utc)

        hour = moment.astimezone(tz).hour
        hours_by_category.setdefault(category, []).append(hour)

    stats = {}
    for category in sorted(hours_by_category):
        hours = hours_by_category[category]
        stats[category] = {
            "count": len(hours),
            "mean": sum(hours) / len(hours),
            "min": min(hours),
            "max": max(hours),
        }
    return stats

