import math


def column_correlations(data):
    """Return the pairwise Pearson correlation matrix of the given columns.

    ``data`` maps column names to equal-length sequences of numbers.  The
    result is a nested dict where ``result[x][y]`` is the Pearson correlation
    between columns ``x`` and ``y``, with 1.0 on the diagonal.

    Correlations involving a column with zero variance (which includes columns
    with fewer than two values) are undefined; those off-diagonal entries are
    reported as 0.0.
    """
    names = list(data.keys())
    columns = {name: [float(value) for value in data[name]] for name in names}

    # Columns are documented as equal length; trim defensively so every
    # statistic is computed over the same observations.
    lengths = [len(values) for values in columns.values()]
    if lengths:
        length = min(lengths)
        columns = {name: values[:length] for name, values in columns.items()}

    deviations = {}
    variances = {}
    for name in names:
        values = columns[name]
        mean = math.fsum(values) / len(values) if values else 0.0
        centered = [value - mean for value in values]
        deviations[name] = centered
        variances[name] = math.fsum(d * d for d in centered)

    def correlation(x, y):
        if x == y:
            return 1.0
        variance_x = variances[x]
        variance_y = variances[y]
        if variance_x <= 0.0 or variance_y <= 0.0:
            return 0.0
        if len(deviations[x]) < 2:
            return 0.0
        covariance = math.fsum(
            dx * dy for dx, dy in zip(deviations[x], deviations[y])
        )
        value = covariance / math.sqrt(variance_x * variance_y)
        # Guard against tiny floating point excursions outside [-1, 1].
        return max(-1.0, min(1.0, value))

    return {x: {y: correlation(x, y) for y in names} for x in names}

