from __future__ import annotations

import csv
import io
from typing import Any


def _parse_number(text: str) -> int | float | None:
    """Return ``text`` as an int or float, or None if it is not numeric."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        pass
    try:
        value = float(stripped)
    except ValueError:
        return None
    return value


def _read_table(csv_text: str) -> tuple[list[str], list[list[str]]]:
    """Split ``csv_text`` into a header list and a list of raw rows."""
    if csv_text.startswith("\ufeff"):
        csv_text = csv_text[1:]
    reader = csv.reader(io.StringIO(csv_text, newline=""))
    rows = [row for row in reader]
    if not rows:
        return [], []
    header = [name.strip() for name in rows[0]]
    body = [row for row in rows[1:] if any(cell.strip() for cell in row)]
    return header, body


def sort_csv_rows(csv_text: str, sort_by_column: str = "title") -> list[dict[str, Any]]:
    """Return the CSV data rows as dicts, sorted ascending by ``sort_by_column``.

    Columns whose values are all numeric are converted to int/float and sorted
    numerically; every other column keeps its string values. Rows with equal
    sort keys keep their original file order.
    """
    header, body = _read_table(csv_text)
    if not header:
        return []
    if sort_by_column not in header:
        raise KeyError(f"column not found in CSV header: {sort_by_column!r}")

    width = len(header)
    padded = [row + [""] * (width - len(row)) for row in body]

    columns: dict[str, list[Any]] = {}
    for index, name in enumerate(header):
        raw = [row[index] for row in padded]
        numeric = [_parse_number(value) for value in raw]
        columns[name] = raw if any(value is None for value in numeric) else numeric

    records: list[dict[str, Any]] = []
    for row_index in range(len(padded)):
        records.append(
            {name: columns[name][row_index] for name in header}
        )

    key_values = columns[sort_by_column]
    if key_values and all(isinstance(value, (int, float)) for value in key_values):
        key = lambda record: record[sort_by_column]  # noqa: E731
    else:
        key = lambda record: record[sort_by_column]  # noqa: E731

    return sorted(records, key=key)

