import math


def _quantile(sorted_values, q):
    """Return the linearly interpolated q-quantile of sorted values."""
    n = len(sorted_values)
    if n == 0:
        return float("nan")
    if n == 1:
        return float(sorted_values[0])

    position = (n - 1) * q
    lower = math.floor(position)
    upper = math.ceil(position)
    if lower == upper:
        return float(sorted_values[lower])

    lower_value = sorted_values[lower]
    upper_value = sorted_values[upper]
    fraction = position - lower
    return float(lower_value + (upper_value - lower_value) * fraction)


def _describe(values):
    present = [value for value in values if value is not None]
    if not present:
        return {
            "count": 0.0,
            "mean": float("nan"),
            "std": float("nan"),
            "min": float("nan"),
            "25%": float("nan"),
            "50%": float("nan"),
            "75%": float("nan"),
            "max": float("nan"),
        }

    mean = math.fsum(present) / len(present)
    filled = [mean if value is None else value for value in values]
    sorted_values = sorted(filled)

    count = float(len(filled))
    if len(filled) > 1:
        variance = math.fsum((value - mean) ** 2 for value in filled) / (
            len(filled) - 1
        )
        std = math.sqrt(variance)
    else:
        std = float("nan")

    return {
        "count": count,
        "mean": float(mean),
        "std": float(std),
        "min": float(sorted_values[0]),
        "25%": _quantile(sorted_values, 0.25),
        "50%": _quantile(sorted_values, 0.50),
        "75%": _quantile(sorted_values, 0.75),
        "max": float(sorted_values[-1]),
    }


def describe_filled_columns(columns):
    """Fill missing column values with the column mean and summarize them."""
    return {name: _describe(values) for name, values in columns.items()}

