"""Discrete Fourier transform magnitudes and their 10-bin histogram."""

from __future__ import annotations

BIN_COUNT = 10


def _magnitudes(values):
    """Magnitudes of the DFT of ``values``, in the order the coefficients come in."""
    try:
        import numpy as np
    except ImportError:  # pragma: no cover - numpy is part of the environment
        np = None

    if np is not None:
        return np.abs(np.fft.fft(np.asarray(values, dtype=float))).tolist()

    import cmath
    import math

    n = len(values)
    result = []
    for k in range(n):
        coefficient = 0j
        for index, value in enumerate(values):
            coefficient += value * cmath.exp(-2j * math.pi * k * index / n)
        result.append(math.sqrt(coefficient.real ** 2 + coefficient.imag ** 2))
    return result


def _histogram(magnitudes, bins=BIN_COUNT):
    """Counts of ``bins`` equal-width bins spanning the magnitudes."""
    try:
        import numpy as np
    except ImportError:  # pragma: no cover - numpy is part of the environment
        np = None

    if np is not None:
        counts, _ = np.histogram(np.asarray(magnitudes, dtype=float), bins=bins)
        return counts.tolist()

    import bisect

    low = min(magnitudes)
    high = max(magnitudes)
    if low == high:
        # A degenerate span is widened so that the single occupied value lands
        # in the middle bin, mirroring numpy's behaviour.
        low -= 0.5
        high += 0.5

    step = (high - low) / bins
    edges = [low + index * step for index in range(bins + 1)]
    edges[-1] = high
    inner = edges[1:-1]

    counts = [0] * bins
    for magnitude in magnitudes:
        if magnitude >= high:
            counts[bins - 1] += 1
        elif magnitude < low:
            continue
        else:
            counts[bisect.bisect_right(inner, magnitude)] += 1
    return counts


def spectrum_magnitude_histogram(pairs):
    """Return the DFT magnitudes of the pair values and a 10-bin histogram of them."""
    values = [value for _, value in pairs]
    if not values:
        return ([], [])
    magnitudes = _magnitudes(values)
    return (magnitudes, _histogram(magnitudes))

