"""Cumulative sums, min-max scaled to [0, 1]."""

import math
import numbers


def normalized_cumulative_sums(data):
    """Return each column's cumulative sum, min-max scaled to [0, 1].

    ``data`` maps column names to equal-length lists of numbers. A column
    whose cumulative sum is constant is returned as all zeros.

    Raises:
        TypeError: if a column contains a non-numeric value.
        ValueError: if ``data`` is empty, a column contains NaN, or the
            columns do not all have the same length.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dict mapping names to lists of numbers")
    if not data:
        raise ValueError("data must not be empty")

    lengths = set()
    for name, column in data.items():
        try:
            length = len(column)
        except TypeError:
            raise TypeError(
                "column %r is not a sequence of numbers" % (name,)
            ) from None
        lengths.add(length)
    if len(lengths) > 1:
        raise ValueError("all columns must have the same length")

    result = {}
    for name, column in data.items():
        running = 0.0
        cumulative = []
        for value in column:
            if not isinstance(value, numbers.Number) or isinstance(value, complex):
                raise TypeError(
                    "column %r contains a non-numeric value: %r" % (name, value)
                )
            number = float(value)
            if math.isnan(number):
                raise ValueError("column %r contains NaN" % (name,))
            running += number
            cumulative.append(running)

        if not cumulative:
            result[name] = []
            continue

        low = min(cumulative)
        high = max(cumulative)
        if high == low:
            result[name] = [0.0] * len(cumulative)
        else:
            span = high - low
            result[name] = [(value - low) / span for value in cumulative]

    return result

