"""Descriptive statistics for the positions of a simple random walk."""

import math


def _percentile(sorted_values, q):
    """Linear-interpolation percentile (numpy's default 'linear' method)."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])
    pos = (q / 100.0) * (n - 1)
    lower = int(math.floor(pos))
    upper = int(math.ceil(pos))
    if lower == upper:
        return float(sorted_values[lower])
    frac = pos - lower
    return float(sorted_values[lower] + frac * (sorted_values[upper] - sorted_values[lower]))


def random_walk_stats(steps):
    if not steps:
        raise ValueError("steps must be a non-empty sequence")

    positions = []
    total = 0
    for step in steps:
        total += step
        positions.append(total)

    n = len(positions)
    mean = sum(positions) / n

    if n > 1:
        variance = sum((p - mean) ** 2 for p in positions) / (n - 1)
        std = math.sqrt(variance)
    else:
        std = float("nan")

    ordered = sorted(positions)

    return {
        "count": float(n),
        "mean": float(mean),
        "std": float(std),
        "min": float(ordered[0]),
        "5%": _percentile(ordered, 5),
        "25%": _percentile(ordered, 25),
        "50%": _percentile(ordered, 50),
        "75%": _percentile(ordered, 75),
        "95%": _percentile(ordered, 95),
        "max": float(ordered[-1]),
    }

