def _is_number(value):
    """True for real numeric values; booleans are not treated as numbers."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def cumulative_column_sums(data):
    """Return running sums down every numeric column of ``data``.

    ``data`` maps column names to equal-length lists of values. Columns whose
    values are not all numbers are skipped. The result maps each numeric column
    name to the list of its cumulative sums, in the original column order.

    Raises:
        ValueError: if the table has no rows or contains no numeric columns.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")

    num_rows = None
    for values in data.values():
        num_rows = len(values)
        break

    if not num_rows:
        raise ValueError("table has no rows")

    result = {}
    for name, values in data.items():
        if len(values) != num_rows:
            raise ValueError(
                "column %r has %d values, expected %d"
                % (name, len(values), num_rows)
            )
        if not all(_is_number(value) for value in values):
            continue

        running = []
        total = 0
        for value in values:
            total += value
            running.append(total)
        result[name] = running

    if not result:
        raise ValueError("table has no numeric columns")

    return result

