import ast
import csv
import io
import math


def _unquote(text):
    """Strip whitespace and any enclosing quotes from a field value."""
    text = text.strip()
    while len(text) >= 2 and text[0] == text[-1] and text[0] in "\"'":
        text = text[1:-1].strip()
    return text


def _to_number(token):
    """Convert a single numeric token to int when possible, else float."""
    token = token.strip().strip("\"'[]").strip()
    if not token:
        return None
    try:
        if "_" not in token and "." not in token and "e" not in token.lower():
            return int(token)
        return float(token)
    except ValueError:
        return None


def _parse_list(value):
    """Turn a string like "[1, 2, 3]" into a list of numbers."""
    if value is None:
        return []
    text = _unquote(value)
    if not text:
        return []
    try:
        parsed = ast.literal_eval(text)
    except (ValueError, SyntaxError):
        # Fall back to scanning comma-separated tokens for numbers.
        numbers = []
        for token in text.replace(";", ",").split(","):
            number = _to_number(token)
            if number is not None:
                numbers.append(number)
        return numbers
    if isinstance(parsed, (int, float)):
        return [parsed]
    return list(parsed)


def _stats(values):
    """Return (sum, mean, population standard deviation) for the numbers."""
    n = len(values)
    if n == 0:
        return 0, 0.0, 0.0
    total = sum(values)
    mean = total / n
    variance = sum((x - mean) ** 2 for x in values) / n
    return total, mean, math.sqrt(variance)


def _find_column(header, name, taken):
    """Index of the column called `name`, exact match first, then substring."""
    for i, cell in enumerate(header):
        if cell == name and i not in taken:
            return i
    for i, cell in enumerate(header):
        if name in cell and i not in taken:
            return i
    return None


def summarize_email_lists(csv_text):
    """Return [(email, sum, mean, std), ...] for each data row, in file order."""
    if isinstance(csv_text, bytes):
        csv_text = csv_text.decode("utf-8-sig")
