    if not rows:
        return []

    header = [cell.strip().lower() for cell in rows[0]]
    email_idx = _find_column(header, "email", set())
    list_idx = _find_column(header, "list", {email_idx} if email_idx is not None else set())

    if email_idx is None and list_idx is None:
        email_idx, list_idx = 0, 1
        data_rows = rows
        list_is_last = True
    else:
        email_idx = 0 if email_idx is None else email_idx
        list_idx = 1 if list_idx is None else list_idx
        data_rows = rows[1:]
