import xml.etree.ElementTree as ET

__all__ = ["xml_to_dict"]


def xml_to_dict(xml):
    """Parse *xml* and return ``{root_tag: value}``.

    A leaf element (no attributes, no child elements) maps to its trimmed text,
    or ``None`` when it has no text. Every other element maps to a dict with
    attributes prefixed by ``'@'``, child elements keyed by tag, and any trimmed
    text under ``'#text'``. Tags repeated among siblings collect into a list in
    document order.

    Raises ``ValueError`` when *xml* is not well-formed.
    """
    if isinstance(xml, (bytes, bytearray)):
        if not bytes(xml).strip():
            raise ValueError("Malformed XML: empty document")
    elif isinstance(xml, str):
        if not xml.strip():
            raise ValueError("Malformed XML: empty document")
    else:
        raise TypeError("xml_to_dict() expects an XML string")

    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError("Malformed XML: %s" % exc) from exc

    return {root.tag: _element_value(root)}


def _element_value(elem):
    """Recursively convert a single element into its Python value."""
    children = list(elem)

    if not children and not elem.attrib:
        return _text_value(elem.text)

    value = {}
    for name, attr_value in elem.attrib.items():
        value["@" + name] = attr_value

    text = _text_value(elem.text)
    if text is not None:
        value["#text"] = text

    for child in children:
        tag = child.tag
        if not isinstance(tag, str):  # comments / processing instructions
            continue
        child_value = _element_value(child)
        if tag not in value:
            value[tag] = child_value
        elif isinstance(value[tag], list):
            value[tag].append(child_value)
        else:
            value[tag] = [value[tag], child_value]

    return value


def _text_value(text):
    """Return trimmed *text*, or ``None`` when it is missing or blank."""
    if text is None:
        return None
    trimmed = text.strip()
    return trimmed if trimmed else None

