import math


def standardize_columns(rows, columns, features):
    """Rescale each listed feature column to zero mean and unit variance.

    Uses the population standard deviation. A constant feature column becomes
    all zeros. Columns that are not listed are copied through unchanged.
    """
    result = [list(row) for row in rows]
    if not result:
        return result

    index_of = {}
    for i, name in enumerate(columns):
        index_of.setdefault(name, i)

    n = len(result)
    for feature in features:
        if feature not in index_of:
            continue
        j = index_of[feature]
        values = [float(row[j]) for row in result]
        mean = sum(values) / n
        variance = sum((v - mean) ** 2 for v in values) / n
        std = math.sqrt(variance)
        if std == 0:
            for row in result:
                row[j] = 0.0
        else:
            for row, v in zip(result, values):
                row[j] = (v - mean) / std

    return result

