import math
import numbers


def row_averages_and_correlations(data):
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")

    if not data:
        return [], []

    if any(not isinstance(row, list) for row in data):
        raise ValueError("every row must be a list")

    num_columns = len(data[0])
    if num_columns == 0:
        raise ValueError("rows must contain at least one number")

    for row in data:
        if len(row) != num_columns:
            raise ValueError("data must be rectangular")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, numbers.Real):
                raise ValueError("all entries must be real numbers")

    averages = [sum(row) / num_columns for row in data]

    num_rows = len(data)
    column_means = [
        sum(row[column] for row in data) / num_rows
        for column in range(num_columns)
    ]

    corr = [[0.0 for _ in range(num_columns)] for _ in range(num_columns)]
    for i in range(num_columns):
        corr[i][i] = 1.0
        for j in range(i + 1, num_columns):
            covariance = sum(
                (data[row][i] - column_means[i])
                * (data[row][j] - column_means[j])
                for row in range(num_rows)
            )
            variance_i = sum(
                (data[row][i] - column_means[i]) ** 2
                for row in range(num_rows)
            )
            variance_j = sum(
                (data[row][j] - column_means[j]) ** 2
                for row in range(num_rows)
            )

            if variance_i == 0 or variance_j == 0:
                correlation = 0.0
            else:
                correlation = covariance / math.sqrt(variance_i * variance_j)
                correlation = max(-1.0, min(1.0, correlation))

            corr[i][j] = correlation
            corr[j][i] = correlation

    return averages, corr

