def interquartile_range_nested(L):
    """Return the interquartile range of all numbers in nested lists.

    Quartiles are computed using linear interpolation between data points,
    with positions based on 0.25 and 0.75 of (n - 1).
    """
    values = sorted(number for sublist in L for number in sublist)
    n = len(values)

    if n == 0:
        return 0.0
    if n == 1:
        return 0.0

    def percentile(fraction):
        position = fraction * (n - 1)
        lower = int(position)
        upper = min(lower + 1, n - 1)
        weight = position - lower
        return values[lower] + weight * (values[upper] - values[lower])

    return float(percentile(0.75) - percentile(0.25))

