"""Aggregate sales records into per-calendar-day totals."""

from datetime import date, datetime, timedelta


def _to_date(value):
    """Return the calendar date described by an ISO date/datetime value."""
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value).strip()
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(text).date()
    except ValueError:
        return date.fromisoformat(text)


def daily_sales_totals(dates, sales):
    """Total the sale amounts per day, filling gaps with zeros.

    ``dates`` holds ISO date or datetime strings and ``sales`` the matching
    amounts.  The result is a list of ``('YYYY-MM-DD', total)`` tuples covering
    every day from the earliest to the latest record, in chronological order.
    """
    records = list(zip(dates, sales))
    if not records:
        raise ValueError("no sales records provided")

    totals = {}
    for raw_day, amount in records:
        day = _to_date(raw_day)
        totals[day] = totals.get(day, 0) + amount

    first, last = min(totals), max(totals)
    result = []
    day = first
    while day <= last:
        result.append((day.isoformat(), totals.get(day, 0)))
        day += timedelta(days=1)
    return result

