import math


def standardized_tensor_product(P, T):
    """Contract P (m x k) with every slice T[:, j, :] (k x p), flatten the
    n resulting m x p products row by row into a table, then standardise
    each column to zero mean and unit population variance.
    """
    if not P or not T:
        raise ValueError("P and T must both be non-empty")

    m = len(P)
    k = len(P[0])
    if k == 0 or any(len(row) != k for row in P):
        raise ValueError("P must be a non-empty rectangular matrix")

    if len(T) != k:
        raise ValueError(
            "P has %d columns but T has %d entries along its first axis"
            % (k, len(T))
        )

    n = len(T[0])
    p = len(T[0][0]) if n else 0
    for block in T:
        if len(block) != n:
            raise ValueError("T must be rectangular along its second axis")
        for row in block:
            if len(row) != p:
                raise ValueError("T must be rectangular along its third axis")

    if n == 0:
        return []

    # table[j] is the flattened m x p product P @ T[:, j, :]
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            Pi = P[i]
            for q in range(p):
                acc = 0.0
                for t in range(k):
                    acc += Pi[t] * T[t][j][q]
                row.append(float(acc))
        table.append(row)

    # Standardise each column with the population standard deviation.
    width = m * p
    for c in range(width):
        column = [table[r][c] for r in range(n)]
        mean = sum(column) / n
        var = sum((x - mean) ** 2 for x in column) / n
        if var == 0.0:
            for r in range(n):
                table[r][c] = 0.0
            continue
        for r in range(n):
            dev = column[r] - mean
            if dev == 0.0:
                table[r][c] = 0.0
                continue
            # sqrt(dev**2 / var) is the same real number as dev / sqrt(var)
            # but rounds more accurately.
            mag = math.sqrt((dev * dev) / var)
            table[r][c] = -mag if dev < 0 else mag

    return table

