def quartiles_of_string_groups(groups):
    """Return the 25th, 50th and 75th percentiles of all integers in groups.

    Each group is a tuple of base-10 integer strings. The percentiles use
    linear interpolation between the closest ranks.
    """
    values = sorted(int(value) for group in groups for value in group)
    if not values:
        raise ValueError("groups must contain at least one integer")

    last = len(values) - 1

    def percentile(percent):
        rank = last * percent / 100
        lower = int(rank)
        upper = min(lower + 1, last)
        fraction = rank - lower
        return float(
            values[lower] + (values[upper] - values[lower]) * fraction
        )

    return (percentile(25), percentile(50), percentile(75))

