def scale_by_group_with_histogram(ids, ages, incomes):
    """Min-max scale ages and incomes within each id group, then histogram.

    Returns ``(scaled, counts)`` where ``scaled`` holds ``[age, income]``
    pairs in the original row order and ``counts`` holds ten bin counts of
    the scaled incomes over [0, 1] (the last bin also takes 1).
    """
    if len(ids) != len(ages) or len(ids) != len(incomes):
        raise ValueError("ids, ages and incomes must have the same length")
    if not ids:
        raise ValueError("cannot scale an empty data set")

    bounds = {}
    for group_id, age, income in zip(ids, ages, incomes):
        if group_id not in bounds:
            bounds[group_id] = [age, age, income, income]
        else:
            lo = bounds[group_id]
            if age < lo[0]:
                lo[0] = age
            elif age > lo[1]:
                lo[1] = age
            if income < lo[2]:
                lo[2] = income
            elif income > lo[3]:
                lo[3] = income

    params = {}
    for group_id, (age_min, age_max, income_min, income_max) in bounds.items():
        age_range = age_max - age_min
        income_range = income_max - income_min
        age_scale = 1.0 / age_range if age_range else 0.0
        income_scale = 1.0 / income_range if income_range else 0.0
        params[group_id] = (
            age_scale,
            -age_min * age_scale if age_range else 0.0,
            income_scale,
            -income_min * income_scale if income_range else 0.0,
        )

    scaled = []
    for group_id, age, income in zip(ids, ages, incomes):
        age_scale, age_offset, income_scale, income_offset = params[group_id]
        scaled.append([
            age * age_scale + age_offset,
            income * income_scale + income_offset,
        ])

    counts = [0] * 10
    for _, scaled_income in scaled:
        if scaled_income <= 0.0:
            index = 0
        elif scaled_income >= 1.0:
            index = 9
        else:
            index = int(scaled_income * 10)
        counts[index] += 1

    return scaled, counts

