import csv
import io
import math

__all__ = ["fill_missing_with_column_mean"]


def _is_blank(cell):
    """A cell counts as missing when it holds only whitespace."""
    return cell is None or cell.strip() == ""


def _parse_number(cell):
    """Return the float value of ``cell``, or None if it is not numeric."""
    text = cell.strip()
    if not text:
        return None
    try:
        value = float(text)
    except ValueError:
        return None
    if math.isnan(value) or math.isinf(value):
        return None
    return value


def fill_missing_with_column_mean(csv_text):
    """Map each CSV column name to its list of values, in row order.

    Columns whose present cells all parse as numbers are returned as floats,
    with empty cells replaced by the mean of the present values. Every other
    column keeps its strings, with empty cells replaced by None. A column with
    no present values becomes a list of None. Empty input yields {}.
    """
    if csv_text is None:
        return {}
    if isinstance(csv_text, (bytes, bytearray)):
        csv_text = bytes(csv_text).decode("utf-8-sig")
    if not csv_text.strip():
        return {}

    reader = csv.reader(io.StringIO(csv_text.lstrip("\ufeff"), newline=""))
    rows = [row for row in reader if row]
    if not rows:
        return {}

    header = [name.strip() for name in rows[0]]
    body = rows[1:]
    width = len(header)

    columns = {}
    for index, name in enumerate(header):
        cells = []
        for row in body:
            cells.append(row[index] if index < len(row) else "")
        present = [cell for cell in cells if not _is_blank(cell)]

        if not present:
            columns[name] = [None] * len(cells)
            continue

        numbers = [_parse_number(cell) for cell in present]
        if any(value is None for value in numbers):
            columns[name] = [None if _is_blank(cell) else cell for cell in cells]
            continue

        mean = sum(numbers) / len(numbers)
        columns[name] = [
            mean if _is_blank(cell) else _parse_number(cell) for cell in cells
        ]

    return columns

