import math
from fractions import Fraction


def first_column_match_stats(target_value, rows):
    indices = [
        index
        for index, row in enumerate(rows)
        if row and row[0] == target_value
    ]

    if not indices:
        return ('N/A', 'N/A', 'N/A', 'N/A')
    if len(indices) == 1:
        return (indices[0], 'N/A', 'N/A', 'N/A')

    count = len(indices)
    total = sum(indices)

    # Work with integers (scaled deviations) so the central moments are exact.
    sum2 = sum3 = sum4 = 0
    for index in indices:
        deviation = count * index - total
        deviation2 = deviation * deviation
        sum2 += deviation2
        sum3 += deviation2 * deviation
        sum4 += deviation2 * deviation2

    m2 = Fraction(sum2, count ** 3)
    m3 = Fraction(sum3, count ** 4)
    m4 = Fraction(sum4, count ** 5)

    mean = total / count
    variance = float(m2)
    skewness = float(m3) / (variance * math.sqrt(variance))
    kurtosis = float(m4 / (m2 * m2) - 3)

    return (mean, variance, skewness, kurtosis)

