"""Table preprocessing: value replacement, categorical encoding, standardization."""

import math
import numbers


def _apply_replacements(values, replacements):
    """Map any value that is a key of ``replacements`` to its mapped value."""
    replaced = []
    for value in values:
        try:
            if value in replacements:
                value = replacements[value]
        except TypeError:  # unhashable values can never be keys
            pass
        replaced.append(value)
    return replaced


def _key(value):
    """Hashable identity for a value, so unhashable values can still be compared."""
    try:
        hash(value)
    except TypeError:
        return ("unhashable", repr(value))
    return ("hashable", value)


def _sorted_unique(values):
    """Distinct values in sorted order, tolerating values that do not compare."""
    unique = []
    seen = set()
    for value in values:
        key = _key(value)
        if key not in seen:
            seen.add(key)
            unique.append(value)
    try:
        unique.sort()
    except TypeError:
        unique.sort(key=lambda item: (type(item).__name__, repr(item)))
    return unique


def _encode(values):
    """Integer codes 0..k-1 assigned to the distinct values in sorted order."""
    unique = _sorted_unique(values)
    return [unique.index(value) for value in values]


def _standardize(values):
    """Subtract the mean and divide by the sample standard deviation."""
    count = len(values)
    if count < 2:
        return [float("nan")] * count
    total = sum(values)
    total_sq = sum(value * value for value in values)
    variance = (count * total_sq - total * total) / (count * (count - 1))
    if variance <= 0:
        return [float("nan")] * count
    scale = count * math.sqrt(variance)
    return [float(count * value - total) / scale for value in values]


def encode_and_standardize(data, replacements):
    """Replace, encode categorical columns, then standardize every column."""
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists of values")
    if not replacements:
        replacements = {}

    standardized = {}
    for column, values in data.items():
        replaced = _apply_replacements(list(values), replacements)
        if replaced and all(isinstance(value, numbers.Number) for value in replaced):
            column_values = replaced
        else:
            column_values = _encode(replaced)
        standardized[column] = _standardize(column_values)
    return standardized

