    """Distinct values in sorted order, tolerating values that do not compare."""
    unique = []
    seen = set()
    for value in values:
        key = _key(value)
        if key not in seen:
            seen.add(key)
            unique.append(value)
    try:
        unique.sort()
    except TypeError:
        unique.sort(key=lambda item: (type(item).__name__, repr(item)))
    return unique


