COLUMNS = ('Open', 'High', 'Low', 'Close', 'Volume')

# Index of each column inside a row: [date, open, high, low, close, volume]
_OFFSETS = {'Open': 1, 'High': 2, 'Low': 3, 'Close': 4, 'Volume': 5}


def _quantile(sorted_values, p):
    """Linear-interpolated quantile, with the position (n - 1) * p."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])
    position = (n - 1) * p
    lower = int(position)
    upper = min(lower + 1, n - 1)
    fraction = position - lower
    return float(sorted_values[lower] + (sorted_values[upper] - sorted_values[lower]) * fraction)


def summarize_stock_column(column, data):
    """Return count/mean/std/min/quartiles/max for one column of stock rows.

    ``data`` holds rows of ``[date, open, high, low, close, volume]``.
    ``None`` values are skipped; ``std`` is the sample standard deviation.
    """
    if column not in _OFFSETS:
        raise ValueError(
            'column must be one of %s, got %r' % (', '.join(COLUMNS), column)
        )

    index = _OFFSETS[column]
    values = []
    for row_number, row in enumerate(data or []):
        if not isinstance(row, (list, tuple)) or len(row) != 6:
            raise ValueError(
                'row %d must have exactly six entries, got %r' % (row_number, row)
            )
