        if value is None:
            continue
        values.append(value)

    count = len(values)
    if count == 0:
        return {
            'count': 0,
            'mean': None,
            'std': None,
            'min': None,
            '25%': None,
            '50%': None,
            '75%': None,
            'max': None,
        }

