import math


def _z_scores(values):
    """Standardize ``values`` to zero mean and unit variance.

    Returns ``None`` when the correlation is undefined for this column,
    i.e. when it is empty or has no spread (all values identical).
    """
    n = len(values)
    if n == 0:
        return None
    mean = math.fsum(values) / n
    deviations = [value - mean for value in values]
    sum_squares = math.fsum(d * d for d in deviations)
    if sum_squares == 0:
        return None
    scale = math.sqrt(sum_squares / n)
    return [d / scale for d in deviations]


def _is_numeric_column(values):
    return all(isinstance(value, (int, float)) for value in values)


def _pearson(x_scores, y_scores):
    n = len(x_scores)
    correlation = math.fsum(a * b for a, b in zip(x_scores, y_scores)) / n
    # Rounding leaves a perfect correlation a hair away from +-1 and can even
    # push it outside [-1, 1]; snap such values to the exact bounds.
    if correlation > 1.0 - 1e-12:
        return 1.0
    if correlation < -1.0 + 1e-12:
        return -1.0
    return correlation


def correlation_without_column(data, column):
    """Return the Pearson correlation matrix of ``data`` without ``column``.

    ``data`` maps column names to equal-length lists of values. The column
    named ``column`` is dropped if present, columns whose values are not all
    numbers are ignored, and every remaining pair is correlated. The result is
    a dict of dicts where ``result[x][y]`` is the correlation of columns ``x``
    and ``y``; correlations involving a column with no spread (empty or
    constant) are ``float('nan')``. Returns ``None`` when no numeric column
    remains.
    """
    scores = {}
    for name, values in data.items():
        if name == column:
            continue
        if not _is_numeric_column(values):
            continue
        scores[name] = _z_scores(values)

    if not scores:
        return None

    names = list(scores)
    result = {}
    for i, x in enumerate(names):
        x_scores = scores[x]
        row = {}
        for j, y in enumerate(names):
            if j < i:
                row[y] = result[y][x]
            elif i == j:
                row[y] = float("nan") if x_scores is None else 1.0
            else:
                y_scores = scores[y]
                if x_scores is None or y_scores is None:
                    row[y] = float("nan")
                else:
                    row[y] = _pearson(x_scores, y_scores)
        result[x] = row
    return result

