"""Histogram utilities for tabular column data."""

import numbers


def _is_number(value):
    """Return True for real numeric values, excluding booleans."""
    return isinstance(value, numbers.Real) and not isinstance(value, bool)


def column_histograms(table):
    """Compute 10-bin histograms for every numeric column in *table*.

    Non-numeric columns are omitted.  The result preserves the table's
    column order.  A ValueError is raised when *table* is not a non-empty
    dict, when its columns are malformed, or when it has no numeric columns.
    """
    if not isinstance(table, dict) or not table:
        raise ValueError("table must be a non-empty dict")

    expected_length = None
    numeric_columns = []

    for name, values in table.items():
        if not isinstance(values, list):
            raise ValueError("each column must be a list")

        if expected_length is None:
            expected_length = len(values)
        elif len(values) != expected_length:
            raise ValueError("all columns must have the same length")

        if values and all(_is_number(value) for value in values):
            numeric_columns.append((name, values))

    if not numeric_columns:
        raise ValueError("table must contain at least one numeric column")

    result = {}
    for name, values in numeric_columns:
        low = min(values)
        high = max(values)
        counts = [0] * 10

        if low == high:
            # The range has zero width; all values belong to the first bin.
            counts[0] = len(values)
        else:
            span = high - low
            for value in values:
                if value == high:
                    index = 9
                else:
                    position = (value - low) / span * 10
                    nearest = round(position)
                    # Correct tiny floating-point errors at exact bin edges.
                    if abs(position - nearest) <= 1e-9 * max(1.0, abs(position)):
                        position = nearest
                    index = int(position)
                    if index < 0:
                        index = 0
                    elif index > 9:
                        index = 9
                counts[index] += 1

        result[name] = counts

    return result

