import re


def tfidf_scores_for_question_articles(titles, contents):
    """Sum TF-IDF vectors for articles whose titles contain "how" or "what"."""
    selected_contents = [
        content
        for title, content in zip(titles, contents)
        if "how" in title.lower() or "what" in title.lower()
    ]

    if not selected_contents:
        return {}

    tokenized = [re.findall(r"\w{2,}", content.lower()) for content in selected_contents]
    n_articles = len(tokenized)

    document_frequency = {}
    for tokens in tokenized:
        for word in set(tokens):
            document_frequency[word] = document_frequency.get(word, 0) + 1

    scores = {}
    for tokens in tokenized:
        term_counts = {}
        for word in tokens:
            term_counts[word] = term_counts.get(word, 0) + 1

        vector = {
            word: count
            * (math.log((1 + n_articles) / (1 + document_frequency[word])) + 1)
            for word, count in term_counts.items()
        }
        norm = math.sqrt(sum(value * value for value in vector.values()))
        if norm:
            for word, value in vector.items():
                scores[word] = scores.get(word, 0.0) + value / norm

    return scores

