def _lookup(mapping, value):
    """Return (found, replacement) for value in mapping, tolerating unhashable values."""
    try:
        if value in mapping:
            return True, mapping[value]
    except TypeError:
        pass
    return False, None


def replace_and_standardize(data, features, mapping):
    """Replace values via mapping, then standardize the feature columns.

    Replacement is applied to every column of the table; the columns named in
    ``features`` are afterwards rescaled to zero mean and unit population
    standard deviation. Columns outside ``features`` keep their replaced
    values. Column order of ``data`` is preserved.
    """
    for name in features:
        if name not in data:
            raise ValueError("feature column missing from data: %r" % (name,))

    mapping = mapping or {}
    replaced = {}
    for name, values in data.items():
        new_values = []
        for value in values:
            found, replacement = _lookup(mapping, value)
            new_values.append(replacement if found else value)
        replaced[name] = new_values

    feature_set = set()
    for name in features:
        try:
            feature_set.add(name)
        except TypeError:
            raise ValueError("unhashable feature name: %r" % (name,))

    result = {}
    for name, values in replaced.items():
        if name not in feature_set:
            result[name] = values
            continue
        if not values:
            result[name] = []
            continue
        numeric = [float(v) for v in values]
        n = len(numeric)
        mean = sum(numeric) / n
        variance = sum((v - mean) ** 2 for v in numeric) / n
        std = variance ** 0.5
        if std == 0:
            result[name] = [0.0] * n
        else:
            result[name] = [(v - mean) / std for v in numeric]
    return result

