def normalize_columns(data_dict, data_keys):
    result = {}

    for key in data_keys:
        if key not in data_dict or key in result:
            continue

        values = data_dict[key]
        if not values:
            result[key] = []
            continue

        lowest = min(values)
        highest = max(values)
        span = highest - lowest

        if span == 0:
            result[key] = [0.0 for _ in values]
        else:
            result[key] = [float((value - lowest) / span) for value in values]

    if not result:
        raise ValueError("None of the requested columns are present in data_dict")

    return result

