"""Histogram helper for column-oriented tables."""

N_BINS = 10


def column_histogram(records, column_name):
    """Return the counts of a 10-bin equal-width histogram of a column.

    ``records`` is a list of dicts (the rows of a table) and ``column_name``
    names the column to summarise.  The bins span the column's minimum to its
    maximum, and a value equal to the maximum falls into the last bin.

    String columns are first encoded as the index of each value among the
    column's distinct values in sorted order.

    Raises ``ValueError`` when the column is not present in the table,
    including when there are no records.
    """
    if not records:
        raise ValueError(
            "cannot build a histogram: the table has no records"
        )

    values = []
    for row in records:
        if not isinstance(row, dict) or column_name not in row:
            raise ValueError(
                "column %r does not exist in the table" % (column_name,)
            )
        values.append(row[column_name])

    if all(isinstance(value, str) for value in values):
        ranks = {value: index for index, value in enumerate(sorted(set(values)))}
        values = [ranks[value] for value in values]

    low = min(values)
    high = max(values)
    counts = [0] * N_BINS

    if high == low:
        counts[-1] = len(values)
        return counts

    span = high - low
    for value in values:
        if value == high:
            index = N_BINS - 1
        else:
            index = int((value - low) * N_BINS // span)
            if index < 0:
                index = 0
            elif index > N_BINS - 1:
                index = N_BINS - 1
        counts[index] += 1

    return counts

