"""Word n-gram frequency counting."""

import re

_WORD_RE = re.compile(r"[^\W_]+", re.UNICODE)


def top_ngrams(text, n, top_k):
    """Return up to `top_k` (ngram, count) tuples, most frequent first.

    Case and punctuation are ignored, and n-grams span sentence boundaries.
    Each n-gram is its words joined by single spaces. Ties are broken by
    order of first appearance in the text.
    """
    if not isinstance(text, str) or not isinstance(n, int) or not isinstance(top_k, int):
        return []
    if n <= 0 or top_k <= 0:
        return []

    words = _WORD_RE.findall(text.lower())
    if len(words) < n:
        return []

    counts = {}
    first_seen = {}
    for i in range(len(words) - n + 1):
        gram = " ".join(words[i:i + n])
        if gram in counts:
            counts[gram] += 1
        else:
            counts[gram] = 1
            first_seen[gram] = i

    ordered = sorted(counts.items(), key=lambda item: (-item[1], first_seen[item[0]]))
    return ordered[:top_k]

