"""Boxplot statistics for a comma-separated number string nested in JSON."""

import json
import math


def _quantile(sorted_values, q):
    """Quantile with linear interpolation between data points."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])
    pos = q * (n - 1)
    lower = int(math.floor(pos))
    upper = int(math.ceil(pos))
    if lower == upper:
        return float(sorted_values[lower])
    frac = pos - lower
    return float(sorted_values[lower] + (sorted_values[upper] - sorted_values[lower]) * frac)


def _parse_values(raw):
    """Turn a comma-separated string into a list of finite floats."""
    if not isinstance(raw, str):
        raise ValueError("data at path is not a comma-separated string: %r" % (raw,))
    tokens = [token.strip() for token in raw.split(",")]
    numbers = []
    for token in tokens:
        if not token:
            continue
        try:
            value = float(token)
        except (TypeError, ValueError):
            raise ValueError("non-numeric value in data: %r" % (token,))
        if not math.isfinite(value):
            raise ValueError("non-finite value in data: %r" % (token,))
        numbers.append(value)
    if not numbers:
        raise ValueError("data string is empty")
    return numbers


def _resolve(json_data, key_path):
    """Walk key_path through nested objects and return the value found."""
    try:
        node = json.loads(json_data)
    except (TypeError, ValueError) as exc:
        raise ValueError("malformed JSON: %s" % (exc,))

    for key in key_path:
        if not isinstance(node, dict) or key not in node:
            raise KeyError(key)
        node = node[key]
    return node


def boxplot_stats_at_path(json_data, key_path):
    """Return q1/median/q3/whiskers/outliers for the numbers at key_path."""
    values = sorted(_parse_values(_resolve(json_data, list(key_path))))

    q1 = _quantile(values, 0.25)
    median = _quantile(values, 0.5)
    q3 = _quantile(values, 0.75)
    iqr = q3 - q1
    low_fence = q1 - 1.5 * iqr
    high_fence = q3 + 1.5 * iqr

    inliers = [v for v in values if low_fence <= v <= high_fence]
    outliers = [v for v in values if v < low_fence or v > high_fence]

    return {
        "q1": q1,
        "median": median,
        "q3": q3,
        "whisker_low": float(min(inliers)),
        "whisker_high": float(max(inliers)),
        "outliers": [float(v) for v in outliers],
    }

