import xml.etree.ElementTree as ET


def _own_text(element):
    """Direct text of an element: its text plus the tail of each child."""
    parts = [element.text or ""]
    for child in element:
        parts.append(child.tail or "")
    return "".join(parts).strip()


def _element_value(element):
    children = list(element)
    attributes = element.attrib
    text = _own_text(element)

    if not children and not attributes:
        return text if text else None

    result = {}
    for name, value in attributes.items():
        result["@" + name] = value

    if text:
        result["#text"] = text

    for child in children:
        tag = child.tag
        value = _element_value(child)
        if tag in result:
            if isinstance(result[tag], list):
                result[tag].append(value)
            else:
                result[tag] = [result[tag], value]
        else:
            result[tag] = value

    return result


def xml_to_dict(s):
    """Parse an XML string into nested dicts keyed by tag."""
    if s is None:
        raise ValueError("XML input is empty")
    if isinstance(s, bytes):
        text = s.decode("utf-8")
    else:
        text = s
    if not text.strip():
        raise ValueError("XML input is empty")

    root = ET.fromstring(text)
    return {root.tag: _element_value(root)}

