    report_dates = []
    year, month = start.year, start.month
    while len(report_dates) < periods:
        candidate = _second_friday(year, month)
        if candidate >= start:
            report_dates.append(candidate)
        if month == 12:
            year, month = year + 1, 1
        else:
            month += 1

    report = []
    index = 0
    for day in report_dates:
        stamp = day.isoformat()
        for category in categories:
            report.append((stamp, category, sales[index]))
            index += 1
    return report

