            is_target = False
            if not self._found and self._attr(attrs, "id") == self._table_id:
                is_target = True
                self._found = True
                self.rows = []
            self._frames.append({
                "is_target": is_target,
                "rows": self.rows if is_target else [],
                "row": None,
                "cell": None,
            })
            return

