import csv
import io
import math


def _parse_int(text):
    try:
        return int(text)
    except (TypeError, ValueError):
        return None


def _parse_float(text):
    try:
        value = float(text)
    except (TypeError, ValueError):
        return None
    if math.isnan(value) or math.isinf(value):
        return None
    return value


def _convert_column(values):
    """Convert a column's raw strings to int/float if all of them are numeric."""
    if not values:
        return values

    ints = []
    for value in values:
        parsed = _parse_int(value)
        if parsed is None:
            ints = None
            break
        ints.append(parsed)
    if ints is not None:
        return ints

    floats = []
    for value in values:
        parsed = _parse_float(value)
        if parsed is None:
            return values
        floats.append(parsed)
    return floats


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("concat_csv_tables requires at least one CSV document")

    columns = None
    rows = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text, newline=""))
        records = [record for record in reader if record]
        if not records:
            continue

        header = [name.strip() for name in records[0]]
        if columns is None:
            columns = header

        index = {}
        for position, name in enumerate(header):
            index.setdefault(name, position)

        for record in records[1:]:
            row = {}
            for name in columns:
                position = index.get(name)
                if position is None or position >= len(record):
                    row[name] = ""
                else:
                    row[name] = record[position]
            rows.append(row)

    if columns is None:
        return []

    converted = {}
    for name in columns:
        converted[name] = _convert_column([row[name] for row in rows])

    return [
        {name: converted[name][i] for name in columns}
        for i in range(len(rows))
    ]

