import csv
import io
import math


def column_summary_stats(csv_text, column_name):
    """Return mean, median and population standard deviation of a CSV column.

    ``csv_text`` is the full text of a CSV file whose first row is a header.
    ``column_name`` selects one of those header columns. Blank cells are
    ignored; every other cell must parse as a number.

    Raises ValueError if the column is absent from the header or holds no
    numeric values.
    """
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row and any(cell.strip() for cell in row)]
    if not rows:
        raise ValueError("CSV text is empty; expected a header row")

    header = [cell.strip().lstrip("\ufeff") for cell in rows[0]]
    target = str(column_name).strip()
    try:
        index = header.index(target)
    except ValueError:
        raise ValueError(f"column {column_name!r} not found in header {header!r}") from None

    values = []
    for row in rows[1:]:
        if index >= len(row):
            continue
        cell = row[index].strip()
        if not cell:
            continue
        try:
            values.append(float(cell))
        except ValueError:
            raise ValueError(
                f"non-numeric value {cell!r} in column {column_name!r}"
            ) from None

    if not values:
        raise ValueError(f"column {column_name!r} contains no numeric values")

    n = len(values)
    mean = math.fsum(values) / n

    ordered = sorted(values)
    mid = n // 2
    if n % 2:
        median = ordered[mid]
    else:
        median = (ordered[mid - 1] + ordered[mid]) / 2.0

    variance = math.fsum((value - mean) ** 2 for value in values) / n
    std_dev = math.sqrt(variance)

    return {"mean": mean, "median": median, "std_dev": std_dev}

