import math


def _to_number(value, mapping):
    """Replace `value` via `mapping` (when it is a key) and coerce to float."""
    try:
        if value in mapping:
            value = mapping[value]
    except TypeError:  # unhashable value can never be a mapping key
        pass
    return float(value)


def _pearson(xs, ys):
    """Pearson correlation of two equal-length numeric sequences."""
    n = len(xs)
    if n != len(ys):
        raise ValueError("columns must have the same length")
    if n == 0:
        return float("nan")

    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    dx = [x - mean_x for x in xs]
    dy = [y - mean_y for y in ys]

    sxy = sum(a * b for a, b in zip(dx, dy))
    sxx = sum(a * a for a in dx)
    syy = sum(b * b for b in dy)

    if sxx == 0.0 or syy == 0.0:
        return float("nan")

    r = sxy / math.sqrt(sxx * syy)
    # guard against tiny floating point overshoot
    if r > 1.0:
        r = 1.0
    elif r < -1.0:
        r = -1.0
    return r


def mapped_correlation_matrix(data, mapping):
    """Pairwise Pearson correlation matrix of the columns of `data`.

    Values are first replaced through `mapping`; any value not present as a
    key is kept as is. Returns a nested dict ``result[a][b]``.
    """
    if not isinstance(data, dict):
        raise ValueError("data must be a dict mapping column names to lists")

    mapping = {} if mapping is None else mapping

    columns = list(data.keys())
    prepared = {}
    for name in columns:
        prepared[name] = [_to_number(v, mapping) for v in data[name]]

    result = {}
    for a in columns:
        row = {}
        for b in columns:
            row[b] = _pearson(prepared[a], prepared[b])
        result[a] = row
    return result

