import csv
import io


def csv_mean_median(csv_text):
    """Return (mean, median) of the numeric values in a single-column CSV.

    The first row is treated as a header. Blank rows and values that cannot be
    parsed as numbers are ignored. Returns (None, None) when there are no
    numeric values.
    """
    if not csv_text:
        return (None, None)

    values = []
    reader = csv.reader(io.StringIO(csv_text))
    for index, row in enumerate(reader):
        if index == 0:
            continue
        if not row:
            continue
        cell = row[0]
        if not cell or not cell.strip():
            continue
        try:
            value = float(cell)
        except ValueError:
            continue
        if value != value:  # NaN is not a usable numeric value
            continue
        values.append(value)

    if not values:
        return (None, None)

    mean = sum(values) / len(values)

    ordered = sorted(values)
    mid = len(ordered) // 2
    if len(ordered) % 2 == 1:
        median = ordered[mid]
    else:
        median = (ordered[mid - 1] + ordered[mid]) / 2.0

    return (float(mean), float(median))

