"""Voronoi neighbours of a planar point set.

Two points are neighbours in the Voronoi diagram exactly when their cells share
an edge, which happens exactly when there is a circle through both points that
contains no other point of the set in its interior (the centre of such a circle
lies on the shared Voronoi edge, and conversely every point of the shared edge
gives such a circle).  Equivalently, the pair is an edge of the Delaunay
triangulation.

The candidate centres for a pair (i, j) lie on the perpendicular bisector of the
segment i-j, so they can be written as ``c(t) = mid + t * n`` with ``n`` normal
to ``i - j``.  A point ``m`` lies strictly inside the circle through ``i`` and
``c(t)`` iff ``|c - m| < |c - i|``, which expands to the linear condition

    t * (n . (m - i)) > ((m . m - i . i) / 2) - mid . (m - i),

i.e. every other point forbids an open ray of parameters.  The pair is a
neighbour iff those forbidden rays do not cover the whole bisector line.

All arithmetic is done on integers (coordinates are scaled by the least common
multiple of their denominators), so the predicates are exact and no epsilon is
needed.
"""

from fractions import Fraction
from math import gcd, isfinite

__all__ = ["voronoi_neighbors"]


def _as_fraction(value):
    """Convert a coordinate to an exact Fraction (floats are taken literally)."""
    if isinstance(value, Fraction):
        return value
    if isinstance(value, float):
        if not isfinite(value):
            raise ValueError("coordinates must be finite numbers")
        return Fraction(value)
    try:
        return Fraction(value)
    except (TypeError, ValueError):
        pass
    ratio = getattr(value, "as_integer_ratio", None)
    if callable(ratio):
        try:
            numerator, denominator = ratio()
            return Fraction(int(numerator), int(denominator))
        except (TypeError, ValueError, OverflowError):
            pass
    try:
        converted = float(value)
    except (TypeError, ValueError):
        raise ValueError("coordinates must be numbers, got {!r}".format(value))
    if not isfinite(converted):
        raise ValueError("coordinates must be finite numbers")
    return Fraction(converted)


def _scale_to_integers(points):
    """Clear denominators so that every coordinate is an exact integer."""
    denominator = 1
    for x, y in points:
        for d in (x.denominator, y.denominator):
            denominator = denominator // gcd(denominator, d) * d
    return [(int(x * denominator), int(y * denominator)) for x, y in points]


def voronoi_neighbors(points):
    """Return the sorted list of index pairs whose Voronoi cells share an edge.

    ``points`` is a sequence of ``[x, y]`` pairs in general position (no three
    points collinear, no four cocircular).  The result is a list of tuples
    ``(i, j)`` with ``i < j``.  Raises ``ValueError`` for fewer than three
    points.
    """
    coords = []
    for point in points:
        try:
            x, y = point
        except (TypeError, ValueError):
            raise ValueError("each point must be an [x, y] pair, got {!r}".format(point))
        coords.append((_as_fraction(x), _as_fraction(y)))

    n = len(coords)
    if n < 3:
        raise ValueError("at least three points are required, got {}".format(n))

    pts = _scale_to_integers(coords)

    neighbours = []
    for i in range(n):
        xi, yi = pts[i]
        ii = xi * xi + yi * yi
        for j in range(i + 1, n):
            xj, yj = pts[j]
            dx = xj - xi
            dy = yj - yi
            if dx == 0 and dy == 0:
                # Coincident points: no well defined shared cell edge.
                continue

            # Normal direction of the perpendicular bisector, and 2 * midpoint.
            nx, ny = -dy, dx
            sx, sy = xi + xj, yi + yj

            # Free interval is [upper_max, lower_min]; both are kept as
            # (numerator, positive denominator) pairs.  None means unbounded.
            lower_num = lower_den = None
            upper_num = upper_den = None
            possible = True

            for k in range(n):
