                xm, ym = pts[k]
                mx = xm - xi
                my = ym - yi
                a = nx * mx + ny * my
                # 2 * B, where B is the right hand side of the inequality.
                b = (xm * xm + ym * ym - ii) - (sx * mx + sy * my)

                if a == 0:
                    # 0 > b is either never or always true.
                    if b < 0:
                        possible = False
                        break
                    continue

                if a > 0:
                    # t > b / a : a lower bound, keep the smallest one.
                    if lower_num is None or b * lower_den < lower_num * a:
                        lower_num, lower_den = b, a
                else:
                    # t < b / a with a < 0 : an upper bound, keep the largest
                    # one.  b / a is rewritten with a positive denominator.
                    num, den = -b, -a
                    if upper_num is None or num * upper_den > upper_num * den:
                        upper_num, upper_den = num, den

                if lower_num is not None and upper_num is not None:
                    # Forbidden rays cover the line as soon as the largest upper
                    # bound reaches the smallest lower bound.
                    if upper_num * lower_den >= lower_num * upper_den:
                        possible = False
                        break

            if possible:
