import random


def _squared_distance(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


def _farthest_first_centers(points, k):
    first = min(range(len(points)), key=lambda i: (points[i][0], points[i][1], i))
    centers = [points[first]]

    while len(centers) < k:
        best_index = 0
        best_distance = -1.0
        for i, point in enumerate(points):
            distance = min(_squared_distance(point, center) for center in centers)
            if distance > best_distance:
                best_distance = distance
                best_index = i
        centers.append(points[best_index])

    return centers


def _kmeans_plus_plus_centers(points, k, seed):
    rng = random.Random(seed)
    centers = [points[rng.randrange(len(points))]]

    while len(centers) < k:
        distances = [
            min(_squared_distance(point, center) for center in centers)
            for point in points
        ]
        total = sum(distances)

        if total == 0.0:
            centers.append(points[rng.randrange(len(points))])
            continue

        target = rng.random() * total
        cumulative = 0.0
        chosen = len(points) - 1
        for i, distance in enumerate(distances):
            cumulative += distance
            if cumulative >= target:
                chosen = i
                break
        centers.append(points[chosen])

    return centers


