"""Utilities for extracting dictionary literals from HTML script elements."""

from __future__ import annotations

import ast
from html.parser import HTMLParser
from typing import Any


class _ScriptCollector(HTMLParser):
    """Collect the raw text content of every script element in a document."""

    def __init__(self) -> None:
        super().__init__(convert_charrefs=False)
        self._in_script = False
        self._parts: list[str] = []
        self.scripts: list[str] = []

    def handle_starttag(
        self, tag: str, attrs: list[tuple[str, str | None]]
    ) -> None:
        if tag == "script" and not self._in_script:
            self._in_script = True
            self._parts = []

    def handle_endtag(self, tag: str) -> None:
        if tag == "script" and self._in_script:
            self.scripts.append("".join(self._parts))
            self._in_script = False
            self._parts = []

    def handle_data(self, data: str) -> None:
        if self._in_script:
            self._parts.append(data)


def extract_script_dicts(html: str) -> list[dict[Any, Any]]:
    """Return dictionary literals found in script elements, in document order.

    A script body contributes only when its entire text is a valid Python
    dictionary literal. Invalid or non-dictionary bodies are skipped.
    """
    parser = _ScriptCollector()
    parser.feed(html)
    parser.close()

    dictionaries: list[dict[Any, Any]] = []
    for script in parser.scripts:
        try:
            value = ast.literal_eval(script.strip())
        except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
            continue
        if isinstance(value, dict):
            dictionaries.append(value)
    return dictionaries

