import calendar
import datetime
import re

_MONTH_END = "month-end"
_QUARTER_END = "quarter-end"

_QUARTER_END_MONTHS = (3, 6, 9, 12)

_WEEKDAYS = ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN")

_NTH_WEEKDAY_RE = re.compile(r"^([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)$")

_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _parse_start_date(start_date):
    """Return a datetime.date for a 'YYYY-MM-DD' string or date-like object."""
    if isinstance(start_date, datetime.datetime):
        return start_date.date()
    if isinstance(start_date, datetime.date):
        return start_date
    if not isinstance(start_date, str) or not _DATE_RE.match(start_date):
        raise ValueError("invalid start date: %r" % (start_date,))
    try:
        return datetime.datetime.strptime(start_date, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("invalid start date: %r" % (start_date,)) from None


def _month_end(year, month):
    return datetime.date(year, month, calendar.monthrange(year, month)[1])


def _nth_weekday(year, month, week, weekday):
    """Date of the `week`-th `weekday` (0=Monday) of the given month."""
    first = datetime.date(year, month, 1)
    offset = (weekday - first.weekday()) % 7
    return first + datetime.timedelta(days=offset + 7 * (week - 1))


def _parse_freq(freq):
    """Normalize `freq` into a scheduling spec tuple."""
    if not isinstance(freq, str):
        raise ValueError("invalid frequency: %r" % (freq,))
    code = freq.strip()
    if code.lower() in (_MONTH_END, _QUARTER_END):
        return (code.lower(),)
    match = _NTH_WEEKDAY_RE.match(code.upper())
    if match is not None:
        return ("nth-weekday", int(match.group(1)), _WEEKDAYS.index(match.group(2)))
    raise ValueError("invalid frequency: %r" % (freq,))


def _date_in_month(spec, year, month):
    """The single matching date of the given month, or None if it has none."""
    kind = spec[0]
    if kind == _MONTH_END:
        return _month_end(year, month)
    if kind == _QUARTER_END:
        return _month_end(year, month) if month in _QUARTER_END_MONTHS else None
    return _nth_weekday(year, month, spec[1], spec[2])


def forecast_schedule(start_date, freq, sales):
    """Pair each sales figure with a consecutive date matching `freq`.

    The first date is the earliest date on or after `start_date` that matches
    the frequency; subsequent dates follow the frequency in order.

    Returns a list of ('YYYY-MM-DD', sales) tuples.
    """
    start = _parse_start_date(start_date)
    spec = _parse_freq(freq)
    values = list(sales)

    dates = []
    year, month = start.year, start.month
    while len(dates) < len(values):
        candidate = _date_in_month(spec, year, month)
        if candidate is not None and candidate >= start:
            dates.append(candidate)
        month += 1
        if month > 12:
            month = 1
            year += 1

    return [(date.isoformat(), value) for date, value in zip(dates, values)]

