    text = (value or "").strip()
    if not text:
        return 0
    if _THOUSANDS.match(text):
        text = text.replace(",", "")
    number = float(text)
    if number.is_integer() and "." not in text and "e" not in text.lower():
        return int(number)
    return number


def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.DictReader(io.StringIO(csv_text.lstrip("\ufeff")))
    fields = [field.strip() for field in (reader.fieldnames or [])]
    reader.fieldnames = fields

    for required in ("Customer", "Category", "Sales"):
        if required not in fields:
            raise ValueError("missing required column: %s" % required)

    seen = set()
    total = 0
    categories = Counter()

    for row in reader:
        customer = (row.get("Customer") or "").strip()
        if customer in seen:
            continue
        seen.add(customer)

        category = (row.get("Category") or "").strip()
        categories[category] += 1
        total += _to_number(row.get("Sales"))

    if isinstance(total, float) and total.is_integer():
        total = int(total)

    if categories:
        top = min(categories.items(), key=lambda item: (-item[1], item[0]))[0]
    else:
        top = None

    return {"Total Sales": total, "Most Popular Category": top}

