REQUIRED_KEYS = ("Name", "Country", "Score")


def _quantile(sorted_values, probability):
    """Return a quantile using linear interpolation between sorted values."""
    position = (len(sorted_values) - 1) * probability
    lower_index = int(position)
    upper_index = min(lower_index + 1, len(sorted_values) - 1)

    if lower_index == upper_index:
        return float(sorted_values[lower_index])

    fraction = position - lower_index
    lower_value = sorted_values[lower_index]
    upper_value = sorted_values[upper_index]
    return float(lower_value + (upper_value - lower_value) * fraction)


def country_score_summary(records):
    if not records:
        raise ValueError("records must not be empty")

    first_by_name = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("each record must be a dict")

        missing = [key for key in REQUIRED_KEYS if key not in record]
        if missing:
            raise ValueError(
                "record is missing required key(s): " + ", ".join(missing)
            )

        name = record["Name"]
        if name not in first_by_name:
            first_by_name[name] = record

    scores_by_country = {}
    for record in first_by_name.values():
        country = record["Country"]
        scores_by_country.setdefault(country, []).append(record["Score"])

    summary = {}
    for country, scores in scores_by_country.items():
        ordered_scores = sorted(scores)
        summary[country] = [
            float(ordered_scores[0]),
            _quantile(ordered_scores, 0.25),
            _quantile(ordered_scores, 0.50),
            _quantile(ordered_scores, 0.75),
            float(ordered_scores[-1]),
        ]

    return summary

