"""Sample covariance matrix for a dict-of-columns table."""

import numbers


def column_covariance(columns):
    """Return the sample (n - 1 normalised) covariance matrix of ``columns``.

    ``columns`` maps column names to equal-length sequences of numbers with at
    least two rows.  The result is a nested dict where ``result[a][b]`` is the
    covariance of columns ``a`` and ``b``.
    """
    if not columns:
        raise ValueError("table has no columns")

    names = list(columns.keys())
    data = [list(columns[name]) for name in names]

    if not data[0]:
        raise ValueError("table has no rows")

    n_rows = len(data[0])
    if n_rows < 2:
        raise ValueError("at least two rows are required")

    for name, values in zip(names, data):
        if len(values) != n_rows:
            raise ValueError(
                "column %r has %d rows, expected %d" % (name, len(values), n_rows)
            )
        for value in values:
            if not isinstance(value, numbers.Real):
                raise TypeError(
                    "column %r contains a non-numeric value: %r" % (name, value)
                )

    means = [sum(values) / n_rows for values in data]
    deviations = [
        [value - mean for value in values] for values, mean in zip(data, means)
    ]

    result = {}
    for a, dev_a in zip(names, deviations):
        row = {}
        for b, dev_b in zip(names, deviations):
            row[b] = sum(da * db for da, db in zip(dev_a, dev_b)) / (n_rows - 1)
        result[a] = row
    return result

