import math


def summarize_from_user(records):
    values = []
    for record in records:
        if "from_user" not in record:
            continue
        value = record["from_user"]
        if not isinstance(value, (int, float)):
            raise ValueError(
                "from_user value must be numeric, got %r" % (value,)
            )
        values.append(float(value))

    if not values:
        return {
            "mean": None,
            "median": None,
            "min": None,
            "max": None,
            "std": None,
        }

    n = len(values)
    ordered = sorted(values)
    mean = math.fsum(values) / n

    middle = n // 2
    if n % 2:
        median = ordered[middle]
    else:
        median = (ordered[middle - 1] + ordered[middle]) / 2.0

    variance = math.fsum((v - mean) ** 2 for v in values) / n

    return {
        "mean": mean,
        "median": median,
        "min": ordered[0],
        "max": ordered[-1],
        "std": math.sqrt(variance),
    }

