"""K-means clustering that reports which point indices landed together."""

import random

_MAX_ITER = 300
_N_INIT = 10


def _sq_dist(a, b):
    total = 0.0
    for x, y in zip(a, b):
        d = x - y
        total += d * d
    return total


def _assign(points, centers):
    """Index of the nearest center for each point (ties go to the lowest index)."""
    labels = []
    for p in points:
        best = 0
        best_d = _sq_dist(p, centers[0])
        for j in range(1, len(centers)):
            d = _sq_dist(p, centers[j])
            if d < best_d:
                best_d = d
                best = j
        labels.append(best)
    return labels


def _init_centers(points, k, rng):
    """k-means++ seeding with deterministic randomness."""
    n = len(points)
    centers = [list(points[rng.randrange(n)])]
    d2 = [_sq_dist(p, centers[0]) for p in points]
    for _ in range(1, k):
        total = sum(d2)
        if total <= 0.0:
            # Every point already coincides with a center; any point works.
            centers.append(list(points[rng.randrange(n)]))
            continue
        target = rng.random() * total
        acc = 0.0
        chosen = n - 1
        for i in range(n):
            acc += d2[i]
            if acc >= target:
                chosen = i
                break
        centers.append(list(points[chosen]))
        new_c = centers[-1]
        d2 = [min(d2[i], _sq_dist(points[i], new_c)) for i in range(n)]
    return centers


def _recompute_centers(points, labels, centers, k, dim):
    """Means of the assigned points; empty clusters are re-seeded."""
    n = len(points)
    counts = [0] * k
    for l in labels:
        counts[l] += 1

    # Re-seed empty clusters from points that are furthest from their own mean,
    # without emptying a cluster that currently holds a single point.
    for j in range(k):
        if counts[j]:
            continue
        far_i, far_d = -1, -1.0
        for i in range(n):
            l = labels[i]
            if counts[l] <= 1:
                continue
            d = _sq_dist(points[i], centers[l])
            if d > far_d:
                far_d, far_i = d, i
        if far_i < 0:
            continue
        counts[labels[far_i]] -= 1
        labels[far_i] = j
        counts[j] = 1

    sums = [[0.0] * dim for _ in range(k)]
    counts = [0] * k
    for p, l in zip(points, labels):
        s = sums[l]
        for t in range(dim):
            s[t] += p[t]
        counts[l] += 1

    new_centers = []
    for j in range(k):
        if counts[j]:
            c = counts[j]
            new_centers.append([v / c for v in sums[j]])
        else:
            new_centers.append(list(centers[j]))
    return new_centers


def _lloyd(points, centers, dim):
    labels = _assign(points, centers)
    for _ in range(_MAX_ITER):
        new_centers = _recompute_centers(points, labels, centers, len(centers), dim)
        new_labels = _assign(points, new_centers)
        centers = new_centers
        if new_labels == labels:
            break
        labels = new_labels
    inertia = 0.0
    for p, l in zip(points, labels):
        inertia += _sq_dist(p, centers[l])
    return labels, inertia


def _split_to_k(points, labels, k, dim):
    """Split clusters until exactly ``k`` non-empty groups exist.

    Needed only when several points coincide, which leaves Lloyd's iteration
    unable to fill every cluster on its own.
    """
    labels = list(labels)
    next_label = max(labels) + 1
    while len(set(labels)) < k:
        counts = {}
        for l in labels:
            counts[l] = counts.get(l, 0) + 1
        best = None
        for l, c in counts.items():
            if c < 2:
                continue
            mean = [0.0] * dim
            for i, p in enumerate(points):
                if labels[i] == l:
                    for t in range(dim):
                        mean[t] += p[t]
            for t in range(dim):
                mean[t] /= c
            for i, p in enumerate(points):
                if labels[i] != l:
                    continue
                d = _sq_dist(p, mean)
                if best is None or d > best[0]:
                    best = (d, i)
        if best is None:
            break
        labels[best[1]] = next_label
        next_label += 1
    return labels


def cluster_point_indices(points, n_clusters):
    """Group ``points`` into ``n_clusters`` k-means clusters.

    Returns a list of clusters, each a list of point indices in ascending order,
    with the clusters ordered by their smallest index. When there are at least
    ``n_clusters`` points the result holds exactly that many groups; otherwise
    every point gets its own group. An empty input (or a non-positive cluster
    count) yields an empty list.
    """
    pts = [[float(v) for v in p] for p in points]
    n = len(pts)
    if n == 0 or n_clusters is None or n_clusters <= 0:
        return []
    dim = len(pts[0])
    k = min(int(n_clusters), n)

    if k == 1:
        return [list(range(n))]

    rng = random.Random(0)
    best_labels = None
    best_inertia = None
    for _ in range(_N_INIT):
        centers = _init_centers(pts, k, rng)
        labels, inertia = _lloyd(pts, centers, dim)
        if best_inertia is None or inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels
            if inertia == 0.0:
                break

    groups = {}
    for i, l in enumerate(best_labels):
        groups.setdefault(l, []).append(i)

    if len(groups) < k:
        best_labels = _split_to_k(pts, best_labels, k, dim)
        groups = {}
        for i, l in enumerate(best_labels):
            groups.setdefault(l, []).append(i)

    clusters = [sorted(g) for g in groups.values() if g]
    clusters.sort(key=lambda g: g[0])
    return clusters

