"""Extract and absolutize hyperlinks from HTML markup."""

from html.parser import HTMLParser
from urllib.parse import urljoin


class _AnchorParser(HTMLParser):
    """Collects the href attribute of every <a> element."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hrefs = []

    def handle_starttag(self, tag, attrs):
        if tag != "a":
            return
        for name, value in attrs:
            if name == "href":
                self.hrefs.append("" if value is None else value)
                break

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def extract_absolute_links(html, base_url):
    """Return the sorted, de-duplicated absolute URLs of all <a href> links.

    Relative references are resolved against ``base_url`` following the same
    rules a browser uses for the ``href`` attribute (RFC 3986 resolution).
    """
    if html is None:
        return []

    parser = _AnchorParser()
    parser.feed(html)
    parser.close()

    links = set()
    for href in parser.hrefs:
        href = href.strip()
        links.add(urljoin(base_url, href))

    return sorted(links)

