"""Sort the data rows of a CSV document by one of its columns."""

import csv
import io
import re

_INT_RE = re.compile(r"[+-]?[0-9]+\Z")
_FLOAT_RE = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?\Z")


def _as_number(text):
    """Return ``text`` as an int or float, or None when it is not numeric."""
    if not isinstance(text, str):
        return None
    value = text.strip()
    if not value:
        return None
    if _INT_RE.match(value):
        return int(value)
    if _FLOAT_RE.match(value):
        return float(value)
    return None


def sort_csv_rows(csv_text, sort_key):
    """Return the CSV data rows sorted ascending by the column ``sort_key``.

    Every row becomes a dict keyed by the header names.  A column whose values
    are all numeric is converted to int/float so that it sorts numerically;
    any other column keeps its string values.  The sort is stable, so rows with
    equal keys stay in their original order.
    """
    reader = csv.DictReader(io.StringIO(csv_text, newline=""), restval="")
    fieldnames = reader.fieldnames
    if not fieldnames:
        raise ValueError("CSV text has no header row")
    if sort_key not in fieldnames:
        raise ValueError(f"sort key {sort_key!r} is not one of the columns {fieldnames!r}")

    rows = []
    for raw in reader:
        raw.pop(None, None)  # ignore fields beyond the header width
        rows.append({name: raw.get(name, "") for name in fieldnames})

    for name in fieldnames:
        if rows and all(_as_number(row[name]) is not None for row in rows):
            for row in rows:
                row[name] = _as_number(row[name])

    return sorted(rows, key=lambda row: row[sort_key])

