    if csv_text is None:
        return []

    reader = csv.DictReader(io.StringIO(csv_text))
    results = []
    for row in reader:
        email = row.get('email')
        cell = row.get('list')
        if email is None and cell is None:
            continue
        email = (email or '').strip()
        numbers = _parse_numbers(cell or '[]')
        total = sum(numbers)
        count = len(numbers)
        results.append({
            'email': email,
            'list': numbers,
            'sum': total,
            'mean': total / count if count else None,
            'median': _median(numbers) if count else None,
        })
    return results

