"""K-means clustering for two-dimensional points."""

import math
import operator


def _dist2(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


class _LCG:
    """Small deterministic pseudo-random generator."""

    def __init__(self, seed):
        self.state = seed & 0xFFFFFFFF

    def random(self):
        self.state = (1664525 * self.state + 1013904223) & 0xFFFFFFFF
        return self.state / 4294967296.0

    def randrange(self, stop):
        return int(self.random() * stop)


def _assign(points, centroids):
    """Assign each point to its nearest centroid (lowest index on ties)."""
    labels = []
    k = len(centroids)
    for point in points:
        best = 0
        best_distance = _dist2(point, centroids[0])
        for j in range(1, k):
            distance = _dist2(point, centroids[j])
            if distance < best_distance:
                best = j
                best_distance = distance
        labels.append(best)
    return labels


def _fill_empty_clusters(points, labels, centroids):
    """Move points from large clusters into any empty clusters."""
    k = len(centroids)
    n = len(points)
    counts = [0] * k
    sum_x = [0.0] * k
    sum_y = [0.0] * k

    for i, label in enumerate(labels):
        counts[label] += 1
        sum_x[label] += points[i][0]
        sum_y[label] += points[i][1]

    for empty in range(k):
        if counts[empty] != 0:
            continue

        donors = [j for j in range(k) if counts[j] > 1]
        if not donors:
            break

        # Split the cluster with the largest squared error.
        donor = donors[0]
        largest_error = -1.0
        for j in donors:
            cx = sum_x[j] / counts[j]
            cy = sum_y[j] / counts[j]
            error = 0.0
            for i in range(n):
                if labels[i] == j:
                    error += _dist2(points[i], (cx, cy))
            if error > largest_error:
                largest_error = error
                donor = j

        cx = sum_x[donor] / counts[donor]
        cy = sum_y[donor] / counts[donor]

        # Move the point farthest from the donor's centroid.
        moved = -1
        farthest = -1.0
        for i in range(n):
            if labels[i] == donor:
                distance = _dist2(points[i], (cx, cy))
                if distance > farthest:
                    farthest = distance
                    moved = i

        labels[moved] = empty
        counts[donor] -= 1
        counts[empty] += 1
        sum_x[donor] -= points[moved][0]
        sum_y[donor] -= points[moved][1]
        sum_x[empty] += points[moved][0]
        sum_y[empty] += points[moved][1]

    return labels


def _run_kmeans(points, initial_centroids):
    """Run Lloyd's algorithm from one set of initial centroids."""
    k = len(initial_centroids)
    centroids = [(float(c[0]), float(c[1])) for c in initial_centroids]
    previous_labels = None

    for _ in range(300):
        labels = _assign(points, centroids)
        labels = _fill_empty_clusters(points, labels, centroids)

        if labels == previous_labels:
            break
        previous_labels = labels

        counts = [0] * k
        sum_x = [0.0] * k
        sum_y = [0.0] * k
        for i, label in enumerate(labels):
            counts[label] += 1
            sum_x[label] += points[i][0]
            sum_y[label] += points[i][1]

        for j in range(k):
            if counts[j]:
                centroids[j] = (sum_x[j] / counts[j], sum_y[j] / counts[j])

    return labels


def _farthest_first(points, k, start):
    """Choose centroids by repeatedly taking the point farthest from those chosen."""
    n = len(points)
    chosen = [start]
    chosen_set = {start}
    min_distance = [_dist2(point, points[start]) for point in points]

    while len(chosen) < k:
        best = -1
        best_distance = -1.0
        for i in range(n):
            if i in chosen_set:
                continue
            if min_distance[i] > best_distance:
                best_distance = min_distance[i]
                best = i

        if best == -1:
            break

        chosen.append(best)
        chosen_set.add(best)
        chosen_point = points[best]
        for i in range(n):
            distance = _dist2(points[i], chosen_point)
            if distance < min_distance[i]:
                min_distance[i] = distance

    return [points[i] for i in chosen]


def _kmeans_plus_plus(points, k, rng):
    """Deterministic k-means++ initialization."""
    n = len(points)
    first = rng.randrange(n)
    chosen = [first]
    chosen_set = {first}
    min_distance = [_dist2(point, points[first]) for point in points]

    while len(chosen) < k:
        total = 0.0
        for i in range(n):
            if i not in chosen_set:
                total += min_distance[i]

        if total <= 0.0:
            # All remaining points coincide with chosen centroids.
            next_index = -1
            for i in range(n):
                if i not in chosen_set:
                    next_index = i
                    break
        else:
            target = rng.random() * total
            cumulative = 0.0
            next_index = -1
            for i in range(n):
                if i in chosen_set:
                    continue
                cumulative += min_distance[i]
                if cumulative > target:
                    next_index = i
                    break
            if next_index == -1:
                for i in range(n - 1, -1, -1):
                    if i not in chosen_set:
                        next_index = i
                        break

        if next_index == -1:
            break

        chosen.append(next_index)
        chosen_set.add(next_index)
        chosen_point = points[next_index]
        for i in range(n):
            distance = _dist2(points[i], chosen_point)
            if distance < min_distance[i]:
                min_distance[i] = distance

    return [points[i] for i in chosen]


def _evenly_spaced(points, k):
    n = len(points)
    if k == 1:
        return [points[0]]
    return [points[(i * (n - 1)) // (k - 1)] for i in range(k)]


def _initializations(points, k):
    """Yield a deterministic collection of initial centroid sets."""
    n = len(points)
    seen = set()

    def add(centroids):
        key = tuple(centroids)
        if key not in seen:
            seen.add(key)
            return centroids
        return None

    # Adapt the number of starts to the problem size.
    if n * k <= 100000:
        starts = sorted({0, n // 4, n // 2, (3 * n) // 4, n - 1})
        seeds = [0, 1, 2, 42, 12345]
    elif n * k <= 1000000:
        starts = sorted({0, n // 2, n - 1})
        seeds = [0, 1]
    else:
        starts = sorted({0, n // 2})
        seeds = [0]

    for start in starts:
        candidate = add(_farthest_first(points, k, start))
        if candidate is not None:
            yield candidate

    candidate = add(points[:k])
    if candidate is not None:
        yield candidate

    candidate = add(_evenly_spaced(points, k))
    if candidate is not None:
        yield candidate

    for seed in seeds:
        candidate = add(_kmeans_plus_plus(points, k, _LCG(seed)))
        if candidate is not None:
            yield candidate


def _labels_to_clusters(labels, k):
    clusters = [[] for _ in range(k)]
    for i, label in enumerate(labels):
        clusters[label].append(i)
    clusters = [cluster for cluster in clusters if cluster]
    clusters.sort(key=lambda cluster: cluster[0])
    return clusters


def _inertia(points, labels, k):
    counts = [0] * k
    sum_x = [0.0] * k
    sum_y = [0.0] * k
    for i, label in enumerate(labels):
        counts[label] += 1
        sum_x[label] += points[i][0]
        sum_y[label] += points[i][1]

    total = 0.0
    for j in range(k):
        if not counts[j]:
            continue
        cx = sum_x[j] / counts[j]
        cy = sum_y[j] / counts[j]
        for i, label in enumerate(labels):
            if label == j:
                total += _dist2(points[i], (cx, cy))
    return total


def kmeans_clusters(xs, ys, n_clusters):
    """Group 2D points into ``n_clusters`` clusters using k-means.

    Point ``i`` is ``(xs[i], ys[i])``.  The result is a list of clusters,
    where each cluster is a sorted list of point indices and clusters are
    ordered by their smallest index.
    """
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    try:
        k = operator.index(n_clusters)
    except TypeError:
        raise ValueError("n_clusters must be an integer") from None

    n = len(xs)
    if k < 0 or k > n:
        raise ValueError("n_clusters must be between 0 and the number of points")

    if n == 0:
        return []

    if k == 0:
        raise ValueError("n_clusters must be positive when points are provided")

    points = [(float(xs[i]), float(ys[i])) for i in range(n)]

    if k == 1:
        return [list(range(n))]
    if k == n:
        return [[i] for i in range(n)]

    best_labels = None
    best_inertia = math.inf
    best_key = None

    for initial_centroids in _initializations(points, k):
        labels = _run_kmeans(points, initial_centroids)
        clusters = _labels_to_clusters(labels, k)
        inertia = _inertia(points, labels, k)
        key = tuple(tuple(cluster) for cluster in clusters)

        if inertia < best_inertia or (inertia == best_inertia and key < best_key):
            best_labels = labels
            best_inertia = inertia
            best_key = key

    return _labels_to_clusters(best_labels, k)

