import csv
import io
import math


def _cbrt(x):
    """Return the real cube root of x, accurate to the nearest float."""
    if x == 0.0 or x != x or math.isinf(x):
        return x
    negative = x < 0.0
    a = -x if negative else x
    cbrt = getattr(math, "cbrt", None)
    y = cbrt(a) if cbrt is not None else a ** (1.0 / 3.0)
    # One Newton step, then keep whichever of the neighbouring floats cubes
    # closest to a; this makes perfect cubes come out exact (27.0 -> 3.0).
    try:
        y = y - (y * y * y - a) / (3.0 * y * y)
    except (OverflowError, ZeroDivisionError):
        pass
    best = y
    best_err = abs(y * y * y - a)
    for candidate in (math.nextafter(y, 0.0), math.nextafter(y, math.inf)):
        try:
            err = abs(candidate * candidate * candidate - a)
        except OverflowError:
            continue
        if err < best_err:
            best, best_err = candidate, err
    return -best if negative else best


def csv_cube_roots(csv_text, columns):
    """Parse a header-row CSV and compute cube roots for selected columns.

    Returns ``(all_columns, cube_roots)`` where ``all_columns`` maps every
    header name to its list of floats and ``cube_roots`` maps each requested
    column to the cube roots of its values.

    Raises KeyError if a requested column is absent, and ValueError if any
    value in the file is not numeric.
    """
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        missing = list(columns)
        if missing:
            raise KeyError(missing[0])
        return {}, {}

    header = [name.strip() for name in rows[0]]
    for name in columns:
        if name not in header:
            raise KeyError(name)

    values = {name: [] for name in header}
    for line_no, row in enumerate(rows[1:], start=2):
        if not row:
            continue
        for index, name in enumerate(header):
            raw = row[index] if index < len(row) else ""
            try:
                value = float(raw)
            except (TypeError, ValueError):
                raise ValueError(
                    "row {} column {!r}: {!r} is not numeric".format(
                        line_no, name, raw
                    )
                ) from None
            values[name].append(value)

    roots = {name: [_cbrt(v) for v in values[name]] for name in columns}
    return values, roots

