def standardize_with_row_means(data):
    if not data:
        return []

    num_rows = len(data)
    num_cols = len(data[0])

    column_means = [
        math.fsum(row[col] for row in data) / num_rows
        for col in range(num_cols)
    ]
    column_stds = [
        math.sqrt(
            math.fsum((row[col] - column_means[col]) ** 2 for row in data)
            / num_rows
        )
        for col in range(num_cols)
    ]

    result = []
    for row in data:
        standardized = [
            (row[col] - column_means[col]) / column_stds[col]
            if column_stds[col] != 0.0
            else 0.0
            for col in range(num_cols)
        ]
        row_mean = math.fsum(standardized) / num_cols if num_cols else 0.0
        result.append(standardized + [row_mean])

    return result

