"""Complete-row filtering plus a pooled histogram."""


def complete_row_histogram(data, bins):
    """Drop rows containing a None and histogram the remaining values.

    ``data`` maps column names to equal-length sequences of numbers (or None).
    Rows with a None in any column are dropped.  The remaining values, pooled
    across all columns, are counted into ``bins`` equal-width bins spanning
    their minimum to their maximum.

    Returns ``(cleaned, counts)`` where ``cleaned`` maps every column name to
    the surviving values, in order, as floats, and ``counts`` is the list of
    bin counts -- or None when no rows survive, when all surviving values are
    equal, or when ``bins`` is not positive.
    """
    columns = list(data)
    if not columns:
        return {}, None

    length = len(data[columns[0]])
    keep = [
        i
        for i in range(length)
        if all(data[col][i] is not None for col in columns)
    ]

    cleaned = {
        col: [float(data[col][i]) for i in keep] for col in columns
    }

    values = [
        float(data[col][i]) for i in keep for col in columns
    ]

    if not values or bins is None or bins < 1:
        return cleaned, None

    low = min(values)
    high = max(values)
    if low == high:
        return cleaned, None

    width = (high - low) / bins
    counts = [0] * bins
    for value in values:
        index = int((value - low) / width)
        if index >= bins:
            index = bins - 1
        elif index < 0:
            index = 0
        counts[index] += 1

    return cleaned, counts

