"""Filtered ordinary least squares regression."""

try:  # numpy is optional; a pure-Python solver is used when it is unavailable
    import numpy as _np
except Exception:  # pragma: no cover - depends on the environment
    _np = None


def _solve_normal_equations(a, b):
    """Solve ``a @ x = b`` by Gaussian elimination with partial pivoting."""
    n = len(b)
    m = [list(map(float, row)) + [float(rhs)] for row, rhs in zip(a, b)]
    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(m[r][col]))
        if abs(m[pivot][col]) < 1e-12:
            continue
        m[col], m[pivot] = m[pivot], m[col]
        inv = 1.0 / m[col][col]
        for r in range(n):
            if r != col and m[r][col] != 0.0:
                factor = m[r][col] * inv
                for c in range(col, n + 1):
                    m[r][c] -= factor * m[col][c]
    x = [0.0] * n
    for i in range(n):
        if abs(m[i][i]) >= 1e-12:
            x[i] = m[i][n] / m[i][i]
    return x


def _least_squares(design, response):
    """Return the minimum-norm OLS solution for ``design @ beta ~= response``."""
    if _np is not None:
