    vars_ = [0.0] * d
    for row in rows:
        for j in range(d):
            diff = row[j] - means[j]
            vars_[j] += diff * diff
    stds = [(v / n) ** 0.5 for v in vars_]

    data = []
    for row in rows:
        data.append([(row[j] - means[j]) / (stds[j] if stds[j] > 0.0 else 1.0)
                     for j in range(d)])
    return data


