    n = len(data)
    centroids = [list(data[rng.randrange(n)])]
    closest = [_dist2(x, centroids[0]) for x in data]
    for _ in range(1, k):
        total = sum(closest)
        if total <= 0.0:
            idx = rng.randrange(n)
        else:
            target = rng.random() * total
            idx = n - 1
            acc = 0.0
            for i, w in enumerate(closest):
                acc += w
                if acc >= target:
                    idx = i
                    break
