"""Column-wise min-max normalization."""

from numbers import Real


def _is_number(value):
    return isinstance(value, Real)


def normalize_columns(data):
    """Rescale each column of ``data`` independently to the range [0, 1].

    A column's minimum maps to 0.0 and its maximum to 1.0. Columns whose
    values are all equal are mapped to all zeros.

    Args:
        data: dict mapping column names to equal-length lists of numbers.

    Returns:
        A new dict with the same keys, each holding a list of rescaled floats
        in the original order.

    Raises:
        ValueError: if ``data`` is empty or any column holds non-numeric
            values.
    """
    if not data:
        raise ValueError("data must contain at least one column")

    result = {}
    for key, values in data.items():
        values = list(values)
        for value in values:
            if not _is_number(value):
                raise ValueError(
                    "column {!r} contains a non-numeric value: {!r}".format(key, value)
                )

        if not values:
            result[key] = []
            continue

        low = min(values)
        high = max(values)
        if low == high:
            result[key] = [0.0 for _ in values]
        else:
            span = high - low
            result[key] = [float((value - low) / span) for value in values]

    return result

