def fruit_sales_box_stats(records):
    """Return (min, Q1, median, Q3, max) sales statistics per fruit."""
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = {}
    for fruit, _day, sales in records:
        sales_by_fruit.setdefault(fruit, []).append(sales)

    def percentile(sorted_values, fraction):
        position = (len(sorted_values) - 1) * fraction
        lower = int(position)
        upper = min(lower + 1, len(sorted_values) - 1)
        weight = position - lower
        return float(
            sorted_values[lower]
            + (sorted_values[upper] - sorted_values[lower]) * weight
        )

    stats = {}
    for fruit, values in sales_by_fruit.items():
        values.sort()
        stats[fruit] = (
            percentile(values, 0.0),
            percentile(values, 0.25),
            percentile(values, 0.5),
            percentile(values, 0.75),
            percentile(values, 1.0),
        )
    return stats

