"""Column summary statistics with value replacement."""

from collections import Counter


def _replace(value, mapping):
    """Return the mapped value for ``value`` when it is a key of ``mapping``."""
    try:
        return mapping[value]
    except (KeyError, TypeError):
        return value


def _as_number(value):
    """Return ``value`` as a float, or None when it is not numeric."""
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _mode(values):
    """Most common value; ties are broken by choosing the smallest value."""
    try:
        counts = Counter(values)
        best = max(counts.values())
        candidates = [value for value, count in counts.items() if count == best]
    except TypeError:
        unique = []
        for value in values:
            for entry in unique:
                if entry[0] is value or entry[0] == value:
                    entry[1] += 1
                    break
            else:
                unique.append([value, 1])
        best = max(count for _, count in unique)
        candidates = [value for value, count in unique if count == best]
    try:
        return min(candidates)
    except TypeError:
        return candidates[0]


def _median(ordered):
    """Median of an already sorted sequence, as a float when numeric."""
    n = len(ordered)
    middle = n // 2
    if n % 2:
        value = ordered[middle]
        number = _as_number(value)
        return number if number is not None else value
    low, high = ordered[middle - 1], ordered[middle]
    low_num, high_num = _as_number(low), _as_number(high)
    if low_num is not None and high_num is not None:
        return (low_num + high_num) / 2.0
    return low


def column_summary_stats(table, mapping, features):
    """Summarize the requested columns of ``table`` after applying ``mapping``."""
    stats = {}
    for feature in features:
        if feature not in table:
            raise ValueError("feature %r is not present in the table" % (feature,))
        column = [_replace(value, mapping) for value in table[feature]]
        if not column:
