def integer_histogram_counts(data_str, separator=',', bins=20):
    """Count integers from a separated string into equal-width histogram bins.

    Returns ``(values, counts)`` where ``values`` holds the integers in their
    original order and ``counts`` holds the per-bin tallies over ``bins``
    equal-width bins spanning ``min(values)`` to ``max(values)``.  Each bin
    includes its left edge; the last bin also includes the maximum.
    """
    if not isinstance(data_str, str):
        raise ValueError('data_str must be a string')

    text = data_str.strip()
    if not text:
        raise ValueError('data_str is empty')

    if not isinstance(bins, int) or isinstance(bins, bool):
        raise ValueError('bins must be an integer')
    if bins < 1:
        raise ValueError('bins must be at least 1')

    if separator is None or separator == '':
        parts = [text]
    else:
        parts = text.split(separator)

    values = []
    for part in parts:
        token = part.strip()
        if not token:
            raise ValueError('empty value in data_str: %r' % (part,))
        try:
            number = float(token)
        except (TypeError, ValueError):
            raise ValueError('value is not numeric: %r' % (part,))
        try:
            values.append(int(number))
        except (ValueError, OverflowError):
            raise ValueError('value is not numeric: %r' % (part,))

    low = min(values)
    high = max(values)

    counts = [0] * bins
    if high == low:
        # Zero-width span: every value lands in the final bin, which owns the
        # maximum and therefore the whole (degenerate) range.
        counts[-1] = len(values)
        return values, counts

    span = high - low
    for value in values:
        index = (value - low) * bins // span
        if index >= bins:
            index = bins - 1
        elif index < 0:
            index = 0
        counts[index] += 1

    return values, counts

