def min_max_scale_columns(rows):
    """Min-max scale each column of a table to the range [0.0, 1.0].

    A column whose values are all equal has no non-zero range, so all of its
    scaled values are 0.0.
    """
    if not rows:
        return []

    column_count = len(rows[0])
    if column_count == 0:
        return [[] for _ in rows]

    minimums = list(rows[0])
    maximums = list(rows[0])

    for row in rows[1:]:
        for column, value in enumerate(row):
            if value < minimums[column]:
                minimums[column] = value
            if value > maximums[column]:
                maximums[column] = value

    ranges = [
        maximums[column] - minimums[column]
        for column in range(column_count)
    ]

    return [
        [
            0.0
            if ranges[column] == 0
            else (value - minimums[column]) / ranges[column]
            for column, value in enumerate(row)
        ]
        for row in rows
    ]

