"""Group rows by their leading values and count distinct trailing values."""


def _make_hashable(value):
    """Return a hashable stand-in that preserves equality for nested values."""
    try:
        hash(value)
    except TypeError:
        pass
    else:
        return ("value", value)

    if isinstance(value, (list, tuple)):
        return ("sequence", tuple(_make_hashable(item) for item in value))
    if isinstance(value, dict):
        return ("mapping", frozenset(
            (_make_hashable(k), _make_hashable(v)) for k, v in value.items()
        ))
    if isinstance(value, (set, frozenset)):
        return ("set", frozenset(_make_hashable(item) for item in value))
    return ("repr", repr(value))


def _sorted_keys(keys):
    """Sort group keys ascending, with a total order fallback for mixed types."""
    try:
        return sorted(keys)
    except TypeError:
        return sorted(keys, key=lambda key: [(type(v).__name__, repr(v)) for v in key])


def count_distinct_by_group(data):
    """Count distinct values per group.

    The last value of each row is the value; the remaining values form the
    group key. Returns one row per distinct key, sorted ascending by key,
    holding the key values followed by the number of distinct values.
    """
    original = {}
    seen = {}

    for row in data:
        values = list(row)
        key = tuple(values[:-1])
        group = _make_hashable(key)

        if group not in original:
            original[group] = key
            seen[group] = set()
        seen[group].add(_make_hashable(values[-1]))

    return [
        list(key) + [len(seen[_make_hashable(key)])]
        for key in _sorted_keys(list(original.values()))
    ]

