import csv
import io
import re

# A value counts as a number only if it is a plain decimal literal, optionally
# signed, with an optional fractional part and/or exponent.
_NUMBER_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")


def _to_number(value):
    """Return ``value`` as an int or float, or None if it is not a number."""
    text = value.strip()
    if not _NUMBER_RE.match(text):
        return None
    if "." in text or "e" in text or "E" in text:
        return float(text)
    return int(text)


def sort_csv_rows(csv_text, sort_by_column):
    """Return the data rows of ``csv_text`` sorted ascending by a column.

    Each row is a dict mapping column names to values.  A column holds numbers
    (ints or floats) when every one of its values parses as a number, otherwise
    it holds the raw strings.  Raises ValueError when ``sort_by_column`` is not
    one of the header names.
    """
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")

    text = csv_text.replace("\r\n", "\n").replace("\r", "\n")
    if text.startswith("\ufeff"):
        text = text[1:]

    reader = csv.reader(io.StringIO(text))
    header = None
    raw_rows = []
    for row in reader:
        if not row:
            continue
        if header is None:
            header = row
            continue
        raw_rows.append(row)

    if header is None:
        raise ValueError("CSV text has no header row")

    if sort_by_column not in header:
        raise ValueError(f"column not found in header: {sort_by_column!r}")

    width = len(header)

    # Pad short rows so every record has a value for every header column.
    for row in raw_rows:
        if len(row) < width:
            row.extend([""] * (width - len(row)))

    # Decide, per column, whether every value is numeric.
    numeric_columns = [
        bool(raw_rows)
        and all(_to_number(row[index]) is not None for row in raw_rows)
        for index in range(width)
    ]

    records = []
    for row in raw_rows:
        record = {}
        for index, name in enumerate(header):
            value = row[index]
            record[name] = _to_number(value) if numeric_columns[index] else value
        records.append(record)

    records.sort(key=lambda record: record[sort_by_column])
    return records

