from bisect import bisect_right


def histogram_bins(values, bins):
    """Compute a histogram over equal-width or explicitly supplied bins."""
    if isinstance(bins, int):
        if bins < 1:
            raise ValueError("bins must be a positive integer")
        values = list(values)
        if values:
            lo = min(values)
            hi = max(values)
        else:
            lo = hi = 0

        if lo == hi:
            edges = [float(lo)] * (bins + 1)
        else:
            edges = [
                float(lo + (hi - lo) * i / bins)
                for i in range(bins + 1)
            ]
            edges[0] = float(lo)
            edges[-1] = float(hi)
    else:
        edges = [float(edge) for edge in bins]
        values = list(values)

    counts = [0] * max(0, len(edges) - 1)
    if not counts:
        return counts, edges

    first = edges[0]
    last = edges[-1]
    last_bin = len(counts) - 1

    for value in values:
        if value != value or value < first or value > last:
            continue
        index = bisect_right(edges, value) - 1
        if index >= last_bin:
            index = last_bin
        counts[index] += 1

    return counts, edges

