_WHITESPACE = b" \t\r\n\v\f"
_COMMENT = 0x23  # '#'


def _skip_blanks(data, pos):
    """Advance past whitespace and '#' comments, returning the new position."""
    size = len(data)
    while pos < size:
        byte = data[pos]
        if byte in _WHITESPACE:
            pos += 1
        elif byte == _COMMENT:
            line_ends = [i for i in (data.find(b"\n", pos), data.find(b"\r", pos)) if i != -1]
            pos = min(line_ends) + 1 if line_ends else size
        else:
            break
    return pos


def _read_token(data, pos):
    """Read one whitespace/comment delimited token, returning (token, next_pos)."""
    pos = _skip_blanks(data, pos)
    start = pos
    size = len(data)
    while pos < size and data[pos] not in _WHITESPACE and data[pos] != _COMMENT:
        pos += 1
    return data[start:pos], pos


def _read_uint(token, field):
    """Convert a decimal header/pixel token to a non-negative int."""
    if not token.isdigit():
        raise ValueError("invalid %s: %r" % (field, token))
    return int(token)


def _parse_header(data):
    """Parse the PGM header, returning (magic, width, height, maxval, pos)."""
