        raise ValueError("not a PGM image: missing P2/P5 magic number")
    magic = data[:2]

    pos = 2
    if pos < len(data) and data[pos] not in _WHITESPACE and data[pos] != _COMMENT:
        raise ValueError("malformed PGM magic number")

    width_token, pos = _read_token(data, pos)
    height_token, pos = _read_token(data, pos)
    maxval_token, pos = _read_token(data, pos)

    width = _read_uint(width_token, "width")
    height = _read_uint(height_token, "height")
    maxval = _read_uint(maxval_token, "maxval")

    if width < 1 or height < 1:
        raise ValueError("invalid image dimensions: %dx%d" % (width, height))
    if maxval < 1 or maxval > 255:
        raise ValueError("unsupported maxval for 8-bit grayscale: %d" % maxval)

    return magic, width, height, maxval, pos


def _histogram(values):
    """Count occurrences of each pixel value, keyed in ascending order."""
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    return dict(sorted(counts.items()))


def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit grayscale PGM image.

    ``data`` holds the raw bytes of a binary (P5) or ASCII (P2) PGM file.
    The result maps each pixel value present in the image to the number of
    pixels carrying that value.  Invalid or unsupported input raises
    ``ValueError``.
    """
    if isinstance(data, (bytearray, memoryview)):
        data = bytes(data)
    elif not isinstance(data, bytes):
        raise ValueError("expected the raw bytes of a PGM image, got %s" % type(data).__name__)

    magic, width, height, maxval, pos = _parse_header(data)
    pixel_count = width * height

    if magic == b"P5":
        if pos >= len(data) or data[pos] not in _WHITESPACE:
