        # treat a CR LF pair as that single separator.
        pos += 2 if data[pos] == 0x0D and data[pos + 1 : pos + 2] == b"\n" else 1

        raster = data[pos : pos + pixel_count]
        if len(raster) < pixel_count:
            raise ValueError("truncated raster data")
        if data[pos + pixel_count :].strip(_WHITESPACE):
            raise ValueError("unexpected data after raster")
        if raster and max(raster) > maxval:
            raise ValueError("pixel value %d exceeds maxval %d" % (max(raster), maxval))

        return _histogram(raster)

    values = []
    for _ in range(pixel_count):
        token, pos = _read_token(data, pos)
        if not token:
            raise ValueError("truncated pixel data")
        value = _read_uint(token, "pixel value")
        if value > maxval:
            raise ValueError("pixel value %d exceeds maxval %d" % (value, maxval))
        values.append(value)

    extra, _ = _read_token(data, pos)
    if extra:
        raise ValueError("unexpected data after pixel data")

    return _histogram(values)

