"""Classical (moving-average) seasonal decomposition."""


def classical_seasonal_decomposition(values, period, model='additive'):
    """Decompose an evenly spaced series into trend, seasonal and residual parts.

    The trend is a centred moving average of order ``period``: a simple moving
    average for odd periods, and a 2x``period`` moving average (half weights at
    the window ends) for even periods.  The seasonal component is the average
    detrended value for each position within the cycle, normalised so that it
    sums to zero (additive) or averages to one (multiplicative).

    Returns a dict with keys 'trend', 'seasonal' and 'resid', each a list as
    long as ``values``.  Entries of 'trend' and 'resid' are None where the
    centred moving average is undefined, i.e. at the ends of the series.
    """
    if model not in ('additive', 'multiplicative'):
        raise ValueError(
            "model must be 'additive' or 'multiplicative', got %r" % (model,)
        )
    if isinstance(period, bool):
        raise ValueError('period must be a positive integer, got %r' % (period,))
    try:
        whole = int(period)
    except (TypeError, ValueError):
        raise ValueError('period must be a positive integer, got %r' % (period,))
    if whole != period or whole < 1:
        raise ValueError('period must be a positive integer, got %r' % (period,))
    period = whole

    series = [float(v) for v in values]
    n = len(series)
    if n < 2 * period:
        raise ValueError(
            'series of length %d is shorter than two full periods (period=%d)'
            % (n, period)
        )

    half = period // 2

    # --- trend: centred moving average -------------------------------------
    trend = [None] * n
    if period % 2 == 1:
        for i in range(half, n - half):
            trend[i] = sum(series[i - half:i + half + 1]) / period
    else:
        edge = 1.0 / (2 * period)
        middle = 1.0 / period
        for i in range(half, n - half):
            trend[i] = (
                (series[i - half] + series[i + half]) * edge
                + sum(series[i - half + 1:i + half]) * middle
            )

    # --- detrended series --------------------------------------------------
    multiplicative = model == 'multiplicative'
    detrended = [None] * n
    for i in range(n):
        if trend[i] is None:
            continue
        if multiplicative:
            detrended[i] = series[i] / trend[i]
        else:
            detrended[i] = series[i] - trend[i]

    # --- seasonal component: average per phase, then normalise -------------
    sums = [0.0] * period
    counts = [0] * period
    for i in range(n):
        if detrended[i] is None:
            continue
        phase = i % period
        sums[phase] += detrended[i]
        counts[phase] += 1

    phase_means = []
    for phase in range(period):
        if counts[phase] == 0:
            phase_means.append(1.0 if multiplicative else 0.0)
        else:
            phase_means.append(sums[phase] / counts[phase])

    if multiplicative:
        reference = sum(phase_means) / period
        if reference != 0.0:
            phase_means = [m / reference for m in phase_means]
    else:
        reference = sum(phase_means) / period
        phase_means = [m - reference for m in phase_means]

    seasonal = [phase_means[i % period] for i in range(n)]

    # --- residual ----------------------------------------------------------
