import math


def max_pairwise_distance(xs, ys):
    """Largest Euclidean distance between any two distinct points (xs[i], ys[i])."""
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n < 2:
        return 0.0

    best = 0.0
    for i in range(n - 1):
        xi = xs[i]
        yi = ys[i]
        for j in range(i + 1, n):
            dx = xs[j] - xi
            dy = ys[j] - yi
            d2 = dx * dx + dy * dy
            if d2 > best:
                best = d2

    return math.sqrt(best)

