        minimum = min(standardized)
        maximum = max(standardized)
        counts = [0] * 20

        if minimum == maximum:
            counts[-1] = n
        else:
            width = (maximum - minimum) / 20
            for value in standardized:
                if value == maximum:
                    index = 19
                else:
                    index = int(math.floor((value - minimum) / width))
                    index = max(0, min(19, index))
                counts[index] += 1

        result[name] = (standardized, counts)

    return result

