import math


def _validate_data(X, y, name):
    if len(X) != len(y):
        raise ValueError(f"{name}: X and y must have the same number of rows")
    if len(X) == 0:
        return 0
    n_features = len(X[0])
    for row in X:
        if len(row) != n_features:
            raise ValueError(f"{name}: all rows of X must have the same length")
    return n_features


def _qr_least_squares(A, b):
    """Solve min ||A x - b||_2 with Householder QR.

    Returns ``(coefficients, full_rank)``.
    """
    n_rows = len(A)
    n_cols = len(A[0]) if n_rows else 0

    R = [[float(value) for value in row] for row in A]
    z = [float(value) for value in b]

    column_scales = [
        math.sqrt(sum(R[i][j] * R[i][j] for i in range(n_rows)))
        for j in range(n_cols)
    ]

    rank = 0
    for k in range(min(n_rows, n_cols)):
        norm = math.sqrt(sum(R[i][k] * R[i][k] for i in range(k, n_rows)))
        scale = column_scales[k]
        if scale == 0.0 or norm <= 1e-12 * scale:
            continue

        rank += 1
        alpha = -norm if R[k][k] >= 0.0 else norm
        v = [0.0] * (n_rows - k)
        v[0] = R[k][k] - alpha
        for i in range(k + 1, n_rows):
            v[i - k] = R[i][k]

        v_norm_sq = sum(value * value for value in v)
        if v_norm_sq == 0.0:
            rank -= 1
            continue

        for j in range(k, n_cols):
            dot = sum(v[i - k] * R[i][j] for i in range(k, n_rows))
            factor = 2.0 * dot / v_norm_sq
            for i in range(k, n_rows):
                R[i][j] -= factor * v[i - k]

        dot = sum(v[i - k] * z[i] for i in range(k, n_rows))
        factor = 2.0 * dot / v_norm_sq
        for i in range(k, n_rows):
            z[i] -= factor * v[i - k]

    coefficients = [0.0] * n_cols
    if rank < n_cols:
        return coefficients, False

    for i in range(n_cols - 1, -1, -1):
        residual = z[i]
        for j in range(i + 1, n_cols):
            residual -= R[i][j] * coefficients[j]
        coefficients[i] = residual / R[i][i]

    return coefficients, True


def _svd_least_squares(A, b):
    """Return the minimum-norm least-squares solution via one-sided Jacobi SVD."""
    n_rows = len(A)
    n_cols = len(A[0]) if n_rows else 0
    if n_cols == 0:
        return []

    B = [[float(value) for value in row] for row in A]
    V = [[0.0] * n_cols for _ in range(n_cols)]
    for i in range(n_cols):
        V[i][i] = 1.0

    for _ in range(100):
        converged = True
        for i in range(n_cols - 1):
            for j in range(i + 1, n_cols):
                alpha = 0.0
                beta = 0.0
                gamma = 0.0
                for k in range(n_rows):
                    bi = B[k][i]
                    bj = B[k][j]
                    alpha += bi * bi
                    beta += bj * bj
                    gamma += bi * bj

                if alpha == 0.0 or beta == 0.0:
                    continue
                if abs(gamma) <= 1e-15 * math.sqrt(alpha * beta):
                    continue

                converged = False
                zeta = (beta - alpha) / (2.0 * gamma)
                if zeta == 0.0:
                    t = 1.0
                else:
                    t = math.copysign(1.0, zeta) / (
                        abs(zeta) + math.sqrt(1.0 + zeta * zeta)
                    )
                c = 1.0 / math.sqrt(1.0 + t * t)
                s = c * t

                for k in range(n_rows):
                    bi = B[k][i]
                    bj = B[k][j]
                    B[k][i] = c * bi - s * bj
                    B[k][j] = s * bi + c * bj

                for k in range(n_cols):
                    vi = V[k][i]
                    vj = V[k][j]
                    V[k][i] = c * vi - s * vj
                    V[k][j] = s * vi + c * vj

        if converged:
            break

    singular_values = [
        math.sqrt(sum(B[k][j] * B[k][j] for k in range(n_rows)))
        for j in range(n_cols)
    ]
    largest = max(singular_values, default=0.0)
    if largest == 0.0:
        return [0.0] * n_cols

    threshold = max(n_rows, n_cols) * 2.220446049250313e-16 * largest
    coefficients = [0.0] * n_cols
    for j, singular_value in enumerate(singular_values):
        if singular_value <= threshold:
            continue

        projection = sum(B[k][j] * b[k] for k in range(n_rows))
        factor = projection / (singular_value * singular_value)
        for i in range(n_cols):
            coefficients[i] += factor * V[i][j]

    return coefficients


def _least_squares(A, b):
    coefficients, full_rank = _qr_least_squares(A, b)
    if full_rank:
        return coefficients
    return _svd_least_squares(A, b)


def fit_and_evaluate_linear_regression(X_train, y_train, X_test, y_test):
    """Fit OLS linear regression with an intercept and evaluate on test data.

    Returns ``(predictions, coefficients, intercept, mse)``.
    """
    n_features = _validate_data(X_train, y_train, "training data")
    n_test_features = _validate_data(X_test, y_test, "test data")
    if len(X_test) > 0 and n_test_features != n_features:
        raise ValueError(
            "X_train and X_test must have the same number of features"
        )

    n_train = len(X_train)
    if n_train == 0:
        raise ValueError("training data must contain at least one row")

    x_mean = [
        sum(float(row[j]) for row in X_train) / n_train
        for j in range(n_features)
    ]
    y_mean = sum(float(value) for value in y_train) / n_train

    centered_X = [
        [float(row[j]) - x_mean[j] for j in range(n_features)]
        for row in X_train
    ]
    centered_y = [float(value) - y_mean for value in y_train]

    coefficients = _least_squares(centered_X, centered_y)
    intercept = y_mean - sum(
        x_mean[j] * coefficients[j] for j in range(n_features)
    )

    predictions = []
    for row in X_test:
        prediction = y_mean
        for j in range(n_features):
            prediction += (float(row[j]) - x_mean[j]) * coefficients[j]
        predictions.append(float(prediction))

    if len(y_test) > 0:
        mse = sum(
            (prediction - float(actual)) ** 2
            for prediction, actual in zip(predictions, y_test)
        ) / len(y_test)
    else:
        mse = 0.0

    return predictions, coefficients, float(intercept), float(mse)

