from math import sqrt


def feature_correlation_matrix(samples):
    """Return the pairwise Pearson correlation matrix between features.

    ``samples`` is a list of rows, each row a list of numeric values of equal
    length. Each position in a row is a feature, so entry ``[i][j]`` of the
    result is the correlation between column ``i`` and column ``j``.
    """
    if not samples:
        return []

    rows = [list(row) for row in samples]
    n_features = len(rows[0])
    n_rows = len(rows)

    for row in rows:
        if len(row) != n_features:
            raise ValueError("all rows must have the same length")

    # Column means.
    means = [0.0] * n_features
    for row in rows:
        for j in range(n_features):
            means[j] += row[j]
    for j in range(n_features):
        means[j] /= n_rows

    # Centered values, plus sums of squared deviations for each feature.
    centered = [[row[j] - means[j] for j in range(n_features)] for row in rows]
    ss = [0.0] * n_features
    for c_row in centered:
        for j in range(n_features):
            ss[j] += c_row[j] * c_row[j]

    # Sum of cross products between every pair of features.
    matrix = [[0.0] * n_features for _ in range(n_features)]
    for i in range(n_features):
        for k in range(i, n_features):
            if i == k:
                # A feature is perfectly correlated with itself, unless it is
                # constant, in which case the correlation is undefined.
                value = 1.0 if ss[i] > 0.0 else 0.0
            elif ss[i] <= 0.0 or ss[k] <= 0.0:
                # At least one feature is constant: correlation undefined.
                value = 0.0
            else:
                cross = 0.0
                for c_row in centered:
                    cross += c_row[i] * c_row[k]
                value = cross / sqrt(ss[i] * ss[k])
                # Guard against floating point overshoot outside [-1, 1].
                if value > 1.0:
                    value = 1.0
                elif value < -1.0:
                    value = -1.0
            matrix[i][k] = value
            matrix[k][i] = value

    return matrix

