import json
from html.parser import HTMLParser


class _TitleExtractor(HTMLParser):
    """Collect the text of the first <title> element in a document."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found = False
        self.done = False
        self._inside = False
        self._chunks = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == "title" and not self.found and not self._inside:
            self.found = True
            self._inside = True
            self._chunks = []

    def handle_startendtag(self, tag, attrs):
        # <title/> is an empty title element.
        if self.done:
            return
        if tag == "title" and not self.found and not self._inside:
            self.found = True
            self.done = True

    def handle_endtag(self, tag):
        if self._inside and tag == "title":
            self._inside = False
            self.done = True

    def handle_data(self, data):
        if self._inside:
            self._chunks.append(data)

    def text(self):
        return "".join(self._chunks)


def extract_title_json(html):
    """Return '{"title": <first title text or null>}' for the given markup."""
    if html is None:
        html = ""
    elif isinstance(html, bytes):
        html = html.decode("utf-8", "replace")
    elif not isinstance(html, str):
        html = str(html)

    parser = _TitleExtractor()
    try:
        parser.feed(html)
        parser.close()
    except Exception:
        # Malformed markup: fall back to whatever was collected so far.
        pass

    if not parser.found:
        title = None
    else:
        title = parser.text().strip()

    return json.dumps({"title": title})

