    sums = [[0.0, 0.0] for _ in range(n_clusters)]
    counts = [0] * n_clusters
    for point, label in zip(points, labels):
        sums[label][0] += point[0]
        sums[label][1] += point[1]
        counts[label] += 1

    # A cluster may become empty when two centers coincide (for example,
    # with duplicate input points).  Move a point from a cluster that has
    # more than one member into each empty cluster.  This keeps every
    # returned cluster represented and is harmless when duplicate points
    # make distinct centers impossible.
    for empty in range(n_clusters):
