"""Ordinary least-squares linear regression with an intercept."""

from math import atan2, cos, isfinite, sin


def _solve_linear_system(matrix, rhs):
    """Solve a square linear system with partial-pivoting elimination.

    Returns None when the matrix is (numerically) singular.
    """
    n = len(rhs)
    if n == 0:
        return []

    a = [list(map(float, matrix[i])) + [float(rhs[i])] for i in range(n)]
    scale = max((abs(value) for row in matrix for value in row), default=0.0)
    tolerance = 1e-12 * scale if scale > 0.0 else 0.0

    for col in range(n):
        pivot = max(range(col, n), key=lambda row: abs(a[row][col]))
        if abs(a[pivot][col]) <= tolerance:
            return None
        if pivot != col:
            a[col], a[pivot] = a[pivot], a[col]

        pivot_value = a[col][col]
        for row in range(col + 1, n):
            factor = a[row][col] / pivot_value
            if factor == 0.0:
                continue
            a[row][col] = 0.0
            for j in range(col + 1, n + 1):
                a[row][j] -= factor * a[col][j]

    solution = [0.0] * n
    for row in range(n - 1, -1, -1):
        total = a[row][n]
        for col in range(row + 1, n):
            total -= a[row][col] * solution[col]
        solution[row] = total / a[row][row]
    return solution


def _symmetric_pseudoinverse_solve(matrix, rhs):
    """Return the minimum-norm solution to matrix*x = rhs.

    matrix is expected to be symmetric positive semidefinite.  A Jacobi
    eigendecomposition is used, which also handles rank-deficient systems.
    """
    n = len(rhs)
    if n == 0:
        return []

    a = [[float(matrix[i][j]) for j in range(n)] for i in range(n)]
    vectors = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    matrix_scale = max((abs(a[i][j]) for i in range(n) for j in range(n)), default=0.0)
    jacobi_tolerance = 1e-15 * matrix_scale

    # Jacobi rotations diagonalize the symmetric matrix.
    for _ in range(100 * n * n + 1):
        p, q = 0, 1
        largest = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                value = abs(a[i][j])
                if value > largest:
                    largest = value
                    p, q = i, j
        if n < 2 or largest <= jacobi_tolerance:
            break

        app, aqq, apq = a[p][p], a[q][q], a[p][q]
        angle = 0.5 * atan2(2.0 * apq, aqq - app)
        c, s = cos(angle), sin(angle)

        # Apply the rotation to A and accumulate it in vectors.
        for k in range(n):
            if k != p and k != q:
                akp, akq = a[k][p], a[k][q]
                a[k][p] = a[p][k] = c * akp - s * akq
                a[k][q] = a[q][k] = s * akp + c * akq
        a[p][p] = c * c * app - 2.0 * s * c * apq + s * s * aqq
        a[q][q] = s * s * app + 2.0 * s * c * apq + c * c * aqq
        a[p][q] = a[q][p] = 0.0

        for k in range(n):
            vkp, vkq = vectors[k][p], vectors[k][q]
            vectors[k][p] = c * vkp - s * vkq
            vectors[k][q] = s * vkp + c * vkq

    eigenvalues = [a[i][i] for i in range(n)]
    max_eigenvalue = max((abs(value) for value in eigenvalues), default=0.0)
    threshold = 1e-12 * max_eigenvalue if max_eigenvalue > 0.0 else 0.0

    solution = [0.0] * n
    for k in range(n):
        eigenvalue = eigenvalues[k]
        if eigenvalue <= threshold:
            continue
        projection = sum(vectors[i][k] * rhs[i] for i in range(n))
        factor = projection / eigenvalue
        for i in range(n):
            solution[i] += factor * vectors[i][k]
    return solution


def fit_linear_regression(features, values):
    """Fit an ordinary least-squares linear regression with an intercept.

    Args:
        features: A list of rows, where each row contains numeric feature
            values.
        values: The target value for each feature row.

    Returns:
        A dict with ``'coefficients'`` (one coefficient per feature column)
        and ``'intercept'``.
    """
    row_count = len(features)
    if row_count != len(values):
        raise ValueError("features and values must have the same length")
    if row_count == 0:
        raise ValueError("at least one observation is required")

    feature_count = len(features[0])

    x = []
    for row in features:
        if len(row) != feature_count:
            raise ValueError("all feature rows must have the same length")
        x.append([float(value) for value in row])
    y = [float(value) for value in values]

    for row in x:
        for value in row:
            if not isfinite(value):
                raise ValueError("features must contain finite numbers")
    for value in y:
        if not isfinite(value):
            raise ValueError("values must contain finite numbers")

    x_means = [
        sum(row[column] for row in x) / row_count
        for column in range(feature_count)
    ]
    y_mean = sum(y) / row_count

    if feature_count == 0:
        return {"coefficients": [], "intercept": float(y_mean)}

    # Solve the normal equations after centering, which makes the intercept
    # independent of the coefficient vector.
    normal_matrix = [[0.0] * feature_count for _ in range(feature_count)]
    normal_rhs = [0.0] * feature_count
    for row, target in zip(x, y):
        centered_y = target - y_mean
        centered_row = [row[j] - x_means[j] for j in range(feature_count)]
        for j in range(feature_count):
            normal_rhs[j] += centered_row[j] * centered_y
            for k in range(j, feature_count):
                product = centered_row[j] * centered_row[k]
                normal_matrix[j][k] += product
                if j != k:
                    normal_matrix[k][j] += product

    coefficients = _solve_linear_system(normal_matrix, normal_rhs)
