"""Utilities for merging CSV documents."""

from __future__ import annotations

import csv
import io
import re
from typing import Any, Iterable

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(
    r"^[+-]?(?:(?:\d+\.\d*)|(?:\.\d+))(?:[eE][+-]?\d+)?$"
    r"|^[+-]?\d+[eE][+-]?\d+$"
)


def _parse_value(value: str | None) -> Any:
    """Return None for an empty cell and a number for numeric-looking text."""
    if value is None or value == "":
        return None

    candidate = value.strip()
    if not candidate:
        return value

    if _INT_RE.fullmatch(candidate):
        try:
            return int(candidate)
        except ValueError:  # pragma: no cover - the regex makes this unlikely
            return value

    if _FLOAT_RE.fullmatch(candidate):
        try:
            return float(candidate)
        except ValueError:  # pragma: no cover - the regex makes this unlikely
            return value

    return value


def merge_csv_texts(csv_texts: Iterable[str]) -> list[dict[str, Any]]:
    """Stack CSV documents into a single list of row dictionaries.

    The columns are the union of all input headers, in first-appearance order.
    A row receives ``None`` for any column not present in its source document
    or for an empty cell. Numeric-looking cells are converted to ``int`` or
    ``float``; all other cells remain strings.
    """
    if csv_texts is None:
        return []

    parsed_documents: list[tuple[list[str], list[list[str]]]] = []
    columns: list[str] = []
    seen_columns: set[str] = set()

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text, newline=""))
        try:
            header = next(reader)
        except StopIteration:
            continue

        if header:
            # A UTF-8 BOM may appear in the first header when text was read
            # from a BOM-prefixed file.
            header = list(header)
            header[0] = header[0].lstrip("\ufeff")

        for column in header:
            if column not in seen_columns:
                seen_columns.add(column)
                columns.append(column)

        rows: list[list[str]] = []
        for row in reader:
            # Completely blank physical lines are not data rows. A row such as
            # "," is retained because it contains actual (empty) cells.
            if row:
                rows.append(row)

        parsed_documents.append((header, rows))

    result: list[dict[str, Any]] = []
    for header, rows in parsed_documents:
        for row in rows:
            row_values = {
                column: _parse_value(row[index] if index < len(row) else None)
                for index, column in enumerate(header)
            }
            result.append({column: row_values.get(column) for column in columns})

    return result

