"""Utilities for standardizing data series."""

from math import sqrt


def _standardize(values):
    """Return the z-scores of *values* using the population std. dev."""
    n = len(values)
    if n == 0:
        return []

    mean = sum(values) / n
    variance = sum((value - mean) ** 2 for value in values) / n
    std_dev = sqrt(variance)

    if std_dev == 0:
        return [0.0 for _ in values]

    return [(value - mean) / std_dev for value in values]


def standardize_series(x, y, labels):
    """Standardize each x/y series independently and map results by label.

    Each series is standardized using its own mean and population standard
    deviation.  The returned dictionary maps every label to
    ``[scaled_x, scaled_y]``.
    """
    return {
        label: [_standardize(x_values), _standardize(y_values)]
        for label, x_values, y_values in zip(labels, x, y)
    }

