import csv
import io
from decimal import Decimal, InvalidOperation
from typing import Dict, List, Union


def _parse_number(value: str):
    """Return *value* as a finite Decimal, or None if it is not numeric."""
    if value is None:
        return None
    text = value.strip()
    if not text:
        return None
    try:
        number = Decimal(text)
    except (InvalidOperation, TypeError, ValueError):
        return None
    if not number.is_finite():
        return None
    return number


def normalize_numeric_columns(csv_text: str) -> Dict[str, List[Union[str, float]]]:
    """Parse a CSV and min-max normalize every all-numeric column.

    Non-numeric columns are returned unchanged as strings.  A numeric column
    containing only one distinct value is normalized to all ``0.0``.  A
    ``ValueError`` is raised when the CSV has no numeric columns.
    """
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")

    reader = csv.reader(io.StringIO(csv_text, newline=""))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV has no header row") from None

    # Remove a possible UTF-8 BOM that survived decoding.
    if header:
        header[0] = header[0].lstrip("\ufeff")

    # Ignore entirely blank records (common at the end of CSV files), but keep
    # the data aligned with the header.
    rows = [row for row in reader if row]
    if not rows:
        raise ValueError("CSV has no data rows")

    columns: Dict[str, List[str]] = {}
    for index, name in enumerate(header):
        values = []
        for row in rows:
            if index < len(row):
                values.append(row[index])
            else:
                # Missing cells cannot form a numeric column.  Represent them
                # as empty strings so the output remains row-aligned.
                values.append("")
        columns[name] = values

    numeric_columns = set()
    normalized: Dict[str, List[Union[str, float]]] = {}
    for name, values in columns.items():
        numbers = [_parse_number(value) for value in values]
        if values and all(number is not None for number in numbers):
            numeric_columns.add(name)
            minimum = min(numbers)  # type: ignore[type-var]
            maximum = max(numbers)  # type: ignore[type-var]
            if maximum == minimum:
                normalized[name] = [0.0 for _ in numbers]
            else:
                span = maximum - minimum
                normalized[name] = [
                    float((number - minimum) / span) for number in numbers  # type: ignore[operator]
                ]
        else:
            normalized[name] = list(values)

    if not numeric_columns:
        raise ValueError("CSV contains no numeric columns")

    return normalized

