import csv
import io
import re
from collections import Counter


_WORD_RE = re.compile(r"\w{2,}", re.UNICODE)
_STOP_WORDS = {"a", "an", "the", "in", "on", "at", "and", "or"}


def top_word_counts(csv_text):
    """Return the ten most common non-stop words in a one-column CSV text.

    Words are case-insensitive runs of at least two word characters. Results
    are ordered by descending count and then alphabetically for ties.
    """
    counts = Counter()

    for row in csv.reader(io.StringIO(csv_text)):
        for field in row:
            for word in _WORD_RE.findall(field.lower()):
                if word not in _STOP_WORDS:
                    counts[word] += 1

    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:10]

