import csv
import io
import re
from datetime import date


_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _parse_iso_date(value):
    """Parse a strict YYYY-MM-DD date string, raising ValueError if invalid."""
    if not isinstance(value, str) or not _DATE_RE.fullmatch(value):
        raise ValueError(f"Invalid date: {value!r}")
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"Invalid date: {value!r}") from exc


def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    """Return CSV data rows whose date column is within the inclusive range.

    The CSV is expected to have a header row. Matching rows are returned as
    lists of strings, preserving their original order.
    """
    start = _parse_iso_date(start_date)
    end = _parse_iso_date(end_date)

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column not found: {column_name!r}")

    try:
        column_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column not found: {column_name!r}")

    matching_rows = []
    for row in reader:
        # Ignore completely blank lines, which csv.reader may represent as [].
        if not row:
            continue
        # Rows shorter than the header are malformed; treat the missing column
        # as not matching the requested range rather than raising.
        if column_index >= len(row):
            continue
        try:
            row_date = _parse_iso_date(row[column_index])
        except ValueError:
            # The row's date is not a valid YYYY-MM-DD value, so it cannot be
            # considered to fall in the range.
            continue
        if start <= row_date <= end:
            matching_rows.append(row)

    return matching_rows

