    """Return ``(header, rows)`` from CSV text.

    Completely blank physical lines are ignored.  Otherwise every row must
    have exactly the same number of fields as the header.
    """
    if not isinstance(csv_text, str):
        raise ValueError("CSV input must be text")

    try:
        parsed = list(csv.reader(io.StringIO(csv_text)))
    except csv.Error as exc:
        raise ValueError("invalid CSV input") from exc

    if not parsed:
        raise ValueError("CSV input must contain a header row")

    header = [cell.strip() for cell in parsed[0]]
    if not header or any(cell == "" for cell in header):
        raise ValueError("CSV header contains an empty column name")
    if len(set(header)) != len(header):
        raise ValueError("CSV header contains duplicate column names")

    rows = []
    for row in parsed[1:]:
        # csv.reader produces an empty list for a blank line.  Such lines do
        # not represent data rows.
        if len(row) == 0:
            continue
        if len(row) != len(header):
            raise ValueError("CSV row has the wrong number of fields")
        rows.append(row)

    return header, rows


def _parse_number(value, column):
    """Parse a required finite numeric field or raise ValueError."""
    if value is None:
        raise ValueError("missing value in column %r" % (column,))
    text = value.strip()
    if text == "":
        raise ValueError("missing value in column %r" % (column,))
    try:
        number = float(text)
    except (TypeError, ValueError) as exc:
        raise ValueError("non-numeric value in column %r" % (column,)) from exc
    if not math.isfinite(number):
        raise ValueError("non-finite value in column %r" % (column,))
    return number


def _least_squares(columns, y):
    """Solve a least-squares problem using pivoted modified Gram-Schmidt.

    ``columns`` is a list of equal-length columns and ``y`` is the response.
    The returned coefficient vector corresponds to the original column order.
    Rank-deficient systems produce a valid least-squares solution (dependent
    columns receive zero coefficients).
    """
    n = len(y)
    p = len(columns)
    if p == 0:
        return []
    if n == 0:
        raise ValueError("cannot fit a regression with no training rows")

    # Residual columns, initially equal to the input columns.
    residual = [list(column) for column in columns]
    unchosen = set(range(p))
    q_columns = []
    pivots = []
    r_rows = []

    # The input columns are standardized before this function is called, so
    # their initial norms are about sqrt(n).  This tolerance only decides when
    # a residual column is numerically indistinguishable from zero.
    rank_tol = 1e-12 * max(1.0, math.sqrt(float(n)))
    rank_tol_sq = rank_tol * rank_tol

    for _ in range(min(n, p)):
        best = None
        best_norm_sq = -1.0
        for j in unchosen:
            norm_sq = math.fsum(value * value for value in residual[j])
            if norm_sq > best_norm_sq:
                best_norm_sq = norm_sq
                best = j

        if best is None or best_norm_sq <= rank_tol_sq:
            break

        norm = math.sqrt(best_norm_sq)
        q = [value / norm for value in residual[best]]
        q_columns.append(q)
        pivots.append(best)

        r_row = [0.0] * p
        r_row[best] = norm

        for j in list(unchosen):
            if j == best:
                continue

            # Orthogonalize this residual column against the new basis vector.
            # A second pass improves orthogonality for poorly conditioned data.
            first = math.fsum(q[i] * residual[j][i] for i in range(n))
            if first != 0.0:
                residual[j] = [
                    residual[j][i] - first * q[i] for i in range(n)
                ]
            second = math.fsum(q[i] * residual[j][i] for i in range(n))
            if second != 0.0:
                residual[j] = [
                    residual[j][i] - second * q[i] for i in range(n)
                ]
            r_row[j] = first + second

        r_rows.append(r_row)
        unchosen.remove(best)

    rank = len(pivots)
    if rank == 0:
        return [0.0] * p

    qty = [
        math.fsum(q_columns[i][row] * y[row] for row in range(n))
        for i in range(rank)
    ]

    def solve_upper_triangular(rhs):
        """Solve the leading rank-by-rank triangular system."""
        result = [0.0] * rank
        for i in range(rank - 1, -1, -1):
            value = rhs[i]
            for k in range(i + 1, rank):
                value -= r_rows[i][pivots[k]] * result[k]
            diagonal = r_rows[i][pivots[i]]
            if diagonal == 0.0:
                result[i] = 0.0
            else:
                result[i] = value / diagonal
        return result

    pivot_set = set(pivots)
    free_order = [j for j in range(p) if j not in pivot_set]
    u = solve_upper_triangular(qty)

    if not free_order:
        solution = u
    else:
        # For a rank-deficient design, R = [R11 R12].  Write z as
        # [z1; z2] in pivot order, where R11*z1 + R12*z2 = Q^T*y.
        # Solving for z1 gives z1 = u - B*z2 with u=R11^-1*Q^T*y and
        # B=R11^-1*R12.  Minimizing ||z1||^2 + ||z2||^2 then requires
        # (B^T B + I) z2 = B^T u, which yields the minimum-norm solution.
        free_count = len(free_order)
        b_matrix = [[0.0] * free_count for _ in range(rank)]
        for k, original_index in enumerate(free_order):
            rhs = [r_rows[i][original_index] for i in range(rank)]
            column = solve_upper_triangular(rhs)
            for i in range(rank):
                b_matrix[i][k] = column[i]

        normal = [
            [
                math.fsum(
                    b_matrix[i][a] * b_matrix[i][b] for i in range(rank)
                )
                + (1.0 if a == b else 0.0)
                for b in range(free_count)
            ]
            for a in range(free_count)
        ]
        normal_rhs = [
            math.fsum(b_matrix[i][k] * u[i] for i in range(rank))
            for k in range(free_count)
        ]

        # The matrix B^T B + I is symmetric positive definite.  Gaussian
        # elimination with partial pivoting is sufficient and stable here.
        augmented = [
            normal[i][:] + [normal_rhs[i]] for i in range(free_count)
        ]
        for col in range(free_count):
            pivot = max(range(col, free_count), key=lambda r: abs(augmented[r][col]))
            if pivot != col:
                augmented[col], augmented[pivot] = augmented[pivot], augmented[col]
            pivot_value = augmented[col][col]
            if pivot_value == 0.0:
                continue
            for row in range(col + 1, free_count):
                factor = augmented[row][col] / pivot_value
                if factor == 0.0:
                    continue
                for k in range(col, free_count + 1):
                    augmented[row][k] -= factor * augmented[col][k]

        z2 = [0.0] * free_count
        for i in range(free_count - 1, -1, -1):
            value = augmented[i][free_count]
            for k in range(i + 1, free_count):
                value -= augmented[i][k] * z2[k]
            diagonal = augmented[i][i]
            if diagonal != 0.0:
                z2[i] = value / diagonal

        z1 = [
            u[i]
            - math.fsum(b_matrix[i][k] * z2[k] for k in range(free_count))
            for i in range(rank)
        ]
        solution = z1 + z2

    coefficients = [0.0] * p
    for i, original_index in enumerate(pivots):
        coefficients[original_index] = solution[i]
    for k, original_index in enumerate(free_order):
        coefficients[original_index] = solution[rank + k]
    return coefficients


def _fit(feature_rows, target_values):
    """Fit an intercept and feature coefficients; return ``(intercept, betas)``."""
    n = len(target_values)
    if n == 0:
        raise ValueError("cannot fit a regression with no training rows")

    feature_count = len(feature_rows[0]) if feature_rows else 0
    target_mean = math.fsum(target_values) / n

    means = [0.0] * feature_count
    scales = [0.0] * feature_count
    active = []

    for j in range(feature_count):
        column = [row[j] for row in feature_rows]
        mean = math.fsum(column) / n
        means[j] = mean
        if min(column) == max(column):
            # A constant feature is absorbed by the intercept.
            continue
        variance = math.fsum((value - mean) ** 2 for value in column) / n
        if variance <= 0.0 or not math.isfinite(variance):
            continue
        scale = math.sqrt(variance)
        if scale == 0.0 or not math.isfinite(scale):
            continue
        scales[j] = scale
        active.append(j)

    if not active:
        return target_mean, [0.0] * feature_count

    standardized_columns = []
    for j in active:
        mean = means[j]
        scale = scales[j]
        standardized_columns.append(
            [(row[j] - mean) / scale for row in feature_rows]
        )

    centered_target = [value - target_mean for value in target_values]
    active_coefficients = _least_squares(standardized_columns, centered_target)

    betas = [0.0] * feature_count
    for local_index, original_index in enumerate(active):
        betas[original_index] = (
            active_coefficients[local_index] / scales[original_index]
        )

    intercept = target_mean - math.fsum(
        betas[j] * means[j] for j in range(feature_count)
    )
    return intercept, betas


def predict_linear_regression(train_csv, test_csv, target):
    """Fit OLS with an intercept and predict ``target`` for rows of ``test_csv``.

    Parameters are CSV strings.  The target column is omitted from the feature
    set during training and is ignored entirely in the test data.  Missing or
    non-numeric values in any used field cause a ``ValueError``.
    """
    if not isinstance(target, str) or target.strip() == "":
        raise ValueError("target must be a non-empty column name")
    target = target.strip()

    train_header, train_rows = _read_csv(train_csv)
    test_header, test_rows = _read_csv(test_csv)

    if target not in train_header:
        raise ValueError("target column is not present in training CSV")
    if target not in test_header:
        raise ValueError("target column is not present in test CSV")

    if set(train_header) != set(test_header):
        raise ValueError("training and test CSV columns do not match")

    feature_names = [name for name in train_header if name != target]
    train_positions = {name: i for i, name in enumerate(train_header)}
    test_positions = {name: i for i, name in enumerate(test_header)}

    if not train_rows:
        raise ValueError("training CSV contains no data rows")

    feature_rows = []
    target_values = []
    for row in train_rows:
        parsed = {}
        for name in train_header:
            parsed[name] = _parse_number(row[train_positions[name]], name)
        feature_rows.append([parsed[name] for name in feature_names])
        target_values.append(parsed[target])

    intercept, betas = _fit(feature_rows, target_values)

    predictions = []
    for row in test_rows:
        # Only feature fields are parsed; the test target is intentionally
        # ignored even if blank or non-numeric.
        prediction = intercept
        for feature_index, name in enumerate(feature_names):
            value = _parse_number(row[test_positions[name]], name)
            prediction += betas[feature_index] * value
        predictions.append(float(prediction))

    return predictions

