    """Return True exactly when n is prime (for 0 <= n < 2**64)."""
    if n < 2:
        return False

    for p in _SMALL_PRIMES:
        if n % p == 0:
            return n == p

    # Write n - 1 as d * 2**s with d odd.
    d = n - 1
    s = 0
    while d & 1 == 0:
        d >>= 1
        s += 1

    for a in _MR_BASES:
        if a % n == 0:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = (x * x) % n
            if x == n - 1:
                break
        else:
            return False

    return True


def sorted_primes(numbers):
    """Return the prime values in *numbers*, sorted in ascending order.

    Prime occurrences are retained, so repeated input values produce
    repeated output values.
    """
    # Cache results for repeated inputs, then sort only the prime values.
    cache = {}
    primes = []
    for n in numbers:
        is_prime = cache.get(n)
        if is_prime is None:
            is_prime = _is_prime(n)
            cache[n] = is_prime
        if is_prime:
            primes.append(n)

    primes.sort()
    return primes

