import csv
import io


def normalize_csv_columns(csv_text):
    """Min-max normalize each numeric column in a CSV document.

    Args:
        csv_text: CSV text containing a header row followed by numeric rows.

    Returns:
        A dict mapping each header to a list of normalized floats.  Constant
        columns are normalized to all zeros.
    """
    reader = csv.reader(io.StringIO(csv_text.lstrip("\ufeff"), newline=""))

    try:
        header = next(reader)
    except StopIteration:
        return {}

    rows = []
    for row in reader:
        # Ignore completely blank lines, which csv.reader represents as [].
        if not row:
            continue
        rows.append(row)

    columns = {name: [] for name in header}

    for row in rows:
        if len(row) != len(header):
            raise ValueError(
                f"expected {len(header)} columns, got {len(row)}"
            )
        for name, value in zip(header, row):
            columns[name].append(float(value))

    normalized = {}
    for name, values in columns.items():
        if not values:
            normalized[name] = []
            continue
        low = min(values)
        high = max(values)
        if high == low:
            normalized[name] = [0.0 for _ in values]
        else:
            span = high - low
            normalized[name] = [(value - low) / span for value in values]

    return normalized

