def normalize_with_row_averages(data):
    """Min-max scale each feature column and append each row's average.

    Each column is scaled independently to [0, 1].  If every value in a
    column is the same, that column is scaled to zero.  The returned rows
    contain the scaled feature values followed by their arithmetic mean.
    """
    if not data:
        return []

    num_rows = len(data)
    num_features = len(data[0])
    if num_features == 0:
        return [[] for _ in range(num_rows)]

    # Compute each column's minimum and maximum in one pass over the data.
    minimums = list(data[0])
    maximums = list(data[0])
    for row in data[1:]:
        if len(row) != num_features:
            raise ValueError("all rows must have the same number of features")
        for col, value in enumerate(row):
            if value < minimums[col]:
                minimums[col] = value
            if value > maximums[col]:
                maximums[col] = value

    ranges = [maximums[col] - minimums[col] for col in range(num_features)]

    result = []
    for row in data:
        scaled = []
        for col, value in enumerate(row):
            if ranges[col] == 0:
                scaled.append(0.0)
            else:
                scaled.append((value - minimums[col]) / ranges[col])
        average = sum(scaled) / num_features
        result.append(scaled + [average])

    return result

