class _DataTableParser(HTMLParser):
    """Parse the first ``table.data-table`` and collect its td text.

    ``HTMLParser`` lower-cases tag and attribute names for us.  We use its
    character-reference conversion so text nodes contain decoded entities.
    """

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self._found_target = False
        self._done = False
        self._table_depth = 0
        self._row = None       # The list for the current row, if any.
        self._cell_parts = None  # Text parts for the current td, if any.

    @staticmethod
    def _class_value(attrs):
        """Return the first class attribute value, or None if absent."""
        for name, value in attrs:
            if name == "class":
                return value
        return None

    def _finish_cell(self):
        if self._cell_parts is not None and self._row is not None:
            self._row.append("".join(self._cell_parts))
        self._cell_parts = None

    def _finish_row(self):
        self._finish_cell()
        if self._row is not None:
            self.rows.append(self._row)
        self._row = None

    def handle_starttag(self, tag, attrs):
        if self._done:
            return

        if not self._found_target:
            if tag == "table" and self._class_value(attrs) == "data-table":
                self._found_target = True
                self._table_depth = 1
            return

        if tag == "table":
            # A nested table is not part of the target table's row/cell
            # structure.  Its text still belongs to an enclosing td.
            self._table_depth += 1
            return

        if self._table_depth != 1:
            return

        if tag == "tr":
            # A new row implicitly closes any previous open cell/row.
            self._finish_row()
            self._row = []
        elif tag == "td":
            if self._row is not None:
                # A new cell implicitly closes the previous one.
                self._finish_cell()
                self._cell_parts = []

    def handle_startendtag(self, tag, attrs):
        # Treat self-closing tags like an immediately closed start tag.  This
        # matters for e.g. <td/> and a self-closing target table.
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if self._done or not self._found_target:
            return

        if tag == "table":
            if self._table_depth > 1:
                self._table_depth -= 1
            else:
                # End of the selected table.
                self._finish_row()
                self._table_depth = 0
                self._done = True
            return

        if self._table_depth != 1:
            return

        if tag == "td":
            self._finish_cell()
        elif tag == "tr":
            self._finish_row()

    def handle_data(self, data):
        if (
            not self._done
            and self._found_target
            and self._table_depth >= 1
            and self._cell_parts is not None
        ):
            self._cell_parts.append(data)


def extract_data_table_rows(html):
    """Return the td text rows of the first table with class "data-table".

    Each row is returned in document order as a list of cell strings.  Text is
    preserved exactly as parsed, except that entities are decoded and all HTML
    tags are omitted.  If no matching table or no rows exist, ``[]`` is
    returned.
    """
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    return parser.rows

