import re
from collections import Counter


def keyword_article_word_counts(articles):
    """Count words in the content of articles whose titles mention like/what.

    Titles are matched case-insensitively as substrings. Content words are
    extracted while ignoring punctuation, and their original casing is kept.
    A ValueError is raised if any article is missing either required key.
    """
    for article in articles:
        if not isinstance(article, dict) or 'Title' not in article or 'Content' not in article:
            raise ValueError("Each article must contain 'Title' and 'Content' keys")

    selected_contents = [
        article['Content']
        for article in articles
        if 'like' in article['Title'].lower() or 'what' in article['Title'].lower()
    ]

    counts = Counter()
    for content in selected_contents:
        counts.update(re.findall(r"[^\W_]+", content, flags=re.UNICODE))

    return dict(counts)

