from html.parser import HTMLParser


_VOID_ELEMENTS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}


class _Node:
    __slots__ = ("tag", "attrs", "children", "parent")

    def __init__(self, tag=None, attrs=None, parent=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []
        self.parent = parent

    def classes(self):
        return (self.attrs.get("class") or "").split()


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node()
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        # HTMLParser lowercases tag and attribute names.
        node = _Node(tag, dict(attrs), self.stack[-1])
        self.stack[-1].children.append(node)
        if tag not in _VOID_ELEMENTS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        node = _Node(tag, dict(attrs), self.stack[-1])
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag):
        # Close the nearest matching open element.  If malformed HTML leaves
        # intervening elements open, they are implicitly closed as well.
        for index in range(len(self.stack) - 1, 0, -1):
            if self.stack[index].tag == tag:
                del self.stack[index:]
                break

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _element_text(node):
    """Return the concatenated text below *node*, excluding markup."""
    parts = []

    def walk(current):
        for child in current.children:
            if isinstance(child, str):
                parts.append(child)
            else:
                walk(child)

    walk(node)
    return "".join(parts).strip()


def _first_descendant(node, predicate):
    """Find the first matching element in pre-order below *node*."""
    for child in node.children:
        if isinstance(child, str):
            continue
        if predicate(child):
            return child
        found = _first_descendant(child, predicate)
        if found is not None:
            return found
    return None


def extract_article_info(html):
    """Extract (title, date, author) from every container div in *html*.

    Missing title/date/author elements yield the corresponding ``No ...``
    placeholder.  Element text is stripped and includes text from nested tags.
    """
    parser = _TreeBuilder()
    parser.feed(html)
    parser.close()

    def is_container(node):
        return node.tag == "div" and "container" in node.classes()

    def has_class(name):
        return lambda node: node.tag == "span" and name in node.classes()

    containers = []

    def collect(node):
        for child in node.children:
            if isinstance(child, str):
                continue
            if is_container(child):
                containers.append(child)
            collect(child)

    collect(parser.root)

    results = []
    for container in containers:
        h1 = _first_descendant(container, lambda node: node.tag == "h1")
        date = _first_descendant(container, has_class("date"))
        author = _first_descendant(container, has_class("author"))

        title_text = _element_text(h1) if h1 is not None else "No Title"
        date_text = _element_text(date) if date is not None else "No Date"
        author_text = _element_text(author) if author is not None else "No Author"
        results.append((title_text, date_text, author_text))

    return results

