def product_profit_report(records):
    """Aggregate sales and profit by product, sorted by total profit descending."""
    totals = {}

    for product, sales, margin in records:
        if product in totals:
            totals[product][0] += sales
            totals[product][1] += sales * margin
        else:
            totals[product] = [sales, sales * margin]

    report = [
        (product, total_sales, total_profit)
        for product, (total_sales, total_profit) in totals.items()
    ]
    report.sort(key=lambda item: item[2], reverse=True)
    return report

