def key_mean_median(json_text):
    """Return the mean and median of numeric values for every key.

    Values that are missing, null, or non-numeric are ignored.  A key that
    only has non-numeric values is still included, with both statistics set
    to None.
    """
    records = json.loads(json_text)
    values_by_key = {}

    for record in records:
        if not isinstance(record, dict):
            continue
        for key, value in record.items():
            values_by_key.setdefault(key, [])
            # bool is a subclass of int in Python, but JSON booleans are not
            # numeric values for this task.
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                values_by_key[key].append(value)

