"""Utilities for merging and standardizing tabular row data."""

from math import sqrt


def _ordered_feature_columns(rows):
    """Return non-id column names in first-seen order across rows."""
    columns = []
    seen = set()
    for row in rows:
        for key in row:
            if key != "id" and key not in seen:
                seen.add(key)
                columns.append(key)
    return columns


def _standardization_params(rows, columns):
    """Compute population mean and standard deviation for each column."""
    params = {}
    for column in columns:
        values = [row[column] for row in rows
                  if column in row and row[column] is not None]
        if not values:
            params[column] = (None, None)
            continue

        mean = sum(values) / len(values)
        variance = sum((value - mean) ** 2 for value in values) / len(values)
        params[column] = (mean, sqrt(variance))
    return params


def merge_and_standardize(rows1, rows2):
    """Outer-join two tables on ``id`` and standardize the first table's columns.

    Feature values in ``rows1`` are converted to z-scores using the population
    standard deviation computed over non-missing values in that column.  A
    constant column is mapped to zero.  Missing values remain ``None``, as do
    values for rows that only occur in the second table.  Columns from
    ``rows2`` are copied unchanged.
