    # key; using the first occurrence also gives deterministic behavior.
    table1_by_id = {}
    for row in rows1:
        table1_by_id.setdefault(row["id"], row)

    table2_by_id = {}
    for row in rows2:
        table2_by_id.setdefault(row["id"], row)

    all_ids = sorted(set(table1_by_id) | set(table2_by_id))

    merged = []
    for row_id in all_ids:
        row1 = table1_by_id.get(row_id)
        row2 = table2_by_id.get(row_id)

        result = {"id": row_id}

        for column in columns1:
            value = row1.get(column) if row1 is not None else None
            if value is None:
                result[column] = None
            else:
                mean, std = params[column]
                if mean is None or std == 0:
                    result[column] = 0.0
