import math


def standardize_columns(rows):
    """Standardize each column to population mean 0 and std dev 1.

    Args:
        rows: A non-empty list of equally-sized rows containing numbers.

    Returns:
        A list of rows of floats with the same shape as ``rows``. Columns
        with zero population standard deviation are returned as all zeros.

    Raises:
        ValueError: If ``rows`` is empty or its rows have inconsistent sizes.
    """
    if not rows:
        raise ValueError("rows must not be empty")

    num_columns = len(rows[0])
    if any(len(row) != num_columns for row in rows):
        raise ValueError("all rows must have the same number of columns")

    num_rows = len(rows)

    means = [
        math.fsum(row[column] for row in rows) / num_rows
        for column in range(num_columns)
    ]

    std_devs = [
        math.sqrt(
            math.fsum(
                (row[column] - means[column]) ** 2 for row in rows
            )
            / num_rows
        )
        for column in range(num_columns)
    ]

    return [
        [
            0.0
            if std_devs[column] == 0.0
            else (row[column] - means[column]) / std_devs[column]
            for column in range(num_columns)
        ]
        for row in rows
    ]

