"""Classical seasonal decomposition of a time series."""


def seasonal_decomposition(values, period, model):
    """Decompose ``values`` into trend, seasonal, and residual components.

    The trend is a centred moving average.  For an odd period it is a simple
    moving average; for an even period it is a 2 x period moving average,
    which keeps the trend values aligned with the original observations.

    Additive seasonal indices are normalised to have mean zero and
    multiplicative indices to have mean one.  Components that require a trend
    value at the ends of the series are returned as ``None``.

    Args:
        values: A sequence of numeric observations.
        period: The seasonal period (a positive integer).
        model: Either ``'additive'`` or ``'multiplicative'``.

    Returns:
        A dict with keys ``'trend'``, ``'seasonal'``, and ``'residual'``.
        Each maps to a list of the same length as ``values``.

    Raises:
        ValueError: If ``period`` is not a positive integer, ``model`` is not
            valid, or there are fewer than two complete periods of data.
    """
    if not isinstance(period, int) or isinstance(period, bool) or period <= 0:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("the series must contain at least two complete periods")

    # Centred moving-average trend.  For even periods, the average of two
    # adjacent p-point moving averages is used.  This is equivalent to a
    # weighted average with half weights at the two endpoints.
    trend = [None] * n
    half = period // 2
    for i in range(half, n - half):
        if period % 2 == 1:
            window = values[i - half : i + half + 1]
            trend[i] = sum(window) / period
        else:
            window_sum = (
                0.5 * values[i - half]
                + sum(values[i - half + 1 : i + half])
                + 0.5 * values[i + half]
            )
            trend[i] = window_sum / period

    # Estimate a seasonal index for each phase from the detrended values.
    phase_values = [[] for _ in range(period)]
    for i, (value, trend_value) in enumerate(zip(values, trend)):
        if trend_value is None:
            continue
        phase = i % period
        if model == "additive":
            phase_values[phase].append(value - trend_value)
        else:
            phase_values[phase].append(value / trend_value)

    # Every phase has at least one observation when there are two complete
    # periods, but guard against a phase with no usable trend values.
    seasonal_indices = []
    for phase in range(period):
        if not phase_values[phase]:
            seasonal_indices.append(None)
        else:
            seasonal_indices.append(
                sum(phase_values[phase]) / len(phase_values[phase])
            )

    defined_indices = [index for index in seasonal_indices if index is not None]
    if not defined_indices:
        raise ValueError("seasonal indices could not be computed")
    normaliser = sum(defined_indices) / len(defined_indices)

    if model == "additive":
        seasonal_indices = [
            None if index is None else index - normaliser
            for index in seasonal_indices
        ]
    else:
        if normaliser == 0:
            raise ValueError("cannot normalise multiplicative seasonal indices")
        seasonal_indices = [
            None if index is None else index / normaliser
            for index in seasonal_indices
        ]

    seasonal = [seasonal_indices[i % period] for i in range(n)]

    residual = [None] * n
    for i in range(n):
        if trend[i] is None or seasonal[i] is None:
            continue
        if model == "additive":
            residual[i] = values[i] - trend[i] - seasonal[i]
        else:
            denominator = trend[i] * seasonal[i]
            if denominator == 0:
                residual[i] = None
            else:
                residual[i] = values[i] / denominator

    return {"trend": trend, "seasonal": seasonal, "residual": residual}

