def scale_table_columns(data):
    """Drop rows containing None, then min-max scale each column to [0, 1]."""
    columns = list(data.keys())
    values = list(data.values())

    if not columns:
        return {}

    row_count = len(values[0])
    keep = [
        i
        for i in range(row_count)
        if all(column[i] is not None for column in values)
    ]

    result = {}
    for name, column in data.items():
        kept_values = [column[i] for i in keep]
        if not kept_values:
            result[name] = []
            continue

        minimum = min(kept_values)
        maximum = max(kept_values)
        if minimum == maximum:
            result[name] = [0.0 for _ in kept_values]
        else:
            span = maximum - minimum
            result[name] = [(value - minimum) / span for value in kept_values]

    return result

