"""Column-oriented ordinary least-squares linear regression."""


def _solve_normal_equations(a, b):
    """Solve a*x = b using Gaussian elimination with partial pivoting.

    If the system is singular, free variables are set to zero, which still
    gives an ordinary-least-squares solution when the normal equations are
    consistent (as they are for a least-squares problem).
    """
    n = len(a)
    if n == 0:
        return []

    # Work on an augmented copy, avoiding mutation of caller data.
    mat = [[float(a[i][j]) for j in range(n)] + [float(b[i])]
           for i in range(n)]

    pivot_cols = []
    row = 0
    for col in range(n):
        pivot = max(range(row, n), key=lambda r: abs(mat[r][col]))
        if abs(mat[pivot][col]) <= 1e-12:
            continue
        mat[row], mat[pivot] = mat[pivot], mat[row]

        pv = mat[row][col]
        for j in range(col, n + 1):
            mat[row][j] /= pv

        for r in range(n):
            if r == row:
                continue
            factor = mat[r][col]
            if factor != 0.0:
                for j in range(col, n + 1):
                    mat[r][j] -= factor * mat[row][j]

        pivot_cols.append(col)
        row += 1
        if row == n:
            break

    solution = [0.0] * n
    for r, col in enumerate(pivot_cols):
        solution[col] = mat[r][n]
    return solution


def _clean_float(value):
    """Remove harmless floating-point noise around exact integer results."""
    nearest = round(value)
    if abs(value - nearest) <= 1e-12 * max(1.0, abs(value)):
        return float(nearest)
    return float(value)


def column_linear_regression(rows, columns, target):
    """Fit an OLS regression predicting ``target`` from the other columns.

    An intercept is always included.  Returns ``(coefficients, intercept)``
    where ``coefficients`` follows the order of the non-target columns.
    """
    if not rows:
        raise ValueError("rows must not be empty")

    columns = list(columns)
    try:
        target_index = columns.index(target)
    except ValueError:
        raise ValueError("target must be one of the columns") from None

    feature_indices = [i for i in range(len(columns)) if i != target_index]
    feature_names = [columns[i] for i in feature_indices]

    # Design matrix includes a leading intercept column.
    design = []
    values = []
    for row in rows:
        design.append([1.0] + [float(row[i]) for i in feature_indices])
        values.append(float(row[target_index]))

    try:
        import numpy as np
    except ImportError:
        np = None

    if np is not None:
        try:
            coefficients, *_ = np.linalg.lstsq(
                np.asarray(design, dtype=float),
                np.asarray(values, dtype=float),
                rcond=None,
            )
            return (
                [_clean_float(c) for c in coefficients[1:]],
                _clean_float(coefficients[0]),
            )
        except np.linalg.LinAlgError:
            pass

    # Pure-Python fallback: build and solve the normal equations.
    num_features = len(feature_names)
    if num_features == 0:
        return [], _clean_float(sum(values) / len(values))

    size = num_features + 1
    xtx = [[0.0] * size for _ in range(size)]
    xty = [0.0] * size
    for x, y in zip(design, values):
        for i in range(size):
            xty[i] += x[i] * y
            for j in range(size):
                xtx[i][j] += x[i] * x[j]

    beta = _solve_normal_equations(xtx, xty)
    return [_clean_float(c) for c in beta[1:]], _clean_float(beta[0])

