from datetime import datetime
from zoneinfo import ZoneInfo


def publication_hour_stats(articles, timezone):
    """Return per-category statistics for publication hours in a timezone.

    Each article must contain ``category`` and ``published_time`` keys. The
    published time is parsed as an ISO 8601 timestamp with a UTC offset and
    converted to ``timezone`` before its hour is recorded.
    """
    if not articles:
        raise ValueError("articles must not be empty")

    tz = ZoneInfo(timezone)
    hours_by_category = {}

    for article in articles:
        if not isinstance(article, dict):
            raise ValueError("each article must be a dictionary")
        if "category" not in article or "published_time" not in article:
            raise ValueError("each article must contain 'category' and 'published_time'")

        published_time = datetime.fromisoformat(article["published_time"])
        local_hour = published_time.astimezone(tz).hour
        hours_by_category.setdefault(article["category"], []).append(local_hour)

    result = {}
    for category, hours in hours_by_category.items():
        count = len(hours)
        result[category] = {
            "count": count,
            "mean": sum(hours) / count,
            "min": min(hours),
            "max": max(hours),
        }

    return result

