"""Utilities for de-duplicating and clustering two-dimensional points."""

from collections import Counter
from math import inf
from random import Random


def _squared_distance(a, b):
    """Return the squared Euclidean distance between two points."""
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2


def _fallback_kmeans(points, n_clusters):
    """Small deterministic k-means implementation used if sklearn is absent.

    It runs several k-means++ initializations and keeps the result with the
    lowest inertia.  This is only a fallback; the primary path uses sklearn.
    """
    if n_clusters >= len(points):
        return list(range(len(points)))

    best_labels = None
    best_inertia = inf
    rng = Random(42)

    for _ in range(10):
        # k-means++ initialization.
        centers = [points[rng.randrange(len(points))]]
        while len(centers) < n_clusters:
            distances = [
                min(_squared_distance(p, c) for c in centers) for p in points
            ]
            total = sum(distances)
            if total == 0:
                # All points are already represented by a center.
                for p in points:
                    if p not in centers:
                        centers.append(p)
                        break
            else:
                threshold = rng.random() * total
                running = 0.0
                chosen = points[-1]
                for p, distance in zip(points, distances):
                    running += distance
                    if running >= threshold:
                        chosen = p
                        break
                centers.append(chosen)

        labels = [0] * len(points)
        for _iteration in range(300):
            new_labels = []
            for p in points:
                distances = [_squared_distance(p, c) for c in centers]
                new_labels.append(min(range(n_clusters), key=distances.__getitem__))

            if new_labels == labels:
                break
            labels = new_labels

            for cluster_index in range(n_clusters):
                members = [p for p, label in zip(points, labels) if label == cluster_index]
                if members:
                    centers[cluster_index] = (
                        sum(p[0] for p in members) / len(members),
                        sum(p[1] for p in members) / len(members),
                    )

        inertia = sum(
            _squared_distance(p, centers[label])
            for p, label in zip(points, labels)
        )
        if inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels

    return best_labels


def _cluster_labels(points, n_clusters):
    """Return a k-means label for every point."""
    try:
        from sklearn.cluster import KMeans

        model = KMeans(
            n_clusters=n_clusters,
            random_state=42,
            n_init=10,
        )
        return model.fit_predict(points)
    except ImportError:
        return _fallback_kmeans(points, n_clusters)


def cluster_unique_points(points, n_clusters):
    """Find duplicate points and cluster the distinct points with k-means.

    Args:
        points: An iterable of (x, y) points.
        n_clusters: Requested number of clusters.  If there are fewer distinct
            points, one cluster per distinct point is used instead.

    Returns:
        A tuple ``(duplicates, clusters)``.  ``duplicates`` maps each repeated
        point to its occurrence count.  ``clusters`` is a lexicographically
        sorted list of sorted point lists.
    """
    normalized_points = [tuple(point) for point in points]
    counts = Counter(normalized_points)

    duplicates = {
        point: count for point, count in counts.items() if count > 1
    }
    unique_points = list(counts.keys())

    if not unique_points:
        return duplicates, []

    requested_clusters = int(n_clusters)
    actual_clusters = max(0, min(requested_clusters, len(unique_points)))
    if actual_clusters == 0:
        return duplicates, []

    # Sorting before clustering makes the result independent of input order.
    unique_points.sort()
    labels = _cluster_labels(unique_points, actual_clusters)

    clusters = [[] for _ in range(actual_clusters)]
    for point, label in zip(unique_points, labels):
        clusters[int(label)].append(point)

    clusters = [sorted(cluster) for cluster in clusters]
    clusters.sort()
    return duplicates, clusters

