"""Pairwise Pearson correlation utilities."""

import math


def column_correlations(data):
    """Return the pairwise Pearson correlation matrix for ``data``.

    ``data`` maps column names to equal-length sequences of numbers.  The
    result is a nested dictionary where ``result[x][y]`` is the Pearson
    correlation coefficient between columns ``x`` and ``y``.

    A zero-variance column has an undefined Pearson correlation with other
    columns; those correlations are reported as ``0.0``.  The diagonal entry
    for every column is ``1.0``.
    """
    columns = list(data.keys())
    result = {column: {} for column in columns}

    if not columns:
        return result

    length = len(data[columns[0]])
    if length == 0:
        for x in columns:
            for y in columns:
                result[x][y] = 1.0 if x == y else 0.0
        return result

    means = {
        column: math.fsum(data[column]) / length
        for column in columns
    }
    centered = {
        column: [value - means[column] for value in data[column]]
        for column in columns
    }
    sum_squares = {
        column: math.fsum(value * value for value in centered[column])
        for column in columns
    }

    for x in columns:
        for y in columns:
            if x == y:
                result[x][y] = 1.0
                continue

            denominator = math.sqrt(sum_squares[x] * sum_squares[y])
            if denominator == 0.0:
                # Pearson correlation is undefined when either column is
                # constant.  Use a neutral value rather than failing.
                result[x][y] = 0.0
                continue

            numerator = math.fsum(
                x_value * y_value
                for x_value, y_value in zip(centered[x], centered[y])
            )
            correlation = numerator / denominator
            # Guard against tiny floating-point overshoots outside [-1, 1].
            result[x][y] = max(-1.0, min(1.0, correlation))

    return result

