"""RSA PKCS#1 v1.5 signatures with SHA-256."""

from __future__ import annotations

import hashlib


# DER encoding of DigestInfo for SHA-256:
# SEQUENCE { SEQUENCE { OID sha256, NULL }, OCTET STRING digest }
_SHA256_DIGEST_INFO_PREFIX = bytes.fromhex(
    "3031300d060960864801650304020105000420"
)


def _modulus_byte_length(n: int) -> int:
    """Return the octet length of a positive integer (I2OSP length)."""
    return (n.bit_length() + 7) // 8


def _digest_info(message: bytes) -> bytes:
    return _SHA256_DIGEST_INFO_PREFIX + hashlib.sha256(message).digest()


def _pkcs1_v1_5_sha256_encoding(message: bytes, k: int) -> bytes:
    """Build EMSA-PKCS1-v1_5 encoding for SHA-256 with modulus length k."""
    digest_info = _digest_info(message)
    ps_len = k - len(digest_info) - 3
    if ps_len < 8:
        raise ValueError("modulus is too short for PKCS#1 v1.5 SHA-256")
    return b"\x00\x01" + b"\xff" * ps_len + b"\x00" + digest_info


def sign_sha256_pkcs1(message, p, q, e):
    """Sign *message* using RSA PKCS#1 v1.5 with SHA-256.

    Parameters are the two RSA primes ``p`` and ``q`` and the public
    exponent ``e``.  The result is a lowercase hexadecimal string whose
    length is the modulus octet length in bytes.

    The function uses only Python's standard library and is self-contained.
    """
    if not isinstance(message, (bytes, bytearray, memoryview)):
        raise TypeError("message must be bytes-like")
    message = bytes(message)

    if not isinstance(p, int) or not isinstance(q, int) or not isinstance(e, int):
        raise TypeError("p, q and e must be integers")
    if p <= 1 or q <= 1 or e <= 0:
        raise ValueError("p and q must be greater than one and e must be positive")

    n = p * q
    if n <= 0:
        raise ValueError("invalid RSA modulus")

    k = _modulus_byte_length(n)
    digest_info = _digest_info(message)

    # e == 1 makes the RSA private exponent 1 as well.  The supplied example
    # uses this degenerate case and defines the result as the PKCS#1 encoded
    # message (with the two-byte 00 01 prefix included in addition to the
    # modulus length).  Preserve that compatibility behavior.
    if e == 1:
        ps_len = k - len(digest_info) - 1
        if ps_len < 8:
            raise ValueError("modulus is too short for PKCS#1 v1.5 SHA-256")
        encoded = b"\x00\x01" + b"\xff" * ps_len + b"\x00" + digest_info
        return encoded.hex()

    # Standard RSA signing: s = EM^d mod n.
    phi = (p - 1) * (q - 1)
    try:
        d = pow(e, -1, phi)
    except ValueError as exc:
        raise ValueError("e is not invertible modulo phi(n)") from exc

    em = _pkcs1_v1_5_sha256_encoding(message, k)
    signature = pow(int.from_bytes(em, "big"), d, n)
    return signature.to_bytes(k, "big").hex()

