def format_sorted_dict_table(my_dict):
    """Return a centered, ASCII-grid table of a dictionary sorted by key."""
    items = sorted(my_dict.items(), key=lambda item: item[0])

    key_width = max([len("Key")] + [len(str(key)) for key, _ in items])
    value_width = max([len("Value")] + [len(str(value)) for _, value in items])

    def rule():
        return "+" + "-" * (key_width + 2) + "+" + "-" * (value_width + 2) + "+"

    def row(key, value):
        return (
            "| "
            + str(key).center(key_width)
            + " | "
            + str(value).center(value_width)
            + " |"
        )

    lines = [rule(), row("Key", "Value"), rule()]
    lines.extend(row(key, value) for key, value in items)
    lines.append(rule())
    return "\n".join(lines)

