import math
import numbers
from collections.abc import Mapping


def normalized_cumulative_sums(data):
    """Return min-max normalized cumulative sums for each column in *data*.

    Each column's values are cumulatively summed and then scaled to [0, 1].
    If a column's cumulative sums are constant, every result for that column
    is 0.0.

    Args:
        data: A mapping from column names to equal-length lists of numbers.

    Returns:
        A dict mapping the same column names to lists of scaled floats.

    Raises:
        TypeError: If *data* is not a mapping, a column is not iterable, or a
            column contains a non-numeric value.
        ValueError: If *data* is empty, a column is empty, columns have
            different lengths, or any value is NaN.
    """
    if not isinstance(data, Mapping):
        raise TypeError("data must be a mapping of column names to lists")

    if not data:
        raise ValueError("data must not be empty")

    converted_columns = {}
    expected_length = None

    for column_name, values in data.items():
        try:
            values_list = list(values)
        except TypeError as exc:
            raise TypeError(
                f"column {column_name!r} must contain numeric values"
            ) from exc

        if expected_length is None:
            expected_length = len(values_list)
        elif len(values_list) != expected_length:
            raise ValueError("all columns must have the same length")

        if not values_list:
            raise ValueError("data must not be empty")

        converted_values = []
        for value in values_list:
            # Complex values are numeric but cannot be ordered or min-max
            # scaled, so they are treated as invalid input here.
            if isinstance(value, complex) or not isinstance(value, numbers.Number):
                raise TypeError(
                    f"column {column_name!r} contains a non-numeric value"
                )

            try:
                numeric_value = float(value)
            except (TypeError, ValueError, OverflowError) as exc:
                raise TypeError(
                    f"column {column_name!r} contains a non-numeric value"
                ) from exc

            if math.isnan(numeric_value):
                raise ValueError(f"column {column_name!r} contains NaN")

            converted_values.append(numeric_value)

        converted_columns[column_name] = converted_values

    result = {}
    for column_name, values in converted_columns.items():
        cumulative = []
        running_total = 0.0
        for value in values:
            running_total += value
            cumulative.append(running_total)

        minimum = min(cumulative)
        maximum = max(cumulative)

        if maximum == minimum:
            result[column_name] = [0.0] * len(cumulative)
        else:
            span = maximum - minimum
            result[column_name] = [
                (value - minimum) / span for value in cumulative
            ]

    return result

