import math
from collections import defaultdict


def standardize_by_group(records):
    """Standardize age and income within groups sharing the same id.

    Population standard deviation is used for each group. Values that are
    constant within their group are standardized to 0.0. The returned records
    preserve the input order and contain only the keys 'id', 'age', 'income'.
    """
    required_keys = ("id", "age", "income")

    # Validate the entire input before computing anything, so a malformed
    # record cannot result in a partial result.
    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in required_keys):
            raise ValueError("each record must contain 'id', 'age', and 'income' keys")

    groups = defaultdict(list)
    for index, record in enumerate(records):
        groups[record["id"]].append(index)

    result = [None] * len(records)

    for indices in groups.values():
        n = len(indices)

        for field in ("age", "income"):
            values = [float(records[index][field]) for index in indices]

            if all(value == values[0] for value in values):
                for index in indices:
                    result[index] = result[index] or {"id": records[index]["id"]}
                    result[index][field] = 0.0
                continue

            mean = math.fsum(values) / n
            variance = math.fsum((value - mean) ** 2 for value in values) / n
            std_dev = math.sqrt(variance)

            if std_dev == 0.0:
                for index in indices:
                    result[index] = result[index] or {"id": records[index]["id"]}
                    result[index][field] = 0.0
            else:
                for index, value in zip(indices, values):
                    result[index] = result[index] or {"id": records[index]["id"]}
                    result[index][field] = (value - mean) / std_dev

    return result

