"""Convert a simple XML document into nested Python dictionaries."""

import xml.etree.ElementTree as ET


def _element_value(element):
    """Return the dictionary/string representation of an XML element."""
    children = list(element)
    text_parts = []

    if element.text:
        text_parts.append(element.text)
    for child in children:
        if child.tail:
            text_parts.append(child.tail)

    text = "".join(text_parts).strip()
    has_attributes = bool(element.attrib)
    has_children = bool(children)

    # A simple leaf is represented only by its text (or None when absent).
    if not has_attributes and not has_children:
        return text or None

    value = {"@" + name: attr_value for name, attr_value in element.attrib.items()}

    for child in children:
        tag = child.tag
        child_value = _element_value(child)

        if tag not in value:
            value[tag] = child_value
        elif isinstance(value[tag], list):
            value[tag].append(child_value)
        else:
            value[tag] = [value[tag], child_value]

    if text:
        value["#text"] = text

    return value


def xml_to_dict(xml):
    """Parse *xml* and return ``{root_tag: root_value}``.

    Raises:
        ValueError: If *xml* is not a well-formed XML document.
    """
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError(str(exc)) from exc

    return {root.tag: _element_value(root)}

