import math


def standardize_columns(rows, columns, features):
    """Return a copy of ``rows`` with selected columns standardized.

    Each requested feature is rescaled to zero mean and unit population
    standard deviation. Constant feature columns are replaced with zeros.
    """
    result = [list(row) for row in rows]
    if not result:
        return result

    feature_set = set(features)
    feature_indices = [
        index for index, name in enumerate(columns) if name in feature_set
    ]
    row_count = len(result)

    for index in feature_indices:
        values = [row[index] for row in result]
        mean = sum(values) / row_count
        variance = sum((value - mean) ** 2 for value in values) / row_count
        stddev = math.sqrt(variance)

        if stddev == 0:
            for row in result:
                row[index] = 0.0
        else:
            for row in result:
                row[index] = (row[index] - mean) / stddev

    return result

