"""Utilities for summarizing rows and correlating columns of a numeric table."""

from math import fsum, isnan, sqrt
from numbers import Real


def _is_number(value):
    """Return True for real numeric values, excluding booleans."""
    return isinstance(value, Real) and not isinstance(value, bool)


def row_averages_and_correlations(data):
    """Return row means and the pairwise Pearson correlation of columns.

    ``data`` must be a rectangular list of lists containing real numbers.
    A ``ValueError`` is raised for malformed input.  Correlations that are
    mathematically undefined (because either column has zero variance, or
    because there are fewer than two rows) are represented by ``nan``.
    """
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")

    # An empty table has no rows and no columns.
    if not data:
        return [], []

    for row in data:
        if not isinstance(row, list):
            raise ValueError("each row must be a list")

    column_count = len(data[0])
    for row in data:
        if len(row) != column_count:
            raise ValueError("data must be rectangular")
        for value in row:
            if not _is_number(value):
                raise ValueError("all entries must be numbers")

    row_count = len(data)

    # The mean of an empty row is undefined.  This is a valid (zero-column)
    # rectangular table, so retain one result per row rather than rejecting it.
    averages = [
        float("nan") if column_count == 0 else fsum(row) / column_count
        for row in data
    ]

    if column_count == 0:
        return averages, []

    columns = list(zip(*data))

    column_means = [fsum(column) / row_count for column in columns]
    centered_columns = [
        [value - mean for value in column]
        for column, mean in zip(columns, column_means)
    ]
    squared_norms = [fsum(value * value for value in column)
                     for column in centered_columns]

    corr = [[0.0 for _ in range(column_count)]
            for _ in range(column_count)]

    for i in range(column_count):
        for j in range(i, column_count):
            denominator = sqrt(squared_norms[i] * squared_norms[j])
            if denominator == 0.0 or isnan(denominator):
                value = float("nan")
            else:
                numerator = fsum(
                    left * right
                    for left, right in zip(centered_columns[i],
                                           centered_columns[j])
                )
                value = numerator / denominator

            corr[i][j] = value
            corr[j][i] = value

    return averages, corr

