import math


def standardized_tensor_product(P, T):
    """Return the column-standardized flattened tensor product table.

    P has shape (m, k) and T has shape (k, n, p).  For each j, the
    m-by-p product P @ T[:, j, :] is flattened row by row to form row j
    of an n-row table.  Each table column is then standardized to zero
    mean and unit population variance.
    """
    # Validate P and determine its shape.
    if not isinstance(P, list) or not P:
        raise ValueError("P must be a non-empty matrix")
    if not isinstance(P[0], list) or not P[0]:
        raise ValueError("P must be a non-empty matrix")

    k = len(P[0])
    m = len(P)
    for row in P:
        if not isinstance(row, list) or len(row) != k:
            raise ValueError("P must be a rectangular non-empty matrix")

    # Validate T and determine its shape.
    if not isinstance(T, list) or not T:
        raise ValueError("T must be a non-empty tensor")
    if len(T) != k:
        raise ValueError("P's number of columns must match T's first dimension")

    if not isinstance(T[0], list) or not T[0]:
        raise ValueError("T must have a non-empty second dimension")
    n = len(T[0])
    if not isinstance(T[0][0], list) or not T[0][0]:
        raise ValueError("T must have a non-empty third dimension")
    p = len(T[0][0])

    for matrix in T:
        if not isinstance(matrix, list) or len(matrix) != n:
            raise ValueError("T must be a rectangular tensor")
        for vector in matrix:
            if not isinstance(vector, list) or len(vector) != p:
                raise ValueError("T must be a rectangular tensor")

    # Build one row per index j of T's second dimension.  Each row is
    # P @ T[:, j, :], flattened in row-major order.
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            for c in range(p):
                value = 0.0
                for l in range(k):
                    value += P[i][l] * T[l][j][c]
                row.append(float(value))
        table.append(row)

    # Standardize each column using population standard deviation.
    width = m * p
    constant_columns = [
        all(table[j][col] == table[0][col] for j in range(n))
        for col in range(width)
    ]

    means = [0.0] * width
    for j in range(n):
        for col in range(width):
            means[col] += table[j][col]
    for col in range(width):
        means[col] /= n

    squared_deviations = [0.0] * width
    for j in range(n):
        for col in range(width):
            difference = table[j][col] - means[col]
            squared_deviations[col] += difference * difference

    for col in range(width):
        if constant_columns[col] or squared_deviations[col] == 0.0:
            for j in range(n):
                table[j][col] = 0.0
        else:
            # Multiplying by the reciprocal population standard deviation
            # is equivalent to dividing by the standard deviation.
            inverse_stddev = math.sqrt(n / squared_deviations[col])
            for j in range(n):
                table[j][col] = (table[j][col] - means[col]) * inverse_stddev

    return table

