def quartiles_of_string_groups(groups):
    """Return the 25th, 50th, and 75th percentiles of all values.

    The inner string values are converted to integers, combined, and sorted.
    Percentiles use linear interpolation between closest ranks.
    """
    values = sorted(int(value) for group in groups for value in group)
    if not values:
        raise ValueError("quartiles_of_string_groups requires at least one value")

    def percentile(q):
        position = (len(values) - 1) * q
        lower = int(position)
        upper = min(lower + 1, len(values) - 1)
        fraction = position - lower
        return float(values[lower] + (values[upper] - values[lower]) * fraction)

    return (percentile(0.25), percentile(0.50), percentile(0.75))

