"""CSV column filling utilities."""

import csv
import io


def fill_missing_with_column_mean(csv_text):
    """Return CSV columns as lists, filling empty numeric cells with the mean.

    A column is treated as numeric only when it has at least one present value
    and every present value can be converted to a float.  Empty values in
    numeric columns are replaced with that column's mean; empty values in
    non-numeric columns become ``None``.  If a column has no present values,
    every entry in it is ``None``.
    """
    if csv_text is None or not str(csv_text).strip():
        return {}

    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)

    # Ignore completely blank physical lines produced by the CSV reader.
    rows = [row for row in rows if row]
    if not rows:
        return {}

    header = rows[0]
    data_rows = rows[1:]

    result = {}
    for column_index, column_name in enumerate(header):
        cells = [
            row[column_index] if column_index < len(row) else ""
            for row in data_rows
        ]

        # Whitespace-only cells are treated as missing, while meaningful
        # string content (including its surrounding whitespace) is preserved.
        present = [cell for cell in cells if cell.strip() != ""]

        if not present:
            result[column_name] = [None for _ in cells]
            continue

        try:
            numbers = [float(cell) for cell in present]
        except (TypeError, ValueError):
            result[column_name] = [
                None if cell.strip() == "" else cell for cell in cells
            ]
        else:
            mean = sum(numbers) / len(numbers)
            result[column_name] = [
                mean if cell.strip() == "" else float(cell) for cell in cells
            ]

    return result

