"""Utilities for computing Pearson correlation matrices."""

from decimal import Decimal, InvalidOperation, localcontext
from fractions import Fraction
from numbers import Integral, Number, Real


def _is_numeric_value(value):
    """Return True when *value* is a real number usable for correlation."""
    if isinstance(value, bool):
        return False
    if isinstance(value, complex):
        return False
    return isinstance(value, Number)


def _as_decimal(value):
    """Convert a numeric value to Decimal as exactly as reasonably possible."""
    if isinstance(value, Decimal):
        return value
    if isinstance(value, Fraction):
        return Decimal(value.numerator) / Decimal(value.denominator)
    if isinstance(value, Integral):
        return Decimal(int(value))
    if isinstance(value, Real):
        return Decimal.from_float(float(value))
    # Fall back for other numeric types, e.g. third-party scalar types.
    return Decimal(str(value))


def correlation_without_column(data, column):
    """Compute a Pearson correlation matrix, excluding one named column.

    ``data`` maps column names to equal-length lists of values.  The column
    named by ``column`` is omitted if present, and columns containing any
    non-real-number value are ignored.  The result is a dict of dicts in which
    ``result[x][y]`` is the Pearson correlation of columns ``x`` and ``y``.

    If no numeric columns remain, or if there are no observations, ``None`` is
    returned.  Correlations involving a constant column are undefined and are
    represented by ``float('nan')``.
    """
    if not data:
        return None

    numeric_columns = {}
    for name, values in data.items():
        if name == column:
            continue
        try:
            values_list = list(values)
        except TypeError:
            # Not an iterable collection; it cannot be a numeric column.
            continue
        if all(_is_numeric_value(value) for value in values_list):
            numeric_columns[name] = values_list

    if not numeric_columns:
        return None

    names = list(numeric_columns)
    observation_count = len(numeric_columns[names[0]])
    if observation_count == 0:
        return None

    # A high precision context makes the final conversion to float as accurate
    # as possible, avoiding avoidable cancellation/rounding differences.
    with localcontext() as context:
        context.prec = 50
        # Non-finite inputs have undefined correlations; let Decimal produce
        # NaN for them instead of raising InvalidOperation.
        context.traps[InvalidOperation] = False
        count = Decimal(observation_count)

        centered = {}
        sum_of_squares = {}
        for name in names:
            values = [_as_decimal(value) for value in numeric_columns[name]]
            mean = sum(values, Decimal(0)) / count
            deviations = [value - mean for value in values]
            centered[name] = deviations
            sum_of_squares[name] = sum(
                (value * value for value in deviations), Decimal(0)
            )

        result = {name: {} for name in names}
        for name in names:
            result[name][name] = 1.0

        for i, x in enumerate(names):
            for y in names[i + 1:]:
                sx = sum_of_squares[x]
                sy = sum_of_squares[y]
                if sx == 0 or sy == 0:
                    correlation = float("nan")
                else:
                    try:
                        numerator = sum(
                            (a * b for a, b in zip(centered[x], centered[y])),
                            Decimal(0),
                        )
                        correlation = float(numerator / (sx * sy).sqrt())
                    except (InvalidOperation, ZeroDivisionError):
                        correlation = float("nan")

                result[x][y] = correlation
                result[y][x] = correlation

    return result

