"""Column histogram utilities."""


def _is_number(value):
    """Return True for real numeric values, excluding booleans."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def column_histograms(table):
    """Compute 10-bin histograms for all numeric columns in *table*.

    A column is numeric when every one of its values is an int or float
    (booleans are not treated as numbers).  Bins have equal width and span
    the column's minimum through maximum; each bin is right-open except the
    last, which includes the maximum.

    Args:
        table: A non-empty dict mapping column names to equal-length lists.

    Returns:
        A dict mapping each numeric column name to a list of ten counts, in
        the same order as the columns in *table*.

    Raises:
        ValueError: If *table* is not a non-empty dict, or no numeric column
            exists.
    """
    if not isinstance(table, dict) or not table:
        raise ValueError("table must be a non-empty dict")

    result = {}
    for name, values in table.items():
        if not isinstance(values, (list, tuple)):
            continue
        if not values or not all(_is_number(value) for value in values):
            continue

        low = min(values)
        high = max(values)
        counts = [0] * 10

        if low == high:
            # All values are the maximum, so they belong in the final bin.
            counts[9] = len(values)
        else:
            width = (high - low) / 10.0
            for value in values:
                if value == high:
                    index = 9
                else:
                    index = int((value - low) / width)
                    # Guard against floating-point round-off at boundaries.
                    if index < 0:
                        index = 0
                    elif index > 9:
                        index = 9
                counts[index] += 1

        result[name] = counts

    if not result:
        raise ValueError("table has no numeric columns")

    return result

