"""TF-IDF scoring for articles whose titles contain question words."""

import math
import re
from collections import Counter


_WORD_RE = re.compile(r"\w{2,}")
_QUESTION_RE = re.compile(r"how|what", re.IGNORECASE)


def tfidf_scores_for_question_articles(titles, contents):
    """Return summed TF-IDF scores for bodies of question-titled articles.

    Articles are selected when their title contains ``how`` or ``what`` as a
    case-insensitive substring.  Words in the selected bodies are lowercased
    runs of at least two word characters.  Each selected body is represented
    by raw term counts multiplied by smoothed IDF, L2-normalized, and the
    resulting per-article scores are summed by word.
    """
    selected_bodies = [
        body
        for title, body in zip(titles, contents)
        if _QUESTION_RE.search(title)
    ]

    if not selected_bodies:
        return {}

    tokenized = [
        _WORD_RE.findall(body.lower())
        for body in selected_bodies
    ]
    term_counts = [Counter(tokens) for tokens in tokenized]

    vocabulary = sorted({word for tokens in tokenized for word in tokens})
    document_frequency = {
        word: sum(word in counts for counts in term_counts)
        for word in vocabulary
    }

    n_documents = len(selected_bodies)
    idf = {
        word: math.log((1 + n_documents) / (1 + df)) + 1
        for word, df in document_frequency.items()
    }

    totals = {word: 0.0 for word in vocabulary}

    for counts in term_counts:
        weighted = {
            word: count * idf[word]
            for word, count in counts.items()
        }
        norm = math.sqrt(sum(score * score for score in weighted.values()))
        if norm == 0.0:
            continue
        for word, score in weighted.items():
            totals[word] += score / norm

    return totals

