def grade_report(students, subjects, grades):
    """Return a grade summary by student and subject.

    Each student entry contains their grade in every subject plus an
    ``Average Grade`` value.  The final ``Average`` entry contains the mean
    grade for each subject and the mean of all students' average grades.
    """
    report = {}
    subject_totals = {subject: 0.0 for subject in subjects}
    total_student_average = 0.0

    for i, student in enumerate(students):
        student_report = {}
        student_total = 0.0

        for j, subject in enumerate(subjects):
            grade = float(grades[i][j])
            student_report[subject] = grade
            subject_totals[subject] += grade
            student_total += grade

        average_grade = student_total / len(subjects) if subjects else 0.0
        student_report["Average Grade"] = average_grade
        report[student] = student_report
        total_student_average += average_grade

    student_count = len(students)
    averages = {}
    for subject in subjects:
        averages[subject] = (
            subject_totals[subject] / student_count if student_count else 0.0
        )
    averages["Average Grade"] = (
        total_student_average / student_count if student_count else 0.0
    )
    report["Average"] = averages

    return report

