"""Ordinary least squares multiple linear regression.

The implementation is self-contained and uses only the Python standard
library.  Predictors are centered and normalized before solving the least
squares problem.  A one-sided Jacobi SVD is used for the small four-column
system, which gives good numerical behavior and also handles rank-deficient
predictor matrices.
"""

import math


def _dot(a, b):
    """Return the dot product of two equal-length sequences."""
    return math.fsum(x * y for x, y in zip(a, b))


def _clean_float(value):
    """Remove insignificant floating-point noise from a result.

    Values that are already within a few ulps of a simple decimal number
    are snapped to that representation.  This keeps exact-looking results
    exact without rounding values that genuinely require more precision.
    """
    value = float(value)
    nearest = round(value, 12)
    if abs(value - nearest) <= 1e-14 * max(1.0, abs(value)):
        return float(nearest)
    return value


def _jacobi_least_squares(a, y):
    """Solve min ||a x - y|| using a one-sided Jacobi SVD.

    ``a`` is an n-by-p list of rows, with p small (four in this task).
    Returns the minimum-norm least-squares coefficient vector.  The SVD is
    computed by repeatedly applying Jacobi rotations to pairs of columns of
    ``a`` until those columns are mutually orthogonal.
    """
    n = len(a)
    p = len(a[0]) if n else 0
    if p == 0:
        return []

    # Work on a copy, and accumulate the right singular vectors in v.
    work = [row[:] for row in a]
    v = [[1.0 if i == j else 0.0 for j in range(p)] for i in range(p)]

    # The columns are normalized before this routine is called, so a fixed
    # relative tolerance is appropriate for deciding when they are
    # orthogonal enough.  The sweep limit is just a safety bound.
    for _ in range(100):
        changed = False
        for i in range(p - 1):
            for j in range(i + 1, p):
                col_i = [work[k][i] for k in range(n)]
                col_j = [work[k][j] for k in range(n)]
                alpha = _dot(col_i, col_i)
                beta = _dot(col_j, col_j)
                if alpha == 0.0 or beta == 0.0:
                    continue
                gamma = _dot(col_i, col_j)
                if abs(gamma) <= 1e-15 * math.sqrt(alpha * beta):
                    continue

                changed = True
                # Rotation that makes the two columns orthogonal.
                zeta = (beta - alpha) / (2.0 * gamma)
                t = math.copysign(1.0, zeta) / (
