    # singular values squared, and v's columns are the right singular
    # vectors.  Apply the pseudoinverse to y.
    singular_sq = [
        math.fsum(work[k][i] * work[k][i] for k in range(n))
        for i in range(p)
    ]
    projected = [
        math.fsum(work[k][i] * y[k] for k in range(n))
        for i in range(p)
    ]

