    # tolerance on squared singular values.  It is deliberately tiny: it
    # removes only directions that are numerically rank-deficient, while
    # retaining genuinely small but informative directions.
    tolerance = 1e-24

    coefficients = [0.0] * p
    for i in range(p):
        if singular_sq[i] > tolerance:
            factor = projected[i] / singular_sq[i]
