"""TF-IDF calculation over text with square-bracket sections removed."""

import math
import re
from collections import Counter


_WORD_RE = re.compile(r"\w{2,}")


def _remove_bracketed_text(text):
    """Remove all square-bracketed sections, including nested sections."""
    result = []
    depth = 0
    for char in text:
        if char == "[":
            depth += 1
        elif char == "]" and depth:
            depth -= 1
        elif depth == 0:
            result.append(char)
    return "".join(result)


def bracket_free_tfidf(texts):
    """
    Return TF-IDF scores for words in each text, ignoring bracketed text.

    Words are lowercased runs of at least two letters, digits, or
    underscores. Raw term frequencies and smoothed inverse document
    frequencies are used, and each document's vector is normalized to unit
    Euclidean length.
    """
    tokenized = [
        _WORD_RE.findall(_remove_bracketed_text(text).lower())
        for text in texts
    ]

    n = len(texts)
    document_frequency = Counter()
    for words in tokenized:
        document_frequency.update(set(words))

    result = []
    for words in tokenized:
        counts = Counter(words)
        if not counts:
            result.append({})
            continue

        scores = {
            word: count * (math.log((1 + n) / (1 + document_frequency[word])) + 1)
            for word, count in counts.items()
        }
        norm = math.sqrt(sum(score * score for score in scores.values()))
        result.append({word: score / norm for word, score in scores.items()})

    return result

