"""Utilities for summarizing the weekdays of a collection of dates."""

from datetime import datetime

_WEEKDAYS = (
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
)

# Formats that can be parsed unambiguously by datetime.strptime.
_DATE_FORMATS = (
    "%Y-%m-%d",
    "%Y/%m/%d",
    "%Y.%m.%d",
    "%B %d, %Y",
    "%b %d, %Y",
    "%B %d %Y",
    "%b %d %Y",
    "%d %B %Y",
    "%d %b %Y",
    "%d %B, %Y",
    "%d %b, %Y",
    "%B %d, %y",
    "%b %d, %y",
    "%d %B %y",
    "%d %b %y",
)


def _parse_date(date_string):
    """Parse a date string using the common formats supported by the function."""
    if not isinstance(date_string, str):
        raise TypeError("date strings must be strings")

    # Tolerate extra whitespace, including around commas.
    text = " ".join(date_string.strip().replace(",", " , ").split())
    text = text.replace(" ,", ",").replace(", ", ", ")

    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            pass

    # Numeric formats with separators can be either year-first or
    # month/day-first.  Year-first forms are unambiguous.
    for sep in ("-", "/", "."):
        parts = text.split(sep)
        if len(parts) != 3 or not all(part.isdigit() for part in parts):
            continue

        first, second, third = (int(part) for part in parts)
        try:
            if len(parts[0]) == 4:
                return datetime(first, second, third).date()
            if len(parts[2]) == 4:
                # Prefer month/day/year for ambiguous values, but use
                # day/month/year when the first component cannot be a month.
                if first > 12 and second <= 12:
                    return datetime(third, second, first).date()
                return datetime(third, first, second).date()
        except ValueError:
            continue

    raise ValueError(f"unrecognized date format: {date_string!r}")


def weekday_distribution(date_strings):
    """Return counts of the dates in *date_strings* for each weekday.

    The result is a dict whose keys are ``Monday`` through ``Sunday`` in
    order, including weekdays with a count of zero.
    """
    distribution = {day: 0 for day in _WEEKDAYS}

    for date_string in date_strings:
        weekday = _parse_date(date_string).weekday()
        distribution[_WEEKDAYS[weekday]] += 1

    return distribution

