def course_grade_summary(records):
    """Summarize grades by course.

    Args:
        records: A list of (student, course, grade) tuples.

    Returns:
        A dict mapping each course to (average_grade, passing_count), where
        passing_count is the number of grades greater than or equal to 60.
    """
    totals = {}
    passing = {}
    counts = {}

    for _student, course, grade in records:
        totals[course] = totals.get(course, 0) + grade
        counts[course] = counts.get(course, 0) + 1
        if grade >= 60:
            passing[course] = passing.get(course, 0) + 1
        elif course not in passing:
            passing[course] = 0

    return {
        course: (totals[course] / counts[course], passing[course])
        for course in totals
    }

