"""Convert XML documents to nested Python dictionaries."""

from __future__ import annotations

import xml.etree.ElementTree as ET
from typing import Any


def _element_value(element: ET.Element) -> Any:
    """Return the dictionary/string/None representation of an XML element."""
    result: dict[str, Any] = {
        f"@{name}": value for name, value in element.attrib.items()
    }

    children: dict[str, Any] = {}
    text_parts: list[str] = []

    if element.text:
        text_parts.append(element.text)

    for child in element:
        value = _element_value(child)
        tag = child.tag

        if tag in children:
            existing = children[tag]
            if not isinstance(existing, list):
                children[tag] = [existing, value]
            else:
                existing.append(value)
        else:
            children[tag] = value

        if child.tail:
            text_parts.append(child.tail)

    # An element with neither attributes nor children is represented solely
    # by its text, or by None when it is empty.
    text = "".join(text_parts).strip()

    if not result and not children:
        return text if text else None

    result.update(children)
    if text:
        result["#text"] = text

    return result


def xml_to_dict(s: str) -> dict[str, Any]:
    """Parse *s* as XML and return a nested dictionary keyed by the root tag.

    Attributes are keyed with a leading ``@``.  Child elements are keyed by
    their tag (and become lists when siblings repeat), while text is stored
    under ``#text`` when the element also has attributes or children.

    Raises:
        ValueError: If *s* is empty or contains only whitespace.
    """
    if not isinstance(s, str):
        raise ValueError("XML input must be a non-empty string")
    if not s.strip():
        raise ValueError("XML input must not be empty or whitespace-only")

    try:
        root = ET.fromstring(s)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML: {exc}") from exc

    return {root.tag: _element_value(root)}

