"""Utilities for extracting email addresses from HTML text content."""

from html.parser import HTMLParser
import re


# Tags whose boundaries represent separations in rendered text.  Inline tags
# are deliberately not included: removing them should not split an address
# such as ``a@<b>b.com</b>``.
_BLOCK_TAGS = {
    "address", "article", "aside", "blockquote", "body", "br", "dd", "div",
    "dl", "dt", "fieldset", "figcaption", "figure", "footer", "form",
    "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr", "html",
    "li", "main", "nav", "ol", "p", "pre", "section", "table", "tbody",
    "td", "tfoot", "th", "thead", "title", "tr", "ul",
}

# Contents of these elements are not rendered page text.
_NON_TEXT_TAGS = {"script", "style"}


class _TextExtractor(HTMLParser):
    """Collect rendered text from an HTML document, excluding markup."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._parts = []
        self._ignored_depth = 0

    def _separate(self):
        self._parts.append("\n")

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in _NON_TEXT_TAGS:
            self._ignored_depth += 1
            return
        if self._ignored_depth == 0 and tag in _BLOCK_TAGS:
            self._separate()

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in _NON_TEXT_TAGS:
            if self._ignored_depth:
                self._ignored_depth -= 1
            return
        if self._ignored_depth == 0 and tag in _BLOCK_TAGS:
            self._separate()

    def handle_data(self, data):
        if self._ignored_depth == 0:
            self._parts.append(data)

    def get_text(self):
        return "".join(self._parts)


def extract_emails_from_html(
    html,
    pattern=r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,7}\b',
):
    """Return email-like matches from the text content of *html*.

    Tags, comments, and other markup are excluded from the text; character
    references (for example ``&#64;``) are decoded.  Matches are returned in
    document order, with duplicates preserved.
    """
    parser = _TextExtractor()
    parser.feed(html)
    parser.close()
    text = parser.get_text()
    return [match.group(0) for match in re.finditer(pattern, text)]

