"""Utilities for concatenating CSV documents."""

import csv
import io
import re


_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(
    r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
)


def _number_if_numeric(value):
    """Return an int/float for a numeric string, otherwise return None."""
    if _INT_RE.fullmatch(value):
        return int(value)
    if _FLOAT_RE.fullmatch(value):
        return float(value)
    return None


def concat_csv_tables(csv_texts):
    """Concatenate the data rows from a list of CSV documents.

    Each document must have a header row and the same set of columns.  The
    returned dictionaries follow the column order of the first document.
    A column is converted to int/float only when every value in that column
    across all concatenated rows is numeric; otherwise all its values remain
    strings.
    """
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    headers = None
    rows = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text, newline=""))
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError("CSV document is empty") from None

        if headers is None:
            headers = header
            order = list(range(len(header)))
        else:
            if (len(header) != len(headers)
                    or set(header) != set(headers)):
                raise ValueError(
                    "all CSV documents must have the same columns"
                )
            index_by_name = {name: index for index, name in enumerate(header)}
            order = [index_by_name[name] for name in headers]

        for row in reader:
            # Ignore completely blank trailing lines.
            if not row:
                continue
            if len(row) != len(header):
                raise ValueError("CSV row has the wrong number of fields")
            rows.append([row[index] for index in order])

    # A column is numeric only if it has data and every value is numeric.
    numeric_columns = [
        bool(rows) and all(_number_if_numeric(row[index]) is not None
                           for row in rows)
        for index in range(len(headers))
    ]

    result = []
    for row in rows:
        result.append({
            name: (_number_if_numeric(row[index])
                   if numeric_columns[index] else row[index])
            for index, name in enumerate(headers)
        })
    return result

