"""Utilities for summarizing numeric CSV columns."""

import csv
import io
import statistics


def column_summary_stats(csv_text, column_name):
    """Return mean, median, and population standard deviation for a CSV column.

    Args:
        csv_text: The complete CSV contents, including a header row.
        column_name: The name of the column to summarize.

    Raises:
        ValueError: If the column is not present in the header.
    """
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {column_name!r} not found in CSV header")

    # Be tolerant of a UTF-8 BOM at the start of the file.
    if header:
        header[0] = header[0].lstrip("\ufeff")

    try:
        column_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column {column_name!r} not found in CSV header") from None

    values = []
    for row in reader:
        if column_index >= len(row):
            continue
        cell = row[column_index].strip()
        if cell == "":
            continue
        values.append(float(cell))

    if not values:
        raise ValueError(f"Column {column_name!r} contains no numeric values")

    return {
        "mean": float(statistics.mean(values)),
        "median": float(statistics.median(values)),
        "std_dev": float(statistics.pstdev(values)),
    }

