"""Utilities for correlating numeric scores with grade labels."""

from math import isfinite, sqrt


def score_grade_correlation(scores, grades):
    """Return the Pearson correlation between scores and encoded grades.

    Grade labels are encoded by their zero-based position among the sorted
    distinct labels.  ``None`` is returned when there are fewer than two
    entries.  Invalid inputs raise :class:`ValueError`.
    """
    if len(scores) != len(grades):
        raise ValueError("scores and grades must have the same length")

    numeric_scores = []
    for score in scores:
        try:
            value = float(score)
        except (TypeError, ValueError):
            raise ValueError(f"invalid score: {score!r}") from None
        if not isfinite(value):
            raise ValueError(f"invalid score: {score!r}")
        numeric_scores.append(value)

    if len(numeric_scores) < 2:
        return None

    # Sorting the distinct labels gives each grade a stable numeric encoding.
    label_to_rank = {
        label: rank for rank, label in enumerate(sorted(set(grades)))
    }
    encoded_grades = [label_to_rank[grade] for grade in grades]

    count = len(numeric_scores)
    mean_score = sum(numeric_scores) / count
    mean_grade = sum(encoded_grades) / count

    covariance = sum(
        (score - mean_score) * (grade - mean_grade)
        for score, grade in zip(numeric_scores, encoded_grades)
    )
    score_variance = sum((score - mean_score) ** 2 for score in numeric_scores)
    grade_variance = sum(
        (grade - mean_grade) ** 2 for grade in encoded_grades
    )

    denominator = sqrt(score_variance) * sqrt(grade_variance)
    if denominator == 0:
        # Pearson correlation is undefined when either input is constant.
        # Returning 0.0 keeps the function's return type a float in this case.
        return 0.0

    correlation = covariance / denominator
    # Correct tiny floating-point excursions from the mathematical range.
    if correlation > 1.0:
        return 1.0
    if correlation < -1.0:
        return -1.0
    if abs(correlation - 1.0) <= 1e-12:
        return 1.0
    if abs(correlation + 1.0) <= 1e-12:
        return -1.0
    return correlation

