import math
import statistics


def csv_mean_median(csv_text):
    """Return the mean and median of numeric values in a one-column CSV.

    The first non-blank row is treated as a header and skipped. Blank rows and
    cells that cannot be converted to a finite float are ignored. If there are
    no numeric values, ``(None, None)`` is returned.
    """
    if not csv_text or not csv_text.strip():
        return (None, None)

    values = []
    reader = csv.reader(io.StringIO(csv_text))
    header_skipped = False

    for row in reader:
        # Ignore blank records (including whitespace-only lines).
        if not row or all(not cell.strip() for cell in row):
            continue

        # The first non-blank record is the header.
        if not header_skipped:
            header_skipped = True
            continue

        cell = row[0].strip()
        if not cell:
            continue

        try:
            value = float(cell)
        except ValueError:
