"""Extract Python dictionary literals from HTML ``<script>`` bodies."""

import ast
from html.parser import HTMLParser


class _ScriptDictExtractor(HTMLParser):
    """Collect the contents of script elements and try to evaluate them."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._in_script = False
        self._script_chunks = []
        self.dicts = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._in_script = True
            self._script_chunks = []

    def handle_data(self, data):
        if self._in_script:
            self._script_chunks.append(data)

    def handle_endtag(self, tag):
        if tag.lower() != "script" or not self._in_script:
            return

        source = "".join(self._script_chunks).strip()
        self._in_script = False
        self._script_chunks = []

        try:
            value = ast.literal_eval(source)
        except Exception:
            # Anything that is not a valid Python literal is ignored.
            return

        if isinstance(value, dict):
            self.dicts.append(value)


def extract_script_dicts(html):
    """Return dict literals found in ``<script>`` elements, in document order.

    Script bodies that are not valid Python dictionary literals are skipped.
    """
    parser = _ScriptDictExtractor()
    parser.feed(html)
    parser.close()
    return parser.dicts

