def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    # Be tolerant of a UTF-8 byte-order mark at the start of the text.
    if csv_text.startswith("\ufeff"):
        csv_text = csv_text[1:]

    reader = csv.reader(io.StringIO(csv_text))
    header = next(reader, None)
    if header is None:
        raise ValueError("CSV text must contain a header row")

    normalized_header = [column.strip() for column in header]
    required = ("Customer", "Category", "Sales")
    missing = [column for column in required if column not in normalized_header]
    if missing:
        raise ValueError("Missing required column(s): " + ", ".join(missing))

    customer_index = normalized_header.index("Customer")
    category_index = normalized_header.index("Category")
    sales_index = normalized_header.index("Sales")

    seen_customers = set()
    total_sales = 0
    categories = []

    for row in reader:
        # Ignore completely blank lines.
        if not row:
            continue

        customer = row[customer_index] if customer_index < len(row) else ""
        if customer in seen_customers:
            continue
        seen_customers.add(customer)

        category = row[category_index] if category_index < len(row) else ""
        sales_value = row[sales_index] if sales_index < len(row) else ""
        total_sales += _parse_sales(sales_value)
        categories.append(category)

    if categories:
        category_counts = Counter(categories)
        most_popular = min(
            category_counts,
            key=lambda category: (-category_counts[category], category),
        )
    else:
        most_popular = None

    return {
        "Total Sales": total_sales,
        "Most Popular Category": most_popular,
    }

