import math


def fit_age_score_regression(records):
    """Fit an ordinary least-squares line predicting Score from Age.

    Only the first record for each name is used.  Returns
    ``(slope, intercept, r)`` where ``r`` is the Pearson correlation
    coefficient between Age and Score.

    For degenerate inputs (no data, or no variation in Age), the slope is
    zero and ``r`` is reported as 0.0.
    """
    seen = set()
    ages = []
    scores = []

    for record in records:
        name = record["Name"]
        if name in seen:
            continue
        seen.add(name)
        ages.append(float(record["Age"]))
        scores.append(float(record["Score"]))

    n = len(ages)
    if n == 0:
        return (0.0, 0.0, 0.0)

    mean_age = sum(ages) / n
    mean_score = sum(scores) / n

    if n == 1:
        return (0.0, mean_score, 0.0)

    covariance = sum(
        (age - mean_age) * (score - mean_score)
        for age, score in zip(ages, scores)
    )
    age_variance = sum((age - mean_age) ** 2 for age in ages)
    score_variance = sum((score - mean_score) ** 2 for score in scores)

    # A vertical or horizontal best-fit line has no finite correlation.
    if age_variance == 0.0:
        return (0.0, mean_score, 0.0)

    slope = covariance / age_variance
    intercept = mean_score - slope * mean_age

    if score_variance == 0.0:
        r = 0.0
    else:
        r = covariance / math.sqrt(age_variance * score_variance)

    return (slope, intercept, r)

