def _percentile(sorted_values, q):
    """Return the q-th percentile using linear interpolation."""
    position = (len(sorted_values) - 1) * q
    lower = int(position)
    upper = lower + 1
    if upper >= len(sorted_values):
        return float(sorted_values[lower])
    fraction = position - lower
    return float(
        sorted_values[lower]
        + (sorted_values[upper] - sorted_values[lower]) * fraction
    )


def country_score_summary(records):
    """Summarize first-occurrence scores by country.

    Each country maps to [min, first quartile, median, third quartile, max].
    """
    if not records:
        raise ValueError("records must not be empty")

    required_keys = ("Name", "Country", "Score")
    seen_names = set()
    country_scores = {}

    for record in records:
        if not isinstance(record, dict) or any(
            key not in record for key in required_keys
        ):
            raise ValueError("each record must contain Name, Country and Score")

        name = record["Name"]
        if name in seen_names:
            continue
        seen_names.add(name)

        country = record["Country"]
        country_scores.setdefault(country, []).append(record["Score"])

    result = {}
    for country, scores in country_scores.items():
        ordered = sorted(scores)
        result[country] = [
            float(ordered[0]),
            _percentile(ordered, 0.25),
            _percentile(ordered, 0.5),
            _percentile(ordered, 0.75),
            float(ordered[-1]),
        ]

    return result

