"""Utilities for working with column-oriented tables."""

from math import fsum
from numbers import Number


def column_covariance(columns):
    """Return the sample covariance matrix of a column-oriented table.

    ``columns`` maps column names to equal-length sequences of numeric
    values.  The returned value is a nested dictionary where
    ``result[a][b]`` is the covariance between columns ``a`` and ``b``,
    using the sample normalization ``n - 1``.

    A :class:`ValueError` is raised for an empty table (including a table
    whose columns have no rows) or for columns of differing lengths.  A
    :class:`TypeError` is raised if a column contains a non-numeric or
    complex value.
    """
    if not columns:
        raise ValueError("the table must contain at least one column")

    names = list(columns)
    raw_columns = [columns[name] for name in names]
    row_count = len(raw_columns[0])

    if row_count == 0:
        raise ValueError("the table must contain at least one row")
    if row_count < 2:
        raise ValueError("at least two rows are required for sample covariance")

    if any(len(values) != row_count for values in raw_columns):
        raise ValueError("all columns must have the same length")

    # Validate all values before doing arithmetic.  Converting to float also
    # gives a consistent numeric result for ints, fractions, decimals, and
    # similar real-valued numeric types.
    data = []
    for name, values in zip(names, raw_columns):
        converted = []
        for value in values:
            if not isinstance(value, Number) or isinstance(value, complex):
                raise TypeError(
                    "column {!r} contains a non-numeric value: {!r}".format(
                        name, value
                    )
                )
            converted.append(float(value))
        data.append(converted)

    means = [fsum(values) / row_count for values in data]

    result = {}
    for i, a in enumerate(names):
        result[a] = {}
        for j, b in enumerate(names):
            total = fsum(
                (x - means[i]) * (y - means[j])
                for x, y in zip(data[i], data[j])
            )
            result[a][b] = total / (row_count - 1)

    return result

