"""K-means point clustering utilities."""

from __future__ import annotations

from math import isfinite
from numbers import Integral
from typing import List, Sequence, Tuple


def _squared_distance(a: Sequence[float], b: Sequence[float]) -> float:
    """Return the squared Euclidean distance between two points."""
    return sum((x - y) * (x - y) for x, y in zip(a, b))


def _initial_indices(
    data: List[Tuple[float, ...]], n_clusters: int, first: int
) -> List[int]:
    """Choose initial centroid indices with deterministic farthest-first search."""
    chosen = [first]
    selected = {first}

    while len(chosen) < n_clusters:
        best_index = None
        best_distance = -1.0
        for index, point in enumerate(data):
            if index in selected:
                continue
            nearest = min(
                _squared_distance(point, data[centroid]) for centroid in chosen
            )
            if nearest > best_distance:
                best_distance = nearest
                best_index = index

        # If all remaining points coincide with an existing centroid, still
        # select a distinct point index.  This lets duplicate-heavy data be
        # split into the requested number of non-empty clusters.
        if best_index is None:
            best_index = next(
                index for index in range(len(data)) if index not in selected
            )
        chosen.append(best_index)
        selected.add(best_index)

    return chosen


def _run_kmeans(
    data: List[Tuple[float, ...]], n_clusters: int, first: int
) -> Tuple[List[int], float, Tuple[int, ...]]:
    """Run k-means from one deterministic initialization.

    Returns labels, within-cluster squared error, and a canonical partition
    signature used as a deterministic tie-breaker between equal-quality runs.
    """
    dimension = len(data[0])
    initial = _initial_indices(data, n_clusters, first)
    centroids = [data[index] for index in initial]

    labels: List[int] = []
    for _ in range(300):
        # Assign each point to its closest centroid (lower index wins ties).
        new_labels: List[int] = []
        for point in data:
            best_cluster = 0
            best_dist = _squared_distance(point, centroids[0])
            for cluster_index in range(1, n_clusters):
                dist = _squared_distance(point, centroids[cluster_index])
                if dist < best_dist:
                    best_dist = dist
                    best_cluster = cluster_index
            new_labels.append(best_cluster)

        # Keep exactly n_clusters non-empty groups when possible by moving the
        # farthest point from a donor cluster into each empty cluster.
        counts = [0] * n_clusters
        for label in new_labels:
            counts[label] += 1

        for empty_cluster in range(n_clusters):
            if counts[empty_cluster] != 0:
                continue
            donor = max(range(n_clusters), key=lambda c: (counts[c], -c))
            if counts[donor] <= 1:
                break

            donor_points = [
                index
                for index, label in enumerate(new_labels)
                if label == donor
            ]
            moving_point = max(
                donor_points,
                key=lambda index: (
                    _squared_distance(data[index], centroids[donor]),
                    -index,
                ),
            )
            new_labels[moving_point] = empty_cluster
            counts[donor] -= 1
            counts[empty_cluster] += 1

        # Recompute centroids from the repaired assignments.
        new_centroids: List[Tuple[float, ...]] = []
        for cluster_index in range(n_clusters):
            members = [
                data[index]
                for index, label in enumerate(new_labels)
                if label == cluster_index
            ]
            if members:
                new_centroids.append(
                    tuple(
                        sum(point[dim] for point in members) / len(members)
                        for dim in range(dimension)
                    )
                )
            else:
                # This should not occur after repair, but retaining the old
                # centroid keeps the algorithm well-defined if it does.
                new_centroids.append(centroids[cluster_index])

        if new_labels == labels:
            centroids = new_centroids
            break

