"""Utilities for extracting and resolving hyperlinks from HTML."""

from html.parser import HTMLParser
from urllib.parse import urljoin


class _AnchorHrefParser(HTMLParser):
    """Collect the raw href values from every ``<a>`` start tag."""

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.hrefs: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag.lower() != "a":
            return
        for name, value in attrs:
            if name.lower() == "href":
                # A valueless attribute is an empty string in HTML.
                self.hrefs.append(value if value is not None else "")
                # An HTML element should not have duplicate attributes, but
                # stopping at the first one keeps the behavior deterministic.
                break


def extract_absolute_links(html: str, base_url: str) -> list[str]:
    """Return sorted, unique absolute links from ``<a href="...">`` tags.

    Relative references are resolved against ``base_url`` using standard URL
    joining rules.  Tags without an href are ignored.
    """
    parser = _AnchorHrefParser()
    parser.feed(html)
    parser.close()

    links = {urljoin(base_url, href.strip()) for href in parser.hrefs}
    return sorted(links)

