"""Utilities for sorting CSV data."""

import csv
import io


def _convert_numeric(value):
    """Return an int/float for a numeric string, or None if not numeric."""
    if isinstance(value, (int, float)):
        return value
    if value is None:
        return None

    text = value.strip()
    if not text:
        return None

    # Prefer int so that values such as "9" are returned as integers.
    try:
        return int(text)
    except ValueError:
        pass

    try:
        return float(text)
    except ValueError:
        return None


def sort_csv_rows(csv_text, sort_key):
    """Sort CSV data rows by *sort_key* and return them as dictionaries.

    A column is converted to numbers only when every value in that column is
    numeric. The sort is stable, so rows with equal keys retain their input
    order. A ``ValueError`` is raised when *sort_key* is not a header column.
    """
    stream = io.StringIO(csv_text, newline="")
    reader = csv.reader(stream)

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {sort_key!r} does not exist") from None

    # Be tolerant of a UTF-8 BOM at the start of the file.
    if header and header[0].startswith("\ufeff"):
        header[0] = header[0][1:]

    if sort_key not in header:
        raise ValueError(f"Column {sort_key!r} does not exist")

    width = len(header)
    rows = []
    for fields in reader:
        # csv.reader yields an empty list for a blank line; DictReader-style
        # behavior is to skip such rows.
        if not fields:
            continue
        if len(fields) < width:
            fields = fields + [""] * (width - len(fields))
        rows.append(dict(zip(header, fields[:width])))

    # Convert each column independently, and only if all of its values are
    # numeric. Missing values are represented as empty strings and therefore
    # prevent a column from being treated as numeric.
    seen_columns = set()
    for column in header:
        if column in seen_columns:
            continue
        seen_columns.add(column)
        converted = []
        for row in rows:
            number = _convert_numeric(row[column])
            if number is None:
                break
            converted.append(number)
        else:
            for row, number in zip(rows, converted):
                row[column] = number

    return sorted(rows, key=lambda row: row[sort_key])

