"""Utilities for computing Pearson correlation matrices from JSON data."""

import json
import math
from typing import Any


def _is_numeric(value: Any) -> bool:
    """Return True for JSON numbers (but not booleans or non-finite values)."""
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and (not isinstance(value, float) or math.isfinite(value))
    )


def _pearson(xs: list[float], ys: list[float]) -> float:
    """Compute the Pearson correlation coefficient for two equal-length lists."""
    n = len(xs)
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n

    covariance = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    variance_x = sum((x - mean_x) ** 2 for x in xs)
    variance_y = sum((y - mean_y) ** 2 for y in ys)

    denominator = math.sqrt(variance_x * variance_y)
    if denominator == 0.0:
        # The coefficient is undefined when either column is constant.
        # Use 0.0 for off-diagonal entries to keep the result usable and
        # JSON-serializable; diagonal entries are set to 1.0 by the caller.
        return 0.0

    # Guard against tiny floating-point overshoots outside [-1, 1].
    return max(-1.0, min(1.0, covariance / denominator))


def numeric_correlation_from_json(json_text: str) -> dict[str, dict[str, float]]:
    """Return the Pearson correlation matrix for numeric columns in *json_text*.

    Parameters
    ----------
    json_text:
        A JSON string representing an object whose keys are column names and
        whose values are equal-length lists.

    Returns
    -------
    dict[str, dict[str, float]]
        A square mapping of numeric column names to their pairwise Pearson
        correlation coefficients.

    Raises
    ------
    ValueError
        If the input is not valid JSON, is not a JSON object, contains no data,
        or has malformed column data.
    """
    def reject_nonstandard_constant(constant: str) -> None:
        raise ValueError(f"Invalid JSON constant: {constant}")

    try:
        data = json.loads(json_text, parse_constant=reject_nonstandard_constant)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON input") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON input must be an object mapping column names to lists")
    if not data:
        raise ValueError("Data is empty")

    # Validate the shape of the input and collect numeric columns.
    numeric_columns: dict[str, list[float]] = {}
    row_count: int | None = None

    for column_name, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"Column {column_name!r} must contain a list")

        if row_count is None:
            row_count = len(values)
        elif len(values) != row_count:
            raise ValueError("All columns must have the same length")

        if all(_is_numeric(value) for value in values):
            numeric_columns[column_name] = [float(value) for value in values]

    if row_count == 0:
        raise ValueError("Data is empty")

    result: dict[str, dict[str, float]] = {}
    column_names = list(numeric_columns)

    for name_x in column_names:
        result[name_x] = {}
        for name_y in column_names:
            if name_x == name_y:
                result[name_x][name_y] = 1.0
            else:
                result[name_x][name_y] = round(
                    _pearson(numeric_columns[name_x], numeric_columns[name_y]), 15
                )

    return result

