def classification_summary(y_true, y_pred):
    """Return per-label and aggregate classification metrics.

    Each label is represented by ``(precision, recall, f1, support)``.
    Undefined metrics are reported as ``0.0``. The aggregate entries are
    ``'macro avg'`` and ``'weighted avg'``; overall accuracy is stored under
    ``'accuracy'``.
    """
    if len(y_true) != len(y_pred):
        raise ValueError("y_true and y_pred must have the same length")

    total_count = len(y_true)

    # Preserve first-appearance order while finding every label in either list.
    labels = []
    seen = set()
    for label in list(y_true) + list(y_pred):
        if label not in seen:
            seen.add(label)
            labels.append(label)

    true_counts = {label: 0 for label in labels}
    pred_counts = {label: 0 for label in labels}
    correct_counts = {label: 0 for label in labels}

    correct = 0
    for true_label, pred_label in zip(y_true, y_pred):
        true_counts[true_label] += 1
        pred_counts[pred_label] += 1
        if true_label == pred_label:
            correct_counts[true_label] += 1
            correct += 1

    # Keep exact fractions so aggregate calculations do not accumulate
    # floating-point error before the final conversion to float.
    exact_metrics = {}
    for label in labels:
        tp = correct_counts[label]
        true_count = true_counts[label]
        pred_count = pred_counts[label]

        precision = Fraction(tp, pred_count) if pred_count else Fraction(0, 1)
        recall = Fraction(tp, true_count) if true_count else Fraction(0, 1)
        f1 = (
            Fraction(2 * tp, pred_count + true_count)
            if pred_count and true_count
            else Fraction(0, 1)
        )
        exact_metrics[label] = (precision, recall, f1, true_count)

    def reported(value):
        """Convert an exact metric to the report's rounded float form."""
        return round(float(value), 16)

    per_label = {
        label: (
            reported(precision),
            reported(recall),
            reported(f1),
            support,
        )
        for label, (precision, recall, f1, support) in exact_metrics.items()
    }

    label_count = len(labels)
    if label_count:
        macro_precision = sum(
            metrics[0] for metrics in exact_metrics.values()
        ) / label_count
        macro_recall = sum(
            metrics[1] for metrics in exact_metrics.values()
        ) / label_count
        macro_f1 = sum(
            metrics[2] for metrics in exact_metrics.values()
        ) / label_count
    else:
        macro_precision = macro_recall = macro_f1 = Fraction(0, 1)

    if total_count:
        weighted_precision = sum(
            metrics[0] * metrics[3] for metrics in exact_metrics.values()
        ) / total_count
        weighted_recall = sum(
            metrics[1] * metrics[3] for metrics in exact_metrics.values()
        ) / total_count
        weighted_f1 = sum(
            metrics[2] * metrics[3] for metrics in exact_metrics.values()
        ) / total_count
    else:
        weighted_precision = weighted_recall = weighted_f1 = Fraction(0, 1)

    report = dict(per_label)
    report["accuracy"] = (
        reported(Fraction(correct, total_count)) if total_count else 0.0
    )
    report["macro avg"] = (
        reported(macro_precision),
        reported(macro_recall),
        reported(macro_f1),
        total_count,
    )
    report["weighted avg"] = (
        reported(weighted_precision),
        reported(weighted_recall),
        reported(weighted_f1),
        total_count,
    )
    return report

