"""Utilities for computing pairwise Euclidean distances between rows."""

import math


def row_distance_matrix(rows):
    """Return the pairwise Euclidean distance matrix for ``rows``.

    Every element of every row must be an ``int`` or ``float``.  A
    ``TypeError`` is raised before any distance calculation if that is not
    the case.
    """
    for row in rows:
        for value in row:
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise TypeError("all row elements must be int or float")

    distances = []
    for i, first_row in enumerate(rows):
        distance_row = []
        for j, second_row in enumerate(rows):
            if i == j:
                distance_row.append(0.0)
            else:
                squared_difference = sum(
                    (first - second) ** 2
                    for first, second in zip(first_row, second_row)
                )
                distance_row.append(math.sqrt(squared_difference))
        distances.append(distance_row)

    return distances

