import csv
import io
import math


def csv_cube_roots(csv_text, columns):
    """Parse CSV text and return all values plus cube roots of selected columns.

    Args:
        csv_text: CSV content including a header row.
        columns: Iterable of column names whose cube roots should be computed.

    Returns:
        A tuple ``(all_columns, cube_roots)``. ``all_columns`` maps every CSV
        column name to its values as floats. ``cube_roots`` maps each requested
        column name to the cube roots of its values.
    """
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        header = []

    all_columns = {name: [] for name in header}

    for row in reader:
        # Ignore completely blank lines, which commonly appear in CSV text.
        if not row:
            continue
        if len(row) != len(header):
            raise ValueError("CSV row has a different number of fields than the header")
        for name, value in zip(header, row):
            try:
                all_columns[name].append(float(value))
            except (TypeError, ValueError) as exc:
                raise ValueError(f"non-numeric value {value!r} in column {name!r}") from exc

    result = {}
    for column in columns:
        if column not in all_columns:
            raise KeyError(column)
        result[column] = [math.cbrt(value) for value in all_columns[column]]

    return all_columns, result

