"""CSV Pearson correlation matrix utilities."""

import csv
import io
from decimal import Decimal, localcontext


def correlation_matrix_from_csv(csv_text):
    """Return the pairwise Pearson correlation matrix of numeric CSV columns.

    The first row of ``csv_text`` is treated as a header.  The returned value
    is a dictionary of dictionaries, keyed by column name, where entry
    ``result[a][b]`` is the Pearson correlation between columns ``a`` and
    ``b``.

    For a column with zero variance, Pearson correlation is mathematically
    undefined.  Such off-diagonal pairs are reported as 0.0; diagonal entries
    are always 1.0.
    """
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")

    # Remove a UTF-8 byte-order mark if present.
    if csv_text.startswith("\ufeff"):
        csv_text = csv_text[1:]

    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if any(cell.strip() for cell in row)]
    if not rows:
        return {}

    header = rows[0]
    column_count = len(header)

    # Decimal gives enough precision to avoid avoidable rounding errors in
    # the intermediate sums, while the public result remains ordinary floats.
    with localcontext() as context:
        context.prec = 50
        columns = [[] for _ in range(column_count)]

        for line_number, row in enumerate(rows[1:], start=2):
            if len(row) != column_count:
                raise ValueError(
                    "row {} has {} fields; expected {}".format(
                        line_number, len(row), column_count
                    )
                )
            for column_index, cell in enumerate(row):
                columns[column_index].append(Decimal(cell.strip()))

        if not rows[1:]:
            return {name: {} for name in header}

        row_count = len(rows) - 1
        means = [sum(column) / Decimal(row_count) for column in columns]
        centered = [
            [value - means[index] for value in column]
            for index, column in enumerate(columns)
        ]
        sum_squares = [
            sum(value * value for value in column) for column in centered
        ]

        result = {name: {} for name in header}
        for i, name_i in enumerate(header):
            result[name_i][name_i] = 1.0
            for j in range(i + 1, column_count):
                denominator = (sum_squares[i] * sum_squares[j]).sqrt()
                if denominator == 0:
                    correlation = 0.0
                else:
                    numerator = sum(
                        x * y for x, y in zip(centered[i], centered[j])
                    )
                    correlation = float(numerator / denominator)
                    # Guard against tiny overshoots from finite precision.
                    correlation = max(-1.0, min(1.0, correlation))
                result[name_i][header[j]] = correlation
                result[header[j]][name_i] = correlation

        return result

