                best_distance = distance
                best_index = i
        centers.append(list(points[best_index]))
    return centers


def _kmeans_plus_plus_initialization(
    points: Sequence[Sequence[float]], k: int, rng: random.Random, first_fixed: bool
) -> List[List[float]]:
    if first_fixed:
        first_index = 0
    else:
        first_index = rng.randrange(len(points))
    centers = [list(points[first_index])]

    while len(centers) < k:
        distances = []
        total = 0.0
        for point in points:
            d2 = min(_squared_distance(point, center) for center in centers)
            distances.append(d2)
            total += d2

        if total <= 0.0:
            # All remaining points coincide with an existing center.  Choose an
            # as-yet unused point if one exists, otherwise stop.
            used = {tuple(center) for center in centers}
            for point in points:
                if tuple(point) not in used:
                    centers.append(list(point))
                    break
            else:
                break
            continue

        target = rng.random() * total
        cumulative = 0.0
        chosen = len(points) - 1
        for i, d2 in enumerate(distances):
            cumulative += d2
            if cumulative >= target:
                chosen = i
                break
        centers.append(list(points[chosen]))

    return centers


def _run_lloyd(
    points: Sequence[Sequence[float]],
    initial_centers: Sequence[Sequence[float]],
    max_iterations: int = 300,
) -> Tuple[List[int], float]:
    """Run Lloyd's algorithm and return (labels, within-cluster SSE)."""
    k = len(initial_centers)
    dimensions = len(points[0])
    centers = [list(center) for center in initial_centers]
    labels: List[int] | None = None

    for _ in range(max_iterations):
        new_labels = [_nearest_label(point, centers) for point in points]

        sums = [[0.0] * dimensions for _ in range(k)]
        counts = [0] * k
        for point, label in zip(points, new_labels):
            counts[label] += 1
            center_sum = sums[label]
            for j, value in enumerate(point):
                center_sum[j] += value

        # Handle any empty cluster.  Move it to the point currently worst
        # represented by its assigned center; this preserves k non-empty
        # clusters whenever there are at least k distinct points.
        for cluster_index in range(k):
            if counts[cluster_index] == 0:
                worst_index = 0
                worst_distance = -1.0
                for i, point in enumerate(points):
                    distance = _squared_distance(point, centers[new_labels[i]])
                    if distance > worst_distance:
                        worst_distance = distance
                        worst_index = i
                centers[cluster_index] = list(points[worst_index])
            else:
                centers[cluster_index] = [
                    value / counts[cluster_index] for value in sums[cluster_index]
                ]

        if labels is not None and new_labels == labels:
            labels = new_labels
            break
        labels = new_labels

    if labels is None:  # pragma: no cover - defensive; there is always >= 1 point
        labels = [_nearest_label(point, centers) for point in points]

    inertia = sum(
        _squared_distance(point, centers[label])
        for point, label in zip(points, labels)
    )
    return labels, inertia


def _canonicalize(labels: Sequence[int]) -> List[int]:
    """Rename clusters in order of first appearance."""
    mapping: dict[int, int] = {}
    result: List[int] = []
    for label in labels:
        if label not in mapping:
            mapping[label] = len(mapping)
        result.append(mapping[label])
    return result


def cluster_labels(rows: Sequence[Sequence[float]]) -> List[int]:
    """Standardize columns, cluster rows into three k-means clusters, and
    return canonical integer labels (clusters numbered by first appearance).
    """
    points = [[float(value) for value in row] for row in rows]
    n = len(points)
    if n == 0:
        return []

    dimensions = len(points[0])
    if any(len(point) != dimensions for point in points):
        raise ValueError("all rows must have the same number of columns")

    if dimensions == 0:
        return [0] * n

    # Standardize each column using the population standard deviation.  A
    # constant column has no variance; subtracting its mean turns it into 0.
    for column in range(dimensions):
        values = [point[column] for point in points]
        mean = sum(values) / n
        variance = sum((value - mean) ** 2 for value in values) / n
        std_dev = math.sqrt(variance)
        if std_dev > 0.0:
            for point in points:
                point[column] = (point[column] - mean) / std_dev
        else:
            for point in points:
                point[column] = 0.0

    # k-means requires at least one distinct point per cluster.  Normally this
    # is exactly 3, but small or highly duplicated inputs are handled
    # gracefully by using the number of available distinct points.
    distinct_count = len({tuple(point) for point in points})
    k = min(3, n, distinct_count)
    if k <= 1:
        return [0] * n

    starts: List[List[List[float]]] = [
        _farthest_first_initialization(points, k)
    ]
    # Deterministic multi-start k-means++ improves robustness against local
    # minima while keeping results reproducible.
    for seed in range(12):
        starts.append(
            _kmeans_plus_plus_initialization(
                points, k, random.Random(seed), first_fixed=(seed % 2 == 0)
            )
        )

    best_labels: List[int] | None = None
    best_inertia = math.inf
    for initial_centers in starts:
        if len(initial_centers) < k:
            continue
        labels, inertia = _run_lloyd(points, initial_centers)
        if inertia < best_inertia - 1e-12:
            best_inertia = inertia
            best_labels = labels

    if best_labels is None:  # pragma: no cover - defensive
        best_labels = [0] * n

    return _canonicalize(best_labels)

