def normalize_csv_column(csv_text, column):
    """Return z-scores for a numeric CSV column using the sample std. dev."""
    if csv_text is None:
        raise ValueError("csv_text must not be None")

    # Remove a UTF-8 BOM if the text was decoded from a BOM-prefixed file.
    if isinstance(csv_text, str) and csv_text.startswith("\ufeff"):
        csv_text = csv_text[1:]

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text must contain a header row") from None

    try:
        column_index = header.index(column)
    except ValueError:
        raise KeyError(f"column {column!r} not found in CSV header") from None

    values = []
    for line_number, row in enumerate(reader, start=2):
        if not row:
            continue
        if column_index >= len(row):
            raise ValueError(
                f"row {line_number} does not contain column {column!r}"
            )
        try:
            values.append(float(row[column_index]))
        except ValueError:
            raise ValueError(
                f"non-numeric value {row[column_index]!r} in column "
                f"{column!r} on row {line_number}"
            ) from None

    count = len(values)
    if count == 0:
        return []
    if count == 1:
        raise ValueError("sample standard deviation requires at least two values")

    mean = sum(values) / count
    variance = sum((value - mean) ** 2 for value in values) / (count - 1)
    std_dev = math.sqrt(variance)

    if std_dev == 0:
        raise ValueError("sample standard deviation is zero")

    return [(value - mean) / std_dev for value in values]

