def _percentile(sorted_values, p):
    """Return the linearly interpolated p-th percentile of sorted values."""
    position = (len(sorted_values) - 1) * p
    lower = int(position)
    upper = min(lower + 1, len(sorted_values) - 1)
    fraction = position - lower
    return float(
        sorted_values[lower]
        + (sorted_values[upper] - sorted_values[lower]) * fraction
    )


def fruit_sales_box_stats(records):
    """Return (min, Q1, median, Q3, max) sales statistics per fruit."""
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = {}
    for fruit, _day, sales in records:
        sales_by_fruit.setdefault(fruit, []).append(sales)

    stats = {}
    for fruit, values in sales_by_fruit.items():
        values.sort()
        stats[fruit] = (
            float(values[0]),
            _percentile(values, 0.25),
            _percentile(values, 0.5),
            _percentile(values, 0.75),
            float(values[-1]),
        )
    return stats

