def column_summary_stats(table, mapping, features):
    """Return summary statistics for selected columns after value mapping.

    The mean, median, and variance are computed after replacing each value
    that appears in ``mapping``.  Variance is the population variance.  When
    multiple values share the highest frequency, the smallest such value is
    reported as the mode.
    """
    result = {}

    for feature in features:
        if feature not in table:
            raise ValueError(f"Feature {feature!r} is not in the table")

        # Replace values first; statistics are computed on the new values.
        values = [mapping.get(value, value) for value in table[feature]]
        if not values:
            raise ValueError(f"Cannot compute statistics for empty feature {feature!r}")

        count = len(values)
        mean = sum(values) / count

        ordered = sorted(values)
        middle = count // 2
        if count % 2:
            median = float(ordered[middle])
        else:
            median = (ordered[middle - 1] + ordered[middle]) / 2.0

        frequencies = {}
        for value in values:
            frequencies[value] = frequencies.get(value, 0) + 1
        highest_frequency = max(frequencies.values())
        mode = min(
            value
            for value, frequency in frequencies.items()
            if frequency == highest_frequency
        )

        variance = sum((value - mean) ** 2 for value in values) / count

        result[feature] = {
            "mean": mean,
            "median": median,
            "mode": mode,
            "variance": variance,
        }

    return result

