                self.seen_table = True
                self.in_table = True
                self.table_depth = 1
            elif self.in_table:
                self.table_depth += 1
            return

        if not self.in_table:
            return

        if tag == "tr":
            # Ignore a nested row while a cell is being collected.
            if self.current_cell is None and self.current_row is None:
                self.current_row = []
            return

