            # Ignore nested cells; only a cell's own text belongs to it.
            if self.current_cell is None:
                self.current_cell = tag
                self.current_cell_tag = tag
                self.cell_parts = []
            return

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        tag = tag.lower()

        if tag == "table":
            if self.in_table:
                self.table_depth -= 1
                if self.table_depth <= 0:
                    self.in_table = False
            return

        if not self.in_table:
            return

        if tag in ("th", "td"):
            if self.current_cell is not None:
                text = "".join(self.cell_parts).strip()
                if tag == "th":
                    self.headers.append(text)
                elif tag == "td" and self.current_row is not None:
                    self.current_row.append(text)
                self.current_cell = None
                self.current_cell_tag = None
                self.cell_parts = []
            return

        if tag == "tr":
            if self.current_cell is None and self.current_row is not None:
                if self.current_row:
                    self.rows.append(self.current_row)
                self.current_row = None

    def handle_data(self, data):
        if self.in_table and self.current_cell is not None:
            self.cell_parts.append(data)


