"""Column-wise min-max scaling for a table represented as a list of rows."""


def min_max_scale_columns(rows):
    """Return a copy of *rows* with each column min-max scaled to [0, 1].

    Each column is scaled independently. If a column is constant, its range
    is zero, so every value in that column is returned as 0.0.
    """
    if not rows:
        return []

    num_columns = len(rows[0])
    mins = [min(row[column] for row in rows) for column in range(num_columns)]
    maxs = [max(row[column] for row in rows) for column in range(num_columns)]

    return [
        [
            0.0 if maxs[column] == mins[column]
            else (row[column] - mins[column]) / (maxs[column] - mins[column])
            for column in range(num_columns)
        ]
        for row in rows
    ]

