def chi_square_independence(xs, ys):
    """Return the Pearson chi-square statistic and degrees of freedom.

    ``xs`` and ``ys`` contain aligned category labels.  The test is the
    Pearson chi-square test of independence without a continuity correction.
    """
    if len(xs) == 0 or len(ys) == 0:
        raise ValueError("input lists must not be empty")
    if len(xs) != len(ys):
        raise ValueError("input lists must have the same length")

    # Preserve first-seen order for deterministic floating-point summation.
    x_categories = list(dict.fromkeys(xs))
    y_categories = list(dict.fromkeys(ys))

    if len(x_categories) < 2 or len(y_categories) < 2:
        raise ValueError("each variable must have at least two distinct categories")

    x_index = {category: i for i, category in enumerate(x_categories)}
    y_index = {category: i for i, category in enumerate(y_categories)}

    observed = [[0] * len(y_categories) for _ in x_categories]
    for x, y in zip(xs, ys):
        observed[x_index[x]][y_index[y]] += 1

    n = len(xs)
    row_totals = [sum(row) for row in observed]
    col_totals = [
        sum(observed[i][j] for i in range(len(x_categories)))
        for j in range(len(y_categories))
    ]

    statistic = 0.0
    for i, row_total in enumerate(row_totals):
        for j, col_total in enumerate(col_totals):
            expected = row_total * col_total / n
            difference = observed[i][j] - expected
            statistic += difference * difference / expected

