import csv
import io


def grouped_column_means(csv_text, group_col, value_col):
    """Return the mean of ``value_col`` for each group in ``group_col``.

    The input is CSV text with a header row.  Blank value cells are ignored.
    A non-numeric, non-blank value causes a ``ValueError`` to be raised.
    Groups that contain only blank values are omitted because their mean is
    undefined.
    """
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")

    # A UTF-8 BOM may appear at the start of the text and would otherwise
    # become part of the first header name.
    if csv_text.startswith("\ufeff"):
        csv_text = csv_text[1:]

    reader = csv.DictReader(io.StringIO(csv_text, newline=""))

    if reader.fieldnames is None:
        raise ValueError("CSV text must contain a header row")

    missing = [name for name in (group_col, value_col) if name not in reader.fieldnames]
    if missing:
        raise ValueError("Missing column(s): " + ", ".join(missing))

    totals = {}
    counts = {}

    for row in reader:
        raw_value = row.get(value_col)
        if raw_value is None or raw_value.strip() == "":
            continue

        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            raise ValueError(
                "Non-numeric value in column {!r}: {!r}".format(value_col, raw_value)
            ) from None

        group = row.get(group_col)
        if group is None:
            group = ""
        else:
            group = str(group)

        totals[group] = totals.get(group, 0.0) + value
        counts[group] = counts.get(group, 0) + 1

    return {group: totals[group] / counts[group] for group in totals}

