"""Utilities for sorting CSV data."""

import csv
import io


def _parse_number(value):
    """Return an int/float if *value* represents a number, else None."""
    if not isinstance(value, str) or value.strip() == "":
        return None

    try:
        return int(value)
    except ValueError:
        pass

    try:
        return float(value)
    except ValueError:
        return None


def sort_csv_rows(csv_text, sort_by_column):
    """Sort the data rows of a CSV document by a named column.

    The first row of ``csv_text`` is treated as the header.  Values in a
    column are converted to numbers (ints when possible, otherwise floats)
    only when every value in that column is numeric.  All other columns keep
    string values.

    Args:
        csv_text: The complete text of a CSV file, including its header.
        sort_by_column: The header name of the column to sort by.

    Returns:
        A list of dictionaries, one per data row, in ascending order by the
        requested column.

    Raises:
        ValueError: If ``sort_by_column`` is not present in the header.
    """
    if not isinstance(csv_text, str):
        raise TypeError("csv_text must be a string")

    reader = csv.reader(io.StringIO(csv_text, newline=""))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {sort_by_column!r} not found in CSV header")

    # Handle a UTF-8 BOM that may accompany text read without utf-8-sig.
    if header:
        header[0] = header[0].lstrip("\ufeff")

    if sort_by_column not in header:
        raise ValueError(f"Column {sort_by_column!r} not found in CSV header")

    # Ignore completely blank records, but retain records consisting of empty
    # fields (for example, a single empty value in a one-column CSV).
    data_rows = [row for row in reader if row]

    # Normalize row lengths to the header length so every column has a value.
    normalized_rows = []
    for row in data_rows:
        if len(row) < len(header):
            row = row + [""] * (len(header) - len(row))
        elif len(row) > len(header):
            row = row[: len(header)]
        normalized_rows.append(row)

    # Determine each column's type from all of its values.  An empty data set
    # has no values to convert, and a non-numeric value makes the entire
    # column string-valued.
    column_is_numeric = []
    for column_index in range(len(header)):
        values = [row[column_index] for row in normalized_rows]
        column_is_numeric.append(
            bool(values) and all(_parse_number(value) is not None for value in values)
        )

    typed_rows = []
    for row in normalized_rows:
        typed_row = {}
        for column_index, column_name in enumerate(header):
            value = row[column_index]
            if column_is_numeric[column_index]:
                value = _parse_number(value)
            typed_row[column_name] = value
        typed_rows.append(typed_row)

    sort_index = header.index(sort_by_column)
    typed_rows.sort(key=lambda row: row[header[sort_index]])
    return typed_rows

