"""Utilities for reading 8-bit grayscale PGM images."""

_WHITESPACE = b" \t\r\n\v\f"
_DIGITS = b"0123456789"


def _is_whitespace(byte):
    return byte in _WHITESPACE


class _PGMReader:
    """A small parser for the textual part of a PGM header."""

    def __init__(self, data):
        self.data = data
        self.pos = 0
        self.length = len(data)

    def skip_space_and_comments(self):
        """Skip PGM whitespace and comments.

        A comment starts with ``#`` and extends to the next CR or LF (or
        the end of the input).
        """
        data = self.data
        while self.pos < self.length:
            byte = data[self.pos]
            if _is_whitespace(byte):
                self.pos += 1
            elif byte == ord("#"):
                self.pos += 1
                while self.pos < self.length and data[self.pos] not in (10, 13):
                    self.pos += 1
            else:
                break

    def read_uint(self):
        """Read an unsigned decimal integer and leave the delimiter in place."""
        data = self.data
        start = self.pos
        if start >= self.length or data[start] not in _DIGITS:
            raise ValueError("expected an unsigned decimal integer")

        self.pos += 1
        while self.pos < self.length and data[self.pos] in _DIGITS:
            self.pos += 1

        # A number must end at whitespace, a comment, or EOF.
        if (
            self.pos < self.length
            and not _is_whitespace(data[self.pos])
            and data[self.pos] != ord("#")
        ):
            raise ValueError("invalid character after integer")

        try:
            return int(data[start:self.pos])
        except ValueError:
            # In particular, Python may reject extremely long decimal
            # strings; such a header is not a usable PGM image anyway.
            raise ValueError("invalid integer") from None


def grayscale_histogram(data):
    """Return the histogram of an 8-bit grayscale P2 or P5 PGM image.

    ``data`` must be the raw bytes of the image.  The result is a dictionary
    whose keys are the pixel values that occur in the image and whose values
    are the corresponding pixel counts.  Invalid input raises ``ValueError``.
    """
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise ValueError("data must be bytes-like")

    try:
        data = bytes(data)
    except (TypeError, ValueError):
        raise ValueError("data must be bytes-like") from None

    reader = _PGMReader(data)

    # The magic number must be the very first thing in the file.
    if reader.length < 2:
        raise ValueError("missing PGM magic number")
    magic = data[:2]
    if magic not in (b"P2", b"P5"):
        raise ValueError("not a P2 or P5 PGM image")
    reader.pos = 2

    # The magic number is a token and therefore needs a delimiter.  A
    # comment may serve as that delimiter.
    if (
        reader.pos < reader.length
        and not _is_whitespace(data[reader.pos])
        and data[reader.pos] != ord("#")
    ):
        raise ValueError("invalid character after PGM magic number")

    reader.skip_space_and_comments()
    width = reader.read_uint()
    reader.skip_space_and_comments()
    height = reader.read_uint()
    reader.skip_space_and_comments()
    maxval = reader.read_uint()

    if width <= 0 or height <= 0:
        raise ValueError("image dimensions must be positive")
    if maxval <= 0 or maxval > 255:
        raise ValueError("maxval must be between 1 and 255 for an 8-bit image")

    pixel_count = width * height
    histogram = {}

    if magic == b"P2":
        # ASCII raster.  There is no need to retain the individual samples.
        seen = 0
        while True:
            reader.skip_space_and_comments()
            if reader.pos >= reader.length:
                break
            value = reader.read_uint()
            if value > maxval:
                raise ValueError("pixel value exceeds maxval")
            seen += 1
            if seen > pixel_count:
                raise ValueError("too many pixel values")
            histogram[value] = histogram.get(value, 0) + 1

        if seen != pixel_count:
            raise ValueError("wrong number of pixel values")
        return histogram

    # Binary raster.  The maxval is followed by exactly one whitespace
    # character which separates the header from the raster.  A CRLF line
    # ending is treated as a single separator for compatibility with text
    # files created on Windows.
    if reader.pos >= reader.length or not _is_whitespace(data[reader.pos]):
        raise ValueError("missing whitespace after maxval")

    # Normally the separator is one byte.  Also consider CRLF as a single
    # line ending, but prefer the one-byte interpretation when only it gives
    # the correct raster size.  This matters when the first raster byte is
    # itself a newline and the separator is a carriage return.
    candidate_starts = [reader.pos + 1]
    if (
        data[reader.pos] == 13
        and reader.pos + 1 < reader.length
        and data[reader.pos + 1] == 10
    ):
        candidate_starts.append(reader.pos + 2)

    raster_start = None
    for start in candidate_starts:
        if reader.length - start == pixel_count:
            raster_start = start
            break
    if raster_start is None:
        raise ValueError("wrong number of bytes in binary raster")

    for value in data[raster_start:]:
        if value > maxval:
            raise ValueError("pixel value exceeds maxval")
        histogram[value] = histogram.get(value, 0) + 1

    return histogram

