"""Classical moving-average seasonal decomposition."""

import operator


def classical_seasonal_decomposition(values, period, model='additive'):
    """Decompose an evenly spaced series into trend, seasonal and residual parts.

    Parameters
    ----------
    values : sequence of numbers
        The observed series.
    period : int
        Number of observations in one seasonal cycle.
    model : {'additive', 'multiplicative'}
        Whether the components combine by addition or multiplication.

    Returns
    -------
    dict
        A dictionary with ``trend``, ``seasonal`` and ``resid`` lists, each
        the same length as ``values``.  Entries whose centred moving average
        is undefined are represented by ``None``.
    """
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    if isinstance(period, bool):
        raise ValueError("period must be a positive integer")
    try:
        period = operator.index(period)
    except TypeError:
        raise ValueError("period must be a positive integer") from None
    if period <= 0:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    # Centred moving average.  For an even period, a symmetric weighted
    # average is needed to keep the filter centred on an observation.
    if period % 2 == 0:
        weights = [0.5] + [1.0] * (period - 1) + [0.5]
    else:
        weights = [1.0] * period
    weights = [w / period for w in weights]

    half = len(weights) // 2
    trend = [None] * n
    for i in range(half, n - half):
        trend[i] = sum(weights[j] * values[i - half + j]
                       for j in range(len(weights)))

    # Detrended observations, only where the trend exists.
    if model == 'additive':
        detrended = {i: values[i] - trend[i]
                     for i in range(n) if trend[i] is not None}
    else:
        detrended = {i: values[i] / trend[i]
                     for i in range(n) if trend[i] is not None}

    # Average the detrended values for each phase of the seasonal cycle.
    phase_sums = [0.0] * period
    phase_counts = [0] * period
    for i, value in detrended.items():
        phase = i % period
        phase_sums[phase] += value
        phase_counts[phase] += 1

    phase_means = [phase_sums[i] / phase_counts[i] for i in range(period)]

    if model == 'additive':
        adjustment = sum(phase_means) / period
        seasonal_values = [value - adjustment for value in phase_means]
    else:
        adjustment = sum(phase_means) / period
        seasonal_values = [value / adjustment for value in phase_means]

    seasonal = [seasonal_values[i % period] for i in range(n)]

    resid = [None] * n
    for i in range(n):
        if trend[i] is None:
            continue
        if model == 'additive':
            resid[i] = detrended[i] - seasonal[i]
        else:
            resid[i] = detrended[i] / seasonal[i]

    return {
        'trend': trend,
        'seasonal': seasonal,
        'resid': resid,
    }

