import csv
import io
import math
import re
import statistics


def _as_number(value):
    """Return *value* as a finite float, or None if it is not numeric."""
    if value is None:
        return None

    text = value.strip()
    if not text:
        return None

    # Allow ordinary decimal/scientific notation and correctly grouped
    # thousands separators.  A quoted CSV field such as "1,000" arrives
    # here as the single string "1,000".
    number_pattern = (
        r"[+-]?(?:(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d*)?|\.\d+)"
        r"(?:[eE][+-]?\d+)?"
    )
    if re.fullmatch(number_pattern, text) is None:
        return None

    try:
        number = float(text.replace(",", ""))
    except ValueError:
        return None

    if not math.isfinite(number):
        return None
    return number


def summarize_numeric_csv(csv_text):
    """Summarize the numeric columns of a CSV document.

    A column is numeric only when every non-blank data row contains a
    parseable number in that column.  Means and sample standard deviations
    are reported for those columns.  If at least two numeric columns exist,
    ``f_value`` is the F statistic for a one-way ANOVA treating each column
    as a group; otherwise it is None.
    """
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        return {"means": {}, "std_devs": {}, "f_value": None}

    if header:
        # Be tolerant of a UTF-8 byte-order mark at the start of the file.
        header[0] = header[0].lstrip("\ufeff")

    column_count = len(header)
    values_by_column = [[] for _ in range(column_count)]
    numeric = [True] * column_count

    for row in reader:
        # Ignore completely blank physical lines.
        if not row or all(cell.strip() == "" for cell in row):
            continue

        for index in range(column_count):
            if not numeric[index]:
                continue

            cell = row[index] if index < len(row) else ""
            number = _as_number(cell)
            if number is None:
                numeric[index] = False
            else:
                values_by_column[index].append(number)

    means = {}
    std_devs = {}
    numeric_groups = []

    for index, is_numeric in enumerate(numeric):
        if not is_numeric:
            continue

        values = values_by_column[index]
        if not values:
            # With no data rows there is no numeric data to summarize.
            continue

        name = header[index]
        means[name] = statistics.fmean(values)
        # The sample standard deviation is undefined for a single value.
        std_devs[name] = statistics.stdev(values) if len(values) >= 2 else 0.0
        numeric_groups.append(values)

    if len(numeric_groups) < 2:
        f_value = None
    else:
        total_count = sum(len(group) for group in numeric_groups)
        group_count = len(numeric_groups)
        degrees_between = group_count - 1
        degrees_within = total_count - group_count

        grand_mean = statistics.fmean(
            value for group in numeric_groups for value in group
        )
        ss_between = sum(
            len(group) * (statistics.fmean(group) - grand_mean) ** 2
            for group in numeric_groups
        )
        ss_within = sum(
            sum((value - statistics.fmean(group)) ** 2 for value in group)
            for group in numeric_groups
        )

        if degrees_within <= 0:
            # With no within-group degrees of freedom, the ANOVA F statistic
            # is undefined.
            f_value = None
        elif ss_within == 0.0:
            f_value = float("inf") if ss_between > 0.0 else float("nan")
        else:
            f_value = (ss_between / degrees_between) / (
                ss_within / degrees_within
            )

    return {"means": means, "std_devs": std_devs, "f_value": f_value}

