import math


def max_pairwise_distance(xs, ys):
    """Return the largest Euclidean distance between two distinct points.

    Point i is (xs[i], ys[i]).  A ValueError is raised when the coordinate
    lists have different lengths.  With fewer than two points, the result is
    0.
    """
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n < 2:
        return 0

    max_squared = 0.0
    for i in range(n):
        xi = xs[i]
        yi = ys[i]
        for j in range(i + 1, n):
            dx = xi - xs[j]
            dy = yi - ys[j]
            squared = dx * dx + dy * dy
            if squared > max_squared:
                max_squared = squared

    return math.sqrt(max_squared)

