"""Utilities for standardizing numeric table columns and computing correlations."""

import math
import numbers


def _is_numeric(value):
    """Return True for real numbers, excluding booleans."""
    return isinstance(value, numbers.Real) and not isinstance(value, bool)


def standardize_and_correlate(table):
    """Standardize numeric columns and return their Pearson correlations.

    Numeric columns are standardized using their population standard
    deviation.  Non-numeric columns are copied unchanged.  The correlation
    matrix follows the insertion order of the numeric columns in ``table``.
    """
    if not table:
        raise ValueError("table must not be empty")

    numeric_columns = [
        name
        for name, values in table.items()
        if values and all(_is_numeric(value) for value in values)
    ]
    if not numeric_columns:
        raise ValueError("table must contain at least one numeric column")

    row_count = len(next(iter(table.values())))
    numeric_set = set(numeric_columns)
    standardized = {}
    moments = {}

    for name, values in table.items():
        if name not in numeric_set:
            standardized[name] = list(values)
            continue

        mean = math.fsum(values) / row_count
        deviations = [float(value) - mean for value in values]
        variance = math.fsum(d * d for d in deviations) / row_count
        std_dev = math.sqrt(variance)

        if std_dev == 0.0:
            standardized[name] = [0.0] * row_count
        else:
            standardized[name] = [d / std_dev for d in deviations]

        moments[name] = (std_dev, deviations)

    corr = []
    for i, name_i in enumerate(numeric_columns):
        std_i, deviations_i = moments[name_i]
        row = []
        for j, name_j in enumerate(numeric_columns):
            if i == j:
                row.append(1.0)
                continue

            std_j, deviations_j = moments[name_j]
            if std_i == 0.0 or std_j == 0.0:
                row.append(0.0)
                continue

            covariance = math.fsum(
                a * b for a, b in zip(deviations_i, deviations_j)
            ) / row_count
            correlation = covariance / (std_i * std_j)
            # Protect against tiny floating-point excursions outside [-1, 1].
            row.append(max(-1.0, min(1.0, correlation)))
        corr.append(row)

    return standardized, corr

