"""Utilities for summarizing numeric values grouped by JSON object keys."""

import json
import math


def _linear_percentile(sorted_values, probability):
    """Return a percentile using linear interpolation between closest ranks."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])

    position = (n - 1) * probability
    lower_index = math.floor(position)
    upper_index = math.ceil(position)

    if lower_index == upper_index:
        return float(sorted_values[lower_index])

    lower_value = sorted_values[lower_index]
    upper_value = sorted_values[upper_index]
    fraction = position - lower_index
    return float(lower_value + (upper_value - lower_value) * fraction)


def _reject_nonstandard_constant(value):
    raise ValueError(f"Invalid JSON numeric constant: {value}")


def summarize_values_by_key(json_text):
    """Summarize numeric values in a JSON list of objects, grouped by key.

    Each result key maps to a dictionary containing the mean, median, first
    quartile (q1), and third quartile (q3) of all values recorded for that key.
    Quartiles use linear interpolation between the two closest sorted values.
    """
    if not isinstance(json_text, str):
        raise ValueError("json_text must be a JSON string")

    try:
        records = json.loads(
            json_text, parse_constant=_reject_nonstandard_constant
        )
    except (json.JSONDecodeError, TypeError, ValueError) as exc:
        if isinstance(exc, ValueError) and not isinstance(exc, json.JSONDecodeError):
            # Preserve our explicit ValueError and reject non-standard constants.
            raise
        raise ValueError("Invalid JSON") from exc

    if not isinstance(records, list):
        raise ValueError("JSON must encode a list of objects")

    values_by_key = {}
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError(f"Item at index {index} is not an object")

        for key, value in record.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    f"Value for key {key!r} at index {index} is not a number"
                )
            if not math.isfinite(value):
                raise ValueError(
                    f"Value for key {key!r} at index {index} is not finite"
                )
            values_by_key.setdefault(key, []).append(value)

    result = {}
    for key, values in values_by_key.items():
        values.sort()
        count = len(values)
        result[key] = {
            "mean": float(math.fsum(values) / count),
            "median": _linear_percentile(values, 0.5),
            "q1": _linear_percentile(values, 0.25),
            "q3": _linear_percentile(values, 0.75),
        }

    return result

